# files created from the Docker/root process on the bind-mounted project
# must remain owned by the host project user (normally deca), not root.  Resolve the
# desired numeric uid/gid from explicit env overrides first, then from the bind mount.
def _vla_resolve_output_owner() -> Optional[Tuple[int, int]]:
    try:
        env_uid = os.environ.get("VLA_OUTPUT_UID")
        env_gid = os.environ.get("VLA_OUTPUT_GID")
        if env_uid is not None and env_gid is not None:
            return int(env_uid), int(env_gid)
    except Exception:
        pass
    try:
        sudo_uid = os.environ.get("SUDO_UID")
        sudo_gid = os.environ.get("SUDO_GID")
        if sudo_uid is not None and sudo_gid is not None:
            uid, gid = int(sudo_uid), int(sudo_gid)
            if uid > 0:
                return uid, gid
    except Exception:
        pass
    for ref in (SHARED_CALIB_ROOT, "/workspace/project_train", os.path.dirname(SHARED_CALIB_ROOT)):
        try:
            st = os.stat(ref)
            if int(st.st_uid) > 0:
                return int(st.st_uid), int(st.st_gid)
        except Exception:
            continue
    try:
        if os.geteuid() != 0:
            return int(os.getuid()), int(os.getgid())
    except Exception:
        pass
    return None


def _vla_fix_created_owner(path: Any, recursive: bool = False) -> None:
    """Best-effort host ownership repair for newly created VLA/log outputs."""
    target = _vla_resolve_output_owner()
    if target is None or not path:
        return
    uid, gid = target
    try:
        p = os.path.abspath(os.path.expanduser(str(path)))
        if recursive and os.path.isdir(p):
            for root, dirs, files in os.walk(p):
                for name in dirs:
                    try:
                        os.chown(os.path.join(root, name), uid, gid)
                    except Exception:
                        pass
                for name in files:
                    try:
                        os.chown(os.path.join(root, name), uid, gid)
                    except Exception:
                        pass
            os.chown(p, uid, gid)
        elif os.path.lexists(p):
            os.chown(p, uid, gid)
    except Exception:
        # Ownership repair must never abort robot/VLA execution.
        pass


def _vla_make_output_dir(path: Any) -> str:
    p = os.path.abspath(os.path.expanduser(str(path)))
    os.makedirs(p, exist_ok=True)
    _vla_fix_created_owner(p)
    return p

