    parser.add_argument("--no-vla-shadow-test-enable", dest="vla_shadow_test_enable", action="store_false")
    parser.add_argument("--vla-shadow-engine",
                        default=USER_SETTINGS.get("vla_shadow_engine", SHARED_VLA_SHADOW_ENGINE))
    parser.add_argument("--vla-shadow-state-norm",
                        default=USER_SETTINGS.get("vla_shadow_state_norm", SHARED_VLA_SHADOW_STATE_NORM))
    parser.add_argument("--vla-shadow-center-threshold", type=float,
                        default=USER_SETTINGS.get("vla_shadow_center_threshold", 0.983))
    parser.add_argument("--vla-shadow-spread-threshold", type=float,
                        default=USER_SETTINGS.get("vla_shadow_spread_threshold", 0.752))
    parser.add_argument("--vla-shadow-finish-threshold", type=float,
                        default=USER_SETTINGS.get("vla_shadow_finish_threshold", 0.985))
    parser.add_argument("--vla-model-decision", dest="vla_model_decision_enable", action="store_true",
                        default=USER_SETTINGS.get("vla_model_decision_enable", True),
                        help="Enable Board+State-v2 model-first macro decision with Stage3 AUTO-X fallback.")
    parser.add_argument("--no-vla-model-decision", dest="vla_model_decision_enable", action="store_false",
                        help="Disable hybrid decision and restore pure Stage3 AUTO-X selection.")
    parser.add_argument("--vla-model-center-threshold", type=float,
                        default=USER_SETTINGS.get("vla_model_center_threshold", 0.70))
    parser.add_argument("--vla-model-spread-threshold", type=float,
                        default=USER_SETTINGS.get("vla_model_spread_threshold", 0.60))
    parser.add_argument("--vla-model-rotate-threshold", type=float,
                        default=USER_SETTINGS.get("vla_model_rotate_threshold", 0.60))
    parser.add_argument("--vla-model-finish-threshold", type=float,
                        default=USER_SETTINGS.get("vla_model_finish_threshold", 0.80))
    parser.add_argument("--vla-model-min-margin", type=float,
                        default=USER_SETTINGS.get("vla_model_min_margin", 0.15))
    parser.add_argument("--motion-policy-version",
                        default=USER_SETTINGS.get("motion_policy_version", "top_vla_motion_v47_center_longpull_compete"),
                        help="Semantic motion-policy ID stored with VLA records so data from compatible/revised policies can coexist.")
    parser.add_argument("--vla-exclude-experimental-rotate-training",
                        dest="vla_experimental_rotate_training_exclude", action="store_true",
                        default=USER_SETTINGS.get("vla_experimental_rotate_training_exclude", False),
                        help="Force every ROTATE macro transition training_eligible=False while ROTATE is experimental; preserve GOOD/BAD/SKIP labels and records.")
    parser.add_argument("--vla-allow-experimental-rotate-training",
                        dest="vla_experimental_rotate_training_exclude", action="store_false",
                        help="Allow ROTATE GOOD transitions into normal training (use only after ROTATE is stabilized).")

    parser.add_argument("--send", action="store_true", default=USER_SETTINGS["send"])
    parser.add_argument("--no-send", dest="send", action="store_false", help="Do not send commands to RoArm.")
    parser.add_argument("--dry-run", action="store_true", default=USER_SETTINGS["dry_run"])
    parser.add_argument("--arm1-port", default=USER_SETTINGS["arm1_port"], help="ARM1, ID2/ID3 side. Default: /dev/roarm_1")
    parser.add_argument("--arm2-port", default=USER_SETTINGS["arm2_port"], help="ARM2, ID0/ID1 side. Default: /dev/roarm_2")
    parser.add_argument("--workspace-step1", dest="workspace_step1", action="store_true", default=USER_SETTINGS["workspace_step1"],
                        help="Enable step1 split: ARM2 left, ARM1 right, center dead-zone blocked.")
    parser.add_argument("--no-workspace-step1", dest="workspace_step1", action="store_false")
    parser.add_argument("--workspace-dead-half-width", type=float, default=USER_SETTINGS["workspace_dead_half_width"],
                        help="Half width of center dead-zone around split_x in board mm.")
    parser.add_argument("--deep-internal-pick-workspace-margin-mm", type=float,
                        default=USER_SETTINGS.get("deep_internal_pick_workspace_margin_mm", 12.0),
                        help="Extra mm that key 4 smart-reposition deep-internal pick points must stay inside the selected arm workspace to avoid center BLOCKED.")
    parser.add_argument("--smart-reposition-side-bias-threshold-mm", type=float,
                        default=USER_SETTINGS.get("smart_reposition_side_bias_threshold_mm", 35.0),
                        help="Key 4 smart reposition: if cloth median-x differs from board center by this many mm, run side-bias recovery first.")
    parser.add_argument("--smart-reposition-marker-empty-threshold-mm", type=float,
                        default=USER_SETTINGS.get("smart_reposition_marker_empty_threshold_mm", 65.0),
                        help="Key 4 smart reposition: only run marker-fill mode if the farthest marker is at least this far from cloth.")
    parser.add_argument("--smart-reposition-side-pull-distance", type=float,
                        default=USER_SETTINGS.get("smart_reposition_side_pull_distance", None),
                        help="Key 4 side-bias mode pull distance. None/default uses --boundary-recovery-pull-distance.")
    parser.add_argument("--auto-center-rounds", type=int,
                        default=USER_SETTINGS.get("auto_center_rounds", 4),
                        help="Key 4 AUTO CENTER: maximum closed-loop drag cycles per key press. Set 1 for one-shot behavior.")
    parser.add_argument("--auto-center-done-error-x-mm", type=float,
                        default=USER_SETTINGS.get("auto_center_done_error_x_mm", 30.0),
                        help="Key 4 AUTO CENTER stops when abs(board_center_x - cloth_center_x) is below this mm.")
    parser.add_argument("--auto-center-done-error-y-mm", type=float,
                        default=USER_SETTINGS.get("auto_center_done_error_y_mm", 35.0),
                        help="Key 4 AUTO CENTER stops when abs(board_center_y - cloth_center_y) is below this mm.")
    parser.add_argument("--auto-center-pull-gain", type=float,
                        default=USER_SETTINGS.get("auto_center_pull_gain", 0.75),
                        help="Key 4 AUTO CENTER drag distance gain: pull_distance = gain * center_error_norm, then clamped.")
    parser.add_argument("--auto-center-pull-min-mm", type=float,
                        default=USER_SETTINGS.get("auto_center_pull_min_mm", 40.0),
                        help="Key 4 AUTO CENTER minimum drag distance when a correction is needed.")
    parser.add_argument("--auto-center-pull-max-mm", type=float,
                        default=USER_SETTINGS.get("auto_center_pull_max_mm", 95.0),
                        help="Key 4 AUTO CENTER maximum drag distance per cycle.")
    parser.add_argument("--auto-center-settle-s", type=float,
                        default=USER_SETTINGS.get("auto_center_settle_s", 0.80),
                        help="Wait time after each AUTO CENTER drag before the next fresh snapshot cycle.")
    parser.add_argument("--auto-center-min-progress-mm", type=float,
                        default=USER_SETTINGS.get("auto_center_min_progress_mm", 12.0),
                        help="Stop AUTO CENTER if consecutive cloth-center estimates move less than this amount after a drag.")
    parser.add_argument("--smart-reposition-suppress-non-smart-overlay", dest="smart_reposition_suppress_non_smart_overlay", action="store_true",
                        default=USER_SETTINGS.get("smart_reposition_suppress_non_smart_overlay", True),
                        help="While key 4 AUTO CENTER is running, hide stale SELECT/SPREAD/center/press overlays and show only the SMART REPOSITION pick/drag overlay.")
    parser.add_argument("--no-smart-reposition-suppress-non-smart-overlay", dest="smart_reposition_suppress_non_smart_overlay", action="store_false",
                        help="Do not hide non-smart overlays during key 4 AUTO CENTER.")
    parser.add_argument("--perception-roi-clip-to-aruco-board", dest="perception_roi_clip_to_aruco_board", action="store_true",
                        default=USER_SETTINGS.get("perception_roi_clip_to_aruco_board", True),
                        help="Run garment/pose perception only inside the ArUco-board rectangle so side robot arms are ignored.")
    parser.add_argument("--no-perception-roi-clip-to-aruco-board", dest="perception_roi_clip_to_aruco_board", action="store_false",
                        help="Disable strict ArUco-board ROI perception; useful only when outside-marker cloth overflow must be visible.")
    parser.add_argument("--perception-roi-board-shrink-px", type=int,
                        default=USER_SETTINGS.get("perception_roi_board_shrink_px", 0),
                        help="Shrink the perception ROI inward from the ArUco-board polygon by this many pixels. 0 means exact marker-center frame.")

    parser.add_argument("--planning-mask-clip-to-board", dest="planning_mask_clip_to_board", action="store_true",
                        default=USER_SETTINGS.get("planning_mask_clip_to_board", True),
                        help="Clip YOLO/fallback garment contours to the ArUco board before center/spread/smart-reposition planning.")
    parser.add_argument("--no-planning-mask-clip-to-board", dest="planning_mask_clip_to_board", action="store_false",
                        help="Disable board clipping for planning masks.")
    parser.add_argument("--planning-mask-board-shrink-px", type=int, default=USER_SETTINGS.get("planning_mask_board_shrink_px", 14),
                        help="Shrink the ArUco board polygon by this many pixels when clipping planning masks.")
    parser.add_argument("--planning-mask-erode-px", type=int, default=USER_SETTINGS.get("planning_mask_erode_px", 7),
                        help="Erode the clipped planning mask by this many pixels for stable interior pick sampling. 0 disables erosion.")
    parser.add_argument("--planning-mask-morph-kernel", type=int, default=USER_SETTINGS.get("planning_mask_morph_kernel", 5),
                        help="Morphology kernel for planning-mask cleanup after board clipping.")
    parser.add_argument("--planning-mask-min-area-px", type=float, default=USER_SETTINGS.get("planning_mask_min_area_px", 1200.0),
                        help="Minimum area of a clipped planning contour. Smaller masks are rejected.")
    parser.add_argument("--planning-mask-max-board-area-ratio", type=float, default=USER_SETTINGS.get("planning_mask_max_board_area_ratio", 0.88),
                        help="Reject clipped planning masks whose area exceeds this ratio of the board polygon area.")
    parser.add_argument("--planning-mask-keep-raw-if-all-filtered", action="store_true",
                        default=USER_SETTINGS.get("planning_mask_keep_raw_if_all_filtered", False),
                        help="If every candidate is rejected by board-clipped planning-mask filtering, keep raw candidates instead of returning no target.")
    parser.add_argument("--smart-reposition-snap-to-mask", dest="smart_reposition_snap_to_mask", action="store_true",
                        default=USER_SETTINGS.get("smart_reposition_snap_to_mask", True),
                        help="Force key-4 MO/SIDE-PICK to an actual sampled mask point after deep-internal calculation.")
    parser.add_argument("--no-smart-reposition-snap-to-mask", dest="smart_reposition_snap_to_mask", action="store_false",
                        help="Use the geometric deep point directly for key-4 pick display/command.")
    parser.add_argument("--smart-reposition-snap-radius-mm", type=float, default=USER_SETTINGS.get("smart_reposition_snap_radius_mm", 95.0),
                        help="Maximum search radius around the deep-internal target when snapping key-4 pick to actual mask samples.")
    parser.add_argument("--smart-reposition-min-projection-ratio", type=float, default=USER_SETTINGS.get("smart_reposition_min_projection_ratio", 0.42),
                        help="Minimum inward projection ratio from edge to center for key-4 mask-snap candidates.")
    parser.add_argument("--lab-empty-veto", dest="lab_empty_veto", action="store_true",
                        default=USER_SETTINGS.get("lab_empty_veto", True),
                        help="Use the E-key empty-board Lab baseline to reject YOLO masks caused by lighting/shadow rather than colored cloth.")
    parser.add_argument("--no-lab-empty-veto", dest="lab_empty_veto", action="store_false",
                        help="Disable Lab empty-board false-positive veto.")
    parser.add_argument("--lab-empty-veto-require-baseline", dest="lab_empty_veto_require_baseline", action="store_true",
                        default=USER_SETTINGS.get("lab_empty_veto_require_baseline", False),
                        help="When Lab veto is enabled, reject garment candidates until E-key empty baseline exists.")
    parser.add_argument("--no-lab-empty-veto-require-baseline", dest="lab_empty_veto_require_baseline", action="store_false")
    parser.add_argument("--lab-empty-veto-l-weight", type=float, default=USER_SETTINGS.get("lab_empty_veto_l_weight", 0.25),
                        help="Weight for Lab L-channel brightness difference. Keep small to suppress lighting/shadow false positives.")
    parser.add_argument("--lab-empty-veto-ab-threshold", type=float, default=USER_SETTINGS.get("lab_empty_veto_ab_threshold", 10.0),
                        help="Pixel is considered color-changed when sqrt(da^2+db^2) exceeds this value.")
    parser.add_argument("--lab-empty-veto-min-mean-ab-diff", type=float, default=USER_SETTINGS.get("lab_empty_veto_min_mean_ab_diff", 4.5),
                        help="Reject candidate if average Lab a/b chroma difference is below this and changed ratio is also low.")
    parser.add_argument("--lab-empty-veto-min-changed-ab-ratio", type=float, default=USER_SETTINGS.get("lab_empty_veto_min_changed_ab_ratio", 0.035),
                        help="Reject candidate if too few mask pixels show Lab a/b chroma change.")
    parser.add_argument("--lab-empty-veto-combined-threshold", type=float, default=USER_SETTINGS.get("lab_empty_veto_combined_threshold", 14.0),
                        help="Combined Lab-diff threshold for secondary changed-pixel check: L_weight*dL + dAB.")
    parser.add_argument("--lab-empty-veto-min-combined-ratio", type=float, default=USER_SETTINGS.get("lab_empty_veto_min_combined_ratio", 0.035),
                        help="Minimum combined-diff changed-pixel ratio for accepting a candidate.")
    parser.add_argument("--lab-empty-refine-mask", dest="lab_empty_refine_mask", action="store_true",
                        default=USER_SETTINGS.get("lab_empty_refine_mask", True),
                        help="After a candidate passes Lab veto, crop planning mask to the high color-change region when enough pixels remain.")
    parser.add_argument("--no-lab-empty-refine-mask", dest="lab_empty_refine_mask", action="store_false")
    parser.add_argument("--lab-empty-refine-min-keep-ratio", type=float, default=USER_SETTINGS.get("lab_empty_refine_min_keep_ratio", 0.18),
                        help="Use Lab-refined mask only if it keeps at least this fraction of the original planning mask area.")
    parser.add_argument("--lab-empty-refine-morph-kernel", type=int, default=USER_SETTINGS.get("lab_empty_refine_morph_kernel", 7),
                        help="Morphology kernel for Lab-refined color-change mask.")
    parser.add_argument("--mask-shape-filter-enable", dest="mask_shape_filter_enable", action="store_true",
                        default=USER_SETTINGS.get("mask_shape_filter_enable", True),
                        help="Reject sparse/noisy masks using fill-ratio checks after planning-mask cleanup.")
    parser.add_argument("--no-mask-shape-filter-enable", dest="mask_shape_filter_enable", action="store_false")
    parser.add_argument("--mask-shape-min-fill-ratio", type=float, default=USER_SETTINGS.get("mask_shape_min_fill_ratio", 0.16),
                        help="Reject masks whose area divided by bbox area is below this value.")
    parser.add_argument("--mask-shape-max-fill-ratio", type=float, default=USER_SETTINGS.get("mask_shape_max_fill_ratio", 0.94),
                        help="Reject masks whose area divided by bbox area is above this value; use high value to avoid rejecting normal garments.")
    parser.add_argument("--dual-candidate-mode", dest="dual_candidate_mode", action="store_true",
                        default=USER_SETTINGS["dual_candidate_mode"],
                        help="Build left/right dual grasp candidates from one YOLO mask. D previews, B runs sequential test.")
    parser.add_argument("--no-dual-candidate-mode", dest="dual_candidate_mode", action="store_false")
    parser.add_argument("--dual-left-key", default=USER_SETTINGS["dual_left_key"], choices=["upper_left", "upper_right", "center"],
                        help="Candidate key used for ARM2/left-side dual target.")
    parser.add_argument("--dual-right-key", default=USER_SETTINGS["dual_right_key"], choices=["upper_left", "upper_right", "center"],
                        help="Candidate key used for ARM1/right-side dual target.")
    parser.add_argument("--dual-sequential-order", default=USER_SETTINGS["dual_sequential_order"], choices=["arm2_first", "arm1_first"],
                        help="Order for B sequential dual pick-place test.")
    parser.add_argument("--auto-wait-cloth-after-no-candidates", dest="auto_wait_cloth_after_no_candidates", action="store_true",
                        default=USER_SETTINGS["auto_wait_cloth_after_no_candidates"],
                        help="If YOLO finds no candidates, wait for a visible scene change before taking the next snapshot.")
    parser.add_argument("--no-auto-wait-cloth-after-no-candidates", dest="auto_wait_cloth_after_no_candidates", action="store_false",
                        help="Keep retrying snapshots even when YOLO finds no candidates.")
    parser.add_argument("--no-candidate-change-threshold", type=float, default=USER_SETTINGS["no_candidate_change_threshold"],
                        help="Mean pixel difference threshold used to resume snapshot after no YOLO candidates.")
    parser.add_argument("--reinfer-between-dual-arms", dest="reinfer_between_dual_arms", action="store_true",
                        default=USER_SETTINGS["reinfer_between_dual_arms"],
                        help="For B sequential test, re-run YOLO after the first arm before moving the second arm.")
    parser.add_argument("--no-reinfer-between-dual-arms", dest="reinfer_between_dual_arms", action="store_false",
                        help="Use the original two targets from the first snapshot for both arms. Not recommended if the cloth moves.")
    parser.add_argument("--reinfer-between-dual-arms-timeout", type=float, default=USER_SETTINGS["reinfer_between_dual_arms_timeout"],
                        help="Seconds to wait for fresh YOLO inference between the two arms in B sequential test.")
    parser.add_argument("--dual-hover-wait", type=float, default=USER_SETTINGS["dual_hover_wait"],
                        help="Wait seconds after dual hover commands in H test.")
    parser.add_argument("--dual-min-board-x-separation", type=float, default=USER_SETTINGS["dual_min_board_x_separation"],
                        help="Minimum board-x separation between ARM2 and ARM1 dual targets in mm.")
    parser.add_argument("--dual-low-z-order", default=USER_SETTINGS["dual_low_z_order"], choices=["arm2_first", "arm1_first"],
                        help="Order for sequential low-Z descent/close in J dual grip-place test.")
    parser.add_argument("--dual-place-after-grip", dest="dual_place_after_grip", action="store_true",
                        default=USER_SETTINGS["dual_place_after_grip"],
                        help="In J test, place the cloth back at the same XY and open/retract after dual lift.")
    parser.add_argument("--no-dual-place-after-grip", dest="dual_place_after_grip", action="store_false",
                        help="In J test, lift both arms and keep holding instead of placing/opening.")
    parser.add_argument("--dual-retract-after-place", dest="dual_retract_after_place", action="store_true",
                        default=USER_SETTINGS["dual_retract_after_place"],
                        help="In J test, retract both arms to place-hover/lift z after opening.")
    parser.add_argument("--no-dual-retract-after-place", dest="dual_retract_after_place", action="store_false")
    parser.add_argument("--dual-stretch-dx", type=float, default=USER_SETTINGS["dual_stretch_dx"],
                        help="Step4 K test: outward board-x stretch distance for each arm in mm. ARM2 moves -dx, ARM1 moves +dx.")
    parser.add_argument("--dual-stretch-wait", type=float, default=USER_SETTINGS["dual_stretch_wait"],
                        help="Wait seconds after both arms reach the stretched lift pose.")
    parser.add_argument("--dual-stretch-place-after", dest="dual_stretch_place_after", action="store_true",
                        default=USER_SETTINGS["dual_stretch_place_after"],
                        help="In K test, place/open at the stretched XY after the stretch motion.")
    parser.add_argument("--no-dual-stretch-place-after", dest="dual_stretch_place_after", action="store_false",
                        help="In K test, stop after the stretch pose and keep both arms holding.")
