    def _set_ready_status_panel_data(data: Optional[Dict[str, Any]]) -> None:
        nonlocal latest_ready_status_panel_data
        with ready_status_panel_lock:
            latest_ready_status_panel_data = dict(data or {})

    def _get_ready_status_panel_data() -> Dict[str, Any]:
        with ready_status_panel_lock:
            return dict(latest_ready_status_panel_data)

    latest_cca_sample_snapshot: Dict[str, Any] = {}
    latest_cca_sample_image: Optional[np.ndarray] = None
    latest_cca_sample_lock = threading.RLock()
    cca_recorded_observations: Dict[str, str] = {}

    def _set_latest_cca_sample_snapshot(data: Optional[Dict[str, Any]]) -> None:
        nonlocal latest_cca_sample_snapshot, latest_cca_sample_image
        with latest_cca_sample_lock:
            latest_cca_sample_snapshot = copy.deepcopy(dict(data or {}))
            if latest_cca_sample_snapshot:
                # Freeze the exact completed-X visual at publication time.  Label
                # keys must never silently save a newer live camera frame.
                if isinstance(snapshot_canvas, np.ndarray) and snapshot_canvas.size > 0:
                    latest_cca_sample_image = snapshot_canvas.copy()
                elif isinstance(snapshot_frame, np.ndarray) and snapshot_frame.size > 0:
                    latest_cca_sample_image = snapshot_frame.copy()
                else:
                    latest_cca_sample_image = None
            else:
                latest_cca_sample_image = None

    def _get_latest_cca_sample_snapshot() -> Dict[str, Any]:
        with latest_cca_sample_lock:
            return copy.deepcopy(latest_cca_sample_snapshot)

