    def _vla_macro_action(action: Any) -> str:
        a = str(action or "").upper()
        if a in {"HUMAN_FINISH", "FINISH", "FINISH_READY_FOR_ROTATION", "READY_TO_ROTATE"} or "READY_FOR_ROTATION" in a:
            return "FINISH"
        if a in {"ROTATE", "ROTATE_MID", "ROTATE_FINAL"} or a.startswith("ROTATE_"):
            return "ROTATE"
        if "CENTER" in a or "CIRCUMCENTER" in a or "NUDGE" in a:
            return "CENTER"
        # Stage1 fail-closed compatibility guard: a stale legacy ACTION4/PRESS name
        # is never exposed as an executable macro in this runtime.
        if "ACTION4" in a or "SMOOTH" in a or "PRESS" in a or "CLEANUP" in a:
            return "REJUDGE"
        if "ACTION3" in a or "LONG_WRINKLE" in a or "STRUCTURAL_STATIC_PROBE" in a:
            return "LONG_PULL"
        if "ORTHOGONAL_SPREAD" in a or "ORTHO_SPREAD" in a:
            return "ORTHO_SPREAD"
        if "ACTION2" in a or "SEGMENTATION_SPREAD" in a or "LOCAL_SPREAD" in a:
            return "SPREAD"
        if "REJUDGE" in a or "NO_ACTION" in a or a in {"STOP", "HUMAN_REJUDGE", "UNKNOWN", ""}:
            return "REJUDGE"
        return a

    def _vla_is_experimental_rotate_transition(tr: Dict[str, Any]) -> bool:
        """vla_0815_v5: quarantine every ROTATE macro while motion is experimental.

        Exact-action matching was too narrow: an unexpected legacy-named ROTATE_MID
        could be labeled GOOD and become training_eligible=True. Macro ROTATE is now
        sufficient, so naming/override mistakes cannot leak experimental ROTATE into training.
        """
        if not isinstance(tr, dict):
            return False
        macro = _vla_macro_action(
            tr.get("executed_macro_action")
            or tr.get("executed_action")
            or tr.get("action_variant")
        )
        return str(macro).upper() == "ROTATE"

    def _vla_file_sha256(path: str) -> Optional[str]:
        try:
            h = hashlib.sha256()
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return None

    def _vla_json_sha256(value: Any) -> Optional[str]:
        try:
            raw = json.dumps(_json_safe(value), ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
            return hashlib.sha256(raw).hexdigest()
        except Exception:
            return None

    def _vla_model_metadata(path_value: Any) -> Dict[str, Any]:
        path = os.path.abspath(os.path.expanduser(str(path_value or ""))) if path_value else ""
        out = {"path": path or None, "exists": bool(path and os.path.isfile(path))}
        if out["exists"]:
            try:
                st = os.stat(path)
                out.update({
                    "size_bytes": int(st.st_size),
                    "mtime_ns": int(st.st_mtime_ns),
                    "sha256": _vla_file_sha256(path),
                })
            except Exception:
                pass
        return out

