    def _vla_compact_value(value: Any, depth: int = 0) -> Any:
        if depth > 6:
            return str(type(value).__name__)
        if isinstance(value, np.ndarray):
            arr = np.asarray(value)
            out = {"shape": list(arr.shape), "dtype": str(arr.dtype)}
            if arr.size > 0 and np.issubdtype(arr.dtype, np.number):
                try:
                    out.update({"min": float(np.nanmin(arr)), "max": float(np.nanmax(arr)), "mean": float(np.nanmean(arr))})
                except Exception:
                    pass
            return out
        if isinstance(value, (np.floating, np.integer)):
            return value.item()
        if isinstance(value, dict):
            skip = {"contour", "pts", "heatmap", "binary", "inner_mask", "ready_heatmap", "ready_inner_mask", "mask"}
            return {str(k): _vla_compact_value(v, depth + 1) for k, v in value.items() if str(k) not in skip}
        if isinstance(value, (list, tuple)):
            seq = list(value)
            if len(seq) > 50:
                return {"count": len(seq), "preview": [_vla_compact_value(v, depth + 1) for v in seq[:10]]}
            return [_vla_compact_value(v, depth + 1) for v in seq]
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        return str(value)

    def _vla_extract_metrics(state: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        s = state if isinstance(state, dict) else {}
        cca = s.get("ready_to_rotate_cca_status", {}) if isinstance(s.get("ready_to_rotate_cca_status", {}), dict) else {}
        structure = s.get("structure", {}) if isinstance(s.get("structure", {}), dict) else {}
        pose = s.get("pose_symmetry", {}) if isinstance(s.get("pose_symmetry", {}), dict) else {}
        try:
            rot = _a152_rotation_plan_status()
        except Exception:
            rot = {}
        return {
            "center_error_mm": None if s.get("center_error_mm") is None else float(s.get("center_error_mm")),
            "wrinkle_ratio": None if s.get("wrinkle_ratio") is None else float(s.get("wrinkle_ratio")),
            "area_px": None if s.get("area_px") is None else float(s.get("area_px")),
            "final_ready": bool(s.get("ready_to_rotate_final_ready", s.get("_final_gate_result", False))),
            "ready_mode": str(s.get("ready_to_rotate_mode", "NO")),
            "pose_symmetry_ok": bool(s.get("pose_symmetry_ok", False)),
            "pose_area_ratio": pose.get("area_ratio"),
            "solidity": structure.get("solidity"),
            "meaningful_count": structure.get("finish_meaningful_count"),
            "max_linear_length_mm": structure.get("finish_max_linear_len_mm"),
            "active_ratio": float(cca.get("dynamic_active_ratio", 0.0) or 0.0),
            "total_area_ratio": float(cca.get("cca_total_area_ratio", 0.0) or 0.0),
            "max_component_area_ratio": float(cca.get("cca_max_component_area_ratio", 0.0) or 0.0),
            "strong_count": int(cca.get("cca_strong_long_component_count", 0) or 0),
            "medium_count": int(cca.get("cca_medium_long_component_count", 0) or 0),
            "rotation_phase": str(auto_x_rotation_state.get("phase", "SPREADING")),
            "pose_rotation_angle_error_deg": rot.get("abs_angle_deg") if isinstance(rot, dict) else None,
            "pose_rotation_ready": bool(rot.get("ready", False)) if isinstance(rot, dict) else False,
        }

    def _vla_rectified_board_image(image: Optional[np.ndarray]) -> Optional[np.ndarray]:
        if image is None or latest_H is None:
            return None
        try:
            min_x, max_x, min_y, max_y = board_bounds(cfg)
            src_pts = []
            for bx, by in ((min_x, max_y), (max_x, max_y), (max_x, min_y), (min_x, min_y)):
                p = board_to_pixel(latest_H, bx, by)
                if p is None:
                    return None
                src_pts.append([float(p[0]), float(p[1])])
            size = max(128, int(getattr(args, "vla_board_image_size", 512)))
            dst_pts = np.array([[0, 0], [size - 1, 0], [size - 1, size - 1], [0, size - 1]], dtype=np.float32)
            M = cv2.getPerspectiveTransform(np.asarray(src_pts, dtype=np.float32), dst_pts)
            return cv2.warpPerspective(image, M, (size, size), flags=cv2.INTER_AREA)
        except Exception as e:
            print(f"[VLA-DATA-WARN] board rectification failed: {repr(e)}")
            return None

    def _vla_shadow_enabled() -> bool:
        return bool(getattr(args, "vla_shadow_test_enable", True))


    def _vla_shadow_thresholds() -> Dict[str, float]:
        return {
            "CENTER": float(np.clip(getattr(args, "vla_shadow_center_threshold", 0.983), 0.0, 1.0)),
            "SPREAD": float(np.clip(getattr(args, "vla_shadow_spread_threshold", 0.752), 0.0, 1.0)),
            "FINISH": float(np.clip(getattr(args, "vla_shadow_finish_threshold", 0.985), 0.0, 1.0)),
        }


    def _vla_shadow_numeric(value: Any, key: str) -> float:
        if isinstance(value, bool):
            return 1.0 if value else 0.0
        if isinstance(value, (int, float, np.integer, np.floating)) and not isinstance(value, bool):
            v = float(value)
            if np.isfinite(v):
                return v
        raise ValueError(f"shadow state value is not finite numeric: {key}={value!r}")


    def _vla_shadow_nested_numeric(root: Dict[str, Any], path: str) -> float:
        cur: Any = root
        for part in str(path).split("."):
            if not isinstance(cur, dict) or part not in cur:
                raise KeyError(f"missing shadow state key: {path}")
            cur = cur[part]
        return _vla_shadow_numeric(cur, path)


    def _vla_shadow_make_state_v2(state: Dict[str, Any]) -> np.ndarray:
        """Exact 25D state used by the Board+State-v2 training converter."""
        metrics = _vla_extract_metrics(state)
        vals: List[float] = []
        base_keys = (
            "center_error_mm", "wrinkle_ratio", "area_px", "pose_symmetry_ok",
            "pose_area_ratio", "solidity", "meaningful_count", "max_linear_length_mm",
            "active_ratio", "total_area_ratio", "max_component_area_ratio",
            "strong_count", "medium_count",
        )
        for key in base_keys:
            if key not in metrics:
                raise KeyError(f"missing shadow metric: {key}")
            vals.append(_vla_shadow_numeric(metrics.get(key), key))

        angle = metrics.get("pose_rotation_angle_error_deg")
        if isinstance(angle, (int, float, np.integer, np.floating)) and not isinstance(angle, bool) and np.isfinite(float(angle)):
            signed_angle = float(angle); angle_valid = 1.0
        elif angle is None:
            signed_angle = 0.0; angle_valid = 0.0
        else:
            raise ValueError(f"unexpected shadow pose_rotation_angle_error_deg={angle!r}")
        vals.extend([signed_angle, angle_valid])

        summary = {
            "planner_heat_stats": state.get("planner_heat_stats", {}) if isinstance(state.get("planner_heat_stats", {}), dict) else {},
            "structure": state.get("structure", {}) if isinstance(state.get("structure", {}), dict) else {},
            "pose_symmetry": state.get("pose_symmetry", {}) if isinstance(state.get("pose_symmetry", {}), dict) else {},
        }
        heat_component_count = _vla_shadow_nested_numeric(summary, "planner_heat_stats.component_count")
        heat_area_cv = _vla_shadow_nested_numeric(summary, "planner_heat_stats.area_cv")
        a3_aspect = _vla_shadow_nested_numeric(summary, "structure.a3_aspect")
        a3_valid_linear_count = _vla_shadow_nested_numeric(summary, "structure.a3_valid_linear_count")
        heat_action2_irregular = _vla_shadow_nested_numeric(summary, "planner_heat_stats.action2_irregular")
        heat_action3_dominant = _vla_shadow_nested_numeric(summary, "planner_heat_stats.action3_dominant")
        heat_best_axis_ratio = _vla_shadow_nested_numeric(summary, "planner_heat_stats.best_axis_ratio")
        heat_best_long_len_to_median = _vla_shadow_nested_numeric(summary, "planner_heat_stats.best_long_len_to_median")
        a3_linear_len_mm = _vla_shadow_nested_numeric(summary, "structure.a3_linear_len")
        pose_axis_len_mm = _vla_shadow_nested_numeric(summary, "pose_symmetry.axis_len_mm")
        a3_linear_len_norm = float(a3_linear_len_mm / pose_axis_len_mm) if pose_axis_len_mm > 1e-6 else 0.0
        abs_rotation_error = abs(signed_angle) if angle_valid > 0.5 else 0.0
        vals.extend([
            heat_component_count, heat_area_cv, a3_aspect, a3_valid_linear_count,
            heat_action2_irregular, heat_action3_dominant, heat_best_axis_ratio,
            heat_best_long_len_to_median, a3_linear_len_norm, abs_rotation_error,
        ])
        out = np.asarray(vals, dtype=np.float32)
        if out.shape != (25,) or not np.all(np.isfinite(out)):
            raise ValueError(f"invalid Shadow state shape/values: {out.shape}")
        return out


    def _vla_shadow_shape(engine_obj, name: str) -> Tuple[int, ...]:
        return tuple(int(x) for x in engine_obj.get_tensor_shape(str(name)))


    def _vla_shadow_shape_match(shape: Tuple[int, ...], expected: Tuple[int, ...]) -> bool:
        return len(shape) == len(expected) and all(int(a) in (-1, int(b)) for a, b in zip(shape, expected))


    def _vla_shadow_load_runtime() -> bool:
        """Load TRT FP32 engine once. Any failure disables only Shadow."""
        with vla_shadow_lock:
            if bool(vla_shadow_runtime.get("initialized", False)):
                return bool(vla_shadow_runtime.get("available", False))
            vla_shadow_runtime["initialized"] = True
            vla_shadow_runtime["status"] = "INITIALIZING"
        t0 = time.perf_counter()
        engine_path = os.path.abspath(os.path.expanduser(str(getattr(args, "vla_shadow_engine", SHARED_VLA_SHADOW_ENGINE))))
        norm_path = os.path.abspath(os.path.expanduser(str(getattr(args, "vla_shadow_state_norm", SHARED_VLA_SHADOW_STATE_NORM))))
        try:
            if not os.path.isfile(engine_path):
                raise FileNotFoundError(f"Shadow engine not found: {engine_path}")
            if not os.path.isfile(norm_path):
                raise FileNotFoundError(f"Shadow state norm not found: {norm_path}")
            import tensorrt as _trt
            import torch as _torch
            import torch.nn.functional as _F
            if not _torch.cuda.is_available():
                raise RuntimeError("CUDA unavailable for TensorRT Shadow")

            d = np.load(norm_path, allow_pickle=False)
            if set(d.files) != {"mean", "std"}:
                raise ValueError(f"state norm keys must be mean/std, got {list(d.files)}")
            mean = np.asarray(d["mean"], dtype=np.float32).reshape(-1)
            std = np.asarray(d["std"], dtype=np.float32).reshape(-1)
            if mean.shape != (25,) or std.shape != (25,) or not np.all(np.isfinite(mean)) or not np.all(np.isfinite(std)) or np.any(std <= 1e-8):
                raise ValueError(f"invalid state norm mean={mean.shape} std={std.shape}")

            logger = _trt.Logger(_trt.Logger.ERROR)
            runtime = _trt.Runtime(logger)
            with open(engine_path, "rb") as f:
                engine = runtime.deserialize_cuda_engine(f.read())
            if engine is None:
                raise RuntimeError("TensorRT engine deserialization failed")
            context = engine.create_execution_context()
            if context is None:
                raise RuntimeError("TensorRT execution context creation failed")

            ios = []
            for i in range(int(engine.num_io_tensors)):
                name = str(engine.get_tensor_name(i))
                ios.append((name, engine.get_tensor_mode(name), _vla_shadow_shape(engine, name), engine.get_tensor_dtype(name)))
            inputs = [x for x in ios if x[1] == _trt.TensorIOMode.INPUT]
            outputs = [x for x in ios if x[1] == _trt.TensorIOMode.OUTPUT]

            def pick(items, preferred, expected):
                exact = [x for x in items if x[0] == preferred]
                pool = exact if exact else [x for x in items if _vla_shadow_shape_match(x[2], expected)]
                if len(pool) != 1:
                    raise RuntimeError(f"cannot resolve TRT tensor {preferred}: {[(x[0], x[2], str(x[3])) for x in items]}")
                if pool[0][3] != _trt.float32:
                    raise RuntimeError(f"TRT {preferred} I/O must be FLOAT, got {pool[0][3]}")
                return pool[0]

            board_io = pick(inputs, "board", (1, 3, 224, 224))
            state_io = pick(inputs, "state", (1, 25))
            logits_io = pick(outputs, "logits", (1, 7))
            if -1 in board_io[2] and not context.set_input_shape(board_io[0], (1, 3, 224, 224)):
                raise RuntimeError("failed to set dynamic board shape")
            if -1 in state_io[2] and not context.set_input_shape(state_io[0], (1, 25)):
                raise RuntimeError("failed to set dynamic state shape")

            load_ms = (time.perf_counter() - t0) * 1000.0
            with vla_shadow_lock:
                vla_shadow_runtime.update({
                    "available": True, "status": "READY", "error": None,
                    "trt": _trt, "torch": _torch, "F": _F, "logger": logger,
                    "runtime": runtime, "engine": engine, "context": context,
                    "board_name": board_io[0], "state_name": state_io[0], "logits_name": logits_io[0],
                    "state_mean": mean, "state_std": std,
                    "engine_path": engine_path, "engine_sha256": _vla_file_sha256(engine_path),
                    "state_norm_path": norm_path, "state_norm_sha256": _vla_file_sha256(norm_path),
                    "load_ms": float(load_ms),
                })
            print(f"[VLA0854-MODEL-TRT-READY] board={board_io[0]}{board_io[2]} state={state_io[0]}{state_io[2]} logits={logits_io[0]}{logits_io[2]} load={load_ms:.1f}ms | FP32 CLASSIFIER_READY=YES DIRECT_ROBOT_CONTROL=NO")
            return True
        except Exception as exc:
            load_ms = (time.perf_counter() - t0) * 1000.0
            with vla_shadow_lock:
                vla_shadow_runtime.update({"available": False, "status": "UNAVAILABLE", "error": repr(exc), "engine_path": engine_path, "state_norm_path": norm_path, "load_ms": float(load_ms)})
            print(f"[VLA0854-MODEL-TRT-UNAVAILABLE] {repr(exc)} | hybrid decision falls back to Stage3 AUTO-X")
            return False


    def _vla_shadow_base_result(observe_label: str) -> Dict[str, Any]:
        return {
            "policy_id": VLA_SHADOW_POLICY_ID,
            "classifier_version": VLA_SHADOW_CLASSIFIER_VERSION,
            "threshold_version": VLA_SHADOW_THRESHOLD_VERSION,
            "state_schema_version": int(VLA_SHADOW_STATE_SCHEMA_VERSION),
            "model_action_taxonomy": list(VLA_SHADOW_MODEL_ACTIONS),
            "source_inference_serial": int(inference_serial),
            "observe_label": str(observe_label),
            "backend": "TensorRT", "engine_precision": "FP32", "io_dtype": "FLOAT",
            "shadow_only": False, "robot_control": False, "direct_robot_control": False,
        "hybrid_macro_decision_input": True, "human_final_authority": True,
            "status": "NOT_RUN", "predicted_action": None, "predicted_display_action": None,
            "confidence": None, "probabilities": None,
            "auto_candidate": False, "auto_candidate_action": None,
            "candidate_threshold": None, "candidate_reason": None,
            "thresholds": _vla_shadow_thresholds(),
        }


    def _vla_shadow_predict_board_state(state: Dict[str, Any], observe_label: str, board_bgr: Optional[np.ndarray]) -> Dict[str, Any]:
        """TensorRT classifier inference for the exact frozen observation; hybrid gate may use only its macro output."""
        result = _vla_shadow_base_result(observe_label)
        if not _vla_shadow_enabled():
            result.update({"status": "DISABLED", "candidate_reason": "shadow_test_disabled"})
            with vla_shadow_lock:
                vla_shadow_runtime["last_result"] = copy.deepcopy(result)
            return result
        if not isinstance(board_bgr, np.ndarray) or board_bgr.size == 0:
            result.update({"status": "INPUT_UNAVAILABLE", "candidate_reason": "rectified_board_image_unavailable"})
            with vla_shadow_lock:
                vla_shadow_runtime["last_result"] = copy.deepcopy(result)
            return result
        if not _vla_shadow_load_runtime():
            with vla_shadow_lock:
                result.update({
                    "status": "UNAVAILABLE", "candidate_reason": "shadow_runtime_unavailable",
                    "error": vla_shadow_runtime.get("error"),
                    "engine_path": vla_shadow_runtime.get("engine_path"),
                    "state_norm_path": vla_shadow_runtime.get("state_norm_path"),
                })
                vla_shadow_runtime["last_result"] = copy.deepcopy(result)
            return result

        t0 = time.perf_counter()
        try:
            state_vec = _vla_shadow_make_state_v2(state)
            with vla_shadow_lock:
                _torch = vla_shadow_runtime["torch"]
                _F = vla_shadow_runtime["F"]
                context = vla_shadow_runtime["context"]
                board_name = str(vla_shadow_runtime["board_name"])
                state_name = str(vla_shadow_runtime["state_name"])
                logits_name = str(vla_shadow_runtime["logits_name"])
                mean = np.asarray(vla_shadow_runtime["state_mean"], dtype=np.float32)
                std = np.asarray(vla_shadow_runtime["state_std"], dtype=np.float32)

                board_rgb = cv2.cvtColor(board_bgr, cv2.COLOR_BGR2RGB)
                image_np = np.ascontiguousarray(board_rgb.transpose(2, 0, 1), dtype=np.float32) / 255.0
                board_t = _torch.from_numpy(image_np).unsqueeze(0).cuda(non_blocking=False)
                board_t = _F.interpolate(
                    board_t, size=(224, 224), mode="bilinear", align_corners=False
                ).contiguous()

                # Diagnostic only. Do NOT feed state_norm to the engine.
                state_norm = np.ascontiguousarray((state_vec - mean) / std, dtype=np.float32)
                state_raw = np.ascontiguousarray(state_vec, dtype=np.float32)
                state_t = _torch.from_numpy(state_raw).unsqueeze(0).cuda(non_blocking=False).contiguous()
                logits_t = _torch.empty((1, 7), dtype=_torch.float32, device=board_t.device)

                context.set_tensor_address(board_name, int(board_t.data_ptr()))
                context.set_tensor_address(state_name, int(state_t.data_ptr()))
                context.set_tensor_address(logits_name, int(logits_t.data_ptr()))
                stream = _torch.cuda.current_stream()
                try:
                    ok = context.execute_async_v3(stream_handle=int(stream.cuda_stream))
                except TypeError:
                    ok = context.execute_async_v3(int(stream.cuda_stream))
                if ok is False:
                    raise RuntimeError("TensorRT execute_async_v3 returned False")
                stream.synchronize()
                probs_t = _torch.softmax(logits_t, dim=1)[0]
                pred_idx = int(_torch.argmax(probs_t).item())
                conf = float(probs_t[pred_idx].item())
                probs = [float(x) for x in probs_t.detach().cpu().numpy().tolist()]
                engine_path = vla_shadow_runtime.get("engine_path")
                engine_sha = vla_shadow_runtime.get("engine_sha256")
                norm_path = vla_shadow_runtime.get("state_norm_path")
                norm_sha = vla_shadow_runtime.get("state_norm_sha256")

            predicted_action = str(VLA_SHADOW_MODEL_ACTIONS[pred_idx])
            display_action = "LEGACY_PRESS_AUDIT" if predicted_action == "PRESS" else predicted_action
            thresholds = _vla_shadow_thresholds()
            threshold = thresholds.get(predicted_action)
            auto_candidate = bool(predicted_action in {"CENTER", "SPREAD", "FINISH"} and threshold is not None and conf >= float(threshold))
            if predicted_action == "PRESS":
                reason = "legacy_PRESS_model_class_audit_only_no_robot_PRESS_route"
            elif threshold is None:
                reason = "action_not_enabled_for_shadow_auto_candidate"
            elif auto_candidate:
                reason = f"{predicted_action}_confidence_pass"
            else:
                reason = f"{predicted_action}_confidence_below_threshold"
            elapsed_ms = (time.perf_counter() - t0) * 1000.0
            result.update({
                "status": "OK", "predicted_index": pred_idx,
                "predicted_action": predicted_action, "predicted_display_action": display_action,
                "confidence": conf, "probabilities": {name: probs[i] for i, name in enumerate(VLA_SHADOW_MODEL_ACTIONS)},
                "auto_candidate": auto_candidate,
                "auto_candidate_action": predicted_action if auto_candidate else None,
                "candidate_threshold": None if threshold is None else float(threshold),
                "candidate_reason": reason,
                "state_v2_names": list(VLA_SHADOW_STATE_NAMES),
                "state_v2": [float(x) for x in state_vec.tolist()],
                "state_v2_normalized": [float(x) for x in state_norm.tolist()],
                "engine_input_contract": {
                    "board": "RGB_float32_0to1_resized_224_no_external_imagenet_norm",
                    "state": "raw_25D_float32_no_external_state_norm",
                    "normalization": "embedded_inside_ONNX_TensorRT_graph",
                },
                "engine_path": engine_path, "engine_sha256": engine_sha,
                "state_norm_path": norm_path, "state_norm_sha256": norm_sha,
                "inference_ms": float(elapsed_ms),
            })
            with vla_shadow_lock:
                vla_shadow_runtime["last_result"] = copy.deepcopy(result)
            cand_txt = f"YES threshold={float(threshold):.3f}" if auto_candidate else (f"NO threshold={float(threshold):.3f}" if threshold is not None else "NO action-not-enabled")
            print(f"[VLA0854-MODEL-TRT] serial={inference_serial} pred={display_action} conf={conf:.4f} audit_candidate={cand_txt} time={elapsed_ms:.1f}ms | FP32 TRT HYBRID_GATE_INPUT=YES DIRECT_ROBOT_CONTROL=NO")
            return result
        except Exception as exc:
            elapsed_ms = (time.perf_counter() - t0) * 1000.0
            result.update({"status": "ERROR", "error": repr(exc), "candidate_reason": "shadow_inference_error", "inference_ms": float(elapsed_ms)})
            with vla_shadow_lock:
                vla_shadow_runtime["last_result"] = copy.deepcopy(result)
            print(f"[VLA0854-MODEL-TRT-ERROR] serial={inference_serial} error={repr(exc)} time={elapsed_ms:.1f}ms | AUTO-X fallback")
            return result

    def _vla_model_decision_enabled() -> bool:
        return bool(getattr(args, "vla_model_decision_enable", True))


    def _vla_model_decision_thresholds() -> Dict[str, float]:
        return {
            "CENTER": float(np.clip(getattr(args, "vla_model_center_threshold", 0.70), 0.0, 1.0)),
            "SPREAD": float(np.clip(getattr(args, "vla_model_spread_threshold", 0.60), 0.0, 1.0)),
            "ROTATE": float(np.clip(getattr(args, "vla_model_rotate_threshold", 0.60), 0.0, 1.0)),
            "FINISH": float(np.clip(getattr(args, "vla_model_finish_threshold", 0.80), 0.0, 1.0)),
        }


    def _vla_model_gate_from_shadow(shadow_result: Any) -> Dict[str, Any]:
        """Pure decision gate: no planner mutation and absolutely no robot motion."""
        thresholds = _vla_model_decision_thresholds()
        min_margin = float(np.clip(getattr(args, "vla_model_min_margin", 0.15), 0.0, 1.0))
        route: Dict[str, Any] = {
            "policy_id": VLA_MODEL_DECISION_POLICY_ID,
            "hybrid_mode_enabled": bool(_vla_model_decision_enabled()),
            "supported_actions": list(VLA_MODEL_DECISION_SUPPORTED_ACTIONS),
            "thresholds": copy.deepcopy(thresholds),
            "min_margin": float(min_margin),
            "model_predicted_action": None,
            "model_predicted_display_action": None,
            "model_confidence": None,
            "model_second_confidence": None,
            "model_margin": None,
            "model_threshold": None,
            "model_supported_action": False,
            "model_gate_pass": False,
            "model_selected": False,
            "model_selected_macro_action": None,
            "model_selected_exact_action": None,
            "decision_source": "AUTO_X_FALLBACK",
            "fallback_reason": None,
            "physical_execute": "ENTER_REQUIRED" if bool(_vla_model_decision_enabled()) else "STAGE3_DEFAULT",
        }
        if not route["hybrid_mode_enabled"]:
            route["decision_source"] = "AUTO_X"
            route["fallback_reason"] = "HYBRID_DISABLED"
            return route
        if not isinstance(shadow_result, dict):
            route["fallback_reason"] = "MODEL_RESULT_UNAVAILABLE"
            return route
        status = str(shadow_result.get("status") or "NOT_RUN").upper()
        route["model_status"] = status
        if status != "OK":
            route["fallback_reason"] = f"MODEL_STATUS_{status}"
            return route
        pred = str(shadow_result.get("predicted_action") or "").upper()
        display = str(shadow_result.get("predicted_display_action") or pred or "-")
        route["model_predicted_action"] = pred or None
        route["model_predicted_display_action"] = display
        try:
            conf = float(shadow_result.get("confidence"))
        except Exception:
            route["fallback_reason"] = "MODEL_CONFIDENCE_INVALID"
            return route
        if not np.isfinite(conf):
            route["fallback_reason"] = "MODEL_CONFIDENCE_INVALID"
            return route
        route["model_confidence"] = float(conf)

        probs_obj = shadow_result.get("probabilities")
        if not isinstance(probs_obj, dict):
            route["fallback_reason"] = "MODEL_PROBABILITIES_UNAVAILABLE"
            return route
        probs: Dict[str, float] = {}
        try:
            for name in VLA_SHADOW_MODEL_ACTIONS:
                v = float(probs_obj.get(name))
                if not np.isfinite(v):
                    raise ValueError(name)
                probs[str(name)] = v
        except Exception:
            route["fallback_reason"] = "MODEL_PROBABILITIES_INVALID"
            return route
        prob_values = list(probs.values())
        if any((v < -1e-6 or v > 1.000001) for v in prob_values):
            route["fallback_reason"] = "MODEL_PROBABILITIES_OUT_OF_RANGE"
            return route
        prob_sum = float(sum(prob_values))
        if not np.isfinite(prob_sum) or abs(prob_sum - 1.0) > 0.01:
            route["fallback_reason"] = "MODEL_PROBABILITIES_NOT_NORMALIZED"
            return route
        ranked = sorted(probs.items(), key=lambda kv: kv[1], reverse=True)
        if not ranked or str(ranked[0][0]) != pred:
            route["fallback_reason"] = "MODEL_TOP1_PROBABILITY_MISMATCH"
            return route
        top_conf = float(ranked[0][1])
        if abs(float(conf) - top_conf) > 1e-4:
            route["fallback_reason"] = "MODEL_CONFIDENCE_TOP1_MISMATCH"
            return route
        second_conf = float(ranked[1][1]) if len(ranked) > 1 else 0.0
        margin = float(top_conf - second_conf)
        route["model_second_confidence"] = second_conf
        route["model_margin"] = margin

        if pred == "PRESS":
            route["fallback_reason"] = "LEGACY_PRESS_AUDIT_ONLY_AUTO_X_FALLBACK"
            return route
        if pred not in VLA_MODEL_DECISION_SUPPORTED_ACTIONS:
            route["fallback_reason"] = f"{pred or 'UNKNOWN'}_AUTO_X_ONLY"
            return route
        route["model_supported_action"] = True
        threshold = thresholds.get(pred)
        route["model_threshold"] = None if threshold is None else float(threshold)
        if threshold is None:
            route["fallback_reason"] = "MODEL_THRESHOLD_UNAVAILABLE"
            return route
        if conf < float(threshold):
            route["fallback_reason"] = f"LOW_CONFIDENCE_{pred}"
            return route
        if margin < float(min_margin):
            route["fallback_reason"] = f"LOW_MARGIN_{pred}"
            return route
        route["model_gate_pass"] = True
        route["decision_source"] = "MODEL_CANDIDATE"
        route["fallback_reason"] = None
        return route

