    def _vla_record_observation(state: Dict[str, Any], observe_label: str) -> Optional[str]:
        """Submission observer: same-snapshot model inference only; no dataset persistence."""
        corrected_img = snapshot_frame.copy() if isinstance(snapshot_frame, np.ndarray) else None
        board_img = _vla_rectified_board_image(corrected_img)
        try:
            result = _vla_shadow_predict_board_state(state, str(observe_label), board_img)
        except Exception as exc:
            result = {
                "status": "ERROR",
                "error": repr(exc),
                "predicted_action": None,
                "predicted_display_action": None,
                "confidence": None,
                "probabilities": {},
            }
            print(f"[VLA0855-MODEL-ERROR] {repr(exc)}; AUTO-X fallback remains available")
        with submission_state_lock:
            submission_runtime_state["model_result"] = copy.deepcopy(result)
            submission_runtime_state["model_status"] = str(result.get("status", "NOT_RUN"))
            submission_runtime_state["model_route"] = None
        return None

