    def _vla_action2_spread_eval_from_transition(tr: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        """motion_v3: compute the original A79 ACTION2 plateau metric from the true VLA before/after pair.

        The old execution-time hook could read latest_spread_eval from an older motion because AUTO-X
        intentionally waits for the next fresh stillness-gated observation.  This helper uses only the
        persisted before/after metrics of the just-completed NORMAL SPREAD transition.  It does not
        change planner action selection and it never treats ORTHO_SPREAD as an ACTION2 plateau sample.
        """
        if not isinstance(tr, dict):
            return None
        if str(tr.get("executed_macro_action", "")).upper() != "SPREAD":
            return None
        before = tr.get("before_metrics", {}) if isinstance(tr.get("before_metrics", {}), dict) else {}
        after = tr.get("after_metrics", {}) if isinstance(tr.get("after_metrics", {}), dict) else {}
        try:
            before_area = float(before.get("area_px"))
            after_area = float(after.get("area_px"))
        except Exception:
            return None
        if not (math.isfinite(before_area) and math.isfinite(after_area)) or before_area <= 1.0:
            return None
        area_gain_pct = (after_area - before_area) / before_area * 100.0
        return {
            "area_gain_pct": float(area_gain_pct),
            "before_area_px": float(before_area),
            "after_area_px": float(after_area),
            "source": "VLA_FRESH_BEFORE_AFTER",
            "transition_id": tr.get("transition_id"),
        }


