    def _a150_late_phase() -> str:
        phase = str(auto_x_late_cca_state.get("phase", "NORMAL") or "NORMAL").upper()
        return phase if phase in {"NORMAL", "LATE", "STRONG_RECOVERY"} else "NORMAL"

    def _a150_effective_probe_limit() -> int:
        legacy = int(max(1, getattr(args, "auto_x_late_track_max_probe_count", 1)))
        recovery_limit = int(max(1, getattr(args, "auto_x_late_recovery_probe_limit", 2)))
        needed = int(max(1, getattr(args, "auto_x_late_recovery_stagnation_limit", 3))) - 1
        # Even when Strong Recovery itself is disabled, the observation sequence
        # must still be able to reach its configured classification boundary.
        return int(max(legacy, recovery_limit, needed))

    def _a150_enter_late_visit(reason: str) -> None:
        visit = int(auto_x_late_cca_state.get("late_visit_id", 0) or 0) + 1
        auto_x_late_cca_state.update({
            "phase": "LATE", "active": True,
            "late_visit_id": visit,
            "late_visit_started_motion_count": int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0),
            "pending_evaluation": None, "pose_soft_key": None, "pose_soft_count": 0,
            "correction_count": 0, "last_result": None,
            "last_classification": None, "last_transition_reason": str(reason),
            "meaningful_components": [],
        })
        print(
            f"[A150-PHASE] ENTER LATE_VISIT_{visit} total_motion={int(auto_x_ready_cycle.get('garment_motion_count',0) or 0)} "
            f"recovery_used={int(auto_x_late_cca_state.get('recovery_used_count',0) or 0)} reason={reason}"
        )

    def _a150_demote_current_visit_structural() -> int:
        visit = int(auto_x_late_cca_state.get("late_visit_id", 0) or 0)
        need = int(max(1, getattr(args, "auto_x_structural_candidate_seen_count", 2)))
        demoted = 0
        for line in list(auto_x_structural_line_memory.get("lines", []) or []):
            if not isinstance(line, dict):
                continue
            if not bool(line.get("a133_late_confirmed", False)):
                continue
            if int(line.get("a150_confirmed_late_visit_id", -1) or -1) != visit:
                continue
            line["ignored"] = False
            line["a133_late_confirmed"] = False
            line["a150_demoted_from_late_visit_id"] = visit
            line["a150_demoted_at_motion_count"] = int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0)
            line["a150_previous_ignored_reason"] = str(line.get("ignored_reason", ""))
            line["ignored_reason"] = f"A150 recovery demoted Late-visit-{visit} structural confirmation to candidate"
            line["ignored_at"] = 0.0
            line["consecutive_seen_count"] = max(need, int(line.get("consecutive_seen_count", 0) or 0))
            demoted += 1
        return demoted

    def _a150_enter_strong_recovery(reason: str, classification: str, track_id: Any = None) -> bool:
        if not bool(getattr(args, "auto_x_late_recovery_enable", True)):
            return False
        used = int(auto_x_late_cca_state.get("recovery_used_count", 0) or 0)
        max_epochs = int(max(0, getattr(args, "auto_x_late_recovery_max_epochs", 1)))
        if used >= max_epochs:
            print(f"[A150-RECOVERY-BLOCKED] used={used}/{max_epochs}; no second Strong Recovery. reason={reason}")
            return False
        current_visit = int(auto_x_late_cca_state.get("late_visit_id", 0) or 0)
        demoted = _a150_demote_current_visit_structural()
        kept_tracks = []
        removed_tracks = 0
        for tr in list(auto_x_late_cca_state.get("tracks", []) or []):
            if not isinstance(tr, dict):
                continue
            visit_raw = tr.get("late_visit_id", current_visit)
            visit = int(current_visit if visit_raw is None else visit_raw)
            state_name = str(tr.get("state", "NEW"))
            keep = bool(state_name == "RESOLVED" or (visit < current_visit and state_name == "STRUCTURAL_CONFIRMED"))
            if keep:
                kept_tracks.append(tr)
            else:
                removed_tracks += 1
        auto_x_structural_line_memory["last_action3_probe"] = None
        auto_x_structural_line_memory["last_repeat_action3_probe"] = None
        auto_x_late_cca_state.update({
            "phase": "STRONG_RECOVERY", "active": False,
            "pending_evaluation": None, "pose_soft_key": None, "pose_soft_count": 0,
            "correction_count": 0, "last_result": "Strong Recovery armed",
            "recovery_used_count": used + 1, "recovery_motion_count": 0,
            "recovery_started_motion_count": int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0),
            "last_classification": str(classification), "last_transition_reason": str(reason),
            "meaningful_components": [], "tracks": kept_tracks,
        })
        for key in ("a2_gray_count", "a3_gray_count", "a3_gray_any_count", "near_ready_count",
                    "no_action_count", "pose_rejudge_count", "ambiguous_stuck_count"):
            auto_x_gray_memory[key] = 0
        auto_x_gray_memory["last_ambiguous_stuck_kind"] = None
        _b58_reset_probe_gate("A150 Strong Recovery partial reset")
        print(
            f"[A150-PHASE] ENTER STRONG_RECOVERY classification={classification} track_id={track_id} "
            f"kept_resolved_tracks={len(kept_tracks)} removed_transient_tracks={removed_tracks} "
            f"demoted_visit_structural={demoted} max_actions={int(max(1,getattr(args,'auto_x_late_recovery_max_actions',5)))} reason={reason}"
        )
        return True

    def _a152_reset_rotation_consensus(reason: str = "") -> None:
        auto_x_rotation_state["consensus_kind"] = None
        auto_x_rotation_state["consensus_angle_deg"] = None
        auto_x_rotation_state["consensus_inference_serial"] = -1
        auto_x_rotation_state["consensus_observation_count"] = 0
        if reason:
            print(f"[A152-ROTATE-CONSENSUS-RESET] reason={reason}")

    def _a152_rotate_aligned_latch_gate(
        rot: Dict[str, Any],
        context: str,
        *,
        allow_enter: bool = False,
    ) -> Tuple[bool, str]:
        """vla_0827 AUTO-X-only small-angle ROTATE hysteresis.

        The legacy pose planner still uses its 8deg deadband.  This garment-local
        latch exists only to prevent repeated small ROTATE <-> SPREAD ping-pong:
          - after an accepted/reliable angle reaches <= enter (12deg default), latch ON;
          - while ON, suppress AUTO-X ROTATE through release (18deg default);
          - release only on a fresh usable angle > release.

        `allow_enter` is deliberately False before the existing 8..14deg fresh
        confirmation is consumed.  Thus an 8..12deg first sample cannot bypass
        the established confirmation policy merely by arming this latch.
        """
        enter = max(0.0, float(getattr(args, "auto_x_rotate_aligned_enter_deg", 12.0)))
        release = max(enter, float(getattr(args, "auto_x_rotate_aligned_release_deg", 18.0)))
        latched = bool(auto_x_rotation_state.get("rotate_aligned_latched", False))

        if not isinstance(rot, dict) or not bool(rot.get("available", False)) or rot.get("abs_angle_deg") is None:
            return latched, (
                f"ROTATE aligned latch={'ON' if latched else 'OFF'}; usable angle unavailable; "
                f"enter<={enter:.1f}deg release>{release:.1f}deg"
            )

        abs_angle = abs(float(rot.get("abs_angle_deg")))
        source = str(rot.get("pose_inference_source") or "UNKNOWN").upper()
        auto_x_rotation_state["rotate_aligned_last_abs_angle_deg"] = float(abs_angle)
        auto_x_rotation_state["rotate_aligned_last_source"] = source

        if latched and abs_angle > release + 1e-9:
            auto_x_rotation_state["rotate_aligned_latched"] = False
            auto_x_rotation_state["rotate_aligned_latched_at_motion_count"] = -1
            auto_x_rotation_state["rotate_aligned_latched_at_inference_serial"] = -1
            _a152_reset_rotation_consensus(
                f"ROTATE aligned latch released at {abs_angle:.1f}>{release:.1f}deg"
            )
            print(
                f"[A152-ROTATE-ALIGNED-LATCH-OFF] context={context} source={source} "
                f"abs={abs_angle:.1f}deg > release={release:.1f}deg; ROTATE re-armed"
            )
            return False, (
                f"ROTATE aligned latch OFF: abs={abs_angle:.1f}deg > {release:.1f}deg; ROTATE re-armed"
            )

        if (not latched) and bool(allow_enter) and abs_angle <= enter + 1e-9:
            auto_x_rotation_state["rotate_aligned_latched"] = True
            auto_x_rotation_state["rotate_aligned_latched_at_motion_count"] = int(
                auto_x_ready_cycle.get("garment_motion_count", 0) or 0
            )
            auto_x_rotation_state["rotate_aligned_latched_at_inference_serial"] = int(inference_serial)
            print(
                f"[A152-ROTATE-ALIGNED-LATCH-ON] context={context} source={source} "
                f"abs={abs_angle:.1f}deg <= enter={enter:.1f}deg; "
                f"hold ROTATE until abs>{release:.1f}deg"
            )
            return True, (
                f"ROTATE aligned latch ON: abs={abs_angle:.1f}deg <= {enter:.1f}deg; "
                f"re-arm only above {release:.1f}deg"
            )

        latched = bool(auto_x_rotation_state.get("rotate_aligned_latched", False))
        if latched:
            print(
                f"[A152-ROTATE-ALIGNED-LATCH-HOLD] context={context} source={source} "
                f"abs={abs_angle:.1f}deg <= release={release:.1f}deg; AUTO-X ROTATE suppressed"
            )
            return True, (
                f"ROTATE aligned latch HOLD: abs={abs_angle:.1f}deg <= {release:.1f}deg"
            )
        return False, (
            f"ROTATE aligned latch OFF: abs={abs_angle:.1f}deg; "
            f"enter<={enter:.1f}deg release>{release:.1f}deg"
        )


    def _a152_rotation_plan_status() -> Dict[str, Any]:
        plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
        if not isinstance(plan, dict):
            return {
                "plan": None, "available": False, "ready": False, "done": False,
                "angle_deg": None, "abs_angle_deg": None,
                "reason": str(latest_pose_rotation_status or "no pose rotation plan"),
                "exact_action": None, "pose_inference_source": None,
                "semantic_axis_gate_pass": None,
            }
        try:
            angle = float(plan.get("delta_full_deg"))
        except Exception:
            angle = None
        raw_done = bool(plan.get("done", False))
        exact = str(plan.get("rotation_motion_exact_action") or "").upper()
        source = str(plan.get("pose_inference_source", "UNKNOWN") or "UNKNOWN").upper()
        axis_len = float(plan.get("axis_len_board_mm", 0.0) or 0.0)

        semantic_sources = {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK", "LAST_VALID_POSE_CACHE"}
        semantic_gate_mm = max(0.0, float(getattr(args, "pose_rotate_semantic_axis_gate_mm", 160.0)))
        semantic_gate_required = bool(source in semantic_sources)
        semantic_gate_pass = bool((not semantic_gate_required) or axis_len >= semantic_gate_mm)
        if not semantic_gate_pass:
            reason = (
                f"ROTATE_SEMANTIC_AXIS_GATE: source={source} neck-waist={axis_len:.1f}mm "
                f"< {semantic_gate_mm:.1f}mm; Pose remains available for diagnostics/non-ROTATE logic"
            )
            print(f"[ROTATE-SEMANTIC-AXIS-BLOCK] {reason}")
            return {
                "plan": plan, "available": False, "ready": False, "done": False,
                "angle_deg": None, "abs_angle_deg": None,
                "observed_angle_deg": angle,
                "reason": reason,
                "axis_len_mm": axis_len,
                "semantic_axis_gate_mm": semantic_gate_mm,
                "semantic_axis_gate_pass": False,
                "exact_action": exact or None,
                "pose_inference_source": source,
            }

        linear_ok = bool(raw_done or exact in {"ROTATE_PULL", "ROTATE_SHEAR"})
        ready = bool(plan.get("ready", False) and linear_ok)
        reason = str(plan.get("ready_reason") or plan.get("status") or latest_pose_rotation_status)
        if not raw_done and not linear_ok:
            reason = f"LEGACY_ARC_DISABLED: exact={exact or 'NONE'}; only ROTATE_PULL/ROTATE_SHEAR may execute | {reason}"
        return {
            "plan": plan,
            "available": True,
            "ready": ready,
            "done": raw_done,
            "angle_deg": angle,
            "abs_angle_deg": None if angle is None else abs(float(angle)),
            "reason": reason,
            "axis_len_mm": axis_len,
            "semantic_axis_gate_mm": semantic_gate_mm,
            "semantic_axis_gate_pass": True,
            "exact_action": exact or None,
            "pose_inference_source": source,
        }

    def _a152_note_post_final_rotate_observation() -> None:
        """Evaluate one fresh post-ROTATE observation exactly once (phase metadata may be FINAL)."""
        if not bool(auto_x_rotation_state.get("awaiting_post_rotate_evaluation", False)):
            return
        if int(auto_x_rotation_state.get("last_post_rotate_eval_inference_serial", -1)) == int(inference_serial):
            return
        rot = _a152_rotation_plan_status()
        if not rot.get("available") or rot.get("abs_angle_deg") is None:
            print(f"[A152-ROTATE-EFFECT-WAIT] fresh pose unavailable: {rot.get('reason')}")
            return
        before = auto_x_rotation_state.get("last_final_rotate_angle_error")
        if before is None:
            auto_x_rotation_state["awaiting_post_rotate_evaluation"] = False
            auto_x_rotation_state["last_post_rotate_eval_inference_serial"] = int(inference_serial)
            print("[A152-ROTATE-EFFECT-WARN] missing pre-rotation angle; effectiveness unknown, but future ROTATE remains nonblocking")
            auto_x_rotation_state["final_rotate_no_improvement"] = True
            return
        before_f = abs(float(before))
        after_f = abs(float(rot.get("abs_angle_deg")))
        improvement = float(before_f - after_f)
        min_improve = max(0.0, float(getattr(args, "auto_x_rotate_min_improvement_deg", 5.0)))
        deadband = max(0.0, float(getattr(args, "pose_rotate_deadband_deg", 8.0)))
        effective = bool(after_f <= deadband or improvement >= min_improve)
        auto_x_rotation_state["last_rotation_improvement_deg"] = improvement
        auto_x_rotation_state["final_rotate_no_improvement"] = bool(not effective)
        auto_x_rotation_state["awaiting_post_rotate_evaluation"] = False
        auto_x_rotation_state["last_post_rotate_eval_inference_serial"] = int(inference_serial)
        print(
            f"[A152-ROTATE-EFFECT] before={before_f:.1f}deg after={after_f:.1f}deg "
            f"improvement={improvement:+.1f}deg required={min_improve:.1f}deg "
            f"deadband={deadband:.1f}deg effective={effective}"
        )

    def _a152_rotation_consensus(kind: str, angle_deg: float) -> Tuple[str, str]:
        """Return PASS, WAIT, or EXHAUSTED for conditional fresh angle confirmation."""
        kind_s = str(kind)
        angle_f = float(angle_deg)
        required = max(1, int(getattr(args, "auto_x_rotate_consensus_required_samples", 2)))
        tolerance = max(0.0, float(getattr(args, "auto_x_rotate_consensus_tolerance_deg", 12.0)))
        max_obs = max(required, int(getattr(args, "auto_x_rotate_consensus_max_observations", 3)))
        prev_kind = auto_x_rotation_state.get("consensus_kind")
        prev_angle = auto_x_rotation_state.get("consensus_angle_deg")
        prev_serial = int(auto_x_rotation_state.get("consensus_inference_serial", -1) or -1)
        obs_count = int(auto_x_rotation_state.get("consensus_observation_count", 0) or 0)

        if required <= 1:
            _a152_reset_rotation_consensus("single-sample policy")
            return "PASS", "consensus required_samples=1"

        if prev_kind != kind_s or prev_angle is None or prev_serial == int(inference_serial):
            auto_x_rotation_state.update({
                "consensus_kind": kind_s,
                "consensus_angle_deg": angle_f,
                "consensus_inference_serial": int(inference_serial),
                "consensus_observation_count": 1,
            })
            return "WAIT", f"first fresh {kind_s} angle sample={angle_f:+.1f}deg"

        same_sign = bool(np.sign(float(prev_angle)) == np.sign(angle_f))
        diff = abs(float(prev_angle) - angle_f)
        obs_count += 1
        if same_sign and diff <= tolerance:
            if obs_count >= required:
                msg = (
                    f"fresh angle consensus PASS samples={obs_count}/{required} "
                    f"last={float(prev_angle):+.1f}/{angle_f:+.1f}deg diff={diff:.1f}<={tolerance:.1f}"
                )
                _a152_reset_rotation_consensus(f"{kind_s} consensus passed")
                return "PASS", msg
            auto_x_rotation_state.update({
                "consensus_kind": kind_s,
                "consensus_angle_deg": angle_f,
                "consensus_inference_serial": int(inference_serial),
                "consensus_observation_count": obs_count,
            })
            return "WAIT", (
                f"stable {kind_s} angle sample {obs_count}/{required}: "
                f"last={float(prev_angle):+.1f}/{angle_f:+.1f}deg diff={diff:.1f}<={tolerance:.1f}"
            )

        auto_x_rotation_state.update({
            "consensus_kind": kind_s,
            "consensus_angle_deg": angle_f,
            "consensus_inference_serial": int(inference_serial),
            "consensus_observation_count": obs_count,
        })
        if obs_count >= max_obs:
            msg = (
                f"unstable {kind_s} angle after {obs_count}/{max_obs} observations: "
                f"prev={float(prev_angle):+.1f} current={angle_f:+.1f} diff={diff:.1f} sign_same={same_sign}"
            )
            _a152_reset_rotation_consensus(f"{kind_s} exhausted")
            return "EXHAUSTED", msg
        return "WAIT", (
            f"unstable {kind_s} angle; collect another fresh sample "
            f"{obs_count}/{max_obs}: prev={float(prev_angle):+.1f} current={angle_f:+.1f} "
            f"diff={diff:.1f} sign_same={same_sign}"
        )

    def _a152_rotation_confirmation_policy(kind: str, rot: Dict[str, Any]) -> Tuple[str, str, str]:
        """v13 confidence-aware one-confirmation policy.

        Returns (status, detail, confirm_class), where confirm_class is NONE,
        FALLBACK, or ANGLE.  Reliable current ROI/full-frame Pose outside the
        8..14deg boundary band executes immediately.  Low-trust cache/mask
        sources and near-boundary reliable angles get exactly ONE additional
        fresh observation.  If that one confirmation disagrees, confirmation is
        exhausted immediately; a third snapshot is never requested.
        """
        angle = float(rot.get("angle_deg"))
        abs_angle = abs(angle)
        deadband = max(0.0, float(getattr(args, "pose_rotate_deadband_deg", 8.0)))
        margin = max(0.0, float(getattr(args, "auto_x_rotate_boundary_confirm_margin_deg", 6.0)))
        confirm_upper = deadband + margin
        source = str(rot.get("pose_inference_source") or "UNKNOWN").upper()
        reliable_current = source in {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK"}
        low_trust = not reliable_current
        near_boundary = bool(deadband < abs_angle <= confirm_upper + 1e-9)

        if reliable_current and not near_boundary:
            _a152_reset_rotation_consensus(
                f"{kind} reliable immediate source={source} abs={abs_angle:.1f}>{confirm_upper:.1f}deg"
            )
            return "PASS", (
                f"v13 immediate reliable angle: source={source} abs={abs_angle:.1f}deg "
                f"> confirm_upper={confirm_upper:.1f}deg"
            ), "NONE"

        confirm_class = "FALLBACK" if low_trust else "ANGLE"
        reason = "low-trust-source" if low_trust else "near-deadband"
        pending_kind = str(auto_x_rotation_state.get("consensus_kind") or "")
        pending_prefix = pending_kind.split(":", 1)[0].upper() if pending_kind else ""
        pending_already = bool(pending_prefix in {"MID", "FINAL"})
        if pending_already:
            consensus_kind = pending_kind
            confirm_mode = "confirm-once"
        else:
            consensus_kind = f"{str(kind).upper()}:{confirm_class}:{source if low_trust else 'BOUNDARY'}"
            confirm_mode = "first-sample"

        status, detail = _a152_rotation_consensus(consensus_kind, angle)
        if pending_already and status == "WAIT":
            _a152_reset_rotation_consensus(f"{kind} single confirmation disagreed")
            status = "EXHAUSTED"
            detail = f"single fresh confirmation disagreed; no third observation | {detail}"

        if status == "WAIT":
            print(
                f"[ROTATE-{confirm_class}-CONFIRM-WAIT] mode={confirm_mode} source={source} "
                f"reason={reason} angle={angle:+.1f}deg; {detail}"
            )
        elif status == "PASS":
            print(
                f"[ROTATE-{confirm_class}-CONFIRM-PASS] mode={confirm_mode} source={source} "
                f"reason={reason} angle={angle:+.1f}deg; {detail}"
            )
        elif status == "EXHAUSTED":
            print(
                f"[ROTATE-{confirm_class}-CONFIRM-FAILED] mode={confirm_mode} source={source} "
                f"reason={reason} angle={angle:+.1f}deg; {detail}"
            )
        return status, (
            f"v13 confirm={reason}/{confirm_mode} source={source} band=({deadband:.1f},{confirm_upper:.1f}]deg | {detail}"
        ), confirm_class


    def _a152_is_spread_progress_action(action: str, late_plan: Optional[Dict[str, Any]] = None) -> bool:
        action_s = str(action)
        if action_s in {
            "ACTION2_SEGMENTATION_SPREAD", "ACTION2_SEGMENTATION_SPREAD_REDUCED",
            "SEGMENTATION_SPREAD", "ACTION2_EDGE_WRINKLE_CIRC_PULL",
            "ACTION3_LONG_WRINKLE_NORMAL_PULL", "ACTION3_LONG_WRINKLE_NORMAL_PULL_REDUCED",
        }:
            return True
        if action_s.startswith("LATE_") and action_s != "LATE_CCA_BLOCKER_PROBE":
            return bool(isinstance(late_plan, dict) and str(late_plan.get("kind")) in {"targeted", "dual"})
        return False

    def _a152_commit_successful_action(action: str, pending: Optional[Dict[str, Any]] = None) -> None:
        """Commit rotation counters as diagnostics only; never use them to block future ROTATE."""
        pending = pending if isinstance(pending, dict) else {}
        action_s = str(action)
        auto_x_rotation_state["final_gate_confirmation_latched"] = False
        auto_x_rotation_state["final_gate_latched_motion_count"] = -1
        auto_x_rotation_state["final_gate_latched_inference_serial"] = -1

        if action_s in {"ROTATE_PULL", "ROTATE_SHEAR"}:
            phase = str(pending.get("rotation_phase") or auto_x_rotation_state.get("pending_rotation_phase") or "MID").upper()
            auto_x_rotation_state["pending_rotation_phase"] = None
            if phase == "FINAL":
                auto_x_rotation_state["final_rotate_count"] = int(auto_x_rotation_state.get("final_rotate_count", 0) or 0) + 1
                auto_x_rotation_state["phase"] = "POST_ROTATE_REPAIR"
                auto_x_rotation_state["last_final_rotate_angle_error"] = abs(float(pending.get("rotation_angle_error_before", 0.0) or 0.0))
                auto_x_rotation_state["awaiting_post_rotate_evaluation"] = True
                auto_x_rotation_state["last_post_rotate_eval_inference_serial"] = -1
                auto_x_rotation_state["last_rotation_improvement_deg"] = None
                auto_x_rotation_state["final_rotate_no_improvement"] = False
                auto_x_rotation_state["last_transition_reason"] = f"{action_s} FINAL-phase completed; full Planner repair/verify"
                _a152_reset_rotation_consensus(f"{action_s} FINAL completed")
                print(
                    f"[A152-ROTATE-COMMIT] exact={action_s} phase=FINAL diagnostic_count={auto_x_rotation_state['final_rotate_count']} "
                    f"pre_error={float(auto_x_rotation_state['last_final_rotate_angle_error']):.1f}deg; count is NONBLOCKING"
                )
            else:
                auto_x_rotation_state["mid_rotate_count"] = int(auto_x_rotation_state.get("mid_rotate_count", 0) or 0) + 1
                auto_x_rotation_state["last_transition_reason"] = f"{action_s} MID-phase completed"
                _a152_reset_rotation_consensus(f"{action_s} MID completed")
                print(
                    f"[A152-ROTATE-COMMIT] exact={action_s} phase=MID diagnostic_count={auto_x_rotation_state['mid_rotate_count']}; "
                    "count/cooldown are NONBLOCKING"
                )
            return

        if _a152_is_spread_progress_action(action_s, pending.get("late_plan")):
            auto_x_rotation_state["spread_progress_count"] = int(auto_x_rotation_state.get("spread_progress_count", 0) or 0) + 1
            print(
                f"[A152-SPREAD-PROGRESS] action={action_s} "
                f"count={int(auto_x_rotation_state.get('spread_progress_count',0) or 0)} diagnostic-only"
            )

        if (int(auto_x_rotation_state.get("final_rotate_count", 0) or 0) > 0
                and str(auto_x_rotation_state.get("phase", "SPREADING")) in {"POST_ROTATE_REPAIR", "FINAL_VERIFY"}):
            auto_x_rotation_state["post_final_rotate_repair_count"] = int(auto_x_rotation_state.get("post_final_rotate_repair_count", 0) or 0) + 1
            auto_x_rotation_state["phase"] = "POST_ROTATE_REPAIR"
            print(
                f"[A152-FINAL-REPAIR-COMMIT] action={action_s} "
                f"count={int(auto_x_rotation_state.get('post_final_rotate_repair_count',0) or 0)}/"
                f"{int(max(0,getattr(args,'auto_x_post_final_rotate_repair_max_actions',2)))} diagnostic-only"
            )
        _a152_reset_rotation_consensus(f"physical garment action changed scene: {action_s}")


    def _a152_choose_final_rotation_action(state: Dict[str, Any]) -> Tuple[str, str]:
        phase = str(auto_x_rotation_state.get("phase", "SPREADING"))
        if phase == "SPREADING":
            auto_x_rotation_state["phase"] = "FINAL_ALIGNMENT"
            auto_x_rotation_state["last_transition_reason"] = "wrinkle finish gate first passed"
            auto_x_rotation_state["final_gate_confirmation_latched"] = True
            auto_x_rotation_state["final_gate_latched_motion_count"] = int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0)
            auto_x_rotation_state["final_gate_latched_inference_serial"] = int(inference_serial)
            print("[A152-PHASE] SPREADING -> FINAL_ALIGNMENT")
        else:
            auto_x_rotation_state["phase"] = "FINAL_VERIFY"

        rot = _a152_rotation_plan_status()
        deadband = max(0.0, float(getattr(args, "pose_rotate_deadband_deg", 8.0)))
        if rot.get("available") and rot.get("abs_angle_deg") is not None:
            angle = float(rot.get("angle_deg")); abs_angle = abs(angle)
            source = str(rot.get("pose_inference_source") or "UNKNOWN").upper()
            reliable_current = source in {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK"}
            # <=8deg already needs no ROTATE.  If that result is current/reliable,
            # arm the 12/18 hysteresis now so a following SPREAD cannot immediately
            # re-trigger ROTATE at 12..18deg.  8..12deg still uses the existing
            # one-fresh confirmation before the latch may turn ON.
            latch_on, latch_detail = _a152_rotate_aligned_latch_gate(
                rot, "FINAL", allow_enter=bool(reliable_current and abs_angle <= deadband)
            )
            if bool(rot.get("done")) or abs_angle <= deadband:
                _a152_reset_rotation_consensus("FINAL angle inside deadband")
                auto_x_rotation_state["pending_rotation_phase"] = None
                return "FINISH_READY_FOR_ROTATION", (
                    f"AUTO-X complete: wrinkle gate passed and angle error={abs_angle:.1f}deg <= deadband={deadband:.1f}deg; "
                    f"{latch_detail}"
                )
            if latch_on:
                _a152_reset_rotation_consensus("FINAL ROTATE suppressed by 12/18 aligned latch")
                auto_x_rotation_state["pending_rotation_phase"] = None
                return "FINISH_READY_FOR_ROTATION", (
                    f"AUTO-X complete: wrinkle gate passed; {latch_detail}; "
                    "small-angle ROTATE suppressed to prevent ROTATE/SPREAD ping-pong"
                )
        else:
            return "ROTATE_UNAVAILABLE_CONTINUE", (
                f"FINAL ROTATE unavailable on this observation: {rot.get('reason')}; "
                "do not rejudge-loop solely for ROTATE; continue ordinary planner"
            )

        angle = float(rot.get("angle_deg")); abs_angle = abs(angle)
        if not bool(getattr(args, "auto_x_rotate_enable", True)):
            return "STOP", f"final wrinkle gate passed but automatic rotation is disabled; remaining angle={angle:+.1f}deg"
        if not bool(rot.get("ready")):
            return "ROTATE_UNAVAILABLE_CONTINUE", (
                f"FINAL ROTATE angle exists but executable plan is unavailable: angle={angle:+.1f}deg; "
                f"{rot.get('reason')}; continue ordinary planner"
            )
        if bool(auto_x_rotation_state.get("final_rotate_no_improvement", False)):
            imp = auto_x_rotation_state.get("last_rotation_improvement_deg")
            print(f"[A152-ROTATE-NO-IMPROVEMENT-NONBLOCKING] previous improvement={imp}; fresh planner continues")

        consensus, detail, confirm_class = _a152_rotation_confirmation_policy("FINAL", rot)
        if consensus == "WAIT":
            # every FINAL confirmation path owns a same-garment latch,
            # including POST_ROTATE_REPAIR -> FINAL_VERIFY. A transient fresh CCA
            # final_gate drop must not erase the first angle sample before the one
            # allowed fresh confirmation is consumed.
            auto_x_rotation_state["final_gate_confirmation_latched"] = True
            auto_x_rotation_state["final_gate_latched_motion_count"] = int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0)
            auto_x_rotation_state["final_gate_latched_inference_serial"] = int(inference_serial)
            rejudge_action = (
                "ROTATE_FALLBACK_CONFIRM_REJUDGE"
                if confirm_class == "FALLBACK" else "ROTATE_ANGLE_CONFIRM_REJUDGE"
            )
            return rejudge_action, f"FINAL {confirm_class.lower()} confirmation: {detail}"
        if consensus == "EXHAUSTED":
            return "ROTATE_CONFIRM_FAILED_CONTINUE", (
                f"FINAL {confirm_class.lower()} confirmation failed after exactly one fresh check: {detail}; "
                "ROTATE skipped for this observation and ordinary planner continues"
            )

        # A confirmed 8..12deg sample is the safe point to arm the hysteresis.
        # Do this only after the legacy one-fresh confirmation has PASSed.
        latch_on, latch_detail = _a152_rotate_aligned_latch_gate(rot, "FINAL_CONFIRMED", allow_enter=True)
        if latch_on:
            auto_x_rotation_state["pending_rotation_phase"] = None
            return "FINISH_READY_FOR_ROTATION", (
                f"AUTO-X complete: wrinkle gate passed; {latch_detail}; "
                "confirmed small-angle ROTATE suppressed"
            )

        exact = str(rot.get("exact_action") or "").upper()
        if exact not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
            return "ROTATE_UNAVAILABLE_CONTINUE", (
                f"FINAL independent ROTATE exact action unavailable: exact={exact or 'NONE'}; continue ordinary planner"
            )
        auto_x_rotation_state["pending_rotation_phase"] = "FINAL"
        used = int(auto_x_rotation_state.get("final_rotate_count", 0) or 0)
        return exact, (
            f"FINAL {exact} READY: angle={angle:+.1f}deg abs={abs_angle:.1f}deg; {detail}; "
            f"previous_final_count={used} diagnostic-only/nonblocking"
        )


    def _a152_choose_mid_rotation_action(state: Dict[str, Any]) -> Optional[Tuple[str, str]]:
        """Choose the new exact PULL/SHEAR action directly from the current angle plan.

        v6 intentionally ignores all legacy MID gates: spread-progress>=3, >=30deg,
        legacy ARC executable-delta>=15deg, one-MID budget, and cooldown.
        """
        if not bool(getattr(args, "auto_x_rotate_enable", True)):
            return None
        phase = str(auto_x_rotation_state.get("phase", "SPREADING"))
        # old MID/FINAL orchestration phase must not hide an otherwise safe exact
        # ROTATE. FINAL gate is handled before this function; outside that gate, the
        # exact angle plan may surface during ordinary spreading or post-rotate repair.
        if phase not in {"SPREADING", "POST_ROTATE_REPAIR", "FINAL_VERIFY", "FINAL_ALIGNMENT"}:
            return None
        rot = _a152_rotation_plan_status()
        if not rot.get("available") or rot.get("abs_angle_deg") is None:
            return None
        angle = float(rot.get("angle_deg")); abs_angle = abs(angle)
        deadband = max(0.0, float(getattr(args, "pose_rotate_deadband_deg", 8.0)))
        source = str(rot.get("pose_inference_source") or "UNKNOWN").upper()
        reliable_current = source in {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK"}
        latch_on, latch_detail = _a152_rotate_aligned_latch_gate(
            rot, "MID", allow_enter=bool(reliable_current and abs_angle <= deadband)
        )
        if abs_angle <= deadband or bool(rot.get("done")):
            _a152_reset_rotation_consensus("MID angle inside deadband")
            return None
        if latch_on:
            _a152_reset_rotation_consensus("MID ROTATE suppressed by 12/18 aligned latch")
            print(f"[A152-MID-ROTATE-LATCH-SKIP] {latch_detail}; ordinary planner continues")
            return None
        if not bool(rot.get("ready")):
            return None

        consensus, detail, confirm_class = _a152_rotation_confirmation_policy("MID", rot)
        if consensus == "WAIT":
            rejudge_action = (
                "ROTATE_FALLBACK_CONFIRM_REJUDGE"
                if confirm_class == "FALLBACK" else "ROTATE_ANGLE_CONFIRM_REJUDGE"
            )
            return rejudge_action, f"MID {confirm_class.lower()} confirmation: {detail}"
        if consensus == "EXHAUSTED":
            print(f"[A152-MID-ROTATE-SKIP] confirmation failed after one fresh check; ordinary planner continues: {detail}")
            return None

        latch_on, latch_detail = _a152_rotate_aligned_latch_gate(rot, "MID_CONFIRMED", allow_enter=True)
        if latch_on:
            print(f"[A152-MID-ROTATE-LATCH-SKIP] {latch_detail}; confirmed small-angle ROTATE suppressed")
            return None

        exact = str(rot.get("exact_action") or "").upper()
        if exact not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
            return None
        auto_x_rotation_state["pending_rotation_phase"] = "MID"
        used = int(auto_x_rotation_state.get("mid_rotate_count", 0) or 0)
        return exact, (
            f"MID {exact} READY: angle={angle:+.1f}deg > deadband={deadband:.1f}deg; {detail}; "
            f"previous_mid_count={used} diagnostic-only/nonblocking; legacy MID gates ignored"
        )


    def _a110_commit_garment_motion(action: str) -> None:
        # Called only after a pending AUTO-X motion succeeded with serial send enabled.
        auto_x_ready_cycle["garment_motion_count"] = int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0) + 1
        count_now = int(auto_x_ready_cycle["garment_motion_count"])
        # a completed garment-changing physical action makes every previously cached
        # pose stale. Do not merely rely on motion-count mismatch; explicitly discard it.
        if isinstance(pose_rotation_recovery_cache.get("last_valid_plan"), dict):
            print(
                f"[POSE-ROT-CACHE-INVALIDATE-MOTION] action={action} motion={count_now}; "
                "discard last valid Pose because garment state changed"
            )
        pose_rotation_recovery_cache["last_valid_plan"] = None
        pose_rotation_recovery_cache["last_valid_motion_count"] = -1
        pose_rotation_recovery_cache["last_valid_inference_serial"] = -1
        pose_rotation_recovery_cache["last_valid_source"] = None
        pose_rotation_recovery_cache["consecutive_perception_failures"] = 0
        pose_rotation_recovery_cache["failure_motion_count"] = count_now
        pose_rotation_recovery_cache["retry_pending"] = False
        pose_rotation_recovery_cache["retry_fail_count"] = 0
        pose_rotation_recovery_cache["retry_motion_count"] = count_now
        pose_rotation_recovery_cache["retry_reason"] = "garment motion invalidated pose cache"
        pose_rotation_recovery_cache["retry_exhausted"] = False
        pose_rotation_recovery_cache["fresh_pose_retry_spent_motion_count"] = -1
        pose_rotation_recovery_cache["confirmation_budget_source"] = None
        pose_rotation_recovery_cache["confirmation_budget_inference_serial"] = -1
        if str(action) == "ACTION_STRUCTURAL_STATIC_PROBE":
            auto_x_static_probe_gate_memory["blocked_after_probe"] = True
            auto_x_static_probe_gate_memory["last_probe_motion_count"] = count_now
            auto_x_static_probe_gate_memory["regression_unlock_motion_count"] = None
            auto_x_static_probe_gate_memory["regression_reason"] = ""
            print(f"[B58-PROBE-GATE] LOCKED_AFTER_PROBE motion={count_now}; rearm requires a successful non-probe garment motion")
        else:
            diagnostic_actions = {
                "ACTION3_REPEAT_OUTWARD_PROBE", "ACTION3B_GRAY_PROBE",
                "ACTION_GRAY_AMBIGUITY_PROBE", "ACTION_NO_ACTION_STUCK_PROBE",
                "LATE_CCA_BLOCKER_PROBE",
            }
            if str(action) not in diagnostic_actions:
                if bool(auto_x_static_probe_gate_memory.get("blocked_after_probe", False)):
                    print(f"[B58-PROBE-GATE] REARMED by non-probe action={action} motion={count_now}")
                auto_x_static_probe_gate_memory["blocked_after_probe"] = False
                auto_x_static_probe_gate_memory["regression_unlock_motion_count"] = None
                auto_x_static_probe_gate_memory["regression_reason"] = ""
        auto_x_same_motion_rejudge_guard["motion_count"] = count_now
        auto_x_same_motion_rejudge_guard["count"] = 0
        print(f"[A143-REJUDGE-GUARD-RESET] physical garment motion={action} count={count_now} -> auto rejudge count=0")
        auto_x_ready_cycle["last_motion_action"] = str(action)
        auto_x_ready_cycle["last_motion_at"] = float(time.time())
        auto_x_ready_cycle["ready_locked_until_motion"] = False
        _set_ready_status_panel_data({})
        _set_latest_cca_sample_snapshot({})
        print(f"[A110-GARMENT-MOTION] committed action={action} count={count_now} ready_lock=RELEASED")
        if _a150_late_phase() == "STRONG_RECOVERY":
            recovery_noncount_actions = {
                "ACTION_STRUCTURAL_STATIC_PROBE", "ACTION3_REPEAT_OUTWARD_PROBE",
                "ACTION3B_GRAY_PROBE", "ACTION_GRAY_AMBIGUITY_PROBE",
                "ACTION_NO_ACTION_STUCK_PROBE", "ACTION_AMBIGUOUS_CIRCUMCENTER_NUDGE",
                "ACTION_POSE_RECOVERY_CIRCUMCENTER_NUDGE", "LATE_CCA_BLOCKER_PROBE",
            }
            if str(action) in recovery_noncount_actions:
                print(f"[A150-RECOVERY-MOTION-BLOCK] diagnostic/weak action={action} was not counted as a Strong Recovery motion")
            else:
                recovery_count = int(auto_x_late_cca_state.get("recovery_motion_count", 0) or 0) + 1
                auto_x_late_cca_state["recovery_motion_count"] = recovery_count
                recovery_limit = int(max(1, getattr(args, "auto_x_late_recovery_max_actions", 5)))
                print(f"[A150-RECOVERY-MOTION] action={action} recovery_motion={recovery_count}/{recovery_limit} total_motion={count_now}")
                if recovery_count >= recovery_limit:
                    print("[A150-RECOVERY-MOTION] maximum Strong Recovery actions reached; next fresh judgment enters LATE_VISIT_2")
        late_threshold = int(max(0, getattr(args, "auto_x_late_cca_after_motion_count", 10)))
        if bool(getattr(args, "auto_x_late_cca_enable", True)) and count_now == late_threshold:
            print(f"[A133-LATE-CCA-ARMED] real garment motion count reached {late_threshold}; the NEXT X fresh snapshot starts strict blocker priority 1->2->5->4->6->3")
            print(
                f"[A145-LATE-ACTION3-POLICY] normal_action3_workspace=True passive_hold={bool(getattr(args,'auto_x_late_main_passive_hold_enable',False))} "
                f"planning_try_both_arms=True legacy_forced_arm_flag={bool(getattr(args,'auto_x_late_allow_forced_arm',False))} "
                f"track_reopen=False main_max={int(getattr(args,'auto_x_late_track_max_main_count',1))} "
                f"probe_max={_a150_effective_probe_limit()}"
            )
            print(
                f"[A136-LATE-MOTION-POLICY] blocker_probe={float(getattr(args,'auto_x_late_probe_pull_mm',12.0)):.1f}mm "
                f"speed={float(getattr(args,'auto_x_late_probe_speed',0.22)):.2f} center_dot_min={float(getattr(args,'auto_x_late_probe_center_direction_dot_min',0.0)):+.2f}; "
                "Late center uses the frozen ordinary A90 ACTION1 circumcenter distance with no Late-only clip"
            )

    def _a110_snapshot_reason_uses_burst(reason: Any) -> bool:
        if not bool(getattr(args, "auto_x_snapshot_burst_median_enable", True)):
            return False
        r = str(reason or "").lower()
        return bool(
            ("auto x manual judge" in r)
            or ("key x manual judge" in r)
            or ("auto-x" in r and ("judge" in r or "judgment" in r or "rejudge" in r))
            or ("a142 automatic" in r)
        )

    def _auto_x_nearest_pose_keypoint_to_board(board_xy: Any) -> Dict[str, Any]:
        """A78 structural-shadow helper: nearest pose keypoint in board coordinates.

        This deliberately does not transform into a pose-axis coordinate system.  It
        only records which trained pose keypoint is closest to a long linear heatmap
        component, matching the user's desired criterion.
        """
        out = {"name": None, "index": None, "dist_mm": None}
        try:
            if not isinstance(latest_pose_rotation_plan, dict):
                return out
            kpts = latest_pose_rotation_plan.get("pose_keypoints_board", {})
            if not isinstance(kpts, dict) or not kpts:
                return out
            b = np.asarray(board_xy, dtype=np.float32).reshape(2)
            best = None
            for name, raw in kpts.items():
                try:
                    if raw is None:
                        continue
                    kv = np.asarray(raw, dtype=np.float32).reshape(-1)
                    if kv.size < 2 or not np.all(np.isfinite(kv[:2])):
                        continue
                    d = float(np.linalg.norm(kv[:2].astype(np.float32) - b))
                    idx = TSHIRT_POSE_KPT.get(str(name))
                    cand = (d, str(name), idx)
                    if best is None or cand[0] < best[0]:
                        best = cand
                except Exception:
                    continue
            if best is not None:
                out.update({"name": best[1], "index": best[2], "dist_mm": float(best[0])})
        except Exception:
            pass
        return out

    def _auto_x_pose_axis_frame_for_structural() -> Optional[Dict[str, Any]]:
        """A94 structural-shadow frame: pose neck-mid -> waist/bottom-mid axis.

        The user observed that nearest pose keypoint labels can jump between
        neck/armpit/shoulder across snapshots.  For stable structural-shadow memory,
        use the almost-fixed garment pose axis instead: record a component center by
        signed distance from this axis and projection along it.
        """
        try:
            plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if not isinstance(plan, dict):
                return None
            neck = plan.get("neck_board_xy")
            waist = plan.get("waist_board_xy")
            if neck is None or waist is None:
                neck = _pose_midpoint_from_kpts(plan, ["neck_left", "neck_right"])
                waist = _pose_midpoint_from_kpts(plan, ["waist_left", "waist_right"])
            if neck is None or waist is None:
                return None
            n = np.asarray(neck, dtype=np.float32).reshape(2)
            h = np.asarray(waist, dtype=np.float32).reshape(2)
            v = h - n
            L = float(np.linalg.norm(v))
            if not np.isfinite(L) or L < 30.0:
                return None
            u = (v / L).astype(np.float32)
            normal = np.array([-float(u[1]), float(u[0])], dtype=np.float32)
            return {"neck": n, "hem": h, "axis_u": u, "normal_u": normal, "axis_len_mm": L}
        except Exception:
            return None

    def _auto_x_structural_signature_for_board_point(board_xy: Any) -> Optional[Dict[str, Any]]:
        """Return pose-axis signature for a wrinkle candidate center.

        Signature values:
        - signed_axis_dist_mm: signed perpendicular distance from neck->waist axis
        - axis_proj_mm: projection along neck->waist axis, from the neck midpoint
        - axis_len_mm: pose axis length used for diagnostics
        """
        try:
            frame = _auto_x_pose_axis_frame_for_structural()
            if not isinstance(frame, dict):
                return None
            p = np.asarray(board_xy, dtype=np.float32).reshape(2)
            neck = np.asarray(frame["neck"], dtype=np.float32).reshape(2)
            u = np.asarray(frame["axis_u"], dtype=np.float32).reshape(2)
            nrm = np.asarray(frame["normal_u"], dtype=np.float32).reshape(2)
            rel = p - neck
            signed_dist = float(np.dot(rel, nrm))
            proj = float(np.dot(rel, u))
            return {
                "axis_valid": True,
                "signed_axis_dist_mm": signed_dist,
                "abs_axis_dist_mm": abs(signed_dist),
                "axis_proj_mm": proj,
                "axis_len_mm": float(frame.get("axis_len_mm", 0.0)),
            }
        except Exception:
            return None

    def _auto_x_structural_signature_for_component(comp: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Build full structural-memory signature from a heatmap component dict."""
        try:
            center = None
            for key in ("center_board", "component_center_board", "problem_board", "problem_board_xy", "wrinkle_problem_board_xy"):
                raw = comp.get(key) if isinstance(comp, dict) else None
                if raw is not None:
                    center = raw
                    break
            if center is None:
                return None
            axis_sig = _auto_x_structural_signature_for_board_point(center)
            if not isinstance(axis_sig, dict):
                return None
            length = float(comp.get("len_mm", comp.get("major_len_mm", 0.0)) or 0.0)
            ratio = float(comp.get("ratio", comp.get("major_ratio", 1.0)) or 1.0)
            if length <= 0.0 or not np.isfinite(length):
                return None
            if ratio <= 0.0 or not np.isfinite(ratio):
                ratio = 1.0
            out = dict(axis_sig)
            out.update({
                "len_mm": float(length),
                "ratio": float(ratio),
                "angle_deg": comp.get("angle_deg"),
                "center_board": [float(np.asarray(center, dtype=np.float32).reshape(2)[0]),
                                 float(np.asarray(center, dtype=np.float32).reshape(2)[1])],
            })
            return out
        except Exception:
            return None

    def _auto_x_repeat_action3_signature_from_mapping(data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """A102 repeat-ACTION3 signature: area, length, and pose-relative location only.

        Angle and aspect ratio are intentionally not used for either matching or
        post-probe confirmation, per the requested diagnostic policy.
        """
        try:
            if not isinstance(data, dict):
                return None
            length = float(data.get("major_len_mm", data.get("len_mm", 0.0)) or 0.0)
            area = float(data.get("area_px", 0.0) or 0.0)
            dist = data.get("axis_signed_dist_mm", data.get("signed_axis_dist_mm"))
            proj = data.get("axis_proj_mm")
            if length <= 0.0 or dist is None or proj is None:
                return None
            return {
                "len_mm": float(length),
                "area_px": float(max(0.0, area)),
                "signed_axis_dist_mm": float(dist),
                "axis_proj_mm": float(proj),
                "center_board": data.get("component_center_board", data.get("center_board", data.get("wrinkle_problem_board_xy"))),
            }
        except Exception:
            return None

    def _auto_x_repeat_action3_match_metrics(sig: Dict[str, Any], track: Dict[str, Any], *, loose: bool = False, position_only: bool = False) -> Optional[Dict[str, float]]:
        """Match repeat-ACTION3 history without angle or aspect ratio."""
        try:
            ref_len = track.get("baseline_len_mm")
            ref_dist = track.get("signed_axis_dist_mm")
            ref_proj = track.get("axis_proj_mm")
            if ref_dist is None or ref_proj is None:
                return None
            dist_delta = abs(float(sig.get("signed_axis_dist_mm", 0.0)) - float(ref_dist))
            proj_delta = abs(float(sig.get("axis_proj_mm", 0.0)) - float(ref_proj))
            len_rel = 0.0
            if ref_len is not None and float(ref_len) > 0.0:
                len_rel = abs(float(sig.get("len_mm", 0.0)) - float(ref_len)) / max(abs(float(ref_len)), 1.0)
            len_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_match_len_rel_tol", 0.30)))
            dist_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_match_axis_distance_tol_mm", 30.0)))
            proj_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_match_axis_projection_tol_mm", 80.0)))
            if loose:
                len_tol = max(len_tol, 0.60)
                dist_tol = max(dist_tol, 45.0)
                proj_tol = max(proj_tol, 110.0)
            len_ok = bool(position_only or ref_len is None or float(ref_len) <= 0.0 or len_rel <= len_tol)
            if len_ok and dist_delta <= dist_tol and proj_delta <= proj_tol:
                return {
                    "score": float((0.0 if position_only else len_rel) + 0.025 * dist_delta + 0.008 * proj_delta),
                    "rel_len": float(len_rel),
                    "dist_delta_mm": float(dist_delta),
                    "proj_delta_mm": float(proj_delta),
                }
        except Exception:
            return None
        return None

    def _auto_x_repeat_action3_find_track(sig: Dict[str, Any], *, loose: bool = False, position_only: bool = False) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, float]]]:
        best = None
        try:
            for tr in list(auto_x_structural_line_memory.get("repeat_action3_tracks", [])):
                if bool(tr.get("confirmed_structure", False)):
                    continue
                mm = _auto_x_repeat_action3_match_metrics(sig, tr, loose=loose, position_only=position_only)
                if mm is None:
                    continue
                if best is None or float(mm["score"]) < float(best[1]["score"]):
                    best = (tr, mm)
        except Exception:
            return None, None
        return best if best is not None else (None, None)

    def _auto_x_repeat_action3_current_cycle_block_track_for_component(comp: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Return an ambiguous repeat-A3 track that blocks normal ACTION3 only in this X cycle.

        After a 20mm repeat probe is judged AMBIGUOUS, the current observation is
        used as the new baseline, but the same component must not immediately run
        a normal ACTION3 in the very same observe generation.  The block expires
        automatically on the next X because observe_generation increments.
        """
        try:
            sig0 = _auto_x_structural_signature_for_component(comp)
            if not isinstance(sig0, dict):
                return None
            sig = _auto_x_repeat_action3_signature_from_mapping({
                "major_len_mm": sig0.get("len_mm"),
                "area_px": comp.get("area_px", 0.0),
                "axis_signed_dist_mm": sig0.get("signed_axis_dist_mm"),
                "axis_proj_mm": sig0.get("axis_proj_mm"),
                "component_center_board": sig0.get("center_board"),
            })
            if not isinstance(sig, dict):
                return None
            generation = int(auto_x_structural_line_memory.get("observe_generation", 0) or 0)
            best = None
            for tr in list(auto_x_structural_line_memory.get("repeat_action3_tracks", [])):
                if bool(tr.get("confirmed_structure", False)):
                    continue
                if int(tr.get("block_normal_action3_generation", -1) or -1) != generation:
                    continue
                position_only = bool(tr.get("baseline_len_mm") is None or float(tr.get("baseline_len_mm", 0.0) or 0.0) <= 0.0)
                mm = _auto_x_repeat_action3_match_metrics(sig, tr, loose=False, position_only=position_only)
                if mm is None:
                    continue
                if best is None or float(mm["score"]) < float(best[1]["score"]):
                    best = (tr, mm)
            return best[0] if best is not None else None
        except Exception:
            return None

    def _auto_x_repeat_action3_block_normal_for_current_cycle(track: Dict[str, Any], reason: str) -> None:
        generation = int(auto_x_structural_line_memory.get("observe_generation", 0) or 0)
        track["block_normal_action3_generation"] = generation
        track["block_normal_action3_reason"] = str(reason)
        track["block_normal_action3_at"] = float(time.time())

    def _auto_x_repeat_action3_probe_track_for_component(comp: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Return a history track when this would be the second/later similar ACTION3."""
        try:
            if not bool(getattr(args, "auto_x_repeat_action3_probe_enabled", True)):
                return None
            sig0 = _auto_x_structural_signature_for_component(comp)
            if not isinstance(sig0, dict):
                return None
            sig = _auto_x_repeat_action3_signature_from_mapping({
                "major_len_mm": sig0.get("len_mm"),
                "area_px": comp.get("area_px", 0.0),
                "axis_signed_dist_mm": sig0.get("signed_axis_dist_mm"),
                "axis_proj_mm": sig0.get("axis_proj_mm"),
                "component_center_board": sig0.get("center_board"),
            })
            if not isinstance(sig, dict):
                return None
            tr, _ = _auto_x_repeat_action3_find_track(sig)
            if not isinstance(tr, dict):
                return None
            trigger = int(max(2, getattr(args, "auto_x_repeat_action3_trigger_count", 2)))
            previous_normal = int(tr.get("normal_action3_count", 0) or 0)
            force_next = bool(tr.get("force_probe_on_next_match", False))
            if force_next or previous_normal + 1 >= trigger:
                return tr
        except Exception:
            return None
        return None

    def _auto_x_repeat_action3_commit_normal_execution(ex: Dict[str, Any]) -> None:
        """Remember an actually selected/executed normal ACTION3 occurrence."""
        try:
            sig = _auto_x_repeat_action3_signature_from_mapping(ex)
            if not isinstance(sig, dict):
                print("[A102-REPEAT-A3] normal ACTION3 not recorded: missing length/pose-relative signature")
                return
            tr, _ = _auto_x_repeat_action3_find_track(sig)
            now = float(time.time())
            if not isinstance(tr, dict):
                tr = {
                    "id": int(auto_x_structural_line_memory.get("next_repeat_action3_id", 1)),
                    "created_at": now,
                    "normal_action3_count": 0,
                    "probe_count": 0,
                    "confirmed_structure": False,
                }
                auto_x_structural_line_memory["next_repeat_action3_id"] = int(tr["id"]) + 1
                auto_x_structural_line_memory.setdefault("repeat_action3_tracks", []).append(tr)
            tr["normal_action3_count"] = int(tr.get("normal_action3_count", 0) or 0) + 1
            tr["baseline_len_mm"] = float(sig["len_mm"])
            tr["baseline_area_px"] = float(sig.get("area_px", 0.0))
            tr["signed_axis_dist_mm"] = float(sig["signed_axis_dist_mm"])
            tr["axis_proj_mm"] = float(sig["axis_proj_mm"])
            tr["baseline_valid"] = True
            tr["force_probe_on_next_match"] = True
            tr["last_normal_action3_at"] = now
            print(f"[A102-REPEAT-A3] track#{tr.get('id')} normal ACTION3 count={tr.get('normal_action3_count')} baseline area={tr.get('baseline_area_px',0.0):.0f}px len={tr.get('baseline_len_mm',0.0):.1f}mm axis=({tr.get('signed_axis_dist_mm',0.0):+.1f},{tr.get('axis_proj_mm',0.0):.1f})")
        except Exception as e:
            print(f"[A102-REPEAT-A3-WARN] failed to record normal ACTION3: {repr(e)}")

    def _auto_x_repeat_action3_reset_baseline(track: Dict[str, Any], sig: Dict[str, Any], reason: str) -> None:
        track["baseline_len_mm"] = float(sig.get("len_mm", 0.0) or 0.0)
        track["baseline_area_px"] = float(sig.get("area_px", 0.0) or 0.0)
        track["signed_axis_dist_mm"] = float(sig.get("signed_axis_dist_mm", 0.0) or 0.0)
        track["axis_proj_mm"] = float(sig.get("axis_proj_mm", 0.0) or 0.0)
        track["baseline_valid"] = True
        track["force_probe_on_next_match"] = True
        track["last_reset_at"] = float(time.time())
        track["last_reset_reason"] = str(reason)

    def _auto_x_repeat_action3_confirm_structure(track: Dict[str, Any], sig: Dict[str, Any], comp: Dict[str, Any], reason: str) -> None:
        """Add an ignored structural line that matches by length+pose location, not ratio."""
        now = float(time.time())
        line = {
            "id": int(auto_x_structural_line_memory.get("next_id", 1)),
            "first_seen_at": now,
            "last_seen_at": now,
            "last_observe_generation": int(auto_x_structural_line_memory.get("observe_generation", 0) or 0),
            "seen_count": int(max(2, getattr(args, "auto_x_structural_candidate_seen_count", 2))),
            "consecutive_seen_count": int(max(2, getattr(args, "auto_x_structural_candidate_seen_count", 2))),
            "stable_count": 1,
            "probe_count": int(track.get("probe_count", 0) or 0),
            "no_response_count": 1,
            "ignored": True,
            "ignored_at": now,
            "ignored_reason": str(reason),
            "repeat_probe_confirmed": True,
            "last_len_mm": float(sig.get("len_mm", 0.0) or 0.0),
            "mean_len_mm": float(sig.get("len_mm", 0.0) or 0.0),
            "last_ratio": float(comp.get("ratio", comp.get("major_ratio", 1.0)) or 1.0),
            "mean_ratio": float(comp.get("ratio", comp.get("major_ratio", 1.0)) or 1.0),
            "signed_axis_dist_mm": float(sig.get("signed_axis_dist_mm", 0.0) or 0.0),
            "abs_axis_dist_mm": abs(float(sig.get("signed_axis_dist_mm", 0.0) or 0.0)),
            "axis_proj_mm": float(sig.get("axis_proj_mm", 0.0) or 0.0),
            "axis_len_mm": 0.0,
            "last_angle_deg": None,
            "last_area_px": float(sig.get("area_px", 0.0) or 0.0),
            "last_center_board": sig.get("center_board"),
        }
        auto_x_structural_line_memory["next_id"] = int(line["id"]) + 1
        auto_x_structural_line_memory.setdefault("lines", []).append(line)
        track["confirmed_structure"] = True
        track["force_probe_on_next_match"] = False
        track["confirmed_at"] = now
        print(f"[A102-REPEAT-A3-CONFIRM] track#{track.get('id')} -> structural ignored line#{line.get('id')}: {reason}")

    def _auto_x_process_repeat_action3_probe_result(components: List[Dict[str, Any]]) -> None:
        """Evaluate the 20mm one-arm diagnostic on the next X.

        Only area, length, and pose-relative location are compared.  If the result
        is not clearly unchanged, it is treated as ambiguous: the current state
        becomes the new baseline, and a future similar ACTION3 decision triggers
        another one-arm probe instead of comparing against an old observation.
        """
        probe = auto_x_structural_line_memory.get("last_repeat_action3_probe")
        if not isinstance(probe, dict) or bool(probe.get("resolved", False)):
            return
        track_id = probe.get("track_id")
        track = next((t for t in auto_x_structural_line_memory.get("repeat_action3_tracks", []) if t.get("id") == track_id), None)
        if not isinstance(track, dict):
            probe["resolved"] = True
            print(f"[A102-REPEAT-A3-PROBE] track#{track_id} missing; result discarded")
            return
        base_sig = {
            "len_mm": float(probe.get("len_mm", 0.0) or 0.0),
            "area_px": float(probe.get("area_px", 0.0) or 0.0),
            "signed_axis_dist_mm": float(probe.get("signed_axis_dist_mm", 0.0) or 0.0),
            "axis_proj_mm": float(probe.get("axis_proj_mm", 0.0) or 0.0),
        }
        best = None
        for position_only in (False, True):
            for comp in components[:16]:
                cs0 = _auto_x_structural_signature_for_component(comp)
                if not isinstance(cs0, dict):
                    continue
                cs = _auto_x_repeat_action3_signature_from_mapping({
                    "major_len_mm": cs0.get("len_mm"),
                    "area_px": comp.get("area_px", 0.0),
                    "axis_signed_dist_mm": cs0.get("signed_axis_dist_mm"),
                    "axis_proj_mm": cs0.get("axis_proj_mm"),
                    "component_center_board": cs0.get("center_board"),
                })
                if not isinstance(cs, dict):
                    continue
                tmp_track = {
                    "baseline_len_mm": base_sig["len_mm"],
                    "signed_axis_dist_mm": base_sig["signed_axis_dist_mm"],
                    "axis_proj_mm": base_sig["axis_proj_mm"],
                }
                mm = _auto_x_repeat_action3_match_metrics(cs, tmp_track, loose=True, position_only=position_only)
                if mm is None:
                    continue
                if best is None or float(mm["score"]) < float(best[2]["score"]):
                    best = (comp, cs, mm)
            if best is not None:
                break
        if best is None:
            track["baseline_valid"] = False
            # Do not compare a future reappearance against the old pre-probe
            # length/area. Keep only the pose-relative region anchor; the next
            # ACTION3 candidate supplies a fresh baseline immediately before its probe.
            track["baseline_len_mm"] = None
            track["baseline_area_px"] = None
            track["force_probe_on_next_match"] = True
            track["last_ambiguous_reason"] = "no comparable line in current pose-relative region"
            _auto_x_repeat_action3_block_normal_for_current_cycle(track, track["last_ambiguous_reason"])
            probe["resolved"] = True
            print(f"[A104-REPEAT-A3-AMBIGUOUS-BLOCK] track#{track_id}: no comparable current line; old measurement is not reused. Normal ACTION3 in this X generation is blocked for the remembered pose region. A later X reappearance becomes the fresh baseline and runs the one-arm probe.")
            return
        comp, cur_sig, mm = best
        base_area = float(base_sig.get("area_px", 0.0) or 0.0)
        cur_area = float(cur_sig.get("area_px", 0.0) or 0.0)
        area_rel = float("inf") if base_area <= 0.0 or cur_area <= 0.0 else abs(cur_area - base_area) / max(base_area, 1.0)
        len_rel = abs(float(cur_sig["len_mm"]) - float(base_sig["len_mm"])) / max(float(base_sig["len_mm"]), 1.0)
        dist_delta = abs(float(cur_sig["signed_axis_dist_mm"]) - float(base_sig["signed_axis_dist_mm"]))
        proj_delta = abs(float(cur_sig["axis_proj_mm"]) - float(base_sig["axis_proj_mm"]))
        area_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_confirm_area_rel_tol", 0.20)))
        len_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_confirm_len_rel_tol", 0.20)))
        dist_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_confirm_axis_distance_tol_mm", 20.0)))
        proj_tol = float(max(0.0, getattr(args, "auto_x_repeat_action3_confirm_axis_projection_tol_mm", 70.0)))
        unchanged = bool(area_rel <= area_tol and len_rel <= len_tol and dist_delta <= dist_tol and proj_delta <= proj_tol)
        track["probe_count"] = int(track.get("probe_count", 0) or 0) + 1
        if unchanged:
            reason = (f"repeat-A3 20mm probe no-response: area {base_area:.0f}->{cur_area:.0f}px rel={area_rel:.2f}<={area_tol:.2f}, "
                      f"len {base_sig['len_mm']:.1f}->{cur_sig['len_mm']:.1f}mm rel={len_rel:.2f}<={len_tol:.2f}, "
                      f"axis_dist Δ={dist_delta:.1f}<={dist_tol:.1f}mm, proj Δ={proj_delta:.1f}<={proj_tol:.1f}mm")
            _auto_x_repeat_action3_confirm_structure(track, cur_sig, comp, reason)
        else:
            reason = (f"ambiguous reset after repeat-A3 probe: area_rel={area_rel:.2f}, len_rel={len_rel:.2f}, "
                      f"axis_dist_delta={dist_delta:.1f}mm, proj_delta={proj_delta:.1f}mm")
            _auto_x_repeat_action3_reset_baseline(track, cur_sig, reason)
            _auto_x_repeat_action3_block_normal_for_current_cycle(track, reason)
            print(f"[A104-REPEAT-A3-AMBIGUOUS-BLOCK] track#{track_id}: {reason}; current area/length/pose-relative location is now the new baseline. This same X generation cannot run normal ACTION3 on the matched region. A later similar ACTION3 decision will run the one-arm probe again.")
        probe["resolved"] = True

    def _auto_x_structural_match_metrics(sig: Dict[str, Any], line: Dict[str, Any], *, action_probe: bool = False) -> Optional[Dict[str, float]]:
        """Compare a current component signature to a remembered structure line."""
        try:
            length = float(sig.get("len_mm", 0.0) or 0.0)
            ratio = float(sig.get("ratio", 1.0) or 1.0)
            ref_len = float(line.get("last_len_mm", line.get("mean_len_mm", length)) or length)
            ref_ratio = float(line.get("last_ratio", line.get("mean_ratio", ratio)) or ratio)
            if length <= 0.0 or ref_len <= 0.0:
                return None
            rel_len = abs(length - ref_len) / max(abs(ref_len), 1.0)
            repeat_confirmed = bool(line.get("repeat_probe_confirmed", False))
            rel_ratio = 0.0 if repeat_confirmed else abs(ratio - ref_ratio) / max(abs(ref_ratio), 0.50)
            dist_delta = abs(float(sig.get("signed_axis_dist_mm", 0.0)) - float(line.get("signed_axis_dist_mm", 0.0)))
            proj_delta = abs(float(sig.get("axis_proj_mm", 0.0)) - float(line.get("axis_proj_mm", 0.0)))
            if action_probe:
                len_tol = float(max(0.0, getattr(args, "auto_x_structural_action3_len_rel_tol", 0.18)))
                ratio_tol = float(max(0.0, getattr(args, "auto_x_structural_action3_ratio_rel_tol", 0.35)))
                dist_tol = float(max(0.0, getattr(args, "auto_x_structural_action3_axis_distance_tol_mm", 20.0)))
                proj_tol = float(max(0.0, getattr(args, "auto_x_structural_action3_axis_projection_tol_mm", 70.0)))
            else:
                len_tol = float(max(0.0, getattr(args, "auto_x_structural_len_rel_tol", 0.25)))
                ratio_tol = float(max(0.0, getattr(args, "auto_x_structural_ratio_rel_tol", 0.35)))
                dist_tol = float(max(0.0, getattr(args, "auto_x_structural_axis_distance_tol_mm", 20.0)))
                proj_tol = float(max(0.0, getattr(args, "auto_x_structural_axis_projection_tol_mm", 70.0)))
            if rel_len <= len_tol and rel_ratio <= ratio_tol and dist_delta <= dist_tol and proj_delta <= proj_tol:
                score = rel_len + 0.60 * rel_ratio + 0.025 * dist_delta + 0.008 * proj_delta
                return {
                    "score": float(score),
                    "rel_len": float(rel_len),
                    "rel_ratio": float(rel_ratio),
                    "dist_delta_mm": float(dist_delta),
                    "proj_delta_mm": float(proj_delta),
                }
        except Exception:
            return None
        return None

    def _auto_x_structural_status_for_component(comp: Dict[str, Any]) -> Dict[str, Any]:
        """Return current structural-shadow memory status for a component."""
        out = {"status": "none", "line": None, "line_id": None, "reason": "no match"}
        try:
            if not bool(getattr(args, "auto_x_structural_shadow_memory", True)):
                out["reason"] = "memory disabled"
                return out
            sig = _auto_x_structural_signature_for_component(comp)
            if not isinstance(sig, dict):
                out["reason"] = "missing pose-axis signature"
                return out
            best = None
            for line in list(auto_x_structural_line_memory.get("lines", [])):
                if bool(line.get("a133_late_confirmed", False)):
                    ref_len = float(line.get("last_len_mm", line.get("mean_len_mm", 0.0)) or 0.0)
                    ref_area = float(line.get("last_area_px", 0.0) or 0.0)
                    cur_len = float(sig.get("len_mm", 0.0) or 0.0)
                    cur_area = float(comp.get("area_px", 0.0) or 0.0)
                    ref_dist = line.get("signed_axis_dist_mm")
                    ref_proj = line.get("axis_proj_mm")
                    cur_dist = sig.get("signed_axis_dist_mm")
                    cur_proj = sig.get("axis_proj_mm")
                    if ref_len <= 0.0 or ref_dist is None or ref_proj is None or cur_dist is None or cur_proj is None:
                        mm = None
                    else:
                        rel_len = abs(cur_len - ref_len) / max(ref_len, 1.0)
                        rel_area = (abs(cur_area - ref_area) / max(ref_area, 1.0)) if ref_area > 0.0 else 0.0
                        dd = abs(float(cur_dist) - float(ref_dist))
                        dp = abs(float(cur_proj) - float(ref_proj))
                        len_tol = max(0.30, float(getattr(args, "auto_x_late_no_response_ratio", 0.15)) * 2.0)
                        area_tol = max(0.35, float(getattr(args, "auto_x_late_no_response_ratio", 0.15)) * 2.5)
                        dist_tol = float(max(1.0, getattr(args, "auto_x_late_match_axis_distance_tol_mm", 25.0)))
                        proj_tol = float(max(1.0, getattr(args, "auto_x_late_match_axis_projection_tol_mm", 75.0)))
                        mm = None
                        if rel_len <= len_tol and rel_area <= area_tol and dd <= dist_tol and dp <= proj_tol:
                            mm = {
                                "score": float(rel_len + 0.8 * rel_area + 0.025 * dd + 0.008 * dp),
                                "rel_len": float(rel_len),
                                "rel_ratio": float(rel_area),  # retained field name for common diagnostic text
                                "dist_delta_mm": float(dd),
                                "proj_delta_mm": float(dp),
                            }
                else:
                    mm = _auto_x_structural_match_metrics(sig, line, action_probe=False)
                if mm is None:
                    continue
                if best is None or float(mm["score"]) < float(best[0]["score"]):
                    best = (mm, line)
            if best is None:
                return out
            mm, line = best
            consecutive = int(line.get("consecutive_seen_count", line.get("seen_count", 0)) or 0)
            need = int(max(1, getattr(args, "auto_x_structural_candidate_seen_count", 2)))
            status = "ignored" if bool(line.get("ignored", False)) else ("candidate" if consecutive >= need else "tracked")
            out.update({
                "status": status,
                "line": line,
                "line_id": line.get("id"),
                "signature": sig,
                "reason": (f"axis-match d={float(sig.get('signed_axis_dist_mm',0.0)):+.1f}mm "
                           f"proj={float(sig.get('axis_proj_mm',0.0)):.1f}mm "
                           f"rel_len={mm['rel_len']:.2f} rel_ratio={mm['rel_ratio']:.2f} "
                           f"dd={mm['dist_delta_mm']:.1f} dp={mm['proj_delta_mm']:.1f} "
                           f"consec={consecutive}/{need}")
            })
        except Exception as e:
            out["reason"] = f"error: {repr(e)}"
        return out

    def _auto_x_update_structural_memory_from_components(components: List[Dict[str, Any]], source: str = "observe") -> None:
        """Update A94 structural-shadow memory from current linear-ish heatmap components.

        Candidate tracking now starts after any real AUTO-X motion count, not after
        ACTION2 count.  A component is remembered by pose-axis distance/projection,
        length, and aspect ratio.  No 60mm minimum length gate is applied here.
        """
        try:
            if not bool(getattr(args, "auto_x_structural_shadow_memory", True)):
                return
            motion_count = int(auto_x_structural_line_memory.get("motion_count", 0) or 0)
            start_count = int(max(0, getattr(args, "auto_x_structural_start_after_motion_count", 2)))
            if motion_count < start_count:
                return
            now = float(time.time())
            generation = int(auto_x_structural_line_memory.get("observe_generation", 0) or 0) + 1
            auto_x_structural_line_memory["observe_generation"] = generation
            max_lines = int(max(3, getattr(args, "auto_x_structural_max_lines", 18)))
            candidate_seen = int(max(1, getattr(args, "auto_x_structural_candidate_seen_count", 2)))
            updated_ids = set()
            for comp in components[:16]:
                try:
                    sig = _auto_x_structural_signature_for_component(comp)
                    if not isinstance(sig, dict):
                        continue
                    best = None
                    for line in auto_x_structural_line_memory.get("lines", []):
                        if line.get("id") in updated_ids:
                            continue
                        mm = _auto_x_structural_match_metrics(sig, line, action_probe=False)
                        if mm is None:
                            continue
                        if best is None or float(mm["score"]) < float(best[0]["score"]):
                            best = (mm, line)
                    if best is None:
                        line = {
                            "id": int(auto_x_structural_line_memory.get("next_id", 1)),
                            "first_seen_at": now,
                            "last_seen_at": now,
                            "last_observe_generation": generation,
                            "seen_count": 1,
                            "consecutive_seen_count": 1,
                            "stable_count": 0,
                            "probe_count": 0,
                            "no_response_count": 0,
                            "ignored": False,
                            "last_len_mm": float(sig["len_mm"]),
                            "mean_len_mm": float(sig["len_mm"]),
                            "last_ratio": float(sig["ratio"]),
                            "mean_ratio": float(sig["ratio"]),
                            "signed_axis_dist_mm": float(sig["signed_axis_dist_mm"]),
                            "abs_axis_dist_mm": float(sig["abs_axis_dist_mm"]),
                            "axis_proj_mm": float(sig["axis_proj_mm"]),
                            "axis_len_mm": float(sig.get("axis_len_mm", 0.0)),
                            "last_angle_deg": sig.get("angle_deg"),
                            "last_area_px": float(comp.get("area_px", 0.0) or 0.0),
                            "last_center_board": sig.get("center_board"),
                        }
                        auto_x_structural_line_memory["next_id"] = int(auto_x_structural_line_memory.get("next_id", 1)) + 1
                        auto_x_structural_line_memory.setdefault("lines", []).append(line)
                        updated_ids.add(line["id"])
                    else:
                        mm, line = best
                        prev_mean_len = float(line.get("mean_len_mm", sig["len_mm"]) or sig["len_mm"])
                        prev_mean_ratio = float(line.get("mean_ratio", sig["ratio"]) or sig["ratio"])
                        prev_gen = int(line.get("last_observe_generation", -999999) or -999999)
                        consecutive = int(line.get("consecutive_seen_count", 0) or 0) + 1 if prev_gen == generation - 1 else 1
                        line["seen_count"] = int(line.get("seen_count", 0)) + 1
                        line["consecutive_seen_count"] = int(consecutive)
                        line["stable_count"] = int(line.get("stable_count", 0)) + 1
                        line["last_seen_at"] = now
                        line["last_observe_generation"] = generation
                        line["last_len_mm"] = float(sig["len_mm"])
                        line["mean_len_mm"] = float(0.70 * prev_mean_len + 0.30 * float(sig["len_mm"]))
                        line["last_ratio"] = float(sig["ratio"])
                        line["mean_ratio"] = float(0.70 * prev_mean_ratio + 0.30 * float(sig["ratio"]))
                        line["signed_axis_dist_mm"] = float(sig["signed_axis_dist_mm"])
                        line["abs_axis_dist_mm"] = float(sig["abs_axis_dist_mm"])
                        line["axis_proj_mm"] = float(sig["axis_proj_mm"])
                        line["axis_len_mm"] = float(sig.get("axis_len_mm", 0.0))
                        line["last_angle_deg"] = sig.get("angle_deg")
                        line["last_area_px"] = float(comp.get("area_px", 0.0) or 0.0)
                        line["last_center_board"] = sig.get("center_board")
                        updated_ids.add(line.get("id"))
                except Exception:
                    continue
            _auto_x_process_repeat_action3_probe_result(components)

            probe = auto_x_structural_line_memory.get("last_action3_probe")
            if isinstance(probe, dict) and not bool(probe.get("resolved", False)):
                if probe.get("signed_axis_dist_mm") is None or probe.get("axis_proj_mm") is None or float(probe.get("len_mm", 0.0) or 0.0) <= 0.0:
                    probe["resolved"] = True
                    print("[A94-STRUCTURAL-PROBE] skipped confirmation: probed ACTION3 candidate had no valid pose-axis signature")
                    return
                psig = {
                    "len_mm": float(probe.get("len_mm", 0.0) or 0.0),
                    "ratio": float(probe.get("ratio", 1.0) or 1.0),
                    "signed_axis_dist_mm": float(probe.get("signed_axis_dist_mm")),
                    "abs_axis_dist_mm": abs(float(probe.get("signed_axis_dist_mm"))),
                    "axis_proj_mm": float(probe.get("axis_proj_mm")),
                }
                matched = None
                for comp in components[:16]:
                    sig = _auto_x_structural_signature_for_component(comp)
                    if not isinstance(sig, dict):
                        continue
                    tmp_line = {
                        "last_len_mm": psig["len_mm"],
                        "last_ratio": psig["ratio"],
                        "signed_axis_dist_mm": psig["signed_axis_dist_mm"],
                        "axis_proj_mm": psig["axis_proj_mm"],
                    }
                    mm = _auto_x_structural_match_metrics(sig, tmp_line, action_probe=True)
                    if mm is None:
                        continue
                    if matched is None or float(mm["score"]) < float(matched[1]["score"]):
                        matched = (sig, mm)
                if matched is not None:
                    line_id = probe.get("line_id")
                    target_line = None
                    for line in auto_x_structural_line_memory.get("lines", []):
                        if line.get("id") == line_id:
                            target_line = line
                            break
                    if target_line is None:
                        best_line = None
                        for line in auto_x_structural_line_memory.get("lines", []):
                            mm = _auto_x_structural_match_metrics(psig, line, action_probe=True)
                            if mm is None:
                                continue
                            if best_line is None or float(mm["score"]) < float(best_line[0]["score"]):
                                best_line = (mm, line)
                        if best_line is not None:
                            target_line = best_line[1]
                    if target_line is not None:
                        target_line["probe_count"] = int(target_line.get("probe_count", 0)) + 1
                        target_line["no_response_count"] = int(target_line.get("no_response_count", 0)) + 1
                        target_line["ignored"] = True
                        target_line["ignored_at"] = now
                        target_line["ignored_reason"] = (f"ACTION3 probe no-response: axis_dist {psig['signed_axis_dist_mm']:+.1f}->{matched[0]['signed_axis_dist_mm']:+.1f}mm, "
                                                           f"proj {psig['axis_proj_mm']:.1f}->{matched[0]['axis_proj_mm']:.1f}mm, "
                                                           f"len {psig['len_mm']:.1f}->{matched[0]['len_mm']:.1f}mm, "
                                                           f"ratio {psig['ratio']:.2f}->{matched[0]['ratio']:.2f}")
                        print(f"[A94-STRUCTURAL-CONFIRM] line#{target_line.get('id')} ignored as garment structure: {target_line.get('ignored_reason')}")
                    probe["resolved"] = True
                else:
                    probe["resolved"] = True
                    print(f"[A94-STRUCTURAL-PROBE] ACTION3 changed candidate enough; keep treating similar lines as wrinkles. axis_dist={psig['signed_axis_dist_mm']:+.1f} len={psig['len_mm']:.1f} ratio={psig['ratio']:.2f}")
            lines = list(auto_x_structural_line_memory.get("lines", []))
            lines.sort(key=lambda z: (bool(z.get("ignored", False)), int(z.get("consecutive_seen_count", 0)), float(z.get("last_seen_at", 0.0))), reverse=True)
            auto_x_structural_line_memory["lines"] = lines[:max_lines]
            if updated_ids:
                cand_n = sum(1 for line in auto_x_structural_line_memory.get("lines", []) if int(line.get("consecutive_seen_count",0)) >= candidate_seen and not bool(line.get("ignored",False)))
                ign_n = sum(1 for line in auto_x_structural_line_memory.get("lines", []) if bool(line.get("ignored",False)))
                print(f"[A94-STRUCTURAL-MEM] {source}: motion_count={motion_count}, updated={len(updated_ids)}, candidates={cand_n}, ignored={ign_n}")
        except Exception as e:
            print(f"[A94-STRUCTURAL-MEM-WARN] {repr(e)}")

    def _auto_x_action2_effective_pull_mm(base_pull_mm: float) -> Tuple[float, str]:
        """A79: choose ACTION2 pull distance, reducing it after mask-area plateau."""
        try:
            base = max(0.0, float(base_pull_mm))
            if not bool(getattr(args, "auto_x_action2_plateau_reduce_enabled", True)):
                return base, "plateau reduction disabled"
            plateau_count = int(auto_x_action2_plateau_count)
            if plateau_count <= 0 and not bool(auto_x_action2_plateau_short_pull_active):
                return base, "normal pull; no ACTION2 area plateau yet"
            reduce_mm = max(0.0, float(getattr(args, "auto_x_action2_plateau_reduce_mm", 25.0)))
            min_pull = max(0.0, float(getattr(args, "auto_x_action2_plateau_min_pull_mm", 20.0)))
            reduced = max(min_pull, base - reduce_mm)
            return float(reduced), f"A80 plateau-short pull active count={plateau_count}: {base:.1f}-{reduce_mm:.1f} -> {reduced:.1f}mm; {auto_x_action2_plateau_last_reason}"
        except Exception as e:
            return max(0.0, float(base_pull_mm)), f"plateau reduction fallback: {repr(e)}"

    def _auto_x_update_action2_plateau_from_eval(ev: Optional[Dict[str, Any]], source: str = "ACTION2") -> None:
        """A79: after ACTION2, if garment-mask area barely changes, shorten future pulls."""
        nonlocal auto_x_action2_plateau_short_pull_active, auto_x_action2_plateau_last_reason, auto_x_action2_plateau_count
        try:
            if not bool(getattr(args, "auto_x_action2_plateau_reduce_enabled", True)):
                return
            if not isinstance(ev, dict):
                return
            area_gain = float(ev.get("area_gain_pct", 0.0) or 0.0)
            thr = max(0.0, float(getattr(args, "auto_x_action2_plateau_area_gain_pct", 3.0)))
            if area_gain <= thr:
                auto_x_action2_plateau_count = int(auto_x_action2_plateau_count) + 1
                auto_x_action2_plateau_short_pull_active = True
                auto_x_action2_plateau_last_reason = f"{source}: area_gain={area_gain:+.1f}% <= {thr:.1f}% plateau_count={auto_x_action2_plateau_count}"
                base = max(0.0, float(getattr(args, "auto_x_segmentation_spread_pull_mm", 50.0)))
                reduced, why = _auto_x_action2_effective_pull_mm(base)
                stop_n = int(max(1, getattr(args, "auto_x_action2_plateau_stop_count", 2)))
                print(f"[A80-ACTION2-PLATEAU] mask-area plateau detected; count={auto_x_action2_plateau_count}/{stop_n}, next ACTION2 pull={reduced:.1f}mm per arm | {why}")
            else:
                auto_x_action2_plateau_count = 0
                auto_x_action2_plateau_short_pull_active = False
                auto_x_action2_plateau_last_reason = f"{source}: area_gain={area_gain:+.1f}% > {thr:.1f}%"
                print(f"[A80-ACTION2-PLATEAU] area gain still meaningful: {area_gain:+.1f}% > {thr:.1f}%; reset plateau count")
        except Exception as e:
            print(f"[A79-ACTION2-PLATEAU-WARN] {repr(e)}")

    calibration_mode = False
    calib_sequence: List[Tuple[str, Dict[str, Any]]] = []
    calib_index = 0
    temp_roarm_xy: Dict[str, List[List[float]]] = {"arm1": [], "arm2": []}
    temp_roarm_z: Dict[str, List[float]] = {"arm1": [], "arm2": []}

    def frame_to_small_gray_f32(src_frame: np.ndarray) -> np.ndarray:
        gray = cv2.cvtColor(src_frame, cv2.COLOR_BGR2GRAY)
        return cv2.resize(gray, (160, 90), interpolation=cv2.INTER_AREA).astype(np.float32)

    def capture_fallback_empty_baseline(src_frame: np.ndarray, reason: str = "manual"):
        nonlocal fallback_empty_gray, fallback_empty_lab, fallback_empty_raw_gray, fallback_empty_frame_count
        raw_empty = src_frame.copy()
        corrected_empty = make_analysis_frame(raw_empty, reason=f"empty-board baseline: {reason}")
        fallback_empty_raw_gray = cv2.cvtColor(raw_empty, cv2.COLOR_BGR2GRAY).astype(np.float32)
        fallback_empty_gray = cv2.cvtColor(corrected_empty, cv2.COLOR_BGR2GRAY).astype(np.float32)
        fallback_empty_lab = cv2.cvtColor(corrected_empty, cv2.COLOR_BGR2LAB).astype(np.float32)
        fallback_empty_frame_count += 1
        print(f"[FALLBACK] Empty-board baseline captured ({reason}). count={fallback_empty_frame_count}. "
              "raw stale-watch + corrected perception baselines are both ready.")
        print("[LAB-EMPTY] Corrected baseline Lab image saved for garment/fallback perception.")

    def compute_foreground_state_from_empty(src_frame: np.ndarray, diff_threshold: Optional[float] = None,
                                            *, background_gray: Optional[np.ndarray] = None,
                                            homography: Optional[np.ndarray] = None) -> Dict[str, Any]:
        """Lightweight foreground state used only for rejudge/clear decisions.

        This intentionally does NOT replace the v3 fallback mask generation.
        It only answers: "is there a meaningful object on the board, and did it move/change?"
        """
        bg_source = fallback_empty_gray if background_gray is None else background_gray
        if bg_source is None:
            return {"valid": False, "reason": "no_empty_baseline", "area_px": 0.0, "contour_area_px": 0.0}
        h_for_mask = latest_H if homography is None else homography
        if h_for_mask is None:
            return {"valid": False, "reason": "no_matching_homography", "area_px": 0.0, "contour_area_px": 0.0}
        try:
            h, w = src_frame.shape[:2]
            gray = cv2.cvtColor(src_frame, cv2.COLOR_BGR2GRAY).astype(np.float32)
            bg = bg_source
            if bg.shape[:2] != gray.shape[:2]:
                bg = cv2.resize(bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
            board_mask = board_polygon_mask_from_h(h_for_mask, cfg, src_frame.shape,
                                                    shrink_px=int(args.fallback_board_shrink_px))
            diff = cv2.absdiff(gray, bg.astype(np.float32))
            th = float(args.change_diff_threshold if diff_threshold is None else diff_threshold)
            _, m = cv2.threshold(np.clip(diff, 0, 255).astype(np.uint8), th, 255, cv2.THRESH_BINARY)
            m = cv2.bitwise_and(m, board_mask)
            k = max(3, int(args.fallback_morph_kernel) | 1)
            kernel = np.ones((k, k), np.uint8)
            m = cv2.medianBlur(m.astype(np.uint8), 5)
            m = cv2.morphologyEx(m, cv2.MORPH_OPEN, kernel, iterations=1)
            m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, kernel, iterations=1)
            m = cv2.bitwise_and(m, board_mask)
            area_px = float(np.count_nonzero(m))
            contours, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if not contours:
                return {"valid": True, "reason": "no_contour", "mask": m, "area_px": area_px,
                        "contour_area_px": 0.0, "bbox": None, "center_px": None}
            contour = max(contours, key=cv2.contourArea)
            contour_area = float(cv2.contourArea(contour))
            x, y, bw, bh = cv2.boundingRect(contour)
            mm = cv2.moments(contour)
            if abs(mm.get("m00", 0.0)) > 1e-6:
                center = np.array([mm["m10"] / mm["m00"], mm["m01"] / mm["m00"]], dtype=np.float32)
            else:
                center = np.array([x + bw / 2.0, y + bh / 2.0], dtype=np.float32)
            return {"valid": True, "reason": "OK", "mask": m, "area_px": area_px,
                    "contour_area_px": contour_area, "bbox": [int(x), int(y), int(bw), int(bh)],
                    "center_px": center}
        except Exception as e:
            return {"valid": False, "reason": f"error:{repr(e)}", "area_px": 0.0, "contour_area_px": 0.0}

    def foreground_has_object(state: Optional[Dict[str, Any]], min_area: Optional[float] = None) -> bool:
        if not state or not state.get("valid", False):
            return False
        th = float(args.wait_cloth_fg_area_threshold_px if min_area is None else min_area)
        return float(state.get("contour_area_px", 0.0)) >= th or float(state.get("area_px", 0.0)) >= th

    def _snapshot_reason_requires_x_count_reset(reason: str) -> bool:
        """Only external target invalidation should reset the X->auto-press cycle.

        Do NOT reset for intentional fresh snapshots taken right before an X action.
        Reset when the current displayed target became unreliable because the cloth
        was removed, moved by a person/external force, or invalidated by the stale-target watcher.
        """
        r = str(reason or "").lower()
        triggers = (
            # only a real garment-cycle boundary resets adaptive state.
            # A stale/changed frozen target merely discards the pending plan and
            # preserves garment-motion, Late, structural, and adaptive memories.
            "cloth removed",
            "waiting for new cloth",
            "empty board",
            "no candidates",
        )
        return any(t in r for t in triggers)

    def _reset_coarse_auto_press_cycle(reason: str):
        nonlocal coarse_x_since_last_press
        nonlocal coarse_action_axis_override, coarse_action_stretch_distance_override
        nonlocal coarse_weak_bad_streak, coarse_x_dominant_streak
        nonlocal coarse_last_direction_kind, coarse_same_direction_streak
        nonlocal latest_spread_eval, spread_eval_history
        nonlocal auto_x_action2_plateau_short_pull_active, auto_x_action2_plateau_last_reason, auto_x_action2_plateau_count

        if not bool(args.auto_press_reset_x_count_on_target_invalidation):
            return
        if not _snapshot_reason_requires_x_count_reset(reason):
            return
        if (coarse_x_since_last_press != 0 or coarse_action_axis_override is not None
                or coarse_action_stretch_distance_override is not None
                or coarse_weak_bad_streak != 0 or coarse_same_direction_streak != 0
                or latest_spread_eval is not None or len(spread_eval_history) > 0):
            print(f"[AUTO-PRESS-RESET] target invalidated -> reset X count/adaptive state. reason={reason}")
        coarse_x_since_last_press = 0
        coarse_action_axis_override = None
        coarse_action_stretch_distance_override = None
        coarse_weak_bad_streak = 0
        coarse_x_dominant_streak = 0
        coarse_last_direction_kind = None
        coarse_same_direction_streak = 0
        latest_spread_eval = None
        spread_eval_history.clear()
        auto_x_action2_plateau_short_pull_active = False
        auto_x_action2_plateau_count = 0
        auto_x_action2_plateau_last_reason = "reset by target invalidation"

    def reset_snapshot(reason: str = "reset"):
        nonlocal snapshot_ready, snapshot_frame, snapshot_raw_frame, snapshot_canvas
        nonlocal force_snapshot_reason, force_snapshot_during_motion_allowed
        nonlocal force_snapshot_burst_reason, last_snapshot_burst_count
        nonlocal auto_x_cancelled_yolo_cleanup_required
        nonlocal stable_prev_gray, stable_since, stable_low_motion_frames
        nonlocal cloth_baseline_gray, cloth_baseline_frames, cloth_seen
        nonlocal wait_cloth_after_no_candidates, no_candidate_baseline_gray
        nonlocal snapshot_reference_gray, snapshot_foreground_state, target_stale_frames, target_removed_frames, target_changed_frames, target_stale_armed_at
        nonlocal latest_candidates, latest_candidate, latest_point, latest_dual_plan, latest_dual_status, latest_coarse_plan, latest_coarse_status, latest_fallback_status, latest_segmentation_source, latest_targeted_press_plan, latest_targeted_press_status, latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status, latest_boundary_plan, latest_boundary_status, latest_marker_fill_plan, latest_marker_fill_status, latest_pose_rotation_plan, latest_pose_rotation_status, auto_pick_done, auto_pick_buffer
        nonlocal latest_full_garment_mask, latest_full_garment_status, latest_yolo_raw_mask, latest_yolo_raw_status
        nonlocal fallback_last_trusted_area_px
        nonlocal auto_x_manual_judge_active, pending_auto_x_action

        _reset_coarse_auto_press_cycle(reason)
        # Any snapshot reset invalidates the completed-X label target. This prevents
        # a later live/manual frame from being paired with stale CCA values.
        _set_latest_cca_sample_snapshot({})
        force_snapshot_burst_frames.clear()
        force_snapshot_reason = None
        force_snapshot_during_motion_allowed = False
        force_snapshot_burst_reason = None
        last_snapshot_burst_count = 1
        _rr = str(reason or "").lower()
        soft_target_invalidation = any(tok in _rr for tok in (
                "cloth changed", "target invalidated"))
        # Camera/H or arm-affine recalibration is allowed during a dataset episode.
        # It invalidates frozen targets but does NOT force a new VLA episode/cycle_id;
        # per-observation environment_fingerprint separates pre/post-calibration data.
        environment_reset = any(tok in _rr for tok in ("homography reset", "calibration finished"))
        cycle_reset = any(tok in _rr for tok in (
                "manual a reset", "cloth removed",
                "waiting for new cloth", "empty board",
                "manual retake"))
        if soft_target_invalidation and not cycle_reset:
            def _publish_soft_target_invalidation() -> None:
                nonlocal pending_auto_x_action, auto_x_manual_judge_active
                pending_auto_x_action = None
                auto_x_manual_judge_active = True
                _a140_set_outer_overlay(
                    "AUTO-X TARGET INVALIDATED - AUTO REJUDGE",
                    str(reason)[:100],
                    hold_s=120.0,
                )

            applied = auto_x_controller.invalidate_target_schedule_rejudge(
                str(reason), time.monotonic(),
                delay_s=max(0.0, float(getattr(args, "auto_x_internal_rejudge_delay_s", 0.25))),
                publisher=_publish_soft_target_invalidation,
            )
            if applied:
                print(
                    "[A143-SOFT-TARGET-INVALIDATION] pending plan discarded; "
                    "garment-motion/Late/structural state preserved; stillness-gated auto rejudge scheduled"
                )
        if environment_reset and not cycle_reset:
            if yolo_busy and "discard cancelled auto-x yolo" not in _rr:
                auto_x_cancelled_yolo_cleanup_required = True
            pass
            _a140_disarm_continuous_cycle(reason, "IDLE")
            if auto_x_physical_recovery_required:
                auto_x_manual_judge_active = True
                _a140_set_outer_overlay(
                    "AUTO-X PHYSICAL RECOVERY REQUIRED - PRESS .",
                    f"environment changed; safety recovery still required: {auto_x_physical_recovery_reason}",
                    hold_s=3600.0,
                )
            else:
                auto_x_manual_judge_active = False
                _a140_set_outer_overlay(
                    "VLA ENVIRONMENT CHANGED",
                    f"{reason}; same episode allowed, next observation gets a new environment fingerprint",
                    hold_s=30.0,
                )
            pass
        if cycle_reset:
            fallback_last_trusted_area_px = None
            if yolo_busy and "discard cancelled auto-x yolo" not in _rr:
                auto_x_cancelled_yolo_cleanup_required = True
            _a140_disarm_continuous_cycle(reason, "IDLE")
            auto_x_debug_logger.stop_session(f"snapshot reset: {reason}")
            _a110_reset_ready_cycle(reason)
            if auto_x_physical_recovery_required:
                # Watcher/homography resets must not release Enter-pick protection
                # or hide an unsafe partial physical state.  "." is the sole recovery ack.
                auto_x_manual_judge_active = True
                _a140_set_outer_overlay(
                    "AUTO-X PHYSICAL RECOVERY REQUIRED - PRESS .",
                    f"manual safety check required; X/standby blocked: {auto_x_physical_recovery_reason}",
                    hold_s=3600.0,
                )
            else:
                auto_x_manual_judge_active = False
                _a140_set_outer_overlay("AUTO-X CYCLE RESET", str(reason)[:100], hold_s=8.0)

        snapshot_ready = False
        snapshot_frame = None
        snapshot_raw_frame = None
        snapshot_canvas = None
        stable_prev_gray = None
        stable_since = None
        stable_low_motion_frames = 0
        cloth_baseline_gray = None
        cloth_baseline_frames = 0
        cloth_seen = False
        wait_cloth_after_no_candidates = False
        no_candidate_baseline_gray = None
        snapshot_reference_gray = None
        snapshot_foreground_state = None
        target_stale_frames = 0
        target_removed_frames = 0
        target_changed_frames = 0
        target_stale_armed_at = 0.0
        latest_candidates = []
        latest_candidate = None
        latest_point = None
        latest_dual_plan = None
        latest_dual_status = "not computed"
        latest_coarse_plan = None
        latest_coarse_status = "not computed"
        latest_targeted_press_plan = None
        latest_targeted_press_status = "not computed"
        latest_wrinkle_heatmap_plan = None
        latest_wrinkle_heatmap_status = "not computed"
        # Tie all overlays to the same snapshot lifecycle.  Old MO-PICK/SIDE-PICK
        # must disappear whenever SELECT/SPREAD/center is cleared or re-estimated.
        latest_boundary_plan = None
        latest_boundary_status = "cleared by snapshot reset"
        latest_marker_fill_plan = None
        latest_marker_fill_status = "cleared by snapshot reset"
        latest_pose_rotation_plan = None
        latest_pose_rotation_status = "cleared by snapshot reset"
        latest_full_garment_mask = None
        latest_full_garment_status = "cleared by snapshot reset"
        latest_yolo_raw_mask = None
        latest_yolo_raw_status = "cleared by snapshot reset"
        latest_fallback_status = "not used"
        latest_segmentation_source = "NONE"
        auto_pick_done = False
        auto_pick_buffer.clear()
        print(f"[SNAPSHOT] {reason}. Waiting for a still view again.")

    def get_effective_coarse_axis_mode() -> str:
        return str(coarse_action_axis_override if coarse_action_axis_override else args.coarse_axis_mode)

    def get_effective_coarse_stretch_distance() -> float:
        if coarse_action_stretch_distance_override is None:
            return float(args.coarse_stretch_distance)
        return float(coarse_action_stretch_distance_override)

    def _largest_contour_from_u8(mask_u8: np.ndarray) -> Optional[np.ndarray]:
        if mask_u8 is None:
            return None
        contours, _ = cv2.findContours(mask_u8.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if not contours:
            return None
        return max(contours, key=cv2.contourArea)

    def _planning_mask_from_candidate(cand: Dict[str, Any], image_shape) -> Optional[np.ndarray]:
        """Return a board-clipped, cleaned planning mask for center/spread/smart planning.

        YOLO may predict a box/mask that leaks outside the ArUco board or includes
        background when the garment partly exits the frame.  This mask is used only
        for geometric planning, not to change the raw YOLO visualization.
        """
        if cand is None or image_shape is None:
            return None
        contour = cand.get("contour") if isinstance(cand, dict) else None
        if contour is None:
            return None
        raw = _mask_u8_from_contour(contour, image_shape)
        if raw is None or int(np.count_nonzero(raw)) < 20:
            return None
        if bool(getattr(args, "planning_mask_clip_to_board", True)) and latest_H is not None:
            board_mask = board_polygon_mask_from_h(
                latest_H, cfg, image_shape,
                shrink_px=max(0, int(getattr(args, "planning_mask_board_shrink_px", 14)))
            )
            m = cv2.bitwise_and(raw.astype(np.uint8), board_mask.astype(np.uint8))
        else:
            m = raw.astype(np.uint8)

        k = max(0, int(getattr(args, "planning_mask_morph_kernel", 5)))
        if k >= 3:
            k = k | 1
            kernel = np.ones((k, k), np.uint8)
            m = cv2.morphologyEx(m, cv2.MORPH_OPEN, kernel, iterations=1)
            m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, kernel, iterations=1)

        cnt = _largest_contour_from_u8(m)
        if cnt is None:
            return None
        clean = np.zeros_like(m, dtype=np.uint8)
        cv2.drawContours(clean, [cnt], -1, 255, thickness=-1)

        erode_px = max(0, int(getattr(args, "planning_mask_erode_px", 7)))
        if erode_px >= 3:
            erode_px = erode_px | 1
            ek = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (erode_px, erode_px))
            eroded = cv2.erode(clean, ek, iterations=1)
            if int(np.count_nonzero(eroded)) >= max(200, int(0.18 * np.count_nonzero(clean))):
                clean = eroded
        return clean

    def _mask_fill_ratio(mask_u8: np.ndarray) -> Tuple[float, float, Tuple[int, int, int, int]]:
        """Return (fill_ratio, contour_area, bbox) for a binary mask's largest component."""
        cnt = _largest_contour_from_u8(mask_u8)
        if cnt is None:
            return 0.0, 0.0, (0, 0, 0, 0)
        x, y, w, h = cv2.boundingRect(cnt)
        bbox_area = max(1.0, float(w * h))
        area = float(cv2.contourArea(cnt))
        return float(area / bbox_area), area, (int(x), int(y), int(w), int(h))

    def _lab_veto_and_refine_planning_mask(mask_u8: np.ndarray, src_frame: np.ndarray, label: str = "candidate") -> Tuple[Optional[np.ndarray], bool, str]:
        """Reject lighting/shadow false positives using E-key empty-board Lab baseline.

        This filter is intentionally color-focused for the current test condition:
        colored garments are accepted by a/b chroma change, while brightness-only L
        changes from natural light or shadows are weakly weighted and usually rejected.
        """
        if mask_u8 is None or int(np.count_nonzero(mask_u8)) < 20:
            return None, False, "empty_mask"
        if not bool(getattr(args, "lab_empty_veto", True)):
            return mask_u8, True, "lab_veto_disabled"
        if fallback_empty_lab is None:
            if bool(getattr(args, "lab_empty_veto_require_baseline", False)):
                return None, False, "no_lab_baseline_reject"
            return mask_u8, True, "no_lab_baseline_pass"

        try:
            h, w = src_frame.shape[:2]
            lab_cur = cv2.cvtColor(src_frame, cv2.COLOR_BGR2LAB).astype(np.float32)
            lab_bg = fallback_empty_lab
            if lab_bg.shape[:2] != lab_cur.shape[:2]:
                lab_bg = cv2.resize(lab_bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
            mb = mask_u8.astype(np.uint8) > 0
            n = int(np.count_nonzero(mb))
            if n < 20:
                return None, False, "too_few_mask_pixels"

            d = np.abs(lab_cur - lab_bg.astype(np.float32))
            dL = d[:, :, 0]
            da = d[:, :, 1]
            db = d[:, :, 2]
            dAB = np.sqrt(da * da + db * db)
            l_weight = float(np.clip(getattr(args, "lab_empty_veto_l_weight", 0.25), 0.0, 2.0))
            combined = l_weight * dL + dAB

            ab_thr = max(0.0, float(getattr(args, "lab_empty_veto_ab_threshold", 10.0)))
            comb_thr = max(0.0, float(getattr(args, "lab_empty_veto_combined_threshold", 14.0)))
            mean_l = float(np.mean(dL[mb]))
            mean_ab = float(np.mean(dAB[mb]))
            mean_comb = float(np.mean(combined[mb]))
            ab_ratio = float(np.count_nonzero((dAB >= ab_thr) & mb) / max(1, n))
            comb_ratio = float(np.count_nonzero((combined >= comb_thr) & mb) / max(1, n))
            min_mean_ab = max(0.0, float(getattr(args, "lab_empty_veto_min_mean_ab_diff", 4.5)))
            min_ab_ratio = float(np.clip(getattr(args, "lab_empty_veto_min_changed_ab_ratio", 0.035), 0.0, 1.0))
            min_comb_ratio = float(np.clip(getattr(args, "lab_empty_veto_min_combined_ratio", 0.035), 0.0, 1.0))

            accept = (mean_ab >= min_mean_ab) or (ab_ratio >= min_ab_ratio) or (comb_ratio >= min_comb_ratio)
            if not accept:
                msg = (f"reject meanL={mean_l:.1f} meanAB={mean_ab:.1f} meanComb={mean_comb:.1f} "
                       f"abRatio={ab_ratio:.3f} combRatio={comb_ratio:.3f}")
                if bool(getattr(args, "fallback_print_debug", False)):
                    print(f"[LAB-VETO] {label}: {msg}")
                return None, False, msg

            refined_msg = "raw_mask"
            out_mask = mask_u8.astype(np.uint8)
            if bool(getattr(args, "lab_empty_refine_mask", True)):
                change = (((dAB >= ab_thr) | (combined >= comb_thr)) & mb).astype(np.uint8) * 255
                k = max(0, int(getattr(args, "lab_empty_refine_morph_kernel", 7)))
                if k >= 3:
                    k = k | 1
                    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k))
                    change = cv2.morphologyEx(change, cv2.MORPH_OPEN, kernel, iterations=1)
                    change = cv2.morphologyEx(change, cv2.MORPH_CLOSE, kernel, iterations=2)
                change = cv2.bitwise_and(change, out_mask)
                cnt = _largest_contour_from_u8(change)
                if cnt is not None:
                    refined = np.zeros_like(out_mask, dtype=np.uint8)
                    cv2.drawContours(refined, [cnt], -1, 255, thickness=-1)
                    raw_area = max(1, int(np.count_nonzero(out_mask)))
                    ref_area = int(np.count_nonzero(refined))
                    min_keep = float(np.clip(getattr(args, "lab_empty_refine_min_keep_ratio", 0.18), 0.0, 1.0))
                    min_area = max(50.0, float(getattr(args, "planning_mask_min_area_px", 1200.0)) * 0.60)
                    if ref_area >= min_area and ref_area >= int(raw_area * min_keep):
                        out_mask = refined
                        refined_msg = f"refined area={ref_area}px keep={ref_area/raw_area:.2f}"
                    else:
                        refined_msg = f"raw_kept refined_too_small area={ref_area}px keep={ref_area/raw_area:.2f}"

            msg = (f"accept meanL={mean_l:.1f} meanAB={mean_ab:.1f} meanComb={mean_comb:.1f} "
                   f"abRatio={ab_ratio:.3f} combRatio={comb_ratio:.3f} {refined_msg}")
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[LAB-VETO] {label}: {msg}")
            return out_mask, True, msg
        except Exception as e:
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[LAB-VETO-WARN] {label}: {repr(e)}")
            if bool(getattr(args, "lab_empty_veto_require_baseline", False)):
                return None, False, f"error_reject {repr(e)}"
            return mask_u8, True, f"error_pass {repr(e)}"

    def sanitize_candidates_for_planning(candidates: List[Dict[str, Any]], src_frame: np.ndarray, reason: str = "snapshot") -> List[Dict[str, Any]]:
        """Use board-clipped masks for all geometry-driven planning.

        This specifically prevents two observed failures:
          1) MO/SIDE-PICK displayed outside the visible cloth because the geometric deep point
             was not forced back to the real mask;
          2) abnormal giant boxes/SPREAD targets when YOLO/fallback mask leaked outside the board.
        """
        if not candidates or not bool(getattr(args, "planning_mask_clip_to_board", True)):
            return candidates
        out: List[Dict[str, Any]] = []
        board_area_px = 0.0
        try:
            if latest_H is not None:
                bm = board_polygon_mask_from_h(latest_H, cfg, src_frame.shape, shrink_px=max(0, int(getattr(args, "planning_mask_board_shrink_px", 14))))
                board_area_px = float(np.count_nonzero(bm))
        except Exception:
            board_area_px = 0.0
        max_board_ratio = float(np.clip(getattr(args, "planning_mask_max_board_area_ratio", 0.88), 0.05, 1.0))
        min_area_px = max(50.0, float(getattr(args, "planning_mask_min_area_px", 1200.0)))
        for cand in candidates:
            try:
                image_shape = cand.get("image_shape", src_frame.shape)
                pmask = _planning_mask_from_candidate(cand, image_shape)
                if pmask is None:
                    continue
                label = f"{reason}:{cand.get('class_name', 'garment')}#{cand.get('object_index', len(out))}"
                pmask, lab_ok, lab_status = _lab_veto_and_refine_planning_mask(pmask, src_frame, label=label)
                if not lab_ok or pmask is None:
                    if bool(getattr(args, "fallback_print_debug", False)):
                        print(f"[PLAN-MASK] reject by Lab empty-board veto: {label} {lab_status}")
                    continue
                cnt = _largest_contour_from_u8(pmask)
                if cnt is None:
                    continue
                area = float(cv2.contourArea(cnt))
                if bool(getattr(args, "mask_shape_filter_enable", True)):
                    fill_ratio, _, bbox = _mask_fill_ratio(pmask)
                    min_fill = float(np.clip(getattr(args, "mask_shape_min_fill_ratio", 0.16), 0.0, 1.0))
                    max_fill = float(np.clip(getattr(args, "mask_shape_max_fill_ratio", 0.94), 0.0, 1.0))
                    if fill_ratio < min_fill or fill_ratio > max_fill:
                        if bool(getattr(args, "fallback_print_debug", False)):
                            print(f"[PLAN-MASK] reject shape fill_ratio={fill_ratio:.3f} not in [{min_fill:.3f},{max_fill:.3f}] bbox={bbox}")
                        continue
                if area < min_area_px:
                    if bool(getattr(args, "fallback_print_debug", False)):
                        print(f"[PLAN-MASK] reject small candidate area={area:.0f}px < {min_area_px:.0f}px")
                    continue
                if board_area_px > 0.0 and area > board_area_px * max_board_ratio:
                    if bool(getattr(args, "fallback_print_debug", False)):
                        print(f"[PLAN-MASK] reject huge candidate area={area:.0f}px > {max_board_ratio:.2f}*board_area={board_area_px:.0f}px")
                    continue
                refined = make_candidate_from_contour(
                    cnt, image_shape,
                    class_name=str(cand.get("class_name", "garment")),
                    conf=float(cand.get("conf", 0.0)),
                    object_index=int(cand.get("object_index", len(out))),
                    refine_candidates=bool(args.grasp_refine_candidates),
                    upper_band_ratio=float(args.grasp_upper_band_ratio),
                    inside_ratio=float(args.grasp_inside_ratio),
                    local_mask_radius=int(args.grasp_local_mask_radius),
                    min_local_mask_ratio=float(args.grasp_min_local_mask_ratio),
                    contour_smooth_epsilon_ratio=float(args.grasp_contour_smooth_epsilon_ratio),
                    debug=bool(args.grasp_debug or args.grasp_score_debug),
                )
                if refined is None:
                    continue
                refined["raw_area"] = float(cand.get("area", 0.0))
                refined["planning_area"] = float(area)
                refined["lab_veto_status"] = str(lab_status)
                refined["source"] = str(cand.get("source", cand.get("class_name", "yolo"))) + "+board_clipped+lab_checked"
                refined["raw_contour"] = cand.get("raw_contour", cand.get("contour"))
                refined["raw_pts"] = cand.get("raw_pts", cand.get("pts"))
                refined["raw_image_shape"] = cand.get("raw_image_shape", cand.get("image_shape", image_shape))
                out.append(refined)
            except Exception as e:
                if bool(getattr(args, "fallback_print_debug", False)):
                    print(f"[PLAN-MASK-WARN] candidate sanitize failed: {repr(e)}")
        if out:
            if bool(getattr(args, "fallback_print_debug", False)) and len(out) != len(candidates):
                print(f"[PLAN-MASK] planning candidates {len(candidates)} -> {len(out)} after board-clip/core filtering ({reason})")
            return out
        if bool(getattr(args, "planning_mask_keep_raw_if_all_filtered", False)):
            print("[PLAN-MASK] all candidates rejected; keeping raw candidates because --planning-mask-keep-raw-if-all-filtered is enabled")
            return candidates
        print("[PLAN-MASK] all candidates rejected by board-clip/core filtering; no planning target will be used")
        return []



    def _expanded_board_mask_for_full_garment(image_shape, expand_mm: float) -> Optional[np.ndarray]:
        """Return a pixel ROI covering the marker board plus an outside margin.

        The normal planning mask is clipped to the board for robot safety, but the
        visual garment frame and '/' overflow measurement need the garment region
        outside the marker rectangle. This ROI is only a search limit, not a robot
        workspace.
        """
        try:
            if latest_H is None:
                return None
            h, w = image_shape[:2]
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            e = max(0.0, float(expand_mm))
            board_corners = [
                (min_bx - e, min_by - e),
                (max_bx + e, min_by - e),
                (max_bx + e, max_by + e),
                (min_bx - e, max_by + e),
            ]
            pts = []
            for bx, by in board_corners:
                pxy = board_to_pixel(latest_H, bx, by)
                if pxy is None:
                    return None
                x = int(round(float(pxy[0]))); y = int(round(float(pxy[1])))
                x = max(-w, min(2 * w, x)); y = max(-h, min(2 * h, y))
                pts.append([x, y])
            mask = np.zeros((h, w), dtype=np.uint8)
            cv2.fillConvexPoly(mask, np.asarray(pts, dtype=np.int32).reshape(-1, 1, 2), 255)
            return mask
        except Exception:
            return None

    def _union_mask_from_candidates_for_full_frame(candidates: List[Dict[str, Any]], image_shape) -> np.ndarray:
        h, w = image_shape[:2]
        union = np.zeros((h, w), dtype=np.uint8)
        for cand in candidates or []:
            contour = cand.get("raw_contour", cand.get("contour")) if isinstance(cand, dict) else None
            if contour is None:
                continue
            try:
                cm = _mask_u8_from_contour(contour, image_shape)
                union = cv2.bitwise_or(union, cm.astype(np.uint8))
            except Exception:
                continue
        return union

    def _empty_baseline_fg_for_full_garment(src_frame: np.ndarray) -> Tuple[Optional[np.ndarray], str]:
        """Foreground outside+inside board using the E-key empty-board baseline.

        This is used to extend the garment contour when YOLO detects only the inside
        portion or fails completely. It is intentionally limited to an expanded
        board ROI and later filtered by board-overlap connected components.
        """
        try:
            if fallback_empty_gray is None:
                return None, "no E-key empty baseline"
            if latest_H is None:
                return None, "no Homography"
            h, w = src_frame.shape[:2]
            roi = _perception_roi_mask(src_frame.shape)
            if roi is None:
                roi = _expanded_board_mask_for_full_garment(
                    src_frame.shape,
                    float(getattr(args, "full_garment_frame_expand_mm", getattr(args, "variable_overflow_raw_expand_mm", 180.0))),
                )
            if roi is None or int(np.count_nonzero(roi)) < 100:
                return None, "garment ROI failed"
            gray = cv2.cvtColor(src_frame, cv2.COLOR_BGR2GRAY).astype(np.float32)
            bg = fallback_empty_gray
            if bg.shape[:2] != gray.shape[:2]:
                bg = cv2.resize(bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
            thr = float(getattr(args, "full_garment_frame_diff_threshold", 16.0))
            diff = cv2.absdiff(gray, bg.astype(np.float32))
            fg_gray = diff > thr
            fg_lab = None
            try:
                if fallback_empty_lab is not None:
                    lab_now = cv2.cvtColor(src_frame, cv2.COLOR_BGR2LAB).astype(np.float32)
                    lab_bg = fallback_empty_lab
                    if lab_bg.shape[:2] != lab_now.shape[:2]:
                        lab_bg = cv2.resize(lab_bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
                    ab = lab_now[:, :, 1:3] - lab_bg[:, :, 1:3]
                    abdist = np.sqrt(np.sum(ab * ab, axis=2))
                    fg_lab = abdist > max(8.0, thr * 0.55)
            except Exception:
                fg_lab = None
            if fg_lab is not None:
                fg = ((fg_gray | fg_lab) & (roi > 0)).astype(np.uint8) * 255
            else:
                fg = (fg_gray & (roi > 0)).astype(np.uint8) * 255
            k = max(3, int(getattr(args, "full_garment_frame_morph_kernel", 9)) | 1)
            kernel = np.ones((k, k), np.uint8)
            fg = cv2.medianBlur(fg, 5)
            fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, kernel, iterations=1)
            fg = cv2.morphologyEx(fg, cv2.MORPH_CLOSE, kernel, iterations=3)
            return fg, f"empty_fg(diff>{thr:.1f})"
        except Exception as e:
            return None, f"empty_fg failed: {repr(e)}"

    def _filter_full_garment_components(src_frame: np.ndarray, union_mask: np.ndarray, yolo_seed: Optional[np.ndarray], source: str) -> Tuple[Optional[np.ndarray], str]:
        """Keep a full garment mask that can extend outside the marker board.

        Step_a26 fix:
          - Do not require every connected component to overlap the ArUco board.
            If the protruding cloth is separated by a small threshold/morphology gap,
            keep it when it is close to the board-connected garment seed.
          - This mask is only for visual full-garment framing and raw overflow
            measurement. Robot contact planning is still clipped back inside the board.
        """
        try:
            if union_mask is None:
                return None, f"{source}: no mask"
            if latest_H is None:
                return None, f"{source}: no Homography"
            h, w = src_frame.shape[:2]
            roi = _perception_roi_mask(src_frame.shape)
            if roi is None:
                roi = _expanded_board_mask_for_full_garment(
                    src_frame.shape,
                    float(getattr(args, "full_garment_frame_expand_mm", getattr(args, "variable_overflow_raw_expand_mm", 180.0))),
                )
            m = (union_mask.astype(np.uint8) > 0).astype(np.uint8) * 255
            if roi is not None:
                m = cv2.bitwise_and(m, roi.astype(np.uint8))

            k = max(3, int(getattr(args, "full_garment_frame_morph_kernel", 9)) | 1)
            kernel = np.ones((k, k), np.uint8)
            m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, kernel, iterations=2)
            m = cv2.morphologyEx(m, cv2.MORPH_OPEN, kernel, iterations=1)

            bridge_px = max(0, int(getattr(args, "full_garment_frame_dilate_bridge_px", 17)))
            if bridge_px >= 3:
                bk = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (bridge_px | 1, bridge_px | 1))
                m_for_cc = cv2.dilate(m, bk, iterations=1)
            else:
                m_for_cc = m

            board_mask = board_polygon_mask_from_h(latest_H, cfg, src_frame.shape, shrink_px=0).astype(np.uint8)
            min_total = float(getattr(args, "full_garment_frame_min_area_px", 900.0))
            min_inside = float(getattr(args, "full_garment_frame_min_inside_area_px", 160.0))
            gap_px = max(0, int(getattr(args, "full_garment_frame_connect_gap_px", 55)))
            roi_area = float(np.count_nonzero(roi)) if roi is not None else float(h * w)

            seed = np.zeros((h, w), dtype=np.uint8)
            inside_seed = cv2.bitwise_and(m, board_mask)
            if int(np.count_nonzero(inside_seed)) >= max(30, int(min_inside * 0.25)):
                seed = cv2.bitwise_or(seed, inside_seed)
            if yolo_seed is not None and int(np.count_nonzero(yolo_seed)) > 50:
                seed = cv2.bitwise_or(seed, (yolo_seed.astype(np.uint8) > 0).astype(np.uint8) * 255)
            if int(np.count_nonzero(seed)) <= 0:
                near_board_k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (max(3, gap_px) | 1, max(3, gap_px) | 1))
                near_board = cv2.dilate(board_mask, near_board_k, iterations=1)
                seed = cv2.bitwise_and(m, near_board)

            if gap_px > 0 and int(np.count_nonzero(seed)) > 0:
                gk = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (gap_px | 1, gap_px | 1))
                seed_near = cv2.dilate(seed, gk, iterations=1)
            else:
                seed_near = seed

            num, labels, stats, _ = cv2.connectedComponentsWithStats((m_for_cc > 0).astype(np.uint8), connectivity=8)
            kept = np.zeros((h, w), dtype=np.uint8)
            kept_count = 0
            kept_area = 0.0
            kept_inside = 0.0
            kept_near = 0.0
            kept_seed = 0.0
            for lab in range(1, int(num)):
                cc = (labels == lab)
                comp_u8 = ((cc & (m > 0))).astype(np.uint8) * 255
                area = float(np.count_nonzero(comp_u8))
                if area < max(80.0, min_total * 0.08):
                    continue
                if area > max(1000.0, roi_area * 0.88):
                    continue
                comp_bool = comp_u8 > 0
                inside_area = float(np.count_nonzero(comp_bool & (board_mask > 0)))
                seed_overlap = float(np.count_nonzero(comp_bool & (seed > 0)))
                near_overlap = float(np.count_nonzero(comp_bool & (seed_near > 0)))
                if inside_area < min_inside and seed_overlap < 30.0 and near_overlap < 30.0:
                    continue
                kept = cv2.bitwise_or(kept, comp_u8)
                kept_count += 1
                kept_area += area
                kept_inside += inside_area
                kept_near += near_overlap
                kept_seed += seed_overlap
            if kept_count <= 0:
                return None, f"{source}: no garment component connected/near board seed"
            if kept_area < min_total:
                return None, f"{source}: kept area too small {kept_area:.0f}px < {min_total:.0f}px"
            kept = cv2.morphologyEx(kept, cv2.MORPH_CLOSE, kernel, iterations=2)
            return kept, (f"{source}(area={kept_area:.0f}px, inside={kept_inside:.0f}px, "
                          f"near={kept_near:.0f}px, seed={kept_seed:.0f}px, parts={kept_count})")
        except Exception as e:
            return None, f"{source}: component filter failed {repr(e)}"

    def build_full_garment_mask_for_frame(src_frame: np.ndarray, raw_candidates: List[Dict[str, Any]], reason: str = "snapshot") -> Tuple[Optional[np.ndarray], str]:
        """Build the display/overflow garment mask in full camera-frame coordinates.

        Step_a27 policy:
          1) If YOLO segmentation returns a mask, preserve that raw full-frame mask
             directly. Do NOT pass it through board clipping or component filters before
             drawing the display bbox. This is the main fix for protruding cloth not
             being boxed.
          2) E-key empty-board foreground is used only as an extension source when YOLO
             misses protruding regions. The foreground extension is filtered, then OR'ed
             back with the raw YOLO mask.
          3) Robot planning still uses sanitized board-clipped planning masks elsewhere.
        """
        try:
            if not bool(getattr(args, "full_garment_frame_mode", True)):
                return None, "full garment frame disabled"
            yolo_union = _union_mask_from_candidates_for_full_frame(raw_candidates or [], src_frame.shape)
            yolo_px = int(np.count_nonzero(yolo_union))
            has_yolo = yolo_px > 80

            fg, fg_status = _empty_baseline_fg_for_full_garment(src_frame)
            fg_px = int(np.count_nonzero(fg)) if fg is not None else 0

            if has_yolo:
                full = (yolo_union.astype(np.uint8) > 0).astype(np.uint8) * 255
                status_parts = [f"yolo_raw_aruco_roi area={yolo_px}px" if bool(getattr(args, "perception_roi_clip_to_aruco_board", True)) and latest_H is not None else f"yolo_raw_unclipped area={yolo_px}px"]
                if fg is not None and fg_px > 80:
                    fg_filt, st = _filter_full_garment_components(src_frame, fg, yolo_union, "fg_extension")
                    if fg_filt is not None and int(np.count_nonzero(fg_filt)) > 80:
                        full = cv2.bitwise_or(full, (fg_filt.astype(np.uint8) > 0).astype(np.uint8) * 255)
                        status_parts.append(st)
                    else:
                        status_parts.append(f"fg_extension_not_used:{st}")
                else:
                    status_parts.append(f"no_fg_extension:{fg_status}")
                k = max(3, int(getattr(args, "full_garment_frame_morph_kernel", 9)) | 1)
                kernel = np.ones((k, k), np.uint8)
                full = cv2.morphologyEx(full, cv2.MORPH_CLOSE, kernel, iterations=1)
                return full, "; ".join(status_parts)

            if fg is not None and fg_px > 80:
                filt, st = _filter_full_garment_components(src_frame, fg, None, fg_status)
                return filt, st

            return None, f"no full mask source: yolo={yolo_px}px, {fg_status}"
        except Exception as e:
            return None, f"full garment mask failed: {repr(e)}"

    def draw_full_garment_overlay(canvas: np.ndarray, full_mask: Optional[np.ndarray], status: str) -> np.ndarray:
        if full_mask is None:
            return canvas
        try:
            out = canvas.copy()
            contours, _ = cv2.findContours((full_mask > 0).astype(np.uint8) * 255, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            contours = [c for c in contours if cv2.contourArea(c) > 80]
            if not contours:
                return out
            overlay = out.copy()
            cv2.drawContours(overlay, contours, -1, (255, 0, 255), thickness=-1)
            out = cv2.addWeighted(overlay, 0.18, out, 0.82, 0)
            cv2.drawContours(out, contours, -1, (255, 0, 255), 3)
            all_pts = np.vstack(contours)
            x, y, w, h = cv2.boundingRect(all_pts)
            cv2.rectangle(out, (x, y), (x + w, y + h), (255, 0, 255), 2)
            cv2.putText(out, "FULL-GARMENT FRAME", (x, max(25, y - 10)), cv2.FONT_HERSHEY_SIMPLEX, 0.65, (0, 0, 0), 4)
            cv2.putText(out, "FULL-GARMENT FRAME", (x, max(25, y - 10)), cv2.FONT_HERSHEY_SIMPLEX, 0.65, (255, 0, 255), 2)
            cv2.putText(out, status[:105], (25, 145), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (0, 0, 0), 3)
            cv2.putText(out, status[:105], (25, 145), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (255, 0, 255), 1)
            return out
        except Exception:
            return canvas

    def _mask_contours_and_bbox(mask: Optional[np.ndarray], min_area: float = 80.0):
        if mask is None:
            return [], None
        try:
            m = (mask.astype(np.uint8) > 0).astype(np.uint8) * 255
            contours, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            contours = [c for c in contours if cv2.contourArea(c) >= float(min_area)]
            if not contours:
                return [], None
            all_pts = np.vstack(contours)
            x, y, w, h = cv2.boundingRect(all_pts)
            return contours, (int(x), int(y), int(w), int(h))
        except Exception:
            return [], None

    def draw_yolo_raw_segmentation_debug(canvas: np.ndarray, raw_mask: Optional[np.ndarray], status: str) -> np.ndarray:
        """Draw the segmentation model's raw full-frame mask, not board-clipped.

        This is a temporary debugging overlay toggled with '['. It answers the exact
        question: did the model itself segment the cloth outside the marker frame?
        """
        if raw_mask is None:
            cv2.putText(canvas, f"RAW YOLO MASK DEBUG: OFF/NO MASK {str(status)[:60]}", (25, 325),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.52, (0, 0, 0), 4)
            cv2.putText(canvas, f"RAW YOLO MASK DEBUG: OFF/NO MASK {str(status)[:60]}", (25, 325),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.52, (255, 255, 0), 2)
            return canvas
        try:
            out = canvas.copy()
            contours, bbox = _mask_contours_and_bbox(raw_mask, min_area=80.0)
            if not contours:
                return out
            alpha = float(np.clip(getattr(args, "debug_segmentation_mask_alpha", 0.35), 0.05, 0.85))
            overlay = out.copy()
            cv2.drawContours(overlay, contours, -1, (255, 255, 0), thickness=-1)
            out = cv2.addWeighted(overlay, alpha, out, 1.0 - alpha, 0)
            cv2.drawContours(out, contours, -1, (255, 255, 0), 2)
            if bbox is not None:
                x, y, w, h = bbox
                cv2.rectangle(out, (x, y), (x + w, y + h), (255, 255, 0), 2)
                cv2.putText(out, "RAW YOLO FULL-FRAME MASK", (x, max(25, y - 12)),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.60, (0, 0, 0), 4)
                cv2.putText(out, "RAW YOLO FULL-FRAME MASK", (x, max(25, y - 12)),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.60, (255, 255, 0), 2)
            cv2.putText(out, f"RAW YOLO MASK DEBUG ON '[' toggle | {str(status)[:85]}", (25, 325),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.50, (0, 0, 0), 4)
            cv2.putText(out, f"RAW YOLO MASK DEBUG ON '[' toggle | {str(status)[:85]}", (25, 325),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.50, (255, 255, 0), 2)
            return out
        except Exception:
            return canvas

    def draw_variable_overflow_plan_overlay(canvas: np.ndarray) -> np.ndarray:
        """Draw the actual / contact point, drag vector, and circumcenter geometry.

        Step_a37 addition:
          - When the / plan is the circumcenter-vacancy policy, draw the selected
            triangle made from the two selected side midpoints and the chosen pose point.
          - If the circumcenter target was accepted, draw the projected circumcircle
            on the OpenCV image.  The circle is sampled in board coordinates first and
            then projected through the current Homography, so it appears correctly under
            camera perspective.
        """
        try:
            vp = latest_variable_overflow_plan
            if not isinstance(vp, dict) or latest_H is None:
                return canvas
            sb = vp.get("start_board_xy")
            eb = vp.get("end_board_xy")
            if not isinstance(sb, (list, tuple)) or not isinstance(eb, (list, tuple)) or len(sb) < 2 or len(eb) < 2:
                return canvas

            def _board_xy_to_px_tuple(xy: Any) -> Optional[Tuple[int, int]]:
                try:
                    if not isinstance(xy, (list, tuple, np.ndarray)) or len(xy) < 2:
                        return None
                    p = board_to_pixel(latest_H, float(xy[0]), float(xy[1]))
                    if p is None:
                        return None
                    return int(round(float(p[0]))), int(round(float(p[1])))
                except Exception:
                    return None

            def _draw_text_with_outline(img: np.ndarray, text_s: str, org: Tuple[int, int], scale: float,
                                        color: Tuple[int, int, int], thickness: int = 2) -> None:
                cv2.putText(img, text_s, org, cv2.FONT_HERSHEY_SIMPLEX, scale, (0, 0, 0), thickness + 2)
                cv2.putText(img, text_s, org, cv2.FONT_HERSHEY_SIMPLEX, scale, color, thickness)

            sp = _board_xy_to_px_tuple(sb)
            ep = _board_xy_to_px_tuple(eb)
            if sp is None or ep is None:
                return canvas
            sx, sy = sp
            ex, ey = ep
            out = canvas.copy()

            ci = vp.get("circumcenter_info")
            if isinstance(ci, dict):
                m1_b = ci.get("side_midpoint_a")
                m2_b = ci.get("side_midpoint_b")
                pose_b = ci.get("pose_point_board_xy")
                target_kind = str(ci.get("target_kind", vp.get("contact_target_type", "?")))
                target_reason = str(ci.get("target_reason", ""))
                pose_name = str(ci.get("pose_point_name", "pose"))
                radius_mm = float(ci.get("circumradius_mm", 0.0) or 0.0)
                target_b = vp.get("contact_target")

                m1_px = _board_xy_to_px_tuple(m1_b)
                m2_px = _board_xy_to_px_tuple(m2_b)
                pose_px = _board_xy_to_px_tuple(pose_b)
                target_px = _board_xy_to_px_tuple(target_b)

                if m1_px is not None and m2_px is not None and pose_px is not None:
                    tri = np.array([m1_px, m2_px, pose_px], dtype=np.int32).reshape((-1, 1, 2))
                    cv2.polylines(out, [tri], True, (0, 0, 0), 5, lineType=cv2.LINE_AA)
                    cv2.polylines(out, [tri], True, (0, 255, 0), 2, lineType=cv2.LINE_AA)
                    for name, pt, col in (("M1", m1_px, (0, 255, 0)), ("M2", m2_px, (0, 255, 0)), (pose_name[:10], pose_px, (0, 180, 255))):
                        cv2.circle(out, pt, 8, (0, 0, 0), -1, lineType=cv2.LINE_AA)
                        cv2.circle(out, pt, 5, col, -1, lineType=cv2.LINE_AA)
                        _draw_text_with_outline(out, name, (pt[0] + 8, pt[1] - 8), 0.45, col, 1)

                if target_kind == "circumcenter" and target_b is not None and target_px is not None and radius_mm > 1.0:
                    circle_pts: List[Tuple[int, int]] = []
                    cx_b, cy_b = float(target_b[0]), float(target_b[1])
                    for th in np.linspace(0.0, 2.0 * math.pi, 144, endpoint=False):
                        bx = cx_b + radius_mm * math.cos(float(th))
                        by = cy_b + radius_mm * math.sin(float(th))
                        pp = _board_xy_to_px_tuple([bx, by])
                        if pp is not None:
                            circle_pts.append(pp)
                    if len(circle_pts) >= 8:
                        cpoly = np.asarray(circle_pts, dtype=np.int32).reshape((-1, 1, 2))
                        cv2.polylines(out, [cpoly], True, (0, 0, 0), 5, lineType=cv2.LINE_AA)
                        cv2.polylines(out, [cpoly], True, (255, 0, 255), 2, lineType=cv2.LINE_AA)
                    cv2.circle(out, target_px, 11, (0, 0, 0), -1, lineType=cv2.LINE_AA)
                    cv2.circle(out, target_px, 7, (255, 0, 255), -1, lineType=cv2.LINE_AA)
                    _draw_text_with_outline(out, f"CIRCUMCENTER r={radius_mm:.0f}mm", (target_px[0] + 12, target_px[1] + 18), 0.48, (255, 0, 255), 1)
                elif target_px is not None:
                    # Fallback target or clamped target: draw it, but do not draw a fake circumcircle.
                    cv2.circle(out, target_px, 10, (0, 0, 0), -1, lineType=cv2.LINE_AA)
                    cv2.circle(out, target_px, 6, (0, 165, 255), -1, lineType=cv2.LINE_AA)
                    _draw_text_with_outline(out, f"TARGET {target_kind[:18]}", (target_px[0] + 12, target_px[1] + 18), 0.45, (0, 165, 255), 1)

                _draw_text_with_outline(out, f"/ CIRC-GEOM: {target_kind} | {target_reason[:55]}",
                                        (25, 355), 0.48, (255, 0, 255) if target_kind == "circumcenter" else (0, 165, 255), 1)

            cv2.circle(out, (sx, sy), 14, (0, 0, 0), 5)
            cv2.circle(out, (sx, sy), 14, (255, 255, 0), 3)
            cv2.circle(out, (sx, sy), 5, (0, 0, 0), -1)
            cv2.circle(out, (sx, sy), 4, (255, 255, 0), -1)
            cv2.arrowedLine(out, (sx, sy), (ex, ey), (0, 0, 0), 6, tipLength=0.25)
            cv2.arrowedLine(out, (sx, sy), (ex, ey), (255, 255, 0), 3, tipLength=0.25)
            label = f"/ CONTACT {str(vp.get('arm_key','?')).upper()} {str(vp.get('side','?'))} dist={float(vp.get('pull_distance',0.0)):.0f}mm"
            tx, ty = max(8, min(canvas.shape[1]-500, sx + 18)), max(30, sy - 18)
            _draw_text_with_outline(out, label, (tx, ty), 0.55, (255, 255, 0), 2)
            return out
        except Exception:
            return canvas

    def draw_latest_full_garment_on_live(canvas: np.ndarray) -> np.ndarray:
        """Always draw the current full-garment bbox/contour on the displayed OpenCV frame.

        In snapshot mode the screen is live by default, so the full-garment bbox drawn
        only into snapshot_canvas is easy to miss. This redraws that full-frame mask
        on the current camera image so protruding cloth is visible without pressing '/'.
        """
        if bool(getattr(args, "full_garment_frame_mode", True)) and latest_full_garment_mask is not None:
            canvas = draw_full_garment_overlay(canvas, latest_full_garment_mask, latest_full_garment_status)
        if debug_segmentation_mask_overlay:
            dbg_mask = latest_full_garment_mask if latest_full_garment_mask is not None else latest_yolo_raw_mask
            dbg_status = ("FULL-GARMENT DEBUG | " + str(latest_full_garment_status)) if latest_full_garment_mask is not None else latest_yolo_raw_status
            canvas = draw_yolo_raw_segmentation_debug(canvas, dbg_mask, dbg_status)
        else:
            cv2.putText(canvas, "[ key: raw YOLO mask debug", (25, 325), cv2.FONT_HERSHEY_SIMPLEX, 0.46, (0, 0, 0), 3)
            cv2.putText(canvas, "[ key: raw YOLO mask debug", (25, 325), cv2.FONT_HERSHEY_SIMPLEX, 0.46, (180, 180, 180), 1)
        canvas = draw_variable_overflow_plan_overlay(canvas)
        return canvas

    def _snap_deep_pick_to_mask_board_point(board: np.ndarray, candidate_mask: np.ndarray, desired: np.ndarray,
                                            edge_pt: np.ndarray, cloth_center: np.ndarray, arm_key: str, label: str) -> Tuple[np.ndarray, float, int]:
        """Snap a geometric deep point to an actual sampled mask-board point.

        Returning the geometric point directly can draw MO/SIDE-PICK in a concavity or
        empty space.  This function keeps the point deep-internal but guarantees it is
        one of the board coordinates sampled from the planning mask.
        """
        desired = np.asarray(desired, dtype=np.float32).reshape(2)
        edge_pt = np.asarray(edge_pt, dtype=np.float32).reshape(2)
        cloth_center = np.asarray(cloth_center, dtype=np.float32).reshape(2)
        idxs = np.where(candidate_mask)[0] if candidate_mask is not None else np.arange(len(board))
        if len(idxs) == 0:
            return desired, -1.0, 0
        pts = board[idxs, :2].astype(np.float32)
        v_in = cloth_center - edge_pt
        n_in = float(np.linalg.norm(v_in))
        if n_in <= 1e-6:
            d = np.linalg.norm(pts - desired.reshape(1, 2), axis=1)
            j = int(np.argmin(d))
            return pts[j].astype(np.float32), float(d[j]), int(len(pts))
        u = v_in / n_in
        proj = (pts - edge_pt.reshape(1, 2)) @ u.reshape(2, 1)
        proj = proj.reshape(-1)
        target_proj = float(np.clip((desired - edge_pt) @ u, 0.0, n_in * 0.92))
        min_ratio = float(np.clip(getattr(args, "smart_reposition_min_projection_ratio", 0.42), 0.0, 0.88))
        min_proj = min(n_in * min_ratio, max(0.0, target_proj * 0.75))
        d_des = np.linalg.norm(pts - desired.reshape(1, 2), axis=1)
        snap_r = max(5.0, float(getattr(args, "smart_reposition_snap_radius_mm", 95.0)))
        ok = (proj >= min_proj) & (d_des <= snap_r)
        if int(np.count_nonzero(ok)) < 3:
            ok = (proj >= max(0.0, n_in * 0.25))
        if int(np.count_nonzero(ok)) < 1:
            ok = np.ones(len(pts), dtype=bool)
        cpts = pts[ok]
        cproj = proj[ok]
        cd = d_des[ok]
        score = cd + 0.35 * np.abs(cproj - target_proj) - 0.05 * cproj
        j = int(np.argmin(score))
        picked = cpts[j].astype(np.float32)
        support = float(np.linalg.norm(picked - desired))
        print(f"[SMART-MASK-SNAP] {label} {arm_key.upper()} desired=({desired[0]:.1f},{desired[1]:.1f}) -> mask=({picked[0]:.1f},{picked[1]:.1f}) support={support:.1f}mm candidates={int(np.count_nonzero(ok))}/{len(pts)}")
        return picked, support, int(np.count_nonzero(ok))

    def _coarse_eval_metrics_from_plan(plan: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        if plan is None:
            return None
        m = plan.get("metrics", {}) if isinstance(plan, dict) else {}
        feat = plan.get("features", {}) if isinstance(plan, dict) else {}
        board = feat.get("board", {}) if isinstance(feat, dict) else {}
        center_board = board.get("center")
        out = {
            "area_px": float(m.get("area_px", feat.get("area_px", 0.0)) or 0.0),
            "solidity": float(m.get("solidity", feat.get("solidity", 0.0)) or 0.0),
            "major_len_board": m.get("major_len_board", feat.get("major_len_board")),
            "minor_len_board": m.get("minor_len_board", feat.get("minor_len_board")),
            "x_separation": float(m.get("x_separation", 0.0) or 0.0),
            "y_diff": float(m.get("y_diff", 0.0) or 0.0),
            "axis_mode": str(m.get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?"))),
            "source": str(plan.get("candidate", {}).get("class_name", "?")),
            "center_board": center_board,
        }
        for key in ("major_len_board", "minor_len_board"):
            if out[key] is not None:
                try:
                    out[key] = float(out[key])
                except Exception:
                    out[key] = None
        return out

    def _pct_gain(after: Optional[float], before: Optional[float]) -> float:
        try:
            b = float(before)
            a = float(after)
            if abs(b) < 1e-6:
                return 0.0
            return 100.0 * (a - b) / b
        except Exception:
            return 0.0

    def _center_shift_mm(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> Optional[float]:
        try:
            cb = before.get("center_board") if before else None
            ca = after.get("center_board") if after else None
            if cb is None or ca is None:
                return None
            b = np.asarray(cb, dtype=np.float32).reshape(2)
            a = np.asarray(ca, dtype=np.float32).reshape(2)
            return float(np.linalg.norm(a - b))
        except Exception:
            return None

    def evaluate_spread_result(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]], action_meta: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        area_gain = _pct_gain(after.get("area_px") if after else None, before.get("area_px") if before else None)
        minor_gain = _pct_gain(after.get("minor_len_board") if after else None, before.get("minor_len_board") if before else None)
        major_gain = _pct_gain(after.get("major_len_board") if after else None, before.get("major_len_board") if before else None)
        sol_gain = 0.0
        try:
            sol_gain = float(after.get("solidity", 0.0)) - float(before.get("solidity", 0.0))
        except Exception:
            sol_gain = 0.0
        shift = _center_shift_mm(before, after)
        mode = str((action_meta or {}).get("mode", before.get("axis_mode", "?") if before else "?"))
        stretch_distance = float((action_meta or {}).get("stretch_distance", args.coarse_stretch_distance))
        try:
            ux = float((action_meta or {}).get("ux", 1.0))
            uy = float((action_meta or {}).get("uy", 0.0))
        except Exception:
            ux, uy = 1.0, 0.0
        x_dom_thr = float(args.coarse_eval_x_dominant_uy_threshold)
        if abs(uy) < x_dom_thr:
            direction_kind = "X_DOMINANT"
        elif abs(uy) > 0.68:
            direction_kind = "Y_DOMINANT"
        else:
            direction_kind = "DIAGONAL_Y"

        good = (area_gain >= float(args.coarse_eval_good_area_gain_pct)
                or minor_gain >= float(args.coarse_eval_good_minor_gain_pct)
                or sol_gain >= float(args.coarse_eval_good_solidity_gain))
        weak = (area_gain >= float(args.coarse_eval_weak_area_gain_pct)
                or minor_gain >= float(args.coarse_eval_weak_minor_gain_pct)
                or sol_gain > 0.015)
        bad_slide = (shift is not None
                     and shift >= float(args.coarse_eval_bad_center_shift_mm)
                     and area_gain < float(args.coarse_eval_weak_area_gain_pct)
                     and minor_gain < float(args.coarse_eval_weak_minor_gain_pct))
        if good:
            decision = "GOOD_CONTINUE"
        elif bad_slide:
            decision = "BAD_SLIDE_REDUCE_DISTANCE_OR_CHANGE_AXIS"
        elif weak:
            decision = "WEAK_TRY_ONCE_MORE_OR_CHANGE_AXIS"
        else:
            decision = "BAD_TRY_OTHER_AXIS"

        return {
            "created_at": time.time(),
            "before": before,
            "after": after,
            "action_meta": action_meta or {},
            "mode": mode,
            "stretch_distance": stretch_distance,
            "ux": float(ux),
            "uy": float(uy),
            "direction_kind": direction_kind,
            "area_gain_pct": float(area_gain),
            "minor_gain_pct": float(minor_gain),
            "major_gain_pct": float(major_gain),
            "solidity_gain": float(sol_gain),
            "center_shift_mm": shift,
            "decision": decision,
        }

    def print_spread_eval(ev: Optional[Dict[str, Any]] = None):
        ev = latest_spread_eval if ev is None else ev
        if not ev:
            print("[SPREAD-EVAL] no evaluation yet")
            return
        b = ev.get("before") or {}
        a = ev.get("after") or {}
        def fmt(v, nd=1):
            return "?" if v is None else f"{float(v):.{nd}f}"
        print("\n========== SPREAD EVAL ==========")
        print(f"mode={ev.get('mode','?')} direction={ev.get('direction_kind','?')} ux={ev.get('ux',0):+.2f} uy={ev.get('uy',0):+.2f} stretch={ev.get('stretch_distance',0):.1f}mm decision={ev.get('decision','?')}")
        print(f"before area={fmt(b.get('area_px'),0)}px minor={fmt(b.get('minor_len_board'))}mm major={fmt(b.get('major_len_board'))}mm solidity={fmt(b.get('solidity'),3)}")
        print(f"after  area={fmt(a.get('area_px'),0)}px minor={fmt(a.get('minor_len_board'))}mm major={fmt(a.get('major_len_board'))}mm solidity={fmt(a.get('solidity'),3)}")
        print(f"gain   area={ev.get('area_gain_pct',0):+.1f}% minor={ev.get('minor_gain_pct',0):+.1f}% major={ev.get('major_gain_pct',0):+.1f}% solidity={ev.get('solidity_gain',0):+.3f} center_shift={fmt(ev.get('center_shift_mm'))}mm")
        print("=================================\n")

    def _alternate_axis_for_direction(direction_kind: str, mode: str) -> str:
        """Choose one alternate policy for the next X action.
        This is a one-step exploration rule, not a permanent mode change.
        """
        d = str(direction_kind)
        m = str(mode)
        if d == "X_DOMINANT":
            return "board_y"
        if d in ("Y_DOMINANT", "DIAGONAL_Y"):
            return "board_x" if "board_y" in m else "minor"
        return "board_y" if "board_y" not in m else "minor"

    def update_adaptive_next_from_eval(ev: Dict[str, Any]):
        nonlocal coarse_action_axis_override, coarse_action_stretch_distance_override, coarse_weak_bad_streak, coarse_x_dominant_streak
        nonlocal coarse_last_direction_kind, coarse_same_direction_streak
        if not bool(args.coarse_eval_adaptive_next):
            return
        decision = str(ev.get("decision", ""))
        mode = str(ev.get("mode", "?"))
        direction_kind = str(ev.get("direction_kind", "?"))
        current_dist = float(ev.get("stretch_distance", get_effective_coarse_stretch_distance()))
        step = max(0.0, float(args.coarse_eval_stretch_step))
        dmin = float(args.coarse_eval_stretch_min)
        dmax = float(args.coarse_eval_stretch_max)

        if direction_kind == "X_DOMINANT":
            coarse_x_dominant_streak += 1
        else:
            coarse_x_dominant_streak = 0

        if coarse_last_direction_kind == direction_kind:
            coarse_same_direction_streak += 1
        else:
            coarse_last_direction_kind = direction_kind
            coarse_same_direction_streak = 1

        direction_limit = max(1, int(args.coarse_eval_direction_repeat_limit))
        repeated = coarse_same_direction_streak >= direction_limit
        weak_required = bool(args.coarse_eval_alternate_only_if_weak)
        is_weak_or_bad = not decision.startswith("GOOD")
        if (bool(args.coarse_eval_force_alternate_on_repeat)
                and repeated
                and ((not weak_required) or is_weak_or_bad)):
            alt = _alternate_axis_for_direction(direction_kind, mode)
            if alt != mode:
                coarse_action_axis_override = alt
                coarse_action_stretch_distance_override = max(dmin, min(dmax, current_dist))
                coarse_same_direction_streak = 0
                coarse_x_dominant_streak = 0
                print(f"[SPREAD-NEXT] Direction repeat: {direction_limit} consecutive {direction_kind}. Next X tries alternate axis={alt} once, stretch_distance={coarse_action_stretch_distance_override:.1f}mm")
                return

        if decision.startswith("GOOD"):
            coarse_weak_bad_streak = 0
            if bool(args.coarse_eval_alternate_once) and coarse_action_axis_override is not None:
                print(f"[SPREAD-NEXT] alternate axis={coarse_action_axis_override} was used once. Returning to normal minor-first policy next.")
                coarse_action_axis_override = None
            else:
                coarse_action_axis_override = None
            coarse_action_stretch_distance_override = min(dmax, max(dmin, current_dist + step * 0.5))
            print(f"[SPREAD-NEXT] GOOD: next stretch_distance={coarse_action_stretch_distance_override:.1f}mm, same_direction_streak={coarse_same_direction_streak}")
            return

        coarse_weak_bad_streak += 1
        if "SLIDE" in decision:
            coarse_action_stretch_distance_override = max(dmin, current_dist - step)
        else:
            coarse_action_stretch_distance_override = max(dmin, current_dist - step * 0.5)

        if coarse_weak_bad_streak >= max(1, int(args.coarse_eval_bad_repeat_limit)):
            coarse_action_axis_override = _alternate_axis_for_direction(direction_kind, mode)
            print(f"[SPREAD-NEXT] {decision}: weak/bad streak={coarse_weak_bad_streak}. Next X temporary axis_override={coarse_action_axis_override}, stretch_distance={coarse_action_stretch_distance_override:.1f}mm")
        else:
            print(f"[SPREAD-NEXT] {decision}: try one more with current policy. weak/bad streak={coarse_weak_bad_streak}, same_direction_streak={coarse_same_direction_streak}, next stretch_distance={coarse_action_stretch_distance_override:.1f}mm")


    def _perception_roi_mask(image_shape) -> Optional[np.ndarray]:
        """Strict perception ROI from the ArUco-board rectangle.

        Step_a52 policy:
          - garment YOLO, full-garment raw mask, fallback foreground, and pose preview
            should not see the side robot arms outside the ArUco rectangle;
          - robot planning was already board-clipped, but raw/full-garment masks were
            still full-frame/expanded and could treat the arms as clothing.
        """
        try:
            if not bool(getattr(args, "perception_roi_clip_to_aruco_board", True)):
                return None
            if latest_H is None:
                return None
            shrink_px = max(0, int(getattr(args, "perception_roi_board_shrink_px", 0)))
            mask = board_polygon_mask_from_h(latest_H, cfg, image_shape, shrink_px=shrink_px).astype(np.uint8)
            if int(np.count_nonzero(mask)) < 100:
                return None
            return mask
        except Exception:
            return None

    def _apply_perception_roi_to_frame(frame: np.ndarray) -> np.ndarray:
        """Black out pixels outside the ArUco-board perception ROI before inference."""
        try:
            roi = _perception_roi_mask(frame.shape)
            if roi is None:
                return frame
            out = frame.copy()
            out[roi <= 0] = 0
            return out
        except Exception:
            return frame

    def _clip_mask_to_perception_roi(mask_u8: Optional[np.ndarray], image_shape) -> Optional[np.ndarray]:
        """Clip any raw/full-garment mask to the same perception ROI."""
        try:
            if mask_u8 is None:
                return None
            roi = _perception_roi_mask(image_shape)
            if roi is None:
                return mask_u8
            return cv2.bitwise_and(mask_u8.astype(np.uint8), roi.astype(np.uint8))
        except Exception:
            return mask_u8

    def _pose_component_filter_mask(mask_u8: Optional[np.ndarray], pose_plan: Optional[Dict[str, Any]],
                                    image_shape, label: str) -> Tuple[Optional[np.ndarray], bool, str, Optional[np.ndarray]]:
        """A131: remove only fully disconnected mask islands with no pose keypoint.

        The original A119 mask is created first. Connected-components is then run on
        that exact binary mask without dilation or gap bridging. A component is removed
        only when it is fully independent and no valid pose keypoint overlaps it.
        If pose evidence is insufficient, the original A119 mask is preserved.
        """
        try:
            if mask_u8 is None:
                return None, False, f"{label}: no mask", None
            source = ((mask_u8.astype(np.uint8) > 0).astype(np.uint8) * 255)
            if not bool(getattr(args, "pose_component_noise_filter", True)):
                return source, False, f"{label}: filter disabled", None
            if not isinstance(pose_plan, dict):
                return source, False, f"{label}: skipped (no valid pose plan)", None
            raw_kpts = pose_plan.get("pose_keypoints_px", {})
            if not isinstance(raw_kpts, dict):
                return source, False, f"{label}: skipped (pose keypoints unavailable)", None

            h, w = image_shape[:2]
            points = []
            for _name, raw in raw_kpts.items():
                try:
                    x, y = float(raw[0]), float(raw[1])
                    if np.isfinite(x) and np.isfinite(y) and 0.0 <= x < w and 0.0 <= y < h:
                        points.append((int(round(x)), int(round(y))))
                except Exception:
                    continue
            min_kpts = max(1, int(getattr(args, "pose_component_noise_min_valid_kpts", 8)))
            if len(points) < min_kpts:
                return source, False, f"{label}: skipped (pose kpts={len(points)}<{min_kpts})", None

            n, labels, stats, _ = cv2.connectedComponentsWithStats((source > 0).astype(np.uint8), connectivity=8)
            component_count = max(0, int(n) - 1)
            if component_count <= 1:
                return source, False, f"{label}: one connected garment component", None

            radius = max(0, int(getattr(args, "pose_component_noise_kpt_radius_px", 10)))
            keep_labels = set()
            for x, y in points:
                x1, x2 = max(0, x - radius), min(w, x + radius + 1)
                y1, y2 = max(0, y - radius), min(h, y + radius + 1)
                if x1 >= x2 or y1 >= y2:
                    continue
                local = labels[y1:y2, x1:x2]
                if radius > 0:
                    yy, xx = np.ogrid[y1:y2, x1:x2]
                    circle = ((xx - x) ** 2 + (yy - y) ** 2) <= (radius ** 2)
                    vals = local[circle]
                else:
                    vals = local.reshape(-1)
                vals = vals[vals > 0]
                if vals.size > 0:
                    keep_labels.update(int(v) for v in np.unique(vals))

            # Fail safely when the pose points do not overlap the current mask at all.
            if not keep_labels:
                return source, False, f"{label}: skipped (no pose keypoint overlaps mask)", None

            filtered = np.zeros_like(source)
            removed = np.zeros_like(source)
            kept_parts = removed_parts = kept_area = removed_area = 0
            removed_details = []
            for lab in range(1, int(n)):
                comp = labels == lab
                area = int(stats[lab, cv2.CC_STAT_AREA])
                if lab in keep_labels:
                    filtered[comp] = 255
                    kept_parts += 1
                    kept_area += area
                else:
                    removed[comp] = 255
                    removed_parts += 1
                    removed_area += area
                    cx = int(stats[lab, cv2.CC_STAT_LEFT] + stats[lab, cv2.CC_STAT_WIDTH] / 2)
                    cy = int(stats[lab, cv2.CC_STAT_TOP] + stats[lab, cv2.CC_STAT_HEIGHT] / 2)
                    removed_details.append(f"{area}px@({cx},{cy})")

            if removed_parts <= 0:
                return source, False, f"{label}: all {component_count} components overlap pose keypoints", None
            if kept_area <= 80:
                return source, False, f"{label}: safety fallback (kept area too small {kept_area}px)", None

            detail = ",".join(removed_details[:6])
            status = (f"{label}: pose_kpts={len(points)} components={component_count} "
                      f"kept={kept_parts}/{kept_area}px removed={removed_parts}/{removed_area}px")
            if detail:
                status += f" [{detail}]"
            return filtered, True, status, removed
        except Exception as e:
            return mask_u8, False, f"{label}: filter error {repr(e)}", None

    def _rebuild_candidates_from_component_mask(mask_u8: np.ndarray,
                                                 source_candidates: List[Dict[str, Any]],
                                                 image_shape) -> List[Dict[str, Any]]:
        """Rebuild A119 candidate contours after disconnected noise removal."""
        try:
            contours, _ = cv2.findContours(
                ((mask_u8.astype(np.uint8) > 0).astype(np.uint8) * 255),
                cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE,
            )
            contours = sorted([c for c in contours if cv2.contourArea(c) > 50.0],
                              key=cv2.contourArea, reverse=True)
            if not contours:
                return []
            base = max(source_candidates, key=lambda c: float(c.get("area", 0.0) or 0.0)) if source_candidates else {}
            rebuilt = []
            for idx, cnt in enumerate(contours):
                cand = make_candidate_from_contour(
                    cnt, image_shape,
                    class_name=str(base.get("class_name", "garment")),
                    conf=float(base.get("conf", 0.0) or 0.0),
                    object_index=int(base.get("object_index", idx) or idx),
                    refine_candidates=bool(args.grasp_refine_candidates),
                    upper_band_ratio=float(args.grasp_upper_band_ratio),
                    inside_ratio=float(args.grasp_inside_ratio),
                    local_mask_radius=int(args.grasp_local_mask_radius),
                    min_local_mask_ratio=float(args.grasp_min_local_mask_ratio),
                    contour_smooth_epsilon_ratio=float(args.grasp_contour_smooth_epsilon_ratio),
                    debug=bool(args.grasp_debug or args.grasp_score_debug),
                )
                if cand is None:
                    continue
                cand["class_id"] = int(base.get("class_id", -1) or -1)
                cand["source"] = str(base.get("source", base.get("class_name", "garment"))) + "_POSE_COMPONENT_FILTERED"
                cand["pose_component_filtered"] = True
                rebuilt.append(cand)
            return rebuilt
        except Exception:
            return []

    def _pose_rotation_perception_failure(status: str) -> bool:
        """Return True only for pose-detection/keypoint failures worth retrying full-frame.

        Geometry, grip quality, workspace, pair-distance, path, and other safety failures
        are intentionally NOT retried here; those remain the existing ROTATE planner's job.
        """
        text = str(status or "").lower()
        return any(token in text for token in (
            "pose predict error",
            "no pose keypoints",
            "no pose instances",
            "cannot read pose xy",
            "missing required keypoints",
        ))

    def _pose_rotation_full_frame_mask_support(plan: Optional[Dict[str, Any]],
                                               mask_candidate: Optional[Dict[str, Any]],
                                               image_shape) -> Tuple[bool, Dict[str, Any]]:
        """Validate that a full-frame fallback pose belongs to the current garment mask.

        This is only an association check. It does not relax or replace any existing
        ROTATE grip/workspace/path validation.
        """
        info: Dict[str, Any] = {
            "ok": False, "support": 0, "inside_support": 0,
            "required_support": max(1, int(getattr(args, "pose_rotate_full_frame_min_kpt_support", 4))),
            "margin_px": max(0.0, float(getattr(args, "pose_rotate_full_frame_kpt_margin_px", 15.0))),
            "valid_pose_keypoints": 0,
            "reason": "not checked",
        }
        if not isinstance(plan, dict):
            info["reason"] = "no full-frame pose plan"
            return False, info
        if not isinstance(mask_candidate, dict) or mask_candidate.get("contour") is None:
            info["reason"] = "no current garment segmentation contour"
            return False, info
        raw_kpts = plan.get("pose_keypoints_px", {})
        if not isinstance(raw_kpts, dict) or not raw_kpts:
            info["reason"] = "full-frame pose has no valid keypoints"
            return False, info
        try:
            contour = np.asarray(mask_candidate.get("contour"), dtype=np.int32)
            if contour.ndim == 2:
                contour = contour.reshape(-1, 1, 2)
            if contour.size < 6 or float(cv2.contourArea(contour)) <= 50.0:
                info["reason"] = "current garment segmentation contour invalid"
                return False, info
            h, w = image_shape[:2]
            margin = float(info["margin_px"])
            support = 0
            inside_support = 0
            valid = 0
            for _name, raw in raw_kpts.items():
                try:
                    x, y = float(raw[0]), float(raw[1])
                except Exception:
                    continue
                if not np.isfinite(x) or not np.isfinite(y) or not (0.0 <= x < w and 0.0 <= y < h):
                    continue
                valid += 1
                signed = float(cv2.pointPolygonTest(contour, (x, y), True))
                if signed >= 0.0:
                    inside_support += 1
                    support += 1
                elif signed >= -margin:
                    support += 1
            info["support"] = int(support)
            info["inside_support"] = int(inside_support)
            info["valid_pose_keypoints"] = int(valid)
            info["ok"] = bool(support >= int(info["required_support"]))
            info["reason"] = (
                f"pose-mask support={support}/{valid} inside={inside_support} "
                f"required>={int(info['required_support'])} margin={margin:.1f}px"
            )
            return bool(info["ok"]), info
        except Exception as e:
            info["reason"] = f"pose-mask support check error: {repr(e)}"
            return False, info

    def _fallback_color_fresh_pose_support(plan: Optional[Dict[str, Any]],
                                           mask_candidate: Optional[Dict[str, Any]],
                                           image_shape) -> Tuple[bool, Dict[str, Any]]:
        """vla_0842: strict association gate for 45..58% fallback_color masks.

        Only fresh Pose outputs from the current snapshot are accepted. Mask-axis and
        last-valid-pose recovery objects are intentionally excluded from this gate.
        """
        info: Dict[str, Any] = {
            "ok": False, "support": 0, "inside_support": 0, "valid_pose_keypoints": 0,
            "required_support": max(1, int(getattr(args, "fallback_color_pose_min_kpt_support", 6))),
            "required_ratio": float(np.clip(getattr(args, "fallback_color_pose_min_support_ratio", 0.60), 0.0, 1.0)),
            "margin_px": max(0.0, float(getattr(args, "fallback_color_pose_kpt_margin_px", 15.0))),
            "pose_source": "NONE", "reason": "not checked",
        }
        if not isinstance(plan, dict):
            info["reason"] = "no fresh pose plan"
            return False, info
        pose_source = str(plan.get("pose_inference_source") or "").upper()
        info["pose_source"] = pose_source or "UNKNOWN"
        if pose_source not in {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK"}:
            info["reason"] = f"non-fresh pose source={pose_source or 'UNKNOWN'}"
            return False, info
        if not isinstance(mask_candidate, dict) or mask_candidate.get("contour") is None:
            info["reason"] = "conditional color contour missing"
            return False, info
        raw_kpts = plan.get("pose_keypoints_px", {})
        if not isinstance(raw_kpts, dict) or not raw_kpts:
            info["reason"] = "fresh pose has no keypoints"
            return False, info
        try:
            contour = np.asarray(mask_candidate.get("contour"), dtype=np.int32)
            if contour.ndim == 2:
                contour = contour.reshape(-1, 1, 2)
            if contour.size < 6 or float(cv2.contourArea(contour)) <= 50.0:
                info["reason"] = "conditional color contour invalid"
                return False, info
            h, w = image_shape[:2]
            margin = float(info["margin_px"])
            support = inside = valid = 0
            for _name, raw in raw_kpts.items():
                try:
                    x, y = float(raw[0]), float(raw[1])
                except Exception:
                    continue
                if not np.isfinite(x) or not np.isfinite(y) or not (0.0 <= x < w and 0.0 <= y < h):
                    continue
                valid += 1
                signed = float(cv2.pointPolygonTest(contour, (x, y), True))
                if signed >= 0.0:
                    inside += 1
                    support += 1
                elif signed >= -margin:
                    support += 1
            ratio = float(support) / float(max(1, valid))
            info.update({
                "support": int(support), "inside_support": int(inside),
                "valid_pose_keypoints": int(valid), "support_ratio": float(ratio),
            })
            ok = bool(
                valid > 0
                and support >= int(info["required_support"])
                and ratio >= float(info["required_ratio"])
            )
            info["ok"] = ok
            info["reason"] = (
                f"fresh_pose_mask support={support}/{valid} ratio={ratio:.2f} inside={inside} "
                f"required>={int(info['required_support'])} ratio>={float(info['required_ratio']):.2f} "
                f"margin={margin:.1f}px source={info['pose_source']}"
            )
            return ok, info
        except Exception as exc:
            info["reason"] = f"fresh pose-mask support check error: {repr(exc)}"
            return False, info

    def run_yolo_on_snapshot(src_frame: np.ndarray, reason: str = "snapshot"):
        nonlocal latest_candidates, latest_candidate, latest_point, latest_dual_plan, latest_dual_status, latest_coarse_plan, latest_coarse_status, latest_fallback_status, latest_segmentation_source, latest_pose_rotation_plan, latest_pose_rotation_status, snapshot_canvas
        nonlocal latest_full_garment_mask, latest_full_garment_status, latest_yolo_raw_mask, latest_yolo_raw_status
        nonlocal fallback_last_trusted_area_px
        nonlocal inference_serial, snapshot_ready, snapshot_frame, snapshot_raw_frame
        nonlocal wait_cloth_after_no_candidates, no_candidate_baseline_gray
        nonlocal snapshot_reference_gray, snapshot_foreground_state, target_stale_frames, target_removed_frames, target_changed_frames, target_stale_armed_at
        nonlocal stable_prev_gray, stable_since, stable_low_motion_frames
        nonlocal fallback_empty_gray, fallback_empty_lab, fallback_empty_raw_gray, fallback_empty_frame_count

        _a140_latency_mark("inference_start", inference_reason=str(reason))
        src_infer = _apply_perception_roi_to_frame(src_frame)
        roi_active = bool(getattr(args, "perception_roi_clip_to_aruco_board", True)) and latest_H is not None
        if roi_active and bool(getattr(args, "fallback_print_debug", False)):
            print("[PERCEPTION-ROI] ArUco-board ROI applied before YOLO/fallback/pose perception")

        canvas, candidates = infer_grasp_candidates(
            grasp_model,
            src_infer,
            conf=args.grasp_conf,
            imgsz=args.grasp_imgsz,
            classes=grasp_classes,
            no_filter=args.grasp_no_filter,
            debug=args.grasp_debug,
            refine_candidates=args.grasp_refine_candidates,
            upper_band_ratio=args.grasp_upper_band_ratio,
            inside_ratio=args.grasp_inside_ratio,
            local_mask_radius=args.grasp_local_mask_radius,
            min_local_mask_ratio=args.grasp_min_local_mask_ratio,
            contour_smooth_epsilon_ratio=args.grasp_contour_smooth_epsilon_ratio,
            score_debug=args.grasp_score_debug,
        )
        # Preserve the original A119 YOLO candidates. The A131 validation below
        # runs only after the normal YOLO/fallback mask has been created.
        raw_full_frame_candidates = list(candidates)
        # fallback_color in the 45..58% band is not trusted yet. It may
        # participate in SAME-snapshot Pose association only; no planner receives it
        # until the fresh Pose/mask validation below explicitly promotes it.
        conditional_color_candidate: Optional[Dict[str, Any]] = None
        latest_fallback_status = "not used"
        latest_segmentation_source = "YOLO" if len(candidates) > 0 else "NONE"
        if len(candidates) > 0:
            try:
                fallback_last_trusted_area_px = float(max(
                    float(c.get("area", c.get("area_px", 0.0)) or 0.0) for c in candidates
                ))
            except Exception:
                pass
        if len(candidates) == 0 and args.fallback_object_mask:
            refine_kwargs = {
                "refine_candidates": args.grasp_refine_candidates,
                "upper_band_ratio": args.grasp_upper_band_ratio,
                "inside_ratio": args.grasp_inside_ratio,
                "local_mask_radius": args.grasp_local_mask_radius,
                "min_local_mask_ratio": args.grasp_min_local_mask_ratio,
                "contour_smooth_epsilon_ratio": args.grasp_contour_smooth_epsilon_ratio,
                "debug": args.grasp_debug or args.grasp_score_debug,
            }
            fb_canvas, fb_candidates, fb_status = fallback_object_mask_candidates(
                src_infer, cfg, latest_H, fallback_empty_gray,
                diff_threshold=args.fallback_diff_threshold,
                color_threshold=args.fallback_color_threshold,
                min_area_px=args.fallback_min_area_px,
                max_area_ratio=args.fallback_max_area_ratio,
                morph_kernel=args.fallback_morph_kernel,
                board_shrink_px=args.fallback_board_shrink_px,
                refine_kwargs=refine_kwargs,
                debug=args.fallback_print_debug,
                trusted_area_px=fallback_last_trusted_area_px,
                color_board_coverage_limit=float(getattr(args, "fallback_color_board_coverage_soft_limit", 0.45)),
                color_board_coverage_pose_max=float(getattr(args, "fallback_color_board_coverage_pose_max", 0.58)),
                empty_baseline_suspect_diff_mean_max=float(getattr(args, "fallback_empty_baseline_suspect_diff_mean_max", 4.0)),
                empty_baseline_suspect_fg_ratio_max=float(getattr(args, "fallback_empty_baseline_suspect_fg_ratio_max", 0.02)),
                empty_baseline_suspect_color_coverage_min=float(getattr(args, "fallback_empty_baseline_suspect_color_coverage_min", 0.15)),
            )
            latest_fallback_status = fb_status
            if len(fb_candidates) > 0:
                canvas, candidates = fb_canvas, fb_candidates
                if bool(fb_candidates[0].get("fallback_empty_baseline_suspect", False)):
                    print(f"[EMPTY_BASELINE_SUSPECT] {fb_candidates[0].get('fallback_empty_baseline_diag', '')} | diagnostic_only=True")
                source_name = str(fb_candidates[0].get("source", fb_candidates[0].get("class_name", "fallback"))).lower()
                if "fallback_bgdiff" in source_name:
                    latest_segmentation_source = "FALLBACK_BGDIFF"
                    try:
                        fallback_last_trusted_area_px = float(
                            fb_candidates[0].get("area", fb_candidates[0].get("area_px", 0.0)) or 0.0
                        )
                    except Exception:
                        pass
                else:
                    if bool(fb_candidates[0].get("fallback_color_pose_validation_required", False)):
                        conditional_color_candidate = fb_candidates[0]
                        latest_segmentation_source = "FALLBACK_COLOR_PENDING_POSE"
                        print(
                            f"[FALLBACK-COLOR-PENDING-POSE] boardCoverage="
                            f"{float(conditional_color_candidate.get('fallback_color_board_coverage', 0.0)):.3f}; "
                            "candidate is held from planners until fresh same-snapshot Pose validation"
                        )
                    else:
                        latest_segmentation_source = "FALLBACK_COLOR"
                if isinstance(conditional_color_candidate, dict):
                    print(f"[FALLBACK] conditional object mask detected after YOLO miss: {fb_status}")
                else:
                    print(f"[FALLBACK] object mask used because YOLO returned no garment candidates: {fb_status}")
            else:
                if str(fb_status).startswith("MASK_SUSPECT"):
                    latest_segmentation_source = "MASK_SUSPECT_FALLBACK_COLOR"
                    print(f"[MASK-SUSPECT] fallback_color rejected; planner receives no mask/target: {fb_status}")
                else:
                    latest_segmentation_source = "NONE"
                print(f"[FALLBACK] object mask not ready: {fb_status}")
                if fallback_empty_gray is None and args.fallback_auto_empty_baseline:
                    fallback_empty_gray = cv2.cvtColor(src_frame, cv2.COLOR_BGR2GRAY).astype(np.float32)
                    fallback_empty_lab = cv2.cvtColor(src_frame, cv2.COLOR_BGR2LAB).astype(np.float32)
                    if isinstance(snapshot_raw_frame, np.ndarray):
                        fallback_empty_raw_gray = cv2.cvtColor(snapshot_raw_frame, cv2.COLOR_BGR2GRAY).astype(np.float32)
                    fallback_empty_frame_count += 1
                    print("[FALLBACK] empty-board baseline captured from this no-candidate frame. "
                          "For best results, start once with an empty board or press E on an empty board.")
                    print("[LAB-EMPTY] Auto baseline Lab image saved from no-candidate frame.")
        _a140_latency_mark("segmentation_complete")
        latest_pose_rotation_plan = None
        latest_pose_rotation_status = "pose disabled"
        if pose_model is not None and (bool(args.pose_rotation_preview) or bool(getattr(args, "pose_component_noise_filter", True))):
            # critical ordering fix: ROTATE must see the same trusted planning-mask
            # sanitation used by physical planners.  In v5 the Pose/ROTATE block ran
            # before the normal sanitation pass, so FALLBACK_BGDIFF could never carry
            # the required +board_clipped+lab_checked provenance and was rejected even
            # when its mask was good.  Sanitize a ROTATE-only copy here; keep the raw
            # candidate list untouched for the existing A131 component-filter pipeline.
            pose_rotation_candidates = sanitize_candidates_for_planning(
                list(candidates), src_frame, reason=f"{reason}:rotate_pose"
            )
            mask_ref_for_pose = (
                max(pose_rotation_candidates, key=lambda c: float(c.get("area", c.get("area_px", 0.0))))
                if pose_rotation_candidates else None
            )
            if isinstance(mask_ref_for_pose, dict):
                print(
                    f"[POSE-ROT-MASK] source={mask_ref_for_pose.get('source', mask_ref_for_pose.get('class_name'))} "
                    f"lab={mask_ref_for_pose.get('lab_veto_status','')} area={float(mask_ref_for_pose.get('area',mask_ref_for_pose.get('area_px',0.0)) or 0.0):.0f}px"
                )
            pose_canvas, pose_plan, pose_status = infer_tshirt_pose_rotation_plan(
                pose_model, src_infer, latest_H, cfg,
                imgsz=int(args.pose_imgsz), conf=float(args.pose_conf), kpt_conf=float(args.pose_kpt_conf),
                target_axis_deg=float(args.pose_target_axis_deg),
                target_axis_mode=str(getattr(args, "pose_target_axis_mode", "auto_nearest")),
                deadband_deg=float(args.pose_rotate_deadband_deg),
                max_delta_deg=float(args.pose_rotate_max_delta_deg),
                gain=float(args.pose_rotate_gain),
                min_axis_len_mm=float(args.pose_rotate_min_axis_len_mm),
                min_grip_keypoints_per_side=int(getattr(args, "pose_rotate_min_grip_keypoints_per_side", 2)),
                initial_min_pair_distance_mm=float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)),
                workspace_grip_retarget=bool(getattr(args, "pose_rotate_inward_grip_retry", True)),
                workspace_grip_step_mm=float(getattr(args, "pose_rotate_inward_grip_step_mm", 20.0)),
                workspace_grip_max_mm=float(getattr(args, "pose_rotate_inward_grip_max_mm", 60.0)),
                workspace_grip_id02_fallback=bool(getattr(args, "pose_rotate_id02_grip_fallback", True)),
                allow_soft_workspace_overlap=bool(getattr(args, "pose_rotate_soft_workspace_overlap", True)),
                soft_workspace_min_pair_distance_mm=float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)),
                soft_workspace_min_x_order_gap_mm=float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)),
                base_canvas=canvas,
                mask_candidate=mask_ref_for_pose,
                mask_direction_check=bool(getattr(args, "pose_mask_direction_check", False)),
                mask_direction_max_diff_deg=float(getattr(args, "pose_mask_direction_max_diff_deg", 55.0)),
                mask_direction_axis_mode=str(getattr(args, "pose_mask_direction_axis_mode", "either")),
                mask_direction_min_axis_ratio=float(getattr(args, "pose_mask_direction_min_axis_ratio", 1.12)),
                mask_direction_min_len_mm=float(getattr(args, "pose_mask_direction_min_len_mm", 90.0)),
                mask_direction_policy=str(getattr(args, "pose_mask_direction_policy", "warn")),
            )
            primary_pose_status = str(pose_status)
            if isinstance(pose_plan, dict):
                pose_plan["pose_inference_source"] = "ARUCO_ROI_PRIMARY"
                pose_plan["pose_primary_status"] = primary_pose_status

            # when the ROI-blackout itself causes pose perception to fail,
            # retry only pose inference on the SAME corrected full-frame snapshot. The
            # result must still belong to the current garment segmentation before it is
            # allowed to enter the unchanged ROTATE planner/safety pipeline.
            if (
                pose_plan is None
                and bool(getattr(args, "pose_rotate_full_frame_fallback", True))
                and _pose_rotation_perception_failure(primary_pose_status)
                and isinstance(src_frame, np.ndarray) and src_frame.size > 0
            ):
                print(f"[ROTATE-POSE-FAILED] source=ARUCO_ROI_PRIMARY status={primary_pose_status}")
                print(f"[POSE-ROT-FULL-FRAME] primary ROI pose failed: {primary_pose_status}; retry same snapshot full-frame")
                fb_canvas, fb_plan, fb_status = infer_tshirt_pose_rotation_plan(
                    pose_model, src_frame, latest_H, cfg,
                    imgsz=int(args.pose_imgsz), conf=float(args.pose_conf), kpt_conf=float(args.pose_kpt_conf),
                    target_axis_deg=float(args.pose_target_axis_deg),
                    target_axis_mode=str(getattr(args, "pose_target_axis_mode", "auto_nearest")),
                    deadband_deg=float(args.pose_rotate_deadband_deg),
                    max_delta_deg=float(args.pose_rotate_max_delta_deg),
                    gain=float(args.pose_rotate_gain),
                    min_axis_len_mm=float(args.pose_rotate_min_axis_len_mm),
                    min_grip_keypoints_per_side=int(getattr(args, "pose_rotate_min_grip_keypoints_per_side", 2)),
                    initial_min_pair_distance_mm=float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)),
                    workspace_grip_retarget=bool(getattr(args, "pose_rotate_inward_grip_retry", True)),
                    workspace_grip_step_mm=float(getattr(args, "pose_rotate_inward_grip_step_mm", 20.0)),
                    workspace_grip_max_mm=float(getattr(args, "pose_rotate_inward_grip_max_mm", 60.0)),
                    workspace_grip_id02_fallback=bool(getattr(args, "pose_rotate_id02_grip_fallback", True)),
                    allow_soft_workspace_overlap=bool(getattr(args, "pose_rotate_soft_workspace_overlap", True)),
                    soft_workspace_min_pair_distance_mm=float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)),
                    soft_workspace_min_x_order_gap_mm=float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)),
                    base_canvas=canvas,
                    mask_candidate=mask_ref_for_pose,
                    mask_direction_check=bool(getattr(args, "pose_mask_direction_check", False)),
                    mask_direction_max_diff_deg=float(getattr(args, "pose_mask_direction_max_diff_deg", 55.0)),
                    mask_direction_axis_mode=str(getattr(args, "pose_mask_direction_axis_mode", "either")),
                    mask_direction_min_axis_ratio=float(getattr(args, "pose_mask_direction_min_axis_ratio", 1.12)),
                    mask_direction_min_len_mm=float(getattr(args, "pose_mask_direction_min_len_mm", 90.0)),
                    mask_direction_policy=str(getattr(args, "pose_mask_direction_policy", "warn")),
                )
                support_ok, support_info = _pose_rotation_full_frame_mask_support(
                    fb_plan, mask_ref_for_pose, src_frame.shape
                )
                if isinstance(fb_plan, dict) and support_ok:
                    fb_plan["pose_inference_source"] = "FULL_FRAME_FALLBACK"
                    fb_plan["pose_primary_status"] = primary_pose_status
                    fb_plan["full_frame_mask_support"] = copy.deepcopy(support_info)
                    pose_plan = fb_plan
                    pose_canvas = fb_canvas
                    pose_status = f"{fb_status} | FULL_FRAME_FALLBACK_ACCEPTED | {support_info.get('reason')}"
                    print(f"[POSE-ROT-FULL-FRAME-ACCEPT] {pose_status}")
                else:
                    pose_status = primary_pose_status
                    print(
                        f"[POSE-ROT-FULL-FRAME-REJECT] fallback_status={fb_status} "
                        f"association={support_info.get('reason')} | keep primary failure"
                    )
                    print(f"[ROTATE-POSE-FAILED] source=FULL_FRAME_FALLBACK status={fb_status} association={support_info.get('reason')}")

            # 45..58% fallback_color is provisional until this exact
            # snapshot's FRESH Pose agrees with the same contour. Do this before any
            # stale-Pose/mask-axis recovery can substitute for fresh evidence.
            if isinstance(conditional_color_candidate, dict):
                pose_mask_ok, pose_mask_info = _fallback_color_fresh_pose_support(
                    pose_plan, conditional_color_candidate, src_frame.shape
                )
                coverage = float(conditional_color_candidate.get("fallback_color_board_coverage", 0.0) or 0.0)
                if pose_mask_ok:
                    conditional_color_candidate["fallback_color_pose_validated"] = True
                    conditional_color_candidate["fallback_color_pose_validation"] = copy.deepcopy(pose_mask_info)
                    latest_segmentation_source = "FALLBACK_COLOR_POSE_VALIDATED"
                    latest_fallback_status = (
                        f"OK fallback_color POSE_VALIDATED boardCoverage={coverage:.3f} | "
                        f"{pose_mask_info.get('reason')}"
                    )
                    print(f"[FALLBACK-COLOR-POSE-ACCEPT] {latest_fallback_status}")
                    conditional_color_candidate = None
                else:
                    reject_reason = (
                        f"MASK_SUSPECT fallback_color REJECTED_AFTER_POSE boardCoverage={coverage:.3f} | "
                        f"{pose_mask_info.get('reason')}"
                    )
                    latest_fallback_status = reject_reason
                    latest_segmentation_source = "MASK_SUSPECT_FALLBACK_COLOR"
                    candidates = []
                    pose_plan = None
                    pose_status = str(pose_status) + " | FALLBACK_COLOR_POSE_REJECTED"
                    try:
                        cv2.putText(pose_canvas, "FALLBACK COLOR REJECTED: POSE/MASK MISMATCH", (25, 175),
                                    cv2.FONT_HERSHEY_SIMPLEX, 0.55, (0, 0, 0), 4)
                        cv2.putText(pose_canvas, "FALLBACK COLOR REJECTED: POSE/MASK MISMATCH", (25, 175),
                                    cv2.FONT_HERSHEY_SIMPLEX, 0.55, (0, 0, 255), 2)
                    except Exception:
                        pass
                    print(f"[FALLBACK-COLOR-POSE-REJECT] planner receives no mask/target: {reject_reason}")
                    conditional_color_candidate = None

            # transient pose-loss recovery.  Fresh rejudgments are allowed
            # to fail a bounded number of times before any stale information is reused.
            # The last-valid pose is reusable only if NO garment motion occurred since it
            # was captured.  A mask-axis fallback is the final conservative backup.
            motion_now = int(auto_x_ready_cycle.get("garment_motion_count", 0) or 0)
            prior_retry_fail_count = int(pose_rotation_recovery_cache.get("retry_fail_count", 0) or 0)
            prior_retry_motion_count = int(pose_rotation_recovery_cache.get("retry_motion_count", -1))
            if isinstance(pose_plan, dict):
                if prior_retry_fail_count > 0 and prior_retry_motion_count == motion_now:
                    # this successful observation IS the one allowed fresh Pose
                    # retry.  Remember that the retry was consumed until garment motion.
                    # Do not reset A140's generic rejudge counter here; changing to a
                    # fallback/Late label must not restart a same-scene auto loop.
                    pose_rotation_recovery_cache["fresh_pose_retry_spent_motion_count"] = motion_now
                    pose_rotation_recovery_cache["confirmation_budget_source"] = str(pose_plan.get("pose_inference_source", "POSE"))
                    pose_rotation_recovery_cache["confirmation_budget_inference_serial"] = int(inference_serial)
                    print(
                        f"[ROTATE-POSE-RETRY-LATCH] motion={motion_now} fresh retry consumed by successful "
                        f"source={pose_rotation_recovery_cache['confirmation_budget_source']}; no same-motion Pose retry reopen"
                    )
                pose_rotation_recovery_cache["last_valid_plan"] = copy.deepcopy(pose_plan)
                pose_rotation_recovery_cache["last_valid_motion_count"] = motion_now
                pose_rotation_recovery_cache["last_valid_inference_serial"] = int(inference_serial)
                pose_rotation_recovery_cache["last_valid_source"] = str(pose_plan.get("pose_inference_source", "POSE"))
                pose_rotation_recovery_cache["consecutive_perception_failures"] = 0
                pose_rotation_recovery_cache["failure_motion_count"] = motion_now
                pose_rotation_recovery_cache["retry_pending"] = False
                pose_rotation_recovery_cache["retry_fail_count"] = 0
                pose_rotation_recovery_cache["retry_fail_need"] = max(1, int(getattr(args, "pose_rotate_transient_fail_observations", 2)))
                pose_rotation_recovery_cache["retry_motion_count"] = motion_now
                pose_rotation_recovery_cache["retry_reason"] = "pose available"
                pose_rotation_recovery_cache["retry_exhausted"] = False
                print(
                    f"[POSE-ROT-CACHE-SAVE] motion={motion_now} source={pose_rotation_recovery_cache['last_valid_source']} "
                    f"axis={float(pose_plan.get('current_axis_deg',0.0)):+.1f}deg"
                )
            elif _pose_rotation_perception_failure(primary_pose_status):
                if int(pose_rotation_recovery_cache.get("failure_motion_count", -1)) != motion_now:
                    pose_rotation_recovery_cache["consecutive_perception_failures"] = 0
                    pose_rotation_recovery_cache["failure_motion_count"] = motion_now
                    pose_rotation_recovery_cache["retry_pending"] = False
                    pose_rotation_recovery_cache["retry_exhausted"] = False
                fail_need = max(1, int(getattr(args, "pose_rotate_transient_fail_observations", 2)))
                # required default=2 means exactly: current failed observation (#1)
                # + ONE scheduled fresh observation (#2).  Once exhausted on the same
                # garment motion, later manual/ordinary observations may re-test the
                # mask fallback but may never become failure=3/2 or schedule another
                # Pose retry.
                consensus_kind_now = str(auto_x_rotation_state.get("consensus_kind") or "")
                low_trust_confirm_pending = bool(
                    ("MASK_AXIS_FALLBACK" in consensus_kind_now
                     or "MASK_SHAPE_FALLBACK" in consensus_kind_now
                     or "LAST_VALID_POSE_CACHE" in consensus_kind_now)
                    and int(pose_rotation_recovery_cache.get("retry_motion_count", motion_now) or motion_now) == motion_now
                )
                fresh_retry_spent_same_motion = bool(
                    int(pose_rotation_recovery_cache.get("fresh_pose_retry_spent_motion_count", -1)) == motion_now
                )
                already_exhausted_same_motion = bool(
                    fresh_retry_spent_same_motion and not low_trust_confirm_pending
                )
                effective_fail_need = 1 if low_trust_confirm_pending else fail_need
                if already_exhausted_same_motion:
                    fail_n = int(max(1, fail_need))
                    pose_rotation_recovery_cache["consecutive_perception_failures"] = fail_n
                    print(
                        f"[ROTATE-POSE-RETRY-EXHAUSTED-STABLE] motion={motion_now} "
                        f"failure remains {fail_n}/{fail_need}; no additional fresh Pose retry will be scheduled"
                    )
                else:
                    fail_n = min(
                        int(max(1, effective_fail_need)),
                        int(pose_rotation_recovery_cache.get("consecutive_perception_failures", 0) or 0) + 1,
                    )
                    pose_rotation_recovery_cache["consecutive_perception_failures"] = fail_n
                pose_rotation_recovery_cache["retry_fail_count"] = fail_n
                pose_rotation_recovery_cache["retry_fail_need"] = effective_fail_need
                pose_rotation_recovery_cache["retry_motion_count"] = motion_now
                pose_rotation_recovery_cache["retry_reason"] = str(primary_pose_status)
                pose_rotation_recovery_cache["retry_pending"] = bool((not already_exhausted_same_motion) and fail_n < effective_fail_need)
                pose_rotation_recovery_cache["retry_exhausted"] = bool(fail_n >= effective_fail_need)
                if low_trust_confirm_pending:
                    print("[ROTATE-FALLBACK-CONFIRM-OBS] pending cache/mask fallback confirmation; rebuild fallback on this one fresh confirmation frame")
                print(f"[POSE-ROT-TRANSIENT-FAIL] fresh failure={fail_n}/{effective_fail_need} motion={motion_now} status={primary_pose_status}")
                print(f"[ROTATE-POSE-RETRY] POSE_FAILED failure={fail_n}/{effective_fail_need} motion={motion_now} pending={bool(pose_rotation_recovery_cache.get('retry_pending',False))}")

                if fail_n >= effective_fail_need:
                    pose_rotation_recovery_cache["retry_pending"] = False
                    if not low_trust_confirm_pending:
                        pose_rotation_recovery_cache["fresh_pose_retry_spent_motion_count"] = motion_now
                        print(
                            f"[ROTATE-POSE-RETRY-LATCH] motion={motion_now} current+fresh Pose budget exhausted "
                            f"at failure={fail_n}/{effective_fail_need}; retry stays closed until garment motion"
                        )
                    cached = pose_rotation_recovery_cache.get("last_valid_plan")
                    cached_motion = int(pose_rotation_recovery_cache.get("last_valid_motion_count", -1))
                    if (bool(getattr(args, "pose_rotate_last_valid_reuse", True))
                            and isinstance(cached, dict) and cached_motion == motion_now):
                        cache_ok, cache_info = _pose_rotation_full_frame_mask_support(cached, mask_ref_for_pose, src_frame.shape)
                        if cache_ok:
                            pose_plan = copy.deepcopy(cached)
                            pose_plan["pose_inference_source"] = "LAST_VALID_POSE_CACHE"
                            pose_plan["pose_primary_status"] = primary_pose_status
                            pose_plan["pose_cache_motion_count"] = motion_now
                            pose_plan["pose_cache_source_inference_serial"] = int(pose_rotation_recovery_cache.get("last_valid_inference_serial", -1))
                            pose_plan["pose_cache_mask_support"] = copy.deepcopy(cache_info)
                            pose_status = (f"POSE CACHE REUSE after {fail_n} fresh failures | "
                                           f"same_motion={motion_now} | {cache_info.get('reason')}")
                            pose_canvas = canvas.copy()
                            pose_rotation_recovery_cache["consecutive_perception_failures"] = 0
                            pose_rotation_recovery_cache["retry_pending"] = False
                            pose_rotation_recovery_cache["retry_fail_count"] = 0
                            # Restore the normal current+one-fresh Pose budget after the
                            # low-trust confirmation frame; do not leave retry_fail_need=1.
                            pose_rotation_recovery_cache["retry_fail_need"] = max(1, int(getattr(args, "pose_rotate_transient_fail_observations", 2)))
                            pose_rotation_recovery_cache["retry_reason"] = "LAST_VALID_POSE_CACHE accepted"
                            pose_rotation_recovery_cache["retry_exhausted"] = False
                            if not low_trust_confirm_pending:
                                pose_rotation_recovery_cache["confirmation_budget_source"] = "LAST_VALID_POSE_CACHE"
                                pose_rotation_recovery_cache["confirmation_budget_inference_serial"] = int(inference_serial)
                                print(
                                    f"[ROTATE-FALLBACK-CONFIRM-ARMED] source=LAST_VALID_POSE_CACHE "
                                    f"after failure={fail_n}/{effective_fail_need}; generic rejudge counter is NOT reset"
                                )
                            print(f"[POSE-ROT-CACHE-REUSE] {pose_status}")
                        else:
                            print(f"[POSE-ROT-CACHE-REJECT] same-motion cache failed current-mask association: {cache_info.get('reason')}")
                    elif isinstance(cached, dict):
                        print(
                            f"[POSE-ROT-CACHE-REJECT] garment moved since cache: cached_motion={cached_motion} current_motion={motion_now}"
                        )

                    if pose_plan is None and bool(getattr(args, "pose_rotate_mask_axis_fallback", True)):
                        mask_plan, mask_status = build_mask_axis_rotation_fallback(
                            mask_ref_for_pose, latest_H, cfg, history_plan=(cached if isinstance(cached, dict) else None),
                            target_axis_deg=float(args.pose_target_axis_deg),
                            target_axis_mode=str(getattr(args, "pose_target_axis_mode", "auto_nearest")),
                            deadband_deg=float(args.pose_rotate_deadband_deg),
                            max_delta_deg=float(args.pose_rotate_max_delta_deg),
                            gain=float(args.pose_rotate_gain),
                            min_axis_ratio=float(getattr(args, "pose_rotate_mask_axis_min_ratio", 1.20)),
                            min_axis_len_mm=float(getattr(args, "pose_rotate_mask_axis_min_len_mm", 140.0)),
                            history_max_diff_deg=float(getattr(args, "pose_rotate_mask_axis_history_max_diff_deg", 40.0)),
                            shape_fallback_enable=bool(getattr(args, "pose_rotate_mask_shape_fallback", True)),
                            shape_min_end_asym=float(getattr(args, "pose_rotate_mask_shape_min_end_asym", 1.12)),
                            shape_min_half_width_ratio=float(getattr(args, "pose_rotate_mask_shape_min_half_width_ratio", 1.10)),
                            shape_min_axis_asym_margin=float(getattr(args, "pose_rotate_mask_shape_min_axis_asym_margin", 0.06)),
                        )
                        if isinstance(mask_plan, dict):
                            pose_plan = mask_plan
                            pose_canvas = canvas.copy()
                            pose_status = str(mask_status)
                            fallback_source = str(mask_plan.get("pose_inference_source") or "MASK_AXIS_FALLBACK").upper()
                            pose_rotation_recovery_cache["consecutive_perception_failures"] = 0
                            pose_rotation_recovery_cache["retry_pending"] = False
                            pose_rotation_recovery_cache["retry_fail_count"] = 0
                            # Restore the normal current+one-fresh Pose budget after the
                            # low-trust confirmation frame; do not leave retry_fail_need=1.
                            pose_rotation_recovery_cache["retry_fail_need"] = max(1, int(getattr(args, "pose_rotate_transient_fail_observations", 2)))
                            pose_rotation_recovery_cache["retry_reason"] = f"{fallback_source} accepted"
                            pose_rotation_recovery_cache["retry_exhausted"] = False
                            if not low_trust_confirm_pending:
                                pose_rotation_recovery_cache["confirmation_budget_source"] = fallback_source
                                pose_rotation_recovery_cache["confirmation_budget_inference_serial"] = int(inference_serial)
                                print(
                                    f"[ROTATE-FALLBACK-CONFIRM-ARMED] source={fallback_source} "
                                    f"after failure={fail_n}/{effective_fail_need}; generic rejudge counter is NOT reset"
                                )
                            print(f"[POSE-ROT-{fallback_source}-ACCEPT] {pose_status}")
                        else:
                            print(f"[POSE-ROT-MASK-FALLBACK-REJECT] {mask_status}")
                            print(f"[ROTATE-FALLBACK-MASK_FAILED] motion={motion_now} failure={fail_n}/{effective_fail_need} status={mask_status}")
                else:
                    print(
                        f"[POSE-ROT-TRANSIENT-RETRY] preserve no-plan result so the controller can obtain another fresh observation; "
                        f"fallbacks arm at failure {fail_need}"
                    )

                if fail_n >= effective_fail_need and pose_plan is None:
                    pose_rotation_recovery_cache["retry_pending"] = False
                    pose_rotation_recovery_cache["retry_exhausted"] = True
                    pose_rotation_recovery_cache["retry_reason"] = (
                        f"bounded pose retries exhausted {fail_n}/{effective_fail_need}; cache/mask-axis fallback unavailable"
                    )
                    print(
                        f"[POSE-ROT-RECOVERY-EXHAUSTED] failure={fail_n}/{effective_fail_need}; "
                        "ROTATE unavailable for this observation only; ordinary CENTER/SPREAD/LONG_PULL planner remains enabled"
                    )
                    print(
                        f"[ROTATE-FALLBACK-UNAVAILABLE] POSE_RETRY_EXHAUSTED motion={motion_now} "
                        f"failure={fail_n}/{effective_fail_need}; cache/mask rotation fallback unavailable; ROTATE-only soft block"
                    )

            _a140_latency_mark("rotate_pair_plan_start")
            _rotate_pair_t0 = time.perf_counter()
            pose_plan = build_linear_pull_rotation_plan(
                pose_plan, mask_ref_for_pose, latest_H, cfg,
                enabled=bool(getattr(args, "pose_rotate_linear_pull_enable", True)),
                shear_threshold_deg=float(getattr(args, "pose_rotate_linear_shear_threshold_deg", 45.0)),
                mask_inset_mm=float(getattr(args, "pose_rotate_linear_mask_inset_mm", 25.0)),
                mask_inset_min_mm=float(getattr(args, "pose_rotate_linear_mask_inset_min_mm", 12.0)),
                shear_pull_mm=float(getattr(args, "pose_rotate_linear_shear_pull_mm", 35.0)),
                shear_effect_gain=float(getattr(args, "pose_rotate_linear_shear_effect_gain", 0.55)),
                shear_target_min_deg=float(getattr(args, "pose_rotate_linear_shear_target_min_deg", 22.0)),
                shear_target_max_deg=float(getattr(args, "pose_rotate_linear_shear_target_max_deg", 35.0)),
                shear_min_mm=float(getattr(args, "pose_rotate_linear_shear_min_mm", 60.0)),
                shear_max_mm=float(getattr(args, "pose_rotate_linear_shear_max_mm", 160.0)),
                pull_ray_max_error_deg=float(getattr(args, "pose_rotate_linear_pull_ray_max_error_deg", 10.0)),
                pull_symmetry_max_error_mm=float(getattr(args, "pose_rotate_linear_pull_symmetry_max_error_mm", 20.0)),
                pull_effect_gain=float(getattr(args, "pose_rotate_linear_pull_effect_gain", 0.80)),
                pull_target_min_deg=float(getattr(args, "pose_rotate_linear_pull_target_min_deg", 10.0)),
                pull_target_max_deg=float(getattr(args, "pose_rotate_linear_pull_target_max_deg", 30.0)),
                pull_min_mm=float(getattr(args, "pose_rotate_linear_pull_min_mm", 40.0)),
                pull_max_mm=float(getattr(args, "pose_rotate_linear_pull_max_mm", 120.0)),
                pull_gain_mm_per_deg=float(getattr(args, "pose_rotate_linear_pull_gain_mm_per_deg", 0.90)),
                pull_outward_mix=float(getattr(args, "pose_rotate_linear_pull_outward_mix", 0.10)),
                pull_pair_stretch_penalty_weight=float(getattr(args, "pose_rotate_linear_pull_pair_stretch_penalty_weight", 0.35)),
                pull_prefer_long_lever=bool(getattr(args, "pose_rotate_linear_pull_prefer_long_lever", True)),
                pull_long_lever_retention_min=float(getattr(args, "pose_rotate_linear_pull_long_lever_retention_min", 0.55)),
                pull_aggressive_enable=bool(getattr(args, "pose_rotate_linear_pull_aggressive_enable", True)),
                pull_aggressive_start_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_start_deg", 18.0)),
                pull_aggressive_full_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_full_deg", 30.0)),
                pull_aggressive_gain_max=float(getattr(args, "pose_rotate_linear_pull_aggressive_gain_max", 1.20)),
                pull_aggressive_target_max_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_target_max_deg", 34.0)),
                pull_aggressive_effect_priority_bonus=float(getattr(args, "pose_rotate_linear_pull_aggressive_effect_priority_bonus", 0.35)),
                initial_min_pair_distance_mm=float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)),
                path_min_pair_distance_mm=float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)),
                min_x_order_gap_mm=float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)),
                max_pair_stretch_mm=float(getattr(args, "pose_rotate_linear_max_pair_stretch_mm", 45.0)),
                shear_max_pair_stretch_mm=float(getattr(args, "pose_rotate_linear_shear_max_pair_stretch_mm", 80.0)),
                max_pair_stretch_ratio=float(getattr(args, "pose_rotate_linear_max_pair_stretch_ratio", 0.20)),
            )
            _rotate_pair_ms = (time.perf_counter() - _rotate_pair_t0) * 1000.0
            _a140_latency_mark("rotate_pair_plan_end")
            if isinstance(pose_plan, dict):
                pose_plan["linear_pair_planning_ms"] = float(_rotate_pair_ms)
            print(f"[VLA0852-S2-LATENCY] stage=rotate_pair_plan serial_next={int(inference_serial)+1} time={_rotate_pair_ms:.1f}ms")
            # preserves the v6 final legacy-arc kill switch. If the linear converter
            # cannot produce ROTATE_PULL/SHEAR, preserve diagnostics but prohibit
            # all physical rotation rather than silently executing the old arc path.
            if isinstance(pose_plan, dict) and not bool(pose_plan.get("done", False)):
                _linear_exact = str(pose_plan.get("rotation_motion_exact_action") or "").upper()
                if _linear_exact not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                    pose_plan = copy.deepcopy(pose_plan)
                    _prior_reason = str(pose_plan.get("ready_reason") or "linear ROTATE unavailable")
                    pose_plan["ready"] = False
                    pose_plan["legacy_arc_disabled"] = True
                    pose_plan["ready_reason"] = f"{_prior_reason} | LEGACY ARC FALLBACK DISABLED"
                    _base_status = str(pose_plan.get("status", "POSE ROT")).split(" | ")[0]
                    pose_plan["status"] = f"{_base_status} | BLOCKED: LINEAR ROTATE REQUIRED"
                    print(
                        f"[POSE-ROT-LEGACY-ARC-DISABLED] snapshot exact={_linear_exact or 'NONE'}; "
                        "ROTATE_PULL/SHEAR unavailable -> Robot motion: NONE"
                    )
            pose_plan = _a153_prepare_pose_rotation_plan(pose_plan, source="snapshot inference")
            if isinstance(pose_plan, dict):
                pose_status = str(pose_plan.get("status", pose_status))
                draw_tshirt_pose_rotation_plan_overlay(pose_canvas, latest_H, pose_plan)
            canvas = pose_canvas
            latest_pose_rotation_plan = pose_plan
            latest_pose_rotation_status = pose_status
            if isinstance(pose_plan, dict):
                _rot_src = str(pose_plan.get("pose_inference_source") or "UNKNOWN").upper()
                _rot_exact = str(pose_plan.get("rotation_motion_exact_action") or "NONE").upper()
                _rot_angle = pose_plan.get("delta_full_deg", pose_plan.get("current_axis_deg"))
                try:
                    _rot_angle_txt = f"{float(_rot_angle):+.1f}deg" if _rot_angle is not None else "NA"
                except Exception:
                    _rot_angle_txt = "NA"
                print(
                    f"[ROTATE-SOURCE] source={_rot_src} angle={_rot_angle_txt} exact={_rot_exact} "
                    f"ready={bool(pose_plan.get('ready',False))} done={bool(pose_plan.get('done',False))}"
                )
            print(f"[POSE-ROT] {pose_status}")
        # fail-closed: if no fresh Pose stage ran, a conditional 45..58%
        # fallback_color candidate never becomes a planning mask.
        if isinstance(conditional_color_candidate, dict):
            coverage = float(conditional_color_candidate.get("fallback_color_board_coverage", 0.0) or 0.0)
            latest_fallback_status = (
                f"MASK_SUSPECT fallback_color REJECTED_AFTER_POSE boardCoverage={coverage:.3f} | "
                "fresh Pose unavailable/disabled"
            )
            latest_segmentation_source = "MASK_SUSPECT_FALLBACK_COLOR"
            candidates = []
            print(f"[FALLBACK-COLOR-POSE-REJECT] planner receives no mask/target: {latest_fallback_status}")
            conditional_color_candidate = None
        _a140_latency_mark("pose_complete")

        selected_union = _union_mask_from_candidates_for_full_frame(candidates, src_frame.shape)
        selected_union = _clip_mask_to_perception_roi(selected_union, src_frame.shape)
        filtered_union, did_filter, component_status, removed_mask = _pose_component_filter_mask(
            selected_union, latest_pose_rotation_plan, src_frame.shape, "selected garment mask"
        )
        if did_filter and filtered_union is not None:
            rebuilt = _rebuild_candidates_from_component_mask(filtered_union, candidates, src_frame.shape)
            if rebuilt:
                candidates = rebuilt
                if raw_full_frame_candidates:
                    raw_full_frame_candidates = list(rebuilt)
                print(f"[POSE-COMPONENT-FILTER] {component_status}")
                try:
                    if removed_mask is not None and int(np.count_nonzero(removed_mask)) > 0:
                        removed_cnts, _ = cv2.findContours(removed_mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
                        cv2.drawContours(canvas, removed_cnts, -1, (0, 0, 255), 2)
                        cv2.putText(canvas, "REMOVED DISCONNECTED MASK NOISE", (25, 145),
                                    cv2.FONT_HERSHEY_SIMPLEX, 0.52, (0, 0, 0), 4)
                        cv2.putText(canvas, "REMOVED DISCONNECTED MASK NOISE", (25, 145),
                                    cv2.FONT_HERSHEY_SIMPLEX, 0.52, (0, 0, 255), 2)
                except Exception:
                    pass
            else:
                print("[POSE-COMPONENT-FILTER] rebuild failed; preserving original A119 candidates")
        elif bool(getattr(args, "fallback_print_debug", False)):
            print(f"[POSE-COMPONENT-FILTER] {component_status}")

        latest_yolo_raw_mask = _union_mask_from_candidates_for_full_frame(raw_full_frame_candidates, src_frame.shape)
        latest_yolo_raw_mask = _clip_mask_to_perception_roi(latest_yolo_raw_mask, src_frame.shape)
        raw_px = int(np.count_nonzero(latest_yolo_raw_mask)) if latest_yolo_raw_mask is not None else 0
        roi_tag = " aruco_roi" if roi_active else " full_frame"
        latest_yolo_raw_status = f"yolo_raw{roi_tag} area={raw_px}px candidates={len(raw_full_frame_candidates)}"

        # keep the YOLO/fallback candidates before strict planning sanitation.
        # X coarse-spread is originally a b18-style whole-mask spread action.  If the
        # stricter a-series board-core filter rejects every planning candidate, X may
        # still safely build a coarse plan from this pre-sanitize mask because the final
        # two target points are rechecked against board/workspace constraints.
        coarse_pre_sanitize_candidates = list(candidates)

        fg_mask, fg_status = build_full_garment_mask_for_frame(
            src_infer,
            raw_full_frame_candidates if len(raw_full_frame_candidates) > 0 else candidates,
            reason=reason,
        )
        fg_mask = _clip_mask_to_perception_roi(fg_mask, src_frame.shape)
        fg_mask_filtered, fg_did_filter, fg_component_status, _fg_removed = _pose_component_filter_mask(
            fg_mask, latest_pose_rotation_plan, src_frame.shape, "full garment mask"
        )
        if fg_did_filter and fg_mask_filtered is not None:
            fg_mask = fg_mask_filtered
            fg_status = str(fg_status) + "; " + str(fg_component_status)
            print(f"[POSE-COMPONENT-FILTER] {fg_component_status}")
        if roi_active:
            fg_status = str(fg_status) + "; aruco_roi_clipped"
        latest_full_garment_mask = fg_mask
        latest_full_garment_status = fg_status
        if fg_mask is not None:
            canvas = draw_full_garment_overlay(canvas, fg_mask, fg_status)
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[FULL-GARMENT] READY: {fg_status}")
        else:
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[FULL-GARMENT] not ready: {fg_status}")

        candidates = sanitize_candidates_for_planning(candidates, src_frame, reason=reason)

        inference_serial += 1
        if isinstance(latest_pose_rotation_plan, dict):
            latest_pose_rotation_plan["source_inference_serial"] = int(inference_serial)
        latest_candidates = candidates
        latest_candidate, latest_point = select_candidate(latest_candidates, selected_grasp_key)
        if args.dual_candidate_mode:
            latest_dual_plan, latest_dual_status = build_dual_plan_from_candidates(
                cfg, latest_H, latest_candidates, left_key=args.dual_left_key, right_key=args.dual_right_key)
        else:
            latest_dual_plan, latest_dual_status = None, "dual_candidate_mode OFF"
        def _try_build_coarse_plan_from(cands, label: str):
            return build_coarse_spread_plan_from_candidates(
                cfg, latest_H, cands,
                inside_ratio=args.coarse_inside_ratio,
                min_board_separation=args.coarse_min_board_separation,
                max_board_y_diff=args.coarse_max_board_y_diff,
                axis_mode=get_effective_coarse_axis_mode(),
                endpoint_band_ratio=args.coarse_endpoint_band_ratio,
                local_radius=args.coarse_local_mask_radius,
                min_local_ratio=args.coarse_min_local_mask_ratio,
                min_side_pixels=args.coarse_min_side_pixels,
                relaxed_minor=args.coarse_relaxed_minor,
                relaxed_min_board_separation=args.coarse_relaxed_min_board_separation,
                relaxed_endpoint_band_ratio=args.coarse_relaxed_endpoint_band_ratio,
                relaxed_local_radius=args.coarse_relaxed_local_mask_radius,
                relaxed_min_local_ratio=args.coarse_relaxed_min_local_mask_ratio,
                relaxed_min_side_pixels=args.coarse_relaxed_min_side_pixels,
                relaxed_max_board_y_diff=args.coarse_relaxed_max_board_y_diff,
                board_y_min_y_separation=args.coarse_board_y_min_y_separation,
                board_y_endpoint_band_ratio=args.coarse_board_y_endpoint_band_ratio,
                board_y_local_radius=args.coarse_board_y_local_mask_radius,
                board_y_min_local_ratio=args.coarse_board_y_min_local_mask_ratio,
                board_y_min_side_pixels=args.coarse_board_y_min_side_pixels)

        if args.coarse_preview_mode:
            latest_coarse_plan, latest_coarse_status = _try_build_coarse_plan_from(latest_candidates, "sanitized")
            if latest_coarse_plan is None and coarse_pre_sanitize_candidates:
                raw_plan, raw_status = _try_build_coarse_plan_from(coarse_pre_sanitize_candidates, "pre_sanitize")
                if raw_plan is not None:
                    latest_coarse_plan = raw_plan
                    latest_coarse_status = "pre-sanitize coarse fallback: " + str(raw_status)
                    if bool(getattr(args, "fallback_print_debug", False)):
                        a2 = latest_coarse_plan["targets"]["arm2"]["board_xy"]
                        a1 = latest_coarse_plan["targets"]["arm1"]["board_xy"]
                        print(f"[COARSE-FALLBACK] using pre-sanitize YOLO/fallback mask for X: ARM2=({a2[0]:.1f},{a2[1]:.1f}) ARM1=({a1[0]:.1f},{a1[1]:.1f}) | {raw_status}")
                elif bool(getattr(args, "fallback_print_debug", False)):
                    print(f"[COARSE-FALLBACK] pre-sanitize candidate also failed: {raw_status}")
            if args.coarse_print_on_infer:
                print_coarse_plan()
        else:
            latest_coarse_plan, latest_coarse_status = None, "coarse_preview_mode OFF"
        snapshot_canvas = canvas
        _a140_latency_mark("inference_complete", completed_inference_serial=int(inference_serial))
        if len(candidates) > 0:
            # Stale-watch stays in RAW coordinates even though all inference/planning used corrected src_frame.
            stale_ref = snapshot_raw_frame if isinstance(snapshot_raw_frame, np.ndarray) else src_frame
            snapshot_reference_gray = frame_to_small_gray_f32(stale_ref)
            snapshot_foreground_state = compute_foreground_state_from_empty(
                stale_ref, background_gray=fallback_empty_raw_gray, homography=latest_raw_H
            )
            target_stale_frames = 0
            target_removed_frames = 0
            target_changed_frames = 0
            target_stale_armed_at = time.time() + float(args.target_stale_cooldown)
            if args.fallback_print_debug and snapshot_foreground_state.get("valid", False):
                print(f"[FG-REF] area={snapshot_foreground_state.get('area_px',0):.0f}px "
                      f"contour={snapshot_foreground_state.get('contour_area_px',0):.0f}px "
                      f"center={snapshot_foreground_state.get('center_px')}")
        else:
            snapshot_reference_gray = None
            snapshot_foreground_state = None
            target_stale_frames = 0
            target_removed_frames = 0
            target_changed_frames = 0
            target_stale_armed_at = 0.0
        print(f"[SNAPSHOT] YOLO done on {reason}: candidates={len(candidates)}, selected={selected_grasp_key}, serial={inference_serial}")

        if len(candidates) == 0 and args.auto_wait_cloth_after_no_candidates and snapshot_mode:
            _reset_coarse_auto_press_cycle("no candidates / empty board after inference")
            # Empty board/no garment: do not keep a stale 'no boxes' snapshot forever.
            # Use the current empty scene as a baseline and wait until a new cloth/scene change appears.
            no_candidate_ref = snapshot_raw_frame if isinstance(snapshot_raw_frame, np.ndarray) else src_frame
            no_candidate_baseline_gray = frame_to_small_gray_f32(no_candidate_ref)
            wait_cloth_after_no_candidates = True
            snapshot_ready = False
            snapshot_frame = None
            stable_prev_gray = None
            stable_since = None
            stable_low_motion_frames = 0
            print("[SNAPSHOT] No YOLO candidates. Waiting for cloth/scene change before next snapshot.")

        if latest_point is None:
            print("[SNAPSHOT] No valid selected point. Try 0/1/2, M, or S to retake.")
        if latest_dual_plan is not None:
            l = latest_dual_plan["targets"]["arm2"]["board_xy"]
            r = latest_dual_plan["targets"]["arm1"]["board_xy"]
            print(f"[DUAL] READY: ARM2 board=({l[0]:.1f},{l[1]:.1f}), ARM1 board=({r[0]:.1f},{r[1]:.1f}) | {latest_dual_plan['summary']}")
        else:
            print(f"[DUAL] not ready: {latest_dual_status}")
        return canvas

    def start_yolo_snapshot_task(src_frame: np.ndarray, reason: str = "snapshot"):
        nonlocal yolo_busy, snapshot_canvas, snapshot_frame, snapshot_raw_frame, auto_x_cancelled_yolo_cleanup_required
        if grasp_model is None:
            return
        if yolo_busy:
            return
        try:
            raw_snapshot = src_frame.copy()
            corrected_snapshot = make_analysis_frame(raw_snapshot, reason=reason)
        except Exception as exc:
            print(f"[CAMERA-UNDISTORT-ERROR] {reason}: {exc}")
            return
        snapshot_raw_frame = raw_snapshot
        snapshot_frame = corrected_snapshot
        yolo_busy = True
        snapshot_canvas = corrected_snapshot.copy()
        cv2.putText(snapshot_canvas, "YOLO RUNNING ON CORRECTED SNAPSHOT...", (25, 115), cv2.FONT_HERSHEY_SIMPLEX, 0.64, (0, 0, 0), 4)
        cv2.putText(snapshot_canvas, "YOLO RUNNING ON CORRECTED SNAPSHOT...", (25, 115), cv2.FONT_HERSHEY_SIMPLEX, 0.64, (0, 255, 255), 2)

        def _worker():
            nonlocal yolo_busy, auto_x_cancelled_yolo_cleanup_required
            try:
                run_yolo_on_snapshot(corrected_snapshot.copy(), reason=reason)
            except Exception as e:
                print(f"[SNAPSHOT-YOLO-ERROR] {repr(e)}")
            finally:
                if auto_x_cancelled_yolo_cleanup_required:
                    auto_x_cancelled_yolo_cleanup_required = False
                    reset_snapshot("discard cancelled AUTO-X YOLO result")
                    print("[A140-YOLO-CANCELLED] stale snapshot products discarded after reset")
                yolo_busy = False

        threading.Thread(target=_worker, daemon=True).start()

    def request_fresh_dual_plan_and_wait(reason: str, timeout: float):
        nonlocal force_snapshot_reason
        old_serial = inference_serial
        reset_snapshot(f"{reason}: requesting fresh target before next arm")
        force_snapshot_reason = reason
        print(f"[REINFER] Requested fresh YOLO snapshot: {reason}")
        start = time.time()
        while time.time() - start < float(timeout):
            time.sleep(0.05)
            if inference_serial > old_serial and not yolo_busy:
                if latest_dual_plan is not None:
                    l = latest_dual_plan["targets"]["arm2"]["board_xy"]
                    r = latest_dual_plan["targets"]["arm1"]["board_xy"]
                    print(f"[REINFER] Fresh dual plan ready: ARM2=({l[0]:.1f},{l[1]:.1f}), ARM1=({r[0]:.1f},{r[1]:.1f})")
                    return latest_dual_plan
                print(f"[REINFER-BLOCKED] Fresh YOLO finished but dual plan is not ready: {latest_dual_status}")
                return None
        print(f"[REINFER-TIMEOUT] No fresh YOLO result within {timeout:.1f}s. Stop sequential test for safety.")
        return None

    def request_fresh_coarse_plan_and_wait(reason: str, timeout: float,
                                           expected_auto_x_epoch: Optional[int] = None):
        nonlocal force_snapshot_reason, force_snapshot_during_motion_allowed
        nonlocal force_snapshot_burst_reason, auto_x_cancelled_yolo_cleanup_required
        nonlocal latest_coarse_status, latest_coarse_wait_outcome, latest_coarse_wait_detail
        old_serial = inference_serial
        _a140_latency_mark("snapshot_request", snapshot_reason=str(reason), old_inference_serial=int(old_serial))
        reset_snapshot(f"{reason}: requesting fresh coarse SPREAD target before motion")
        latest_coarse_wait_outcome = "WAITING_AUTO_X" if expected_auto_x_epoch is not None else "WAITING_GENERIC"
        latest_coarse_wait_detail = str(reason)
        if (expected_auto_x_epoch is not None
                and not auto_x_controller.is_current(int(expected_auto_x_epoch))):
            print(f"[A140-COARSE-REINFER-CANCELLED] reset/disarm before snapshot request epoch={expected_auto_x_epoch}")
            return None
        force_snapshot_reason = reason
        force_snapshot_during_motion_allowed = True
        print(f"[COARSE-REINFER] Requested fresh snapshot before motion: {reason}")
        started = time.monotonic()
        soft_timeout_s = max(0.5, float(timeout))
        is_auto_x_wait = expected_auto_x_epoch is not None
        grace_s = (
            max(0.0, float(getattr(args, "auto_x_fresh_inflight_grace_s", 10.0)))
            if is_auto_x_wait else 0.0
        )
        hard_total_s = (
            max(
                soft_timeout_s + grace_s,
                float(getattr(args, "auto_x_fresh_hard_timeout_s", 45.0)),
            ) if is_auto_x_wait else soft_timeout_s
        )

        def _cancelled() -> bool:
            nonlocal latest_coarse_wait_outcome, latest_coarse_wait_detail
            if (expected_auto_x_epoch is not None
                    and not auto_x_controller.is_current(int(expected_auto_x_epoch))):
                latest_coarse_wait_outcome = "CANCELLED"
                latest_coarse_wait_detail = f"reset/disarm epoch={expected_auto_x_epoch}"
                print(f"[A140-COARSE-REINFER-CANCELLED] reset/disarm while waiting epoch={expected_auto_x_epoch}")
                return True
            return False

        def _consume_completed_fresh_result():
            """Return (finished, plan_or_none). finished=True means this fresh worker ended."""
            nonlocal latest_coarse_wait_outcome, latest_coarse_wait_detail
            if inference_serial <= old_serial or yolo_busy:
                return False, None
            latest_coarse_wait_outcome = "COMPLETED"
            latest_coarse_wait_detail = str(latest_coarse_status)
            if latest_coarse_plan is not None:
                a2 = latest_coarse_plan["targets"]["arm2"]["board_xy"]
                a1 = latest_coarse_plan["targets"]["arm1"]["board_xy"]
                m = latest_coarse_plan.get("metrics", {})
                mode = m.get("axis_mode", latest_coarse_plan.get("spread_axis", {}).get("axis_mode", "?"))
                print(f"[COARSE-REINFER] Fresh coarse plan ready: mode={mode} ARM2=({a2[0]:.1f},{a2[1]:.1f}), ARM1=({a1[0]:.1f},{a1[1]:.1f})")
                return True, latest_coarse_plan
            print(f"[COARSE-REINFER-BLOCKED] Fresh inference finished but coarse plan is not ready: {latest_coarse_status}")
            return True, None

        def _same_request_capture_pending() -> bool:
            return bool(
                (force_snapshot_reason is not None and str(force_snapshot_reason) == str(reason))
                or (bool(snapshot_ready) and inference_serial <= old_serial)
            )

        def _technical_timeout(phase: str, elapsed_s: float):
            nonlocal force_snapshot_reason, force_snapshot_burst_reason
            nonlocal auto_x_cancelled_yolo_cleanup_required, latest_coarse_status
            nonlocal latest_coarse_wait_outcome, latest_coarse_wait_detail
            # Do not let an abandoned forced request fire later as a stale logical
            # observation. If a worker is already running we cannot kill it safely;
            # mark its products for one-shot discard in start_yolo_snapshot_task().
            if force_snapshot_reason is not None and str(force_snapshot_reason) == str(reason):
                force_snapshot_reason = None
            force_snapshot_burst_reason = None
            force_snapshot_burst_frames.clear()
            if yolo_busy:
                auto_x_cancelled_yolo_cleanup_required = True
            latest_coarse_status = (
                f"AUTO_X_FRESH_WAIT_TECHNICAL_TIMEOUT: phase={phase} "
                f"elapsed={float(elapsed_s):.2f}s soft={soft_timeout_s:.2f}s "
                f"grace={grace_s:.2f}s hard={hard_total_s:.2f}s "
                f"yolo_busy={bool(yolo_busy)} serial={int(inference_serial)} old_serial={int(old_serial)}"
            )
            latest_coarse_wait_outcome = "TECHNICAL_TIMEOUT"
            latest_coarse_wait_detail = str(latest_coarse_status)
            _a140_latency_mark(
                "fresh_wait_technical_timeout",
                wait_phase=str(phase),
                elapsed_s=float(elapsed_s),
                soft_timeout_s=float(soft_timeout_s),
                grace_s=float(grace_s),
                hard_timeout_s=float(hard_total_s),
                yolo_busy=bool(yolo_busy),
            )
            print(
                f"[A161-COARSE-REINFER-TECHNICAL-TIMEOUT] phase={phase} "
                f"elapsed={float(elapsed_s):.2f}s; stale request/result cancelled; "
                "DO NOT classify as NO_ACTION_CANDIDATE or schedule automatic rejudge"
            )
            return None

        try:
            soft_deadline = started + soft_timeout_s
            while time.monotonic() < soft_deadline:
                time.sleep(0.05)
                if _cancelled():
                    return None
                finished, result = _consume_completed_fresh_result()
                if finished:
                    return result

            finished, result = _consume_completed_fresh_result()
            if finished:
                return result

            if not is_auto_x_wait:
                latest_coarse_wait_outcome = "GENERIC_TIMEOUT"
                latest_coarse_wait_detail = f"generic timeout after {soft_timeout_s:.2f}s"
                print(f"[COARSE-REINFER-TIMEOUT] No fresh coarse result within {soft_timeout_s:.1f}s. Stop X action for safety.")
                return None

            capture_pending = _same_request_capture_pending()
            inference_pending = bool(yolo_busy)
            if not capture_pending and not inference_pending:
                return _technical_timeout("REQUEST_IDLE_AT_SOFT_DEADLINE", time.monotonic() - started)

            phase = "INFERENCE" if inference_pending else "CAPTURE_OR_BURST"
            print(
                f"[A161-COARSE-REINFER-GRACE] soft_timeout={soft_timeout_s:.1f}s reached "
                f"while phase={phase} is still active; grace={grace_s:.1f}s; "
                "same logical snapshot retained, no automatic rejudge"
            )
            _a140_latency_mark(
                "fresh_wait_grace_start",
                wait_phase=phase,
                soft_timeout_s=float(soft_timeout_s),
                grace_s=float(grace_s),
            )

            grace_deadline = min(started + hard_total_s, time.monotonic() + grace_s)
            while time.monotonic() < grace_deadline:
                time.sleep(0.05)
                if _cancelled():
                    return None
                finished, result = _consume_completed_fresh_result()
                if finished:
                    elapsed = time.monotonic() - started
                    print(f"[A161-COARSE-REINFER-GRACE-PASS] fresh result completed after {elapsed:.2f}s; reuse same logical snapshot")
                    _a140_latency_mark("fresh_wait_grace_pass", elapsed_s=float(elapsed))
                    return result

            finished, result = _consume_completed_fresh_result()
            if finished:
                elapsed = time.monotonic() - started
                print(f"[A161-COARSE-REINFER-GRACE-PASS] fresh result completed after {elapsed:.2f}s; reuse same logical snapshot")
                _a140_latency_mark("fresh_wait_grace_pass", elapsed_s=float(elapsed))
                return result

            # If the inference worker itself is still active, do NOT return None here.
            # That was the vla_0840 bug: None became NO_ACTION_CANDIDATE and spawned
            # another rejudge while the useful result was about to finish.
            if yolo_busy:
                print(
                    f"[A161-COARSE-REINFER-ACTIVE-HOLD] inference still running after grace; "
                    f"continue waiting for SAME worker up to hard_total={hard_total_s:.1f}s; "
                    "NO_ACTION_CANDIDATE suppressed"
                )
                _a140_latency_mark("fresh_wait_active_hold_start")
                hard_deadline = started + hard_total_s
                while time.monotonic() < hard_deadline:
                    time.sleep(0.05)
                    if _cancelled():
                        return None
                    finished, result = _consume_completed_fresh_result()
                    if finished:
                        elapsed = time.monotonic() - started
                        print(f"[A161-COARSE-REINFER-ACTIVE-HOLD-PASS] inference completed after {elapsed:.2f}s")
                        _a140_latency_mark("fresh_wait_active_hold_pass", elapsed_s=float(elapsed))
                        return result
                finished, result = _consume_completed_fresh_result()
                if finished:
                    return result
                return _technical_timeout("INFERENCE_HARD_FAILSAFE", time.monotonic() - started)

            return _technical_timeout("CAPTURE_GRACE_EXHAUSTED", time.monotonic() - started)
        finally:
            force_snapshot_during_motion_allowed = False

    def _motion_worker(name: str, fn, expected_auto_x_epoch: Optional[int] = None):
        nonlocal motion_busy, pending_auto_x_action, auto_x_manual_judge_active
        try:
            fn()
        except Exception as e:
            print(f"[MOTION-ERROR] {name}: {repr(e)}")
            if str(name).startswith("x-auto-judge") or str(name) == "auto-x-pending-execute":
                applied = False
                if expected_auto_x_epoch is not None:
                    def _publish_worker_failure() -> None:
                        nonlocal pending_auto_x_action, auto_x_manual_judge_active
                        pending_auto_x_action = None
                        auto_x_manual_judge_active = True
                        auto_x_ready_cycle["cycle_active"] = False
                        _a140_set_outer_overlay("AUTO-X ERROR - PRESS X", f"{name}: {repr(e)}", hold_s=120.0)

                    applied = auto_x_controller.fail_if_current(
                        int(expected_auto_x_epoch), f"{name}: {repr(e)}", fatal=True,
                        publisher=_publish_worker_failure,
                    )
                if applied:
                    print(f"[A140-CYCLE] ERROR stop name={name} manual X required")
                    _a140_latency_print_cycle("ERROR")
                    auto_x_debug_logger.stop_session(f"A140 fatal motion/judge exception: {name}: {repr(e)}")
                else:
                    print(f"[A140-STALE-WORKER-ERROR] name={name} epoch={expected_auto_x_epoch}; reset/newer generation preserved")
        finally:
            try:
                if str(name).startswith("x-auto-judge"):
                    stop_reason = auto_x_debug_logger.consume_stop_request()
                    if stop_reason:
                        auto_x_debug_logger.stop_session(stop_reason)

                # Once a robot has touched or lifted the cloth, the old snapshot target is stale.
                # First move both arms back to the side standby positions from the provided reference code,
                # then discard the old target so the next YOLO snapshot is captured with the clothing area clear.
                if args.auto_reinfer_after_motion and ("pick" in str(name).lower()):
                    if args.imaging_standby and not args.no_standby:
                        move_arms_to_standby(reason="before re-infer after motion")
                    reset_snapshot("robot motion finished; old target invalidated, waiting for fresh still frame")
            except Exception as cleanup_error:
                print(f"[MOTION-CLEANUP-ERROR] {name}: {repr(cleanup_error)}")
            finally:
                # Publish idle only after every worker-finally cleanup is complete.
                # Otherwise a new X can arm between idle publication and an old
                # pick worker's target-invalidating reset.
                with motion_lock:
                    motion_busy = False
                print(f"[MOTION] {name} finished")

    def start_motion_task(name: str, fn, expected_auto_x_epoch: Optional[int] = None) -> bool:
        nonlocal motion_thread, motion_busy, arms_in_imaging_standby
        if auto_x_physical_recovery_required:
            print(
                f"[A140-PHYSICAL-RECOVERY-BLOCK] task={name}; manual safety check and . acknowledgement required: "
                f"{auto_x_physical_recovery_reason}"
            )
            return False
        if auto_x_controller.armed and str(name) != "auto-x-pending-execute":
            print(f"[A140-OTHER-MOTION-SUPPRESSED] task={name}; AUTO-X cycle must be reset before other robot motion")
            return False
        if not args.async_motion:
            arms_in_imaging_standby = False
            fn()
            return True
        with motion_lock:
            if motion_busy:
                print(f"[MOTION-BUSY] {name} ignored because another robot motion is running.")
                return False
            motion_busy = True
            arms_in_imaging_standby = False
        try:
            motion_thread = threading.Thread(
                target=_motion_worker, args=(name, fn, expected_auto_x_epoch), daemon=True,
            )
            motion_thread.start()
        except Exception as e:
            with motion_lock:
                motion_busy = False
                motion_thread = None
            print(f"[MOTION-START-ERROR] {name}: {repr(e)}")
            return False
        print(f"[MOTION] {name} started in background. OpenCV window will keep updating.")
        return True

    def start_auto_x_judge_task(name: str, fn,
                                expected_cycle_epoch: Optional[int] = None) -> bool:
        """Start a perception-only AUTO-X judge while the camera loop stays alive.

        Even with ``--no-async-motion``, a fresh judgment must run off the main
        camera loop; otherwise the forced 5-frame snapshot cannot be collected.
        This helper never dispatches a garment action; the manual-X callback may
        still reuse the existing imaging-standby helper before capture.  It
        deliberately preserves the action-local standby command state.
        """
        nonlocal motion_thread, motion_busy
        with motion_lock:
            if motion_busy:
                print(f"[MOTION-BUSY] {name} ignored because another robot motion/judgment is running.")
                return False
            motion_busy = True
        try:
            motion_thread = threading.Thread(
                target=_motion_worker, args=(name, fn, expected_cycle_epoch), daemon=True,
            )
            motion_thread.start()
        except Exception as e:
            with motion_lock:
                motion_busy = False
                motion_thread = None
            print(f"[MOTION-START-ERROR] {name}: {repr(e)}")
            return False
        print(f"[MOTION] {name} started in background so the camera can collect a fresh logical snapshot.")
        return True

    def _run_threaded_commands(command_items: List[Tuple[str, Any]], label: str, gap: Optional[float] = None):
        """Issue commands to ARM1/ARM2 with minimal start-time skew.
        Each command runs in its own short thread so serial waits on one arm do not delay the other arm.
        """
        if not send_enabled:
            print(f"[DRY-RUN] {label}: parallel command group not sent")
            return
        if command_items:
            _a140_note_action_command(str(label))
        threads = []
        command_gap = float(args.dual_fast_command_gap if gap is None else gap)

        def _wrap(arm_key: str, fn):
            try:
                fn()
            except Exception as e:
                print(f"[{label}-ERROR] {arm_key.upper()}: {repr(e)}")
                if auto_x_controller.state == "EXECUTING":
                    auto_x_action_parallel_errors.append(f"{label}:{arm_key}:{repr(e)}")

        for idx, (arm_key, fn) in enumerate(command_items):
            th = threading.Thread(target=_wrap, args=(arm_key, fn), daemon=True)
            threads.append(th)
            th.start()
            if command_gap > 0 and idx + 1 < len(command_items):
                time.sleep(command_gap)
        for th in threads:
            th.join()

    def _should_log_motion_detail(pose_name: str = "") -> bool:
            if bool(getattr(args, "pose_rotate_target_logs", False)):
                return True
            if not bool(getattr(args, "compact_motion_log", True)):
                return True
            return not str(pose_name).startswith("POSE-ROT")

    def parallel_move_targets(xyz_map: Dict[str, Dict[str, float]], pose_name: str, gripper_angle: float,
                                  wait_after: Optional[float] = None, speed: Optional[float] = None,
                                  allow_after_error: bool = False):
            if auto_x_controller.state == "EXECUTING" and auto_x_action_parallel_errors and not bool(allow_after_error):
                print(
                    f"[A140-PARALLEL-MOVE-SUPPRESSED] pose={pose_name}; "
                    "an earlier arm command failed, so no subsequent move group is issued"
                )
                return False
            errors_before = len(auto_x_action_parallel_errors)
            items = []
            spd_eff = float(spd_default if speed is None else speed)
            if not np.isfinite(spd_eff) or spd_eff <= 0:
                spd_eff = float(spd_default)
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz_map.get(arm_key)
                if arm_obj is None or tgt is None:
                    continue
                def make_fn(a=arm_obj, t=tgt, k=arm_key, sp=spd_eff):
                    return lambda: (
                        (print(f"[FAST-{pose_name}] {k.upper()} move: ({t['rx']:.1f},{t['ry']:.1f},{t['rz']:.1f}) spd={sp:.2f}") if _should_log_motion_detail(pose_name) else None),
                        a.move_goal(args.move_command, t["rx"], t["ry"], t["rz"], t=gripper_angle, spd=sp)
                    )
                items.append((arm_key, make_fn()))
            _run_threaded_commands(items, f"FAST-{pose_name}")
            group_ok = len(auto_x_action_parallel_errors) == errors_before
            if wait_after is not None:
                time.sleep(float(wait_after))
            if (auto_x_controller.state == "EXECUTING"
                    and group_ok
                    and (str(pose_name) in ("COARSE-AIR-RELEASE-Z-RETRACT", "COARSE-STRETCH-RETRACT")
                         or str(pose_name).startswith("POSE-ROT-VERTICAL-RETRACT"))):
                _a140_note_vertical_clear(str(pose_name))
            return bool(group_ok)

    def parallel_move_targets_with_speed(xyz_map: Dict[str, Dict[str, float]], pose_name: str, gripper_angle: float,
                                             speed_map: Optional[Dict[str, float]] = None,
                                             wait_after: Optional[float] = None):
            """Move both arms in parallel, optionally with per-arm speed.

            Step_b11 uses this only for lift-level pose-rotation waypoints.  If one
            gripper has a much shorter board path than the other, sending both arms
            with the same speed can make one arrive early and stretch the cloth.
            Per-arm speed scaling keeps the gripper pair closer to a rigid motion.
            A152 additionally suppresses every later waypoint after the first
            AUTO-X parallel-command failure.
            """
            if auto_x_controller.state == "EXECUTING" and auto_x_action_parallel_errors:
                print(
                    f"[A152-POSE-ROT-MOVE-SUPPRESSED] pose={pose_name}; "
                    "an earlier arm command failed, so no later rotation waypoint is issued"
                )
                return False
            errors_before = len(auto_x_action_parallel_errors)
            speed_map = speed_map or {}
            items = []
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz_map.get(arm_key)
                if arm_obj is None or tgt is None:
                    continue
                spd_eff = float(speed_map.get(arm_key, spd_default))
                def make_fn(a=arm_obj, t=tgt, k=arm_key, sp=spd_eff):
                    return lambda: (
                        (print(f"[FAST-{pose_name}] {k.upper()} move: ({t['rx']:.1f},{t['ry']:.1f},{t['rz']:.1f}) spd={sp:.3f}") if _should_log_motion_detail(pose_name) else None),
                        a.move_goal(args.move_command, t["rx"], t["ry"], t["rz"], t=gripper_angle, spd=sp)
                    )
                items.append((arm_key, make_fn()))
            _run_threaded_commands(items, f"FAST-{pose_name}")
            group_ok = len(auto_x_action_parallel_errors) == errors_before
            if wait_after is not None:
                time.sleep(float(wait_after))
            return bool(group_ok)

    def parallel_gripper(angle: float, pose_name: str, wait_after: Optional[float] = None):
            if (auto_x_controller.state == "EXECUTING"
                    and auto_x_action_parallel_errors
                    and "OPEN" not in str(pose_name).upper()):
                print(
                    f"[A140-PARALLEL-GRIPPER-SUPPRESSED] pose={pose_name}; "
                    "only release/open cleanup is allowed after a parallel arm failure"
                )
                return False
            errors_before = len(auto_x_action_parallel_errors)
            items = []
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                if arm_obj is None:
                    continue
                def make_fn(a=arm_obj, k=arm_key):
                    return lambda: (
                        (print(f"[FAST-{pose_name}] {k.upper()} gripper angle={angle:.3f}") if _should_log_motion_detail(pose_name) else None),
                        a.set_gripper(float(angle), spd=args.grip_spd, acc=args.grip_acc, delay=0.25)
                    )
                items.append((arm_key, make_fn()))
            _run_threaded_commands(items, f"FAST-{pose_name}")
            group_ok = len(auto_x_action_parallel_errors) == errors_before
            if wait_after is not None:
                time.sleep(float(wait_after))
            if (auto_x_controller.state == "EXECUTING"
                    and group_ok
                    and abs(float(angle) - float(args.grip_open)) <= 1e-6
                    and (str(pose_name) == "COARSE-AIR-RELEASE-OPEN"
                         or str(pose_name) == "COARSE-STRETCH-OPEN"
                         or str(pose_name).startswith("COARSE-STRETCH-SLOW-OPEN-"))):
                _a140_note_release(str(pose_name))
            return bool(group_ok)

    def pose_rotation_gripper(angle: float, pose_name: str, repeat: int = 1, wait_after: Optional[float] = None):
            """Robust T:106 gripper command path for pose rotation only.

            Step_b4 separates wrist/tool-angle motion from gripper commands:
              - T:104 move_goal uses args.t as the wrist/tool angle.
              - T:106 set_gripper uses grip_open/grip_close/grip_hold.

            ARM2 had cases where the close command did not visibly close the gripper,
            so pose rotation defaults to sequential ARM2-first T:106 commands with
            optional repeats.  A152 returns a real success value and latches AUTO-X
            command failures so later non-release motion is not issued blindly.
            """
            rep = max(1, int(repeat))
            cleanup_open = "OPEN" in str(pose_name).upper()
            if (auto_x_controller.state == "EXECUTING"
                    and auto_x_action_parallel_errors
                    and not cleanup_open):
                print(
                    f"[A152-POSE-ROT-GRIPPER-SUPPRESSED] pose={pose_name}; "
                    "an earlier arm command failed"
                )
                return False

            if not bool(getattr(args, "pose_rotate_sequential_gripper", True)):
                ok = True
                for i in range(rep):
                    ok = bool(parallel_gripper(
                        float(angle), f"{pose_name}-{i+1}",
                        wait_after=float(getattr(args, "pose_rotate_gripper_command_delay", 0.35)),
                    )) and ok
                    if not ok and not cleanup_open:
                        break
                if wait_after is not None:
                    time.sleep(float(wait_after))
                return bool(ok)

            order = ["arm2", "arm1"] if str(getattr(args, "pose_rotate_gripper_order", "arm2_first")) == "arm2_first" else ["arm1", "arm2"]
            cmd_delay = max(0.0, float(getattr(args, "pose_rotate_gripper_command_delay", 0.35)))
            errors_before = len(auto_x_action_parallel_errors)
            for i in range(rep):
                for arm_key in order:
                    arm_obj = arms.get(arm_key)
                    if arm_obj is None:
                        continue
                    if _should_log_motion_detail(str(pose_name)):
                        print(f"[POSE-GRIPPER-{pose_name}] {arm_key.upper()} T:106 cmd={float(angle):.3f} repeat={i+1}/{rep}")
                    try:
                        arm_obj.set_gripper(float(angle), spd=args.grip_spd, acc=args.grip_acc, delay=cmd_delay)
                    except Exception as e:
                        print(f"[POSE-GRIPPER-{pose_name}-ERROR] {arm_key.upper()}: {repr(e)}")
                        if auto_x_controller.state == "EXECUTING":
                            auto_x_action_parallel_errors.append(f"POSE-GRIPPER-{pose_name}:{arm_key}:{repr(e)}")
                        if not cleanup_open:
                            return False
                if i + 1 < rep:
                    time.sleep(cmd_delay)
            if wait_after is not None:
                time.sleep(float(wait_after))
            return bool(len(auto_x_action_parallel_errors) == errors_before)

    def set_all_torque(enable: bool):
        nonlocal torque_released
        with motion_lock:
            busy = motion_busy
        if busy:
            print("[TORQUE-BLOCKED] Robot is moving. Stop/finish motion before changing torque.")
            return
        any_arm = False
        for _arm_key, arm_obj in arms.items():
            if arm_obj is None:
                continue
            any_arm = True
            if enable:
                print(f"[TORQUE] {_arm_key.upper()} torque ON")
                arm_obj.torque_on()
            else:
                print(f"[TORQUE] {_arm_key.upper()} torque OFF")
                arm_obj.torque_off()
        if not any_arm:
            print("[TORQUE] No serial arm is connected. Run with --send and check /dev/roarm_*.")
            return
        torque_released = not enable

    def toggle_all_torque():
        set_all_torque(enable=torque_released)

    def start_arm1_calibration():
        nonlocal calibration_mode, calib_sequence, calib_index, temp_roarm_xy, temp_roarm_z
        if not args.send:
            print("[CALIB-ERROR] Run with --send --arm1-port ... --arm2-port ...")
            return
        calibration_mode = True
        calib_index = 0
        temp_roarm_xy = {"arm1": [], "arm2": []}
        temp_roarm_z = {"arm1": [], "arm2": []}
        calib_sequence = []
        for arm_key in ("arm2", "arm1"):
            for point in cfg["dual_roarm"][arm_key]["calib_points"]:
                calib_sequence.append((arm_key, point))
        print("\n========== DUAL-ARM STEP1 CALIBRATION START ==========")
        print("ARM2: ID0 -> ID1 -> RED_EXTRA")
        print("ARM1: ID2 -> ID3 -> BLUE_EXTRA")
        print("At each step: active arm torque OFF, manually place gripper tip on the point, then press Enter.")
        print("======================================================\n")
        show_calib_step()

    def show_calib_step():
        if not calibration_mode or calib_index >= len(calib_sequence):
            return
        arm_key, point = calib_sequence[calib_index]
        for other_key, other_obj in arms.items():
            if other_obj is not None and other_key != arm_key:
                try:
                    other_obj.torque_on()
                except Exception:
                    pass
        arm_obj = arms.get(arm_key)
        if arm_obj is not None:
            print(f"[CALIB] {arm_key.upper()} torque OFF for manual positioning")
            arm_obj.torque_off()
        label = point["label"]
        bx, by = point["board_xy"]
        print(f"[CALIB] STEP {calib_index + 1}/{len(calib_sequence)}: {arm_key.upper()} -> {label} board=({bx:.1f},{by:.1f})")
        print("[CALIB] Move gripper tip exactly above this physical point, then press Enter.")

    def finish_calibration():
        nonlocal calibration_mode
        print("\n========== DUAL-ARM STEP1 CALIBRATION RESULT ==========")
        for arm_key in ("arm2", "arm1"):
            points = cfg["dual_roarm"][arm_key]["calib_points"]
            board_pts = np.array([p["board_xy"] for p in points], dtype=float)
            roarm_pts = np.array(temp_roarm_xy[arm_key], dtype=float)
            if len(roarm_pts) != len(board_pts):
                print(f"[CALIB-ERROR] {arm_key}: insufficient points")
                calibration_mode = False
                return
            M, pred, err = compute_affine(board_pts, roarm_pts)
            cfg["dual_roarm"][arm_key]["calib_roarm_points"] = roarm_pts.tolist()
            cfg["dual_roarm"][arm_key]["calib_roarm_z"] = temp_roarm_z[arm_key]
            cfg["dual_roarm"][arm_key]["board_to_roarm_affine_2x3"] = M.tolist()
            z_arr = np.array(temp_roarm_z[arm_key], dtype=float)
            finite_z = z_arr[np.isfinite(z_arr)]
            if len(finite_z) > 0:
                cfg["dual_roarm"][arm_key]["grip_z"] = float(finite_z.mean())
            print(f"\n[{arm_key.upper()}] affine:")
            print(json.dumps(M.tolist(), indent=2))
            for p, b, r, pr, e in zip(points, board_pts, roarm_pts, pred, err):
                print(f"  {p['label']}: board=({b[0]:.1f},{b[1]:.1f}) measured=({r[0]:.1f},{r[1]:.1f}) pred=({pr[0]:.1f},{pr[1]:.1f}) err={e:.2f} mm")
            print(f"  mean error={err.mean():.2f} mm, max error={err.max():.2f} mm")
            print(f"  calibrated grip_z={cfg['dual_roarm'][arm_key].get('grip_z')}")
            arm_obj = arms.get(arm_key)
            if arm_obj is not None:
                arm_obj.torque_on()
        save_config(args.config, cfg)
        print(f"[CALIB] authoritative config saved: {os.path.abspath(args.config)}")
        if str(args.calib_cache or "").strip():
            cache_parent = os.path.dirname(os.path.abspath(args.calib_cache))
            if cache_parent:
                os.makedirs(cache_parent, exist_ok=True)
            with open(args.calib_cache, "w", encoding="utf-8") as f:
                json.dump({"created_at_unix": time.time(), "dual_roarm": cfg["dual_roarm"]}, f, ensure_ascii=False, indent=2)
            print(f"[CALIB] optional affine cache saved: {args.calib_cache}")
        else:
            print("[CALIB] separate affine cache disabled; calibration stored in authoritative config only")
        calibration_mode = False
        print("========== CALIBRATION FINISHED ==========\n")
        if not args.no_standby:
            move_arms_to_standby(reason="after calibration")
        reset_snapshot("calibration finished")

    def capture_calib_point():
        nonlocal calib_index
        if not calibration_mode:
            return
        if calib_index >= len(calib_sequence):
            return
        arm_key, point = calib_sequence[calib_index]
        arm_obj = arms.get(arm_key)
        if arm_obj is None:
            print(f"[CALIB-ERROR] {arm_key} serial not connected")
            return
        print(f"[CALIB] Request {arm_key.upper()} feedback for {point['label']}")
        fb = arm_obj.feedback(timeout=2.5)
        if fb is None or "x" not in fb or "y" not in fb:
            print("[CALIB-ERROR] feedback failed. Press Enter again after checking serial.")
            return
        x = float(fb["x"]); y = float(fb["y"]); z = float(fb.get("z", float("nan")))
        temp_roarm_xy[arm_key].append([x, y])
        temp_roarm_z[arm_key].append(z)
        print(f"[CALIB] saved {arm_key.upper()} {point['label']}: roarm=({x:.2f},{y:.2f}), z={z:.2f}")
        calib_index += 1
        if calib_index >= len(calib_sequence):
            finish_calibration()
        else:
            show_calib_step()

    def undo_calib_point():
        nonlocal calib_index
        if not calibration_mode or calib_index <= 0:
            print("[CALIB] nothing to undo")
            return
        calib_index -= 1
        arm_key, point = calib_sequence[calib_index]
        if temp_roarm_xy[arm_key]:
            temp_roarm_xy[arm_key].pop()
        if temp_roarm_z[arm_key]:
            temp_roarm_z[arm_key].pop()
        print(f"[CALIB] undone: {arm_key.upper()} {point['label']}")
        show_calib_step()

    def get_arm_grip_z(arm_key: str) -> Optional[float]:
        # IMPORTANT: arm-specific z must override common --grip-z.
        # Previous step13 checked common grip_z first, so --arm1-grip-z was effectively ignored
        # when the default common grip_z=-115 was present.
        if arm_key == "arm1" and args.arm1_grip_z is not None:
            return float(args.arm1_grip_z)
        if arm_key == "arm2" and args.arm2_grip_z is not None:
            return float(args.arm2_grip_z)
        if args.grip_z is not None:
            return float(args.grip_z)
        z = cfg["dual_roarm"][arm_key].get("grip_z")
        return None if z is None else float(z)

    def get_arm_lift_z(arm_key: str) -> float:
        if arm_key == "arm1" and args.arm1_grip_lift_z is not None:
            return float(args.arm1_grip_lift_z)
        if arm_key == "arm2" and args.arm2_grip_lift_z is not None:
            return float(args.arm2_grip_lift_z)
        return float(lift_z)

    def get_pose_rotate_grip_z(arm_key: str) -> Optional[float]:
        """motion_v4 ROTATE-only contact Z; other actions keep get_arm_grip_z()."""
        if arm_key == "arm1":
            value = getattr(args, "pose_rotate_arm1_grip_z", None)
            if value is not None:
                return float(value)
        if arm_key == "arm2":
            value = getattr(args, "pose_rotate_arm2_grip_z", None)
            if value is not None:
                return float(value)
        return get_arm_grip_z(arm_key)

    def get_pose_rotate_lift_z(arm_key: str) -> float:
        """motion_v7 pose-rotation-only lift; positive extra Z lifts farther from the board.

        ARM1 keeps the legacy +20mm ROTATE-only lift. ARM2 defaults to 0mm extra
        because the 2026-08-12 VLA log showed repeatable saturation near the base
        lift (~-80mm) while the former -60mm target missed the 20mm Z tolerance.
        """
        base = float(get_arm_lift_z(arm_key))
        if str(arm_key) == "arm2":
            arm2_extra = getattr(args, "pose_rotate_arm2_lift_extra_mm", None)
            if arm2_extra is not None:
                extra = max(0.0, float(arm2_extra))
            else:
                extra = max(0.0, float(getattr(args, "pose_rotate_lift_extra_mm", 20.0)))
        else:
            extra = max(0.0, float(getattr(args, "pose_rotate_lift_extra_mm", 20.0)))
        return float(base + extra)

    def resolve_target_from_pixel(pixel_point, rz: float, source="TARGET"):
            if latest_H is None:
                print("[TARGET] Homography not available. Show all markers and press L.")
                return None
            x, y = as_int_point(pixel_point)
            bx, by = pixel_to_board(latest_H, x, y)
            arm_key = select_arm_for_board_x(cfg, bx)
            if arm_key is None:
                dual = cfg.get("dual_roarm", {})
                split_x_local = float(dual.get("split_board_x", 247.0))
                dead_half_local = float(dual.get("workspace", {}).get("dead_half_width", USER_SETTINGS["workspace_dead_half_width"]))
                print(f"[ZONE-BLOCKED] board x={bx:.1f} is in center dead-zone "
                      f"({split_x_local - dead_half_local:.1f} < x < {split_x_local + dead_half_local:.1f}). No arm selected in step1.")
                return None
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
            except Exception as e:
                print(f"[TARGET-BLOCKED] {e}")
                return None
            if (not TEMP_HIDE_BOARD_TO_ROARM_LOGS) and ((not bool(getattr(args, "compact_motion_log", True))) or bool(getattr(args, "pose_rotate_target_logs", False)) or not str(source).startswith("POSE-ROT")):
                print(f"[{source}] pixel=({x},{y}) -> board=({bx:.1f},{by:.1f}) -> {arm_key.upper()} roarm=({rx:.1f},{ry:.1f},{rz:.1f})")
            if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, args.board_margin)):
                print("[TARGET-BLOCKED] board coordinate outside board bounds")
                return None
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
                print("[TARGET-BLOCKED] RoArm target outside safety range")
                return None
            return arm_key, bx, by, rx, ry, float(rz)

    def pick_latest():
        if latest_candidate is None or latest_point is None:
            print("[PICK] No selected grasp point yet. Wait for YOLO candidate or run with --grasp-model.")
            return
        target_hover = resolve_target_from_pixel(latest_point, approach_z, source="PICK-HOVER")
        if target_hover is None:
            return
        arm_key, bx, by, rx_h, ry_h, rz_h = target_hover
        grip_z = get_arm_grip_z(arm_key)
        if grip_z is None:
            print(f"[PICK-BLOCKED] {arm_key.upper()} grip_z is not set. Press C to calibrate or pass --grip-z.")
            return
        target_grip = resolve_target_from_pixel(latest_point, grip_z, source="PICK-GRIP")
        target_lift = resolve_target_from_pixel(latest_point, lift_z, source="PICK-LIFT")
        if target_grip is None or target_lift is None:
            return
        _, _, _, rx_g, ry_g, rz_g = target_grip
        _, _, _, rx_l, ry_l, rz_l = target_lift
        arm_obj = arms.get(arm_key)
        print("\n========== PICK ==========")
        print(f"Selected arm: {arm_key.upper()} ({cfg['dual_roarm'][arm_key]['side']})")
        print(f"Object: {latest_candidate.get('object_index')}:{latest_candidate.get('class_name')} conf={latest_candidate.get('conf'):.2f}")
        print(f"Point: board=({bx:.1f},{by:.1f}), target={selected_grasp_key}")
        if args.place_after_lift:
            print("Sequence: hover -> descend -> OPEN wait -> LIMITED CLOSE -> small lift -> place same/custom XY -> open -> retract")
        else:
            print("Sequence: hover -> descend -> OPEN wait -> LIMITED CLOSE -> lift only")
        print("==========================\n")
        if send_enabled and arm_obj is not None:
            arm_obj.torque_on()

            print(f"[PICK] open gripper before approach: angle={args.grip_open:.3f}")
            arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(0.40)

            print(f"[PICK] move hover: ({rx_h:.1f}, {ry_h:.1f}, {rz_h:.1f})")
            arm_obj.move_goal(args.move_command, rx_h, ry_h, rz_h, t=args.grip_open, spd=spd_default)
            time.sleep(args.grip_down_wait)

            print(f"[PICK] descend to grip point: ({rx_g:.1f}, {ry_g:.1f}, {rz_g:.1f})")
            arm_obj.move_goal(args.move_command, rx_g, ry_g, rz_g, t=args.grip_open, spd=spd_default)
            time.sleep(args.grip_down_wait)

            print(f"[PICK] gripper OPEN at grip point, waiting {args.grip_open_wait:.2f}s before close")
            arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(args.grip_open_wait)
            time.sleep(args.grip_contact_wait)

            close_repeat = max(1, int(args.grip_close_repeat))
            for i in range(close_repeat):
                print(f"[PICK] LIMITED CLOSE {i+1}/{close_repeat}: angle={args.grip_close:.3f}; lift is NOT sent yet")
                arm_obj.gripper_close(args.grip_close, spd=args.grip_spd, acc=args.grip_acc)
                time.sleep(args.grip_close_wait)

            if abs(float(args.grip_hold) - float(args.grip_close)) > 1e-6:
                print(f"[PICK] setting hold angle before lift: {args.grip_hold:.3f}")
                arm_obj.set_gripper(args.grip_hold, spd=args.grip_spd, acc=args.grip_acc, delay=0.3)
            print(f"[PICK] close-settle wait {args.grip_close_settle:.2f}s, then lift while holding limited close")
            time.sleep(args.grip_close_settle)

            # 6) Lift only after full-close phase is finished.
            print(f"[PICK] lifting with limited close/hold: ({rx_l:.1f}, {ry_l:.1f}, {rz_l:.1f})")
            arm_obj.move_goal(args.move_command, rx_l, ry_l, rz_l, t=args.grip_hold, spd=spd_default)
            time.sleep(args.place_settle_wait)

            if args.place_after_lift:
                if args.place_same_xy:
                    px, py = float(bx), float(by)
                    place_desc = "same XY"
                else:
                    px = float(args.place_board_x if args.place_board_x is not None else bx)
                    py = float(args.place_board_y if args.place_board_y is not None else by)
                    place_desc = "custom XY"

                # safety: do not place into the center dead-zone or the other arm's private area.
                place_arm_key = select_arm_for_board_x(cfg, px)
                if place_arm_key != arm_key:
                    print(f"[PLACE-BLOCKED] place target board=({px:.1f},{py:.1f}) would use {place_arm_key}; "
                          f"current arm is {arm_key}. Step1 blocks cross-zone placing.")
                elif (not args.allow_outside_board) and (not is_board_safe(cfg, px, py, args.board_margin)):
                    print("[PLACE-BLOCKED] place board coordinate outside board bounds")
                else:
                    pz_hover = float(args.place_hover_z if args.place_hover_z is not None else lift_z)
                    pz_down = float(args.place_z if args.place_z is not None else grip_z)
                    prx, pry = board_to_arm_xy(cfg, arm_key, px, py)
                    if is_xyz_safe(prx, pry, pz_hover, args) and is_xyz_safe(prx, pry, pz_down, args):
                        if TEMP_HIDE_BOARD_TO_ROARM_LOGS:
                            print(f"[PLACE] {place_desc}: move to place height and release")
                        else:
                            print(f"[PLACE] {place_desc}: board=({px:.1f},{py:.1f}) -> roarm=({prx:.1f},{pry:.1f}) "
                                  f"hover_z={pz_hover:.1f}, place_z={pz_down:.1f}")
                        arm_obj.move_goal(args.move_command, prx, pry, pz_hover, t=args.grip_hold, spd=spd_default)
                        time.sleep(args.place_settle_wait)
                        arm_obj.move_goal(args.move_command, prx, pry, pz_down, t=args.grip_hold, spd=spd_default)
                        time.sleep(args.place_settle_wait)
                        print(f"[PLACE] opening gripper at place point: angle={args.grip_open:.3f}")
                        arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
                        time.sleep(args.place_open_wait)
                        if args.place_retract_after_open:
                            print(f"[PLACE] retract after open: ({prx:.1f}, {pry:.1f}, {pz_hover:.1f})")
                            arm_obj.move_goal(args.move_command, prx, pry, pz_hover, t=safe_gripper, spd=spd_default)
                            time.sleep(args.place_settle_wait)
                    else:
                        print("[PLACE-BLOCKED] place target outside RoArm safety range")

            if args.relax_after_lift and not args.place_after_lift:
                post_angle = float(args.post_lift_gripper if args.post_lift_gripper is not None else args.grip_hold)
                print(f"[PICK] optional post-lift relax angle={post_angle:.3f}")
                time.sleep(0.40)
                arm_obj.set_gripper(post_angle, spd=args.grip_spd, acc=args.grip_acc, delay=0.30)

            if (not args.place_after_lift) and args.auto_place:
                px = float(args.place_board_x if args.place_board_x is not None else (min_bx + max_bx) / 2.0)
                py = float(args.place_board_y if args.place_board_y is not None else (min_by + max_by) / 2.0)
                pz_hover = float(args.place_hover_z if args.place_hover_z is not None else lift_z)
                pz_down = float(args.place_z if args.place_z is not None else grip_z)
                prx, pry = board_to_arm_xy(cfg, arm_key, px, py)
                if is_xyz_safe(prx, pry, pz_hover, args) and is_xyz_safe(prx, pry, pz_down, args):
                    print(f"[PLACE] board=({px:.1f},{py:.1f}) with {arm_key.upper()}")
                    time.sleep(0.8)
                    arm_obj.move_goal(args.move_command, prx, pry, pz_hover, t=args.grip_hold, spd=spd_default)
                    time.sleep(1.0)
                    arm_obj.move_goal(args.move_command, prx, pry, pz_down, t=args.grip_hold, spd=spd_default)
                    time.sleep(0.8)
                    arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
                    time.sleep(0.8)
                    arm_obj.move_goal(args.move_command, prx, pry, pz_hover, t=safe_gripper, spd=spd_default)
                else:
                    print("[PLACE-BLOCKED] place target outside safety range")
        else:
            print("[DRY-RUN] Pick command not sent.")

    def recompute_dual_plan(print_result: bool = True):
        nonlocal latest_dual_plan, latest_dual_status
        latest_dual_plan, latest_dual_status = build_dual_plan_from_candidates(
            cfg, latest_H, latest_candidates, left_key=args.dual_left_key, right_key=args.dual_right_key)
        if print_result:
            if latest_dual_plan is None:
                print(f"[DUAL] not ready: {latest_dual_status}")
            else:
                l = latest_dual_plan["targets"]["arm2"]["board_xy"]
                r = latest_dual_plan["targets"]["arm1"]["board_xy"]
                print("\n========== DUAL CANDIDATE ==========")
                print(f"Object: {latest_dual_plan['summary']}")
                print(f"ARM2 target: key={latest_dual_plan['targets']['arm2']['key']} board=({l[0]:.1f},{l[1]:.1f})")
                print(f"ARM1 target: key={latest_dual_plan['targets']['arm1']['key']} board=({r[0]:.1f},{r[1]:.1f})")
                print("H: dual hover only | J: same-snapshot dual grip-place | B: sequential safety test with re-infer before second arm.")
                print("====================================\n")
        return latest_dual_plan

    def print_coarse_plan():
        if latest_coarse_plan is not None:
            a2 = latest_coarse_plan["targets"]["arm2"]["board_xy"]
            a1 = latest_coarse_plan["targets"]["arm1"]["board_xy"]
            m = latest_coarse_plan.get("metrics", {})
            major = m.get("major_len_board")
            minor = m.get("minor_len_board")
            major_txt = "?" if major is None else f"{major:.1f}mm"
            minor_txt = "?" if minor is None else f"{minor:.1f}mm"
            print("\n========== COARSE SPREAD PREVIEW ==========")
            print("This is NOT shoulder detection. It is a minor-first random-cloth spread preview.")
            axis = m.get("axis_mode", "?")
            print(f"ARM2-SPREAD board=({a2[0]:.1f},{a2[1]:.1f}) local={m.get('arm2_local_ratio', 0):.2f}")
            print(f"ARM1-SPREAD board=({a1[0]:.1f},{a1[1]:.1f}) local={m.get('arm1_local_ratio', 0):.2f}")
            print(f"axis={axis} area={m.get('area_px', 0):.0f}px solidity={m.get('solidity', 0):.3f} "
                  f"major={major_txt} minor={minor_txt} x_sep={m.get('x_separation', 0):.1f} y_diff={m.get('y_diff', 0):.1f}")
            print("==========================================\n")
        else:
            print(f"[COARSE] not ready: {latest_coarse_status}")

    def recompute_coarse_plan(print_result: bool = True):
        nonlocal latest_coarse_plan, latest_coarse_status
        latest_coarse_plan, latest_coarse_status = build_coarse_spread_plan_from_candidates(
            cfg, latest_H, latest_candidates,
            inside_ratio=args.coarse_inside_ratio,
            min_board_separation=args.coarse_min_board_separation,
            max_board_y_diff=args.coarse_max_board_y_diff,
            axis_mode=get_effective_coarse_axis_mode(),
            endpoint_band_ratio=args.coarse_endpoint_band_ratio,
            local_radius=args.coarse_local_mask_radius,
            min_local_ratio=args.coarse_min_local_mask_ratio,
            min_side_pixels=args.coarse_min_side_pixels,
            relaxed_minor=args.coarse_relaxed_minor,
            relaxed_min_board_separation=args.coarse_relaxed_min_board_separation,
            relaxed_endpoint_band_ratio=args.coarse_relaxed_endpoint_band_ratio,
            relaxed_local_radius=args.coarse_relaxed_local_mask_radius,
            relaxed_min_local_ratio=args.coarse_relaxed_min_local_mask_ratio,
            relaxed_min_side_pixels=args.coarse_relaxed_min_side_pixels,
            relaxed_max_board_y_diff=args.coarse_relaxed_max_board_y_diff,
            board_y_min_y_separation=args.coarse_board_y_min_y_separation,
            board_y_endpoint_band_ratio=args.coarse_board_y_endpoint_band_ratio,
            board_y_local_radius=args.coarse_board_y_local_mask_radius,
            board_y_min_local_ratio=args.coarse_board_y_min_local_mask_ratio,
            board_y_min_side_pixels=args.coarse_board_y_min_side_pixels)
        if print_result:
            print_coarse_plan()
        return latest_coarse_plan

    def pick_dual_sequential():
        # safety test: first arm uses the current dual plan.
        # Before the second arm moves, re-infer by default because the first arm may disturb the cloth.
        # This is intentionally NOT simultaneous dual-arm low-Z motion yet.
        nonlocal latest_candidate, latest_point, selected_grasp_key
        plan = latest_dual_plan if latest_dual_plan is not None else recompute_dual_plan(print_result=True)
        if plan is None:
            print(f"[DUAL-PICK-BLOCKED] {latest_dual_status}")
            return

        order = ["arm2", "arm1"] if args.dual_sequential_order == "arm2_first" else ["arm1", "arm2"]
        print("\n========== DUAL SEQUENTIAL PICK-PLACE TEST ==========")
        print("This does NOT move both arms down at the same time.")
        print("It tests whether the two detected left/right targets can be handled by their assigned arms.")
        print(f"Order: {' -> '.join([x.upper() for x in order])}")
        print("=====================================================\n")

        old_candidate = latest_candidate
        old_point = latest_point
        old_key = selected_grasp_key
        try:
            for idx, arm_key in enumerate(order):
                if idx > 0 and args.reinfer_between_dual_arms:
                    print(f"[DUAL-PICK] {order[idx-1].upper()} finished. Re-inferring before {arm_key.upper()} because the cloth may have moved.")
                    fresh_plan = request_fresh_dual_plan_and_wait(
                        reason=f"between {order[idx-1].upper()} and {arm_key.upper()}",
                        timeout=float(args.reinfer_between_dual_arms_timeout),
                    )
                    if fresh_plan is None:
                        print(f"[DUAL-PICK-BLOCKED] Cannot safely update target for {arm_key.upper()}. Stop B sequence.")
                        return
                    plan = fresh_plan

                target = plan["targets"].get(arm_key)
                if target is None:
                    print(f"[DUAL-PICK-BLOCKED] missing target for {arm_key.upper()}")
                    return
                selected_grasp_key = target.get("key", old_key)
                latest_candidate = plan["candidate"]
                latest_point = target["point"]
                bx, by = target["board_xy"]
                print(f"[DUAL-PICK] {arm_key.upper()} using {selected_grasp_key}: board=({bx:.1f},{by:.1f})")
                pick_latest()
                time.sleep(max(0.2, float(args.place_settle_wait)))
        finally:
            selected_grasp_key = old_key
            latest_candidate = old_candidate
            latest_point = old_point


    def validate_dual_plan_for_step3(plan: Optional[Dict[str, Any]], label: str = "DUAL") -> bool:
        if plan is None:
            print(f"[{label}-BLOCKED] dual plan is not ready: {latest_dual_status}")
            return False
        try:
            a2 = plan["targets"]["arm2"]
            a1 = plan["targets"]["arm1"]
            bx2, by2 = a2["board_xy"]
            bx1, by1 = a1["board_xy"]
        except Exception as e:
            print(f"[{label}-BLOCKED] invalid dual plan structure: {repr(e)}")
            return False

        sep_x = float(bx1) - float(bx2)
        min_sep = float(args.dual_min_board_x_separation)
        if sep_x < min_sep:
            print(f"[{label}-BLOCKED] dual targets are too close in board-x: sep={sep_x:.1f}mm < {min_sep:.1f}mm")
            return False
        if select_arm_for_board_x(cfg, float(bx2)) != "arm2":
            print(f"[{label}-BLOCKED] ARM2 target is not in ARM2 private workspace: x={bx2:.1f}")
            return False
        if select_arm_for_board_x(cfg, float(bx1)) != "arm1":
            print(f"[{label}-BLOCKED] ARM1 target is not in ARM1 private workspace: x={bx1:.1f}")
            return False
        print(f"[{label}] geometry OK: ARM2 x={bx2:.1f}, ARM1 x={bx1:.1f}, sep={sep_x:.1f}mm")
        return True

    def resolve_dual_target_for_arm(plan: Dict[str, Any], arm_key: str, rz: float, source: str) -> Optional[Dict[str, float]]:
            target = plan["targets"].get(arm_key)
            if target is None:
                print(f"[{source}-BLOCKED] missing target for {arm_key.upper()}")
                return None
            bx, by = [float(v) for v in target["board_xy"]]
            expected = select_arm_for_board_x(cfg, bx)
            if expected != arm_key:
                print(f"[{source}-BLOCKED] board=({bx:.1f},{by:.1f}) belongs to {expected}, not {arm_key}")
                return None
            if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, args.board_margin)):
                print(f"[{source}-BLOCKED] {arm_key.upper()} board coordinate outside board bounds")
                return None
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
            except Exception as e:
                print(f"[{source}-BLOCKED] {arm_key.upper()} affine error: {e}")
                return None
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
                print(f"[{source}-BLOCKED] {arm_key.upper()} RoArm target outside safety range: ({rx:.1f},{ry:.1f},{rz:.1f})")
                return None
            if (not TEMP_HIDE_BOARD_TO_ROARM_LOGS) and ((not bool(getattr(args, "compact_motion_log", True))) or not str(source).startswith(("POSE-ROT", "DUAL"))):
                print(f"[{source}] {arm_key.upper()} board=({bx:.1f},{by:.1f}) -> roarm=({rx:.1f},{ry:.1f},{rz:.1f})")
            return {"arm_key": arm_key, "bx": bx, "by": by, "rx": float(rx), "ry": float(ry), "rz": float(rz)}

    def resolve_dual_plan_xyz(plan: Dict[str, Any]) -> Optional[Dict[str, Dict[str, Dict[str, float]]]]:
        grip_z_map = {}
        for arm_key in ("arm2", "arm1"):
            gz = get_arm_grip_z(arm_key)
            if gz is None:
                print(f"[DUAL-BLOCKED] {arm_key.upper()} grip_z is not set. Press C to calibrate or pass --grip-z.")
                return None
            grip_z_map[arm_key] = float(gz)

        out = {"arm2": {}, "arm1": {}}
        for arm_key in ("arm2", "arm1"):
            hover = resolve_dual_target_for_arm(plan, arm_key, approach_z, f"DUAL-HOVER-{arm_key.upper()}")
            grip = resolve_dual_target_for_arm(plan, arm_key, grip_z_map[arm_key], f"DUAL-GRIP-{arm_key.upper()}")
            lift = resolve_dual_target_for_arm(plan, arm_key, lift_z, f"DUAL-LIFT-{arm_key.upper()}")
            pz_hover = float(args.place_hover_z if args.place_hover_z is not None else lift_z)
            pz_down = float(args.place_z if args.place_z is not None else grip_z_map[arm_key])
            place_hover = resolve_dual_target_for_arm(plan, arm_key, pz_hover, f"DUAL-PLACE-HOVER-{arm_key.upper()}")
            place_down = resolve_dual_target_for_arm(plan, arm_key, pz_down, f"DUAL-PLACE-{arm_key.upper()}")
            if None in (hover, grip, lift, place_hover, place_down):
                return None
            out[arm_key] = {
                "hover": hover,
                "grip": grip,
                "lift": lift,
                "place_hover": place_hover,
                "place_down": place_down,
            }
        return out

    def move_both_to_dual_hover():
        # same snapshot dual plan, hover only. No low-Z and no gripper close.
        plan = latest_dual_plan if latest_dual_plan is not None else recompute_dual_plan(print_result=True)
        if not validate_dual_plan_for_step3(plan, label="DUAL-HOVER"):
            return
        xyz = resolve_dual_plan_xyz(plan)
        if xyz is None:
            return

        print("\n========== DUAL HOVER TEST (H) ==========")
        print("Both arms move only to safe hover above their targets. No descent, no close.")
        print("Check clearance, camera occlusion, cable path, and whether each arm is above the correct side.")
        print("========================================\n")
        if send_enabled:
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                if arm_obj is not None:
                    arm_obj.torque_on()
                    arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(0.20)
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz[arm_key]["hover"]
                if arm_obj is not None:
                    print(f"[DUAL-HOVER] moving {arm_key.upper()} to hover")
                    arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                    time.sleep(0.15)
            time.sleep(float(args.dual_hover_wait))
        else:
            print("[DRY-RUN] Dual hover commands not sent.")


    def validate_coarse_plan_for_hover(plan: Optional[Dict[str, Any]], label: str = "COARSE-HOVER") -> bool:
        """Validate the current coarse SPREAD plan for hover-only motion.

        This is intentionally lighter than grip/place validation:
        - The plan was already generated from real mask pixels and workspace checks.
        - Hover-only motion does not need grip_z/place_z.
        - Still verify that ARM2 target belongs to the left private workspace and ARM1 to the right.
        """
        if plan is None:
            print(f"[{label}-BLOCKED] coarse spread plan is not ready: {latest_coarse_status}")
            return False
        try:
            a2 = plan["targets"]["arm2"]
            a1 = plan["targets"]["arm1"]
            bx2, by2 = [float(v) for v in a2["board_xy"]]
            bx1, by1 = [float(v) for v in a1["board_xy"]]
        except Exception as e:
            print(f"[{label}-BLOCKED] invalid coarse plan structure: {repr(e)}")
            return False

        arm2_zone = select_arm_for_board_x(cfg, bx2)
        arm1_zone = select_arm_for_board_x(cfg, bx1)
        if arm2_zone != "arm2":
            print(f"[{label}-BLOCKED] ARM2-SPREAD is not in ARM2 private workspace: board=({bx2:.1f},{by2:.1f}) -> {arm2_zone}")
            return False
        if arm1_zone != "arm1":
            print(f"[{label}-BLOCKED] ARM1-SPREAD is not in ARM1 private workspace: board=({bx1:.1f},{by1:.1f}) -> {arm1_zone}")
            return False
        if (not args.allow_outside_board):
            if not is_board_safe(cfg, bx2, by2, args.board_margin):
                print(f"[{label}-BLOCKED] ARM2-SPREAD board coordinate outside board bounds: ({bx2:.1f},{by2:.1f})")
                return False
            if not is_board_safe(cfg, bx1, by1, args.board_margin):
                print(f"[{label}-BLOCKED] ARM1-SPREAD board coordinate outside board bounds: ({bx1:.1f},{by1:.1f})")
                return False
        sep = abs(bx1 - bx2)
        ydiff = abs(by1 - by2)
        mode = plan.get("metrics", {}).get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?"))
        print(f"[{label}] geometry OK: mode={mode} ARM2=({bx2:.1f},{by2:.1f}) ARM1=({bx1:.1f},{by1:.1f}) sep={sep:.1f}mm ydiff={ydiff:.1f}mm")
        return True

    def resolve_coarse_hover_xyz(plan: Dict[str, Any]) -> Optional[Dict[str, Dict[str, float]]]:
        """Resolve only hover targets for the current coarse SPREAD plan.

        Unlike resolve_dual_plan_xyz(), this does not require grip_z/lift/place targets.
        The next step is only a safe hover check above ARM2-SPREAD and ARM1-SPREAD.
        """
        out: Dict[str, Dict[str, float]] = {}
        for arm_key in ("arm2", "arm1"):
            hover = resolve_dual_target_for_arm(plan, arm_key, approach_z, f"COARSE-HOVER-{arm_key.upper()}")
            if hover is None:
                return None
            out[arm_key] = hover
        return out

    def move_both_to_coarse_spread_hover():
        plan = latest_coarse_plan if latest_coarse_plan is not None else recompute_coarse_plan(print_result=True)
        if not validate_coarse_plan_for_hover(plan, label="COARSE-HOVER"):
            return
        xyz = resolve_coarse_hover_xyz(plan)
        if xyz is None:
            return

        metrics = plan.get("metrics", {}) if isinstance(plan, dict) else {}
        mode = metrics.get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?")) if isinstance(plan, dict) else "?"
        src = plan.get("candidate", {}).get("class_name", "?") if isinstance(plan, dict) else "?"
        a2 = plan["targets"]["arm2"]["board_xy"]
        a1 = plan["targets"]["arm1"]["board_xy"]

        print("\n========== COARSE SPREAD HOVER TEST (O) ==========")
        print("This uses ARM2-SPREAD / ARM1-SPREAD from the current coarse plan.")
        print("Sequence: open both grippers -> move both arms to safe hover above SPREAD points.")
        print("No descent, no close, no lift, no stretch, no cloth contact.")
        print(f"mode={mode}, source={src}")
        print(f"ARM2-SPREAD board=({a2[0]:.1f},{a2[1]:.1f})")
        print(f"ARM1-SPREAD board=({a1[0]:.1f},{a1[1]:.1f})")
        print("Check whether the gripper tips hover above the displayed SPREAD points and whether arms collide/occlude.")
        print("=================================================\n")

        if send_enabled:
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                if arm_obj is not None:
                    arm_obj.torque_on()
                    print(f"[COARSE-HOVER] opening {arm_key.upper()} gripper before hover")
                    arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(0.25)
            # Hover-only movement is issued sequentially for initial safety.
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz.get(arm_key)
                if arm_obj is not None and tgt is not None:
                    print(f"[COARSE-HOVER] moving {arm_key.upper()} to SPREAD hover: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                    arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                    time.sleep(0.15)
            time.sleep(float(args.coarse_hover_wait))
        else:
            print("[DRY-RUN] Coarse spread hover commands not sent.")

    def resolve_coarse_grip_xyz(plan: Dict[str, Any]) -> Optional[Dict[str, Dict[str, Dict[str, float]]]]:
        """Resolve hover, grip_z, and small-lift targets for the current coarse SPREAD plan.

        This uses the same ARM2-SPREAD / ARM1-SPREAD board points as the preview overlay.
        It does not compute stretch/place targets. Step10 is only a contact/grip validation stage.
        """
        grip_z_map: Dict[str, float] = {}
        for arm_key in ("arm2", "arm1"):
            gz = get_arm_grip_z(arm_key)
            if gz is None:
                print(f"[COARSE-GRIP-BLOCKED] {arm_key.upper()} grip_z is not set. Press C to calibrate or pass --grip-z.")
                return None
            grip_z_map[arm_key] = float(gz)

        lift_z_map: Dict[str, float] = {arm_key: get_arm_lift_z(arm_key) for arm_key in ("arm2", "arm1")}
        print(f"[COARSE-Z] effective grip_z: ARM2={grip_z_map['arm2']:.1f}, ARM1={grip_z_map['arm1']:.1f}; "
              f"lift_z: ARM2={lift_z_map['arm2']:.1f}, ARM1={lift_z_map['arm1']:.1f}; speed={spd_default:.2f}")

        out: Dict[str, Dict[str, Dict[str, float]]] = {"arm2": {}, "arm1": {}}
        for arm_key in ("arm2", "arm1"):
            hover = resolve_dual_target_for_arm(plan, arm_key, approach_z, f"COARSE-HOVER-{arm_key.upper()}")
            grip = resolve_dual_target_for_arm(plan, arm_key, grip_z_map[arm_key], f"COARSE-GRIP-{arm_key.upper()}")
            lift = resolve_dual_target_for_arm(plan, arm_key, lift_z_map[arm_key], f"COARSE-LIFT-{arm_key.upper()}")
            if hover is None or grip is None or lift is None:
                return None
            out[arm_key] = {"hover": hover, "grip": grip, "lift": lift}
        return out

    def lower_both_to_coarse_grip_z_open():
        plan = latest_coarse_plan if latest_coarse_plan is not None else recompute_coarse_plan(print_result=True)
        if not validate_coarse_plan_for_hover(plan, label="COARSE-Z-DOWN"):
            return
        xyz = resolve_coarse_grip_xyz(plan)
        if xyz is None:
            return

        metrics = plan.get("metrics", {}) if isinstance(plan, dict) else {}
        mode = metrics.get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?")) if isinstance(plan, dict) else "?"
        src = plan.get("candidate", {}).get("class_name", "?") if isinstance(plan, dict) else "?"
        low_order = ["arm2", "arm1"] if args.coarse_grip_low_z_order == "arm2_first" else ["arm1", "arm2"]

        print("\n========== COARSE SPREAD Z-DOWN TEST (Z) ==========")
        print("This is only a z-down/contact-position test for ARM2-SPREAD / ARM1-SPREAD.")
        print("Sequence: open both -> hover -> descend to grip_z with grippers open.")
        print("No close, no lift, no stretch, no place.")
        print(f"mode={mode}, source={src}, low-z order={' -> '.join([x.upper() for x in low_order])}")
        print("Keep emergency power cutoff ready. Press G later to open grippers if needed.")
        print("=================================================\n")

        if not send_enabled:
            print("[DRY-RUN] Coarse z-down commands not sent.")
            return

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            if arm_obj is not None:
                arm_obj.torque_on()
                print(f"[COARSE-Z-DOWN] opening {arm_key.upper()} gripper before hover")
                arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
        time.sleep(0.25)

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["hover"]
            if arm_obj is not None:
                print(f"[COARSE-Z-DOWN] {arm_key.upper()} hover: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                time.sleep(0.15)
        time.sleep(args.grip_down_wait)

        for arm_key in low_order:
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["grip"]
            if arm_obj is None:
                print(f"[COARSE-Z-DOWN-BLOCKED] {arm_key.upper()} serial is not connected")
                return
            print(f"[COARSE-Z-DOWN] {arm_key.upper()} descend open to grip_z: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
            arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
            time.sleep(float(args.coarse_lower_wait))

        print("[COARSE-Z-DOWN] finished. Grippers are still open at grip_z. Use X for actual close/lift test, or G to open/recover.")

    def _coarse_plan_board_points(plan: Dict[str, Any]) -> Optional[Tuple[float, float, float, float]]:
        try:
            bx2, by2 = [float(v) for v in plan["targets"]["arm2"]["board_xy"]]
            bx1, by1 = [float(v) for v in plan["targets"]["arm1"]["board_xy"]]
            return bx2, by2, bx1, by1
        except Exception:
            return None

    # A91 must live in main() scope so AUTO SPREAD and human override SPREAD
    # share the exact same final minor-axis binding helper.
    def _apply_action2_minor_stretch_axis(plan: Optional[Dict[str, Any]], label: str = "ACTION2") -> None:
        """A91: bind the FINAL physical ACTION2 pull axis to the mask minor axis."""
        try:
            if not isinstance(plan, dict):
                return
            feat = plan.get("features") if isinstance(plan.get("features"), dict) else None
            if not isinstance(feat, dict):
                return
            board = feat.get("board") if isinstance(feat.get("board"), dict) else {}
            a = board.get("minor_min")
            b = board.get("minor_max")
            if a is None or b is None:
                return
            va = np.asarray(a, dtype=np.float32).reshape(2)
            vb = np.asarray(b, dtype=np.float32).reshape(2)
            u = vb - va
            n = float(np.linalg.norm(u))
            if n < 1e-6 or not np.all(np.isfinite(u)):
                return
            u = u / n
            pts = _coarse_plan_board_points(plan)
            if pts is not None:
                bx2, by2, bx1, by1 = pts
                pair_u = np.asarray([float(bx1 - bx2), float(by1 - by2)], dtype=np.float32)
                pn = float(np.linalg.norm(pair_u))
                if pn > 1e-6 and float(np.dot(u, pair_u / pn)) < 0.0:
                    u = -u
            if not isinstance(plan.get("spread_axis"), dict):
                plan["spread_axis"] = {}
            old_mode = str(plan.get("spread_axis", {}).get("axis_mode", plan.get("metrics", {}).get("axis_mode", "?")))
            plan["spread_axis"]["force_stretch_axis_board"] = [float(u[0]), float(u[1])]
            plan["spread_axis"]["force_stretch_axis_reason"] = "A91 final ACTION2 pull direction forced to segmentation-mask minor/shortest axis"
            if isinstance(plan.get("metrics"), dict):
                plan["metrics"]["a91_forced_minor_stretch_axis"] = True
                plan["metrics"]["a91_original_axis_mode"] = old_mode
            print(f"[A91-ACTION2-AXIS] {label}: FINAL pull direction forced to mask minor axis; original_plan_axis={old_mode}, u=({float(u[0]):+.3f},{float(u[1]):+.3f})")
        except Exception as e:
            print(f"[A91-ACTION2-AXIS-WARN] failed to force minor-axis stretch: {repr(e)}")


    def _vla_action2_step37_binding_signature(plan: Optional[Dict[str, Any]]) -> Optional[str]:
        """Stable geometry id for the exact frozen Step37+A91 SPREAD plan."""
        if not isinstance(plan, dict):
            return None
        try:
            pts = _coarse_plan_board_points(plan)
            if pts is None:
                return None
            forced = None
            if isinstance(plan.get("spread_axis"), dict):
                forced = plan.get("spread_axis", {}).get("force_stretch_axis_board")
            payload = {
                "arm2_board_xy": [round(float(pts[0]), 4), round(float(pts[1]), 4)],
                "arm1_board_xy": [round(float(pts[2]), 4), round(float(pts[3]), 4)],
                "forced_axis": None if forced is None else [round(float(forced[0]), 6), round(float(forced[1]), 6)],
                "axis_mode": str(plan.get("metrics", {}).get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?"))),
                "a109": bool(plan.get("metrics", {}).get("a109_step37_action2", False)),
                "a91": bool(plan.get("metrics", {}).get("a91_forced_minor_stretch_axis", False)),
            }
            raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
            return hashlib.sha1(raw).hexdigest()[:16]
        except Exception:
            return None

    def _vla_freeze_action2_step37_plan(base_plan: Optional[Dict[str, Any]], label: str) -> Tuple[Optional[Dict[str, Any]], str, Optional[str]]:
        """Build once from the X snapshot, apply A91 once, and tag immutable binding metadata."""
        if not isinstance(base_plan, dict):
            return None, "X exact SPREAD base plan unavailable", None
        plan, status = _a109_build_step37_action2_plan(cfg, latest_H, base_plan)
        if not isinstance(plan, dict):
            return None, str(status), None
        _apply_action2_minor_stretch_axis(plan, label)
        bind_id = _vla_action2_step37_binding_signature(plan)
        plan.setdefault("metrics", {})["vla_x_exact_spread_frozen"] = True
        plan.setdefault("metrics", {})["vla_x_exact_spread_binding_id"] = bind_id
        plan.setdefault("spread_axis", {})["vla_x_exact_spread_frozen"] = True
        plan["vla_x_exact_spread_binding_id"] = bind_id
        plan["vla_x_exact_spread_binding_source"] = "X_JUDGMENT_SAME_SNAPSHOT_STEP37_A91"
        return plan, str(status), bind_id

    def _coarse_spread_unit_vec_board(plan: Dict[str, Any]) -> Tuple[float, float]:
        pts = _coarse_plan_board_points(plan)
        if pts is None:
            return -1.0, 0.0
        bx2, by2, bx1, by1 = pts
        pair_vx = float(bx1 - bx2)
        pair_vy = float(by1 - by2)
        try:
            forced = None
            if isinstance(plan.get("spread_axis"), dict):
                forced = plan.get("spread_axis", {}).get("force_stretch_axis_board")
            if forced is None:
                forced = plan.get("force_stretch_axis_board")
            if forced is not None:
                fu = np.asarray(forced, dtype=np.float32).reshape(2)
                fn = float(np.linalg.norm(fu))
                if fn > 1e-6 and np.all(np.isfinite(fu)):
                    ux = float(fu[0] / fn)
                    uy = float(fu[1] / fn)
                    if (ux * pair_vx + uy * pair_vy) < 0.0:
                        ux, uy = -ux, -uy
                    return ux, uy
        except Exception:
            pass
        vx = pair_vx
        vy = pair_vy
        n = float((vx * vx + vy * vy) ** 0.5)
        if n < 1e-6:
            return 1.0, 0.0
        return vx / n, vy / n

    def _spread_safe_pull_mm(plan: Dict[str, Any], desired_mm: float, min_pull_mm: float,
                             label: str = "SPREAD") -> Tuple[Optional[float], str]:
        """Reduce only the requested spread distance until both outward endpoints are safe.

        This does not change the frozen grasp points, spread axis, low-Z ordering, or
        trajectory. It only applies the existing private-workspace, board-bound, affine,
        and RoArm XYZ constraints to the final outward endpoints before motion starts.
        """
        pts = _coarse_plan_board_points(plan)
        if pts is None:
            return None, "invalid frozen spread plan"
        bx2, by2, bx1, by1 = pts
        ux, uy = _coarse_spread_unit_vec_board(plan)
        desired = max(0.0, float(desired_mm))
        hard_min = max(0.0, min(float(min_pull_mm), desired))
        step = max(1.0, float(getattr(args, "auto_x_spread_safe_backoff_step_mm", 5.0)))
        lift_z = {"arm2": float(get_arm_lift_z("arm2")), "arm1": float(get_arm_lift_z("arm1"))}

        def _endpoint_ok(arm_key: str, bx: float, by: float) -> Tuple[bool, str]:
            expected = select_arm_for_board_x(cfg, float(bx))
            if expected != arm_key:
                return False, f"{arm_key} endpoint belongs to {expected}"
            if (not args.allow_outside_board) and (not is_board_safe(cfg, float(bx), float(by), args.board_margin)):
                return False, f"{arm_key} endpoint outside board"
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, float(bx), float(by))
            except Exception as exc:
                return False, f"{arm_key} affine failed: {exc}"
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(float(rx), float(ry), lift_z[arm_key], args)):
                return False, f"{arm_key} endpoint outside RoArm XYZ"
            return True, "OK"

        candidates = []
        d = desired
        while d + 1e-6 >= hard_min:
            candidates.append(float(d))
            d -= step
        if not candidates or abs(candidates[-1] - hard_min) > 1e-6:
            candidates.append(float(hard_min))

        last_reason = "no safe candidate"
        for dist in candidates:
            sx2, sy2 = bx2 - ux * dist, by2 - uy * dist
            sx1, sy1 = bx1 + ux * dist, by1 + uy * dist
            ok2, why2 = _endpoint_ok("arm2", sx2, sy2)
            ok1, why1 = _endpoint_ok("arm1", sx1, sy1)
            if ok2 and ok1:
                if abs(dist - desired) <= 1e-6:
                    return float(dist), f"{label}: requested {desired:.1f}mm is safe"
                return float(dist), f"{label}: safety backoff {desired:.1f}->{dist:.1f}mm"
            last_reason = f"{label}: {dist:.1f}mm blocked ({why2}; {why1})"
        return None, last_reason

    def _action5_dynamic_pull_mm(plan: Optional[Dict[str, Any]]) -> Tuple[float, str, Dict[str, Any]]:
        """Compute ACTION5 desired pull from the selected midpoint-normal mask span."""
        fallback = 25.0
        if not isinstance(plan, dict):
            return fallback, "ACTION5 dynamic fallback: plan missing", {"policy": "ORTHO_FALLBACK_25"}
        info = plan.get("action5", {}) if isinstance(plan.get("action5"), dict) else {}
        if not bool(getattr(args, "auto_x_action5_dynamic_pull_enable", True)):
            return fallback, "ACTION5 dynamic pull disabled; compatibility 25mm", {"policy": "ORTHO_FIXED_25_COMPAT"}
        span = float(info.get("orthogonal_mask_span_mm", info.get("proj_span_mm", 0.0)) or 0.0)
        pair = float(info.get("pair_distance_mm", plan.get("metrics", {}).get("pair_distance_mm", 0.0)) or 0.0)
        ratio = max(0.0, float(getattr(args, "auto_x_action5_dynamic_span_ratio", 0.14)))
        preferred_min = max(0.0, float(getattr(args, "auto_x_action5_dynamic_min_pull_mm", 30.0)))
        preferred_max = max(preferred_min, float(getattr(args, "auto_x_action5_dynamic_max_pull_mm", 60.0)))
        pair_fraction = max(0.0, float(getattr(args, "auto_x_action5_dynamic_pair_fraction", 0.25)))
        hard_min = max(0.0, float(getattr(args, "auto_x_action5_dynamic_hard_min_pull_mm", 15.0)))
        span_desired = float(np.clip(span * ratio, preferred_min, preferred_max)) if span > 0.0 else fallback
        pair_cap = pair * pair_fraction if pair > 0.0 else preferred_max
        requested = min(span_desired, preferred_max, pair_cap)
        requested = max(hard_min, requested)
        meta = {
            "policy": "ORTHO_DYNAMIC_SPAN_PAIR_WORKSPACE",
            "orthogonal_mask_span_mm": span,
            "pair_distance_mm": pair,
            "span_ratio": ratio,
            "span_desired_mm": span_desired,
            "pair_cap_mm": pair_cap,
            "preferred_min_mm": preferred_min,
            "preferred_max_mm": preferred_max,
            "hard_min_mm": hard_min,
            "requested_pull_mm": requested,
        }
        reason = (f"ORTHO dynamic: span={span:.1f}*{ratio:.2f}->{span_desired:.1f}mm, "
                  f"pair_cap={pair_cap:.1f}mm -> request={requested:.1f}mm")
        return float(requested), reason, meta

    def resolve_coarse_stretch_xyz(plan: Dict[str, Any], base_xyz: Dict[str, Dict[str, Dict[str, float]]]) -> Optional[Dict[str, Dict[str, float]]]:
        """Compute stretch/place/retract targets after coarse grip/lift.

        The default stretch direction follows the selected SPREAD candidate line:
        ARM2 moves away from ARM1, and ARM1 moves away from ARM2.
        For minor/minor_relaxed this follows the minor-axis-derived candidate pair,
        not a blind board-x-only stretch.
        """
        pts = _coarse_plan_board_points(plan)
        if pts is None:
            print("[COARSE-STRETCH-BLOCKED] invalid coarse plan board points")
            return None
        bx2, by2, bx1, by1 = pts
        dist = max(0.0, float(get_effective_coarse_stretch_distance()))
        if dist <= 0.0:
            print(f"[COARSE-STRETCH-BLOCKED] effective coarse_stretch_distance must be positive. current={dist:.1f}mm")
            return None

        ux, uy = _coarse_spread_unit_vec_board(plan)

        def _try_resolve(label: str, use_board_x_only: bool = False):
            if use_board_x_only:
                sx2, sy2 = bx2 - dist, by2
                sx1, sy1 = bx1 + dist, by1
                desc = "board-x fallback"
            else:
                sx2, sy2 = bx2 - ux * dist, by2 - uy * dist
                sx1, sy1 = bx1 + ux * dist, by1 + uy * dist
                desc = "selected-axis"

            lift_z2 = float(base_xyz["arm2"]["lift"]["rz"])
            lift_z1 = float(base_xyz["arm1"]["lift"]["rz"])
            place_z2 = float(args.place_z if args.place_z is not None else base_xyz["arm2"]["grip"]["rz"])
            place_z1 = float(args.place_z if args.place_z is not None else base_xyz["arm1"]["grip"]["rz"])
            release_retract_z = float(args.coarse_release_retract_z if args.coarse_release_retract_z is not None else approach_z)

            print(f"[COARSE-STRETCH] trying {desc}: dist={dist:.1f}mm each side, "
                  f"ARM2 board=({sx2:.1f},{sy2:.1f}), ARM1 board=({sx1:.1f},{sy1:.1f})")
            out = {
                "arm2": {
                    "stretch_lift": resolve_board_target_for_arm("arm2", sx2, sy2, lift_z2, f"COARSE-STRETCH-LIFT-ARM2-{label}"),
                    "stretch_place": resolve_board_target_for_arm("arm2", sx2, sy2, place_z2, f"COARSE-STRETCH-PLACE-ARM2-{label}"),
                    "stretch_retract": resolve_board_target_for_arm("arm2", sx2, sy2, lift_z2, f"COARSE-STRETCH-RETRACT-ARM2-{label}"),
                    "stretch_release_retract": resolve_board_target_for_arm("arm2", sx2, sy2, release_retract_z, f"COARSE-STRETCH-VERTICAL-RETRACT-ARM2-{label}"),
                },
                "arm1": {
                    "stretch_lift": resolve_board_target_for_arm("arm1", sx1, sy1, lift_z1, f"COARSE-STRETCH-LIFT-ARM1-{label}"),
                    "stretch_place": resolve_board_target_for_arm("arm1", sx1, sy1, place_z1, f"COARSE-STRETCH-PLACE-ARM1-{label}"),
                    "stretch_retract": resolve_board_target_for_arm("arm1", sx1, sy1, lift_z1, f"COARSE-STRETCH-RETRACT-ARM1-{label}"),
                    "stretch_release_retract": resolve_board_target_for_arm("arm1", sx1, sy1, release_retract_z, f"COARSE-STRETCH-VERTICAL-RETRACT-ARM1-{label}"),
                },
                "meta": {"mode": desc, "distance": dist, "ux": ux, "uy": uy},
            }
            for arm_key in ("arm2", "arm1"):
                for name, tgt in out[arm_key].items():
                    if tgt is None:
                        return None
            return out

        axis_out = _try_resolve("AXIS", use_board_x_only=False)
        if axis_out is not None:
            return axis_out
        # ACTION5 ORTHO must never silently change into a board-x spread.
        # If the exact selected orthogonal ray cannot be resolved safely at all
        # required Z levels, fail closed and request a fresh judgment instead.
        is_action5_ortho = bool(isinstance(plan.get("action5"), dict))
        if is_action5_ortho:
            print("[ACTION5-ORTHO-BLOCKED] selected midpoint-normal ray stretch target is unsafe; board-x fallback is forbidden for ORTHO.")
            return None
        if args.coarse_stretch_fallback_board_x:
            print("[COARSE-STRETCH] selected-axis target blocked; retrying simple board-x stretch.")
            return _try_resolve("BOARDX", use_board_x_only=True)
        print("[COARSE-STRETCH-BLOCKED] selected-axis stretch target blocked and board-x fallback is disabled.")
        return None


    def coarse_grip_and_small_lift():
        nonlocal latest_spread_eval, spread_eval_history, coarse_x_since_last_press
        if bool(args.coarse_action_use_displayed_plan_first) and latest_coarse_plan is not None:
            plan = latest_coarse_plan
            m0 = plan.get("metrics", {}) if isinstance(plan, dict) else {}
            mode0 = m0.get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?")) if isinstance(plan, dict) else "?"
            try:
                p2 = plan["targets"]["arm2"]["board_xy"]
                p1 = plan["targets"]["arm1"]["board_xy"]
                print(f"[COARSE-X] using displayed latest plan without re-infer: mode={mode0} ARM2=({p2[0]:.1f},{p2[1]:.1f}), ARM1=({p1[0]:.1f},{p1[1]:.1f})")
            except Exception:
                print(f"[COARSE-X] using displayed latest plan without re-infer: mode={mode0}")
        elif bool(args.coarse_action_fresh_snapshot) and snapshot_mode:
            plan = request_fresh_coarse_plan_and_wait(
                reason="before coarse grip/stretch",
                timeout=float(args.coarse_action_fresh_timeout),
            )
        else:
            plan = latest_coarse_plan if latest_coarse_plan is not None else recompute_coarse_plan(print_result=True)
        if not validate_coarse_plan_for_hover(plan, label="COARSE-GRIP-STRETCH"):
            return False
        xyz = resolve_coarse_grip_xyz(plan)
        if xyz is None:
            return False
        stretch_xyz = None
        if args.coarse_stretch_after_lift:
            stretch_xyz = resolve_coarse_stretch_xyz(plan, xyz)
            if stretch_xyz is None:
                print("[COARSE-GRIP-STRETCH-BLOCKED] stretch target could not be resolved safely. Stop before gripping.")
                return False

        before_eval_metrics = _coarse_eval_metrics_from_plan(plan)
        metrics = plan.get("metrics", {}) if isinstance(plan, dict) else {}
        mode = metrics.get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?")) if isinstance(plan, dict) else "?"
        src = plan.get("candidate", {}).get("class_name", "?") if isinstance(plan, dict) else "?"
        low_order = ["arm2", "arm1"] if args.coarse_grip_low_z_order == "arm2_first" else ["arm1", "arm2"]
        a2 = plan["targets"]["arm2"]["board_xy"]
        a1 = plan["targets"]["arm1"]["board_xy"]

        print("\n========== COARSE GRIP + STRETCH + EVAL TEST (X) ==========")
        print("This uses ARM2-SPREAD / ARM1-SPREAD from a fresh/current coarse plan when enabled.")
        if bool(args.coarse_parallel_x):
            print("Sequence: fresh/displayed plan -> parallel open -> parallel hover -> parallel descend -> parallel close -> parallel lift -> parallel stretch -> air release -> vertical z-retract -> standby/eval.")
        else:
            print("Sequence: fresh/displayed plan -> open -> hover -> sequential descend/close -> lift -> stretch at lift_z -> air/low-height open -> vertical z-retract -> standby/eval.")
        print(f"reuse_displayed_plan_first={bool(args.coarse_action_use_displayed_plan_first)}, fresh_snapshot_fallback={bool(args.coarse_action_fresh_snapshot)}, parallel_x={bool(args.coarse_parallel_x)}, stretch_after_lift={bool(args.coarse_stretch_after_lift)}, air_release={bool(args.coarse_release_at_stretch_lift)}, vertical_retract={bool(args.coarse_release_vertical_retract_before_standby)}, place_after_stretch={bool(args.coarse_stretch_place_after)}")
        print(f"mode={mode}, source={src}, low-z order={' -> '.join([x.upper() for x in low_order])}")
        print(f"ARM2-SPREAD board=({a2[0]:.1f},{a2[1]:.1f})")
        print(f"ARM1-SPREAD board=({a1[0]:.1f},{a1[1]:.1f})")
        print(f"grip_open={args.grip_open:.3f}, grip_close={args.grip_close:.3f}, grip_hold={args.grip_hold:.3f}, stretch_distance={get_effective_coarse_stretch_distance():.1f}mm")
        if bool(args.coarse_parallel_x):
            print(f"parallel moderate waits: descend={float(args.coarse_parallel_descend_wait):.2f}s, contact={float(args.coarse_parallel_contact_wait):.2f}s, close_repeat={int(args.coarse_parallel_close_repeat)}, close_wait={float(args.coarse_parallel_close_wait):.2f}s, close_settle={float(args.coarse_parallel_close_settle):.2f}s, lift_wait={float(args.coarse_parallel_lift_wait):.2f}s")
        print("Keep emergency power cutoff ready. This will close the grippers and move the cloth.")
        print("===================================================\n")

        def _finish_after_coarse_motion(after_reason: str, action_meta: Dict[str, Any]):
            nonlocal latest_spread_eval, spread_eval_history, coarse_x_since_last_press
            if args.coarse_eval_after_action:
                if args.imaging_standby and not args.no_standby:
                    move_arms_to_standby(reason="before spread evaluation snapshot")
                time.sleep(max(0.0, float(args.coarse_eval_after_settle)))
                after_plan = request_fresh_coarse_plan_and_wait(
                    reason=after_reason,
                    timeout=float(args.coarse_action_fresh_timeout),
                )
                after_eval_metrics = _coarse_eval_metrics_from_plan(after_plan)
                ev = evaluate_spread_result(before_eval_metrics, after_eval_metrics, action_meta=action_meta)
                latest_spread_eval = ev
                spread_eval_history.append(ev)
                if len(spread_eval_history) > 12:
                    del spread_eval_history[:-12]
                print_spread_eval(ev)
                update_adaptive_next_from_eval(ev)
            elif args.auto_reinfer_after_motion:
                reset_snapshot("coarse grip/stretch finished; waiting for fresh still frame")

        if not send_enabled:
            print("[DRY-RUN] Coarse grip commands not sent.")
            return False

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            if arm_obj is None:
                print(f"[COARSE-GRIP-BLOCKED] {arm_key.upper()} serial is not connected")
                return False
            _a140_note_action_command(f"coarse grip/stretch {arm_key} torque-on")
            arm_obj.torque_on()

        if bool(args.coarse_parallel_x):
            print("[COARSE-PARALLEL-X] enabled: hover, descend, close, and lift will run in parallel.")
            parallel_gripper(args.grip_open, "COARSE-PARALLEL-OPEN-BEFORE-HOVER", wait_after=max(0.0, float(args.coarse_parallel_pre_open_wait)))

            parallel_move_targets({
                "arm2": xyz["arm2"]["hover"],
                "arm1": xyz["arm1"]["hover"],
            }, "COARSE-PARALLEL-HOVER", args.grip_open, wait_after=max(0.0, float(args.coarse_parallel_hover_wait)))

            parallel_move_targets({
                "arm2": xyz["arm2"]["grip"],
                "arm1": xyz["arm1"]["grip"],
            }, "COARSE-PARALLEL-DESCEND", args.grip_open, wait_after=max(0.0, float(args.coarse_parallel_descend_wait)))

            print(f"[COARSE-PARALLEL-X] open at both grip points, wait {float(args.coarse_parallel_open_at_grip_wait):.2f}s")
            parallel_gripper(args.grip_open, "COARSE-PARALLEL-OPEN-AT-GRIP", wait_after=max(0.0, float(args.coarse_parallel_open_at_grip_wait)))
            time.sleep(max(0.0, float(args.coarse_parallel_contact_wait)))

            close_repeat = max(1, int(args.coarse_parallel_close_repeat))
            for i in range(close_repeat):
                print(f"[COARSE-PARALLEL-X] LIMITED CLOSE both arms {i+1}/{close_repeat}: angle={args.grip_close:.3f}")
                parallel_gripper(args.grip_close, f"COARSE-PARALLEL-CLOSE-{i+1}", wait_after=max(0.0, float(args.coarse_parallel_close_wait)))

            if abs(float(args.grip_hold) - float(args.grip_close)) > 1e-6:
                print(f"[COARSE-PARALLEL-X] hold both arms angle={args.grip_hold:.3f}")
                parallel_gripper(args.grip_hold, "COARSE-PARALLEL-HOLD", wait_after=max(0.0, float(args.coarse_parallel_hold_wait)))

            print(f"[COARSE-PARALLEL-X] fast close-settle wait {float(args.coarse_parallel_close_settle):.2f}s")
            time.sleep(max(0.0, float(args.coarse_parallel_close_settle)))
        else:
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                if arm_obj is not None:
                    print(f"[COARSE-GRIP] opening {arm_key.upper()} before hover")
                    arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(0.30)

            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz[arm_key]["hover"]
                if arm_obj is not None:
                    print(f"[COARSE-GRIP] {arm_key.upper()} hover: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                    arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                    time.sleep(0.15)
            time.sleep(args.grip_down_wait)

            # Low-Z descent and close is sequential for safety.
            for arm_key in low_order:
                arm_obj = arms.get(arm_key)
                tgt = xyz[arm_key]["grip"]
                if arm_obj is None:
                    print(f"[COARSE-GRIP-BLOCKED] {arm_key.upper()} serial is not connected")
                    return False
                print(f"[COARSE-GRIP] {arm_key.upper()} descend to grip_z: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                time.sleep(args.grip_down_wait)

                print(f"[COARSE-GRIP] {arm_key.upper()} open at grip point, wait {args.grip_open_wait:.2f}s")
                arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
                time.sleep(args.grip_open_wait)
                time.sleep(args.grip_contact_wait)

                close_repeat = max(1, int(args.grip_close_repeat))
                for i in range(close_repeat):
                    print(f"[COARSE-GRIP] {arm_key.upper()} LIMITED CLOSE {i+1}/{close_repeat}: angle={args.grip_close:.3f}")
                    arm_obj.gripper_close(args.grip_close, spd=args.grip_spd, acc=args.grip_acc)
                    time.sleep(args.grip_close_wait)
                if abs(float(args.grip_hold) - float(args.grip_close)) > 1e-6:
                    print(f"[COARSE-GRIP] {arm_key.upper()} hold angle={args.grip_hold:.3f}")
                    arm_obj.set_gripper(args.grip_hold, spd=args.grip_spd, acc=args.grip_acc, delay=0.30)
                print(f"[COARSE-GRIP] {arm_key.upper()} close-settle wait {args.grip_close_settle:.2f}s")
                time.sleep(args.grip_close_settle)

        if args.coarse_grip_lift_after_close:
            if bool(args.coarse_parallel_x):
                parallel_move_targets({
                    "arm2": xyz["arm2"]["lift"],
                    "arm1": xyz["arm1"]["lift"],
                }, "COARSE-PARALLEL-LIFT", args.grip_hold, wait_after=max(0.0, float(args.coarse_parallel_lift_wait)))
            else:
                for arm_key in ("arm2", "arm1"):
                    arm_obj = arms.get(arm_key)
                    tgt = xyz[arm_key]["lift"]
                    if arm_obj is not None:
                        print(f"[COARSE-LIFT] {arm_key.upper()} small lift while holding: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                        arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_hold, spd=spd_default)
                        time.sleep(0.15)
                time.sleep(args.place_settle_wait)

            if args.coarse_stretch_after_lift and stretch_xyz is not None:
                meta = stretch_xyz.get("meta", {})
                print(f"[COARSE-STRETCH] moving outward at lift_z: mode={meta.get('mode','?')} dist={meta.get('distance',0):.1f}mm")
                parallel_move_targets({
                    "arm2": stretch_xyz["arm2"]["stretch_lift"],
                    "arm1": stretch_xyz["arm1"]["stretch_lift"],
                }, "COARSE-STRETCH-LIFT", args.grip_hold, wait_after=float(args.coarse_stretch_wait))

                action_meta = {
                    "mode": mode,
                    "source": src,
                    "stretch_distance": float(get_effective_coarse_stretch_distance()),
                    "stretch_target_mode": meta.get("mode", "?"),
                    "ux": float(meta.get("ux", 1.0)),
                    "uy": float(meta.get("uy", 0.0)),
                }

                if bool(args.coarse_release_at_stretch_lift):
                    print("[COARSE-AIR-RELEASE] opening grippers at stretched lift pose, not on the board. This avoids board/friction wrinkles.")
                    parallel_gripper(args.grip_open, "COARSE-AIR-RELEASE-OPEN", wait_after=float(args.coarse_release_open_wait))
                    if bool(args.coarse_release_vertical_retract_before_standby):
                        print("[COARSE-AIR-RELEASE] vertical same-XY retract before any standby XY motion")
                        parallel_move_targets({
                            "arm2": stretch_xyz["arm2"]["stretch_release_retract"],
                            "arm1": stretch_xyz["arm1"]["stretch_release_retract"],
                        }, "COARSE-AIR-RELEASE-Z-RETRACT", safe_gripper, wait_after=float(args.place_settle_wait))
                    _finish_after_coarse_motion("after coarse air-release stretch for spread evaluation", action_meta)
                elif args.coarse_stretch_place_after:
                    print("[COARSE-STRETCH-PLACE] placing down at stretched XY, then opening grippers")
                    parallel_move_targets({
                        "arm2": stretch_xyz["arm2"]["stretch_place"],
                        "arm1": stretch_xyz["arm1"]["stretch_place"],
                    }, "COARSE-STRETCH-PLACE", args.grip_hold, wait_after=float(args.place_settle_wait))
                    if bool(getattr(args, "auto_x_action2_floor_slow_release_active", False)):
                        steps = max(1, int(getattr(args, "auto_x_action2_slow_open_steps", 5)))
                        step_wait = max(0.0, float(getattr(args, "auto_x_action2_slow_open_step_wait", 0.22)))
                        start_angle = float(args.grip_hold)
                        end_angle = float(args.grip_open)
                        print(f"[COARSE-STRETCH-FLOOR-SLOW-OPEN] ACTION2 floor release: {steps} incremental gripper steps from {start_angle:.3f} to {end_angle:.3f}, wait={step_wait:.2f}s")
                        for oi in range(1, steps + 1):
                            a = start_angle + (end_angle - start_angle) * (float(oi) / float(steps))
                            parallel_gripper(a, f"COARSE-STRETCH-SLOW-OPEN-{oi}", wait_after=step_wait)
                    else:
                        parallel_gripper(args.grip_open, "COARSE-STRETCH-OPEN", wait_after=float(args.place_open_wait))
                    if args.coarse_stretch_retract_after_place:
                        parallel_move_targets({
                            "arm2": stretch_xyz["arm2"]["stretch_retract"],
                            "arm1": stretch_xyz["arm1"]["stretch_retract"],
                        }, "COARSE-STRETCH-RETRACT", safe_gripper, wait_after=float(args.place_settle_wait))
                    _finish_after_coarse_motion("after coarse grip/stretch/place for spread evaluation", action_meta)
                else:
                    print("[COARSE-STRETCH] finished. Both grippers keep holding at stretched lift pose. No release/place/retract.")
            elif not args.coarse_grip_keep_holding_after_lift:
                print("[COARSE-GRIP] opening both grippers at lift_z because --no-coarse-grip-keep-holding-after-lift was set")
                parallel_gripper(args.grip_open, "COARSE-GRIP-OPEN-AFTER-LIFT", wait_after=float(args.place_open_wait))
            else:
                print("[COARSE-GRIP] finished. Both grippers keep holding at lift_z. Stretch/place disabled.")
        else:
            print("[COARSE-GRIP] finished at grip_z after close. No lift/stretch/place yet.")
        return True


    def _execute_no_action_stuck_soft_probe(plan: Optional[Dict[str, Any]], reason: str = "") -> bool:
        """A93: soft-pad two-arm probe for repeated NO_ACTION_CANDIDATE.

        This intentionally does NOT pinch/lift the cloth.  Both grippers are closed
        to the padded press angle before contact, then lowered onto the cloth and
        swept outward by a short distance while staying at the same light press Z.
        """
        if not isinstance(plan, dict):
            print("[A93-NO-ACTION-PROBE-BLOCKED] no saved probe plan")
            return False
        if not validate_coarse_plan_for_hover(plan, label="A93-NO-ACTION-PROBE"):
            return False
        pts = _coarse_plan_board_points(plan)
        if pts is None:
            print("[A93-NO-ACTION-PROBE-BLOCKED] invalid plan board points")
            return False
        bx2, by2, bx1, by1 = pts
        ux, uy = _coarse_spread_unit_vec_board(plan)
        pull = float(max(1.0, getattr(args, "auto_x_no_action_probe_pull_mm", 15.0)))
        z_offset = float(getattr(args, "auto_x_no_action_probe_press_z_offset_mm", 3.0))
        spd = float(getattr(args, "auto_x_no_action_probe_speed", 0.20))
        if (not np.isfinite(spd)) or spd <= 0:
            spd = 0.20
        press_grip = float(getattr(args, "press_gripper", getattr(args, "grip_close", 2.95)))
        clear_z = float(_effective_press_clear_z())

        z_map: Dict[str, float] = {}
        for ak in ("arm2", "arm1"):
            gz = get_arm_grip_z(ak)
            if gz is None:
                print(f"[A93-NO-ACTION-PROBE-BLOCKED] {ak.upper()} grip_z not calibrated")
                return False
            z_map[ak] = float(gz) + z_offset

        end2 = (float(bx2) - ux * pull, float(by2) - uy * pull)
        end1 = (float(bx1) + ux * pull, float(by1) + uy * pull)
        xyz = {
            "arm2": {
                "hover": resolve_board_target_for_arm("arm2", bx2, by2, clear_z, "A93-NOACTION-HOVER-ARM2"),
                "down": resolve_board_target_for_arm("arm2", bx2, by2, z_map["arm2"], "A93-NOACTION-DOWN-ARM2"),
                "sweep": resolve_board_target_for_arm("arm2", end2[0], end2[1], z_map["arm2"], "A93-NOACTION-SWEEP-ARM2"),
                "clear": resolve_board_target_for_arm("arm2", end2[0], end2[1], clear_z, "A93-NOACTION-CLEAR-ARM2"),
            },
            "arm1": {
                "hover": resolve_board_target_for_arm("arm1", bx1, by1, clear_z, "A93-NOACTION-HOVER-ARM1"),
                "down": resolve_board_target_for_arm("arm1", bx1, by1, z_map["arm1"], "A93-NOACTION-DOWN-ARM1"),
                "sweep": resolve_board_target_for_arm("arm1", end1[0], end1[1], z_map["arm1"], "A93-NOACTION-SWEEP-ARM1"),
                "clear": resolve_board_target_for_arm("arm1", end1[0], end1[1], clear_z, "A93-NOACTION-CLEAR-ARM1"),
            },
        }
        for ak in ("arm2", "arm1"):
            for name, tgt in xyz[ak].items():
                if tgt is None:
                    print(f"[A93-NO-ACTION-PROBE-BLOCKED] {ak.upper()} {name} target invalid")
                    return False
        print("\n========== ACTION NO-ACTION STUCK SOFT PROBE EXECUTE (A93) ==========")
        print(f"reason={reason}")
        print("Motion: padded grippers closed before contact -> light down on cloth -> 15mm outward sweep -> clear/open. No pinch, no lift.")
        print(f"ARM2 start=({bx2:.1f},{by2:.1f}) -> end=({end2[0]:.1f},{end2[1]:.1f})")
        print(f"ARM1 start=({bx1:.1f},{by1:.1f}) -> end=({end1[0]:.1f},{end1[1]:.1f})")
        print(f"axis=({ux:+.3f},{uy:+.3f}) pull={pull:.1f}mm press_z_offset=+{z_offset:.1f}mm speed={spd:.2f} gripper={press_grip:.3f}")
        print("====================================================================\n")
        if not send_enabled:
            print("[DRY-RUN] A93 no-action soft probe commands not sent.")
            return False
        for ak in ("arm2", "arm1"):
            arm_obj = arms.get(ak)
            if arm_obj is None:
                print(f"[A93-NO-ACTION-PROBE-BLOCKED] {ak.upper()} serial is not connected")
                return False
        _a140_note_action_command("A93 no-action soft-probe torque-on")
        for ak in ("arm2", "arm1"):
            arm_obj = arms.get(ak)
            arm_obj.torque_on()

        def _abort_no_action_parallel(stage: str) -> bool:
            if not auto_x_action_parallel_errors:
                return False
            released = bool(parallel_gripper(
                float(args.grip_open), f"A93-NOACTION-ABORT-OPEN-{stage}", wait_after=0.10,
            ))
            if released:
                _a140_note_release(f"A93 no-action abort open after {stage}")
            print(
                f"[A140-NOACTION-PARTIAL-STOP] stage={stage} errors={auto_x_action_parallel_errors}; "
                "release attempted, horizontal standby suppressed"
            )
            return True

        parallel_gripper(press_grip, "A93-NOACTION-PADDED-CLOSE-BEFORE-CONTACT", wait_after=0.10)
        if _abort_no_action_parallel("PADDED-CLOSE"):
            return False
        parallel_move_targets({"arm2": xyz["arm2"]["hover"], "arm1": xyz["arm1"]["hover"]},
                              "A93-NOACTION-HOVER", press_grip,
                              wait_after=max(0.05, float(getattr(args, "targeted_press_wait_before_down", 0.12))), speed=spd)
        if _abort_no_action_parallel("HOVER"):
            return False
        parallel_move_targets({"arm2": xyz["arm2"]["down"], "arm1": xyz["arm1"]["down"]},
                              "A93-NOACTION-LIGHT-DOWN", press_grip,
                              wait_after=max(0.10, float(getattr(args, "targeted_press_wait_after_down", 0.20))), speed=spd)
        if _abort_no_action_parallel("DOWN"):
            return False
        parallel_move_targets({"arm2": xyz["arm2"]["sweep"], "arm1": xyz["arm1"]["sweep"]},
                              "A93-NOACTION-SOFT-SWEEP", press_grip,
                              wait_after=max(0.10, float(getattr(args, "targeted_press_wait_after_sweep", 0.25))), speed=spd)
        if _abort_no_action_parallel("SWEEP"):
            return False
        clear_errors_before = len(auto_x_action_parallel_errors)
        parallel_move_targets({"arm2": xyz["arm2"]["clear"], "arm1": xyz["arm1"]["clear"]},
                              "A93-NOACTION-CLEAR", press_grip,
                              wait_after=max(0.10, float(getattr(args, "targeted_press_wait_after_clear", 0.20))), speed=spd)
        clear_ok = len(auto_x_action_parallel_errors) == clear_errors_before
        if clear_ok:
            _a140_note_vertical_clear("A93 no-action stuck soft probe")
        if _abort_no_action_parallel("CLEAR"):
            return False
        parallel_gripper(float(args.grip_open), "A93-NOACTION-OPEN-AFTER-CLEAR", wait_after=0.10)
        if not auto_x_action_parallel_errors:
            _a140_note_release("A93-NOACTION-OPEN-AFTER-CLEAR")
        if (not auto_x_action_parallel_errors
                and bool(getattr(args, "imaging_standby", True))
                and not bool(getattr(args, "no_standby", False))):
            move_arms_to_standby(reason="after A93 no-action stuck soft probe")
        if auto_x_action_parallel_errors:
            print("[A140-NOACTION-PARTIAL-STOP] release error; horizontal standby suppressed")
            return False
        if bool(getattr(args, "auto_reinfer_after_motion", True)):
            reset_snapshot("A93 no-action stuck soft probe finished; waiting for fresh still frame")
        return True

    def x_wrinkle_spread_then_auto_align_rotate(expected_cycle_epoch: Optional[int] = None):
        """A72 manual X decision entry.

        X only rejudges the current garment state and selects one pending action.
        It does not execute the selected action until ENTER/SPACE is pressed.
        """
        if bool(getattr(args, "auto_align_rotate_after_wrinkle", True)):
            auto_align_rotate_after_wrinkle_pipeline(
                trigger="key X manual judge",
                expected_cycle_epoch=expected_cycle_epoch,
            )
        else:
            fail_epoch = int(
                auto_x_controller.current_epoch()
                if expected_cycle_epoch is None else expected_cycle_epoch
            )

            def _publish_planner_disabled() -> None:
                nonlocal pending_auto_x_action, auto_x_manual_judge_active
                pending_auto_x_action = None
                auto_x_manual_judge_active = True
                _a140_set_outer_overlay("AUTO-X ERROR - PRESS X", "planner disabled; no physical motion", hold_s=120.0)

            if auto_x_controller.fail_if_current(
                    fail_epoch, "AUTO-X planner disabled; X cannot authorize physical motion",
                    fatal=False, publisher=_publish_planner_disabled):
                print("[A140-X-NO-PHYSICAL-FALLBACK] AUTO-X planner is disabled; X performed no robot motion.")

    def _execute_pending_auto_x_action_impl() -> bool:
        """Execute the action selected by the latest A72 X manual judgment."""
        nonlocal pending_auto_x_action, auto_x_manual_judge_active, latest_coarse_plan, latest_targeted_press_plan, latest_pose_rotation_plan, coarse_action_stretch_distance_override
        nonlocal auto_x_action2_plateau_short_pull_active, auto_x_action2_plateau_last_reason, auto_x_action2_plateau_count
        nonlocal last_auto_x_executed_action, last_auto_x_executed_at
        nonlocal latest_auto_x_post_action_title, latest_auto_x_post_action_detail_1, latest_auto_x_post_action_detail_2
        if not isinstance(pending_auto_x_action, dict):
            print("[AUTO-X-PENDING] no executable action is pending. Press X to judge/rejudge/select an action. Normal Enter-pick is suppressed while AUTO-X manual mode is active.")
            return False
        pending = dict(pending_auto_x_action)
        pending_auto_x_action = None
        execution_epoch = int(pending.get("a140_cycle_epoch", -1))
        action = str(pending.get("action", ""))
        reason = str(pending.get("reason", ""))
        auto_x_action_parallel_errors.clear()
        _a140_latency_mark("physical_action_start", executing_action=str(action))
        auto_x_debug_logger.mark_action(action, reason)
        print("\n========== AUTO-X A72 EXECUTE PENDING ==========")
        print(f"action={action}")
        print(f"reason={reason}")
        print("A143 policy: Enter executes only the frozen pending action; after standby, automatic stillness-gated judgment resumes.")
        print("===============================================\n")
        ok = False
        # a contact-arrival failure can now recover cleanly to standby without
        # executing a sweep.  That is a successful safety envelope/rejudge outcome,
        # but it must not increment garment-motion, spread-progress, or Late counters.
        completed_without_garment_motion = False
        late_plan = pending.get("late_plan") if isinstance(pending.get("late_plan"), dict) else None
        if action in {"ROTATE_PULL", "ROTATE_SHEAR"}:
            if send_enabled and (arms.get("arm1") is None or arms.get("arm2") is None):
                auto_x_manual_judge_active = True
                print(f"[A152-ROTATE-PREFLIGHT-BLOCK] action={action}; both ARM1 and ARM2 serial connections are required; Robot motion: NONE")
                return False
            if not bool(getattr(args, "pose_rotate_place_after", True)):
                auto_x_manual_judge_active = True
                print(f"[A152-ROTATE-PREFLIGHT-BLOCK] action={action}; --no-pose-rotate-place-after is incompatible with AUTO-X safety; Robot motion: NONE")
                return False
            if not bool(getattr(args, "pose_rotate_vertical_retract_after_open", True)):
                auto_x_manual_judge_active = True
                print(f"[A152-ROTATE-PREFLIGHT-BLOCK] action={action}; vertical retract after release is required; Robot motion: NONE")
                return False
            frozen_pose = pending.get("pose_rotation_plan") if isinstance(pending.get("pose_rotation_plan"), dict) else None
            if not isinstance(frozen_pose, dict):
                auto_x_manual_judge_active = True
                print(f"[A152-ROTATE-PENDING-BLOCK] action={action}; exact frozen pose plan missing; Robot motion: NONE")
                return False
            if not bool(frozen_pose.get("ready", False)) or bool(frozen_pose.get("done", False)):
                auto_x_manual_judge_active = True
                print(f"[A152-ROTATE-PENDING-BLOCK] action={action}; frozen plan no longer executable by metadata: {frozen_pose.get('status')}")
                return False
            saved_pose_plan = latest_pose_rotation_plan
            saved_hover_only = bool(getattr(args, "pose_rotate_hover_only", True))
            try:
                latest_pose_rotation_plan = copy.deepcopy(frozen_pose)
                setattr(args, "pose_rotate_hover_only", False)
                print(
                    f"[A152-LINEAR-ROTATE-EXEC] exact={action} "
                    f"phase={str(pending.get('rotation_phase') or 'MID')} frozen_plan=True "
                    f"angle_error={float(frozen_pose.get('delta_full_deg',0.0)):+.1f}deg "
                    f"planned_effect={float(frozen_pose.get('planned_rotation_effect_deg', abs(float(frozen_pose.get('action_delta_deg',0.0))))):.1f}deg "
                    f"pull={float(frozen_pose.get('linear_pull_mm_effective',0.0)):.1f}mm"
                )
                ok = bool(pose_rotation_correct_once(reset_after_motion=False))
            finally:
                setattr(args, "pose_rotate_hover_only", saved_hover_only)
                latest_pose_rotation_plan = saved_pose_plan
        elif action == "CENTER_CIRCUMCENTER_LATE":
            vp = late_plan.get("variable_plan") if isinstance(late_plan, dict) else None
            ok = bool(_a133_execute_variable_overflow_plan_exact(vp, label="A136 CENTER_CIRCUMCENTER_LATE / original ACTION1 geometry"))
        elif str(action).startswith("LATE_") and isinstance(late_plan, dict) and str(late_plan.get("kind")) == "targeted":
            saved_tp = pending.get("targeted_plan")
            if isinstance(saved_tp, dict):
                latest_targeted_press_plan = copy.deepcopy(saved_tp)
            resolved = late_plan.get("resolved_motion")
            if not isinstance(resolved, dict):
                auto_x_manual_judge_active = True
                print("[A140-EXACT-PENDING-BLOCK] LATE targeted resolved motion is missing; Robot motion: NONE.")
                return False
