    def _a140_start_pending_from_physical_approval(source: str) -> bool:
        """Submission physical gate: same Stage3 binding checker, then automatic approval/dispatch."""
        nonlocal pending_auto_x_action, auto_x_manual_judge_active
        if not isinstance(pending_auto_x_action, dict):
            return False

        def _execution_binding_error(pending: Dict[str, Any]) -> Optional[str]:
            action_now = str(pending.get("action", "UNKNOWN"))
            macro_now = _vla_macro_action(action_now)
            unavailable = pending.get("vla_selected_macro_unavailable")
            if unavailable:
                return f"selected macro {unavailable} has no safe frozen plan"

            bound_action = pending.get("vla_bound_execution_action")
            if bound_action not in (None, "") and str(bound_action) != action_now:
                return f"bound exact action={bound_action} but pending dispatcher={action_now}"
            bound_macro = pending.get("vla_bound_execution_macro")
            if bound_macro not in (None, "") and str(bound_macro) != str(macro_now):
                return f"bound macro={bound_macro} but pending macro={macro_now}"

            human_macro = pending.get("vla_human_macro_action")
            if human_macro not in (None, "") and str(human_macro).upper() not in {"FINISH", "REJUDGE"}:
                if str(human_macro).upper() != str(macro_now).upper():
                    return f"human-selected macro={human_macro} but pending macro={macro_now}"

            # Exact frozen-plan checks for every motion family whose executor consumes
            # snapshot geometry.  These checks do not rebuild geometry; they only prove
            # that the current dispatcher still owns the plan it is about to execute.
            if action_now in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                rp = pending.get("pose_rotation_plan")
                if not isinstance(rp, dict):
                    return "ROTATE exact frozen pose/mask rotation plan is missing"
                exact = str(rp.get("rotation_motion_exact_action") or "").upper()
                if exact != action_now:
                    return f"ROTATE frozen plan exact={exact or 'NONE'} but dispatcher={action_now}"
                if not bool(rp.get("ready", False)) or bool(rp.get("done", False)):
                    return f"ROTATE frozen plan is not executable: status={rp.get('status')}"
            elif action_now == "CENTER_CIRCUMCENTER":
                if not isinstance(pending.get("coarse_plan"), dict):
                    return "CENTER exact frozen coarse/segmentation plan is missing"
            elif action_now in {"ACTION_AMBIGUOUS_CIRCUMCENTER_NUDGE", "ACTION_POSE_RECOVERY_CIRCUMCENTER_NUDGE", "ACTION_NO_ACTION_STUCK_PROBE"}:
                if not isinstance(pending.get("coarse_plan"), dict):
                    return f"{action_now} exact frozen coarse plan is missing"
            elif action_now in {"ACTION2_SEGMENTATION_SPREAD", "SEGMENTATION_SPREAD", "ACTION2_SEGMENTATION_SPREAD_REDUCED"}:
                _sp = pending.get("action2_step37_plan")
                if not isinstance(_sp, dict):
                    return f"{action_now} exact frozen Step37 spread plan is missing"
                if True:
                    _expected = pending.get("action2_step37_binding_id")
                    _actual = _vla_action2_step37_binding_signature(_sp)
                    if not bool(pending.get("action2_step37_bound_at_x", False)):
                        return f"{action_now} spread plan was not bound at X judgment"
                    if not _expected or str(_expected) != str(_actual):
                        return f"{action_now} spread binding mismatch expected={_expected} actual={_actual}"
            elif action_now in {"ACTION5_ORTHOGONAL_SPREAD", "ACTION_GRAY_AMBIGUITY_PROBE"}:
                if not isinstance(pending.get("coarse_plan"), dict):
                    return f"{action_now} exact frozen coarse/orthogonal plan is missing"
            elif action_now in {
                "ACTION3_LONG_WRINKLE_NORMAL_PULL", "ACTION3_LONG_WRINKLE_NORMAL_PULL_REDUCED",
                "ACTION3B_GRAY_PROBE", "ACTION3_REPEAT_OUTWARD_PROBE",
                "ACTION_STRUCTURAL_STATIC_PROBE",
            }:
                if not isinstance(pending.get("targeted_plan"), dict):
                    return f"{action_now} exact frozen targeted plan is missing"
            elif action_now == "CENTER_CIRCUMCENTER_LATE" or action_now.startswith("LATE_"):
                if not isinstance(pending.get("late_plan"), dict):
                    return f"{action_now} exact frozen Late plan is missing"
            return None

        action = str(pending_auto_x_action.get("action", "UNKNOWN"))
        if action == "HUMAN_FINISH":
            return bool(_submission_finish_cycle("MODEL_OR_AUTOX_FINISH"))
        if action == "HUMAN_REJUDGE":
            _submission_stop_cycle("REJUDGE_HOLD", str(pending_auto_x_action.get("reason") or "no executable safe action"))
            return False

        binding_error = _execution_binding_error(dict(pending_auto_x_action))
        if binding_error:
            print(f"[VLA0855-FULLAUTO-BINDING-BLOCKED] action={action} reason={binding_error}")
            _a140_set_outer_overlay(
                "FULL AUTO BLOCKED - SAFETY GATE",
                f"{action}: {binding_error} | cycle stopped; inspect then press X",
                hold_s=180.0,
            )
            _submission_stop_cycle("BINDING_BLOCKED", str(binding_error))
            return False

        if bool(motion_busy):
            print(f"[VLA0855-FULLAUTO-APPROVAL-DEFER] source={source} action={action} motion_busy=True")
            return False
        approval_epoch = auto_x_controller.claim_physical_approval()
        if approval_epoch is None:
            print(
                f"[VLA0855-FULLAUTO-APPROVAL-BLOCKED] source={source} action={action} "
                f"armed={bool(auto_x_controller.armed)} state={auto_x_controller.state}"
            )
            return False

        auto_x_latency.begin(auto_x_controller.cycle_number, action, "full_auto_approval")
        _a140_set_outer_overlay(
            f"FULL AUTO EXECUTING: {action}",
            "exact frozen Stage3 plan | next: standby -> stillness -> auto rejudge",
            hold_s=180.0,
        )
        print(f"[VLA0855-FULLAUTO-APPROVAL] source={source} action={action} epoch={approval_epoch} exact_pending_plan=True")
        started = start_motion_task(
            "auto-x-pending-execute", execute_pending_auto_x_action,
            expected_auto_x_epoch=approval_epoch,
        )
        if not started:
            auto_x_controller.restore_physical_approval(approval_epoch)
            _a140_latency_print_cycle("START_BLOCKED")
            print(f"[VLA0855-FULLAUTO-START-BLOCKED] action={action}; approval restored")
            return False
        return True

    def _a156_schedule_action3_auto_approval(action: str, expected_epoch: int) -> None:
        preview_s = max(0.0, float(getattr(args, "auto_x_action3_auto_execute_preview_s", 1.0)))
        action_s = str(action)
        print(f"[A156-ACTION3-AUTO-SCHEDULE] action={action_s} preview={preview_s:.2f}s; target watcher remains active")
        def _worker():
            if preview_s > 0.0:
                time.sleep(preview_s)
            deadline = time.monotonic() + 3.0
            while bool(motion_busy) and time.monotonic() < deadline:
                time.sleep(0.05)
            pending = pending_auto_x_action if isinstance(pending_auto_x_action, dict) else None
            if (not isinstance(pending, dict)
                    or str(pending.get("action")) != action_s
                    or int(pending.get("a140_cycle_epoch", -1)) != int(expected_epoch)
                    or not auto_x_controller.is_current(int(expected_epoch))):
                print(f"[A156-ACTION3-AUTO-CANCEL] action={action_s}; pending target was invalidated/replaced")
                return
            if bool(motion_busy):
                print(f"[A156-ACTION3-AUTO-CANCEL] action={action_s}; worker remained busy after preview")
                return
            print(f"[A156-ACTION3-AUTO-APPROVAL] action={action_s}; executing exact frozen plan without Enter")
            _a140_start_pending_from_physical_approval("AUTO_ACTION3")
        threading.Thread(target=_worker, daemon=True).start()

    def _a15031_start_key1_circumcenter() -> bool:
        """Immediately execute one ordinary CENTER_CIRCUMCENTER from the latest plan.

        Temporary A150-3-1 diagnostic behavior:
          - top-row 1 and numeric-keypad 1 are both received as ord('1');
          - any frozen AUTO-X action is superseded by CENTER_CIRCUMCENTER;
          - when AUTO-X was already armed, normal post-action stillness rejudge resumes;
          - when invoked from idle, exactly one audited Circumcenter action runs and
            the controller returns to IDLE.
        """
        nonlocal pending_auto_x_action, auto_x_manual_judge_active

        if calibration_mode:
            print("[A150-3-1-KEY1] blocked during calibration")
            return False
        if auto_x_physical_recovery_required:
            print(
                "[A150-3-1-KEY1] blocked: physical recovery acknowledgement is required; "
                "inspect safety and press . first"
            )
            return False
        if motion_busy or yolo_busy:
            print(
                f"[A150-3-1-KEY1] blocked: motion_busy={bool(motion_busy)} "
                f"yolo_busy={bool(yolo_busy)}"
            )
            return False
        if latest_coarse_plan is None:
            print(
                "[A150-3-1-KEY1] blocked: no current coarse/segmentation plan. "
                "Capture/complete one valid snapshot first, then press 1 again."
            )
            return False

        was_armed = bool(auto_x_controller.armed)
        old_pending = (
            str(pending_auto_x_action.get("action", "UNKNOWN"))
            if isinstance(pending_auto_x_action, dict) else None
        )

        arm_effect = auto_x_controller.arm_manual()
        key1_epoch = int(auto_x_controller.current_epoch())
        if not was_armed:
            _a110_reset_ready_cycle("A150-3-1 standalone key-1 Circumcenter")
            auto_x_ready_cycle["cycle_active"] = True

        reason = (
            "A150-3-1 manual key-1 override: execute one ordinary "
            "CENTER_CIRCUMCENTER from the latest displayed coarse/segmentation plan"
        )
        result = auto_x_controller.handle_planner_result(
            "CENTER_CIRCUMCENTER",
            reason,
            time.monotonic(),
            expected_epoch=key1_epoch,
        )
        if str(result.get("kind")) != "executable":
            print(f"[A150-3-1-KEY1] controller rejected forced Circumcenter: {result}")
            return False

        pending_auto_x_action = {
            "action": "CENTER_CIRCUMCENTER",
            "reason": reason,
            "coarse_plan": copy.deepcopy(latest_coarse_plan),
            "a140_cycle_epoch": key1_epoch,
            "a15031_key1_override": True,
            "a15031_key1_standalone": bool(not was_armed),
        }
        auto_x_manual_judge_active = True
        _a140_set_outer_overlay(
            "KEY 1 FORCE CIRCUMCENTER",
            "current AUTO-X pending action is overridden; executing immediately",
            hold_s=120.0,
        )
        if old_pending is not None:
            print(f"[A150-3-1-KEY1] discarded pending action={old_pending}")
        print(
            f"[A150-3-1-KEY1] {arm_effect}; execute CENTER_CIRCUMCENTER immediately "
            f"standalone={bool(not was_armed)} epoch={key1_epoch}"
        )
        return bool(_a140_start_pending_from_physical_approval("KEY1_CIRCUMCENTER"))

    def dual_grip_place_same_snapshot():
        # same snapshot dual plan.
        # Both arms first move to hover. Low-Z descent/close is still sequential for safety.
        # After both close, both lift and place/open/retract using the same snapshot targets.
        plan = latest_dual_plan if latest_dual_plan is not None else recompute_dual_plan(print_result=True)
        if not validate_dual_plan_for_step3(plan, label="DUAL-GRIP"):
            return
        xyz = resolve_dual_plan_xyz(plan)
        if xyz is None:
            return

        low_order = ["arm2", "arm1"] if args.dual_low_z_order == "arm2_first" else ["arm1", "arm2"]
        print("\n========== DUAL GRIP-PLACE TEST (J) ==========")
        print("Same snapshot is used for both ARM2-L and ARM1-R targets.")
        print("Sequence: both hover -> sequential low-Z/close -> both lift -> place/open/retract.")
        print(f"Low-Z order: {' -> '.join([x.upper() for x in low_order])}")
        print("This is more advanced than B. Keep emergency power cutoff ready.")
        print("=============================================\n")

        if not send_enabled:
            print("[DRY-RUN] Dual grip-place commands not sent.")
            return

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            if arm_obj is not None:
                arm_obj.torque_on()
                print(f"[DUAL-GRIP] opening {arm_key.upper()} before hover")
                arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
        time.sleep(0.30)
        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["hover"]
            if arm_obj is not None:
                print(f"[DUAL-GRIP] moving {arm_key.upper()} hover: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
                time.sleep(0.15)
        time.sleep(args.grip_down_wait)

        # 2) Sequential descent and close, no re-inference between arms because this is a same-snapshot dual test.
        for arm_key in low_order:
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["grip"]
            if arm_obj is None:
                print(f"[DUAL-GRIP-BLOCKED] {arm_key.upper()} serial is not connected")
                return
            print(f"[DUAL-GRIP] {arm_key.upper()} descend to grip: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
            arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_open, spd=spd_default)
            time.sleep(args.grip_down_wait)
            print(f"[DUAL-GRIP] {arm_key.upper()} open at grip point, wait {args.grip_open_wait:.2f}s")
            arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
            time.sleep(args.grip_open_wait)
            time.sleep(args.grip_contact_wait)
            close_repeat = max(1, int(args.grip_close_repeat))
            for i in range(close_repeat):
                print(f"[DUAL-GRIP] {arm_key.upper()} close {i+1}/{close_repeat}: angle={args.grip_close:.3f}")
                arm_obj.gripper_close(args.grip_close, spd=args.grip_spd, acc=args.grip_acc)
                time.sleep(args.grip_close_wait)
            if abs(float(args.grip_hold) - float(args.grip_close)) > 1e-6:
                print(f"[DUAL-GRIP] {arm_key.upper()} hold angle={args.grip_hold:.3f}")
                arm_obj.set_gripper(args.grip_hold, spd=args.grip_spd, acc=args.grip_acc, delay=0.3)
            time.sleep(args.grip_close_settle)

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["lift"]
            if arm_obj is not None:
                print(f"[DUAL-LIFT] moving {arm_key.upper()} lift: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_hold, spd=spd_default)
                time.sleep(0.15)
        time.sleep(args.place_settle_wait)

        if not args.dual_place_after_grip:
            print("[DUAL-GRIP] dual_place_after_grip is OFF. Both arms remain holding after lift.")
            return

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["place_hover"]
            if arm_obj is not None:
                print(f"[DUAL-PLACE] {arm_key.upper()} place-hover: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_hold, spd=spd_default)
                time.sleep(0.15)
        time.sleep(args.place_settle_wait)

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            tgt = xyz[arm_key]["place_down"]
            if arm_obj is not None:
                print(f"[DUAL-PLACE] {arm_key.upper()} down: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=args.grip_hold, spd=spd_default)
                time.sleep(0.15)
        time.sleep(args.place_settle_wait)

        for arm_key in ("arm2", "arm1"):
            arm_obj = arms.get(arm_key)
            if arm_obj is not None:
                print(f"[DUAL-PLACE] opening {arm_key.upper()} at place point")
                arm_obj.gripper_open(args.grip_open, spd=args.grip_spd, acc=args.grip_acc)
        time.sleep(args.place_open_wait)

        if args.dual_retract_after_place:
            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                tgt = xyz[arm_key]["place_hover"]
                if arm_obj is not None:
                    print(f"[DUAL-PLACE] retract {arm_key.upper()}: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                    arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=safe_gripper, spd=spd_default)
                    time.sleep(0.15)
            time.sleep(args.place_settle_wait)


    def resolve_board_target_for_arm(arm_key: str, bx: float, by: float, rz: float, source: str) -> Optional[Dict[str, float]]:
            """Resolve an arbitrary board target for a specific arm.
            Used by Step4 stretched-place targets where the target is shifted outward from the grasp point.

            Step_b31: keep terminal logs clean by default. The detailed
            board=(x,y) -> roarm=(x,y,z) expansion is useful while debugging
            calibration, but too noisy during repeated heatmap/targeted press.
            """
            bx = float(bx); by = float(by); rz = float(rz)
            src_s = str(source)
            compact = bool(getattr(args, "compact_motion_log", True))
            is_target_press = src_s.startswith("TARGET-PRESS")
            detail_log = bool(getattr(args, "board_target_detail_logs", False))
            if src_s.startswith("POSE-ROT"):
                detail_log = bool(getattr(args, "pose_rotate_target_logs", False))
            if src_s.startswith("STANDBY"):
                detail_log = bool(getattr(args, "standby_detail_logs", False))
            if is_target_press:
                detail_log = bool(getattr(args, "targeted_press_motion_detail_logs", False))
            print_success = (not compact) or detail_log
            print_block = bool(getattr(args, "board_target_block_logs", True)) or (not compact) or detail_log
            if is_target_press and not detail_log and compact:
                print_block = False

            expected = select_arm_for_board_x(cfg, bx)
            if expected != arm_key:
                if print_block:
                    print(f"[{source}-BLOCKED] shifted board=({bx:.1f},{by:.1f}) belongs to {expected}, not {arm_key.upper()}")
                return None
            if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, args.board_margin)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} shifted board coordinate outside board bounds: ({bx:.1f},{by:.1f})")
                return None
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
            except Exception as e:
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} affine error: {e}")
                return None
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} shifted RoArm target outside safety range: ({rx:.1f},{ry:.1f},{rz:.1f})")
                return None
            if print_success and not TEMP_HIDE_BOARD_TO_ROARM_LOGS:
                print(f"[{source}] {arm_key.upper()} board=({bx:.1f},{by:.1f}) -> roarm=({rx:.1f},{ry:.1f},{rz:.1f})")
            return {"arm_key": arm_key, "bx": bx, "by": by, "rx": float(rx), "ry": float(ry), "rz": float(rz)}

    def resolve_board_target_for_arm_soft_action3(arm_key: str, bx: float, by: float, rz: float, source: str) -> Optional[Dict[str, float]]:
            """A95 ACTION3-only resolver that bypasses the left/right hard split.

            This is intentionally not used by normal ACTION1/ACTION2/ACTION4/ACTION5.
            It still enforces board bounds, affine conversion, and RoArm XYZ safety.
            Collision risk is controlled at the ACTION3 sequence level by requiring
            a minimum active/hold point separation and sequential approach/down/clear.
            """
            bx = float(bx); by = float(by); rz = float(rz)
            src_s = str(source)
            compact = bool(getattr(args, "compact_motion_log", True))
            detail_log = bool(getattr(args, "targeted_press_motion_detail_logs", False)) or bool(getattr(args, "board_target_detail_logs", False))
            print_success = (not compact) or detail_log
            print_block = bool(getattr(args, "board_target_block_logs", True)) or (not compact) or detail_log
            if src_s.startswith("TARGET-PRESS") and compact and not detail_log:
                print_block = False
            if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, args.board_margin)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-ACTION3 board coordinate outside board bounds: ({bx:.1f},{by:.1f})")
                return None
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
            except Exception as e:
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-ACTION3 affine error: {e}")
                return None
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-ACTION3 RoArm target outside safety range: ({rx:.1f},{ry:.1f},{rz:.1f})")
                return None
            if print_success and not TEMP_HIDE_BOARD_TO_ROARM_LOGS:
                print(f"[{source}-SOFT-ACTION3] {arm_key.upper()} board=({bx:.1f},{by:.1f}) -> roarm=({rx:.1f},{ry:.1f},{rz:.1f})")
            return {"arm_key": arm_key, "bx": bx, "by": by, "rx": float(rx), "ry": float(ry), "rz": float(rz), "soft_action3": True}

    def _pose_rotation_soft_workspace_active(plan: Optional[Dict[str, Any]]) -> bool:
            if not isinstance(plan, dict):
                return False
            if not bool(getattr(args, "pose_rotate_soft_workspace_overlap", True)):
                return False
            mode = str(plan.get("workspace_validation_mode", "private_workspace"))
            return bool(plan.get("soft_workspace_candidate", False) or mode in {"pending_dynamic_overlap", "dynamic_overlap"})

    def _a153_pair_geometry_ok(a2_xy: Any, a1_xy: Any, label: str, print_block: bool = True) -> bool:
            try:
                a2 = np.asarray(a2_xy, dtype=np.float32).reshape(2)
                a1 = np.asarray(a1_xy, dtype=np.float32).reshape(2)
                pair_dist = float(np.linalg.norm(a1 - a2))
            except Exception as e:
                if print_block:
                    print(f"[A153-SOFT-WS-BLOCKED] {label}: invalid pair geometry: {repr(e)}")
                return False
            min_pair = max(0.0, float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)))
            min_gap = max(0.0, float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)))
            finite = bool(np.all(np.isfinite(a2)) and np.all(np.isfinite(a1)) and np.isfinite(pair_dist))
            order_ok = bool(float(a2[0]) + min_gap <= float(a1[0]))
            pair_ok = bool(pair_dist >= min_pair)
            if not (finite and order_ok and pair_ok):
                if print_block:
                    print(
                        f"[A153-SOFT-WS-BLOCKED] {label}: finite={finite} pair={pair_dist:.1f}/{min_pair:.1f}mm "
                        f"x_order A2={float(a2[0]):.1f} + {min_gap:.1f} <= A1={float(a1[0]):.1f} -> {order_ok}"
                    )
                return False
            return True

    def resolve_board_target_for_arm_pose_rotation(plan: Optional[Dict[str, Any]], arm_key: str,
                                                    bx: float, by: float, rz: float,
                                                    source: str) -> Optional[Dict[str, float]]:
            """Resolve a pose-rotation target while softening only the private x split.

            Board bounds, affine conversion, and RoArm XYZ limits remain hard. This
            resolver is never used by non-rotation actions.
            """
            if not _pose_rotation_soft_workspace_active(plan):
                return resolve_board_target_for_arm(arm_key, bx, by, rz, source)
            bx = float(bx); by = float(by); rz = float(rz)
            compact = bool(getattr(args, "compact_motion_log", True))
            detail_log = bool(getattr(args, "pose_rotate_target_logs", False)) or bool(getattr(args, "board_target_detail_logs", False))
            print_success = (not compact) or detail_log
            print_block = bool(getattr(args, "board_target_block_logs", True)) or (not compact) or detail_log
            if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, args.board_margin)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-workspace board coordinate outside board bounds: ({bx:.1f},{by:.1f})")
                return None
            try:
                rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
            except Exception as e:
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-workspace affine error: {e}")
                return None
            if (not args.allow_unsafe_roarm) and (not is_xyz_safe(float(rx), float(ry), rz, args)):
                if print_block:
                    print(f"[{source}-BLOCKED] {arm_key.upper()} soft-workspace RoArm target outside safety range: ({rx:.1f},{ry:.1f},{rz:.1f})")
                return None
            if print_success and not TEMP_HIDE_BOARD_TO_ROARM_LOGS:
                zone = select_arm_for_board_x(cfg, bx)
                print(f"[{source}-A153-SOFT-WS] {arm_key.upper()} board=({bx:.1f},{by:.1f}) nominal_zone={zone} -> roarm=({rx:.1f},{ry:.1f},{rz:.1f})")
            return {
                "arm_key": arm_key, "bx": bx, "by": by,
                "rx": float(rx), "ry": float(ry), "rz": float(rz),
                "pose_rotate_soft_workspace": True,
            }

    def recompute_pose_rotation_plan_from_frame(src_frame: np.ndarray, reason: str = "manual"):
            nonlocal latest_pose_rotation_plan, latest_pose_rotation_status, snapshot_canvas
            if pose_model is None:
                latest_pose_rotation_plan = None
                latest_pose_rotation_status = "pose model not loaded"
                print(f"[POSE-ROT] {latest_pose_rotation_status}")
                return None
            if latest_H is None:
                latest_pose_rotation_plan = None
                latest_pose_rotation_status = "Homography not locked"
                print(f"[POSE-ROT] {latest_pose_rotation_status}")
                return None
            base = snapshot_canvas if snapshot_canvas is not None else src_frame
            mask_ref = None
            try:
                if latest_candidates:
                    mask_ref = max(latest_candidates, key=lambda c: float(c.get("area", c.get("area_px", 0.0))))
                elif latest_candidate is not None:
                    mask_ref = latest_candidate
            except Exception:
                mask_ref = latest_candidate
            pose_canvas, plan, status = infer_tshirt_pose_rotation_plan(
                pose_model, src_frame, latest_H, cfg,
                imgsz=int(args.pose_imgsz), conf=float(args.pose_conf), kpt_conf=float(args.pose_kpt_conf),
                target_axis_deg=float(args.pose_target_axis_deg),
                target_axis_mode=str(getattr(args, "pose_target_axis_mode", "auto_nearest")),
                deadband_deg=float(args.pose_rotate_deadband_deg),
                max_delta_deg=float(args.pose_rotate_max_delta_deg),
                gain=float(args.pose_rotate_gain),
                min_axis_len_mm=float(args.pose_rotate_min_axis_len_mm),
                min_grip_keypoints_per_side=int(getattr(args, "pose_rotate_min_grip_keypoints_per_side", 2)),
                initial_min_pair_distance_mm=float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)),
                arm2_grip_inset_mm=float(getattr(args, "pose_rotate_arm2_grip_inset_mm", 0.0)),
                arm1_grip_inset_mm=float(getattr(args, "pose_rotate_arm1_grip_inset_mm", 0.0)),
                arm2_opposite_extra_inset_mm=float(getattr(args, "pose_rotate_arm2_opposite_extra_inset_mm", 0.0)),
                arm1_opposite_extra_inset_mm=float(getattr(args, "pose_rotate_arm1_opposite_extra_inset_mm", 0.0)),
                min_ready_scale=float(getattr(args, "pose_rotate_min_ready_scale", 0.0)),
                small_scale_inward_retry=bool(getattr(args, "pose_rotate_small_scale_inward_retry", True)),
                workspace_grip_retarget=bool(getattr(args, "pose_rotate_inward_grip_retry", True)),
                workspace_grip_step_mm=float(getattr(args, "pose_rotate_inward_grip_step_mm", 20.0)),
                workspace_grip_max_mm=float(getattr(args, "pose_rotate_inward_grip_max_mm", 60.0)),
                workspace_grip_id02_fallback=bool(getattr(args, "pose_rotate_id02_grip_fallback", True)),
                allow_soft_workspace_overlap=bool(getattr(args, "pose_rotate_soft_workspace_overlap", True)),
                soft_workspace_min_pair_distance_mm=float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)),
                soft_workspace_min_x_order_gap_mm=float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)),
                base_canvas=base,
                mask_candidate=mask_ref,
                mask_direction_check=bool(getattr(args, "pose_mask_direction_check", False)),
                mask_direction_max_diff_deg=float(getattr(args, "pose_mask_direction_max_diff_deg", 55.0)),
                mask_direction_axis_mode=str(getattr(args, "pose_mask_direction_axis_mode", "either")),
                mask_direction_min_axis_ratio=float(getattr(args, "pose_mask_direction_min_axis_ratio", 1.12)),
                mask_direction_min_len_mm=float(getattr(args, "pose_mask_direction_min_len_mm", 90.0)),
                mask_direction_policy=str(getattr(args, "pose_mask_direction_policy", "block")),
            )
            plan = build_linear_pull_rotation_plan(
                plan, mask_ref, latest_H, cfg,
                enabled=bool(getattr(args, "pose_rotate_linear_pull_enable", True)),
                shear_threshold_deg=float(getattr(args, "pose_rotate_linear_shear_threshold_deg", 45.0)),
                mask_inset_mm=float(getattr(args, "pose_rotate_linear_mask_inset_mm", 25.0)),
                mask_inset_min_mm=float(getattr(args, "pose_rotate_linear_mask_inset_min_mm", 12.0)),
                shear_pull_mm=float(getattr(args, "pose_rotate_linear_shear_pull_mm", 35.0)),
                shear_effect_gain=float(getattr(args, "pose_rotate_linear_shear_effect_gain", 0.55)),
                shear_target_min_deg=float(getattr(args, "pose_rotate_linear_shear_target_min_deg", 22.0)),
                shear_target_max_deg=float(getattr(args, "pose_rotate_linear_shear_target_max_deg", 35.0)),
                shear_min_mm=float(getattr(args, "pose_rotate_linear_shear_min_mm", 60.0)),
                shear_max_mm=float(getattr(args, "pose_rotate_linear_shear_max_mm", 160.0)),
                pull_ray_max_error_deg=float(getattr(args, "pose_rotate_linear_pull_ray_max_error_deg", 10.0)),
                pull_symmetry_max_error_mm=float(getattr(args, "pose_rotate_linear_pull_symmetry_max_error_mm", 20.0)),
                pull_effect_gain=float(getattr(args, "pose_rotate_linear_pull_effect_gain", 0.80)),
                pull_target_min_deg=float(getattr(args, "pose_rotate_linear_pull_target_min_deg", 10.0)),
                pull_target_max_deg=float(getattr(args, "pose_rotate_linear_pull_target_max_deg", 30.0)),
                pull_min_mm=float(getattr(args, "pose_rotate_linear_pull_min_mm", 40.0)),
                pull_max_mm=float(getattr(args, "pose_rotate_linear_pull_max_mm", 120.0)),
                pull_gain_mm_per_deg=float(getattr(args, "pose_rotate_linear_pull_gain_mm_per_deg", 0.90)),
                pull_outward_mix=float(getattr(args, "pose_rotate_linear_pull_outward_mix", 0.10)),
                pull_pair_stretch_penalty_weight=float(getattr(args, "pose_rotate_linear_pull_pair_stretch_penalty_weight", 0.35)),
                pull_prefer_long_lever=bool(getattr(args, "pose_rotate_linear_pull_prefer_long_lever", True)),
                pull_long_lever_retention_min=float(getattr(args, "pose_rotate_linear_pull_long_lever_retention_min", 0.55)),
                pull_aggressive_enable=bool(getattr(args, "pose_rotate_linear_pull_aggressive_enable", True)),
                pull_aggressive_start_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_start_deg", 18.0)),
                pull_aggressive_full_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_full_deg", 30.0)),
                pull_aggressive_gain_max=float(getattr(args, "pose_rotate_linear_pull_aggressive_gain_max", 1.20)),
                pull_aggressive_target_max_deg=float(getattr(args, "pose_rotate_linear_pull_aggressive_target_max_deg", 34.0)),
                pull_aggressive_effect_priority_bonus=float(getattr(args, "pose_rotate_linear_pull_aggressive_effect_priority_bonus", 0.35)),
                initial_min_pair_distance_mm=float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)),
                path_min_pair_distance_mm=float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)),
                min_x_order_gap_mm=float(getattr(args, "pose_rotate_soft_workspace_min_x_order_gap_mm", 20.0)),
                max_pair_stretch_mm=float(getattr(args, "pose_rotate_linear_max_pair_stretch_mm", 45.0)),
                shear_max_pair_stretch_mm=float(getattr(args, "pose_rotate_linear_shear_max_pair_stretch_mm", 80.0)),
                max_pair_stretch_ratio=float(getattr(args, "pose_rotate_linear_max_pair_stretch_ratio", 0.20)),
            )
            plan = _a153_prepare_pose_rotation_plan(plan, source=f"recompute:{reason}")
            if isinstance(plan, dict):
                status = str(plan.get("status", status))
                draw_tshirt_pose_rotation_plan_overlay(pose_canvas, latest_H, plan)
            latest_pose_rotation_plan = plan
            latest_pose_rotation_status = status
            snapshot_canvas = pose_canvas
            print(f"[POSE-ROT] recompute on {reason}: {status}")
            return plan

    def save_pose_failure_capture(src_frame: np.ndarray, reason: str = "manual key 3"):
        """Save raw/overlay images and metadata for later pose relabeling/fine-tuning."""
        try:
            save_dir = str(getattr(args, "pose_fail_save_dir", "pose_fail_captures"))
            os.makedirs(save_dir, exist_ok=True)
            ts = time.strftime("%Y%m%d_%H%M%S")
            base_name = f"pose_fail_{ts}_{int(time.time() * 1000) % 1000:03d}"
            raw_img = src_frame.copy() if src_frame is not None else None
            if snapshot_frame is not None:
                raw_img = snapshot_frame.copy()
            overlay_img = snapshot_canvas.copy() if snapshot_canvas is not None else raw_img
            raw_path = os.path.join(save_dir, base_name + "_raw.jpg")
            overlay_path = os.path.join(save_dir, base_name + "_overlay.jpg")
            meta_path = os.path.join(save_dir, base_name + ".json")
            if raw_img is not None:
                cv2.imwrite(raw_path, raw_img)
            if overlay_img is not None:
                cv2.imwrite(overlay_path, overlay_img)
            meta = {
                "reason": reason,
                "time": ts,
                "raw_image": raw_path,
                "overlay_image": overlay_path,
                "pose_status": latest_pose_rotation_status,
                "pose_plan": latest_pose_rotation_plan,
                "homography_locked": bool(homography_locked),
                "note": "Use the raw image for manual keypoint relabeling. Overlay image records what the model/code believed at capture time.",
            }
            with open(meta_path, "w", encoding="utf-8") as f:
                json.dump(_json_safe(meta), f, ensure_ascii=False, indent=2)
            print(f"[POSE-FAIL-SAVE] saved raw={raw_path}")
            print(f"[POSE-FAIL-SAVE] saved overlay={overlay_path}")
            print(f"[POSE-FAIL-SAVE] saved meta={meta_path}")
        except Exception as e:
            print(f"[POSE-FAIL-SAVE-ERROR] {repr(e)}")

    def request_fresh_pose_rotation_plan_and_wait(reason: str, timeout: float):
            """Ask the main camera loop for a fresh snapshot, then rebuild the pose-rotation plan.

            The pose model itself is run here after the normal snapshot/Yolo pipeline finishes.
            This reuses the existing stable-frame mechanism so the robot arms are moved to standby
            and the camera sees the current cloth state before the next rotation step.
            """
            nonlocal force_snapshot_reason
            old_serial = inference_serial
            reset_snapshot(f"{reason}: requesting fresh pose-rotation target before motion")
            force_snapshot_reason = reason
            print(f"[POSE-AUTO] Requested fresh snapshot: {reason}")
            start = time.time()
            while time.time() - start < float(timeout):
                time.sleep(0.05)
                if inference_serial > old_serial and not yolo_busy:
                    if snapshot_frame is None:
                        print("[POSE-AUTO-BLOCKED] fresh inference finished but snapshot_frame is None")
                        return None
                    return recompute_pose_rotation_plan_from_frame(snapshot_frame.copy(), reason=reason)
            print(f"[POSE-AUTO-TIMEOUT] No fresh pose snapshot within {timeout:.1f}s. Stop auto rotation for safety.")
            return None

    def compute_pose_rotation_slack_geometry(plan: Dict[str, Any]) -> Optional[Dict[str, Any]]:
            """Compute inward pre-slack board points for key-6 pose rotation.

            The actual grippers still approach and close at the original pose points.
            After lift, ARM2 moves toward ARM1 and ARM1 moves toward ARM2 by the
            effective pre-slack distance.  Rotation waypoints are then generated from
            the shorter gripper pair, so the cloth is not pulled taut during rotation.
            """
            if not isinstance(plan, dict):
                return None
            cached = plan.get("_pose_slack_geometry")
            if isinstance(cached, dict):
                return cached
            try:
                center_b = np.asarray(plan.get("center_board_xy"), dtype=np.float32).reshape(2)
                a2_orig = np.asarray(plan.get("targets", {}).get("arm2", {}).get("orig_board_xy"), dtype=np.float32).reshape(2)
                a1_orig = np.asarray(plan.get("targets", {}).get("arm1", {}).get("orig_board_xy"), dtype=np.float32).reshape(2)
                total_delta = float(plan.get("action_delta_deg", 0.0))
            except Exception as e:
                print(f"[POSE-SLACK-BLOCKED] cannot read pose rotation points: {repr(e)}")
                return None

            pair_start = float(np.linalg.norm(a1_orig - a2_orig))
            if not np.isfinite(pair_start) or pair_start < 1.0:
                print(f"[POSE-SLACK-BLOCKED] invalid pair distance: {pair_start}")
                return None
            u = (a1_orig - a2_orig) / max(pair_start, 1e-6)

            linear_exact = str(plan.get("rotation_motion_exact_action", ""))
            if linear_exact in {"ROTATE_SHEAR", "ROTATE_PULL"}:
                try:
                    a2_target = np.asarray(plan.get("targets", {}).get("arm2", {}).get("rotated_board_xy"), dtype=np.float32).reshape(2)
                    a1_target = np.asarray(plan.get("targets", {}).get("arm1", {}).get("rotated_board_xy"), dtype=np.float32).reshape(2)
                except Exception as exc:
                    print(f"[POSE-ROT-LINEAR-BLOCKED] cannot read straight-pull targets: {repr(exc)}")
                    return None
                lift_z2 = get_pose_rotate_lift_z("arm2")
                lift_z1 = get_pose_rotate_lift_z("arm1")
                if lift_z2 is None or lift_z1 is None:
                    print("[POSE-ROT-LINEAR-BLOCKED] lift_z missing for one arm")
                    return None
                place_z2 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                                 else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm2")))
                place_z1 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                                 else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm1")))
                checks = [
                    select_arm_for_board_x(cfg, float(a2_orig[0])) == "arm2",
                    select_arm_for_board_x(cfg, float(a1_orig[0])) == "arm1",
                    select_arm_for_board_x(cfg, float(a2_target[0])) == "arm2",
                    select_arm_for_board_x(cfg, float(a1_target[0])) == "arm1",
                    is_board_safe(cfg, float(a2_orig[0]), float(a2_orig[1]), margin=0.0),
                    is_board_safe(cfg, float(a1_orig[0]), float(a1_orig[1]), margin=0.0),
                    is_board_safe(cfg, float(a2_target[0]), float(a2_target[1]), margin=0.0),
                    is_board_safe(cfg, float(a1_target[0]), float(a1_target[1]), margin=0.0),
                ]
                if not all(checks):
                    print("[POSE-ROT-LINEAR-BLOCKED] private workspace/board check failed")
                    return None
                pair_target = float(np.linalg.norm(a1_target - a2_target))
                min_pair = max(0.0, float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)))
                max_abs = max(0.0, float(
                    getattr(args, "pose_rotate_linear_shear_max_pair_stretch_mm", 80.0)
                    if linear_exact == "ROTATE_SHEAR"
                    else getattr(args, "pose_rotate_linear_max_pair_stretch_mm", 45.0)
                ))
                max_ratio = max(0.0, float(getattr(args, "pose_rotate_linear_max_pair_stretch_ratio", 0.20)))
                allowed = max_abs
                if max_ratio > 0.0:
                    allowed = min(allowed, pair_start * max_ratio) if allowed > 0.0 else pair_start * max_ratio
                stretch = max(0.0, pair_target - pair_start)
                if pair_target < min_pair or (allowed > 0.0 and stretch > allowed + 1e-6):
                    print(f"[POSE-ROT-LINEAR-BLOCKED] pair {pair_start:.1f}->{pair_target:.1f}mm stretch={stretch:.1f}/{allowed:.1f}mm")
                    return None
                geom = {
                    "enabled": False, "linear_mode": True, "linear_exact_action": linear_exact,
                    "requested_mm": 0.0, "effective_mm": 0.0, "restore_ratio": 0.0,
                    "pre_slack_min_pair_mm": float(pair_start),
                    "pair_start_mm": float(pair_start), "pair_slack_mm": float(pair_start),
                    "pair_rot_mm": float(pair_target), "pair_final_mm": float(pair_target),
                    "center_board_xy": [float(center_b[0]), float(center_b[1])],
                    "arm2_orig_board_xy": [float(a2_orig[0]), float(a2_orig[1])],
                    "arm1_orig_board_xy": [float(a1_orig[0]), float(a1_orig[1])],
                    "arm2_slack_board_xy": [float(a2_orig[0]), float(a2_orig[1])],
                    "arm1_slack_board_xy": [float(a1_orig[0]), float(a1_orig[1])],
                    "arm2_rot_board_xy": [float(a2_target[0]), float(a2_target[1])],
                    "arm1_rot_board_xy": [float(a1_target[0]), float(a1_target[1])],
                    "arm2_final_board_xy": [float(a2_target[0]), float(a2_target[1])],
                    "arm1_final_board_xy": [float(a1_target[0]), float(a1_target[1])],
                }
                plan["_pose_slack_geometry"] = geom
                print(f"[POSE-ROT-LINEAR] {linear_exact}: pre-slack disabled; pair {pair_start:.1f}->{pair_target:.1f}mm")
                return geom

            requested = abs(float(getattr(args, "pose_rotate_pre_slack_mm", 50.0)))
            restore_ratio = float(getattr(args, "pose_rotate_restore_ratio", 0.0))
            if str(plan.get("selected_target_name", "")).lower() == "opposite":
                opp_slack = getattr(args, "pose_rotate_opposite_pre_slack_mm", None)
                if opp_slack is not None:
                    try:
                        opp_slack_f = float(opp_slack)
                        if np.isfinite(opp_slack_f) and opp_slack_f >= 0.0:
                            requested = abs(opp_slack_f)
                    except Exception:
                        pass
                opp_restore = getattr(args, "pose_rotate_opposite_restore_ratio", None)
                if opp_restore is not None:
                    try:
                        opp_restore_f = float(opp_restore)
                        if np.isfinite(opp_restore_f):
                            restore_ratio = opp_restore_f
                    except Exception:
                        pass
            enabled = bool(getattr(args, "pose_rotate_pre_slack", True)) and requested > 0.01
            restore_ratio = float(np.clip(restore_ratio, 0.0, 1.0))
            pre_slack_min_pair = abs(float(getattr(args, "pose_rotate_pre_slack_min_pair_mm", 160.0)))
            if not np.isfinite(pre_slack_min_pair):
                pre_slack_min_pair = 160.0
            # Never use this quality floor to relax the existing 80mm path safety.
            # The initial ROTATE grip gate should already make pair_start >=160mm,
            # but clamp defensively so a marginal/custom plan does not move inward.
            pre_slack_min_pair = max(0.0, min(pre_slack_min_pair, pair_start))
            if not enabled:
                requested = 0.0

            lift_z2 = get_pose_rotate_lift_z("arm2")
            lift_z1 = get_pose_rotate_lift_z("arm1")
            if lift_z2 is None or lift_z1 is None:
                print("[POSE-SLACK-BLOCKED] lift_z missing for one arm")
                return None
            place_z2 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                             else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm2")))
            place_z1 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                             else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm1")))

            def _rotate_point(p: np.ndarray, delta_deg: float) -> np.ndarray:
                th = float(np.radians(delta_deg))
                R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]], dtype=np.float32)
                return center_b + R @ (p - center_b)

            soft_workspace = _pose_rotation_soft_workspace_active(plan)

            def _target_ok(arm_key: str, p: np.ndarray, z: float) -> bool:
                bx = float(p[0]); by = float(p[1])
                if (not soft_workspace) and select_arm_for_board_x(cfg, bx) != arm_key:
                    return False
                if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, margin=0.0)):
                    return False
                try:
                    rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
                except Exception:
                    return False
                if (not args.allow_unsafe_roarm) and (not is_xyz_safe(float(rx), float(ry), float(z), args)):
                    return False
                return True

            # Try the requested offset first, then shrink automatically.  The final
            # 0.0 candidate preserves old step_b11/step_b12 behavior and should pass
            # whenever the original pose plan itself is feasible.
            scale_candidates = [1.0, 0.85, 0.75, 0.60, 0.50, 0.40, 0.33, 0.25, 0.15, 0.0]
            if requested <= 0.01:
                scale_candidates = [0.0]
            chosen = None
            for sc in scale_candidates:
                eff = float(requested * sc)
                # keep the useful pre-slack behavior, but never let
                # the actual pre-rotation gripper pair shrink below the dedicated
                # quality floor (default 160mm). This does NOT replace the existing
                # 80mm A153 in-path safety check used for the full rotation path.
                max_eff = max(0.0, (pair_start - pre_slack_min_pair) / 2.0)
                eff = min(eff, max_eff)
                a2_slack = a2_orig + u * eff
                a1_slack = a1_orig - u * eff
                a2_rot = _rotate_point(a2_slack, total_delta)
                a1_rot = _rotate_point(a1_slack, total_delta)
                rot_pair = float(np.linalg.norm(a1_rot - a2_rot))
                if rot_pair > 1e-6:
                    u_rot = (a1_rot - a2_rot) / rot_pair
                else:
                    u_rot = u.copy()
                a2_final = a2_rot - u_rot * eff * restore_ratio
                a1_final = a1_rot + u_rot * eff * restore_ratio

                checks = [
                    _target_ok("arm2", a2_slack, float(lift_z2)),
                    _target_ok("arm1", a1_slack, float(lift_z1)),
                    _target_ok("arm2", a2_rot, float(lift_z2)),
                    _target_ok("arm1", a1_rot, float(lift_z1)),
                    _target_ok("arm2", a2_final, float(place_z2)),
                    _target_ok("arm1", a1_final, float(place_z1)),
                    _target_ok("arm2", a2_final, float(approach_z)),
                    _target_ok("arm1", a1_final, float(approach_z)),
                ]
                if soft_workspace:
                    checks.extend([
                        _a153_pair_geometry_ok(a2_orig, a1_orig, "orig grip pair", print_block=False),
                        _a153_pair_geometry_ok(a2_slack, a1_slack, f"pre-slack pair sc={sc:.2f}", print_block=False),
                        _a153_pair_geometry_ok(a2_rot, a1_rot, f"rotated pair sc={sc:.2f}", print_block=False),
                        _a153_pair_geometry_ok(a2_final, a1_final, f"final pair sc={sc:.2f}", print_block=False),
                    ])
                if all(checks):
                    chosen = (eff, a2_slack, a1_slack, a2_rot, a1_rot, a2_final, a1_final)
                    break

            if chosen is None:
                print("[POSE-SLACK-BLOCKED] no safe slack geometry found, even at 0mm. Keep original pose block.")
                return None

            eff, a2_slack, a1_slack, a2_rot, a1_rot, a2_final, a1_final = chosen
            pair_slack = float(np.linalg.norm(a1_slack - a2_slack))
            pair_rot = float(np.linalg.norm(a1_rot - a2_rot))
            pair_final = float(np.linalg.norm(a1_final - a2_final))
            geom = {
                "enabled": bool(enabled),
                "requested_mm": float(requested),
                "effective_mm": float(eff),
                "restore_ratio": float(restore_ratio),
                "pre_slack_min_pair_mm": float(pre_slack_min_pair),
                "pair_start_mm": float(pair_start),
                "pair_slack_mm": float(pair_slack),
                "pair_rot_mm": float(pair_rot),
                "pair_final_mm": float(pair_final),
                "center_board_xy": [float(center_b[0]), float(center_b[1])],
                "arm2_orig_board_xy": [float(a2_orig[0]), float(a2_orig[1])],
                "arm1_orig_board_xy": [float(a1_orig[0]), float(a1_orig[1])],
                "arm2_slack_board_xy": [float(a2_slack[0]), float(a2_slack[1])],
                "arm1_slack_board_xy": [float(a1_slack[0]), float(a1_slack[1])],
                "arm2_rot_board_xy": [float(a2_rot[0]), float(a2_rot[1])],
                "arm1_rot_board_xy": [float(a1_rot[0]), float(a1_rot[1])],
                "arm2_final_board_xy": [float(a2_final[0]), float(a2_final[1])],
                "arm1_final_board_xy": [float(a1_final[0]), float(a1_final[1])],
            }
            plan["_pose_slack_geometry"] = geom
            if requested > 0.01:
                print(f"[POSE-SLACK] requested={requested:.1f}mm, effective={eff:.1f}mm/arm, "
                      f"min_pair={pre_slack_min_pair:.1f}mm, restore_ratio={restore_ratio:.2f}, "
                      f"pair {pair_start:.1f} -> {pair_slack:.1f} -> {pair_final:.1f}mm")
            return geom

    def resolve_pose_rotation_xyz(plan: Dict[str, Any]) -> Optional[Dict[str, Dict[str, Dict[str, float]]]]:
        if not isinstance(plan, dict):
            return None
        geom = compute_pose_rotation_slack_geometry(plan)
        if not isinstance(geom, dict):
            return None
        out: Dict[str, Dict[str, Dict[str, float]]] = {}
        for arm_key in ("arm2", "arm1"):
            td = plan.get("targets", {}).get(arm_key)
            if not isinstance(td, dict):
                print(f"[POSE-ROT-BLOCKED] missing {arm_key.upper()} target")
                return None
            ob = td.get("orig_board_xy")
            if ob is None:
                print(f"[POSE-ROT-BLOCKED] missing {arm_key.upper()} board xy")
                return None
            grip_z = get_pose_rotate_grip_z(arm_key)
            if grip_z is None:
                print(f"[POSE-ROT-BLOCKED] {arm_key.upper()} ROTATE grip_z is not set")
                return None
            lift_z_eff = get_pose_rotate_lift_z(arm_key)
            place_z_eff = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                                else (args.place_z if args.place_z is not None else grip_z))
            prefix = "arm2" if arm_key == "arm2" else "arm1"
            slack_b = geom[f"{prefix}_slack_board_xy"]
            rot_b = geom[f"{prefix}_rot_board_xy"]
            final_b = geom[f"{prefix}_final_board_xy"]
            out[arm_key] = {
                "hover": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(ob[0]), float(ob[1]), approach_z, f"POSE-ROT-HOVER-{arm_key.upper()}"),
                "grip": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(ob[0]), float(ob[1]), float(grip_z), f"POSE-ROT-GRIP-{arm_key.upper()}"),
                "lift": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(ob[0]), float(ob[1]), float(lift_z_eff), f"POSE-ROT-LIFT-{arm_key.upper()}"),
                "pre_slack_lift": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(slack_b[0]), float(slack_b[1]), float(lift_z_eff), f"POSE-ROT-PRE-SLACK-LIFT-{arm_key.upper()}"),
                "rotate_lift": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(rot_b[0]), float(rot_b[1]), float(lift_z_eff), f"POSE-ROT-TARGET-LIFT-{arm_key.upper()}"),
                "rotate_place": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(final_b[0]), float(final_b[1]), float(place_z_eff), f"POSE-ROT-TARGET-PLACE-{arm_key.upper()}"),
                "rotate_retract": resolve_board_target_for_arm_pose_rotation(plan, arm_key, float(final_b[0]), float(final_b[1]), approach_z, f"POSE-ROT-TARGET-RETRACT-{arm_key.upper()}"),
            }
            for name, tgt in out[arm_key].items():
                if tgt is None:
                    print(f"[POSE-ROT-BLOCKED] {arm_key.upper()} {name} target blocked")
                    return None
        return out

    def maybe_apply_inward_grip_retry(plan: Optional[Dict[str, Any]], reason: str = "pose rotation blocked") -> Optional[Dict[str, Any]]:
            """Try safer inward grip points for key-6 pose rotation when target geometry is blocked.

            This is NOT automatic key-4/smart reposition.  The cloth is not dragged or
            recentered.  Only the intended key-6 grip points are moved inward toward the
            detected garment center, then the rotation plan is rechecked.
            """
            if isinstance(plan, dict) and str(plan.get("rotation_motion_exact_action", "")) in {"ROTATE_SHEAR", "ROTATE_PULL"}:
                # rotate_pull_v1 already solved mask inset + private-workspace retargeting;
                # the legacy inward retry rebuilds circular targets and must not alter it.
                return plan
            if not isinstance(plan, dict):
                return plan
            if bool(plan.get("done")):
                return plan
            if not bool(getattr(args, "pose_rotate_inward_grip_retry", True)):
                return plan
            if isinstance(plan.get("_pose_inward_grip"), dict):
                return plan

            rr = str(plan.get("ready_reason", "")).lower()
            # Inward gripping is intended for target/workspace/board blocks only.
            # It should not override pose-mask validation or missing-keypoint failures.
            if ("pose-mask" in rr) or ("validation" in rr) or ("missing" in rr) or ("axis too short" in rr):
                return plan

            should_try = (not bool(plan.get("ready")))
            if not should_try:
                # A plan can be ready at the pose level but become blocked when converted
                # through slack/board/roarm safety checks.  Test a copy so the normal plan
                # is not polluted with failed slack geometry.
                probe = copy.deepcopy(plan)
                probe.pop("_pose_slack_geometry", None)
                if resolve_pose_rotation_xyz(probe) is None:
                    should_try = True
            if not should_try:
                return plan

            try:
                center_b = np.asarray(plan.get("center_board_xy"), dtype=np.float32).reshape(2)
                a2_orig0 = np.asarray(plan.get("targets", {}).get("arm2", {}).get("orig_board_xy"), dtype=np.float32).reshape(2)
                a1_orig0 = np.asarray(plan.get("targets", {}).get("arm1", {}).get("orig_board_xy"), dtype=np.float32).reshape(2)
                base_action = float(plan.get("unscaled_action_delta_deg", plan.get("action_delta_deg", 0.0)))
            except Exception as e:
                print(f"[POSE-INWARD-GRIP] cannot read pose plan geometry: {repr(e)}")
                return plan

            step_mm = abs(float(getattr(args, "pose_rotate_inward_grip_step_mm", 20.0)))
            max_mm = abs(float(getattr(args, "pose_rotate_inward_grip_max_mm", 60.0)))
            if step_mm <= 0.01 or max_mm <= 0.01:
                return plan

            offsets = []
            n = max(1, int(math.ceil(max_mm / step_mm)))
            for i in range(1, n + 1):
                off = min(max_mm, i * step_mm)
                if not offsets or abs(off - offsets[-1]) > 1e-6:
                    offsets.append(float(off))

            def _unit_to_center(p: np.ndarray) -> np.ndarray:
                v = center_b - p
                d = float(np.linalg.norm(v))
                if not np.isfinite(d) or d < 1e-6:
                    return np.zeros(2, dtype=np.float32)
                return (v / d).astype(np.float32)

            def _rotate_point(p: np.ndarray, delta_deg: float) -> np.ndarray:
                th = float(np.radians(delta_deg))
                R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]], dtype=np.float32)
                return center_b + R @ (p - center_b)

            u2 = _unit_to_center(a2_orig0)
            u1 = _unit_to_center(a1_orig0)
            angle_scales = [1.0, 0.85, 0.75, 0.60, 0.50, 0.40, 0.33, 0.25, 0.18, 0.12, 0.08, 0.05]
            min_ready_scale_eff = max(0.0, float(getattr(args, "pose_rotate_min_ready_scale", 0.0)))
            if min_ready_scale_eff > 0.0 and bool(getattr(args, "pose_rotate_small_scale_inward_retry", True)):
                angle_scales = [sc for sc in angle_scales if sc >= min_ready_scale_eff - 1e-9]
            print(f"[POSE-INWARD-GRIP] retry enabled because key-6 plan is blocked: {reason}")
            print(f"[POSE-INWARD-GRIP] This only changes grip points inward; it does NOT run key-4/smart reposition.")

            for off in offsets:
                a2_new = a2_orig0 + u2 * off
                a1_new = a1_orig0 + u1 * off
                if select_arm_for_board_x(cfg, float(a2_new[0])) != "arm2" or select_arm_for_board_x(cfg, float(a1_new[0])) != "arm1":
                    print(f"[POSE-INWARD-GRIP] offset={off:.1f}mm blocked: inward grip crosses workspace "
                          f"A2x={float(a2_new[0]):.1f}, A1x={float(a1_new[0]):.1f}")
                    continue
                if (not args.allow_outside_board) and (not (is_board_safe(cfg, float(a2_new[0]), float(a2_new[1]), margin=0.0)
                                                            and is_board_safe(cfg, float(a1_new[0]), float(a1_new[1]), margin=0.0))):
                    print(f"[POSE-INWARD-GRIP] offset={off:.1f}mm blocked: inward grip outside board")
                    continue

                for sc in angle_scales:
                    test_delta = float(base_action * sc)
                    r2 = _rotate_point(a2_new, test_delta)
                    r1 = _rotate_point(a1_new, test_delta)
                    if select_arm_for_board_x(cfg, float(r2[0])) != "arm2" or select_arm_for_board_x(cfg, float(r1[0])) != "arm1":
                        continue
                    if (not args.allow_outside_board) and (not (is_board_safe(cfg, float(r2[0]), float(r2[1]), margin=0.0)
                                                                and is_board_safe(cfg, float(r1[0]), float(r1[1]), margin=0.0))):
                        continue

                    candidate = copy.deepcopy(plan)
                    candidate.pop("_pose_slack_geometry", None)
                    candidate["ready"] = True
                    candidate["done"] = False
                    candidate["ready_reason"] = "OK after inward grip retry"
                    candidate["action_delta_deg"] = float(test_delta)
                    candidate["selected_scale"] = float(sc)
                    candidate["_pose_inward_grip"] = {
                        "enabled": True,
                        "offset_mm": float(off),
                        "angle_scale": float(sc),
                        "original_ready_reason": str(plan.get("ready_reason", "")),
                        "arm2_orig_before_inward": [float(a2_orig0[0]), float(a2_orig0[1])],
                        "arm1_orig_before_inward": [float(a1_orig0[0]), float(a1_orig0[1])],
                    }
                    candidate["targets"]["arm2"]["orig_board_xy"] = [float(a2_new[0]), float(a2_new[1])]
                    candidate["targets"]["arm1"]["orig_board_xy"] = [float(a1_new[0]), float(a1_new[1])]
                    candidate["targets"]["arm2"]["rotated_board_xy"] = [float(r2[0]), float(r2[1])]
                    candidate["targets"]["arm1"]["rotated_board_xy"] = [float(r1[0]), float(r1[1])]
                    candidate["status"] = (f"POSE ROT INWARD-GRIP: offset={off:.1f}mm scale={sc:.2f} "
                                           f"action={test_delta:+.1f} | READY")
                    if resolve_pose_rotation_xyz(candidate) is not None:
                        print(f"[POSE-INWARD-GRIP] selected offset={off:.1f}mm, angle_scale={sc:.2f}, "
                              f"action={test_delta:+.1f}deg")
                        print(f"[POSE-INWARD-GRIP] ARM2 grip {a2_orig0[0]:.1f},{a2_orig0[1]:.1f} -> {a2_new[0]:.1f},{a2_new[1]:.1f}; "
                              f"ARM1 grip {a1_orig0[0]:.1f},{a1_orig0[1]:.1f} -> {a1_new[0]:.1f},{a1_new[1]:.1f}")
                        return candidate

            print(f"[POSE-INWARD-GRIP] no safe inward grip retry found up to {max_mm:.1f}mm. Keep BLOCKED.")
            return plan

    def build_pose_rotation_step_waypoints_xyz(plan: Dict[str, Any]) -> Optional[List[Dict[str, Any]]]:
            """Build lift-level waypoints for the current ROTATE plan.

            Current exact ROTATE_PULL/ROTATE_SHEAR plans use only straight board-space
            interpolation from their independently planned grips to pull targets.  The
            historical equal-angle arc branch below is retained only for non-executable
            imported plans and is unreachable from the v6 AUTO-X/VLA physical executor.

            Board-space pair distance, board bounds, private arm workspace, RoArm XYZ,
            and synchronized arrival safety are checked at every exact-linear waypoint.
            """
            if not isinstance(plan, dict):
                return None
            geom = compute_pose_rotation_slack_geometry(plan)
            if not isinstance(geom, dict):
                return None
            try:
                center_b = np.asarray(geom.get("center_board_xy"), dtype=np.float32).reshape(2)
                a2_start = np.asarray(geom.get("arm2_slack_board_xy"), dtype=np.float32).reshape(2)
                a1_start = np.asarray(geom.get("arm1_slack_board_xy"), dtype=np.float32).reshape(2)
                total_delta = float(plan.get("action_delta_deg", 0.0))
            except Exception as e:
                print(f"[POSE-ROT-DIST-BLOCKED] cannot read pose rotation board points: {repr(e)}")
                return None

            d0 = float(np.linalg.norm(a1_start - a2_start))
            if not np.isfinite(d0) or d0 < 1.0:
                print(f"[POSE-ROT-DIST-BLOCKED] invalid initial gripper distance: {d0}")
                return None

            linear_exact = str(plan.get("rotation_motion_exact_action", ""))
            if linear_exact in {"ROTATE_SHEAR", "ROTATE_PULL"}:
                try:
                    a2_final = np.asarray(geom.get("arm2_rot_board_xy"), dtype=np.float32).reshape(2)
                    a1_final = np.asarray(geom.get("arm1_rot_board_xy"), dtype=np.float32).reshape(2)
                except Exception as exc:
                    print(f"[POSE-ROT-LINEAR-BLOCKED] invalid final pull points: {repr(exc)}")
                    return None
                move2 = float(np.linalg.norm(a2_final - a2_start))
                move1 = float(np.linalg.norm(a1_final - a1_start))
                seg = max(2.0, float(getattr(args, "pose_rotate_linear_waypoint_mm", 20.0)))
                n_steps = max(1, int(math.ceil(max(move2, move1) / seg)))
                min_pair = max(0.0, float(getattr(args, "pose_rotate_soft_workspace_min_pair_distance_mm", 80.0)))
                max_abs = max(0.0, float(
                    getattr(args, "pose_rotate_linear_shear_max_pair_stretch_mm", 80.0)
                    if linear_exact == "ROTATE_SHEAR"
                    else getattr(args, "pose_rotate_linear_max_pair_stretch_mm", 45.0)
                ))
                max_ratio = max(0.0, float(getattr(args, "pose_rotate_linear_max_pair_stretch_ratio", 0.20)))
                allowed = max_abs
                if max_ratio > 0.0:
                    allowed = min(allowed, d0 * max_ratio) if allowed > 0.0 else d0 * max_ratio
                lift_z2 = get_pose_rotate_lift_z("arm2"); lift_z1 = get_pose_rotate_lift_z("arm1")
                if lift_z2 is None or lift_z1 is None:
                    return None
                rot_speed_base = float(getattr(args, "pose_rotate_rotation_speed", spd_default))
                if not np.isfinite(rot_speed_base) or rot_speed_base <= 0:
                    rot_speed_base = float(spd_default)
                sync_speed = bool(getattr(args, "pose_rotate_sync_speed", True))
                min_speed_scale = float(np.clip(float(getattr(args, "pose_rotate_sync_min_speed_scale", 0.45)), 0.05, 1.0))
                prev2 = a2_start.copy(); prev1 = a1_start.copy(); out_wp = []
                max_seen = d0
                for i in range(1, n_steps + 1):
                    t = float(i) / float(n_steps)
                    b2 = a2_start + (a2_final - a2_start) * t
                    b1 = a1_start + (a1_final - a1_start) * t
                    pd = float(np.linalg.norm(b1 - b2)); max_seen = max(max_seen, pd)
                    if pd < min_pair or (allowed > 0.0 and pd > d0 + allowed + 1e-6):
                        print(f"[POSE-ROT-LINEAR-BLOCKED] step {i}/{n_steps} pair={pd:.1f} start={d0:.1f} allowed_stretch={allowed:.1f}")
                        return None
                    if not (is_board_safe(cfg,float(b2[0]),float(b2[1]),0.0) and is_board_safe(cfg,float(b1[0]),float(b1[1]),0.0)):
                        print(f"[POSE-ROT-LINEAR-BLOCKED] step {i}/{n_steps} outside board")
                        return None
                    if select_arm_for_board_x(cfg,float(b2[0])) != "arm2" or select_arm_for_board_x(cfg,float(b1[0])) != "arm1":
                        print(f"[POSE-ROT-LINEAR-BLOCKED] step {i}/{n_steps} crosses private workspace")
                        return None
                    t2 = resolve_board_target_for_arm_pose_rotation(plan,"arm2",float(b2[0]),float(b2[1]),float(lift_z2),f"POSE-ROT-LINEAR-{i:02d}-ARM2")
                    t1 = resolve_board_target_for_arm_pose_rotation(plan,"arm1",float(b1[0]),float(b1[1]),float(lift_z1),f"POSE-ROT-LINEAR-{i:02d}-ARM1")
                    if t2 is None or t1 is None:
                        return None
                    l2 = float(np.linalg.norm(b2-prev2)); l1 = float(np.linalg.norm(b1-prev1))
                    speed_map={"arm2":rot_speed_base,"arm1":rot_speed_base}
                    if sync_speed:
                        ml=max(l2,l1,1e-6)
                        speed_map={"arm2":rot_speed_base*max(min_speed_scale,min(1.0,l2/ml)),
                                   "arm1":rot_speed_base*max(min_speed_scale,min(1.0,l1/ml))}
                    out_wp.append({
                        "index":i,"count":n_steps,"delta_deg":float(plan.get("action_delta_deg",0.0))*t,
                        "linear_progress":t,"linear_exact_action":linear_exact,
                        "board":{"arm2":[float(b2[0]),float(b2[1])],"arm1":[float(b1[0]),float(b1[1])]},
                        "xyz":{"arm2":t2,"arm1":t1},"pair_dist_mm":pd,
                        "move_len_mm":{"arm2":l2,"arm1":l1},"speed_map":speed_map,
                    })
                    prev2=b2; prev1=b1
                print(f"[POSE-ROT-LINEAR] {linear_exact}: straight waypoints={n_steps}, segment<={seg:.1f}mm, pair={d0:.1f}->{max_seen:.1f}mm")
                return out_wp

            stepwise = bool(getattr(args, "pose_rotate_stepwise_move", True))
            step_max = abs(float(getattr(args, "pose_rotate_step_max_deg", 10.0)))
            if (not stepwise) or step_max <= 0.01:
                n_steps = 1
            else:
                n_steps = max(1, int(math.ceil(abs(total_delta) / step_max)))

            max_stretch = max(0.0, float(getattr(args, "pose_rotate_distance_max_stretch_mm", 3.0)))
            distance_lock = bool(getattr(args, "pose_rotate_distance_lock", True))
            sync_speed = bool(getattr(args, "pose_rotate_sync_speed", True))
            min_speed_scale = float(getattr(args, "pose_rotate_sync_min_speed_scale", 0.45))
            min_speed_scale = float(np.clip(min_speed_scale, 0.05, 1.0))

            lift_z2 = get_pose_rotate_lift_z("arm2")
            lift_z1 = get_pose_rotate_lift_z("arm1")
            if lift_z2 is None or lift_z1 is None:
                print("[POSE-ROT-DIST-BLOCKED] lift_z missing for one arm")
                return None

            prev_b2 = a2_start.copy()
            prev_b1 = a1_start.copy()
            waypoints: List[Dict[str, Any]] = []
            max_seen_dist = d0

            for i in range(1, n_steps + 1):
                delta_i = total_delta * (float(i) / float(n_steps))
                th = float(np.radians(delta_i))
                R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]], dtype=np.float32)
                b2 = center_b + R @ (a2_start - center_b)
                b1 = center_b + R @ (a1_start - center_b)

                dist_i = float(np.linalg.norm(b1 - b2))
                max_seen_dist = max(max_seen_dist, dist_i)
                if distance_lock and dist_i > d0 + max_stretch:
                    print(f"[POSE-ROT-DIST-BLOCKED] waypoint {i}/{n_steps} would stretch pair distance "
                          f"{dist_i:.1f}mm > start {d0:.1f}mm + {max_stretch:.1f}mm")
                    return None

                if not (is_board_safe(cfg, float(b2[0]), float(b2[1]), margin=0.0)
                        and is_board_safe(cfg, float(b1[0]), float(b1[1]), margin=0.0)):
                    print(f"[POSE-ROT-DIST-BLOCKED] waypoint {i}/{n_steps} outside board: "
                          f"A2=({float(b2[0]):.1f},{float(b2[1]):.1f}) "
                          f"A1=({float(b1[0]):.1f},{float(b1[1]):.1f})")
                    return None
                if _pose_rotation_soft_workspace_active(plan):
                    if not _a153_pair_geometry_ok(b2, b1, f"rotation waypoint {i}/{n_steps}"):
                        return None
                elif select_arm_for_board_x(cfg, float(b2[0])) != "arm2" or select_arm_for_board_x(cfg, float(b1[0])) != "arm1":
                    print(f"[POSE-ROT-DIST-BLOCKED] waypoint {i}/{n_steps} crosses arm workspace: "
                          f"A2x={float(b2[0]):.1f}->{select_arm_for_board_x(cfg, float(b2[0]))}, "
                          f"A1x={float(b1[0]):.1f}->{select_arm_for_board_x(cfg, float(b1[0]))}")
                    return None

                t2 = resolve_board_target_for_arm_pose_rotation(plan, "arm2", float(b2[0]), float(b2[1]), float(lift_z2),
                                                                f"POSE-ROT-DIST-STEP-{i:02d}-ARM2")
                t1 = resolve_board_target_for_arm_pose_rotation(plan, "arm1", float(b1[0]), float(b1[1]), float(lift_z1),
                                                                f"POSE-ROT-DIST-STEP-{i:02d}-ARM1")
                if t2 is None or t1 is None:
                    print(f"[POSE-ROT-DIST-BLOCKED] waypoint {i}/{n_steps} RoArm target blocked")
                    return None

                len2 = float(np.linalg.norm(b2 - prev_b2))
                len1 = float(np.linalg.norm(b1 - prev_b1))
                rot_speed_base = float(getattr(args, "pose_rotate_rotation_speed", spd_default))
                if not np.isfinite(rot_speed_base) or rot_speed_base <= 0:
                    rot_speed_base = float(spd_default)
                speed_map = {"arm2": float(rot_speed_base), "arm1": float(rot_speed_base)}
                if sync_speed:
                    max_len = max(len2, len1, 1e-6)
                    s2 = float(rot_speed_base) * max(min_speed_scale, min(1.0, len2 / max_len))
                    s1 = float(rot_speed_base) * max(min_speed_scale, min(1.0, len1 / max_len))
                    speed_map = {"arm2": s2, "arm1": s1}

                waypoints.append({
                    "index": i,
                    "count": n_steps,
                    "delta_deg": float(delta_i),
                    "board": {
                        "arm2": [float(b2[0]), float(b2[1])],
                        "arm1": [float(b1[0]), float(b1[1])],
                    },
                    "xyz": {"arm2": t2, "arm1": t1},
                    "pair_dist_mm": float(dist_i),
                    "move_len_mm": {"arm2": float(len2), "arm1": float(len1)},
                    "speed_map": speed_map,
                })
                prev_b2 = b2
                prev_b1 = b1

            if (not bool(getattr(args, "compact_motion_log", True))) or bool(getattr(args, "pose_rotate_target_logs", False)):
                print(f"[POSE-ROT-DIST] slack_start_pair={d0:.1f}mm, max_waypoint_pair={max_seen_dist:.1f}mm, "
                      f"steps={n_steps}, step_max={step_max:.1f}deg, sync_speed={sync_speed}, "
                      f"rotation_speed={float(getattr(args, 'pose_rotate_rotation_speed', spd_default)):.2f}")
            else:
                print(f"[POSE-ROT-DIST] steps={n_steps}, pair={d0:.1f}->{max_seen_dist:.1f}mm, rot_speed={float(getattr(args, 'pose_rotate_rotation_speed', spd_default)):.2f}")
            return waypoints

    def _a153_validate_soft_workspace_pair_path(plan: Dict[str, Any],
                                                   waypoints: List[Dict[str, Any]]) -> Tuple[bool, str]:
            if not _pose_rotation_soft_workspace_active(plan):
                return True, "private workspace path"
            geom = compute_pose_rotation_slack_geometry(plan)
            if not isinstance(geom, dict):
                return False, "slack geometry unavailable"
            try:
                lift_z2 = float(get_pose_rotate_lift_z("arm2"))
                lift_z1 = float(get_pose_rotate_lift_z("arm1"))
                place_z2 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                                 else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm2")))
                place_z1 = float(args.pose_rotate_place_z if args.pose_rotate_place_z is not None
                                 else (args.place_z if args.place_z is not None else get_pose_rotate_grip_z("arm1")))
                orig2 = np.asarray(geom["arm2_orig_board_xy"], dtype=np.float32)
                orig1 = np.asarray(geom["arm1_orig_board_xy"], dtype=np.float32)
                slack2 = np.asarray(geom["arm2_slack_board_xy"], dtype=np.float32)
                slack1 = np.asarray(geom["arm1_slack_board_xy"], dtype=np.float32)
                final2 = np.asarray(geom["arm2_final_board_xy"], dtype=np.float32)
                final1 = np.asarray(geom["arm1_final_board_xy"], dtype=np.float32)
            except Exception as e:
                return False, f"cannot read soft-workspace geometry: {repr(e)}"

            # soft workspace starts only after the garment has been gripped and lifted.
            # The physical hover/down/grip points themselves must remain in each arm's private zone.
            if select_arm_for_board_x(cfg, float(orig2[0])) != "arm2" or select_arm_for_board_x(cfg, float(orig1[0])) != "arm1":
                return False, (f"initial grip is not private: A2x={float(orig2[0]):.1f}->"
                               f"{select_arm_for_board_x(cfg,float(orig2[0]))}, A1x={float(orig1[0]):.1f}->"
                               f"{select_arm_for_board_x(cfg,float(orig1[0]))}")

            paired_nodes: List[Tuple[np.ndarray, np.ndarray, float, float, str]] = [
                (orig2, orig1, lift_z2, lift_z1, "lift-start"),
                (slack2, slack1, lift_z2, lift_z1, "pre-slack"),
            ]
            for wp in waypoints:
                bd = wp.get("board", {}) if isinstance(wp, dict) else {}
                try:
                    paired_nodes.append((
                        np.asarray(bd.get("arm2"), dtype=np.float32),
                        np.asarray(bd.get("arm1"), dtype=np.float32),
                        lift_z2, lift_z1, f"rotate-{int(wp.get('index',0))}",
                    ))
                except Exception:
                    return False, "invalid waypoint board coordinates"
            paired_nodes.append((final2, final1, place_z2, place_z1, "place-final"))

            sample_mm = max(2.0, float(getattr(args, "pose_rotate_soft_workspace_path_sample_mm", 20.0)))
            sample_count = 0
            for seg_idx in range(1, len(paired_nodes)):
                p20, p10, z20, z10, label0 = paired_nodes[seg_idx - 1]
                p21, p11, z21, z11, label1 = paired_nodes[seg_idx]
                d2 = float(np.linalg.norm(p21 - p20))
                d1 = float(np.linalg.norm(p11 - p10))
                n = max(1, int(math.ceil(max(d2, d1) / sample_mm)))
                for j in range(1, n + 1):
                    t = float(j) / float(n)
                    b2 = p20 + (p21 - p20) * t
                    b1 = p10 + (p11 - p10) * t
                    z2 = float(z20 + (z21 - z20) * t)
                    z1 = float(z10 + (z11 - z10) * t)
                    sample_count += 1
                    label = f"{label0}->{label1} sample {j}/{n}"
                    if not _a153_pair_geometry_ok(b2, b1, label):
                        return False, f"pair geometry failed at {label}"
                    t2 = resolve_board_target_for_arm_pose_rotation(plan, "arm2", float(b2[0]), float(b2[1]), z2, "A153-PATH-ARM2")
                    t1 = resolve_board_target_for_arm_pose_rotation(plan, "arm1", float(b1[0]), float(b1[1]), z1, "A153-PATH-ARM1")
                    if t2 is None or t1 is None:
                        return False, f"board/affine/XYZ target failed at {label}"
            return True, f"dynamic pair path samples={sample_count}, interval<={sample_mm:.1f}mm"

    def _pose_rotation_initial_pair_check(plan: Optional[Dict[str, Any]], source: str, print_block: bool = True) -> Tuple[bool, str, str]:
            if not isinstance(plan, dict) or bool(plan.get("done", False)):
                return True, "OK", "not applicable"
            try:
                targets = plan.get("targets")
                if not isinstance(targets, dict):
                    raise ValueError("targets missing")
                arm2 = targets.get("arm2") if isinstance(targets.get("arm2"), dict) else None
                arm1 = targets.get("arm1") if isinstance(targets.get("arm1"), dict) else None
                if not isinstance(arm2, dict) or not isinstance(arm1, dict):
                    raise ValueError("arm1/arm2 targets missing")
                raw2 = arm2.get("orig_board_xy")
                raw1 = arm1.get("orig_board_xy")
                if raw2 is None or raw1 is None:
                    raise ValueError("orig_board_xy missing")
                p2 = np.asarray(raw2, dtype=np.float32).reshape(2)
                p1 = np.asarray(raw1, dtype=np.float32).reshape(2)
                if not np.all(np.isfinite(p2)) or not np.all(np.isfinite(p1)):
                    raise ValueError("non-finite initial grip target")
                dist = float(np.linalg.norm(p1 - p2))
            except Exception as exc:
                detail = f"invalid/missing initial grip targets: {exc}"
                if print_block:
                    print(f"[POSE-ROT-INITIAL-TARGETS-BLOCKED] source={source}; {detail}")
                return False, "INVALID_TARGETS", detail
            min_initial = max(0.0, float(getattr(args, "pose_rotate_initial_min_pair_distance_mm", 160.0)))
            if not np.isfinite(dist):
                detail = "initial grip pair distance is non-finite"
                if print_block:
                    print(f"[POSE-ROT-INITIAL-TARGETS-BLOCKED] source={source}; {detail}")
                return False, "INVALID_TARGETS", detail
            if dist < min_initial:
                detail = f"pair={dist:.1f}mm < {min_initial:.1f}mm"
                if print_block:
                    print(f"[POSE-ROT-INITIAL-PAIR-BLOCKED] source={source}; {detail}")
                return False, "PAIR_TOO_CLOSE", detail
            return True, "OK", f"pair={dist:.1f}mm >= {min_initial:.1f}mm"

    def _pose_rotation_initial_pair_ok(plan: Optional[Dict[str, Any]], source: str, print_block: bool = True) -> bool:
            ok, _, _ = _pose_rotation_initial_pair_check(plan, source=source, print_block=print_block)
            return bool(ok)

    def _a153_prepare_pose_rotation_plan(plan: Optional[Dict[str, Any]], source: str = "pose inference") -> Optional[Dict[str, Any]]:
            """Promote only private-workspace blocks after a complete path validation.

            vla_0815_v5: legacy circular/arc rotation remains non-executable.
            ROTATE_MID/ROTATE_FINAL are historical compatibility strings only. Current
            frozen physical plans must already be exact ROTATE_PULL or ROTATE_SHEAR.
            """
            if not isinstance(plan, dict) or bool(plan.get("done", False)):
                return plan
            exact = str(plan.get("rotation_motion_exact_action") or "").upper()
            if exact not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                plan = copy.deepcopy(plan)
                plan["ready"] = False
                plan["legacy_arc_disabled"] = True
                plan["ready_reason"] = (
                    f"LEGACY_ARC_DISABLED: exact={exact or 'NONE'}; only ROTATE_PULL/ROTATE_SHEAR are executable"
                )
                base_status = str(plan.get("status", "POSE ROT")).split(" | ")[0]
                plan["status"] = f"{base_status} | BLOCKED: LEGACY ARC DISABLED"
                print(f"[POSE-ROT-LEGACY-ARC-DISABLED] source={source} exact={exact or 'NONE'}; Robot motion: NONE")
                return plan
            pair_ok, pair_code, pair_detail = _pose_rotation_initial_pair_check(plan, source=source)
            if not pair_ok:
                plan["ready"] = False
                plan["rotation_block_code"] = str(pair_code)
                if pair_code == "PAIR_TOO_CLOSE":
                    plan["ready_reason"] = f"ROTATE initial grip pair too close: {pair_detail}"
                    plan["status"] = str(plan.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: initial grip pair too close"
                    print(f"[ROTATE-GEOMETRY-BLOCK] code=PAIR_TOO_CLOSE source={source} detail={pair_detail}")
                else:
                    prior = str(plan.get("ready_reason") or "").strip()
                    if "no safe independent straight-pull geometry" in prior.lower():
                        plan["rotation_block_code"] = "NO_SAFE_LINEAR_GEOMETRY"
                        plan["status"] = str(plan.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: no safe independent linear geometry"
                        print(f"[ROTATE-GEOMETRY-FAILED] code=NO_SAFE_LINEAR_GEOMETRY source={source} detail={prior}")
                    else:
                        if not prior or prior == "OK independent linear ROTATE":
                            plan["ready_reason"] = f"ROTATE initial targets unavailable: {pair_detail}"
                        plan["status"] = str(plan.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: invalid/missing initial targets"
                        print(f"[ROTATE-GEOMETRY-FAILED] code=INVALID_INITIAL_TARGETS source={source} detail={pair_detail}")
                return plan
            if bool(plan.get("soft_workspace_validated", False)) and bool(plan.get("ready", False)):
                return plan
            force_linear_validation = exact in {"ROTATE_PULL", "ROTATE_SHEAR"}
            if not bool(plan.get("soft_workspace_candidate", False)) and not force_linear_validation:
                return plan
            candidate = plan
            if (not force_linear_validation) and (not bool(getattr(args, "pose_rotate_soft_workspace_overlap", True))):
                candidate["ready"] = False
                candidate["workspace_validation_mode"] = "private_workspace_hard_block"
                candidate["ready_reason"] = "A153 soft workspace overlap disabled"
                return candidate

            candidate.pop("_pose_slack_geometry", None)
            candidate["workspace_validation_mode"] = (
                "independent_linear_full_path" if force_linear_validation else "dynamic_overlap"
            )
            candidate["soft_workspace_validated"] = False
            candidate["ready"] = True
            xyz = resolve_pose_rotation_xyz(candidate)
            if xyz is None:
                candidate["ready"] = False
                candidate["ready_reason"] = "A153 SOFT_WORKSPACE_DYNAMIC_BLOCKED: target resolution/slack geometry failed"
                candidate["status"] = str(candidate.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: A153 target validation"
                print(f"[A153-SOFT-WS-BLOCKED] source={source}; target resolution/slack geometry failed")
                print(f"[ROTATE-WORKSPACE-BLOCK] source={source} detail=target resolution/slack geometry failed")
                return candidate
            waypoints = build_pose_rotation_step_waypoints_xyz(candidate)
            if waypoints is None or (bool(getattr(args, "pose_rotate_stepwise_move", True)) and not waypoints):
                candidate["ready"] = False
                candidate["ready_reason"] = "A153 SOFT_WORKSPACE_DYNAMIC_BLOCKED: rotation waypoint validation failed"
                candidate["status"] = str(candidate.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: A153 waypoint validation"
                print(f"[A153-SOFT-WS-BLOCKED] source={source}; rotation waypoint validation failed")
                print(f"[ROTATE-PATH-UNSAFE] source={source} detail=rotation waypoint validation failed")
                return candidate
            path_ok, path_reason = _a153_validate_soft_workspace_pair_path(candidate, waypoints)
            if not path_ok:
                candidate["ready"] = False
                candidate["ready_reason"] = f"A153 SOFT_WORKSPACE_DYNAMIC_BLOCKED: {path_reason}"
                candidate["status"] = str(candidate.get("status", "POSE ROT")).split(" | ")[0] + " | BLOCKED: A153 path validation"
                print(f"[A153-SOFT-WS-BLOCKED] source={source}; {path_reason}")
                print(f"[ROTATE-PATH-UNSAFE] source={source} detail={path_reason}")
                return candidate

            candidate["ready"] = True
            candidate["ready_reason"] = "OK after A153 complete soft-workspace path validation"
            candidate["soft_workspace_validated"] = True
            candidate["soft_workspace_validation_detail"] = path_reason
            candidate["_a153_prevalidated_waypoints"] = copy.deepcopy(waypoints)
            base_status = str(candidate.get("status", "POSE ROT")).split(" | ")[0]
            candidate["status"] = f"{base_status} | READY_SOFT_WS scale={float(candidate.get('selected_scale',1.0)):.2f}"
            if force_linear_validation:
                print(
                    f"[A153-LINEAR-PATH-PASS] source={source}; exact={exact}; "
                    f"full board/affine/XYZ/waypoint validation passed; {path_reason}"
                )
            else:
                print(
                    f"[A153-SOFT-WS-PASS] source={source}; private workspace overlap accepted only for pose rotation; "
                    f"{path_reason}; reasons={candidate.get('soft_workspace_reasons',[])}"
                )
            return candidate

    def _a156_optimize_small_mid_rotation_plan(plan: Optional[Dict[str, Any]], min_action_deg: float) -> Optional[Dict[str, Any]]:
        """Deprecated compatibility stub.

        v6 independent ROTATE never re-grips or rescales a legacy arc/MID plan.
        Kept only so older internal call sites, if any are reintroduced accidentally,
        cannot mutate the exact ROTATE_PULL/ROTATE_SHEAR geometry.
        """
        if isinstance(plan, dict):
            exact = str(plan.get("rotation_motion_exact_action", "")).upper()
            if exact and exact not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                print(f"[A156-DEPRECATED-NOOP] refusing legacy rotation optimization exact={exact}")
        return plan

    def _a157_next_workspace_grip_alternative(plan: Optional[Dict[str, Any]], reason: str) -> Optional[Dict[str, Any]]:
            """Promote one already private-zone alternative and run the full A153 preflight.

            Used only after a grip-arrival timeout.  It does not move the garment before
            rotation and does not use fallback_color/fallback_bgdiff geometry.
            """
            if isinstance(plan, dict) and str(plan.get("rotation_motion_exact_action", "")) in {"ROTATE_SHEAR", "ROTATE_PULL"}:
                print(f"[A157-GRIP-RETRY-NONE] linear ROTATE uses fresh rejudge instead of arc-alternative retry: {reason}")
                return None
            if not isinstance(plan, dict):
                return None
            alternatives = list(plan.get("workspace_grip_alternatives", []) or [])
            if not alternatives:
                print(f"[A157-GRIP-RETRY-NONE] no private-zone alternate grip pair: {reason}")
                return None
            try:
                center = np.asarray(plan.get("center_board_xy"), dtype=np.float32).reshape(2)
                delta = float(plan.get("action_delta_deg", 0.0))
            except Exception as exc:
                print(f"[A157-GRIP-RETRY-BLOCKED] invalid plan geometry: {repr(exc)}")
                return None

            def _rotate(p: np.ndarray) -> np.ndarray:
                th = float(np.radians(delta))
                R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]], dtype=np.float32)
                return center + R @ (p - center)

            for idx, alt in enumerate(alternatives):
                try:
                    p2 = np.asarray(alt.get("arm2_board_xy"), dtype=np.float32).reshape(2)
                    p1 = np.asarray(alt.get("arm1_board_xy"), dtype=np.float32).reshape(2)
                except Exception:
                    continue
                if select_arm_for_board_x(cfg, float(p2[0])) != "arm2" or select_arm_for_board_x(cfg, float(p1[0])) != "arm1":
                    continue
                candidate = copy.deepcopy(plan)
                for key in ("_pose_slack_geometry", "_a153_prevalidated_waypoints", "soft_workspace_validation_detail"):
                    candidate.pop(key, None)
                candidate["workspace_grip_alternatives"] = alternatives[idx + 1:]
                candidate["targets"]["arm2"]["orig_board_xy"] = [float(p2[0]), float(p2[1])]
                candidate["targets"]["arm1"]["orig_board_xy"] = [float(p1[0]), float(p1[1])]
                r2, r1 = _rotate(p2), _rotate(p1)
                candidate["targets"]["arm2"]["rotated_board_xy"] = [float(r2[0]), float(r2[1])]
                candidate["targets"]["arm1"]["rotated_board_xy"] = [float(r1[0]), float(r1[1])]
                candidate["targets"]["arm2"]["source"] = str(alt.get("arm2_source", "A157_GRIP_RETRY"))
                candidate["targets"]["arm1"]["source"] = str(alt.get("arm1_source", "A157_GRIP_RETRY"))
                candidate["ready"] = True
                candidate["done"] = False
                candidate["soft_workspace_candidate"] = True
                candidate["soft_workspace_validated"] = False
                candidate["workspace_validation_mode"] = "pending_dynamic_overlap"
                candidate["soft_workspace_reasons"] = [f"A157 alternate private grip after {reason}"]
                candidate["grip_selection_reason"] = f"A157 arrival retry alternative {idx + 1}"
                candidate["status"] = (f"POSE ROT A157 ALT-GRIP A2=({p2[0]:.0f},{p2[1]:.0f}) "
                                       f"A1=({p1[0]:.0f},{p1[1]:.0f}) action={delta:+.1f}")
                candidate = _a153_prepare_pose_rotation_plan(candidate, source=f"A157 grip-arrival retry {idx + 1}")
                if isinstance(candidate, dict) and bool(candidate.get("ready", False)):
                    print(f"[A157-GRIP-RETRY-PASS] selected alternate {idx + 1}: "
                          f"A2=({p2[0]:.1f},{p2[1]:.1f}) A1=({p1[0]:.1f},{p1[1]:.1f})")
                    return candidate
            print(f"[A157-GRIP-RETRY-NONE] alternate pairs failed full path validation: {reason}")
            return None

    def _a156_pose_feedback_pair(timeout_s: float) -> Dict[str, Optional[Dict[str, Any]]]:
            result: Dict[str, Optional[Dict[str, Any]]] = {"arm2": None, "arm1": None}
            threads = []
            for key in ("arm2", "arm1"):
                arm = arms.get(key)
                if arm is None:
                    continue
                def _read(k=key, a=arm):
                    try:
                        result[k] = a.feedback(timeout=max(0.10, float(timeout_s)))
                    except Exception as exc:
                        print(f"[A156-POSE-ARRIVAL-FEEDBACK-ERROR] {k.upper()}: {repr(exc)}")
                threads.append(threading.Thread(target=_read, daemon=True))
            for th in threads: th.start()
            for th in threads: th.join()
            return result

    def _a156_wait_pose_pair_arrival(targets: Dict[str, Dict[str, float]], label: str) -> bool:
            if not bool(getattr(args, "pose_rotate_arrival_barrier", True)) or not send_enabled:
                return True
            timeout_s = max(0.5, float(getattr(args, "pose_rotate_arrival_timeout_s", 8.0)))
            xy_tol = max(1.0, float(getattr(args, "pose_rotate_arrival_xy_tolerance_mm", 25.0)))
            z_tol = max(1.0, float(getattr(args, "pose_rotate_arrival_z_tolerance_mm", 20.0)))
            need = max(1, int(getattr(args, "pose_rotate_arrival_consecutive_samples", 2)))
            poll = max(0.0, float(getattr(args, "pose_rotate_arrival_poll_interval_s", 0.15)))
            fb_timeout = max(0.10, float(getattr(args, "pose_rotate_arrival_feedback_timeout_s", 0.80)))
            soft_enabled = bool(getattr(args, "pose_rotate_waypoint_soft_pass_enable", True)) and str(label).startswith("WAYPOINT-")
            soft_max_xy = max(xy_tol, float(getattr(args, "pose_rotate_waypoint_soft_pass_max_xy_mm", 30.0)))
            stall_window = max(2, int(getattr(args, "pose_rotate_waypoint_soft_pass_stall_window", 4)))
            stall_delta = max(0.1, float(getattr(args, "pose_rotate_waypoint_soft_pass_stall_delta_mm", 2.0)))
            history: Dict[str, List[Tuple[float, float]]] = {"arm2": [], "arm1": []}
            soft_seen: Dict[str, float] = {}
            started = time.monotonic(); stable = 0; sample = 0
            print(
                f"[A156-POSE-ARRIVAL-BARRIER] label={label} timeout={timeout_s:.1f}s "
                f"xy_tol={xy_tol:.1f} z_tol={z_tol:.1f} stable={need}"
                + (f" waypoint_soft={xy_tol:.1f}..{soft_max_xy:.1f}mm stalled_window={stall_window}" if soft_enabled else "")
            )
            while time.monotonic() - started <= timeout_s:
                sample += 1
                fb = _a156_pose_feedback_pair(fb_timeout)
                oks = []
                parts = []
                sample_soft: Dict[str, float] = {}
                for key in ("arm2", "arm1"):
                    t = targets.get(key) if isinstance(targets, dict) else None
                    f = fb.get(key)
                    ok = False; xy = float('inf'); ze = float('inf'); soft_ok = False; span = float('inf')
                    if isinstance(t, dict) and isinstance(f, dict):
                        try:
                            fx, fy, fz = float(f['x']), float(f['y']), float(f['z'])
                            xy = float(math.hypot(fx-float(t['rx']), fy-float(t['ry'])))
                            ze = abs(fz-float(t['rz']))
                            hist = history[key]
                            hist.append((fx, fy))
                            if len(hist) > stall_window:
                                del hist[:-stall_window]
                            normal_ok = bool(xy <= xy_tol and ze <= z_tol)
                            if (soft_enabled and (xy_tol < xy <= soft_max_xy) and ze <= z_tol
                                    and len(hist) >= stall_window):
                                last = np.asarray(hist[-1], dtype=np.float32)
                                span = max(float(np.linalg.norm(np.asarray(p, dtype=np.float32) - last)) for p in hist)
                                soft_ok = bool(span <= stall_delta)
                            ok = bool(normal_ok or soft_ok)
                            if soft_ok:
                                sample_soft[key] = float(xy)
                        except Exception:
                            pass
                    oks.append(ok)
                    soft_tag = f" soft={soft_ok} stall_span={span:.1f}" if soft_enabled else ""
                    parts.append(f"{key.upper()} xy={xy:.1f} z={ze:.1f} ok={ok}{soft_tag}")
                stable = stable + 1 if all(oks) else 0
                if all(oks) and sample_soft:
                    soft_seen.update(sample_soft)
                print(f"[A156-POSE-ARRIVAL-SAMPLE] {label} n={sample} {' | '.join(parts)} stable={stable}/{need}")
                if stable >= need:
                    if soft_seen:
                        event = {
                            "stage": str(label),
                            "arms": sorted(soft_seen.keys()),
                            "xy_error_mm": {k: float(v) for k, v in soft_seen.items()},
                            "normal_xy_tolerance_mm": float(xy_tol),
                            "soft_max_xy_mm": float(soft_max_xy),
                            "stall_window": int(stall_window),
                            "stall_delta_mm": float(stall_delta),
                        }
                        pose_rotate_arrival_soft_pass_events.append(copy.deepcopy(event))
                        pass
                        print(
                            f"[A156-POSE-WAYPOINT-SOFT-PASS] label={label} arms={event['arms']} "
                            f"xy={event['xy_error_mm']} normal_tol={xy_tol:.1f} soft_max={soft_max_xy:.1f}"
                        )
                    print(f"[A156-POSE-ARRIVAL-PASS] label={label} elapsed={time.monotonic()-started:.2f}s")
                    return True
                time.sleep(poll)
            print(f"[A156-POSE-ARRIVAL-TIMEOUT] label={label}; later rotation motion suppressed")
            return False

    def _motion_v20_recover_pose_post_grip_failure(xyz: Dict[str, Dict[str, Dict[str, float]]],
                                                     pose_open_angle: float,
                                                     failure_stage: str) -> bool:
            """Generic safety recovery for every ROTATE failure after close-at-grip begins.

            The failed action remains a failure. Recovery is complete only after:
            FULL-OPEN -> fresh T:105 -> vertical clear at each arm's ACTUAL current XY
            -> confirmed camera-clear standby. No planned old grip/waypoint XY is reused.
            """
            enabled = bool(getattr(
                args, "pose_rotate_post_grip_auto_recovery",
                getattr(args, "pose_rotate_lift_failure_auto_recovery", True),
            ))
            if not enabled:
                print(f"[POSE-ROT-POST-GRIP-RECOVERY-DISABLED] stage={failure_stage}; '.' acknowledgement required")
                return False

            print(
                f"[POSE-ROT-POST-GRIP-RECOVERY] stage={failure_stage}; "
                "FULL-OPEN -> T:105 actual-current-XY vertical clear -> confirmed standby"
            )
            open_ok = bool(pose_rotation_gripper(
                float(pose_open_angle),
                "POSE-ROT-FULL-OPEN-AFTER-POST-GRIP-FAIL",
                repeat=max(1, int(getattr(args, "pose_rotate_open_repeat", 1))),
                wait_after=0.15,
            ))
            if open_ok:
                _a140_note_release("POSE-ROT-FULL-OPEN-AFTER-POST-GRIP-FAIL")
            else:
                print("[POSE-ROT-POST-GRIP-RECOVERY-OPEN-FAILED] full-open command failed")

            clear_targets: Dict[str, Dict[str, float]] = {}
            feedback_ok = False
            if open_ok:
                fb = _a156_pose_feedback_pair(max(0.20, float(getattr(args, "pose_rotate_arrival_feedback_timeout_s", 0.80))))
                feedback_ok = True
                for key in ("arm2", "arm1"):
                    f = fb.get(key)
                    hover = ((xyz.get(key) or {}).get("hover") if isinstance(xyz, dict) else None)
                    if not isinstance(f, dict) or not isinstance(hover, dict):
                        feedback_ok = False
                        print(f"[POSE-ROT-POST-GRIP-RECOVERY-FEEDBACK-MISSING] {key.upper()}")
                        continue
                    try:
                        rx, ry = float(f['x']), float(f['y'])
                        rz = float(hover['rz'])
                        if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
                            raise ValueError(f"actual-current-XY clear target outside XYZ safety: ({rx:.1f},{ry:.1f},{rz:.1f})")
                        clear_targets[key] = {"rx": rx, "ry": ry, "rz": rz}
                        print(
                            f"[POSE-ROT-POST-GRIP-RECOVERY-TARGET] {key.upper()} "
                            f"actual=({rx:.1f},{ry:.1f},{float(f['z']):.1f}) -> vertical_clear_z={rz:.1f}"
                        )
                    except Exception as exc:
                        feedback_ok = False
                        print(f"[POSE-ROT-POST-GRIP-RECOVERY-TARGET-BLOCK] {key.upper()}: {exc}")
                feedback_ok = bool(feedback_ok and len(clear_targets) == 2)

            clear_cmd_ok = False
            clear_arrival_ok = False
            if open_ok and feedback_ok:
                clear_cmd_ok = bool(parallel_move_targets(
                    clear_targets,
                    "POSE-ROT-VERTICAL-RETRACT-POST-GRIP-FAIL",
                    float(pose_open_angle),
                    wait_after=0.15,
                    speed=vertical_retract_spd,
                    allow_after_error=True,
                ))
                if clear_cmd_ok:
                    clear_arrival_ok = bool(_a156_wait_pose_pair_arrival(
                        clear_targets, "POST-GRIP-RECOVERY-CLEAR"
                    ))
                if clear_arrival_ok:
                    _a140_note_vertical_clear("POSE-ROT-VERTICAL-RETRACT-POST-GRIP-FAIL")
                else:
                    print(
                        "[POSE-ROT-POST-GRIP-RECOVERY-CLEAR-FAILED] "
                        f"command_ok={clear_cmd_ok} arrival_ok={clear_arrival_ok}"
                    )

            standby_ok = False
            if open_ok and clear_arrival_ok and args.imaging_standby and not args.no_standby:
                standby_ok = bool(move_arms_to_standby(
                    reason=f"vla_0822 ROTATE {failure_stage} automatic recovery"
                ))
            elif open_ok and clear_arrival_ok:
                print(
                    "[POSE-ROT-POST-GRIP-RECOVERY-STANDBY-BLOCKED] "
                    "imaging standby is disabled; recovery envelope cannot be certified"
                )

            complete = bool(open_ok and feedback_ok and clear_arrival_ok and standby_ok)
            pass
            if complete:
                print(
                    "[POSE-ROT-POST-GRIP-RECOVERY-COMPLETE] failed ROTATE safely released/cleared/standby-confirmed; "
                    "'.' acknowledgement not required"
                )
            else:
                print(
                    "[POSE-ROT-POST-GRIP-RECOVERY-INCOMPLETE] "
                    f"open={open_ok} feedback={feedback_ok} clear={clear_arrival_ok} standby={standby_ok}; "
                    "manual safety check + '.' acknowledgement required"
                )
            return complete

    def _motion_v20_fail_pose_post_grip(xyz: Dict[str, Dict[str, Dict[str, float]]],
                                         pose_open_angle: float,
                                         failure_stage: str, reason: str) -> bool:
            recovered = _motion_v20_recover_pose_post_grip_failure(xyz, pose_open_angle, failure_stage)
            if not recovered:
                _a140_require_physical_recovery(
                    f"{reason}; automatic post-grip release/actual-XY-clear/standby recovery did not complete"
                )
            return False

    def pose_rotation_correct_once(reset_after_motion: bool = True, allow_grip_arrival_retry: bool = True) -> bool:
            nonlocal latest_pose_rotation_plan
            pose_rotate_arrival_soft_pass_events.clear()
            plan = latest_pose_rotation_plan
            if not isinstance(plan, dict):
                print(f"[POSE-ROT] No pose rotation plan. Press M for snapshot, or press 5 to recompute pose on current view. status={latest_pose_rotation_status}")
                return False

            # executor-level semantic gate. This duplicates the AUTO-X
            # decision guard intentionally so manual key-6 / human ROTATE override
            # cannot bypass the 160mm neck->waist trust requirement.
            _rot_source = str(plan.get("pose_inference_source", "UNKNOWN") or "UNKNOWN").upper()
            _rot_axis_len = float(plan.get("axis_len_board_mm", 0.0) or 0.0)
            _rot_sem_gate = max(0.0, float(getattr(args, "pose_rotate_semantic_axis_gate_mm", 160.0)))
            if (_rot_source in {"ARUCO_ROI_PRIMARY", "FULL_FRAME_FALLBACK", "LAST_VALID_POSE_CACHE"}
                    and _rot_axis_len < _rot_sem_gate):
                print(
                    f"[POSE-ROT-SEMANTIC-AXIS-BLOCK] source={_rot_source} "
                    f"neck-waist={_rot_axis_len:.1f}mm < {_rot_sem_gate:.1f}mm; Robot motion: NONE"
                )
                return False

            pass
            if plan.get("done"):
                print(f"[POSE-ROT] Already within deadband. No motion. {plan.get('status')}")
                return False
            exact_action = str(plan.get("rotation_motion_exact_action") or "").upper()
            if exact_action not in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                print(
                    f"[POSE-ROT-LEGACY-ARC-DISABLED] executor rejected exact={exact_action or 'NONE'}; "
                    "only ROTATE_PULL/ROTATE_SHEAR may move the robot. Robot motion: NONE"
                )
                return False
            if not plan.get("ready"):
                print(f"[POSE-ROT-BLOCKED] plan is not ready: {plan.get('ready_reason')} | {plan.get('status')}")
                return False
            pair_ok, pair_code, pair_detail = _pose_rotation_initial_pair_check(plan, source="pre-motion executor")
            if not pair_ok:
                print(f"[POSE-ROT] blocked before motion: code={pair_code} detail={pair_detail}")
                return False
            if _pose_rotation_soft_workspace_active(plan) and not bool(plan.get("soft_workspace_validated", False)):
                print("[A153-POSE-ROT-PREFLIGHT-BLOCK] soft-workspace plan was not promoted by complete dynamic validation; Robot motion: NONE")
                return False
            xyz = resolve_pose_rotation_xyz(plan)
            if xyz is None:
                return False
            # validate the entire distance-locked lifted path before either
            # gripper descends.  A late geometry failure must never occur after grip.
            prevalidated_waypoints = plan.get("_a153_prevalidated_waypoints") if isinstance(plan.get("_a153_prevalidated_waypoints"), list) else None
            if prevalidated_waypoints is None:
                prevalidated_waypoints = build_pose_rotation_step_waypoints_xyz(plan)
            if prevalidated_waypoints is None or (bool(getattr(args, "pose_rotate_stepwise_move", True)) and not prevalidated_waypoints):
                print("[A152-POSE-ROT-PREFLIGHT-BLOCK] no valid distance-locked rotation path; Robot motion: NONE")
                return False
            print("\n========== POSE ROTATION CORRECTION ==========")
            print(f"angle current={plan.get('current_axis_deg'):+.1f} deg, target={plan.get('target_axis_deg'):+.1f} deg, "
                  f"need={plan.get('delta_full_deg'):+.1f} deg, action={plan.get('action_delta_deg'):+.1f} deg")
            geom = plan.get("_pose_slack_geometry") if isinstance(plan, dict) else None
            for arm_key in ("arm2", "arm1"):
                td = plan["targets"][arm_key]
                ob = td["orig_board_xy"]
                rb = td["rotated_board_xy"]
                if isinstance(geom, dict):
                    prefix = "arm2" if arm_key == "arm2" else "arm1"
                    sb = geom.get(f"{prefix}_slack_board_xy", ob)
                    fb = geom.get(f"{prefix}_final_board_xy", rb)
                    print(f"{arm_key.upper()}: board grip=({ob[0]:.1f},{ob[1]:.1f}) -> slack=({sb[0]:.1f},{sb[1]:.1f}) -> place=({fb[0]:.1f},{fb[1]:.1f})")
                else:
                    print(f"{arm_key.upper()}: board grip=({ob[0]:.1f},{ob[1]:.1f}) -> rotated=({rb[0]:.1f},{rb[1]:.1f})")
            if isinstance(geom, dict):
                print(f"Pre-slack: requested={geom.get('requested_mm', 0.0):.1f}mm, effective={geom.get('effective_mm', 0.0):.1f}mm/arm, "
                      f"restore_ratio={geom.get('restore_ratio', 0.0):.2f}, pair {geom.get('pair_start_mm', 0.0):.1f} -> "
                      f"{geom.get('pair_slack_mm', 0.0):.1f} -> {geom.get('pair_final_mm', 0.0):.1f}mm")
            print(f"Rotation segment speed: {float(getattr(args, 'pose_rotate_rotation_speed', spd_default)):.2f} "
                  f"(normal={float(spd_default):.2f}, fast_free={float(getattr(args, 'pose_rotate_fast_free_speed', spd_default)):.2f}, "
                  f"near_cloth={float(getattr(args, 'pose_rotate_near_cloth_speed', spd_default)):.2f}, "
                  f"vertical_retract={float(getattr(args, 'pose_rotate_vertical_retract_speed', spd_default)):.2f})")
            if args.pose_rotate_hover_only:
                print("Mode: HOVER ONLY. This is the safe first test. Re-run with --no-pose-rotate-hover-only for actual grip/rotate/place.")
            else:
                print("Mode: ACTUAL grip -> lift -> rotate -> place/open/retract. Keep emergency stop ready.")
            print("================================================\n")

            if not send_enabled:
                print("[DRY-RUN] Pose rotation commands not sent; frozen plan passed A152 rotation preflight.")
                return True

            for arm_key in ("arm2", "arm1"):
                arm_obj = arms.get(arm_key)
                if arm_obj is not None:
                    arm_obj.torque_on()
            pose_open_angle = float(getattr(args, "pose_rotate_open_angle", args.grip_open))
            pose_hold_angle = float(args.grip_hold)

            fast_free_spd = float(getattr(args, "pose_rotate_fast_free_speed", spd_default))
            near_cloth_spd = float(getattr(args, "pose_rotate_near_cloth_speed", spd_default))
            vertical_retract_spd = float(getattr(args, "pose_rotate_vertical_retract_speed", spd_default))
            if (not bool(getattr(args, "pose_rotate_fast_free_move", True))) or (not np.isfinite(fast_free_spd)) or fast_free_spd <= 0:
                fast_free_spd = float(spd_default)
            if (not np.isfinite(near_cloth_spd)) or near_cloth_spd <= 0:
                near_cloth_spd = float(spd_default)
            if (not np.isfinite(vertical_retract_spd)) or vertical_retract_spd <= 0:
                vertical_retract_spd = float(spd_default)
            pose_grip_down_wait = max(0.0, float(getattr(args, "pose_rotate_grip_down_wait", args.grip_down_wait)))
            pose_grip_open_wait = max(0.0, float(getattr(args, "pose_rotate_grip_open_wait", args.grip_open_wait)))
            pose_grip_contact_wait = max(0.0, float(getattr(args, "pose_rotate_grip_contact_wait", args.grip_contact_wait)))
            pose_grip_close_wait = max(0.0, float(getattr(args, "pose_rotate_grip_close_wait", args.grip_close_wait)))
            pose_grip_close_settle = max(0.0, float(getattr(args, "pose_rotate_grip_close_settle", args.grip_close_settle)))
            pose_hold_after_grip_wait = max(0.0, float(getattr(args, "pose_rotate_hold_after_grip_wait", 0.12)))

            # the final release is NOT a raw servo angle by default.
            # On this RoArm gripper, smaller T:106 command values open the gripper more.
            # The old step_b17 default used 0.785rad, which physically opened the gripper
            # wider, not 45deg. Here we compute "open 45deg from hold/closed":
            #     raw_cmd = grip_hold - radians(45)  ~= 3.15 - 0.785 = 2.36rad
            raw_release_override = getattr(args, "pose_rotate_release_open_angle", None)
            if raw_release_override is not None:
                pose_release_open_angle = float(raw_release_override)
                release_desc = "raw override"
            else:
                release_open_deg = float(getattr(args, "pose_rotate_release_open_deg", 45.0))
                if not np.isfinite(release_open_deg):
                    release_open_deg = 45.0
                release_open_deg = max(0.0, min(120.0, release_open_deg))
                pose_release_open_angle = float(pose_hold_angle - np.deg2rad(release_open_deg))
                lower = min(float(pose_open_angle), float(pose_hold_angle))
                upper = max(float(pose_open_angle), float(pose_hold_angle))
                pose_release_open_angle = max(lower, min(upper, pose_release_open_angle))
                release_desc = f"{release_open_deg:.1f}deg open from hold"

            print(f"[POSE-ROT] open before approach: T:106 angle={pose_open_angle:.3f} rad ({np.degrees(pose_open_angle):.1f} deg). Approach/down T:104 t also stays OPEN; close is sent only after grip-down is complete.")
            print(f"[POSE-ROT] release after place: {release_desc} -> T:106 cmd={pose_release_open_angle:.3f} rad ({np.degrees(pose_release_open_angle):.1f} servo-deg).")
            if not pose_rotation_gripper(pose_open_angle, "POSE-ROT-OPEN",
                                             repeat=max(1, int(getattr(args, "pose_rotate_open_repeat", 1))), wait_after=0.20):
                print("[A152-POSE-ROT-OPEN-FAILED] pre-approach full-open command failed")
                return False

            # Keep the gripper open while moving to hover.  On this RoArm setup, the
            # T:104 "t" field affects the gripper/tool state, so using args.t here can
            # make the gripper close during the approach.  Use pose_open_angle until
            # the z-down motion is fully finished.
            if not parallel_move_targets({"arm2": xyz["arm2"]["hover"], "arm1": xyz["arm1"]["hover"]},
                                             "POSE-ROT-HOVER-OPEN", pose_open_angle, wait_after=0.30, speed=fast_free_spd):
                print("[A152-POSE-ROT-HOVER-FAILED] both-arm hover command failed")
                return False
            if args.pose_rotate_hover_only:
                print("[POSE-ROT] Hover-only finished. Check both grippers are above the intended sleeve/side points.")
                return False

            # Descend to the actual grip target with the gripper still OPEN. Do not
            # send close until this z-down command and its wait have finished.
            if not parallel_move_targets({"arm2": xyz["arm2"]["grip"], "arm1": xyz["arm1"]["grip"]},
                                             "POSE-ROT-GRIP-DOWN-OPEN", pose_open_angle, wait_after=pose_grip_down_wait, speed=near_cloth_spd):
                print("[A152-POSE-ROT-GRIP-DOWN-FAILED] both-arm open descent command failed")
                return False
            if not _a156_wait_pose_pair_arrival({"arm2": xyz["arm2"]["grip"], "arm1": xyz["arm1"]["grip"]}, "GRIP-DOWN-OPEN"):
                pose_rotation_gripper(pose_open_angle, "POSE-ROT-OPEN-AFTER-GRIP-ARRIVAL-TIMEOUT", repeat=1, wait_after=0.10)
                parallel_move_targets({"arm2": xyz["arm2"]["hover"], "arm1": xyz["arm1"]["hover"]},
                                      "POSE-ROT-VERTICAL-RETRACT-ABORT-OPEN", pose_open_angle, wait_after=0.15, speed=vertical_retract_spd)
                _a140_note_release("POSE-ROT-OPEN-AFTER-GRIP-ARRIVAL-TIMEOUT")
                if args.imaging_standby and not args.no_standby:
                    move_arms_to_standby(reason="after pose grip-arrival timeout")
                if bool(allow_grip_arrival_retry):
                    retry_plan = _a157_next_workspace_grip_alternative(plan, reason="grip arrival timeout")
                    if isinstance(retry_plan, dict) and bool(retry_plan.get("ready", False)):
                        latest_pose_rotation_plan = retry_plan
                        print("[A157-GRIP-RETRY] retrying the complete approach exactly once with the next private-zone pair")
                        return pose_rotation_correct_once(reset_after_motion=reset_after_motion, allow_grip_arrival_retry=False)
                print("[A157-GRIP-RETRY-ABORT] no more grip retries; rotation cancelled without close/lift/waypoint motion")
                return False

            print(f"[POSE-ROT] reached grip target. Re-assert OPEN at grip point, wait {pose_grip_open_wait:.2f}s, then close.")
            if not pose_rotation_gripper(pose_open_angle, "POSE-ROT-OPEN-AT-GRIP",
                                             repeat=max(1, int(getattr(args, "pose_rotate_open_repeat", 1))),
                                             wait_after=pose_grip_open_wait):
                print("[A152-POSE-ROT-OPEN-AT-GRIP-FAILED] open reassertion failed")
                return False
            time.sleep(pose_grip_contact_wait)

            if not pose_rotation_gripper(float(args.grip_close), "POSE-ROT-CLOSE-AT-GRIP",
                                             repeat=max(1, int(getattr(args, "pose_rotate_close_repeat", args.grip_close_repeat))),
                                             wait_after=pose_grip_close_wait):
                print("[A152-POSE-ROT-CLOSE-FAILED] close-at-grip command failed")
                return _motion_v20_fail_pose_post_grip(
                    xyz, pose_open_angle, "CLOSE-AT-GRIP-COMMAND", "ROTATE close-at-grip command failed"
                )
            if abs(float(args.grip_hold) - float(args.grip_close)) > 1e-6:
                if not pose_rotation_gripper(pose_hold_angle, "POSE-ROT-HOLD-AFTER-GRIP", repeat=1, wait_after=pose_hold_after_grip_wait):
                    print("[A152-POSE-ROT-HOLD-FAILED] hold-angle command failed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "HOLD-AFTER-GRIP-COMMAND", "ROTATE hold-after-grip command failed"
                    )
            time.sleep(pose_grip_close_settle)

            print(
                "[A157-POSE-ROT-LIFT-Z] "
                f"ARM2 target_z={float(xyz['arm2']['lift']['rz']):.1f}mm "
                f"(extra={float(getattr(args, 'pose_rotate_arm2_lift_extra_mm', 0.0)):.1f}mm) | "
                f"ARM1 target_z={float(xyz['arm1']['lift']['rz']):.1f}mm "
                f"(default_extra={float(getattr(args, 'pose_rotate_lift_extra_mm', 20.0)):.1f}mm)"
            )
            if not parallel_move_targets({"arm2": xyz["arm2"]["lift"], "arm1": xyz["arm1"]["lift"]},
                                             "POSE-ROT-LIFT-HOLD", pose_hold_angle, wait_after=float(args.pose_rotate_wait), speed=near_cloth_spd):
                print("[A152-POSE-ROT-LIFT-FAILED] both-arm lift command failed; no rotation waypoint is issued")
                return _motion_v20_fail_pose_post_grip(
                    xyz, pose_open_angle, "LIFT-HOLD-COMMAND", "ROTATE LIFT-HOLD command failed"
                )
            if not _a156_wait_pose_pair_arrival({"arm2": xyz["arm2"]["lift"], "arm1": xyz["arm1"]["lift"]}, "LIFT-HOLD"):
                print("[A156-POSE-LIFT-ARRIVAL-BLOCK] cloth is held; no rotation waypoint is issued")
                return _motion_v20_fail_pose_post_grip(
                    xyz, pose_open_angle, "LIFT-HOLD-ARRIVAL", "ROTATE LIFT-HOLD arrival failed"
                )

            slack_geom = plan.get("_pose_slack_geometry") if isinstance(plan, dict) else None
            slack_eff = float(slack_geom.get("effective_mm", 0.0)) if isinstance(slack_geom, dict) else 0.0
            if slack_eff > 0.01:
                print(f"[POSE-SLACK] move inward before rotation: effective={slack_eff:.1f}mm/arm, "
                      f"pair_start={float(slack_geom.get('pair_start_mm', 0.0)):.1f}mm, "
                      f"pair_slack={float(slack_geom.get('pair_slack_mm', 0.0)):.1f}mm, "
                      f"restore_ratio={float(slack_geom.get('restore_ratio', 0.0)):.2f}")
                if not parallel_move_targets({"arm2": xyz["arm2"]["pre_slack_lift"], "arm1": xyz["arm1"]["pre_slack_lift"]},
                                                 "POSE-ROT-PRE-SLACK-LIFT-HOLD", pose_hold_angle,
                                                 wait_after=float(getattr(args, "pose_rotate_pre_slack_wait", 0.20)), speed=near_cloth_spd):
                    print("[A152-POSE-ROT-PRE-SLACK-FAILED] inward slack command failed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "PRE-SLACK-COMMAND", "ROTATE pre-slack command failed"
                    )
                if not _a156_wait_pose_pair_arrival({"arm2": xyz["arm2"]["pre_slack_lift"], "arm1": xyz["arm1"]["pre_slack_lift"]}, "PRE-SLACK-LIFT"):
                    print("[A156-POSE-PRE-SLACK-ARRIVAL-BLOCK] later rotation waypoints suppressed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "PRE-SLACK-ARRIVAL", "ROTATE pre-slack arrival failed"
                    )
            else:
                if str(plan.get("rotation_motion_exact_action", "")) in {"ROTATE_SHEAR", "ROTATE_PULL"}:
                    print(f"[POSE-ROT-LINEAR] {plan.get('rotation_motion_exact_action')}: pre-slack intentionally disabled; pull starts from lifted grip points.")
                else:
                    print("[POSE-SLACK] disabled or unsafe; rotate from original lifted grip points.")

            if bool(getattr(args, "pose_rotate_stepwise_move", True)):
                waypoints = prevalidated_waypoints
                for wp in waypoints:
                    i = int(wp["index"])
                    n = int(wp["count"])
                    l2 = float(wp.get("move_len_mm", {}).get("arm2", 0.0))
                    l1 = float(wp.get("move_len_mm", {}).get("arm1", 0.0))
                    d = float(wp.get("pair_dist_mm", 0.0))
                    if str(plan.get("rotation_motion_exact_action", "")) in {"ROTATE_PULL", "ROTATE_SHEAR"}:
                        print(
                            f"[POSE-ROT-LINEAR-STEP] exact={plan.get('rotation_motion_exact_action')} "
                            f"step={i}/{n} progress={float(wp.get('linear_progress', 0.0)):.2f} "
                            f"pair={d:.1f}mm move_len A2={l2:.1f}mm A1={l1:.1f}mm"
                        )
                    else:
                        print(f"[POSE-ROT-HISTORICAL-ARC-STEP] step {i}/{n}: delta={float(wp['delta_deg']):+.1f}deg "
                              f"pair={d:.1f}mm move_len A2={l2:.1f}mm A1={l1:.1f}mm")
                    if not parallel_move_targets_with_speed(wp["xyz"],
                                                                f"POSE-ROT-ROTATE-LIFT-HOLD-STEP-{i:02d}-OF-{n:02d}",
                                                                pose_hold_angle,
                                                                speed_map=wp.get("speed_map"),
                                                                wait_after=float(getattr(args, "pose_rotate_step_wait", 0.12))):
                        print(f"[A152-POSE-ROT-WAYPOINT-FAILED] step={i}/{n}; later waypoints suppressed")
                        return _motion_v20_fail_pose_post_grip(
                            xyz, pose_open_angle, f"WAYPOINT-{i:02d}-OF-{n:02d}-COMMAND",
                            f"ROTATE waypoint {i}/{n} command failed"
                        )
                    if not _a156_wait_pose_pair_arrival(wp["xyz"], f"WAYPOINT-{i:02d}-OF-{n:02d}"):
                        print(f"[A156-POSE-WAYPOINT-ARRIVAL-BLOCK] step={i}/{n}; later waypoints suppressed")
                        return _motion_v20_fail_pose_post_grip(
                            xyz, pose_open_angle, f"WAYPOINT-{i:02d}-OF-{n:02d}-ARRIVAL",
                            f"ROTATE waypoint {i}/{n} arrival failed"
                        )
            else:
                waypoints = prevalidated_waypoints
                rot_spd = float(getattr(args, "pose_rotate_rotation_speed", spd_default))
                if not np.isfinite(rot_spd) or rot_spd <= 0:
                    rot_spd = float(spd_default)
                if not parallel_move_targets_with_speed({"arm2": xyz["arm2"]["rotate_lift"], "arm1": xyz["arm1"]["rotate_lift"]},
                                                            "POSE-ROT-ROTATE-LIFT-HOLD", pose_hold_angle,
                                                            speed_map={"arm2": rot_spd, "arm1": rot_spd},
                                                            wait_after=float(args.pose_rotate_wait)):
                    print("[A152-POSE-ROT-SINGLE-MOVE-FAILED] rotation command failed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "SINGLE-ROTATE-COMMAND", "ROTATE single-move command failed"
                    )
            if args.pose_rotate_place_after:
                if not parallel_move_targets({"arm2": xyz["arm2"]["rotate_place"], "arm1": xyz["arm1"]["rotate_place"]},
                                                 "POSE-ROT-PLACE-HOLD", pose_hold_angle, wait_after=float(args.pose_rotate_wait), speed=near_cloth_spd):
                    print("[A152-POSE-ROT-PLACE-FAILED] both-arm place command failed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "PLACE-HOLD-COMMAND", "ROTATE place command failed"
                    )
                if not _a156_wait_pose_pair_arrival({"arm2": xyz["arm2"]["rotate_place"], "arm1": xyz["arm1"]["rotate_place"]}, "PLACE-HOLD"):
                    print("[A156-POSE-PLACE-ARRIVAL-BLOCK] release suppressed because both place targets were not confirmed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "PLACE-HOLD-ARRIVAL", "ROTATE place arrival failed"
                    )
                if not pose_rotation_gripper(pose_release_open_angle, "POSE-ROT-OPEN-AT-PLACE-PARTIAL",
                                             repeat=max(1, int(getattr(args, "pose_rotate_open_repeat", 1))), wait_after=float(args.place_open_wait)):
                    print("[A152-POSE-ROT-PARTIAL-RELEASE-FAILED] release command failed")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "PARTIAL-RELEASE-COMMAND", "ROTATE partial release command failed"
                    )
                # no horizontal release escape. After opening, lift straight up
                # at the same final board XY, then let move_arms_to_standby handle the
                # normal high-Z return to the standby position. This avoids dragging the
                # cloth sideways at low/place Z.
                if bool(getattr(args, "pose_rotate_vertical_retract_after_open", True)):
                    print("[POSE-ROT-RELEASE] partial release -> vertical retract at same XY -> full OPEN in air -> standby.")
                    clear_ok = bool(parallel_move_targets({"arm2": xyz["arm2"]["rotate_retract"], "arm1": xyz["arm1"]["rotate_retract"]},
                                                        "POSE-ROT-VERTICAL-RETRACT-OPEN-PARTIAL", pose_release_open_angle, wait_after=0.15, speed=vertical_retract_spd))
                    if not clear_ok:
                        print("[A152-POSE-ROT-CLEAR-FAILED] same-XY vertical clear command failed")
                        return _motion_v20_fail_pose_post_grip(
                            xyz, pose_open_angle, "POST-PLACE-VERTICAL-CLEAR", "ROTATE post-place vertical clear failed"
                        )
                    # The existing manual rotation uses a partial release at cloth level.
                    # AUTO-X safety auditing additionally requires a proven full-open
                    # command after the grippers are clear of the cloth.
                    full_open_ok = bool(pose_rotation_gripper(
                        pose_open_angle, "POSE-ROT-FULL-OPEN-AFTER-CLEAR",
                        repeat=max(1, int(getattr(args, "pose_rotate_open_repeat", 1))), wait_after=0.15,
                    ))
                    if not full_open_ok:
                        print("[A152-POSE-ROT-FULL-OPEN-FAILED] full-open command after clear failed")
                        return _motion_v20_fail_pose_post_grip(
                            xyz, pose_open_angle, "FULL-OPEN-AFTER-CLEAR", "ROTATE full-open after clear failed"
                        )
                    if auto_x_controller.state == "EXECUTING":
                        _a140_note_release("POSE-ROT-FULL-OPEN-AFTER-CLEAR")
                else:
                    print("[A152-POSE-ROT-BLOCKED] vertical retract is required for AUTO-X rotation safety")
                    return _motion_v20_fail_pose_post_grip(
                        xyz, pose_open_angle, "VERTICAL-RETRACT-DISABLED", "ROTATE vertical retract safety requirement disabled"
                    )
            else:
                print("[A152-POSE-ROT-BLOCKED] place-after is required for AUTO-X rotation safety")
                return _motion_v20_fail_pose_post_grip(
                    xyz, pose_open_angle, "PLACE-AFTER-DISABLED", "ROTATE place-after safety requirement disabled"
                )
            standby_ok = True
            if args.imaging_standby and not args.no_standby:
                standby_ok = bool(move_arms_to_standby(reason="after pose rotation"))
            if not standby_ok:
                print("[A152-POSE-ROT-STANDBY-FAILED] both-arm standby was not completed")
                return _motion_v20_fail_pose_post_grip(
                    xyz, pose_open_angle, "STANDBY", "ROTATE standby completion failed"
                )
            if reset_after_motion:
                reset_snapshot("pose rotation motion finished; waiting for fresh view")
            return True

    def pose_rotation_correct():
            nonlocal latest_pose_rotation_plan
            """Key 6 entry point.

            Hover-only mode remains a single safe hover preview. In actual mode, step_b15
            repeats fresh pose -> feasible rotation only. If the plan is BLOCKED because
            rotated targets are unsafe/cross-zone, mask validation failed, or the garment
            moved outside the marker area, key-6 stops immediately. It never calls the
            key-4 smart reposition / marker-fill / auto-center drag path automatically.
            Manual key 4 remains available.
            """
            if bool(args.pose_rotate_hover_only) or (not bool(getattr(args, "pose_auto_rotate", True))):
                pose_rotation_correct_once()
                return

            max_rounds = max(1, int(getattr(args, "pose_auto_rotate_max_rounds", 4)))
            fresh_timeout = max(0.5, float(getattr(args, "pose_auto_rotate_fresh_timeout", 10.0)))
            settle_s = max(0.0, float(getattr(args, "pose_auto_rotate_settle_s", 0.9)))
            # safety change: key-6 must never auto-run key-4/smart-reposition.
            # Keep the CLI flags for backward compatibility, but ignore them here.
            recenter_enabled = False
            recenter_max = 0
            recenter_used = 0

            def _pose_plan_feasible_for_motion(plan: Optional[Dict[str, Any]]) -> Tuple[bool, str]:
                if not isinstance(plan, dict):
                    return False, f"no pose plan: {latest_pose_rotation_status}"
                if bool(plan.get("done")):
                    return True, f"done: {plan.get('status')}"
                if not bool(plan.get("ready")):
                    rr = str(plan.get('ready_reason', ''))
                    mv = plan.get("mask_validation") if isinstance(plan, dict) else None
                    if isinstance(mv, dict) and ("pose-mask" in rr or "mask" in rr):
                        return False, f"validation blocked: {rr} | {plan.get('status')}"
                    return False, f"plan not ready: {rr} | {plan.get('status')}"
                if _pose_rotation_soft_workspace_active(plan) and not bool(plan.get("soft_workspace_validated", False)):
                    return False, "soft-workspace plan has not passed complete dynamic validation"
                if resolve_pose_rotation_xyz(plan) is None:
                    return False, "plan ready, but RoArm/board target resolution is blocked"
                return True, f"ready: {plan.get('status')}"

            def _pose_plan_motion_stats(plan: Optional[Dict[str, Any]]) -> Dict[str, float]:
                """Return simple board-space movement stats for deciding whether a late round is worth executing."""
                out = {"action_abs_deg": 0.0, "max_move_mm": 0.0, "arm1_move_mm": 0.0, "arm2_move_mm": 0.0}
                if not isinstance(plan, dict):
                    return out
                try:
                    out["action_abs_deg"] = abs(float(plan.get("action_delta_deg", 0.0)))
                except Exception:
                    out["action_abs_deg"] = 0.0
                try:
                    targets = plan.get("targets", {})
                    moves = []
                    for arm_key in ("arm2", "arm1"):
                        t = targets.get(arm_key, {}) if isinstance(targets, dict) else {}
                        ob = t.get("orig_board_xy")
                        rb = t.get("rotated_board_xy")
                        if ob is None or rb is None:
                            continue
                        d = float(np.linalg.norm(np.asarray(rb, dtype=np.float32) - np.asarray(ob, dtype=np.float32)))
                        if np.isfinite(d):
                            out[f"{arm_key}_move_mm"] = d
                            moves.append(d)
                    if moves:
                        out["max_move_mm"] = float(max(moves))
                except Exception:
                    pass
                return out

            def _should_skip_tiny_late_round(plan: Optional[Dict[str, Any]], round_idx: int) -> Tuple[bool, str]:
                if not bool(getattr(args, "pose_auto_rotate_skip_small_late_rounds", True)):
                    return False, ""
                start_round = max(2, int(getattr(args, "pose_auto_rotate_skip_small_from_round", 2)))
                if int(round_idx) < start_round:
                    return False, ""
                stats = _pose_plan_motion_stats(plan)
                min_action = max(0.0, float(getattr(args, "pose_auto_rotate_min_round_action_deg", 5.0)))
                min_move = max(0.0, float(getattr(args, "pose_auto_rotate_min_round_move_mm", 18.0)))
                action_abs = float(stats.get("action_abs_deg", 0.0))
                max_move = float(stats.get("max_move_mm", 0.0))
                too_small_action = min_action > 0.0 and action_abs < min_action
                too_small_move = min_move > 0.0 and max_move < min_move
                if too_small_action or too_small_move:
                    return True, (f"late tiny correction skipped: round={round_idx}, "
                                  f"action={action_abs:.1f}deg < {min_action:.1f}deg or "
                                  f"max_move={max_move:.1f}mm < {min_move:.1f}mm "
                                  f"(ARM2={float(stats.get('arm2_move_mm', 0.0)):.1f}, "
                                  f"ARM1={float(stats.get('arm1_move_mm', 0.0)):.1f})")
                return False, (f"late correction large enough: action={action_abs:.1f}deg, "
                               f"max_move={max_move:.1f}mm")

            def _should_skip_tiny_execute(plan: Optional[Dict[str, Any]], round_idx: int) -> Tuple[bool, str]:
                if not bool(getattr(args, "pose_rotate_skip_small_execute", True)):
                    return False, ""
                stats = _pose_plan_motion_stats(plan)
                min_action = max(0.0, float(getattr(args, "pose_rotate_min_execute_action_deg", 5.0)))
                min_move = max(0.0, float(getattr(args, "pose_rotate_min_execute_move_mm", 18.0)))
                action_abs = float(stats.get("action_abs_deg", 0.0))
                max_move = float(stats.get("max_move_mm", 0.0))
                too_small_action = min_action > 0.0 and action_abs < min_action
                too_small_move = min_move > 0.0 and max_move < min_move
                if too_small_action or too_small_move:
                    return True, (f"tiny pose rotation skipped: round={round_idx}, "
                                  f"action={action_abs:.1f}deg < {min_action:.1f}deg or "
                                  f"max_move={max_move:.1f}mm < {min_move:.1f}mm "
                                  f"(ARM2={float(stats.get('arm2_move_mm', 0.0)):.1f}, "
                                  f"ARM1={float(stats.get('arm1_move_mm', 0.0)):.1f})")
                return False, (f"pose rotation large enough: action={action_abs:.1f}deg, "
                               f"max_move={max_move:.1f}mm")

            def _single_recenter_then_fresh_pose(reason: str) -> Optional[Dict[str, Any]]:
                # Disabled on purpose in step_b15. Do not call marker_corner_fill_drag()
                # from key-6, because automatic pull-in/recenter was unstable.
                print(f"[POSE-AUTO-RECENTER-DISABLED] key-6 blocked, but auto smart reposition is removed: {reason}")
                return None

            def _print_pose_follow_diagnostics(before_plan: Dict[str, Any], after_plan: Dict[str, Any]) -> None:
                diag = compute_pose_follow_diagnostics(before_plan, after_plan)
                if not isinstance(diag, dict):
                    print("[POSE-FOLLOW] diagnostics unavailable: missing before/after pose keypoints")
                    return
                ratio_warn = float(getattr(args, "pose_rotate_follow_ratio_warn", 0.60))
                waist_warn = float(getattr(args, "pose_rotate_waist_goal_error_warn_mm", 55.0))
                bend_warn = float(getattr(args, "pose_rotate_side_bend_warn_mm", 45.0))
                waist_err = diag.get("waist_goal_error_mm")
                left_bend = diag.get("left_side_bend_after_mm")
                right_bend = diag.get("right_side_bend_after_mm")
                flags = []
                if float(diag.get("follow_ratio", 999.0)) < ratio_warn and float(diag.get("neck_move_mm", 0.0)) > 10.0:
                    flags.append("LOWER_FOLLOW_LOW")
                if waist_err is not None and float(waist_err) > waist_warn:
                    flags.append("WAIST_TARGET_LAG")
                if left_bend is not None and float(left_bend) > bend_warn:
                    flags.append("LEFT_SIDE_BENT")
                if right_bend is not None and float(right_bend) > bend_warn:
                    flags.append("RIGHT_SIDE_BENT")
                verdict = "OK" if not flags else "WARN " + ",".join(flags)
                print("\n========== POSE FOLLOW / TWIST DIAGNOSTICS ==========")
                print(f"axis before={diag['before_axis_deg']:+.1f}deg -> after={diag['after_axis_deg']:+.1f}deg, "
                      f"after_need={diag['after_need_deg']:+.1f}deg, action={diag['action_delta_deg']:+.1f}deg")
                print(f"move: neck={diag['neck_move_mm']:.1f}mm, waist={diag['waist_move_mm']:.1f}mm, "
                      f"follow_ratio={diag['follow_ratio']:.2f}  warn_if<{ratio_warn:.2f}")
                print(f"goal_error: neck={None if diag.get('neck_goal_error_mm') is None else round(float(diag['neck_goal_error_mm']), 1)}mm, "
                      f"waist={None if waist_err is None else round(float(waist_err), 1)}mm  warn_if_waist>{waist_warn:.1f}mm")
                print(f"side_bend_after: left={None if left_bend is None else round(float(left_bend), 1)}mm, "
                      f"right={None if right_bend is None else round(float(right_bend), 1)}mm  warn_if>{bend_warn:.1f}mm")
                print(f"verdict={verdict}")
                print("Interpretation: this is not shoulder/waist parallelism. It checks whether the lower waist points followed the commanded rotation and whether side lines are bent.")
                print("=====================================================\n")

            print("\n========== POSE AUTO ROTATION LOOP (6) ==========")
            print(f"max_rounds={max_rounds}, deadband={float(args.pose_rotate_deadband_deg):.1f}deg, "
                  f"max_delta={float(args.pose_rotate_max_delta_deg):.1f}deg, gain={float(args.pose_rotate_gain):.2f}")
            print(f"Adaptive recenter: enabled={recenter_enabled}, max_single_drags={recenter_max}  [step_b16 hard-disabled]")
            print("Each round: fresh pose -> rotate only when feasible. If BLOCKED, stop without smart reposition/key-4 drag.")
            print(f"Late-round tiny corrections: skip from round {int(getattr(args, 'pose_auto_rotate_skip_small_from_round', 2))} "
                  f"if action<{float(getattr(args, 'pose_auto_rotate_min_round_action_deg', 10.0)):.1f}deg "
                  f"or move<{float(getattr(args, 'pose_auto_rotate_min_round_move_mm', 35.0)):.1f}mm")
            print("Keep emergency power cutoff ready.")
            print("=================================================\n")

            for round_idx in range(1, max_rounds + 1):
                print(f"\n[POSE-AUTO] round {round_idx}/{max_rounds}")
                plan = latest_pose_rotation_plan
                use_existing_fresh = False
                if isinstance(plan, dict):
                    use_existing_fresh = bool(plan.pop("_fresh_after_pose_rotation", False))
                if isinstance(plan, dict) and (round_idx == 1 or use_existing_fresh):
                    src = "current displayed" if round_idx == 1 else "fresh post-check"
                    print(f"[POSE-AUTO] using {src} pose plan first: {plan.get('status')}")
                else:
                    plan = request_fresh_pose_rotation_plan_and_wait(
                        reason=f"pose auto round {round_idx}",
                        timeout=fresh_timeout,
                    )

                # no adaptive recenter/key-4. This loop only checks feasibility.
                # If the only issue is unsafe/cross-zone grip targets, it may retry by
                # gripping slightly inward toward the garment center. That does not move
                # the garment before rotation.
                while True:
                    feasible, why = _pose_plan_feasible_for_motion(plan)
                    if feasible:
                        print(f"[POSE-AUTO] feasibility OK: {why}")
                        latest_pose_rotation_plan = plan
                        break

                    print(f"[POSE-AUTO-BLOCKED] {why}")
                    retry_plan = maybe_apply_inward_grip_retry(plan, reason=why)
                    if isinstance(retry_plan, dict) and retry_plan is not plan:
                        plan = retry_plan
                        latest_pose_rotation_plan = plan
                        print("[POSE-AUTO] retrying feasibility with inward grip points.")
                        continue

                    if str(getattr(args, "pose_invalid_fallback_action", "center")).lower() == "none" and "validation blocked" in str(why):
                        print("[POSE-AUTO] stop: pose/mask validation failed and fallback action is none. Press key 3 to save this failure scene if needed.")
                        plan = None
                        break
                    print("[POSE-AUTO] stop: rotation is BLOCKED. step_b16 does not auto-run smart reposition/key-4 drag.")
                    print("[POSE-AUTO] Use manual key 4 only if you intentionally want to pull/recenter the garment.")
                    plan = None
                    break

                if not isinstance(plan, dict):
                    break
                if bool(plan.get("done")):
                    break

                skip_exec, exec_reason = _should_skip_tiny_execute(plan, round_idx)
                if skip_exec:
                    print(f"[POSE-AUTO-SKIP] {exec_reason}")
                    print("[POSE-AUTO-SKIP] Stop auto loop without executing a tiny motion. Press 5 for preview or 6 again if you intentionally want micro-correction.")
                    latest_pose_rotation_plan = plan
                    break
                elif exec_reason:
                    print(f"[POSE-AUTO] {exec_reason}")

                skip_tiny, skip_reason = _should_skip_tiny_late_round(plan, round_idx)
                if skip_tiny:
                    print(f"[POSE-AUTO-SKIP] {skip_reason}")
                    print("[POSE-AUTO-SKIP] Stop auto loop without executing another short motion. Press 5 for preview or 6 again if you still want more correction.")
                    latest_pose_rotation_plan = plan
                    break
                elif skip_reason:
                    print(f"[POSE-AUTO] {skip_reason}")

                before_motion_plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else plan
                # In auto mode, suppress the internal reset_snapshot() in pose_rotation_correct_once().
                # The optional diagnostics below will request exactly one fresh post-check after the
                # arms have completed release, vertical retract, and standby.
                pose_rotation_correct_once(reset_after_motion=False)

                post_diag_plan = None
                did_single_post_check = False
                if (not bool(args.pose_rotate_hover_only)) and bool(getattr(args, "pose_rotate_follow_diagnostics", True)):
                    diag_timeout = max(0.5, float(getattr(args, "pose_rotate_follow_diagnostic_timeout", fresh_timeout)))
                    post_diag_plan = request_fresh_pose_rotation_plan_and_wait(
                        reason=f"pose follow diagnostics after round {round_idx}",
                        timeout=diag_timeout,
                    )
                    did_single_post_check = True
                    if isinstance(post_diag_plan, dict):
                        _print_pose_follow_diagnostics(before_motion_plan, post_diag_plan)
                        post_diag_plan["_fresh_after_pose_rotation"] = True
                        latest_pose_rotation_plan = post_diag_plan
                        if bool(post_diag_plan.get("done")):
                            print("[POSE-AUTO] post-check says rotation is within deadband. Stop without another fresh re-check.")
                            break
                    else:
                        print("[POSE-FOLLOW] post-rotation fresh pose plan unavailable; diagnostics skipped.")

                if not did_single_post_check:
                    reset_snapshot("pose rotation motion finished; waiting for fresh view")

                if round_idx < max_rounds:
                    time.sleep(settle_s)
                    # If diagnostics already produced a fresh plan, reuse it in the next round.
                    # This avoids the old duplicate behavior: post-check once, then immediately
                    # requesting another fresh pose while/after the arms return to standby.
                    if post_diag_plan is None:
                        latest_pose_rotation_plan = None

            print("[POSE-AUTO] loop finished. Check final pose overlay, then press 5 if you want a fresh manual preview.\n")

    def _apply_low_z_roarm_offset(target: Optional[Dict[str, float]], prefix: str, source: str) -> Optional[Dict[str, float]]:
        """Apply a RoArm-local XY offset only to low-z contact/drag targets.

        The displayed camera pick point stays unchanged.  Use this when hover is
        visually correct but the real gripper tip shifts sideways during z descent.
        """
        if target is None:
            return None
        arm_key = str(target.get("arm_key", ""))
        ox = float(getattr(args, f"{prefix}_{arm_key}_contact_offset_x", 0.0))
        oy = float(getattr(args, f"{prefix}_{arm_key}_contact_offset_y", 0.0))
        if abs(ox) < 1e-9 and abs(oy) < 1e-9:
            return target
        out = dict(target)
        out["rx_raw"] = float(target["rx"])
        out["ry_raw"] = float(target["ry"])
        out["rx"] = float(target["rx"]) + ox
        out["ry"] = float(target["ry"]) + oy
        if (not args.allow_unsafe_roarm) and (not is_xyz_safe(out["rx"], out["ry"], out["rz"], args)):
            print(f"[{source}-OFFSET-BLOCKED] {arm_key.upper()} offset target outside safety range: "
                  f"raw=({target['rx']:.1f},{target['ry']:.1f}) offset=({ox:.1f},{oy:.1f}) "
                  f"final=({out['rx']:.1f},{out['ry']:.1f},{out['rz']:.1f})")
            return None
        print(f"[{source}-OFFSET] {arm_key.upper()} RoArm low-z offset=({ox:.1f},{oy:.1f}) "
              f"raw=({target['rx']:.1f},{target['ry']:.1f},{target['rz']:.1f}) "
              f"final=({out['rx']:.1f},{out['ry']:.1f},{out['rz']:.1f})")
        return out

    def _targeted_press_source_candidate(plan: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
        if isinstance(plan, dict) and isinstance(plan.get("candidate"), dict):
            return plan.get("candidate")
        if latest_coarse_plan is not None and isinstance(latest_coarse_plan.get("candidate"), dict):
            return latest_coarse_plan.get("candidate")
        if latest_candidate is not None:
            return latest_candidate
        if latest_candidates:
            try:
                return max(latest_candidates, key=lambda c: c.get("area", 0.0))
            except Exception:
                return latest_candidates[0]
        return None

    def _targeted_clamp_board_xy(bx: float, by: float) -> Tuple[float, float]:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        m = float(args.targeted_press_board_margin)
        return (float(np.clip(float(bx), min_bx + m, max_bx - m)),
                float(np.clip(float(by), min_by + m, max_by - m)))

    def _board_vec_unit(v) -> Optional[np.ndarray]:
        vv = np.asarray(v, dtype=np.float32).reshape(2)
        n = float(np.linalg.norm(vv))
        if n < 1e-6:
            return None
        return vv / n

    def _targeted_mask_ratio_at_board(mask_u8: np.ndarray, bx: float, by: float) -> float:
        p = board_to_pixel(latest_H, float(bx), float(by))
        if p is None:
            return 0.0
        return float(_local_mask_ratio(mask_u8, p, radius=int(args.targeted_press_local_mask_radius)))

    def _targeted_candidate_from_problem(kind: str, score: float, problem_board, outward_board,
                                         center_board, mask_u8: np.ndarray, reason: str,
                                         extra: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
        """Convert a detected contour/edge problem point into an inset press preview path.

        problem_board: where the defect/edge was detected, usually near the mask contour.
        press_start: problem_board moved inward toward cloth center, so the pad starts on cloth instead of the bare edge.
        press_end: press_start moved outward to flatten the detected defect/edge.
        """
        try:
            pb = np.asarray(problem_board, dtype=np.float32).reshape(2)
            cb = np.asarray(center_board, dtype=np.float32).reshape(2)
            out_u = _board_vec_unit(outward_board)
            in_u = _board_vec_unit(cb - pb)
            if out_u is None or in_u is None:
                return None

            inset = max(0.0, float(args.targeted_press_inset_mm))
            press_start = pb + in_u * inset
            sx, sy = _targeted_clamp_board_xy(float(press_start[0]), float(press_start[1]))

            local_ratio = _targeted_mask_ratio_at_board(mask_u8, sx, sy)
            if local_ratio < float(args.targeted_press_min_local_mask_ratio):
                # Try a slightly deeper inset before rejecting. This often helps when the contour point
                # is exactly on the garment boundary and homography/pixel rounding places it on the board.
                press_start2 = pb + in_u * (inset * 1.6 + 8.0)
                sx2, sy2 = _targeted_clamp_board_xy(float(press_start2[0]), float(press_start2[1]))
                local_ratio2 = _targeted_mask_ratio_at_board(mask_u8, sx2, sy2)
                if local_ratio2 >= local_ratio:
                    sx, sy, local_ratio = sx2, sy2, local_ratio2
                if local_ratio < float(args.targeted_press_min_local_mask_ratio):
                    return None

            dist = max(0.0, float(args.targeted_press_sweep_distance))
            ex, ey = _targeted_clamp_board_xy(sx + float(out_u[0]) * dist, sy + float(out_u[1]) * dist)
            arm_key = select_arm_for_board_x(cfg, sx)
            if arm_key is None:
                return None

            problem_px = board_to_pixel(latest_H, float(pb[0]), float(pb[1]))
            sp = board_to_pixel(latest_H, sx, sy)
            ep = board_to_pixel(latest_H, ex, ey)
            return {
                "kind": str(kind),
                "score": float(score),
                "arm_key": arm_key,
                "problem_board_xy": [float(pb[0]), float(pb[1])],
                "start_board_xy": [float(sx), float(sy)],
                "end_board_xy": [float(ex), float(ey)],
                "problem_px": None if problem_px is None else [float(problem_px[0]), float(problem_px[1])],
                "start_px": None if sp is None else [float(sp[0]), float(sp[1])],
                "end_px": None if ep is None else [float(ep[0]), float(ep[1])],
                "local_mask_ratio": float(local_ratio),
                "inset_mm": float(inset),
                "reason": str(reason),
                "extra": dict(extra or {}),
            }
        except Exception:
            return None

    def _odd_ksize(v: int, min_v: int = 3) -> int:
        k = max(int(min_v), int(v))
        if k % 2 == 0:
            k += 1
        return k

    def _normalize_u8_f32(arr: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
        a = np.asarray(arr, dtype=np.float32)
        out = np.zeros(a.shape, dtype=np.uint8)
        if mask is not None:
            m = mask > 0
            if not np.any(m):
                return out
            vals = a[m]
            lo, hi = float(np.percentile(vals, 2.0)), float(np.percentile(vals, 98.0))
        else:
            lo, hi = float(np.percentile(a, 2.0)), float(np.percentile(a, 98.0))
        if hi <= lo + 1e-6:
            return out
        n = np.clip((a - lo) * (255.0 / (hi - lo)), 0, 255).astype(np.uint8)
        if mask is not None:
            n[mask <= 0] = 0
        return n

    def _wrinkle_source_frame_for_candidate(cand: Dict[str, Any]) -> Optional[np.ndarray]:
        frame = snapshot_frame
        if frame is None:
            return None
        try:
            image_shape = cand.get("image_shape")
            if image_shape is not None:
                ih, iw = int(image_shape[0]), int(image_shape[1])
                if frame.shape[0] != ih or frame.shape[1] != iw:
                    return cv2.resize(frame, (iw, ih), interpolation=cv2.INTER_LINEAR)
        except Exception:
            pass
        return frame

    def _wrinkle_plan_score(plan: Optional[Dict[str, Any]]) -> Dict[str, float]:
        if plan is None:
            return {"candidate_count": 0.0, "candidate_score_sum": 0.0, "candidate_score_max": 0.0, "heat_mean_top": 0.0}
        cands = list(plan.get("candidates", []))
        scores = [float(c.get("score", 0.0)) for c in cands]
        heat_top = 0.0
        try:
            heat = plan.get("heatmap")
            inner = plan.get("inner_mask")
            if heat is not None and inner is not None:
                vals = np.asarray(heat)[np.asarray(inner) > 0]
                if vals.size > 0:
                    cut = np.percentile(vals, 95.0)
                    top = vals[vals >= cut]
                    heat_top = float(np.mean(top)) if top.size > 0 else float(np.mean(vals))
        except Exception:
            heat_top = 0.0
        return {
            "candidate_count": float(len(cands)),
            "candidate_score_sum": float(np.sum(scores)) if scores else 0.0,
            "candidate_score_max": float(np.max(scores)) if scores else 0.0,
            "heat_mean_top": float(heat_top),
        }

    def _wrinkle_feedback_penalty_for_board_xy(sxy) -> float:
        if not bool(args.wrinkle_feedback_avoid_repeat):
            return 0.0
        try:
            p = np.asarray(sxy, dtype=np.float32).reshape(2)
        except Exception:
            return 0.0
        radius = max(0.0, float(args.wrinkle_feedback_repeat_radius_mm))
        penalty = 0.0
        for h in wrinkle_press_history[-max(1, int(args.wrinkle_feedback_history_max)):]:
            try:
                hp = np.asarray(h.get("board_xy", [999999.0, 999999.0]), dtype=np.float32).reshape(2)
                d = float(np.linalg.norm(p - hp))
            except Exception:
                continue
            if d <= radius:
                penalty = max(penalty, float(args.wrinkle_feedback_repeat_penalty) * (1.0 - d / max(1.0, radius)))
        return float(penalty)

    def _remember_targeted_press_history(action_plan: Optional[Dict[str, Any]], result: Optional[Dict[str, Any]] = None):
        if action_plan is None:
            return
        now = time.time()
        for p in action_plan.get("passes", []):
            c = p.get("candidate", {})
            sxy = c.get("start_board_xy")
            if not sxy:
                continue
            ex = c.get("extra", {}) if isinstance(c.get("extra", {}), dict) else {}
            direction = ex.get("direction_board")
            if direction is None:
                try:
                    exy = c.get("end_board_xy", sxy)
                    vv = np.asarray([float(exy[0]) - float(sxy[0]), float(exy[1]) - float(sxy[1])], dtype=np.float32)
                    vu = _unit_or_none(vv)
                    direction = [float(vu[0]), float(vu[1])] if vu is not None else [0.0, 0.0]
                except Exception:
                    direction = [0.0, 0.0]
            wrinkle_press_history.append({
                "time": float(now),
                "kind": str(c.get("kind", "?")),
                "arm_key": str(p.get("arm_key", c.get("arm_key", "?"))),
                "board_xy": [float(sxy[0]), float(sxy[1])],
                "direction_board": [float(direction[0]), float(direction[1])] if isinstance(direction, (list, tuple)) and len(direction) >= 2 else [0.0, 0.0],
                "score": float(c.get("score", 0.0)),
                "result": dict(result or {}),
            })
        hmax = max(1, int(args.wrinkle_feedback_history_max))
        if len(wrinkle_press_history) > hmax:
            del wrinkle_press_history[:-hmax]

    def _safe_jsonable(obj: Any) -> Any:
        if isinstance(obj, np.ndarray):
            return {"__ndarray__": list(obj.shape), "dtype": str(obj.dtype)}
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return float(obj)
        if isinstance(obj, dict):
            return {str(k): _safe_jsonable(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple)):
            return [_safe_jsonable(v) for v in obj]
        return obj

    def save_wrinkle_feedback_debug(action_plan: Optional[Dict[str, Any]],
                                    before_plan: Optional[Dict[str, Any]],
                                    after_plan: Optional[Dict[str, Any]],
                                    result: Dict[str, Any],
                                    prefix: str = "targeted") -> Optional[str]:
        if not bool(args.wrinkle_feedback_save_debug):
            return None
        try:
            out_dir = os.path.join(os.getcwd(), str(args.wrinkle_feedback_dir))
            os.makedirs(out_dir, exist_ok=True)
            stamp = time.strftime("%Y%m%d_%H%M%S")
            base = os.path.join(out_dir, f"{stamp}_{prefix}")
            if snapshot_frame is not None:
                cv2.imwrite(base + "_snapshot.jpg", snapshot_frame)
            if before_plan is not None and before_plan.get("heatmap") is not None:
                heat = before_plan.get("heatmap")
                cv2.imwrite(base + "_before_heatmap.png", cv2.applyColorMap(np.asarray(heat, dtype=np.uint8), cv2.COLORMAP_JET))
            if after_plan is not None and after_plan.get("heatmap") is not None:
                heat = after_plan.get("heatmap")
                cv2.imwrite(base + "_after_heatmap.png", cv2.applyColorMap(np.asarray(heat, dtype=np.uint8), cv2.COLORMAP_JET))
            meta = {
                "result": result,
                "action_plan": _safe_jsonable(action_plan),
                "before_summary": before_plan.get("summary") if before_plan else None,
                "after_summary": after_plan.get("summary") if after_plan else None,
                "history": _safe_jsonable(wrinkle_press_history),
            }
            with open(base + ".json", "w", encoding="utf-8") as f:
                json.dump(meta, f, ensure_ascii=False, indent=2)
            print(f"[WRINKLE-FEEDBACK] saved debug files: {base}.*")
            return base
        except Exception as e:
            print("[WRINKLE-FEEDBACK-SAVE-WARN]", repr(e))
            return None

    def _unit_or_none(v) -> Optional[np.ndarray]:
        try:
            vv = np.asarray(v, dtype=np.float32).reshape(2)
            n = float(np.linalg.norm(vv))
            if n < 1e-6:
                return None
            return vv / n
        except Exception:
            return None

    def _pixel_vec_to_board_unit(cx_px: float, cy_px: float, v_px) -> Optional[np.ndarray]:
        if latest_H is None:
            return None
        vu = _unit_or_none(v_px)
        if vu is None:
            return None
        try:
            scale = 30.0
            b0 = np.array(pixel_to_board(latest_H, float(cx_px), float(cy_px)), dtype=np.float32)
            b1 = np.array(pixel_to_board(latest_H, float(cx_px + vu[0] * scale), float(cy_px + vu[1] * scale)), dtype=np.float32)
            return _unit_or_none(b1 - b0)
        except Exception:
            return None

    def _wrinkle_blob_orientation_board(wc: np.ndarray, cxp: float, cyp: float) -> Dict[str, Any]:
        """Estimate wrinkle blob orientation using PCA of the heatmap blob contour.

        major_board follows the long axis of the detected wrinkle-like blob.
        normal_board is perpendicular to that long axis. Pressing across this normal often reduces wrinkle-like ridges better than sweeping along the line.
        """
        out = {
            "major_board": None,
            "normal_board": None,
            "major_ratio": 1.0,
            "angle_deg": 0.0,
        }
        try:
            pts = wc.reshape(-1, 2).astype(np.float32)
            if pts.shape[0] < 5:
                return out
            mean = np.mean(pts, axis=0)
            pts0 = pts - mean
            cov = np.cov(pts0.T)
            vals, vecs = np.linalg.eigh(cov)
            order = np.argsort(vals)[::-1]
            vals = vals[order]
            vecs = vecs[:, order]
            major_px = vecs[:, 0].astype(np.float32)
            if major_px[0] < 0:
                major_px = -major_px
            minor_val = max(float(vals[1]) if len(vals) > 1 else 1e-6, 1e-6)
            ratio = float(np.sqrt(max(float(vals[0]), 1e-6) / minor_val))
            normal_px = np.array([-major_px[1], major_px[0]], dtype=np.float32)
            major_b = _pixel_vec_to_board_unit(cxp, cyp, major_px)
            normal_b = _pixel_vec_to_board_unit(cxp, cyp, normal_px)
            out["major_board"] = None if major_b is None else [float(major_b[0]), float(major_b[1])]
            out["normal_board"] = None if normal_b is None else [float(normal_b[0]), float(normal_b[1])]
            out["major_ratio"] = float(ratio)
            out["angle_deg"] = float(np.degrees(np.arctan2(float(major_px[1]), float(major_px[0]))))
            return out
        except Exception:
            return out

    def _adaptive_wrinkle_direction_from_feedback(pb: np.ndarray, direction_u: np.ndarray) -> Tuple[np.ndarray, str]:
        du = _unit_or_none(direction_u)
        if du is None:
            return direction_u, "invalid"
        if not bool(args.wrinkle_press_reverse_after_bad_feedback):
            return du, "no_adapt"
        radius = max(0.0, float(args.wrinkle_feedback_repeat_radius_mm))
        bad_thr = float(args.wrinkle_feedback_bad_delta_threshold)
        good_thr = float(args.wrinkle_feedback_good_delta_threshold)
        best_bad = None
        best_good = None
        p = np.asarray(pb, dtype=np.float32).reshape(2)
        for h in wrinkle_press_history[-max(1, int(args.wrinkle_feedback_history_max)):]:
            if str(h.get("kind", "")) != "wrinkle":
                continue
            try:
                hp = np.asarray(h.get("board_xy", [999999.0, 999999.0]), dtype=np.float32).reshape(2)
                d = float(np.linalg.norm(p - hp))
            except Exception:
                continue
            if d > radius:
                continue
            prev_dir = _unit_or_none(h.get("direction_board", [0.0, 0.0]))
            if prev_dir is None:
                continue
            result = h.get("result", {}) if isinstance(h.get("result", {}), dict) else {}
            delta = float(result.get("candidate_score_delta", 999.0))
            dot = float(np.dot(prev_dir, du))
            if delta >= bad_thr and dot > 0.35:
                best_bad = (d, delta, prev_dir)
            if delta <= good_thr and dot < -0.35:
                best_good = (d, delta, prev_dir)
        if best_bad is not None:
            return -du, f"reverse_bad_feedback(delta={best_bad[1]:+.1f})"
        if best_good is not None:
            return -du, f"match_previous_good(delta={best_good[1]:+.1f})"
        return du, "keep"

    def _choose_wrinkle_press_direction(pb: np.ndarray, cb: np.ndarray, orient: Dict[str, Any]) -> Tuple[Optional[np.ndarray], str]:
        outward = _unit_or_none(pb - cb)
        if outward is None:
            return None, "no_outward"
        mode = str(args.wrinkle_press_direction_mode)
        major = _unit_or_none(orient.get("major_board"))
        normal = _unit_or_none(orient.get("normal_board"))
        ratio = float(orient.get("major_ratio", 1.0))
        chosen = outward
        reason = "center_outward"

        if mode == "major_outward" and major is not None and ratio >= float(args.wrinkle_press_direction_min_major_ratio):
            chosen = major if float(np.dot(major, outward)) >= 0.0 else -major
            reason = f"major_outward(ratio={ratio:.2f})"
        elif mode == "normal_outward" and normal is not None and ratio >= float(args.wrinkle_press_direction_min_major_ratio):
            chosen = normal if float(np.dot(normal, outward)) >= 0.0 else -normal
            reason = f"normal_to_wrinkle(ratio={ratio:.2f})"
        else:
            chosen = outward
            reason = f"center_outward(ratio={ratio:.2f})"

        chosen, adapt_reason = _adaptive_wrinkle_direction_from_feedback(pb, chosen)
        if adapt_reason not in ("keep", "no_adapt"):
            reason += f"/{adapt_reason}"
        return chosen, reason

    def _wrinkle_board_vacancy_gaps(board_pts: np.ndarray) -> Dict[str, float]:
        """보드 사각형 기준으로 옷이 어느 변에서 더 멀리 떨어져 있는지 계산합니다."""
        try:
            pts = np.asarray(board_pts, dtype=np.float32).reshape(-1, 2)
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            if len(pts) < 10:
                return {"left": 0.0, "right": 0.0, "top": 0.0, "bottom": 0.0}
            lo_x = float(np.percentile(pts[:, 0], 2.0))
            hi_x = float(np.percentile(pts[:, 0], 98.0))
            lo_y = float(np.percentile(pts[:, 1], 2.0))
            hi_y = float(np.percentile(pts[:, 1], 98.0))
            return {
                "left": max(0.0, lo_x - float(min_bx)),
                "right": max(0.0, float(max_bx) - hi_x),
                "top": max(0.0, float(max_by) - hi_y),
                "bottom": max(0.0, lo_y - float(min_by)),
            }
        except Exception:
            return {"left": 0.0, "right": 0.0, "top": 0.0, "bottom": 0.0}

    def _wrinkle_direction_score_toward_vacancy(u: np.ndarray, board_pts: np.ndarray, origin: np.ndarray) -> Tuple[float, str, Dict[str, float]]:
        """주름 법선의 한쪽 방향이 보드의 빈 변을 얼마나 향하는지 점수화합니다."""
        uu = _unit_or_none(u)
        if uu is None:
            return -1e9, "invalid", {}
        gaps = _wrinkle_board_vacancy_gaps(board_pts)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        side_vec = {
            "left": np.array([-1.0, 0.0], dtype=np.float32),
            "right": np.array([1.0, 0.0], dtype=np.float32),
            "top": np.array([0.0, 1.0], dtype=np.float32),
            "bottom": np.array([0.0, -1.0], dtype=np.float32),
        }
        p = np.asarray(origin, dtype=np.float32).reshape(2)
        point_gap = {
            "left": max(0.0, float(p[0]) - float(min_bx)),
            "right": max(0.0, float(max_bx) - float(p[0])),
            "top": max(0.0, float(max_by) - float(p[1])),
            "bottom": max(0.0, float(p[1]) - float(min_by)),
        }
        side_w = float(getattr(args, "targeted_press_wrinkle_vacancy_side_weight", 1.0))
        center_w = float(getattr(args, "targeted_press_wrinkle_center_side_weight", 0.25))
        terms = {}
        score = 0.0
        for side, sv in side_vec.items():
            align = max(0.0, float(np.dot(uu, sv)))
            term = align * (side_w * float(gaps.get(side, 0.0)) + center_w * float(point_gap.get(side, 0.0)))
            terms[side] = float(term)
            score += term
        best_side = max(terms, key=lambda k: terms[k]) if terms else "?"
        return float(score), f"toward_empty_{best_side}(gap={gaps.get(best_side,0.0):.1f},score={score:.1f})", gaps

    def _choose_wrinkle_normal_toward_empty_side(pb: np.ndarray, cb: np.ndarray, orient: Dict[str, Any], board_pts: np.ndarray) -> Tuple[Optional[np.ndarray], str]:
        """주름선에 수직인 두 방향 중 보드에서 옷이 덜 채워진 쪽을 고릅니다."""
        major = _unit_or_none(orient.get("major_board"))
        normal = _unit_or_none(orient.get("normal_board"))
        ratio = float(orient.get("major_ratio", 1.0))
        min_ratio = float(getattr(args, "targeted_press_wrinkle_min_major_ratio_for_edge_pull", 1.15))
        p = np.asarray(pb, dtype=np.float32).reshape(2)
        if normal is not None and ratio >= min_ratio:
            s1, r1, _ = _wrinkle_direction_score_toward_vacancy(normal, board_pts, p)
            s2, r2, _ = _wrinkle_direction_score_toward_vacancy(-normal, board_pts, p)
            if s2 > s1:
                return (-normal).astype(np.float32), f"normal_to_empty/{r2}/ratio={ratio:.2f}"
            return normal.astype(np.float32), f"normal_to_empty/{r1}/ratio={ratio:.2f}"
        gaps = _wrinkle_board_vacancy_gaps(board_pts)
        side_vec = {
            "left": np.array([-1.0, 0.0], dtype=np.float32),
            "right": np.array([1.0, 0.0], dtype=np.float32),
            "top": np.array([0.0, 1.0], dtype=np.float32),
            "bottom": np.array([0.0, -1.0], dtype=np.float32),
        }
        side = max(gaps, key=lambda k: gaps[k]) if gaps else "right"
        u = side_vec.get(side, np.array([1.0, 0.0], dtype=np.float32))
        return u.astype(np.float32), f"fallback_to_emptiest_{side}(gap={gaps.get(side,0.0):.1f},ratio={ratio:.2f})"

    def _wrinkle_contact_from_normal_ray(board_pts: np.ndarray,
                                         origin: np.ndarray,
                                         u: np.ndarray,
                                         mask_u8: np.ndarray) -> Tuple[Optional[np.ndarray], Optional[np.ndarray], str]:
        """주름 중심에서 선택 방향으로 옷 가장자리까지 따라간 뒤, 가장자리 안쪽 접촉점을 고릅니다."""
        pts = np.asarray(board_pts, dtype=np.float32).reshape(-1, 2)
        origin = np.asarray(origin, dtype=np.float32).reshape(2)
        uu = _unit_or_none(u)
        if uu is None or len(pts) < 10:
            return None, None, "invalid normal ray"
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        margin = max(0.0, float(getattr(args, "targeted_press_board_margin", 35.0)))
        board_safe = ((pts[:, 0] >= min_bx + margin) & (pts[:, 0] <= max_bx - margin) &
                      (pts[:, 1] >= min_by + margin) & (pts[:, 1] <= max_by - margin))
        pts_safe = pts[board_safe]
        if len(pts_safe) < 10:
            pts_safe = pts[((pts[:, 0] >= min_bx) & (pts[:, 0] <= max_bx) & (pts[:, 1] >= min_by) & (pts[:, 1] <= max_by))]
        if len(pts_safe) < 10:
            return None, None, "no safe cloth points"
        rel = pts_safe - origin.reshape(1, 2)
        proj = (rel @ uu.reshape(2, 1)).reshape(-1)
        perp = np.abs(rel[:, 0] * float(uu[1]) - rel[:, 1] * float(uu[0]))
        forward = proj > 5.0
        if int(np.count_nonzero(forward)) < 5:
            return None, None, "no cloth points along normal"
        max_proj = float(np.max(proj[forward]))
        ray_w = max(5.0, float(getattr(args, "targeted_press_wrinkle_edge_ray_width_mm", 42.0)))
        edge_band = max(5.0, float(getattr(args, "targeted_press_wrinkle_edge_band_mm", 55.0)))
        near_edge = forward & (proj >= max_proj - edge_band) & (perp <= ray_w)
        if int(np.count_nonzero(near_edge)) < 3:
            near_edge = forward & (proj >= max_proj - edge_band * 1.8)
        if int(np.count_nonzero(near_edge)) < 1:
            return None, None, "no edge hit on normal ray"
        cand_pts = pts_safe[near_edge]
        cand_rel = cand_pts - origin.reshape(1, 2)
        cand_proj = (cand_rel @ uu.reshape(2, 1)).reshape(-1)
        cand_perp = np.abs(cand_rel[:, 0] * float(uu[1]) - cand_rel[:, 1] * float(uu[0]))
        score = -cand_proj + 0.30 * cand_perp
        edge = cand_pts[int(np.argmin(score))].astype(np.float32)
        inset0 = max(0.0, float(getattr(args, "targeted_press_wrinkle_edge_contact_inset_mm", 32.0)))
        min_local = float(getattr(args, "targeted_press_min_local_mask_ratio", 0.18))
        trials = [inset0, inset0 * 1.3, inset0 * 1.6, max(12.0, inset0 * 0.65)]
        best = None
        best_ratio = -1.0
        best_note = ""
        for inset in trials:
            p = edge - uu.astype(np.float32) * float(inset)
            bx, by = _targeted_clamp_board_xy(float(p[0]), float(p[1]))
            p = np.array([bx, by], dtype=np.float32)
            ratio = _targeted_mask_ratio_at_board(mask_u8, float(p[0]), float(p[1]))
            if ratio > best_ratio:
                best, best_ratio, best_note = p, ratio, f"edge_inset={inset:.1f}"
            if ratio >= min_local:
                return p, edge, f"{best_note}, local={ratio:.2f}"
            d = np.linalg.norm(pts_safe - p.reshape(1, 2), axis=1)
            nearest = pts_safe[int(np.argmin(d))].astype(np.float32)
            ratio2 = _targeted_mask_ratio_at_board(mask_u8, float(nearest[0]), float(nearest[1]))
            if ratio2 > best_ratio:
                best, best_ratio, best_note = nearest, ratio2, f"snapped_edge_inset={inset:.1f} d={float(np.min(d)):.1f}"
            if ratio2 >= min_local:
                return nearest, edge, f"{best_note}, local={ratio2:.2f}"
        if best is not None and best_ratio >= max(0.08, min_local * 0.55):
            return best.astype(np.float32), edge, f"low_local_allowed {best_note}, local={best_ratio:.2f}"
        return None, edge, f"edge contact local too low: best={best_ratio:.2f}"

    def _wrinkle_outward_fallback_contact(problem_xy: np.ndarray,
                                          u: np.ndarray,
                                          mask_u8: np.ndarray,
                                          board_pts: Optional[np.ndarray] = None) -> Tuple[Optional[np.ndarray], str]:
        """Return a safe outward-offset contact when the edge-ray contact is unavailable.

        This prevents the old bad fallback where S == P, which made the outward guard
        reject every candidate with P->S=0. The fallback is still outward: S = P + u*d,
        optionally snapped to nearby cloth support.
        """
        if not bool(getattr(args, "targeted_press_wrinkle_outward_fallback", True)):
            return None, "outward fallback OFF"
        uu = _unit_or_none(u)
        if uu is None:
            return None, "invalid fallback direction"
        p0 = np.asarray(problem_xy, dtype=np.float32).reshape(2)
        offset = max(float(getattr(args, "targeted_press_wrinkle_min_contact_outward_mm", 12.0)) + 2.0,
                     float(getattr(args, "targeted_press_wrinkle_outward_fallback_offset_mm", 28.0)))
        bx, by = _targeted_clamp_board_xy(float(p0[0] + float(uu[0]) * offset),
                                          float(p0[1] + float(uu[1]) * offset))
        cand = np.array([bx, by], dtype=np.float32)
        min_local = max(0.0, float(getattr(args, "targeted_press_wrinkle_outward_fallback_min_local", 0.10)))
        local = _targeted_mask_ratio_at_board(mask_u8, float(cand[0]), float(cand[1]))
        if local >= min_local:
            return cand, f"outward_fallback_offset={offset:.1f} local={local:.2f}"
        try:
            if board_pts is not None:
                pts = np.asarray(board_pts, dtype=np.float32).reshape(-1, 2)
                if len(pts) >= 5:
                    rel = pts - p0.reshape(1, 2)
                    proj = (rel @ uu.reshape(2, 1)).reshape(-1)
                    dist = np.linalg.norm(pts - cand.reshape(1, 2), axis=1)
                    snap_lim = max(0.0, float(getattr(args, "targeted_press_wrinkle_outward_fallback_snap_mm", 35.0)))
                    ok = (proj >= max(6.0, offset * 0.45)) & (dist <= snap_lim)
                    if int(np.count_nonzero(ok)) > 0:
                        idxs = np.where(ok)[0]
                        best_i = int(idxs[int(np.argmin(dist[idxs]))])
                        snapped = pts[best_i].astype(np.float32)
                        local2 = _targeted_mask_ratio_at_board(mask_u8, float(snapped[0]), float(snapped[1]))
                        if local2 >= max(0.06, min_local * 0.55):
                            return snapped, (f"outward_fallback_snapped offset={offset:.1f} "
                                             f"d={float(dist[best_i]):.1f} local={local2:.2f}")
        except Exception as e:
            return None, f"outward fallback snap error: {e}"
        return None, f"outward fallback local too low: local={local:.2f} < {min_local:.2f}"

    def _validate_wrinkle_outward_path(problem_xy: np.ndarray,
                                       start_xy: np.ndarray,
                                       end_xy: np.ndarray,
                                       chosen_dir: Optional[np.ndarray] = None) -> Tuple[bool, str, Dict[str, float]]:
        """Reject 2번 heatmap wrinkle paths that move inward or bend back toward the wrinkle.

        P = wrinkle/problem center, S = press start point, E = sweep end point.
        Valid order must be: P -> S -> E.
        This catches both abnormal cases the user observed:
          1) S is on the wrong side of P, so the press point is inward.
          2) E bends back inward after clamping or arm/path selection.
        """
        if not bool(getattr(args, "targeted_press_wrinkle_outward_guard", True)):
            return True, "outward_guard_off", {}
        try:
            p0 = np.asarray(problem_xy, dtype=np.float32).reshape(2)
            s0 = np.asarray(start_xy, dtype=np.float32).reshape(2)
            e0 = np.asarray(end_xy, dtype=np.float32).reshape(2)
            ps = s0 - p0
            se = e0 - s0
            pe = e0 - p0
            ps_len = float(np.linalg.norm(ps))
            se_len = float(np.linalg.norm(se))
            pe_len = float(np.linalg.norm(pe))
            min_contact = max(0.0, float(getattr(args, "targeted_press_wrinkle_min_contact_outward_mm", 12.0)))
            min_gain = max(0.0, float(getattr(args, "targeted_press_wrinkle_min_end_outward_gain_mm", 12.0)))
            min_sweep = max(0.0, float(getattr(args, "targeted_press_wrinkle_min_sweep_mm", 25.0)))
            min_cos = float(getattr(args, "targeted_press_wrinkle_min_outward_cos", 0.25))
            metrics = {
                "ps_len": ps_len,
                "se_len": se_len,
                "pe_len": pe_len,
                "end_gain": float(pe_len - ps_len),
                "radial_sweep_cos": -999.0,
                "radial_dir_cos": -999.0,
                "sweep_dir_cos": -999.0,
            }
            if ps_len < min_contact:
                return False, f"press too close to wrinkle: P->S={ps_len:.1f}mm < {min_contact:.1f}mm", metrics
            if se_len < min_sweep:
                return False, f"sweep too short after clamp: S->E={se_len:.1f}mm < {min_sweep:.1f}mm", metrics
            radial = ps / max(ps_len, 1e-6)
            sweep = se / max(se_len, 1e-6)
            radial_sweep_cos = float(np.dot(radial, sweep))
            metrics["radial_sweep_cos"] = radial_sweep_cos
            if radial_sweep_cos < min_cos:
                return False, f"end bends inward: cos((S-P),(E-S))={radial_sweep_cos:.2f} < {min_cos:.2f}", metrics
            end_gain = float(pe_len - ps_len)
            if end_gain < min_gain:
                return False, f"end not farther outward: |E-P|-|S-P|={end_gain:.1f}mm < {min_gain:.1f}mm", metrics
            if chosen_dir is not None:
                u = _unit_or_none(chosen_dir)
                if u is not None:
                    radial_dir_cos = float(np.dot(radial, u))
                    sweep_dir_cos = float(np.dot(sweep, u))
                    metrics["radial_dir_cos"] = radial_dir_cos
                    metrics["sweep_dir_cos"] = sweep_dir_cos
                    if radial_dir_cos < min_cos:
                        return False, f"press is opposite chosen outward normal: cos((S-P),u)={radial_dir_cos:.2f} < {min_cos:.2f}", metrics
                    if sweep_dir_cos < min_cos:
                        return False, f"sweep is opposite chosen outward normal: cos((E-S),u)={sweep_dir_cos:.2f} < {min_cos:.2f}", metrics
            return True, (f"outward_ok P->S={ps_len:.1f}mm S->E={se_len:.1f}mm "
                          f"gain={float(pe_len - ps_len):.1f}mm cos={radial_sweep_cos:.2f}"), metrics
        except Exception as e:
            return False, f"outward guard error: {e}", {}


    def build_wrinkle_heatmap_plan(cand: Optional[Dict[str, Any]] = None,
                                   feat: Optional[Dict[str, Any]] = None,
                                   mask_u8: Optional[np.ndarray] = None,
                                   print_result: bool = False) -> Optional[Dict[str, Any]]:
        """Step35: generate a wrinkle-like texture heatmap inside the cloth mask.

        This is not learned wrinkle recognition. It combines local contrast, high-pass shading,
        gradient magnitude, and optional multi-angle Gabor response. The goal is to look inside
        the garment mask instead of only at the contour.
        """
        nonlocal latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status

        if not bool(args.wrinkle_heatmap_mode):
            latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, "wrinkle_heatmap_mode OFF"
            return None

        if cand is None:
            cand = _targeted_press_source_candidate(latest_coarse_plan)
        if cand is None:
            latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, "no candidate"
            return None

        contour = cand.get("contour") if isinstance(cand, dict) else None
        image_shape = cand.get("image_shape") if isinstance(cand, dict) else None
        if contour is None or image_shape is None:
            latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, "missing contour/image_shape"
            return None

        if mask_u8 is None:
            mask_u8 = _mask_u8_from_contour(contour, image_shape)
        if feat is None:
            feat = compute_coarse_mask_features(cand, latest_H)
        center_board = None
        if isinstance(feat, dict):
            center_board = feat.get("board", {}).get("center") if isinstance(feat.get("board", {}), dict) else None

        frame = _wrinkle_source_frame_for_candidate(cand)
        if frame is None:
            latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, "no snapshot_frame for texture heatmap"
            return None

        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY) if frame.ndim == 3 else frame.copy()
            tile = max(2, int(args.wrinkle_heatmap_clahe_tile))
            clahe = cv2.createCLAHE(clipLimit=max(0.1, float(args.wrinkle_heatmap_clahe_clip)), tileGridSize=(tile, tile))
            eq = clahe.apply(gray)

            blur_k = _odd_ksize(int(args.wrinkle_heatmap_blur_ksize), 7)
            illum = cv2.GaussianBlur(eq, (blur_k, blur_k), 0)
            high = cv2.absdiff(eq, illum)

            sx = cv2.Sobel(eq, cv2.CV_32F, 1, 0, ksize=3)
            sy = cv2.Sobel(eq, cv2.CV_32F, 0, 1, ksize=3)
            grad = cv2.magnitude(sx, sy)

            lap = cv2.Laplacian(eq, cv2.CV_32F, ksize=3)
            lap = np.abs(lap)

            gabor_resp = np.zeros_like(grad, dtype=np.float32)
            if bool(args.wrinkle_heatmap_gabor):
                gk = _odd_ksize(int(args.wrinkle_heatmap_gabor_ksize), 7)
                sigma = max(0.5, float(args.wrinkle_heatmap_gabor_sigma))
                lambd = max(2.0, float(args.wrinkle_heatmap_gabor_lambda))
                for theta in (0.0, np.pi / 4.0, np.pi / 2.0, 3.0 * np.pi / 4.0):
                    kern = cv2.getGaborKernel((gk, gk), sigma, theta, lambd, gamma=0.45, psi=0, ktype=cv2.CV_32F)
                    resp = cv2.filter2D(eq, cv2.CV_32F, kern)
                    gabor_resp = np.maximum(gabor_resp, np.abs(resp))

            erode_px = max(0, int(args.wrinkle_heatmap_erode_px))
            if erode_px > 0:
                k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * erode_px + 1, 2 * erode_px + 1))
                inner_mask = cv2.erode(mask_u8, k, iterations=1)
                if int(np.count_nonzero(inner_mask)) < max(200, int(np.count_nonzero(mask_u8)) * 0.20):
                    inner_mask = mask_u8.copy()
            else:
                inner_mask = mask_u8.copy()

            dist_to_edge_px = cv2.distanceTransform((mask_u8 > 0).astype(np.uint8), cv2.DIST_L2, 5)
            wrinkle_px_per_mm = None
            try:
                margin_mm = max(0.0, float(getattr(args, "wrinkle_heatmap_inner_roi_margin_mm", 30.0)))
                if margin_mm > 0.0 and latest_H is not None and center_board is not None:
                    c0 = np.asarray(center_board, dtype=np.float32).reshape(2)
                    p0 = board_to_pixel(latest_H, float(c0[0]), float(c0[1]))
                    p1 = board_to_pixel(latest_H, float(c0[0] + 50.0), float(c0[1]))
                    p2 = board_to_pixel(latest_H, float(c0[0]), float(c0[1] + 50.0))
                    scales = []
                    if p0 is not None and p1 is not None:
                        scales.append(float(np.linalg.norm(np.asarray(p1) - np.asarray(p0))) / 50.0)
                    if p0 is not None and p2 is not None:
                        scales.append(float(np.linalg.norm(np.asarray(p2) - np.asarray(p0))) / 50.0)
                    if scales:
                        wrinkle_px_per_mm = float(np.median(scales))
                        base_keep = int(np.count_nonzero(mask_u8))
                        min_keep_ratio = float(np.clip(getattr(args, "wrinkle_heatmap_inner_roi_min_keep_ratio", 0.10), 0.02, 0.95))
                        min_keep = max(200, int(base_keep * min_keep_ratio))
                        chosen = None
                        chosen_margin = 0.0
                        for f in (1.0, 0.80, 0.60, 0.45):
                            margin_px = max(1, int(round(margin_mm * f * wrinkle_px_per_mm)))
                            roi = (((dist_to_edge_px >= float(margin_px)) & (mask_u8 > 0)).astype(np.uint8)) * 255
                            roi2 = cv2.bitwise_and(inner_mask, roi)
                            if int(np.count_nonzero(roi2)) >= min_keep:
                                chosen = roi2
                                chosen_margin = margin_mm * f
                                break
                        if chosen is not None:
                            inner_mask = chosen
                            if print_result:
                                print(f"[WRINKLE-ROI] inner ROI margin={chosen_margin:.1f}mm keeps {int(np.count_nonzero(inner_mask))}/{base_keep} px")
                        elif print_result:
                            print(f"[WRINKLE-ROI] requested inner margin={margin_mm:.1f}mm too strict; keep existing eroded mask")
            except Exception as e:
                if args.grasp_debug or print_result:
                    print("[WRINKLE-ROI-WARN]", repr(e))

            high_n = _normalize_u8_f32(high, inner_mask)
            grad_n = _normalize_u8_f32(grad, inner_mask)
            lap_n = _normalize_u8_f32(lap, inner_mask)
            if bool(args.wrinkle_heatmap_gabor):
                gabor_n = _normalize_u8_f32(gabor_resp, inner_mask)
            else:
                gabor_n = np.zeros_like(high_n)

            combined = (0.30 * high_n.astype(np.float32)
                        + 0.30 * grad_n.astype(np.float32)
                        + 0.20 * lap_n.astype(np.float32)
                        + 0.20 * gabor_n.astype(np.float32))
            heat = _normalize_u8_f32(combined, inner_mask)
            heat[inner_mask <= 0] = 0

            ready_inner_mask = np.zeros_like(mask_u8, dtype=np.uint8)
            ready_heatmap = np.zeros_like(heat, dtype=np.uint8)
            ready_threshold = 0.0
            ready_roi_valid = False
            ready_margin_mm = max(0.0, float(getattr(args, "auto_x_ready_cca_inner_roi_margin_mm", 15.0)))
            try:
                if ready_margin_mm <= 0.0:
                    ready_inner_mask = (mask_u8 > 0).astype(np.uint8) * 255
                elif wrinkle_px_per_mm is not None and float(wrinkle_px_per_mm) > 1e-6:
                    ready_margin_px = max(1, int(round(ready_margin_mm * float(wrinkle_px_per_mm))))
                    ready_inner_mask = (((dist_to_edge_px >= float(ready_margin_px)) & (mask_u8 > 0)).astype(np.uint8)) * 255
                base_ready_px = int(np.count_nonzero(mask_u8 > 0))
                min_ready_px = max(200, int(base_ready_px * 0.10))
                if int(np.count_nonzero(ready_inner_mask > 0)) >= min_ready_px:
                    ready_high_n = _normalize_u8_f32(high, ready_inner_mask)
                    ready_grad_n = _normalize_u8_f32(grad, ready_inner_mask)
                    ready_lap_n = _normalize_u8_f32(lap, ready_inner_mask)
                    if bool(args.wrinkle_heatmap_gabor):
                        ready_gabor_n = _normalize_u8_f32(gabor_resp, ready_inner_mask)
                    else:
                        ready_gabor_n = np.zeros_like(ready_high_n)
                    ready_combined = (0.30 * ready_high_n.astype(np.float32)
                                      + 0.30 * ready_grad_n.astype(np.float32)
                                      + 0.20 * ready_lap_n.astype(np.float32)
                                      + 0.20 * ready_gabor_n.astype(np.float32))
                    ready_heatmap = _normalize_u8_f32(ready_combined, ready_inner_mask)
                    ready_heatmap[ready_inner_mask <= 0] = 0
                    ready_vals = ready_heatmap[ready_inner_mask > 0]
                    if ready_vals.size > 0:
                        ready_threshold = max(float(args.wrinkle_heatmap_score_min),
                                              float(np.percentile(ready_vals, np.clip(float(args.wrinkle_heatmap_percentile), 50.0, 99.5))))
                        ready_roi_valid = True
                elif print_result:
                    print(f"[A114-READY-ROI] invalid: 15mm ROI too small ({int(np.count_nonzero(ready_inner_mask > 0))}/{base_ready_px}px)")
            except Exception as _ready_roi_e:
                if args.grasp_debug or print_result:
                    print("[A114-READY-ROI-WARN]", repr(_ready_roi_e))

            vals = heat[inner_mask > 0]
            if vals.size == 0:
                latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, "empty inner mask"
                return None
            thr = max(float(args.wrinkle_heatmap_score_min),
                      float(np.percentile(vals, np.clip(float(args.wrinkle_heatmap_percentile), 50.0, 99.5))))
            binary = np.zeros_like(heat, dtype=np.uint8)
            binary[(heat >= thr) & (inner_mask > 0)] = 255
            binary = cv2.morphologyEx(binary, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)), iterations=1)
            binary = cv2.dilate(binary, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)), iterations=1)

            contours, _ = cv2.findContours(binary, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            wrinkle_candidates: List[Dict[str, Any]] = []
            if center_board is not None:
                cb = np.asarray(center_board, dtype=np.float32).reshape(2)
            else:
                cb = None
            try:
                board_pts_all = mask_pixels_to_board_points(mask_u8, latest_H, stride=2)
            except Exception:
                board_pts_all = None

            for wc in contours:
                area = float(cv2.contourArea(wc))
                if area < float(args.wrinkle_heatmap_min_blob_area):
                    continue
                m = cv2.moments(wc)
                if abs(m.get("m00", 0.0)) < 1e-6:
                    continue
                cxp = float(m["m10"] / m["m00"])
                cyp = float(m["m01"] / m["m00"])
                x, y, w, h = cv2.boundingRect(wc)
                roi_mask = np.zeros_like(heat, dtype=np.uint8)
                cv2.drawContours(roi_mask, [wc], -1, 255, -1)
                mean_score = float(cv2.mean(heat, mask=roi_mask)[0])
                max_score = float(np.max(heat[roi_mask > 0])) if np.any(roi_mask > 0) else mean_score
                try:
                    bx, by = pixel_to_board(latest_H, cxp, cyp)
                except Exception:
                    continue
                edge_dist_mm = None
                try:
                    if wrinkle_px_per_mm is not None and wrinkle_px_per_mm > 1e-6:
                        ix = int(np.clip(round(cxp), 0, dist_to_edge_px.shape[1] - 1))
                        iy = int(np.clip(round(cyp), 0, dist_to_edge_px.shape[0] - 1))
                        edge_dist_mm = float(dist_to_edge_px[iy, ix]) / float(wrinkle_px_per_mm)
                        min_edge_mm = max(0.0, float(getattr(args, "wrinkle_heatmap_candidate_min_edge_dist_mm", 0.0)))
                        if min_edge_mm > 0.0 and edge_dist_mm < min_edge_mm:
                            if print_result:
                                print(f"[WRINKLE-ROI] skip edge-shadow candidate edge_dist={edge_dist_mm:.1f}mm < {min_edge_mm:.1f}mm")
                            continue
                except Exception:
                    edge_dist_mm = None
                if cb is not None:
                    pb = np.array([float(bx), float(by)], dtype=np.float32)
                    orient = _wrinkle_blob_orientation_board(wc, cxp, cyp)
                    edge_mode = bool(getattr(args, "targeted_press_wrinkle_edge_pull_mode", True)) and board_pts_all is not None and len(board_pts_all) >= 10
                    edge_pt = None
                    contact_reason = ""
                    if edge_mode:
                        un, dir_reason = _choose_wrinkle_normal_toward_empty_side(pb, cb, orient, board_pts_all)
                        if un is None:
                            continue
                        contact, edge_pt, contact_reason = _wrinkle_contact_from_normal_ray(board_pts_all, pb, un, mask_u8)
                        if contact is None:
                            # Do not fall back to the wrinkle center. Use a small outward-offset
                            # contact so the action can still run while satisfying P -> S -> E.
                            fb_contact, fb_reason = _wrinkle_outward_fallback_contact(pb, un, mask_u8, board_pts_all)
                            if fb_contact is None:
                                if print_result:
                                    print(f"[WRINKLE-EDGE-PULL] skip: {contact_reason}; fallback: {fb_reason}")
                                continue
                            start_board = np.asarray(fb_contact, dtype=np.float32).reshape(2)
                            direction_note = f"edge_pull_fallback/{dir_reason}/{contact_reason}/{fb_reason}"
                        else:
                            start_board = np.asarray(contact, dtype=np.float32).reshape(2)
                            direction_note = f"edge_pull/{dir_reason}/{contact_reason}"
                    else:
                        un, dir_reason = _choose_wrinkle_press_direction(pb, cb, orient)
                        if un is None:
                            continue
                        fb_contact, fb_reason = _wrinkle_outward_fallback_contact(pb, un, mask_u8, board_pts_all)
                        if fb_contact is None:
                            if print_result:
                                print(f"[WRINKLE-OUTWARD-FALLBACK] skip: {dir_reason}; {fb_reason}")
                            continue
                        start_board = np.asarray(fb_contact, dtype=np.float32).reshape(2)
                        direction_note = f"center_to_outward_fallback/{dir_reason}/{fb_reason}"
                    dist = max(0.0, float(args.targeted_press_wrinkle_sweep_distance))
                    sx_b, sy_b = _targeted_clamp_board_xy(float(start_board[0]), float(start_board[1]))
                    ex_b, ey_b = _targeted_clamp_board_xy(sx_b + float(un[0]) * dist, sy_b + float(un[1]) * dist)
                    outward_ok, outward_reason, outward_metrics = _validate_wrinkle_outward_path(
                        pb,
                        np.array([sx_b, sy_b], dtype=np.float32),
                        np.array([ex_b, ey_b], dtype=np.float32),
                        un,
                    )
                    if not outward_ok:
                        if print_result:
                            print(f"[WRINKLE-OUTWARD-GUARD] skip: {outward_reason}")
                        continue
                    sp = board_to_pixel(latest_H, sx_b, sy_b)
                    ep = board_to_pixel(latest_H, ex_b, ey_b)
                    arm_key = select_arm_for_board_x(cfg, sx_b)
                    if arm_key is None:
                        continue
                    local_ratio = _targeted_mask_ratio_at_board(mask_u8, sx_b, sy_b)
                    local_min_required = float(args.targeted_press_min_local_mask_ratio)
                    if "fallback" in str(direction_note):
                        local_min_required = min(local_min_required,
                                                 max(0.06, float(getattr(args, "targeted_press_wrinkle_outward_fallback_min_local", 0.10))))
                    if local_ratio < local_min_required:
                        if print_result:
                            print(f"[WRINKLE-LOCAL] skip: local={local_ratio:.2f} < {local_min_required:.2f} ({direction_note})")
                        continue
                    sweep_len = float(np.linalg.norm(np.array([ex_b - sx_b, ey_b - sy_b], dtype=np.float32)))
                    item = {
                        "kind": "wrinkle",
                        "score": float(max_score) * float(args.targeted_press_wrinkle_score_weight) + float(args.targeted_press_wrinkle_bonus),
                        "arm_key": arm_key,
                        "problem_board_xy": [float(pb[0]), float(pb[1])],
                        "start_board_xy": [float(sx_b), float(sy_b)],
                        "end_board_xy": [float(ex_b), float(ey_b)],
                        "problem_px": [float(cxp), float(cyp)],
                        "start_px": None if sp is None else [float(sp[0]), float(sp[1])],
                        "end_px": None if ep is None else [float(ep[0]), float(ep[1])],
                        "local_mask_ratio": float(local_ratio),
                        "inset_mm": float(getattr(args, "targeted_press_wrinkle_edge_contact_inset_mm", 0.0)) if edge_mode else 0.0,
                        "reason": f"wrinkle heatmap mean={mean_score:.1f} max={max_score:.1f} edge_dist={edge_dist_mm if edge_dist_mm is not None else -1:.1f}mm sweep={sweep_len:.1f}mm dir={direction_note} guard={outward_reason}",
                        "extra": {"area_px": float(area), "bbox": [int(x), int(y), int(w), int(h)],
                                  "edge_dist_mm": None if edge_dist_mm is None else float(edge_dist_mm),
                                  "mean_score": float(mean_score), "max_score": float(max_score),
                                  "orientation_deg": float(orient.get("angle_deg", 0.0)),
                                  "major_ratio": float(orient.get("major_ratio", 1.0)),
                                  "direction_board": [float(un[0]), float(un[1])],
                                  "direction_reason": str(direction_note),
                                  "wrinkle_problem_board_xy": [float(pb[0]), float(pb[1])],
                                  "edge_pull_mode": bool(edge_mode),
                                  "outward_guard_ok": True,
                                  "outward_guard_reason": str(outward_reason),
                                  "outward_guard_metrics": outward_metrics,
                                  "edge_contact_board_xy": [float(sx_b), float(sy_b)],
                                  "edge_board_xy": None if edge_pt is None else [float(edge_pt[0]), float(edge_pt[1])],
                                  "sweep_len_preview_mm": float(sweep_len)}
                    }
                    wrinkle_candidates.append(item)

            wrinkle_candidates.sort(key=lambda c: float(c.get("score", 0.0)), reverse=True)
            wrinkle_candidates = wrinkle_candidates[:max(1, int(args.wrinkle_heatmap_max_candidates))]

            _inner_keep_ratio = float(np.count_nonzero(inner_mask > 0)) / max(1.0, float(np.count_nonzero(mask_u8 > 0)))
            latest_wrinkle_heatmap_plan = {
                "heatmap": heat,
                "inner_mask": inner_mask,
                "binary": binary,
                "ready_heatmap": ready_heatmap,
                "ready_inner_mask": ready_inner_mask,
                "ready_threshold": float(ready_threshold),
                "ready_roi_valid": bool(ready_roi_valid),
                "ready_inner_roi_margin_mm": float(ready_margin_mm),
                "candidates": wrinkle_candidates,
                "threshold": float(thr),
                "inner_roi_margin_mm": float(getattr(args, "wrinkle_heatmap_inner_roi_margin_mm", 30.0)),
                "inner_roi_keep_ratio": _inner_keep_ratio,
                "status": "OK",
                "summary": f"wrinkle heatmap candidates={len(wrinkle_candidates)} thr={thr:.1f} percentile={float(args.wrinkle_heatmap_percentile):.1f} inner_margin={float(getattr(args, 'wrinkle_heatmap_inner_roi_margin_mm', 30.0)):.1f}mm keep={_inner_keep_ratio:.2f}",
            }
            latest_wrinkle_heatmap_status = "OK"
            if print_result:
                print("\n========== WRINKLE HEATMAP PREVIEW (STEP37) ==========")
                print(latest_wrinkle_heatmap_plan["summary"])
                print("This is texture/contrast based, not a trained wrinkle detector. Step37 also adapts sweep direction from feedback.")
                for idx, item in enumerate(wrinkle_candidates, 1):
                    sxy = item.get("start_board_xy", [0, 0])
                    exy = item.get("end_board_xy", [0, 0])
                    ex = item.get("extra", {})
                    print(f"{idx:02d}. wrinkle arm={item.get('arm_key','?').upper()} score={float(item.get('score',0)):.1f} "
                          f"local={float(item.get('local_mask_ratio',0)):.2f} ratio={float(ex.get('major_ratio',1.0)):.2f} "
                          f"press=({sxy[0]:.1f},{sxy[1]:.1f}) -> end=({exy[0]:.1f},{exy[1]:.1f}) "
                          f"{item.get('reason','')}")
                print("======================================================\n")
            return latest_wrinkle_heatmap_plan
        except Exception as e:
            latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status = None, f"error: {e}"
            if args.grasp_debug or print_result:
                print("[WRINKLE-HEATMAP-ERROR]", repr(e))
            return None

    def build_targeted_press_preview(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Step29 preview only: generate inset targeted press path candidates.

        The problem location is still detected from contour concavity / edge extremes,
        but the actual press start point is inset toward the cloth center and verified
        with local mask support. This avoids showing/executing points directly on the garment edge.
        """
        nonlocal latest_targeted_press_plan, latest_targeted_press_status

        if not bool(args.targeted_press_preview_mode):
            latest_targeted_press_plan, latest_targeted_press_status = None, "targeted_press_preview_mode OFF"
            if print_result:
                print(f"[TARGET-PRESS] {latest_targeted_press_status}")
            return None

        cand = _targeted_press_source_candidate(plan)
        if cand is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "no candidate/mask"
            if print_result:
                print(f"[TARGET-PRESS] not ready: {latest_targeted_press_status}")
            return None

        contour = cand.get("contour") if isinstance(cand, dict) else None
        image_shape = cand.get("image_shape") if isinstance(cand, dict) else None
        if contour is None or image_shape is None or latest_H is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "missing contour/image_shape/H"
            if print_result:
                print(f"[TARGET-PRESS] not ready: {latest_targeted_press_status}")
            return None

        feat = compute_coarse_mask_features(cand, latest_H)
        if feat is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "coarse mask features unavailable"
            if print_result:
                print(f"[TARGET-PRESS] not ready: {latest_targeted_press_status}")
            return None

        center_board = feat.get("board", {}).get("center") if isinstance(feat.get("board", {}), dict) else None
        solidity = float(feat.get("solidity", cand.get("solidity", 1.0)) or 1.0)
        if center_board is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "no center board"
            if print_result:
                print(f"[TARGET-PRESS] not ready: {latest_targeted_press_status}")
            return None

        mask_u8 = _mask_u8_from_contour(contour, image_shape)
        cb = np.asarray(center_board, dtype=np.float32).reshape(2)
        raw_candidates: List[Dict[str, Any]] = []

        def _add_targeted_candidate(item: Optional[Dict[str, Any]]):
            if item is None:
                return
            local = float(item.get("local_mask_ratio", 0.0))
            kind = str(item.get("kind", ""))
            quality_bonus = local * float(args.targeted_press_quality_local_weight)
            if kind == "concavity":
                quality_bonus += float(args.targeted_press_concavity_bonus)
            repeat_penalty = _wrinkle_feedback_penalty_for_board_xy(item.get("start_board_xy"))
            item["score"] = float(item.get("score", 0.0)) + quality_bonus - repeat_penalty
            item.setdefault("extra", {})
            item["extra"]["quality_bonus"] = float(quality_bonus)
            item["extra"]["repeat_penalty"] = float(repeat_penalty)
            if item["score"] > 0:
                raw_candidates.append(item)

        if bool(args.targeted_press_include_wrinkle_candidates):
            wh = build_wrinkle_heatmap_plan(cand, feat=feat, mask_u8=mask_u8, print_result=print_result)
            if wh is not None:
                for witem in wh.get("candidates", []):
                    _add_targeted_candidate(witem)

        try:
            cnt = contour.astype(np.int32)
            if cnt.ndim == 2:
                cnt = cnt.reshape(-1, 1, 2)
            if len(cnt) >= 4:
                hull = cv2.convexHull(cnt, returnPoints=False)
                if hull is not None and len(hull) >= 4:
                    defects = cv2.convexityDefects(cnt, hull)
                    if defects is not None:
                        for d in defects[:, 0, :]:
                            s_idx, e_idx, f_idx, depth_raw = int(d[0]), int(d[1]), int(d[2]), float(d[3])
                            depth_px = depth_raw / 256.0
                            if depth_px < float(args.targeted_press_min_defect_depth_px):
                                continue
                            spx = cnt[s_idx, 0].astype(np.float32)
                            epx = cnt[e_idx, 0].astype(np.float32)
                            fpx = cnt[f_idx, 0].astype(np.float32)
                            hull_mid_px = (spx + epx) * 0.5
                            try:
                                fb = np.array(pixel_to_board(latest_H, float(fpx[0]), float(fpx[1])), dtype=np.float32)
                                hb = np.array(pixel_to_board(latest_H, float(hull_mid_px[0]), float(hull_mid_px[1])), dtype=np.float32)
                            except Exception:
                                continue
                            outward = hb - fb
                            score = float(depth_px) + max(0.0, (1.0 - solidity) * 45.0)
                            item = _targeted_candidate_from_problem(
                                "concavity",
                                score,
                                fb,
                                outward,
                                cb,
                                mask_u8,
                                f"convexity defect depth={depth_px:.1f}px / inset-start",
                                {"depth_px": float(depth_px), "solidity": float(solidity)}
                            )
                            _add_targeted_candidate(item)
        except Exception as e:
            if args.grasp_debug:
                print("[TARGET-PRESS-DEFECT-WARN]", repr(e))

        use_edge_extremes = bool(args.targeted_press_include_edge_extremes) and (
            (not bool(args.targeted_press_edge_only_when_low_solidity))
            or solidity <= float(args.targeted_press_solidity_threshold)
        )
        if use_edge_extremes:
            try:
                cnt2 = contour.reshape(-1, 2).astype(np.float32)
                extreme_specs = [
                    ("edge_left", cnt2[int(np.argmin(cnt2[:, 0]))]),
                    ("edge_right", cnt2[int(np.argmax(cnt2[:, 0]))]),
                    ("edge_top", cnt2[int(np.argmin(cnt2[:, 1]))]),
                    ("edge_bottom", cnt2[int(np.argmax(cnt2[:, 1]))]),
                ]
                for kind, ppx in extreme_specs:
                    try:
                        pb = np.array(pixel_to_board(latest_H, float(ppx[0]), float(ppx[1])), dtype=np.float32)
                    except Exception:
                        continue
                    outward = pb - cb
                    edge_boost = 20.0 if solidity <= float(args.targeted_press_solidity_threshold) else 8.0
                    score = edge_boost + max(0.0, (1.0 - solidity) * 35.0)
                    item = _targeted_candidate_from_problem(
                        kind,
                        score,
                        pb,
                        outward,
                        cb,
                        mask_u8,
                        f"edge extreme / inset-start / solidity={solidity:.3f}",
                        {"solidity": float(solidity)}
                    )
                    _add_targeted_candidate(item)
            except Exception as e:
                if args.grasp_debug:
                    print("[TARGET-PRESS-EDGE-WARN]", repr(e))

        if not raw_candidates:
            latest_targeted_press_plan = None
            latest_targeted_press_status = f"no inset targeted candidates. solidity={solidity:.3f}"
            if print_result:
                print(f"[TARGET-PRESS] {latest_targeted_press_status}")
            return None

        def _target_kind_rank(item: Dict[str, Any]) -> int:
            k = str(item.get("kind", ""))
            if k == "wrinkle":
                return 3
            if k == "concavity":
                return 2
            if k.startswith("edge_"):
                return 1
            return 0
        raw_candidates.sort(key=lambda x: (_target_kind_rank(x), float(x.get("score", 0.0))), reverse=True)
        selected: List[Dict[str, Any]] = []
        sep = max(0.0, float(args.targeted_press_min_separation_mm))
        for item in raw_candidates:
            sxy = np.asarray(item.get("start_board_xy", [0.0, 0.0]), dtype=np.float32)
            if all(float(np.linalg.norm(sxy - np.asarray(sel.get("start_board_xy", [0.0, 0.0]), dtype=np.float32))) >= sep
                   for sel in selected):
                selected.append(item)
            if len(selected) >= max(1, int(args.targeted_press_max_candidates)):
                break

        latest_targeted_press_plan = {
            "candidates": selected,
            "status": "OK",
            "source_class": str(cand.get("class_name", "?")) if isinstance(cand, dict) else "?",
            "solidity": float(solidity),
            "center_board": [float(center_board[0]), float(center_board[1])],
            "summary": f"inset targeted press preview candidates={len(selected)} solidity={solidity:.3f} inset={float(args.targeted_press_inset_mm):.1f}mm",
        }
        latest_targeted_press_status = "OK"

        if print_result:
            print("\n========== TARGETED PRESS PREVIEW (STEP29 INSET) ==========")
            print(latest_targeted_press_plan["summary"])
            print("Preview only: robot will NOT move. Targets may come from wrinkle heatmap, edge/concavity; PRESS point is on cloth.")
            for idx, item in enumerate(selected, 1):
                pxy = item.get("problem_board_xy", [0, 0])
                sxy = item.get("start_board_xy", [0, 0])
                exy = item.get("end_board_xy", [0, 0])
                print(f"{idx:02d}. {item.get('kind')} arm={item.get('arm_key','?').upper()} "
                      f"score={float(item.get('score',0)):.1f} local={float(item.get('local_mask_ratio',0)):.2f} "
                      f"problem=({pxy[0]:.1f},{pxy[1]:.1f}) press=({sxy[0]:.1f},{sxy[1]:.1f}) -> end=({exy[0]:.1f},{exy[1]:.1f}) "
                      f"{item.get('reason','')}")
            print("==========================================================\n")
        return latest_targeted_press_plan

    def get_arm_boundary_recovery_grip_z(arm_key: str) -> float:
        if args.boundary_recovery_grip_z is not None:
            return float(args.boundary_recovery_grip_z)
        return float(get_arm_grip_z(arm_key))

    def _boundary_board_points_from_plan(plan: Optional[Dict[str, Any]] = None) -> Optional[np.ndarray]:
        """Sample the current cloth/object mask as board coordinates for boundary recovery."""
        try:
            src_plan = latest_coarse_plan if plan is None else plan
            cand = None
            if isinstance(src_plan, dict):
                cand = src_plan.get("candidate", {})
            if not cand and latest_candidate is not None:
                cand = latest_candidate
            if not cand:
                return None
            contour = cand.get("contour") if isinstance(cand, dict) else None
            image_shape = cand.get("image_shape") if isinstance(cand, dict) else None
            if contour is None or image_shape is None or latest_H is None:
                return None
            mask = _mask_u8_from_contour(contour, image_shape)
            _pts, board = _mask_pixels_with_board_coords(mask, latest_H, max_points=32000)
            if board is None or len(board) < 20:
                return None
            return board.astype(np.float32)
        except Exception as e:
            print(f"[BOUNDARY-WARN] failed to sample mask board points: {repr(e)}")
            return None

    def _choose_boundary_primary_side(board: np.ndarray) -> Tuple[Optional[str], Dict[str, Any]]:
        """Choose the boundary side that needs recovery.

        Step24 still sometimes picked top/bottom because it simply chose the edge band
        with the largest number of mask points. For a garment slightly protruding left,
        the top/bottom band can contain more pixels than the left band, and then the
        planner may choose ARM1. Step25 prioritizes left/right edge violations when
        x-edge danger is present.
        """
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        margin = float(args.boundary_recovery_margin)
        min_edge = max(1, int(args.boundary_recovery_min_edge_points))

        edge_masks = {
            "left": board[:, 0] <= min_bx + margin,
            "right": board[:, 0] >= max_bx - margin,
            "bottom": board[:, 1] <= min_by + margin,
            "top": board[:, 1] >= max_by - margin,
        }
        counts = {k: int(np.count_nonzero(v)) for k, v in edge_masks.items()}

        scores: Dict[str, float] = {}
        for side, mask in edge_masks.items():
            if not np.any(mask):
                scores[side] = 0.0
                continue
            pts = board[mask]
            if side == "left":
                depth = float((min_bx + margin) - np.percentile(pts[:, 0], 15))
            elif side == "right":
                depth = float(np.percentile(pts[:, 0], 85) - (max_bx - margin))
            elif side == "bottom":
                depth = float((min_by + margin) - np.percentile(pts[:, 1], 15))
            else:  # top
                depth = float(np.percentile(pts[:, 1], 85) - (max_by - margin))
            scores[side] = max(0.0, depth) + 0.05 * float(counts[side])

        eligible = {k: counts[k] for k in counts if counts[k] >= min_edge}
        info = {"counts": counts, "scores": scores, "status": "edge detected"}

        if bool(args.boundary_recovery_debug_side_scores):
            print(f"[BOUNDARY-SIDE] counts={counts} scores={{{', '.join(f'{k}:{v:.1f}' for k, v in scores.items())}}} prefer_lr={bool(args.boundary_recovery_prefer_lr_edges)}")

        if not eligible:
            info["status"] = f"no edge count >= {min_edge}"
            return None, info

        if bool(args.boundary_recovery_prefer_lr_edges):
            lr_eligible = {k: counts[k] for k in ("left", "right") if counts.get(k, 0) >= min_edge}
            if lr_eligible:
                side = max(lr_eligible.keys(), key=lambda k: (scores.get(k, 0.0), counts.get(k, 0)))
                info["side"] = side
                info["status"] = "left/right priority edge detected"
                return side, info

        side = max(eligible.keys(), key=lambda k: (scores.get(k, 0.0), counts.get(k, 0)))
        info["side"] = side
        return side, info

    def _boundary_pull_vector(side: str) -> Tuple[float, float]:
        if side == "left":
            return (1.0, 0.0)
        if side == "right":
            return (-1.0, 0.0)
        if side == "top":
            return (0.0, -1.0)
        if side == "bottom":
            return (0.0, 1.0)
        return (0.0, 0.0)

    def _boundary_candidate_for_arm(board: np.ndarray, side: str, arm_key: str) -> Optional[Tuple[float, float, int]]:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        edge_band = max(20.0, float(args.boundary_recovery_edge_band_mm))
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        dead = float(args.workspace_dead_half_width)

        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        target_safe = ((board[:, 0] >= min_bx + target_margin) & (board[:, 0] <= max_bx - target_margin) &
                       (board[:, 1] >= min_by + target_margin) & (board[:, 1] <= max_by - target_margin))

        if arm_key == "arm2":
            arm_side = board[:, 0] <= (split_x - dead)
        else:
            arm_side = board[:, 0] >= (split_x + dead)

        if side == "left":
            edge = board[:, 0] <= min_bx + edge_band
        elif side == "right":
            edge = board[:, 0] >= max_bx - edge_band
        elif side == "top":
            edge = board[:, 1] >= max_by - edge_band
        elif side == "bottom":
            edge = board[:, 1] <= min_by + edge_band
        else:
            edge = np.zeros(len(board), dtype=bool)

        min_pts = max(3, int(args.boundary_recovery_min_inside_points) // 3)

        masks_to_try = [
            target_safe & arm_side & edge,
            board_inside & arm_side & edge,
            target_safe & arm_side,
            board_inside & arm_side,
        ]

        idxs = np.array([], dtype=int)
        for mask in masks_to_try:
            cand = np.where(mask)[0]
            if len(cand) >= min_pts:
                idxs = cand
                break

        if len(idxs) < min_pts:
            return None

        pts = board[idxs]
        if side == "left":
            pick_idx = int(np.argmin(pts[:, 0]))
        elif side == "right":
            pick_idx = int(np.argmax(pts[:, 0]))
        elif side == "top":
            pick_idx = int(np.argmax(pts[:, 1]))
        elif side == "bottom":
            pick_idx = int(np.argmin(pts[:, 1]))
        else:
            pick_idx = 0

        bx, by = float(pts[pick_idx, 0]), float(pts[pick_idx, 1])
        # Final command target is always clamped inside the board safety margin.
        bx, by = _clamp_board_xy(bx, by, target_margin)
        return bx, by, int(len(idxs))

    def _boundary_candidate_for_opposite_drag_arm(board: np.ndarray, side: str, arm_key: str) -> Optional[Tuple[float, float, int]]:
        """Choose a stable internal cloth point for key 9 center-axis correction.

        Key 9 policy in step_a3:
          - If cloth is biased toward ID0/ID1 side (left), ARM1 uses a visible point
            on the ID2/ID3-side part of the cloth and drags +x.
          - If cloth is biased toward ID2/ID3 side (right), ARM2 uses a visible point
            on the ID0/ID1-side part of the cloth and drags -x.

        The selected point is not the garment edge.  It is an actual mask sample near
        the pulling-side cloth band, then inset toward the cloth center by
        --boundary-recovery-pick-inset-mm.
        """
        if side not in ("left", "right"):
            return _boundary_candidate_for_arm(board, side, arm_key)

        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        dead = float(args.workspace_dead_half_width)
        min_pts = max(3, int(args.boundary_recovery_min_inside_points) // 3)
        inset = max(0.0, float(getattr(args, "boundary_recovery_pick_inset_mm", 45.0)))

        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        target_safe = ((board[:, 0] >= min_bx + target_margin) & (board[:, 0] <= max_bx - target_margin) &
                       (board[:, 1] >= min_by + target_margin) & (board[:, 1] <= max_by - target_margin))

        if arm_key == "arm2":
            arm_side = board[:, 0] <= (split_x - dead)
        else:
            arm_side = board[:, 0] >= (split_x + dead)

        # Use actual visible cloth samples.  Prefer safe samples in the selected arm's workspace.
        masks_to_try = [
            target_safe & arm_side,
            board_inside & arm_side,
            target_safe,
            board_inside,
        ]
        idxs = np.array([], dtype=int)
        for mask in masks_to_try:
            cand = np.where(mask)[0]
            if len(cand) >= min_pts:
                idxs = cand
                break
        if len(idxs) < min_pts:
            return None

        pts = board[idxs].astype(np.float32)
        all_inside = board[board_inside].astype(np.float32)
        if len(all_inside) >= 10:
            cloth_center = np.median(all_inside[:, :2], axis=0).astype(np.float32)
        else:
            cloth_center = np.median(board[:, :2], axis=0).astype(np.float32)

        if side == "left":
            edge_idx = int(np.argmax(pts[:, 0]))
        else:
            edge_idx = int(np.argmin(pts[:, 0]))
        edge_pt = pts[edge_idx, :2].copy().astype(np.float32)

        v_in = cloth_center.astype(np.float32) - edge_pt
        n_in = float(np.linalg.norm(v_in))
        if n_in > 1e-6 and inset > 0.0:
            desired = edge_pt + (v_in / n_in) * min(inset, n_in * 0.92)
        else:
            desired = edge_pt.copy()

        # the camera overlay and the commanded pick point must be the DEEP internal point,
        # not the original edge-side sampled pixel.  The old nearest-sample fallback could still snap
        # back to a contour/edge pixel when the board-sampled mask was sparse.  Here we use the inward
        # target directly so the displayed point moves clearly inside the garment.
        min_ratio = float(np.clip(getattr(args, "boundary_recovery_min_internal_ratio", 0.62), 0.0, 0.90))
        if n_in > 1e-6:
            deep_len = min(max(inset, n_in * min_ratio), n_in * 0.88)
            deep_pick = edge_pt + (v_in / n_in) * deep_len
        else:
            deep_pick = edge_pt.copy()

        # fix:
        # Deep inward points can cross into the center dead zone.  Then the camera overlay
        # shows a plausible cloth point, but resolve_board_target_for_arm blocks it as
        # belongs_to=None.  Keep the final displayed/commanded pick inside the assigned
        # arm workspace while still moving as far inward as possible along edge->center.
        ws_margin = max(0.0, float(getattr(args, "deep_internal_pick_workspace_margin_mm", 12.0)))
        if n_in > 1e-6:
            if arm_key == "arm1":
                arm_min_x = float(split_x + dead + ws_margin)
                if float(deep_pick[0]) < arm_min_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_min_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = max(float(deep_pick[0]), arm_min_x)
            else:
                arm_max_x = float(split_x - dead - ws_margin)
                if float(deep_pick[0]) > arm_max_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_max_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = min(float(deep_pick[0]), arm_max_x)

        # Keep the generated point safely on the board, but do not snap it back to the edge sample.
        deep_pick[0] = float(np.clip(deep_pick[0], min_bx + target_margin, max_bx - target_margin))
        deep_pick[1] = float(np.clip(deep_pick[1], min_by + target_margin, max_by - target_margin))
        d_support = np.linalg.norm(pts[:, :2] - deep_pick.reshape(1, 2), axis=1)
        support_dist = float(np.min(d_support)) if len(d_support) else -1.0
        bx, by = float(deep_pick[0]), float(deep_pick[1])
        print(f"[BOUNDARY-DEEP-INTERNAL-PICK] {arm_key.upper()} side={side} edge=({edge_pt[0]:.1f},{edge_pt[1]:.1f}) "
              f"center=({cloth_center[0]:.1f},{cloth_center[1]:.1f}) inset={inset:.1f} ratio={min_ratio:.2f} "
              f"pick=({bx:.1f},{by:.1f}) ws_margin={float(getattr(args, 'deep_internal_pick_workspace_margin_mm', 12.0)):.1f} nearest_mask_sample_dist={support_dist:.1f}mm")
        return bx, by, int(len(idxs))

    def _choose_boundary_center_bias_side(board: np.ndarray) -> Tuple[Optional[str], Dict[str, Any]]:
        """Classify cloth bias using the board center axis, not edge counts.

        Returns side='left' when the cloth mass center is closer to ID0/ID1 side and
        needs to be pulled toward ID2/ID3; side='right' is the mirror case.
        """
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        center_axis_x = 0.5 * (float(min_bx) + float(max_bx))
        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        pts = board[board_inside] if int(np.count_nonzero(board_inside)) >= 10 else board
        if pts is None or len(pts) < 10:
            return None, {"status": "not enough board mask points", "counts": {}}

        center_x = float(np.median(pts[:, 0]))
        mean_x = float(np.mean(pts[:, 0]))
        delta = center_x - center_axis_x
        deadband = max(0.0, float(getattr(args, "boundary_recovery_bias_deadband_mm", 25.0)))

        left_count = int(np.count_nonzero(pts[:, 0] < center_axis_x))
        right_count = int(np.count_nonzero(pts[:, 0] > center_axis_x))
        info = {
            "status": "center-axis bias detected",
            "center_axis_x": float(center_axis_x),
            "cloth_median_x": float(center_x),
            "cloth_mean_x": float(mean_x),
            "delta_x": float(delta),
            "deadband_mm": float(deadband),
            "counts": {"left_of_axis": left_count, "right_of_axis": right_count},
        }
        if abs(delta) < deadband:
            info["status"] = f"centered within deadband {deadband:.1f}mm"
            return None, info
        side = "left" if delta < 0.0 else "right"
        info["side"] = side
        return side, info

    def build_boundary_recovery_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Build a one-shot grip pull-in plan using only safe inside-board cloth pixels."""
        nonlocal latest_boundary_plan, latest_boundary_status
        if not bool(args.boundary_recovery_mode):
            latest_boundary_plan, latest_boundary_status = None, "boundary_recovery_mode OFF"
            return None

        board = _boundary_board_points_from_plan(plan)
        if board is None or len(board) < 20:
            latest_boundary_plan, latest_boundary_status = None, "no current mask board points"
            if print_result:
                print(f"[BOUNDARY] not ready: {latest_boundary_status}")
            return None

        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        inside_safe = ((board[:, 0] >= min_bx + target_margin) & (board[:, 0] <= max_bx - target_margin) &
                       (board[:, 1] >= min_by + target_margin) & (board[:, 1] <= max_by - target_margin))
        inside_count = int(np.count_nonzero(inside_safe))
        if inside_count < int(args.boundary_recovery_min_inside_points):
            latest_boundary_plan = None
            latest_boundary_status = f"not enough safe inside cloth points: {inside_count}/{int(args.boundary_recovery_min_inside_points)}"
            if print_result:
                print(f"[BOUNDARY] not ready: {latest_boundary_status}")
            return None

        side, side_info = _choose_boundary_center_bias_side(board)
        if side is not None:
            print(f"[BOUNDARY-CENTER-BIAS] selected side={side} median_x={side_info.get('cloth_median_x'):.1f} "
                  f"axis_x={side_info.get('center_axis_x'):.1f} delta={side_info.get('delta_x'):.1f} "
                  f"deadband={side_info.get('deadband_mm'):.1f}")
        if side is None:
            latest_boundary_plan = None
            latest_boundary_status = f"OK/no center-axis correction needed: {side_info.get('status','?')} info={side_info}"
            if print_result:
                print(f"[BOUNDARY] {latest_boundary_status}")
            return None
        if bool(args.boundary_recovery_lr_only) and side not in ("left", "right"):
            latest_boundary_plan = None
            latest_boundary_status = f"left/right-only mode: detected side={side}, so boundary drag is skipped for now. Use --no-boundary-recovery-lr-only to allow top/bottom."
            if print_result:
                print(f"[BOUNDARY] {latest_boundary_status}")
            return None

        use_cross_pull_lr = bool(getattr(args, "boundary_recovery_cross_pull_lr", False)) and side in ("left", "right")
        if use_cross_pull_lr:
            preferred_arms = ["arm1"] if side == "left" else ["arm2"]
        elif bool(args.boundary_recovery_strict_side_arm) and side in ("left", "right"):
            preferred_arms = ["arm2"] if side == "left" else ["arm1"]
        else:
            preferred_arms = {
                "left": ["arm2", "arm1"],
                "right": ["arm1", "arm2"],
                "top": ["arm2", "arm1"],
                "bottom": ["arm2", "arm1"],
            }.get(side, ["arm2", "arm1"])

        chosen = None
        candidate_debug = []
        for arm_key in preferred_arms:
            if use_cross_pull_lr:
                cand = _boundary_candidate_for_opposite_drag_arm(board, side, arm_key)
            else:
                cand = _boundary_candidate_for_arm(board, side, arm_key)
            candidate_debug.append((arm_key, cand))
            if cand is not None:
                chosen = (arm_key, cand)
                break
        if chosen is None:
            latest_boundary_plan = None
            latest_boundary_status = f"no reachable safe inside point for side={side}, candidates={candidate_debug}"
            if print_result:
                print(f"[BOUNDARY] not ready: {latest_boundary_status}")
            return None

        arm_key, (start_bx, start_by, npts) = chosen
        ux, uy = _boundary_pull_vector(side)
        dist = max(0.0, float(args.boundary_recovery_pull_distance))
        end_bx, end_by = _clamp_board_xy(start_bx + ux * dist, start_by + uy * dist, target_margin)

        hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
        hover = resolve_board_target_for_arm(arm_key, start_bx, start_by, hover_z, "BOUNDARY-HOVER")

        if bool(args.boundary_recovery_drag_mode):
            # Contact-drag recovery: do not grip/lift the cloth.  The gripper is used like a padded
            # contact tool, then the arm drags the visible edge area a short distance toward board center.
            contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
            if args.boundary_recovery_drag_clear_z is not None:
                clear_z = float(args.boundary_recovery_drag_clear_z)
            elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
                clear_z = float(args.press_extra_clear_z)
            elif args.press_clear_z is not None:
                clear_z = float(args.press_clear_z)
            else:
                clear_z = float(hover_z)

            down_raw = resolve_board_target_for_arm(arm_key, start_bx, start_by, contact_z, "BOUNDARY-DRAG-DOWN")
            drag_raw = resolve_board_target_for_arm(arm_key, end_bx, end_by, contact_z, "BOUNDARY-DRAG-IN")
            down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "BOUNDARY-DRAG-DOWN")
            drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "BOUNDARY-DRAG-IN")
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is None or down is None or drag is None or clear is None:
                latest_boundary_plan = None
                latest_boundary_status = f"resolved drag target blocked for {arm_key.upper()} side={side}"
                if print_result:
                    print(f"[BOUNDARY] not ready: {latest_boundary_status}")
                return None

            mode = "drag"
            summary_prefix = "boundary contact-drag pull-in"
            extra_targets = {
                "hover": hover, "down": down, "drag": drag, "clear": clear,
                "down_raw": down_raw, "drag_raw": drag_raw,
                "contact_offset_roarm": [
                    float(getattr(args, f"boundary_recovery_{arm_key}_contact_offset_x", 0.0)),
                    float(getattr(args, f"boundary_recovery_{arm_key}_contact_offset_y", 0.0)),
                ],
            }
            z_info = {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)}
            sequence_text = "padded-close -> hover -> vertical contact down -> low-z drag inward -> vertical clear -> open -> standby/reinfer"
        else:
            # Legacy recovery: grip-close, lift, pull, air-release.
            grip_z = get_arm_boundary_recovery_grip_z(arm_key)
            lift_z = float(args.boundary_recovery_lift_z)
            down = resolve_board_target_for_arm(arm_key, start_bx, start_by, grip_z, "BOUNDARY-GRIP-DOWN")
            lift = resolve_board_target_for_arm(arm_key, start_bx, start_by, lift_z, "BOUNDARY-LIFT")
            pull = resolve_board_target_for_arm(arm_key, end_bx, end_by, lift_z, "BOUNDARY-PULL")
            clear = resolve_board_target_for_arm(arm_key, end_bx, end_by, hover_z, "BOUNDARY-CLEAR")
            if hover is None or down is None or lift is None or pull is None or clear is None:
                latest_boundary_plan = None
                latest_boundary_status = f"resolved target blocked for {arm_key.upper()} side={side}"
                if print_result:
                    print(f"[BOUNDARY] not ready: {latest_boundary_status}")
                return None

            mode = "grip_lift"
            summary_prefix = "boundary grip pull-in"
            extra_targets = {"hover": hover, "down": down, "lift": lift, "pull": pull, "clear": clear}
            z_info = {"hover_z": float(hover_z), "grip_z": float(grip_z), "lift_z": float(lift_z)}
            sequence_text = "open -> hover -> down -> close -> lift -> pull-in -> air release -> vertical clear -> standby/reinfer"

        latest_boundary_plan = {
            "mode": mode,
            "side": side,
            "arm_key": arm_key,
            "counts": side_info.get("counts", {}),
            "inside_count": inside_count,
            "reachable_points": npts,
            "start_board_xy": [float(start_bx), float(start_by)],
            "end_board_xy": [float(end_bx), float(end_by)],
            "pull_vector": [float(ux), float(uy)],
            "pull_distance": float(dist),
            "z_info": z_info,
            **extra_targets,
            "summary": (f"{summary_prefix} side={side} arm={arm_key.upper()} cross_pull_lr={bool(getattr(args, 'boundary_recovery_cross_pull_lr', False))} strict_side={bool(args.boundary_recovery_strict_side_arm)} prefer_lr={bool(args.boundary_recovery_prefer_lr_edges)} "
                        f"start=({start_bx:.1f},{start_by:.1f}) -> end=({end_bx:.1f},{end_by:.1f}) "
                        f"dist={dist:.1f}mm inside={inside_count} reachable={npts} counts={side_info.get('counts', {})}"),
        }
        latest_boundary_status = "OK"
        if print_result:
            print("\n========== BOUNDARY RECOVERY PLAN ==========")
            print(latest_boundary_plan["summary"])
            print(f"mode={mode} z_info={z_info}")
            print(f"Sequence: {sequence_text}")
            print("Only safe inside-board mask points are used as contact/grip targets; outside-board cloth is not chased.")
            print("===========================================\n")
        return latest_boundary_plan

    def boundary_grip_pull_in():
        nonlocal latest_boundary_plan, latest_boundary_status, coarse_x_since_last_press
        if not bool(args.boundary_recovery_mode):
            print("[BOUNDARY] boundary recovery mode is OFF")
            return
        plan = None
        if bool(args.boundary_recovery_fresh_snapshot) and snapshot_mode:
            plan = request_fresh_coarse_plan_and_wait(
                reason="before boundary recovery",
                timeout=float(args.boundary_recovery_fresh_timeout),
            )
        else:
            plan = latest_coarse_plan
        bp = build_boundary_recovery_plan(plan, print_result=True)
        if bp is None:
            return

        preview_wait = max(0.0, float(getattr(args, "boundary_recovery_preview_wait", 0.0)))
        if preview_wait > 0.0:
            print(f"[BOUNDARY-PREVIEW] showing selected contact point/drag vector for {preview_wait:.2f}s before motion")
            time.sleep(preview_wait)

        if not send_enabled:
            print("[DRY-RUN] Boundary recovery commands not sent.")
            return

        arm_key = bp["arm_key"]
        arm_obj = arms.get(arm_key)
        if arm_obj is None:
            print(f"[BOUNDARY-BLOCKED] {arm_key.upper()} is not connected.")
            return

        mode = str(bp.get("mode", "grip_lift"))
        if mode == "drag":
            drag_gripper = float(args.boundary_recovery_drag_gripper)
            drag_speed = float(args.boundary_recovery_drag_speed)
            print("\n========== BOUNDARY CONTACT-DRAG PULL-IN (9) ==========")
            print(bp["summary"])
            print(f"drag_gripper={drag_gripper:.3f}, contact_z={bp.get('z_info', {}).get('contact_z')}, clear_z={bp.get('z_info', {}).get('clear_z')}, speed={drag_speed:.2f}")
            print("This does NOT grip/lift the cloth. It presses lightly and drags the visible edge area inward.")
            print("If the cloth is dragged too hard, raise --boundary-recovery-drag-z or reduce --boundary-recovery-drag-gripper.")
            print("Keep emergency power cutoff ready.")
            print("=======================================================\n")

            arm_obj.torque_on()
            print(f"[BOUNDARY-PADDED-CLOSE] {arm_key.upper()} contact gripper angle={drag_gripper:.3f}")
            arm_obj.set_gripper(drag_gripper, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(0.15)

            hover = bp["hover"]
            print(f"[BOUNDARY-HOVER] {arm_key.upper()} move: ({hover['rx']:.1f},{hover['ry']:.1f},{hover['rz']:.1f})")
            arm_obj.move_goal(args.move_command, hover["rx"], hover["ry"], hover["rz"], t=args.t, spd=spd_default)
            time.sleep(0.25)

            down = bp["down"]
            print(f"[BOUNDARY-CONTACT-DOWN] {arm_key.upper()} move: ({down['rx']:.1f},{down['ry']:.1f},{down['rz']:.1f})")
            arm_obj.move_goal(args.move_command, down["rx"], down["ry"], down["rz"], t=args.t, spd=drag_speed)
            time.sleep(max(0.0, float(args.boundary_recovery_drag_down_wait)))

            drag = bp["drag"]
            print(f"[BOUNDARY-DRAG-IN] {arm_key.upper()} drag low: ({drag['rx']:.1f},{drag['ry']:.1f},{drag['rz']:.1f})")
            arm_obj.move_goal(args.move_command, drag["rx"], drag["ry"], drag["rz"], t=args.t, spd=drag_speed)
            time.sleep(max(0.0, float(args.boundary_recovery_drag_sweep_wait)))

            clear = bp["clear"]
            print(f"[BOUNDARY-VERTICAL-CLEAR] {arm_key.upper()} clear at same XY: ({clear['rx']:.1f},{clear['ry']:.1f},{clear['rz']:.1f})")
            arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=args.t, spd=spd_default)
            time.sleep(0.25)

            if bool(args.boundary_recovery_drag_open_after_clear):
                print(f"[BOUNDARY-OPEN-AFTER-CLEAR] {arm_key.upper()} open angle={float(args.grip_open):.3f}")
                arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
                time.sleep(float(args.boundary_recovery_release_wait))
        else:
            print("\n========== BOUNDARY GRIP PULL-IN ==========")
            print(bp["summary"])
            print(f"grip_open={args.grip_open:.3f}, grip_close={args.grip_close:.3f}, lift_z={float(args.boundary_recovery_lift_z):.1f}")
            print("Keep emergency power cutoff ready. This is a one-shot inward grip pull.")
            print("==========================================\n")

            arm_obj.torque_on()
            arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(float(args.boundary_recovery_open_wait))

            for pose_name in ("hover", "down"):
                tgt = bp[pose_name]
                tval = float(args.grip_open)
                print(f"[BOUNDARY-{pose_name.upper()}] {arm_key.upper()} move: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=tval, spd=spd_default)
                time.sleep(0.25 if pose_name == "hover" else 0.20)

            print(f"[BOUNDARY-CLOSE] {arm_key.upper()} close angle={float(args.grip_close):.3f}")
            arm_obj.set_gripper(float(args.grip_close), spd=args.grip_spd, acc=args.grip_acc, delay=0.25)
            time.sleep(float(args.boundary_recovery_close_wait))

            for pose_name in ("lift", "pull"):
                tgt = bp[pose_name]
                print(f"[BOUNDARY-{pose_name.upper()}] {arm_key.upper()} move: ({tgt['rx']:.1f},{tgt['ry']:.1f},{tgt['rz']:.1f})")
                arm_obj.move_goal(args.move_command, tgt["rx"], tgt["ry"], tgt["rz"], t=float(args.grip_close), spd=spd_default)
                time.sleep(float(args.boundary_recovery_lift_wait))

            print(f"[BOUNDARY-RELEASE] {arm_key.upper()} open at pulled lift pose")
            arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.25)
            time.sleep(float(args.boundary_recovery_release_wait))

            clear = bp["clear"]
            print(f"[BOUNDARY-CLEAR] {arm_key.upper()} vertical clear: ({clear['rx']:.1f},{clear['ry']:.1f},{clear['rz']:.1f})")
            arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=float(args.grip_open), spd=spd_default)
            time.sleep(0.25)

        # Boundary recovery changes the cloth pose, so the X->auto-press cycle should start over.
        coarse_x_since_last_press = 0
        _reset_coarse_auto_press_cycle("cloth changed: boundary recovery executed")

        if args.imaging_standby and not args.no_standby:
            move_arms_to_standby(reason="after boundary recovery")
        if bool(args.boundary_recovery_reinfer_after) and snapshot_mode:
            request_fresh_coarse_plan_and_wait(
                reason="after boundary recovery",
                timeout=float(args.boundary_recovery_fresh_timeout),
            )
        elif args.auto_reinfer_after_motion:
            reset_snapshot("boundary recovery finished; waiting for fresh still frame")




    # ============================================================
    # variable ArUco-frame side/corner overflow recovery
    # ============================================================

    def _expanded_board_mask_for_variable_overflow(image_shape, expand_mm: float) -> Optional[np.ndarray]:
        """ArUco rectangle mask expanded in board-mm, then projected back to pixels.

        This is intentionally larger than the normal board/planning mask.  It lets key
        '/' measure cloth that protrudes beyond marker sides, while all robot contact
        points remain selected from the clipped planning mask later.
        """
        try:
            if latest_H is None:
                return None
            h, w = image_shape[:2]
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            e = max(0.0, float(expand_mm))
            board_corners = [
                (min_bx - e, min_by - e),
                (max_bx + e, min_by - e),
                (max_bx + e, max_by + e),
                (min_bx - e, max_by + e),
            ]
            pts = []
            for bx, by in board_corners:
                pxy = board_to_pixel(latest_H, bx, by)
                if pxy is None:
                    return None
                x = int(round(float(pxy[0]))); y = int(round(float(pxy[1])))
                x = max(-w, min(2 * w, x)); y = max(-h, min(2 * h, y))
                pts.append([x, y])
            mask = np.zeros((h, w), dtype=np.uint8)
            cv2.fillConvexPoly(mask, np.asarray(pts, dtype=np.int32).reshape(-1, 1, 2), 255)
            return mask
        except Exception:
            return None

    def _variable_overflow_filter_components(mask_u8: np.ndarray, image_shape, source: str) -> Tuple[Optional[np.ndarray], str]:
        """Keep raw garment-mask components for key '/' overflow.

        Step_a26 fix:
          - Earlier versions required every component to overlap the ArUco board.
            That drops protruding cloth when the outside part is split by a small
            segmentation gap. Now the board-overlapping garment component is used as
            a seed and nearby outside components are preserved.
        """
        try:
            if mask_u8 is None:
                return None, f"{source}: no mask"
            h, w = image_shape[:2]
            m = (mask_u8.astype(np.uint8) > 0).astype(np.uint8) * 255
            if latest_H is None:
                return None, f"{source}: no Homography"
            expand_mm = float(getattr(args, "variable_overflow_raw_expand_mm", 160.0))
            roi_mask = _expanded_board_mask_for_variable_overflow(image_shape, expand_mm=expand_mm)
            if roi_mask is not None:
                m = cv2.bitwise_and(m, roi_mask.astype(np.uint8))
            board_mask = board_polygon_mask_from_h(latest_H, cfg, image_shape, shrink_px=0).astype(np.uint8)
            min_total = float(getattr(args, "variable_overflow_raw_min_area_px", 900.0))
            min_inside = float(getattr(args, "variable_overflow_component_min_inside_area_px", 180.0))
            piece_min = max(80.0, min_total * 0.08)
            gap_px = max(0, int(getattr(args, "variable_overflow_connect_gap_px", 55)))

            seed = cv2.bitwise_and(m, board_mask)
            if gap_px > 0 and int(np.count_nonzero(seed)) > 0:
                gk = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (gap_px | 1, gap_px | 1))
                seed_near = cv2.dilate(seed, gk, iterations=1)
            else:
                seed_near = seed

            bridge_px = max(3, int(getattr(args, "full_garment_frame_dilate_bridge_px", 17)) | 1)
            bk = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (bridge_px, bridge_px))
            m_for_cc = cv2.dilate(m, bk, iterations=1)

            num, labels, stats, _cent = cv2.connectedComponentsWithStats((m_for_cc > 0).astype(np.uint8), connectivity=8)
            kept = np.zeros((h, w), dtype=np.uint8)
            kept_count = 0
            kept_area = 0.0
            kept_inside = 0.0
            kept_near = 0.0
            for lab in range(1, int(num)):
                cc = (labels == lab)
                comp_u8 = ((cc & (m > 0))).astype(np.uint8) * 255
                area = float(np.count_nonzero(comp_u8))
                if area < piece_min:
                    continue
                comp_bool = comp_u8 > 0
                inside_area = float(np.count_nonzero(comp_bool & (board_mask > 0)))
                near_area = float(np.count_nonzero(comp_bool & (seed_near > 0)))
                if inside_area < min_inside and near_area < 30.0:
                    continue
                kept = cv2.bitwise_or(kept, comp_u8)
                kept_count += 1
                kept_area += area
                kept_inside += inside_area
                kept_near += near_area
            if kept_count <= 0:
                return None, f"{source}: no component connected/near board seed"
            if kept_area < min_total:
                return None, f"{source}: kept foreground too small area={kept_area:.0f}px < {min_total:.0f}px"
            return kept, f"{source}(kept_area={kept_area:.0f}px, inside={kept_inside:.0f}px, near={kept_near:.0f}px, parts={kept_count})"
        except Exception as e:
            return None, f"{source}: component filter failed {repr(e)}"

    def _variable_overflow_yolo_raw_mask() -> Tuple[Optional[np.ndarray], str]:
        """Full-frame YOLO garment mask for key '/'.  This is never board-clipped."""
        try:
            if not bool(getattr(args, "variable_overflow_prefer_yolo_raw_mask", True)):
                return None, "yolo_raw disabled"
            # do not secretly rerun YOLO during '/' by default.
            # The user wants judgment only at S/M or after post-motion stillness snapshots.
            # First use the latest stored raw full-frame mask from that snapshot.
            if latest_yolo_raw_mask is not None and snapshot_frame is not None and latest_yolo_raw_mask.shape[:2] == snapshot_frame.shape[:2]:
                filt, st = _variable_overflow_filter_components(latest_yolo_raw_mask, snapshot_frame.shape, "latest_yolo_raw_mask")
                if filt is not None:
                    return filt, st + "; " + str(latest_yolo_raw_status)
            if not bool(getattr(args, "variable_overflow_pose_neck_rerun_yolo_raw", False)):
                return None, "yolo_raw: rerun disabled; use latest_full_garment_mask/latest_yolo_raw_mask from snapshot"
            if grasp_model is None:
                return None, "yolo_raw: grasp model not loaded"
            if snapshot_frame is None:
                return None, "yolo_raw: no snapshot frame"
            # Optional one-shot segmentation directly on the frozen snapshot. Do not pass the
            # result through sanitize_candidates_for_planning(), because that clips to the board.
            snapshot_infer = _apply_perception_roi_to_frame(snapshot_frame)
            _canvas, raw_candidates = infer_grasp_candidates(
                grasp_model,
                snapshot_infer,
                conf=args.grasp_conf,
                imgsz=args.grasp_imgsz,
                classes=grasp_classes,
                no_filter=args.grasp_no_filter,
                debug=False,
                refine_candidates=False,
                upper_band_ratio=args.grasp_upper_band_ratio,
                inside_ratio=args.grasp_inside_ratio,
                local_mask_radius=args.grasp_local_mask_radius,
                min_local_mask_ratio=args.grasp_min_local_mask_ratio,
                contour_smooth_epsilon_ratio=args.grasp_contour_smooth_epsilon_ratio,
                score_debug=False,
            )
            if not raw_candidates:
                return None, "yolo_raw: no garment candidates"
            h, w = snapshot_frame.shape[:2]
            union = np.zeros((h, w), dtype=np.uint8)
            for cand in raw_candidates:
                contour = cand.get("raw_contour", cand.get("contour"))
                if contour is None:
                    continue
                cm = _mask_u8_from_contour(contour, snapshot_frame.shape)
                union = cv2.bitwise_or(union, cm.astype(np.uint8))
            union = _clip_mask_to_perception_roi(union, snapshot_frame.shape)
            if int(np.count_nonzero(union)) < 80:
                return None, "yolo_raw: empty union mask"
            filt, st = _variable_overflow_filter_components(union, snapshot_frame.shape, "yolo_raw_aruco_roi")
            if filt is None:
                return None, st
            return filt, st
        except Exception as e:
            return None, f"yolo_raw failed: {repr(e)}"

    def _expanded_raw_foreground_mask_for_variable_overflow() -> Tuple[Optional[np.ndarray], str]:
        """Return a raw garment mask for key '/' that includes marker-outside cloth.

        Step_a24 policy:
          1) Prefer full-frame YOLO segmentation without ArUco board clipping.
          2) If YOLO fails, use expanded empty-board foreground, but keep only components
             that overlap the normal board so table noise/shadows cannot become contact points.
        """
        try:
            try:
                if latest_full_garment_mask is not None and snapshot_frame is not None:
                    if latest_full_garment_mask.shape[:2] == snapshot_frame.shape[:2]:
                        filt, st = _variable_overflow_filter_components(
                            latest_full_garment_mask,
                            snapshot_frame.shape,
                            "latest_full_garment_mask"
                        )
                        if filt is not None:
                            return filt, st + "; " + str(latest_full_garment_status)
            except Exception:
                pass

            yolo_mask, yolo_status = _variable_overflow_yolo_raw_mask()
            if yolo_mask is not None:
                return yolo_mask, yolo_status

            if not bool(getattr(args, "variable_overflow_use_expanded_raw_fg", True)):
                return None, yolo_status + "; expanded_raw_fg disabled"
            if snapshot_frame is None:
                return None, yolo_status + "; expanded_raw_fg: no snapshot frame"
            if fallback_empty_gray is None:
                return None, yolo_status + "; expanded_raw_fg: no empty baseline; press E on empty board"
            if latest_H is None:
                return None, yolo_status + "; expanded_raw_fg: no Homography"
            frame = snapshot_frame
            h, w = frame.shape[:2]
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY).astype(np.float32)
            bg = fallback_empty_gray
            if bg.shape[:2] != gray.shape[:2]:
                bg = cv2.resize(bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
            expand_mm = float(getattr(args, "variable_overflow_raw_expand_mm", 160.0))
            roi_mask = _expanded_board_mask_for_variable_overflow(frame.shape, expand_mm=expand_mm)
            if roi_mask is None or int(np.count_nonzero(roi_mask)) < 100:
                return None, yolo_status + "; expanded_raw_fg: expanded ROI mask failed"

            diff = cv2.absdiff(gray, bg.astype(np.float32))
            thr = float(getattr(args, "variable_overflow_raw_diff_threshold", 18.0))
            fg_gray = (diff > thr)
            fg_lab = None
            try:
                if fallback_empty_lab is not None:
                    lab_now = cv2.cvtColor(frame, cv2.COLOR_BGR2LAB).astype(np.float32)
                    lab_bg = fallback_empty_lab
                    if lab_bg.shape[:2] != lab_now.shape[:2]:
                        lab_bg = cv2.resize(lab_bg.astype(np.float32), (w, h), interpolation=cv2.INTER_AREA)
                    ab = lab_now[:, :, 1:3] - lab_bg[:, :, 1:3]
                    abdist = np.sqrt(np.sum(ab * ab, axis=2))
                    fg_lab = abdist > max(8.0, thr * 0.55)
            except Exception:
                fg_lab = None
            if fg_lab is not None:
                fg_bool = (fg_gray | fg_lab) & (roi_mask > 0)
            else:
                fg_bool = fg_gray & (roi_mask > 0)
            fg = fg_bool.astype(np.uint8) * 255
            k = max(3, int(getattr(args, "variable_overflow_raw_morph_kernel", 7)) | 1)
            kernel = np.ones((k, k), np.uint8)
            fg = cv2.medianBlur(fg, 5)
            fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, kernel, iterations=1)
            fg = cv2.morphologyEx(fg, cv2.MORPH_CLOSE, kernel, iterations=2)
            filt, st = _variable_overflow_filter_components(
                fg, frame.shape,
                f"expanded_raw_fg(diff>{thr:.1f}, expand={expand_mm:.0f}mm; {yolo_status})"
            )
            if filt is None:
                return None, st
            return filt, st
        except Exception as e:
            return None, f"variable overflow raw mask failed: {repr(e)}"

    def _expanded_raw_foreground_board_points_for_variable_overflow() -> Tuple[Optional[np.ndarray], str]:
        mask, status = _expanded_raw_foreground_mask_for_variable_overflow()
        if mask is None:
            return None, status
        try:
            _pts, board = _mask_pixels_with_board_coords(mask, latest_H, max_points=65000)
            if board is None or len(board) < 20:
                return None, status + "; not enough board samples"
            return board.astype(np.float32), status
        except Exception as e:
            return None, status + f"; board transform failed: {repr(e)}"

    def _expanded_planning_board_points_for_variable_overflow() -> Tuple[Optional[np.ndarray], str]:
        """Select contact candidates from the same raw garment mask, clipped inside the board.

        Step_a24: the contact mask is an internal mask, not the raw edge.  A distance
        transform removes edge pixels so the robot presses/drags on a stable cloth
        interior point instead of a sleeve tip, contour boundary, or table noise.
        """
        if not bool(getattr(args, "variable_overflow_planning_from_expanded_fg", True)):
            return None, "expanded_fg_planning disabled"
        mask, status = _expanded_raw_foreground_mask_for_variable_overflow()
        if mask is None:
            return None, status
        try:
            if snapshot_frame is None or latest_H is None:
                return None, status + "; no snapshot/H"
            shrink = int(getattr(args, "planning_mask_board_shrink_px", 0))
            board_mask = board_polygon_mask_from_h(latest_H, cfg, snapshot_frame.shape, shrink_px=max(0, shrink))
            inside = cv2.bitwise_and(mask.astype(np.uint8), board_mask.astype(np.uint8))
            k = max(3, int(getattr(args, "planning_mask_morph_kernel", 5)) | 1)
            kernel = np.ones((k, k), np.uint8)
            inside = cv2.morphologyEx(inside, cv2.MORPH_CLOSE, kernel, iterations=1)
            inside = cv2.morphologyEx(inside, cv2.MORPH_OPEN, kernel, iterations=1)

            if int(np.count_nonzero(inside)) < 80:
                return None, status + "; internal planning: no inside-board garment pixels"

            dist = cv2.distanceTransform((inside > 0).astype(np.uint8), cv2.DIST_L2, 5)
            min_edge = float(getattr(args, "variable_overflow_contact_min_edge_dist_px", 16.0))
            internal = ((dist >= max(1.0, min_edge)) & (inside > 0)).astype(np.uint8) * 255
            if int(np.count_nonzero(internal)) < 80:
                weak_edge = max(4.0, min_edge * 0.55)
                internal = ((dist >= weak_edge) & (inside > 0)).astype(np.uint8) * 255
                if int(np.count_nonzero(internal)) < 80:
                    return None, status + f"; internal planning: no stable interior pixels edge>={min_edge:.1f}px"
                edge_status = f"edge_dist>={weak_edge:.1f}px_relaxed"
            else:
                edge_status = f"edge_dist>={min_edge:.1f}px"

            _pts, board = _mask_pixels_with_board_coords(internal, latest_H, max_points=52000)
            if board is None or len(board) < 20:
                return None, status + "; internal planning: not enough board samples"
            return board.astype(np.float32), "internal_cloth_planning_clip(" + edge_status + "); " + status
        except Exception as e:
            return None, status + f"; internal planning failed: {repr(e)}"

    def _candidate_board_points_for_variable_overflow(plan: Optional[Dict[str, Any]], use_raw: bool = True) -> Tuple[Optional[np.ndarray], Optional[Dict[str, Any]], str]:
        """Return garment mask samples in board mm for key '/' overflow planning.

        Step_a22 fix:
          - raw overflow measurement uses expanded foreground first, even if no YOLO candidate exists.
          - safe contact-point planning can also come from expanded foreground clipped inside the board.
          - if expanded raw foreground is required and unavailable, do not silently use a board-clipped contour.
        """
        try:
            cand = None
            if isinstance(plan, dict):
                cand = plan.get("candidate", {})
            if (not cand) and latest_candidate is not None:
                cand = latest_candidate
            if latest_H is None:
                return None, None, "no Homography"

            if bool(use_raw):
                fg_board, fg_src = _expanded_raw_foreground_board_points_for_variable_overflow()
                if fg_board is not None and len(fg_board) >= 20:
                    return fg_board.astype(np.float32), cand if isinstance(cand, dict) else None, fg_src
                if bool(getattr(args, "variable_overflow_require_expanded_raw_fg", True)):
                    return None, cand if isinstance(cand, dict) else None, fg_src + "; expanded raw foreground is required for outside-marker overflow"
                if not isinstance(cand, dict) or not cand:
                    return None, None, fg_src + "; no YOLO/planning candidate fallback"
                contour = cand.get("raw_contour", cand.get("contour"))
                image_shape = cand.get("raw_image_shape", cand.get("image_shape"))
                src = "raw_contour" if cand.get("raw_contour") is not None else "planning_contour_fallback"
                if bool(getattr(args, "fallback_print_debug", False)):
                    print(f"[VAR-OVERFLOW-RAW] expanded foreground unavailable: {fg_src}; fallback to {src}")
            else:
                if isinstance(cand, dict) and cand:
                    contour = cand.get("contour")
                    image_shape = cand.get("image_shape")
                    src = "planning_contour_preferred_deep_internal"
                    if contour is not None and image_shape is not None:
                        mask = _mask_u8_from_contour(contour, image_shape)
                        try:
                            board_mask = board_polygon_mask_from_h(latest_H, cfg, image_shape, shrink_px=max(0, int(getattr(args, "planning_mask_board_shrink_px", 0)))).astype(np.uint8)
                            mask = cv2.bitwise_and(mask.astype(np.uint8), board_mask)
                        except Exception:
                            pass
                        dist = cv2.distanceTransform((mask > 0).astype(np.uint8), cv2.DIST_L2, 5)
                        min_edge = float(getattr(args, "variable_overflow_contact_min_edge_dist_px", 28.0))
                        internal = ((dist >= max(1.0, min_edge)) & (mask > 0)).astype(np.uint8) * 255
                        if int(np.count_nonzero(internal)) < 80:
                            weak_edge = max(10.0, min_edge * 0.70)
                            internal = ((dist >= weak_edge) & (mask > 0)).astype(np.uint8) * 255
                            src = f"planning_contour_preferred_internal_relaxed_edge>={weak_edge:.1f}px"
                        else:
                            src = f"planning_contour_preferred_internal_edge>={min_edge:.1f}px"
                        _pts, board = _mask_pixels_with_board_coords(internal, latest_H, max_points=42000)
                        if board is not None and len(board) >= 20:
                            return board.astype(np.float32), cand, src
                fg_plan, fg_plan_src = _expanded_planning_board_points_for_variable_overflow()
                if fg_plan is not None and len(fg_plan) >= 20:
                    return fg_plan.astype(np.float32), cand if isinstance(cand, dict) else None, fg_plan_src
                if not isinstance(cand, dict) or not cand:
                    return None, None, fg_plan_src + "; no YOLO/planning candidate fallback"
                contour = cand.get("contour")
                image_shape = cand.get("image_shape")
                src = "planning_contour_fallback_after_expanded_failed"
                if bool(getattr(args, "fallback_print_debug", False)):
                    print(f"[VAR-OVERFLOW-PLAN] expanded planning unavailable: {fg_plan_src}; fallback to {src}")

            if contour is None or image_shape is None:
                return None, cand if isinstance(cand, dict) else None, f"{src}: no contour/image_shape"
            mask = _mask_u8_from_contour(contour, image_shape)
            _pts, board = _mask_pixels_with_board_coords(mask, latest_H, max_points=42000)
            if board is None or len(board) < 20:
                return None, cand if isinstance(cand, dict) else None, f"{src}: not enough board samples"
            return board.astype(np.float32), cand if isinstance(cand, dict) else None, src
        except Exception as e:
            return None, None, f"failed to sample board points: {repr(e)}"

    def _variable_side_overflows_from_board(board: np.ndarray) -> Dict[str, Any]:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        frame_margin = max(0.0, float(getattr(args, "variable_overflow_frame_margin_mm", 0.0)))
        left_lim = float(min_bx + frame_margin)
        right_lim = float(max_bx - frame_margin)
        bottom_lim = float(min_by + frame_margin)
        top_lim = float(max_by - frame_margin)
        lo_pct = float(np.clip(getattr(args, "variable_overflow_low_percentile", 5.0), 0.0, 49.0))
        hi_pct = float(np.clip(getattr(args, "variable_overflow_high_percentile", 95.0), 51.0, 100.0))
        x_low = float(np.percentile(board[:, 0], lo_pct))
        x_high = float(np.percentile(board[:, 0], hi_pct))
        y_low = float(np.percentile(board[:, 1], lo_pct))
        y_high = float(np.percentile(board[:, 1], hi_pct))
        n = max(1, len(board))
        sides = {
            "01": {
                "name": "01_left",
                "overflow": max(0.0, left_lim - x_low),
                "outside_ratio": float(np.count_nonzero(board[:, 0] < left_lim) / n),
                "unit": np.array([1.0, 0.0], dtype=np.float32),
                "single_arm": "arm1",
                "opposite": "23",
            },
            "23": {
                "name": "23_right",
                "overflow": max(0.0, x_high - right_lim),
                "outside_ratio": float(np.count_nonzero(board[:, 0] > right_lim) / n),
                "unit": np.array([-1.0, 0.0], dtype=np.float32),
                "single_arm": "arm2",
                "opposite": "01",
            },
            "02": {
                "name": "02_top",
                "overflow": max(0.0, y_high - top_lim),
                "outside_ratio": float(np.count_nonzero(board[:, 1] > top_lim) / n),
                "unit": np.array([0.0, -1.0], dtype=np.float32),
                "single_arm": "arm2",
                "opposite": "13",
            },
            "13": {
                "name": "13_bottom",
                "overflow": max(0.0, bottom_lim - y_low),
                "outside_ratio": float(np.count_nonzero(board[:, 1] < bottom_lim) / n),
                "unit": np.array([0.0, 1.0], dtype=np.float32),
                "single_arm": "arm1",
                "opposite": "02",
            },
        }
        return {
            "limits": {"left": left_lim, "right": right_lim, "top": top_lim, "bottom": bottom_lim},
            "percentiles": {"x_low": x_low, "x_high": x_high, "y_low": y_low, "y_high": y_high, "lo_pct": lo_pct, "hi_pct": hi_pct},
            "sides": sides,
        }

    def _marker_xy_for_variable_overflow(marker_id: int) -> np.ndarray:
        try:
            v = cfg.get("aruco", {}).get("marker_board_mm", {}).get(str(int(marker_id)))
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return np.array([float(v[0]), float(v[1])], dtype=np.float32)
        except Exception:
            pass
        fallback = {
            0: (0.0, 0.0),
            1: (0.0, -496.0),
            2: (492.0, 5.0),
            3: (494.0, -490.0),
        }
        return np.array(fallback.get(int(marker_id), (0.0, 0.0)), dtype=np.float32)

    def _variable_arm_workspace_mask(points: np.ndarray, arm_key: str) -> np.ndarray:
        """Return the board-x workspace mask for the selected arm."""
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        dead = float(args.workspace_dead_half_width)
        if str(arm_key).lower() == "arm2":
            return points[:, 0] <= (split_x - dead)
        return points[:, 0] >= (split_x + dead)

    def _variable_anchor_for_single(side: str, arm_key: str, board_for_center: np.ndarray) -> np.ndarray:
        """Anchor for the user-defined single-side overflow policy.

        The old code used fixed corners for top/bottom overflow. That worked on one
        side but could select the wrong cloth region on the other side. This version
        treats the target as an entire opposite side segment:
          01 overflow -> grab near side 23, pull toward +x with ARM1
          23 overflow -> grab near side 01, pull toward -x with ARM2
          02 overflow -> grab near side 13, pull toward -y with ARM2
          13 overflow -> grab near side 02, pull toward +y with ARM1
        The anchor coordinate along the side is taken from real internal cloth points
        in the selected arm workspace when possible, so it follows the garment instead
        of always jumping to a fixed corner.
        """
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        pts = board_for_center if board_for_center is not None and len(board_for_center) >= 5 else None
        if pts is not None:
            pts2 = pts[:, :2].astype(np.float32)
            arm_mask = _variable_arm_workspace_mask(pts2, arm_key)
            p_arm = pts2[arm_mask]
            p_use = p_arm if len(p_arm) >= 8 else pts2
            cx = float(np.median(p_use[:, 0])); cy = float(np.median(p_use[:, 1]))
        else:
            cx = 0.5 * (float(min_bx) + float(max_bx)); cy = 0.5 * (float(min_by) + float(max_by))

        x_safe = float(np.clip(cx, min_bx + target_margin, max_bx - target_margin))
        y_safe = float(np.clip(cy, min_by + target_margin, max_by - target_margin))
        if side == "01":   # left overflow -> choose right-side cloth region
            return np.array([float(max_bx - target_margin), y_safe], dtype=np.float32)
        if side == "23":   # right overflow -> choose left-side cloth region
            return np.array([float(min_bx + target_margin), y_safe], dtype=np.float32)
        if side == "02":   # top overflow -> choose bottom-side cloth region
            return np.array([x_safe, float(min_by + target_margin)], dtype=np.float32)
        if side == "13":   # bottom overflow -> choose top-side cloth region
            return np.array([x_safe, float(max_by - target_margin)], dtype=np.float32)
        return np.array([x_safe, y_safe], dtype=np.float32)

    def _variable_target_distance(points: np.ndarray, target_type: str, target_value: Any) -> np.ndarray:
        """Distance from board points to the user-policy target side or marker."""
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        p = points[:, :2].astype(np.float32)
        if target_type == "side":
            side = str(target_value)
            if side == "01":
                return np.abs(p[:, 0] - float(min_bx))
            if side == "23":
                return np.abs(p[:, 0] - float(max_bx))
            if side == "02":
                return np.abs(p[:, 1] - float(max_by))
            if side == "13":
                return np.abs(p[:, 1] - float(min_by))
        if target_type == "marker":
            marker_xy = _marker_xy_for_variable_overflow(int(target_value)).reshape(1, 2)
            return np.linalg.norm(p - marker_xy, axis=1)
        anchor = np.asarray(target_value, dtype=np.float32).reshape(1, 2)
        return np.linalg.norm(p - anchor, axis=1)

    def _choose_variable_overflow_mode(raw_board: np.ndarray, planning_board: np.ndarray) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:
        info = _variable_side_overflows_from_board(raw_board)
        sides = info["sides"]
        min_single = max(0.0, float(getattr(args, "variable_overflow_min_overflow_mm", 20.0)))
        diag_major_min = max(0.0, float(getattr(args, "variable_overflow_diagonal_major_min_mm", 30.0)))
        diag_minor_min = max(0.0, float(getattr(args, "variable_overflow_diagonal_minor_min_mm", 25.0)))
        diag_share = float(np.clip(getattr(args, "variable_overflow_diagonal_minor_share", 0.35), 0.0, 0.49))

        corners = [
            {"corner": 0, "sides": ("01", "02"), "opposite_marker": 3, "arm_key": "arm1"},
            {"corner": 2, "sides": ("02", "23"), "opposite_marker": 1, "arm_key": "arm2"},
            {"corner": 3, "sides": ("23", "13"), "opposite_marker": 0, "arm_key": "arm2"},
            {"corner": 1, "sides": ("13", "01"), "opposite_marker": 2, "arm_key": "arm1"},
        ]
        diag_candidates = []
        for item in corners:
            s1, s2 = item["sides"]
            d1 = float(sides[s1]["overflow"]); d2 = float(sides[s2]["overflow"])
            major = max(d1, d2); minor = min(d1, d2)
            minor_share = float(minor / max(1e-6, major + minor))
            if major >= diag_major_min and minor >= diag_minor_min and minor_share >= diag_share:
                vec = d1 * sides[s1]["unit"] + d2 * sides[s2]["unit"]
                norm = float(np.linalg.norm(vec))
                if norm > 1e-6:
                    opposite_marker = int(item["opposite_marker"])
                    diag_candidates.append({
                        **item,
                        "mode": "diagonal",
                        "main_side": f"{s1}+{s2}",
                        "overflow_norm": norm,
                        "pull_unit": (vec / norm).astype(np.float32),
                        "major": major,
                        "minor": minor,
                        "minor_share": minor_share,
                        "anchor": _marker_xy_for_variable_overflow(opposite_marker),
                        "contact_target_type": "marker",
                        "contact_target": opposite_marker,
                        "policy": f"corner{int(item['corner'])}->marker{opposite_marker}",
                    })
        if diag_candidates:
            best = max(diag_candidates, key=lambda x: (float(x["overflow_norm"]), float(x["minor_share"])))
            return best, info

        single_side = max(sides.keys(), key=lambda k: float(sides[k]["overflow"]))
        d = float(sides[single_side]["overflow"])
        if d < min_single:
            return None, info
        arm_key = str(sides[single_side]["single_arm"])
        unit = sides[single_side]["unit"].astype(np.float32)
        target_side = str(sides[single_side]["opposite"])
        anchor = _variable_anchor_for_single(single_side, arm_key, planning_board)
        return {
            "mode": "single",
            "main_side": single_side,
            "sides": (single_side,),
            "arm_key": arm_key,
            "opposite": target_side,
            "overflow_norm": d,
            "pull_unit": unit,
            "anchor": anchor,
            "major": d,
            "minor": 0.0,
            "minor_share": 0.0,
            "contact_target_type": "side",
            "contact_target": target_side,
            "policy": f"side{single_side}->side{target_side}",
        }, info

    def _choose_variable_overflow_contact_point(planning_board: np.ndarray, mode: Dict[str, Any]) -> Optional[Tuple[float, float, int, float]]:
        """Choose the actual / contact point using the user-provided policy.

        Step_a30 fix:
          - The side/corner case chooses the *target side or target marker* first.
          - The selected arm workspace is enforced before choosing the point.
          - The final contact is pulled inward toward the garment center, so the gripper
            lands on a stable internal area, not the cloth edge.
        """
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        min_pts = max(3, int(getattr(args, "variable_overflow_min_inside_points", 18)))
        arm_key = str(mode.get("arm_key", "arm1"))
        anchor = np.asarray(mode.get("anchor", [0.0, 0.0]), dtype=np.float32).reshape(2)
        target_type = str(mode.get("contact_target_type", "point"))
        target_value = mode.get("contact_target", anchor)

        board_inside = ((planning_board[:, 0] >= min_bx) & (planning_board[:, 0] <= max_bx) &
                        (planning_board[:, 1] >= min_by) & (planning_board[:, 1] <= max_by))
        target_safe = ((planning_board[:, 0] >= min_bx + target_margin) & (planning_board[:, 0] <= max_bx - target_margin) &
                       (planning_board[:, 1] >= min_by + target_margin) & (planning_board[:, 1] <= max_by - target_margin))
        arm_side = _variable_arm_workspace_mask(planning_board[:, :2].astype(np.float32), arm_key)

        # Prefer the selected arm workspace.  Only use any-workspace fallback when the user explicitly enables it.
        masks_to_try = [
            ("target_safe_arm_workspace", target_safe & arm_side),
            ("board_inside_arm_workspace", board_inside & arm_side),
        ]
        if bool(getattr(args, "variable_overflow_allow_non_arm_workspace_contact_fallback", False)):
            masks_to_try.extend([
                ("target_safe_any_workspace", target_safe),
                ("board_inside_any_workspace", board_inside),
            ])

        idxs = np.array([], dtype=int)
        used_mask_name = "none"
        for name, mask in masks_to_try:
            cand = np.where(mask)[0]
            if len(cand) >= min_pts:
                idxs = cand
                used_mask_name = name
                break
        if len(idxs) < min_pts:
            return None

        pts = planning_board[idxs].astype(np.float32)
        all_inside = planning_board[board_inside].astype(np.float32)
        cloth_center = np.median(all_inside[:, :2], axis=0).astype(np.float32) if len(all_inside) >= 10 else np.median(planning_board[:, :2].astype(np.float32), axis=0)

        d_target = _variable_target_distance(pts, target_type, target_value)
        band_mm = max(15.0, float(getattr(args, "variable_overflow_contact_side_band_mm", 120.0)))
        if target_type == "side":
            band_limit = float(np.percentile(d_target, min(35.0, max(5.0, float(getattr(args, "variable_overflow_contact_side_anchor_percentile", 50.0))))))
            band_limit = max(band_limit, min(band_mm, float(np.max(d_target)) if len(d_target) else band_mm))
            band_idxs_local = np.where(d_target <= band_limit)[0]
            if len(band_idxs_local) < max(4, min_pts // 2):
                band_idxs_local = np.argsort(d_target)[:max(4, min(len(pts), min_pts))]
            edge_pool = pts[band_idxs_local]
            edge_pt = np.median(edge_pool[:, :2], axis=0).astype(np.float32)
        else:
            edge_i = int(np.argmin(d_target))
            edge_pt = pts[edge_i, :2].astype(np.float32)

        v_in = cloth_center - edge_pt
        n_in = float(np.linalg.norm(v_in))
        offset_mm = max(0.0, float(getattr(args, "variable_overflow_contact_interior_offset_mm", 65.0)))
        ratio = float(np.clip(getattr(args, "variable_overflow_contact_center_ratio", 0.35), 0.05, 0.85))
        if n_in > 1e-6:
            desired = edge_pt + (v_in / n_in) * min(offset_mm, n_in * ratio)
        else:
            desired = edge_pt.copy()

        d_desired = np.linalg.norm(pts[:, :2] - desired.reshape(1, 2), axis=1)
        d_anchor = np.linalg.norm(pts[:, :2] - anchor.reshape(1, 2), axis=1)
        d_center = np.linalg.norm(pts[:, :2] - cloth_center.reshape(1, 2), axis=1)

        score = d_desired + 0.12 * d_target + 0.03 * d_center + 0.02 * d_anchor
        j = int(np.argmin(score))
        bx, by = float(pts[j, 0]), float(pts[j, 1])
        bx, by = _clamp_board_xy(bx, by, target_margin)
        if bool(getattr(args, "fallback_print_debug", False)):
            print(f"[VAR-OVERFLOW-CONTACT] {arm_key.upper()} policy={mode.get('policy','?')} target={target_type}:{target_value} "
                  f"from={used_mask_name} points={len(idxs)} target_dist={float(d_target[j]):.1f}mm "
                  f"anchor_dist={float(d_anchor[j]):.1f}mm desired_dist={float(d_desired[j]):.1f}mm "
                  f"edge=({float(edge_pt[0]):.1f},{float(edge_pt[1]):.1f}) "
                  f"desired=({float(desired[0]):.1f},{float(desired[1]):.1f})")
        return bx, by, int(len(idxs)), float(d_anchor[j])

    def _resolve_board_target_for_arm_relaxed_variable(arm_key: str, bx: float, by: float, rz: float, source: str) -> Optional[Dict[str, float]]:
        """Resolve a board target for the new pose-neck pull policy without the x-split block.

        The old / side-policy deliberately blocked the center dead zone by using
        resolve_board_target_for_arm().  The neck pull path often starts near the
        shirt center, so this single-arm policy needs relaxed workspace checking while
        still keeping board and RoArm safety checks.
        """
        bx = float(bx); by = float(by); rz = float(rz)
        if (not args.allow_outside_board) and (not is_board_safe(cfg, bx, by, max(0.0, float(args.board_margin)))):
            print(f"[{source}-BLOCKED] {arm_key.upper()} board target outside safe board bounds: ({bx:.1f},{by:.1f})")
            return None
        try:
            rx, ry = board_to_arm_xy(cfg, arm_key, bx, by)
        except Exception as e:
            print(f"[{source}-BLOCKED] {arm_key.upper()} affine error: {e}")
            return None
        if (not args.allow_unsafe_roarm) and (not is_xyz_safe(rx, ry, rz, args)):
            print(f"[{source}-BLOCKED] {arm_key.upper()} RoArm target outside safety range: ({rx:.1f},{ry:.1f},{rz:.1f})")
            return None
        return {"arm_key": str(arm_key), "rx": float(rx), "ry": float(ry), "rz": float(rz), "bx": float(bx), "by": float(by)}

    def _choose_arm_for_pose_neck_pull(start_b: np.ndarray) -> str:
        """Choose a single arm for the pose-neck pull based on board x.

        The center dead-zone is intentionally not used here; only one arm moves while
        the other remains at standby, and the relaxed resolver still performs RoArm
        safety checks.
        """
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        return "arm2" if float(start_b[0]) < split_x else "arm1"

    def _pose_neck_pull_target_board_xy() -> Optional[np.ndarray]:
        """Target = 50 mm inside the board from the midpoint of the ID1-ID3 bottom line."""
        try:
            p0 = _marker_xy_for_variable_overflow(0)
            p1 = _marker_xy_for_variable_overflow(1)
            p2 = _marker_xy_for_variable_overflow(2)
            p3 = _marker_xy_for_variable_overflow(3)
            top_mid = 0.5 * (p0 + p2)
            bottom_mid = 0.5 * (p1 + p3)
            inward = top_mid - bottom_mid
            n = float(np.linalg.norm(inward))
            if n < 1e-6:
                return None
            inward = inward / n
            d = max(0.0, float(getattr(args, "variable_overflow_pose_neck_target_from_bottom_mm", 50.0)))
            target = bottom_mid + inward * d
            target_margin = float(args.boundary_recovery_target_margin)
            tx, ty = _clamp_board_xy(float(target[0]), float(target[1]), target_margin)
            return np.array([tx, ty], dtype=np.float32)
        except Exception:
            return None

    def _pose_neck_grip_board_xy_from_latest_pose(planning_board: Optional[np.ndarray]) -> Tuple[Optional[np.ndarray], str, Dict[str, Any]]:
        """Return the neck-centered grip point moved slightly toward the shirt body.

        Uses the pose model semantics supplied by the user:
          neck_center = mean(neck_left, neck_right)
          waist_mid    = mean(waist_left, waist_right)
          shirt axis   = neck_center -> waist_mid

        The selected contact is neck_center + inset * unit(neck->waist), optionally
        snapped to the nearest internal garment-mask board point so the gripper lands
        on cloth and not table/background.
        """
        try:
            plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if plan is None:
                return None, "pose neck unavailable: no latest pose plan", {}
            neck = plan.get("neck_board_xy")
            waist = plan.get("waist_board_xy")
            if neck is None or waist is None:
                return None, "pose neck unavailable: missing neck/waist board points", {}
            neck_b = np.asarray(neck, dtype=np.float32).reshape(2)
            waist_b = np.asarray(waist, dtype=np.float32).reshape(2)
            if not np.all(np.isfinite(neck_b)) or not np.all(np.isfinite(waist_b)):
                return None, "pose neck unavailable: non-finite neck/waist", {}
            axis = waist_b - neck_b
            axis_len = float(np.linalg.norm(axis))
            min_len = float(getattr(args, "pose_rotate_min_axis_len_mm", 80.0))
            if axis_len < min_len:
                return None, f"pose neck unavailable: axis_len={axis_len:.1f}mm < {min_len:.1f}mm", {}
            u_body = axis / axis_len
            inset = max(0.0, float(getattr(args, "variable_overflow_pose_neck_inset_mm", 45.0)))
            desired = neck_b + u_body * inset
            target_margin = float(args.boundary_recovery_target_margin)
            dx, dy = _clamp_board_xy(float(desired[0]), float(desired[1]), target_margin)
            desired = np.array([dx, dy], dtype=np.float32)

            snap_used = False
            snap_dist = None
            snapped = desired.copy()
            if bool(getattr(args, "variable_overflow_pose_neck_snap_to_mask", True)) and planning_board is not None and len(planning_board) >= 10:
                pts = planning_board[:, :2].astype(np.float32)
                min_bx, max_bx, min_by, max_by = board_bounds(cfg)
                inside = ((pts[:, 0] >= min_bx + target_margin) & (pts[:, 0] <= max_bx - target_margin) &
                          (pts[:, 1] >= min_by + target_margin) & (pts[:, 1] <= max_by - target_margin))
                pts2 = pts[inside] if int(np.count_nonzero(inside)) >= 10 else pts
                d = np.linalg.norm(pts2 - desired.reshape(1, 2), axis=1)
                j = int(np.argmin(d))
                snap_dist = float(d[j])
                max_snap = max(0.0, float(getattr(args, "variable_overflow_pose_neck_snap_max_mm", 80.0)))
                if snap_dist <= max_snap:
                    snapped = pts2[j].astype(np.float32)
                    snap_used = True
            detail = {
                "neck_board_xy": [float(neck_b[0]), float(neck_b[1])],
                "waist_board_xy": [float(waist_b[0]), float(waist_b[1])],
                "desired_board_xy": [float(desired[0]), float(desired[1])],
                "snapped_board_xy": [float(snapped[0]), float(snapped[1])],
                "inset_mm": float(inset),
                "axis_len_mm": float(axis_len),
                "snap_used": bool(snap_used),
                "snap_dist_mm": None if snap_dist is None else float(snap_dist),
            }
            msg = (f"pose neck grip OK neck=({neck_b[0]:.1f},{neck_b[1]:.1f}) "
                   f"desired=({desired[0]:.1f},{desired[1]:.1f}) "
                   f"snap={'yes' if snap_used else 'no'}"
                   + (f" snap_dist={snap_dist:.1f}mm" if snap_dist is not None else ""))
            return snapped.astype(np.float32), msg, detail
        except Exception as e:
            return None, f"pose neck grip failed: {repr(e)}", {}

    def _inside_vacancy_candidate_board_points(plan: Optional[Dict[str, Any]]) -> Tuple[Optional[np.ndarray], Optional[np.ndarray], Optional[Dict[str, Any]], str]:
        """Return board-internal garment points and raw candidate points for Step_a35.

        This intentionally does NOT use expanded outside-board foreground or full-garment
        reconstruction.  The decision mask is the garment contour visible inside the normal
        ArUco rectangle, because the outside-marker mask has been unstable in practice.
        """
        try:
            cand = None
            if isinstance(plan, dict):
                cand = plan.get("candidate", {})
            if (not cand) and latest_candidate is not None:
                cand = latest_candidate
            if latest_H is None:
                return None, None, None, "inside_vacancy: no Homography"
            if not isinstance(cand, dict) or not cand:
                return None, None, None, "inside_vacancy: no candidate"

            raw_contour = cand.get("raw_contour", cand.get("contour"))
            raw_shape = cand.get("raw_image_shape", cand.get("image_shape"))
            contour = cand.get("contour", cand.get("raw_contour"))
            image_shape = cand.get("image_shape", cand.get("raw_image_shape"))
            if contour is None or image_shape is None:
                return None, None, cand, "inside_vacancy: no contour/image_shape"

            def _contour_to_board(cont, shape, max_points=50000):
                if cont is None or shape is None:
                    return None
                m = _mask_u8_from_contour(cont, shape)
                _px, bd = _mask_pixels_with_board_coords(m, latest_H, max_points=max_points)
                if bd is None or len(bd) < 20:
                    return None
                return bd.astype(np.float32)

            board = _contour_to_board(contour, image_shape, max_points=52000)
            raw_board = _contour_to_board(raw_contour, raw_shape, max_points=52000) if raw_contour is not None and raw_shape is not None else None
            if board is None or len(board) < 20:
                return None, raw_board, cand, "inside_vacancy: not enough board samples"

            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                      (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
            board_inside = board[inside].astype(np.float32)
            if len(board_inside) < 20:
                return None, raw_board, cand, "inside_vacancy: not enough inside-frame garment samples"
            src = "inside_vacancy_contour(board_internal; no outside-frame reconstruction)"
            return board_inside, raw_board, cand, src
        except Exception as e:
            return None, None, None, f"inside_vacancy failed: {repr(e)}"

    def _inside_vacancy_gap_info(board_inside: np.ndarray) -> Dict[str, Any]:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        lo_pct = float(np.clip(getattr(args, "variable_overflow_vacancy_low_percentile", 2.0), 0.0, 49.0))
        hi_pct = float(np.clip(getattr(args, "variable_overflow_vacancy_high_percentile", 98.0), 51.0, 100.0))
        pts = board_inside[:, :2].astype(np.float32)
        x_low = float(np.percentile(pts[:, 0], lo_pct))
        x_high = float(np.percentile(pts[:, 0], hi_pct))
        y_low = float(np.percentile(pts[:, 1], lo_pct))
        y_high = float(np.percentile(pts[:, 1], hi_pct))
        gaps = {
            "01": max(0.0, x_low - float(min_bx)),       # empty gap to left side
            "23": max(0.0, float(max_bx) - x_high),      # empty gap to right side
            "02": max(0.0, float(max_by) - y_high),      # empty gap to top side
            "13": max(0.0, y_low - float(min_by)),       # empty gap to bottom side
        }
        units = {
            "01": np.array([-1.0, 0.0], dtype=np.float32),
            "23": np.array([1.0, 0.0], dtype=np.float32),
            "02": np.array([0.0, 1.0], dtype=np.float32),
            "13": np.array([0.0, -1.0], dtype=np.float32),
        }
        ordered = sorted(gaps.keys(), key=lambda k: float(gaps[k]), reverse=True)
        major = ordered[0]
        second = ordered[1] if len(ordered) > 1 else None
        major_gap = float(gaps[major])
        second_gap = float(gaps[second]) if second is not None else 0.0
        second_share = second_gap / max(major_gap, 1e-6)
        second_min_share = float(np.clip(getattr(args, "variable_overflow_vacancy_second_min_share", 0.20), 0.0, 1.0))
        second_min_gap = max(0.0, float(getattr(args, "variable_overflow_vacancy_second_min_gap_mm", 15.0)))
        selected = [major]
        if second is not None and second_gap >= second_min_gap and second_share >= second_min_share:
            selected.append(second)

        v = np.zeros(2, dtype=np.float32)
        for s in selected:
            v += float(gaps[s]) * units[s]
        if float(np.linalg.norm(v)) < 1e-6:
            v = np.array([float(gaps["23"] - gaps["01"]), float(gaps["02"] - gaps["13"])], dtype=np.float32)
        v_norm = float(np.linalg.norm(v))
        unit = v / v_norm if v_norm > 1e-6 else np.zeros(2, dtype=np.float32)
        return {
            "gaps": gaps,
            "units": {k: [float(vv[0]), float(vv[1])] for k, vv in units.items()},
            "ordered": ordered,
            "selected": selected,
            "major_side": major,
            "second_side": second,
            "major_gap": major_gap,
            "second_gap": second_gap,
            "second_share": float(second_share),
            "vacancy_vector": [float(v[0]), float(v[1])],
            "vacancy_norm": float(v_norm),
            "pull_unit": [float(unit[0]), float(unit[1])],
            "percentiles": {"x_low": x_low, "x_high": x_high, "y_low": y_low, "y_high": y_high, "lo_pct": lo_pct, "hi_pct": hi_pct},
            "limits": {"left": float(min_bx), "right": float(max_bx), "bottom": float(min_by), "top": float(max_by)},
        }

    def _vacancy_preferred_arm_from_unit(unit: np.ndarray, contact_x: Optional[float] = None) -> Optional[str]:
        unit = np.asarray(unit, dtype=np.float32).reshape(2)
        ux = float(unit[0])
        dead = abs(float(getattr(args, "variable_overflow_vacancy_horizontal_arm_deadband", 0.22)))
        if ux >= dead:
            return "arm1"  # pulling toward ID2-ID3 side
        if ux <= -dead:
            return "arm2"  # pulling toward ID0-ID1 side
        if contact_x is not None:
            try:
                return select_arm_for_board_x(cfg, float(contact_x))
            except Exception:
                pass
        return None

    def _circumcenter_arm_base_reference(arm_key: str) -> np.ndarray:
        """Approximate each fixed robot base in board coordinates by its marker-side midpoint.

        ARM2 is mounted along the ID0-ID1 side and ARM1 along ID2-ID3.  This is
        used only for ACTION1 arm selection; actual motion still uses calibrated
        board->RoArm affine conversion and the normal XYZ safety checks.
        """
        if str(arm_key).lower() == "arm2":
            return 0.5 * (_marker_xy_for_variable_overflow(0) + _marker_xy_for_variable_overflow(1))
        return 0.5 * (_marker_xy_for_variable_overflow(2) + _marker_xy_for_variable_overflow(3))

    def _choose_circumcenter_arm_toward_base(start: np.ndarray, end: np.ndarray) -> Dict[str, Any]:
        """Choose the single ACTION1 arm from the actual board drag segment.

        Primary rule: select the arm whose fixed side-base gets closer from start to end.
        Safety exception: if that arm is much farther from the contact point than the
        other arm, or beyond the absolute cross-reach limit, use the nearer arm.
        """
        start = np.asarray(start, dtype=np.float32).reshape(2)
        end = np.asarray(end, dtype=np.float32).reshape(2)
        metrics: Dict[str, Dict[str, float]] = {}
        for arm_key in ("arm1", "arm2"):
            base = _circumcenter_arm_base_reference(arm_key).astype(np.float32).reshape(2)
            d0 = float(np.linalg.norm(start - base))
            d1 = float(np.linalg.norm(end - base))
            metrics[arm_key] = {
                "base_x": float(base[0]), "base_y": float(base[1]),
                "start_distance_mm": d0, "end_distance_mm": d1,
                "approach_gain_mm": d0 - d1,
            }

        nearest = min(("arm1", "arm2"), key=lambda ak: metrics[ak]["start_distance_mm"])
        toward = max(("arm1", "arm2"), key=lambda ak: metrics[ak]["approach_gain_mm"])
        min_gain = max(0.0, float(getattr(args, "variable_overflow_circumcenter_toward_base_min_gain_mm", 5.0)))
        max_extra = max(0.0, float(getattr(args, "variable_overflow_circumcenter_cross_arm_max_extra_reach_mm", 150.0)))
        max_abs = max(1.0, float(getattr(args, "variable_overflow_circumcenter_cross_arm_max_base_distance_mm", 390.0)))

        selection_enabled = bool(getattr(args, "variable_overflow_circumcenter_toward_base_arm_selection", True))
        if not selection_enabled:
            vec = end - start
            n = float(np.linalg.norm(vec))
            u_local = vec / n if n > 1e-6 else np.zeros(2, dtype=np.float32)
            legacy = _vacancy_preferred_arm_from_unit(u_local, contact_x=float(start[0]))
            primary = legacy if legacy in ("arm1", "arm2") else nearest
            reason = "LEGACY_DIRECTION_POLICY"
        elif metrics[toward]["approach_gain_mm"] < min_gain:
            primary = nearest
            reason = "NO_ARM_MOVES_MEANINGFULLY_TOWARD_BASE_NEAREST_FALLBACK"
        else:
            primary = toward
            reason = "TOWARD_BASE"

        far_fallback = False
        extra_reach = float(metrics[primary]["start_distance_mm"] - metrics[nearest]["start_distance_mm"])
        if selection_enabled and primary != nearest and (metrics[primary]["start_distance_mm"] > max_abs or extra_reach > max_extra):
            primary = nearest
            reason = "FAR_CROSS_ARM_NEAREST_FALLBACK"
            far_fallback = True

        alternate = "arm2" if primary == "arm1" else "arm1"
        return {
            "primary": primary,
            "alternate": alternate,
            "nearest": nearest,
            "toward": toward,
            "reason": reason,
            "far_fallback": bool(far_fallback),
            "extra_reach_mm": extra_reach,
            "limits": {"min_gain_mm": min_gain, "max_extra_reach_mm": max_extra, "max_base_distance_mm": max_abs},
            "metrics": metrics,
        }

    def _variable_pose_center_error_mm() -> Tuple[Optional[float], str, Dict[str, Any]]:
        try:
            plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if plan is None:
                return None, "pose center unavailable: no latest pose plan", {}
            center = plan.get("center_board_xy")
            if center is None:
                return None, "pose center unavailable: missing center_board_xy", {}
            c = np.asarray(center, dtype=np.float32).reshape(2)
            if not np.all(np.isfinite(c)):
                return None, "pose center unavailable: non-finite", {}
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            bc = np.array([(float(min_bx) + float(max_bx)) * 0.5, (float(min_by) + float(max_by)) * 0.5], dtype=np.float32)
            err = float(np.linalg.norm(c - bc))
            detail = {"pose_center_board_xy": [float(c[0]), float(c[1])], "board_center_xy": [float(bc[0]), float(bc[1])], "error_mm": err}
            return err, f"pose_center_error={err:.1f}mm center=({c[0]:.1f},{c[1]:.1f}) board_center=({bc[0]:.1f},{bc[1]:.1f})", detail
        except Exception as e:
            return None, f"pose center error failed: {repr(e)}", {}

    def _inside_vacancy_stop_metrics(plan: Optional[Dict[str, Any]]) -> Tuple[Optional[float], Optional[float], str, Dict[str, Any]]:
        inside, raw_total, _cand, src = _inside_vacancy_candidate_board_points(plan)
        ratio = None
        detail: Dict[str, Any] = {"src": src}
        try:
            if inside is not None:
                if raw_total is not None and len(raw_total) >= 20:
                    min_bx, max_bx, min_by, max_by = board_bounds(cfg)
                    raw_inside = ((raw_total[:, 0] >= min_bx) & (raw_total[:, 0] <= max_bx) &
                                  (raw_total[:, 1] >= min_by) & (raw_total[:, 1] <= max_by))
                    ratio = float(np.count_nonzero(raw_inside) / max(1, len(raw_total)))
                    detail["inside_count"] = int(np.count_nonzero(raw_inside))
                    detail["total_count"] = int(len(raw_total))
                else:
                    ratio = 1.0
                    detail["inside_count"] = int(len(inside))
                    detail["total_count"] = int(len(inside))
                    detail["ratio_note"] = "raw total unavailable; inside-only contour used"
        except Exception as e:
            detail["ratio_error"] = repr(e)
            ratio = None
        pose_err, pose_msg, pose_detail = _variable_pose_center_error_mm()
        detail["pose"] = pose_detail
        msg = f"inside_ratio={'NA' if ratio is None else f'{ratio:.3f}'} | {pose_msg} | {src}"
        return ratio, pose_err, msg, detail

    def _side_midpoint_board(side: str) -> np.ndarray:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        mid_x = (float(min_bx) + float(max_bx)) * 0.5
        mid_y = (float(min_by) + float(max_by)) * 0.5
        side = str(side)
        if side == "01":
            return np.array([float(min_bx), mid_y], dtype=np.float32)
        if side == "23":
            return np.array([float(max_bx), mid_y], dtype=np.float32)
        if side == "02":
            return np.array([mid_x, float(max_by)], dtype=np.float32)
        if side == "13":
            return np.array([mid_x, float(min_by)], dtype=np.float32)
        return np.array([mid_x, mid_y], dtype=np.float32)

    def _distance_to_board_side_mm(p: np.ndarray, side: str) -> float:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        p = np.asarray(p, dtype=np.float32).reshape(2)
        side = str(side)
        if side == "01":
            return float(p[0] - float(min_bx))
        if side == "23":
            return float(float(max_bx) - p[0])
        if side == "02":
            return float(float(max_by) - p[1])
        if side == "13":
            return float(p[1] - float(min_by))
        return 0.0

    def _circumcenter_2d(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> Tuple[Optional[np.ndarray], float, float, str]:
        a = np.asarray(a, dtype=np.float64).reshape(2)
        b = np.asarray(b, dtype=np.float64).reshape(2)
        c = np.asarray(c, dtype=np.float64).reshape(2)
        if not (np.all(np.isfinite(a)) and np.all(np.isfinite(b)) and np.all(np.isfinite(c))):
            return None, 0.0, 0.0, "non-finite triangle point"
        area2 = float(abs(np.cross(b - a, c - a)))
        area = 0.5 * area2
        min_area = max(0.0, float(getattr(args, "variable_overflow_circumcenter_min_triangle_area_mm2", 2500.0)))
        if area < min_area:
            return None, 0.0, area, f"triangle area too small: {area:.1f} < {min_area:.1f} mm^2"
        d = 2.0 * (a[0] * (b[1] - c[1]) + b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]))
        if abs(d) < 1e-6:
            return None, 0.0, area, "triangle nearly collinear"
        aa = a[0] * a[0] + a[1] * a[1]
        bb = b[0] * b[0] + b[1] * b[1]
        cc = c[0] * c[0] + c[1] * c[1]
        ux = (aa * (b[1] - c[1]) + bb * (c[1] - a[1]) + cc * (a[1] - b[1])) / d
        uy = (aa * (c[0] - b[0]) + bb * (a[0] - c[0]) + cc * (b[0] - a[0])) / d
        o = np.array([float(ux), float(uy)], dtype=np.float32)
        radius = float(np.linalg.norm(o.astype(np.float64) - a))
        max_r = max(1.0, float(getattr(args, "variable_overflow_circumcenter_max_radius_mm", 320.0)))
        if radius > max_r:
            return None, radius, area, f"circumradius too large: {radius:.1f} > {max_r:.1f} mm"
        margin = max(0.0, float(getattr(args, "variable_overflow_circumcenter_safe_margin_mm", 35.0)))
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        if not (float(min_bx) + margin <= float(o[0]) <= float(max_bx) - margin and
                float(min_by) + margin <= float(o[1]) <= float(max_by) - margin):
            return None, radius, area, (f"circumcenter outside safe board margin={margin:.1f}: "
                                        f"({float(o[0]):.1f},{float(o[1]):.1f})")
        return o, radius, area, "OK"

    def _pose_keypoints_for_circumcenter() -> Dict[str, np.ndarray]:
        out: Dict[str, np.ndarray] = {}
        try:
            plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if not plan:
                return out
            vk = plan.get("valid_keypoints_board_xy")
            if isinstance(vk, dict):
                for k, v in vk.items():
                    try:
                        arr = np.asarray(v, dtype=np.float32).reshape(2)
                        if np.all(np.isfinite(arr)):
                            out[str(k)] = arr
                    except Exception:
                        pass
            for k_plan, k_out in (("neck_board_xy", "neck_center"), ("waist_board_xy", "waist_mid"), ("center_board_xy", "pose_center")):
                v = plan.get(k_plan)
                if v is not None and k_out not in out:
                    try:
                        arr = np.asarray(v, dtype=np.float32).reshape(2)
                        if np.all(np.isfinite(arr)):
                            out[k_out] = arr
                    except Exception:
                        pass
            t = plan.get("targets", {})
            if isinstance(t, dict):
                for arm_key, td in t.items():
                    if isinstance(td, dict) and td.get("orig_board_xy") is not None:
                        try:
                            arr = np.asarray(td.get("orig_board_xy"), dtype=np.float32).reshape(2)
                            if np.all(np.isfinite(arr)):
                                out[f"{arm_key}_pose_grip"] = arr
                        except Exception:
                            pass
        except Exception:
            pass
        return out

    def _choose_pose_point_for_circumcenter(side_a: str, side_b: str, cloth_center: np.ndarray) -> Tuple[Optional[str], Optional[np.ndarray], Dict[str, Any]]:
        """Choose the third triangle vertex for the circumcenter experiment.

        Step_a39 policy requested by the user:
          1) The first two triangle vertices are the midpoints of the two emptiest
             ArUco-board sides.
          2) Estimate the direction from the garment representative center toward those
             two empty sides.  This is the side we want to fill.
          3) Pose points are first filtered to the garment edge facing that fill direction.
             This is the cloth edge opposite the side where the garment is presumed to
             have shifted/outflowed.  It prevents the triangle from using a point such as
             NECK when the desired geometry should use the opposite cloth edge.
          4) Within that edge candidate set, choose points whose distances to the two
             selected sides are most similar.
          5) If multiple points are similarly balanced, choose the point whose average
             distance to the two selected sides is shortest.
        """
        kpts_all = _pose_keypoints_for_circumcenter()
        detail: Dict[str, Any] = {
            "num_pose_points": int(len(kpts_all)),
            "side_a": str(side_a),
            "side_b": str(side_b),
            "selection_policy": "opposite_edge_filter_then_min_distance_difference_then_min_average_distance",
        }
        if not kpts_all:
            return None, None, detail

        fallback_names = {"neck_center", "waist_mid", "pose_center"}
        primary: Dict[str, np.ndarray] = {}
        fallback: Dict[str, np.ndarray] = {}
        for name, pt in kpts_all.items():
            n = str(name)
            if n in fallback_names or n.endswith("_pose_grip"):
                fallback[n] = pt
            else:
                primary[n] = pt
        kpts = primary if primary else fallback
        detail["num_primary_pose_points"] = int(len(primary))
        detail["using_fallback_pose_points"] = bool(not primary)

        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        tol = max(0.0, float(getattr(args, "variable_overflow_circumcenter_pose_equal_tolerance_mm", 12.0)))
        edge_band = max(0.0, float(getattr(args, "variable_overflow_circumcenter_pose_edge_band_mm", 95.0)))
        use_edge_filter = bool(getattr(args, "variable_overflow_circumcenter_pose_opposite_edge_filter", True))

        cloth_c = np.asarray(cloth_center, dtype=np.float32).reshape(2)
        m1 = _side_midpoint_board(side_a)
        m2 = _side_midpoint_board(side_b)
        empty_side_center = ((m1.astype(np.float32) + m2.astype(np.float32)) * 0.5).astype(np.float32)
        fill_vec = empty_side_center - cloth_c
        fill_norm = float(np.linalg.norm(fill_vec))
        if fill_norm > 1e-6:
            fill_dir = (fill_vec / fill_norm).astype(np.float32)
        else:
            fill_dir = np.array([0.0, 0.0], dtype=np.float32)
            use_edge_filter = False

        scored: List[Tuple[float, float, float, str, np.ndarray, float, float]] = []
        for name, pt in kpts.items():
            p2 = np.asarray(pt, dtype=np.float32).reshape(2)
            if not np.all(np.isfinite(p2)):
                continue
            if not (float(min_bx) - 30.0 <= float(p2[0]) <= float(max_bx) + 30.0 and
                    float(min_by) - 30.0 <= float(p2[1]) <= float(max_by) + 30.0):
                continue
            d1 = max(0.0, _distance_to_board_side_mm(p2, side_a))
            d2 = max(0.0, _distance_to_board_side_mm(p2, side_b))
            diff = abs(d1 - d2)
            avg = 0.5 * (d1 + d2)
            edge_proj = float(np.dot((p2 - cloth_c).astype(np.float32), fill_dir)) if fill_norm > 1e-6 else 0.0
            scored.append((float(diff), float(avg), float(edge_proj), str(name), p2, float(d1), float(d2)))

        detail.update({
            "num_scored_pose_points": int(len(scored)),
            "equal_tolerance_mm": float(tol),
            "opposite_edge_filter": bool(use_edge_filter),
            "edge_band_mm": float(edge_band),
            "empty_side_center": [float(empty_side_center[0]), float(empty_side_center[1])],
            "cloth_center_for_edge_filter": [float(cloth_c[0]), float(cloth_c[1])],
            "fill_dir": [float(fill_dir[0]), float(fill_dir[1])],
        })
        if not scored:
            return None, None, detail

        edge_candidates = scored
        if use_edge_filter:
            max_proj = max(v[2] for v in scored)
            threshold = max_proj - edge_band
            filtered = [v for v in scored if v[2] >= threshold]
            # Keep a fallback so one noisy projection never kills the geometry.
            # But record the fallback clearly in the debug dictionary.
            if filtered:
                edge_candidates = filtered
                detail.update({
                    "edge_filter_max_projection_mm": float(max_proj),
                    "edge_filter_threshold_mm": float(threshold),
                    "num_edge_candidates": int(len(edge_candidates)),
                    "edge_filter_fallback_used": False,
                })
            else:
                detail.update({
                    "edge_filter_max_projection_mm": float(max_proj),
                    "edge_filter_threshold_mm": float(threshold),
                    "num_edge_candidates": 0,
                    "edge_filter_fallback_used": True,
                })
                edge_candidates = scored
        else:
            detail["num_edge_candidates"] = int(len(edge_candidates))

        min_diff = min(v[0] for v in edge_candidates)
        similarly_balanced = [v for v in edge_candidates if v[0] <= min_diff + tol]
        similarly_balanced.sort(key=lambda x: (x[1], x[0], -x[2], x[3]))
        diff, avg, edge_proj, name, pt, d1, d2 = similarly_balanced[0]

        top_edge = sorted(edge_candidates, key=lambda x: (x[0], x[1], -x[2], x[3]))[:8]
        top_all = sorted(scored, key=lambda x: (-x[2], x[0], x[1], x[3]))[:8]
        detail.update({
            "selected_pose_name": name,
            "score": float(avg),
            "dist_diff_mm": float(diff),
            "mean_dist_to_selected_sides_mm": float(avg),
            "edge_projection_mm": float(edge_proj),
            "dist_to_side_a": float(d1),
            "dist_to_side_b": float(d2),
            "min_dist_diff_mm": float(min_diff),
            "num_similarly_balanced": int(len(similarly_balanced)),
            "top_edge_by_balance": [
                {"name": str(t[3]), "diff": float(t[0]), "avg": float(t[1]), "edge_proj": float(t[2]), "d1": float(t[5]), "d2": float(t[6])}
                for t in top_edge
            ],
            "top_all_by_edge_projection": [
                {"name": str(t[3]), "diff": float(t[0]), "avg": float(t[1]), "edge_proj": float(t[2]), "d1": float(t[5]), "d2": float(t[6])}
                for t in top_all
            ],
        })
        # Keep old key for compatibility with terminal logs that were reading top_by_balance.
        detail["top_by_balance"] = detail["top_edge_by_balance"]
        return name, pt.astype(np.float32), detail

    def _contour_points_for_circumcenter_vertex(self_cand: Optional[Dict[str, Any]], max_points: int = 3000) -> Tuple[Optional[np.ndarray], str]:
        """Return board-coordinate points sampled from the visible garment contour.

        Step_a40 deliberately uses the segmentation-mask contour as the third
        circumcenter-triangle vertex source.  This is more flexible than using the
        sparse 12 pose keypoints.  The contour is still restricted to the normal
        ArUco rectangle because the current / policy intentionally ignores
        marker-outside garment reconstruction.
        """
        try:
            cand0 = self_cand if isinstance(self_cand, dict) else None
            if (not cand0) and latest_candidate is not None:
                cand0 = latest_candidate
            if not isinstance(cand0, dict) or latest_H is None:
                return None, "no candidate/H for contour vertex"
            contour = cand0.get("contour", cand0.get("raw_contour"))
            shape = cand0.get("image_shape", cand0.get("raw_image_shape"))
            if contour is None:
                return None, "no contour for contour vertex"

            px_pts = None
            if shape is not None:
                try:
                    mask = _mask_u8_from_contour(contour, shape)
                    found = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
                    contours = found[0] if len(found) == 2 else found[1]
                    if contours:
                        cmax = max(contours, key=cv2.contourArea)
                        arr = np.asarray(cmax, dtype=np.float32).reshape(-1, 2)
                        if len(arr) >= 5:
                            px_pts = arr
                except Exception:
                    px_pts = None
            if px_pts is None:
                try:
                    arr = np.asarray(contour, dtype=np.float32).reshape(-1, 2)
                    if len(arr) >= 5:
                        px_pts = arr
                except Exception:
                    px_pts = None
            if px_pts is None or len(px_pts) < 5:
                return None, "not enough pixel contour points"

            if len(px_pts) > int(max_points):
                step = max(1, int(np.ceil(len(px_pts) / float(max_points))))
                px_pts = px_pts[::step]
            src_pts = px_pts.reshape(-1, 1, 2).astype(np.float32)
            try:
                board = cv2.perspectiveTransform(src_pts, latest_H).reshape(-1, 2).astype(np.float32)
            except Exception as e:
                return None, f"contour vertex perspectiveTransform failed: {repr(e)}"
            board = board[np.all(np.isfinite(board), axis=1)]
            if len(board) < 5:
                return None, "not enough finite board contour points"
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            near = ((board[:, 0] >= float(min_bx) - 5.0) & (board[:, 0] <= float(max_bx) + 5.0) &
                    (board[:, 1] >= float(min_by) - 5.0) & (board[:, 1] <= float(max_by) + 5.0))
            board = board[near]
            if len(board) < 5:
                return None, "not enough board-internal contour points"
            return board.astype(np.float32), f"segmentation contour points={len(board)}"
        except Exception as e:
            return None, f"contour vertex extraction failed: {repr(e)}"

    def _choose_contour_vertex_for_circumcenter(side_a: str, side_b: str, cloth_center: np.ndarray,
                                                cand0: Optional[Dict[str, Any]]) -> Tuple[Optional[str], Optional[np.ndarray], Dict[str, Any]]:
        """Choose the third triangle vertex from the segmentation-mask contour.

        Step_a40 user-requested policy:
          1) Use the two selected empty ArUco sides from the vacancy/gap logic.
          2) Search the garment contour edge facing those empty sides.  This is the
             cloth edge opposite the direction where the garment shifted/outflowed.
          3) For each contour point on that edge, compute its distances to the two
             selected side midpoints, not merely to the infinite side lines.
          4) Choose points whose two midpoint distances are most equal.
          5) If several are similarly equal, choose the one with the shortest average
             distance to those two side midpoints.
        """
        detail: Dict[str, Any] = {
            "side_a": str(side_a),
            "side_b": str(side_b),
            "selection_policy": "segmentation_contour_opposite_edge_then_equal_distance_to_two_side_midpoints_then_min_average",
        }
        contour_pts, msg = _contour_points_for_circumcenter_vertex(cand0)
        detail["contour_source"] = msg
        if contour_pts is None or len(contour_pts) < max(5, int(getattr(args, "variable_overflow_circumcenter_min_contour_points", 25))):
            detail["reason"] = "not enough contour points"
            return None, None, detail

        tol = max(0.0, float(getattr(args, "variable_overflow_circumcenter_contour_equal_tolerance_mm", 12.0)))
        edge_band = max(0.0, float(getattr(args, "variable_overflow_circumcenter_contour_edge_band_mm", 95.0)))
        use_edge_filter = bool(getattr(args, "variable_overflow_circumcenter_pose_opposite_edge_filter", True))
        cloth_c = np.asarray(cloth_center, dtype=np.float32).reshape(2)
        m1 = _side_midpoint_board(side_a)
        m2 = _side_midpoint_board(side_b)
        empty_side_center = ((m1.astype(np.float32) + m2.astype(np.float32)) * 0.5).astype(np.float32)
        fill_vec = empty_side_center - cloth_c
        fill_norm = float(np.linalg.norm(fill_vec))
        if fill_norm > 1e-6:
            fill_dir = (fill_vec / fill_norm).astype(np.float32)
        else:
            fill_dir = np.array([0.0, 0.0], dtype=np.float32)
            use_edge_filter = False

        scored: List[Tuple[float, float, float, int, np.ndarray, float, float]] = []
        for idx, p in enumerate(contour_pts.astype(np.float32)):
            if not np.all(np.isfinite(p)):
                continue
            d1 = float(np.linalg.norm(p - m1.reshape(2)))
            d2 = float(np.linalg.norm(p - m2.reshape(2)))
            diff = abs(d1 - d2)
            avg = 0.5 * (d1 + d2)
            edge_proj = float(np.dot((p - cloth_c).astype(np.float32), fill_dir)) if fill_norm > 1e-6 else 0.0
            scored.append((float(diff), float(avg), float(edge_proj), int(idx), p.astype(np.float32), float(d1), float(d2)))

        detail.update({
            "num_contour_points": int(len(contour_pts)),
            "num_scored_contour_points": int(len(scored)),
            "equal_tolerance_mm": float(tol),
            "edge_band_mm": float(edge_band),
            "opposite_edge_filter": bool(use_edge_filter),
            "empty_side_center": [float(empty_side_center[0]), float(empty_side_center[1])],
            "cloth_center_for_edge_filter": [float(cloth_c[0]), float(cloth_c[1])],
            "fill_dir": [float(fill_dir[0]), float(fill_dir[1])],
        })
        if not scored:
            detail["reason"] = "no scored contour points"
            return None, None, detail

        edge_candidates = scored
        if use_edge_filter:
            max_proj = max(v[2] for v in scored)
            threshold = max_proj - edge_band
            filtered = [v for v in scored if v[2] >= threshold]
            min_need = max(5, int(getattr(args, "variable_overflow_circumcenter_min_contour_points", 25)))
            if len(filtered) >= min(5, min_need):
                edge_candidates = filtered
                detail.update({
                    "edge_filter_max_projection_mm": float(max_proj),
                    "edge_filter_threshold_mm": float(threshold),
                    "num_edge_candidates": int(len(edge_candidates)),
                    "edge_filter_fallback_used": False,
                })
            else:
                sorted_by_edge = sorted(scored, key=lambda x: (-x[2], x[1], x[0]))
                keep_n = max(5, min(len(sorted_by_edge), min_need))
                edge_candidates = sorted_by_edge[:keep_n]
                detail.update({
                    "edge_filter_max_projection_mm": float(max_proj),
                    "edge_filter_threshold_mm": float(threshold),
                    "num_edge_candidates": int(len(edge_candidates)),
                    "edge_filter_fallback_used": True,
                    "edge_filter_fallback_policy": f"top_{keep_n}_by_edge_projection",
                })
        else:
            detail["num_edge_candidates"] = int(len(edge_candidates))

        min_diff = min(v[0] for v in edge_candidates)
        similarly_balanced = [v for v in edge_candidates if v[0] <= min_diff + tol]
        similarly_balanced.sort(key=lambda x: (x[1], x[0], -x[2], x[3]))
        diff, avg, edge_proj, idx, pt, d1, d2 = similarly_balanced[0]

        top_edge = sorted(edge_candidates, key=lambda x: (x[0], x[1], -x[2], x[3]))[:10]
        top_all = sorted(scored, key=lambda x: (-x[2], x[0], x[1], x[3]))[:10]
        detail.update({
            "selected_vertex_name": "mask_contour_vertex",
            "selected_contour_index": int(idx),
            "selected_vertex_board_xy": [float(pt[0]), float(pt[1])],
            "dist_diff_to_side_midpoints_mm": float(diff),
            "mean_dist_to_side_midpoints_mm": float(avg),
            "edge_projection_mm": float(edge_proj),
            "dist_to_side_midpoint_a": float(d1),
            "dist_to_side_midpoint_b": float(d2),
            "min_dist_diff_to_side_midpoints_mm": float(min_diff),
            "num_similarly_balanced": int(len(similarly_balanced)),
            "top_edge_by_midpoint_balance": [
                {"idx": int(t[3]), "diff_mid": float(t[0]), "avg_mid": float(t[1]), "edge_proj": float(t[2]), "d_mid1": float(t[5]), "d_mid2": float(t[6])}
                for t in top_edge
            ],
            "top_all_by_edge_projection": [
                {"idx": int(t[3]), "diff_mid": float(t[0]), "avg_mid": float(t[1]), "edge_proj": float(t[2]), "d_mid1": float(t[5]), "d_mid2": float(t[6])}
                for t in top_all
            ],
        })
        return "mask_contour_vertex", pt.astype(np.float32), detail

    def _weighted_side_midpoint_target(gap_info: Dict[str, Any], side_a: str, side_b: str) -> np.ndarray:
        gaps = gap_info.get("gaps", {}) if isinstance(gap_info, dict) else {}
        g1 = max(1e-6, float(gaps.get(side_a, 0.0)))
        g2 = max(1e-6, float(gaps.get(side_b, 0.0)))
        m1 = _side_midpoint_board(side_a)
        m2 = _side_midpoint_board(side_b)
        return ((g1 * m1 + g2 * m2) / (g1 + g2)).astype(np.float32)

    def _inside_vacancy_representative_center_info(plan: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        board_inside, raw_total, _cand, src = _inside_vacancy_candidate_board_points(plan)
        info: Dict[str, Any] = {"src": src, "ok": False}
        if board_inside is None or len(board_inside) < 20:
            info["reason"] = "no board-internal garment samples"
            return info
        gap_info = _inside_vacancy_gap_info(board_inside)
        pts = board_inside[:, :2].astype(np.float32)
        pct = gap_info.get("percentiles", {})
        try:
            mask_center = np.array([
                (float(pct.get("x_low", np.percentile(pts[:, 0], 2.0))) + float(pct.get("x_high", np.percentile(pts[:, 0], 98.0)))) * 0.5,
                (float(pct.get("y_low", np.percentile(pts[:, 1], 2.0))) + float(pct.get("y_high", np.percentile(pts[:, 1], 98.0)))) * 0.5,
            ], dtype=np.float32)
        except Exception:
            mask_center = np.median(pts, axis=0).astype(np.float32)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        board_center = np.array([(float(min_bx) + float(max_bx)) * 0.5, (float(min_by) + float(max_by)) * 0.5], dtype=np.float32)
        pose_center = None
        try:
            pose_plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if pose_plan is not None and pose_plan.get("center_board_xy") is not None:
                pc = np.asarray(pose_plan.get("center_board_xy"), dtype=np.float32).reshape(2)
                if np.all(np.isfinite(pc)):
                    pose_center = pc
        except Exception:
            pose_center = None
        source = str(getattr(args, "variable_overflow_vacancy_stop_center_source", "mixed")).lower()
        center_used = mask_center.copy()
        center_source = "mask"
        if source == "pose" and pose_center is not None:
            center_used = pose_center.astype(np.float32)
            center_source = "pose"
        elif source == "mixed" and pose_center is not None:
            w = float(np.clip(getattr(args, "variable_overflow_vacancy_pose_center_weight", 0.30), 0.0, 1.0))
            center_used = ((1.0 - w) * mask_center + w * pose_center).astype(np.float32)
            center_source = f"mixed(mask={1.0-w:.2f},pose={w:.2f})"
        gaps = gap_info.get("gaps", {})
        gap_balance = float(math.hypot(float(gaps.get("01", 0.0)) - float(gaps.get("23", 0.0)),
                                       float(gaps.get("02", 0.0)) - float(gaps.get("13", 0.0))))
        center_err = float(np.linalg.norm(center_used - board_center))
        info.update({
            "ok": True,
            "board_inside_count": int(len(board_inside)),
            "mask_center": [float(mask_center[0]), float(mask_center[1])],
            "pose_center": None if pose_center is None else [float(pose_center[0]), float(pose_center[1])],
            "center_used": [float(center_used[0]), float(center_used[1])],
            "center_source": center_source,
            "board_center": [float(board_center[0]), float(board_center[1])],
            "center_error_mm": float(center_err),
            "gap_balance_mm": float(gap_balance),
            "gap_info": gap_info,
        })
        return info

    def _inside_vacancy_center_balance_stop_metrics(plan: Optional[Dict[str, Any]]) -> Tuple[bool, Optional[float], Optional[float], str, Dict[str, Any]]:
        detail = _inside_vacancy_representative_center_info(plan)
        if not bool(detail.get("ok", False)):
            msg = f"vacancy_center_balance unavailable: {detail.get('reason', detail.get('src', 'unknown'))}"
            return False, None, None, msg, detail
        center_err = float(detail.get("center_error_mm", 999999.0))
        gap_balance = float(detail.get("gap_balance_mm", 999999.0))
        center_done = float(getattr(args, "variable_overflow_vacancy_center_done_mm", 50.0))
        gap_done = float(getattr(args, "variable_overflow_vacancy_gap_balance_done_mm", 80.0))
        ok = center_err <= center_done and gap_balance <= gap_done
        msg = (f"center_source={detail.get('center_source')} center_error={center_err:.1f}mm "
               f"gap_balance={gap_balance:.1f}mm gaps={{{', '.join(f'{k}:{float(v):.1f}' for k, v in detail.get('gap_info', {}).get('gaps', {}).items())}}}")
        return bool(ok), center_err, gap_balance, msg, detail

    def _build_circumcenter_vacancy_pull_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Step_a36 / policy: inside-frame vacancy filling with an experimental circumcenter target.

        1) Use only the garment contour visible inside the ArUco board.
        2) Choose the two emptiest board sides from robust side gaps.
        3) Choose a pose keypoint whose distances to those two sides are most similar.
        4) Build a triangle from the two selected side midpoints and that pose point.
        5) Use the triangle circumcenter as the garment-center target when safe; otherwise
           fall back to the gap-weighted side-midpoint target.
        """
        board_inside, raw_total, cand, src = _inside_vacancy_candidate_board_points(plan)
        if board_inside is None or len(board_inside) < 20:
            if print_result:
                print(f"[VAR-CIRC] not ready: {src}")
            return None
        gap_info = _inside_vacancy_gap_info(board_inside)
        ordered = list(gap_info.get("ordered", []))
        if len(ordered) < 2:
            if print_result:
                print(f"[VAR-CIRC] not ready: could not order side gaps: {gap_info}")
            return None
        side_a, side_b = str(ordered[0]), str(ordered[1])
        gaps = gap_info.get("gaps", {})
        major_gap = float(gaps.get(side_a, 0.0))
        second_gap = float(gaps.get(side_b, 0.0))
        min_move = max(0.0, float(getattr(args, "variable_overflow_min_overflow_mm", 30.0)))
        if major_gap < min_move:
            if print_result:
                print(f"[VAR-CIRC] no correction needed: major_gap={major_gap:.1f}mm < {min_move:.1f}mm gaps={gaps}")
            return None

        center_info = _inside_vacancy_representative_center_info(plan)
        if bool(center_info.get("ok", False)):
            center = np.asarray(center_info.get("center_used"), dtype=np.float32).reshape(2)
        else:
            center = np.median(board_inside[:, :2].astype(np.float32), axis=0).astype(np.float32)

        m1 = _side_midpoint_board(side_a)
        m2 = _side_midpoint_board(side_b)
        vertex_source = "mask_contour" if bool(getattr(args, "variable_overflow_circumcenter_contour_vertex_mode", True)) else "pose_keypoint"
        if vertex_source == "mask_contour":
            pose_name, pose_pt, pose_detail = _choose_contour_vertex_for_circumcenter(side_a, side_b, center, cand)
        else:
            pose_name, pose_pt, pose_detail = _choose_pose_point_for_circumcenter(side_a, side_b, center)
        target_kind = "circumcenter"
        target_reason = "OK"
        radius = 0.0
        area = 0.0
        target = None
        if pose_pt is not None:
            target, radius, area, target_reason = _circumcenter_2d(m1, m2, pose_pt)
        else:
            target_reason = f"no valid {vertex_source} vertex for circumcenter"
        if target is None:
            if not bool(getattr(args, "variable_overflow_circumcenter_fallback_to_weighted", True)):
                if print_result:
                    print(f"[VAR-CIRC] blocked: {target_reason}; fallback disabled. pose={pose_detail}")
                return None
            target = _weighted_side_midpoint_target(gap_info, side_a, side_b)
            target_kind = "weighted_side_midpoint_fallback"

        target = np.asarray(target, dtype=np.float32).reshape(2)
        target_margin = float(args.boundary_recovery_target_margin)
        safe_margin = max(target_margin, max(0.0, float(getattr(args, "variable_overflow_circumcenter_safe_margin_mm", 35.0))) if target_kind == "circumcenter" else target_margin)
        tx, ty = _clamp_board_xy(float(target[0]), float(target[1]), safe_margin)
        target = np.array([tx, ty], dtype=np.float32)
        vec = target - center
        vec_norm = float(np.linalg.norm(vec))
        if vec_norm < 1e-6:
            if print_result:
                print(f"[VAR-CIRC] no correction needed: center already at target center=({center[0]:.1f},{center[1]:.1f})")
            return None
        u = (vec / vec_norm).astype(np.float32)
        gain = max(0.0, float(getattr(args, "variable_overflow_circumcenter_center_target_gain", 0.85)))
        min_pull = max(0.0, float(getattr(args, "variable_overflow_min_pull_mm", 30.0)))
        # Circumcenter uses its own base-plan cap. Keep the shared
        # variable_overflow_max_pull_mm=95mm untouched for non-Circumcenter recovery paths.
        circumcenter_base_max_pull = max(
            min_pull,
            float(getattr(args, "variable_overflow_circumcenter_base_max_pull_mm", 120.0)),
        )
        raw_dist = gain * vec_norm
        direct_to_circumcenter = bool(getattr(args, "variable_overflow_circumcenter_direct_to_center", True)) and str(target_kind) == "circumcenter"
        pull_scale = max(0.0, float(getattr(args, "variable_overflow_circumcenter_pull_scale", 1.25)))
        final_max_pull = max(0.0, float(getattr(args, "variable_overflow_circumcenter_final_max_pull_mm", 150.0)))
        fallback_base_dist = float(np.clip(raw_dist, min_pull, circumcenter_base_max_pull))

        planning_board, _cand2, plan_src = _candidate_board_points_for_variable_overflow(plan, use_raw=False)
        if planning_board is None or len(planning_board) < 20:
            planning_board = board_inside
            plan_src = src + "; using board_inside as contact pool"
        pts_all = planning_board[:, :2].astype(np.float32)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        board_safe = ((pts_all[:, 0] >= min_bx + target_margin) & (pts_all[:, 0] <= max_bx - target_margin) &
                      (pts_all[:, 1] >= min_by + target_margin) & (pts_all[:, 1] <= max_by - target_margin))
        pts_safe = pts_all[board_safe]
        if len(pts_safe) < max(5, int(getattr(args, "variable_overflow_min_inside_points", 18))):
            pts_safe = pts_all[((pts_all[:, 0] >= min_bx) & (pts_all[:, 0] <= max_bx) & (pts_all[:, 1] >= min_by) & (pts_all[:, 1] <= max_by))]
        if len(pts_safe) < 5:
            if print_result:
                print("[VAR-CIRC] blocked: no safe internal contact points")
            return None

        offset = max(0.0, float(getattr(args, "variable_overflow_vacancy_contact_offset_mm", 85.0)))
        inset = max(0.0, float(getattr(args, "variable_overflow_circumcenter_vertex_contact_inset_mm", 35.0)))
        contact_source = "fallback_center_plus_pull_offset"
        contact_vertex = None
        desired_anchor = None
        if pose_pt is not None:
            try:
                contact_vertex = np.asarray(pose_pt, dtype=np.float32).reshape(2)
                inward = center.astype(np.float32) - contact_vertex.astype(np.float32)
                inward_norm = float(np.linalg.norm(inward))
                if inward_norm > 1e-6:
                    desired_anchor = contact_vertex + (inward / inward_norm).astype(np.float32) * inset
                    contact_source = f"{vertex_source}_vertex_inset_to_center"
            except Exception:
                desired_anchor = None
        if desired_anchor is None:
            desired_anchor = center + u * offset
        ax, ay = _clamp_board_xy(float(desired_anchor[0]), float(desired_anchor[1]), target_margin)
        anchor = np.array([ax, ay], dtype=np.float32)
        center_w = max(0.0, float(getattr(args, "variable_overflow_vacancy_contact_center_weight", 0.03)))

        hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
        contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
        if args.boundary_recovery_drag_clear_z is not None:
            clear_z = float(args.boundary_recovery_drag_clear_z)
        elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
            clear_z = float(args.press_extra_clear_z)
        elif args.press_clear_z is not None:
            clear_z = float(args.press_clear_z)
        else:
            clear_z = float(hover_z)

        # ACTION1 is single-arm, so do not pre-filter contact candidates by
        # the normal left/right workspace split.  For each real safe contact candidate,
        # choose the arm from the actual start->end segment relative to the fixed side bases.
        proposals: List[Dict[str, Any]] = []
        pool = pts_safe
        d_anchor = np.linalg.norm(pool - anchor.reshape(1, 2), axis=1)
        d_center = np.linalg.norm(pool - center.reshape(1, 2), axis=1)
        base_score = d_anchor + center_w * d_center
        for jj in np.argsort(base_score)[:min(24, len(pool))]:
            start = pool[int(jj)].astype(np.float32)
            if direct_to_circumcenter:
                base_vec = target.astype(np.float32) - start
                contact_to_target_dist = float(np.linalg.norm(base_vec))
                if contact_to_target_dist <= 1e-6:
                    continue
                proposal_u = (base_vec / contact_to_target_dist).astype(np.float32)
                base_plan_dist = min(contact_to_target_dist, circumcenter_base_max_pull)
            else:
                base_plan_dist = float(fallback_base_dist)
                proposal_u = u.astype(np.float32)
            scaled_request_dist = float(base_plan_dist * pull_scale)
            if final_max_pull > 0.0:
                scaled_request_dist = min(scaled_request_dist, final_max_pull)
            end = start + proposal_u * scaled_request_dist
            ex, ey = _clamp_board_xy(float(end[0]), float(end[1]), target_margin)
            end = np.array([ex, ey], dtype=np.float32)
            arm_info = _choose_circumcenter_arm_toward_base(start, end)
            primary = str(arm_info.get("primary", ""))
            alternate = str(arm_info.get("alternate", ""))
            if primary in ("arm1", "arm2"):
                proposals.append({
                    "arm_key": primary, "start": start, "end": end,
                    "score": float(base_score[int(jj)]), "selection_rank": 0,
                    "pool": "all_safe_no_workspace_split",
                    "anchor_dist": float(d_anchor[int(jj)]), "arm_selection": arm_info,
                    "base_plan_dist": float(base_plan_dist),
                    "scaled_request_dist": float(scaled_request_dist),
                    "proposal_unit": [float(proposal_u[0]), float(proposal_u[1])],
                })
            # Keep one high-penalty resolver fallback only for kinematic/affine failure.
            # This does not override the explicit far-contact nearest-arm policy above.
            if alternate in ("arm1", "arm2"):
                proposals.append({
                    "arm_key": alternate, "start": start, "end": end,
                    "score": float(base_score[int(jj)]) + 1000.0, "selection_rank": 1,
                    "pool": "all_safe_no_workspace_split_resolver_fallback",
                    "anchor_dist": float(d_anchor[int(jj)]), "arm_selection": arm_info,
                    "base_plan_dist": float(base_plan_dist),
                    "scaled_request_dist": float(scaled_request_dist),
                    "proposal_unit": [float(proposal_u[0]), float(proposal_u[1])],
                })

        proposals.sort(key=lambda p: (int(p.get("selection_rank", 9)), float(p.get("score", 1e9))))
        chosen = None
        resolved = None
        for prop in proposals:
            arm_key = str(prop["arm_key"])
            start = np.asarray(prop["start"], dtype=np.float32).reshape(2)
            end = np.asarray(prop["end"], dtype=np.float32).reshape(2)
            hover = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), hover_z, "VAR-CIRC-HOVER")
            down_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), contact_z, "VAR-CIRC-DOWN")
            drag_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(end[0]), float(end[1]), contact_z, "VAR-CIRC-DRAG")
            down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "VAR-CIRC-DOWN") if down_raw is not None else None
            drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "VAR-CIRC-DRAG") if drag_raw is not None else None
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is not None and down is not None and drag is not None and clear is not None:
                chosen = prop
                resolved = (hover, down, drag, clear, down_raw, drag_raw)
                break
        if chosen is None or resolved is None:
            if print_result:
                print(f"[VAR-CIRC] blocked: no reachable proposal after toward-base arm selection; proposals={len(proposals)}")
            return None

        hover, down, drag, clear, down_raw, drag_raw = resolved
        arm_key = str(chosen["arm_key"])
        arm_selection = chosen.get("arm_selection", {}) if isinstance(chosen.get("arm_selection", {}), dict) else {}
        start = np.asarray(chosen["start"], dtype=np.float32).reshape(2)
        end = np.asarray(chosen["end"], dtype=np.float32).reshape(2)
        actual_vec = (end - start).astype(np.float32)
        actual_norm = float(np.linalg.norm(actual_vec))
        if actual_norm > 1e-6:
            u_actual = (actual_vec / actual_norm).astype(np.float32)
        else:
            u_actual = u.astype(np.float32)
        base_plan_dist = float(chosen.get("base_plan_dist", actual_norm))
        scaled_request_dist = float(chosen.get("scaled_request_dist", actual_norm))
        dist = float(actual_norm)
        angle_deg = float(np.degrees(np.arctan2(float(u_actual[1]), float(u_actual[0]))))
        stop_ok, center_err, gap_balance, stop_msg, stop_detail = _inside_vacancy_center_balance_stop_metrics(plan)
        direct_note = "circumcenter_base_scaled" if direct_to_circumcenter else "fallback_base_scaled"
        arm_reason = str(arm_selection.get("reason", "UNKNOWN"))
        arm_nearest = str(arm_selection.get("nearest", "NA"))
        arm_toward = str(arm_selection.get("toward", "NA"))
        arm_metrics = arm_selection.get("metrics", {}) if isinstance(arm_selection.get("metrics", {}), dict) else {}
        chosen_metric = arm_metrics.get(arm_key, {}) if isinstance(arm_metrics.get(arm_key, {}), dict) else {}
        summary = (f"circumcenter-vacancy pull arm={arm_key.upper()} arm_policy={arm_reason} nearest={arm_nearest} toward={arm_toward} "
                   f"base_d={float(chosen_metric.get('start_distance_mm', 0.0)):.1f}->{float(chosen_metric.get('end_distance_mm', 0.0)):.1f} "
                   f"base_gain={float(chosen_metric.get('approach_gain_mm', 0.0)):+.1f}mm angle={angle_deg:+.1f}deg "
                   f"target_kind={target_kind} direct_mode={direct_note} center_target=({target[0]:.1f},{target[1]:.1f}) center=({center[0]:.1f},{center[1]:.1f}) "
                   f"center_to_target={vec_norm:.1f} raw_dist={raw_dist:.1f} base_dist={base_plan_dist:.1f} "
                   f"base_cap={circumcenter_base_max_pull:.1f} scale={pull_scale:.3f} "
                   f"scaled_request={scaled_request_dist:.1f} final_cap={final_max_pull:.1f} actual_dist={dist:.1f}mm "
                   f"sides=({side_a},{side_b}) gaps={{{', '.join(f'{k}:{float(v):.1f}' for k, v in gaps.items())}}} "
                   f"triangle_vertex={pose_name} source={vertex_source} circum_reason={target_reason} radius={radius:.1f} area={area:.1f} "
                   f"start=({start[0]:.1f},{start[1]:.1f}) -> end=({end[0]:.1f},{end[1]:.1f}) "
                   f"anchor=({anchor[0]:.1f},{anchor[1]:.1f}) contact_source={contact_source} inset={inset:.1f} "
                   f"center_err={'NA' if center_err is None else f'{center_err:.1f}'} gap_balance={'NA' if gap_balance is None else f'{gap_balance:.1f}'})")
        vp = {
            "mode": "drag",
            "recovery_kind": "circumcenter_vacancy_pull",
            "overflow_mode": "circumcenter_vacancy",
            "side": str(side_a),
            "arm_key": arm_key,
            "arm_selection_info": copy.deepcopy(arm_selection),
            "side_gap_mm": gaps,
            "side_overflow_mm": gaps,
            "vacancy_info": gap_info,
            "circumcenter_info": {
                "target_kind": target_kind,
                "target_reason": target_reason,
                "side_a": side_a,
                "side_b": side_b,
                "side_midpoint_a": [float(m1[0]), float(m1[1])],
                "side_midpoint_b": [float(m2[0]), float(m2[1])],
                "pose_point_name": pose_name,
                "pose_point_board_xy": None if pose_pt is None else [float(pose_pt[0]), float(pose_pt[1])],
                "pose_detail": pose_detail,
                "vertex_source": vertex_source,
                "triangle_vertex_name": pose_name,
                "triangle_vertex_board_xy": None if pose_pt is None else [float(pose_pt[0]), float(pose_pt[1])],
                "triangle_vertex_detail": pose_detail,
                "contact_source": contact_source,
                "contact_anchor_board_xy": [float(anchor[0]), float(anchor[1])],
                "contact_vertex_board_xy": None if contact_vertex is None else [float(contact_vertex[0]), float(contact_vertex[1])],
                "contact_inset_mm": float(inset),
                "circumradius_mm": float(radius),
                "triangle_area_mm2": float(area),
                "direct_to_circumcenter": bool(direct_to_circumcenter),
                "base_plan_distance_mm": float(base_plan_dist),
                "base_max_pull_mm": float(circumcenter_base_max_pull),
                "pull_scale": float(pull_scale),
                "scaled_request_distance_mm": float(scaled_request_dist),
                "final_max_pull_mm": float(final_max_pull),
                "actual_pull_distance_mm": float(dist),
            },
            "center_info": center_info,
            "center_error_mm": None if center_err is None else float(center_err),
            "gap_balance_mm": None if gap_balance is None else float(gap_balance),
            "major": float(major_gap),
            "minor": float(second_gap),
            "reachable_points": int(len(pts_safe)),
            "start_board_xy": [float(start[0]), float(start[1])],
            "end_board_xy": [float(end[0]), float(end[1])],
            "pull_vector": [float(u_actual[0]), float(u_actual[1])],
            "pull_distance": float(dist),
            "policy": "inside_frame_circumcenter_vacancy_fill",
            "contact_target_type": "center_target_circumcenter_or_weighted_side_midpoint",
            "contact_source": contact_source,
            "contact_target": [float(target[0]), float(target[1])],
            "raw_mask_source": src,
            "planning_mask_source": plan_src,
            "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
            "hover": hover,
            "down": down,
            "drag": drag,
            "clear": clear,
            "down_raw": down_raw,
            "drag_raw": drag_raw,
            "summary": summary,
        }
        if print_result:
            print("\n========== CIRCUMCENTER INSIDE-VACANCY PULL PLAN (/) ==========")
            print(summary)
            print(f"stop_check: {stop_msg}")
            print("Policy: build the original circumcenter/fallback direction, then multiply its planned pull distance by the Circumcenter scale and apply the final safety cap.")
            print("Arm policy A132: normal x-workspace split is ignored for this single-arm ACTION1; choose the arm whose side-base becomes closer along the actual contact drag. If that arm is too far across the board, fall back to the nearer arm.")
            print("==============================================================\n")
        return vp

    def _build_inside_vacancy_pull_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Step_a35 / policy: use only board-internal garment frame side gaps.

        1) Measure distance from each ArUco rectangle side to the nearest robust garment frame.
        2) Pull toward the emptiest side(s) using the side-gap ratio.
        3) Use the arm on the side being pulled to: +x->ARM1, -x->ARM2.
        """
        board_inside, raw_total, cand, src = _inside_vacancy_candidate_board_points(plan)
        if board_inside is None or len(board_inside) < 20:
            if print_result:
                print(f"[VAR-VACANCY] not ready: {src}")
            return None
        gap_info = _inside_vacancy_gap_info(board_inside)
        u = np.asarray(gap_info.get("pull_unit", [0.0, 0.0]), dtype=np.float32).reshape(2)
        un = float(np.linalg.norm(u))
        min_move = max(0.0, float(getattr(args, "variable_overflow_min_overflow_mm", 30.0)))
        vacancy_norm = float(gap_info.get("vacancy_norm", 0.0))
        if un < 1e-6 or vacancy_norm < min_move:
            if print_result:
                print(f"[VAR-VACANCY] no correction needed: vacancy_norm={vacancy_norm:.1f}mm < {min_move:.1f}mm gaps={gap_info.get('gaps')}")
            return None
        u = u / un
        gain = max(0.0, float(getattr(args, "variable_overflow_gain", 0.80)))
        min_pull = max(0.0, float(getattr(args, "variable_overflow_min_pull_mm", 30.0)))
        max_pull = max(min_pull, float(getattr(args, "variable_overflow_max_pull_mm", 95.0)))
        raw_dist = gain * vacancy_norm
        dist = float(np.clip(raw_dist, min_pull, max_pull))

        planning_board, _cand2, plan_src = _candidate_board_points_for_variable_overflow(plan, use_raw=False)
        if planning_board is None or len(planning_board) < 20:
            planning_board = board_inside
            plan_src = src + "; using board_inside as contact pool"
        pts_all = planning_board[:, :2].astype(np.float32)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(args.boundary_recovery_target_margin)
        board_safe = ((pts_all[:, 0] >= min_bx + target_margin) & (pts_all[:, 0] <= max_bx - target_margin) &
                      (pts_all[:, 1] >= min_by + target_margin) & (pts_all[:, 1] <= max_by - target_margin))
        pts_safe = pts_all[board_safe]
        if len(pts_safe) < max(5, int(getattr(args, "variable_overflow_min_inside_points", 18))):
            pts_safe = pts_all[((pts_all[:, 0] >= min_bx) & (pts_all[:, 0] <= max_bx) & (pts_all[:, 1] >= min_by) & (pts_all[:, 1] <= max_by))]
        if len(pts_safe) < 5:
            if print_result:
                print("[VAR-VACANCY] blocked: no safe internal contact points")
            return None

        center = np.median(board_inside[:, :2].astype(np.float32), axis=0).astype(np.float32)
        offset = max(0.0, float(getattr(args, "variable_overflow_vacancy_contact_offset_mm", 85.0)))
        anchor = center + u * offset
        ax, ay = _clamp_board_xy(float(anchor[0]), float(anchor[1]), target_margin)
        anchor = np.array([ax, ay], dtype=np.float32)
        center_w = max(0.0, float(getattr(args, "variable_overflow_vacancy_contact_center_weight", 0.03)))
        workspace_penalty = max(0.0, float(getattr(args, "variable_overflow_vacancy_workspace_penalty", 250.0)))
        preferred = _vacancy_preferred_arm_from_unit(u, contact_x=float(anchor[0]))
        arm_order = [preferred] if preferred in ("arm1", "arm2") else []
        for ak in ("arm1", "arm2"):
            if ak not in arm_order:
                arm_order.append(ak)

        hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
        contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
        if args.boundary_recovery_drag_clear_z is not None:
            clear_z = float(args.boundary_recovery_drag_clear_z)
        elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
            clear_z = float(args.press_extra_clear_z)
        elif args.press_clear_z is not None:
            clear_z = float(args.press_clear_z)
        else:
            clear_z = float(hover_z)

        proposals: List[Dict[str, Any]] = []
        for arm_key in arm_order:
            ws = _variable_arm_workspace_mask(pts_safe, arm_key)
            pools = []
            if int(np.count_nonzero(ws)) >= max(3, int(getattr(args, "variable_overflow_min_inside_points", 18))):
                pools.append(("workspace", pts_safe[ws], 0.0))
            # For horizontal pulls, do not use the opposite arm unless the preferred arm has no reachable solution.
            pools.append(("all_safe_with_penalty", pts_safe, workspace_penalty))
            for pool_name, pool, pen in pools:
                if len(pool) < 5:
                    continue
                d_anchor = np.linalg.norm(pool - anchor.reshape(1, 2), axis=1)
                d_center = np.linalg.norm(pool - center.reshape(1, 2), axis=1)
                score = d_anchor + center_w * d_center + pen + (0.0 if arm_key == preferred else workspace_penalty * 0.5)
                for jj in np.argsort(score)[:min(10, len(pool))]:
                    start = pool[int(jj)].astype(np.float32)
                    end = start + u * dist
                    ex, ey = _clamp_board_xy(float(end[0]), float(end[1]), target_margin)
                    end = np.array([ex, ey], dtype=np.float32)
                    proposals.append({"arm_key": arm_key, "start": start, "end": end, "score": float(score[int(jj)]), "pool": pool_name, "anchor_dist": float(d_anchor[int(jj)])})

        proposals.sort(key=lambda p: float(p.get("score", 1e9)))
        chosen = None
        resolved = None
        for prop in proposals:
            arm_key = str(prop["arm_key"])
            start = np.asarray(prop["start"], dtype=np.float32).reshape(2)
            end = np.asarray(prop["end"], dtype=np.float32).reshape(2)
            hover = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), hover_z, "VAR-VAC-HOVER")
            down_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), contact_z, "VAR-VAC-DOWN")
            drag_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(end[0]), float(end[1]), contact_z, "VAR-VAC-DRAG")
            down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "VAR-VAC-DOWN") if down_raw is not None else None
            drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "VAR-VAC-DRAG") if drag_raw is not None else None
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is not None and down is not None and drag is not None and clear is not None:
                chosen = prop
                resolved = (hover, down, drag, clear, down_raw, drag_raw)
                break
        if chosen is None or resolved is None:
            if print_result:
                print(f"[VAR-VACANCY] blocked: no reachable proposal. preferred_arm={preferred} proposals={len(proposals)}")
            return None

        hover, down, drag, clear, down_raw, drag_raw = resolved
        arm_key = str(chosen["arm_key"])
        start = np.asarray(chosen["start"], dtype=np.float32).reshape(2)
        end = np.asarray(chosen["end"], dtype=np.float32).reshape(2)
        angle_deg = float(np.degrees(np.arctan2(float(u[1]), float(u[0]))))
        ratio, pose_center_err, stop_msg, stop_detail = _inside_vacancy_stop_metrics(plan)
        summary = (f"inside-vacancy pull arm={arm_key.upper()} preferred={preferred} angle={angle_deg:+.1f}deg "
                   f"vacancy_norm={vacancy_norm:.1f} raw_dist={raw_dist:.1f} dist={dist:.1f}mm "
                   f"gaps={{{', '.join(f'{k}:{float(v):.1f}' for k, v in gap_info['gaps'].items())}}} "
                   f"selected={gap_info.get('selected')} start=({start[0]:.1f},{start[1]:.1f}) -> end=({end[0]:.1f},{end[1]:.1f}) "
                   f"anchor=({anchor[0]:.1f},{anchor[1]:.1f}) pool={chosen.get('pool')} inside_ratio={'NA' if ratio is None else f'{ratio:.3f}'} "
                   f"pose_center_err={'NA' if pose_center_err is None else f'{pose_center_err:.1f}'}")
        vp = {
            "mode": "drag",
            "recovery_kind": "inside_vacancy_pull",
            "overflow_mode": "inside_vacancy",
            "side": str(gap_info.get("major_side", "?")),
            "arm_key": arm_key,
            "side_gap_mm": gap_info.get("gaps", {}),
            "side_overflow_mm": gap_info.get("gaps", {}),
            "inside_ratio": None if ratio is None else float(ratio),
            "pose_center_error_mm": None if pose_center_err is None else float(pose_center_err),
            "vacancy_info": gap_info,
            "major": float(gap_info.get("major_gap", 0.0)),
            "minor": float(gap_info.get("second_gap", 0.0)),
            "minor_share": float(gap_info.get("second_share", 0.0)),
            "reachable_points": int(len(pts_safe)),
            "start_board_xy": [float(start[0]), float(start[1])],
            "end_board_xy": [float(end[0]), float(end[1])],
            "pull_vector": [float(u[0]), float(u[1])],
            "pull_distance": float(dist),
            "policy": "inside_frame_side_gap_vacancy_fill",
            "contact_target_type": "inside_vacancy_anchor",
            "contact_target": [float(anchor[0]), float(anchor[1])],
            "raw_mask_source": src,
            "planning_mask_source": plan_src,
            "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
            "hover": hover,
            "down": down,
            "drag": drag,
            "clear": clear,
            "down_raw": down_raw,
            "drag_raw": drag_raw,
            "summary": summary,
        }
        if print_result:
            print("\n========== INSIDE-FRAME VACANCY PULL PLAN (/) ==========")
            print(summary)
            print(f"stop_check: {stop_msg}")
            print("Policy: use only board-internal garment frame; pull toward the emptiest board side(s). Horizontal target side determines arm: 23->ARM1, 01->ARM2.")
            print("=======================================================\n")
        return vp

    def _continuous_overflow_vector_info(raw_board: np.ndarray) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:
        """Compute a general inward correction vector from all outside garment-mask points.

        Step_a33 algorithm:
          - Do not classify into 01/23/02/13/corner cases.
          - For every full-garment board point outside the safe board rectangle, compute
            the nearest point on the safe rectangle.
          - The vector from outside point to that nearest safe point is its required
            inward displacement.
          - The weighted mean of those vectors becomes the pull direction; the pull depth
            is a high percentile of outside-point distances.
        """
        info = _variable_side_overflows_from_board(raw_board)
        try:
            if raw_board is None or len(raw_board) < 20:
                return None, info
            pts = raw_board[:, :2].astype(np.float32)
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            frame_margin = max(0.0, float(getattr(args, "variable_overflow_frame_margin_mm", 0.0)))
            cont_margin = max(0.0, float(getattr(args, "variable_overflow_continuous_safe_margin_mm", 0.0)))
            m = frame_margin + cont_margin
            left = float(min_bx + m)
            right = float(max_bx - m)
            bottom = float(min_by + m)
            top = float(max_by - m)
            if left >= right or bottom >= top:
                return None, info

            nearest = pts.copy()
            nearest[:, 0] = np.clip(nearest[:, 0], left, right)
            nearest[:, 1] = np.clip(nearest[:, 1], bottom, top)
            vecs = nearest - pts
            d = np.linalg.norm(vecs, axis=1)
            outside = d > 1e-3
            outside_count = int(np.count_nonzero(outside))
            outside_ratio = float(outside_count / max(1, len(pts)))
            min_ratio = max(0.0, float(getattr(args, "variable_overflow_continuous_min_outside_ratio", 0.002)))
            min_overflow = max(0.0, float(getattr(args, "variable_overflow_min_overflow_mm", 30.0)))
            if outside_count < 5 or outside_ratio < min_ratio:
                return None, info

            v_out = vecs[outside].astype(np.float32)
            d_out = d[outside].astype(np.float32)
            pct = float(np.clip(getattr(args, "variable_overflow_continuous_percentile", 90.0), 50.0, 100.0))
            depth = float(np.percentile(d_out, pct))
            max_depth = float(np.max(d_out))
            mean_depth = float(np.mean(d_out))
            if depth < min_overflow:
                return None, info

            w = np.maximum(d_out, 1.0).reshape(-1, 1)
            v_mean = np.sum(v_out * w, axis=0) / max(1e-6, float(np.sum(w)))
            v_norm = float(np.linalg.norm(v_mean))
            if v_norm < 1e-6:
                j = int(np.argmax(d_out))
                v_mean = v_out[j]
                v_norm = float(np.linalg.norm(v_mean))
            if v_norm < 1e-6:
                sides = info.get("sides", {})
                if not sides:
                    return None, info
                k = max(sides.keys(), key=lambda kk: float(sides[kk].get("overflow", 0.0)))
                v_mean = np.asarray(sides[k].get("unit", [0.0, 0.0]), dtype=np.float32)
                v_norm = float(np.linalg.norm(v_mean))
                if v_norm < 1e-6:
                    return None, info

            unit = (v_mean / v_norm).astype(np.float32)
            angle_deg = float(np.degrees(np.arctan2(float(unit[1]), float(unit[0]))))
            depths = {k: float(v.get("overflow", 0.0)) for k, v in info.get("sides", {}).items()}
            max_side = max(depths.keys(), key=lambda kk: depths[kk]) if depths else "?"
            info["continuous"] = {
                "outside_count": outside_count,
                "outside_ratio": outside_ratio,
                "depth_mm": depth,
                "max_depth_mm": max_depth,
                "mean_depth_mm": mean_depth,
                "pull_unit": [float(unit[0]), float(unit[1])],
                "angle_deg": angle_deg,
                "safe_limits": {"left": left, "right": right, "bottom": bottom, "top": top},
            }
            return {
                "mode": "continuous",
                "main_side": str(max_side),
                "arm_key": "auto",
                "overflow_norm": float(depth),
                "pull_unit": unit,
                "major": float(depth),
                "minor": 0.0,
                "minor_share": 0.0,
                "outside_ratio": outside_ratio,
                "outside_count": outside_count,
                "max_depth": max_depth,
                "mean_depth": mean_depth,
                "policy": "continuous_outside_points_to_safe_board",
            }, info
        except Exception as e:
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[VAR-CONTINUOUS] vector calc failed: {repr(e)}")
            return None, info

    def _continuous_contact_proposals(planning_board: np.ndarray, unit: np.ndarray, pull_distance: float) -> List[Dict[str, Any]]:
        """Return ranked arm/contact proposals for continuous vector pull.

        Contact is chosen from the board-internal stable garment mask.  The target
        anchor is cloth_center - unit * offset, meaning: grab an internal point toward
        the overflowing side, then drag it in the inward correction direction.
        """
        props: List[Dict[str, Any]] = []
        try:
            if planning_board is None or len(planning_board) < 20:
                return props
            pts_all = planning_board[:, :2].astype(np.float32)
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            target_margin = float(args.boundary_recovery_target_margin)
            safe = ((pts_all[:, 0] >= min_bx + target_margin) & (pts_all[:, 0] <= max_bx - target_margin) &
                    (pts_all[:, 1] >= min_by + target_margin) & (pts_all[:, 1] <= max_by - target_margin))
            pts_safe = pts_all[safe]
            if len(pts_safe) < max(5, int(getattr(args, "variable_overflow_min_inside_points", 18))):
                board_inside = ((pts_all[:, 0] >= min_bx) & (pts_all[:, 0] <= max_bx) &
                                (pts_all[:, 1] >= min_by) & (pts_all[:, 1] <= max_by))
                pts_safe = pts_all[board_inside]
            if len(pts_safe) < 5:
                return props

            unit = np.asarray(unit, dtype=np.float32).reshape(2)
            un = float(np.linalg.norm(unit))
            if un < 1e-6:
                return props
            unit = unit / un
            center = np.median(pts_safe, axis=0).astype(np.float32)
            offset = max(0.0, float(getattr(args, "variable_overflow_continuous_contact_offset_mm", 85.0)))
            anchor = center - unit * offset
            ax, ay = _clamp_board_xy(float(anchor[0]), float(anchor[1]), target_margin)
            anchor = np.array([ax, ay], dtype=np.float32)
            center_w = max(0.0, float(getattr(args, "variable_overflow_continuous_contact_center_weight", 0.03)))
            workspace_penalty = max(0.0, float(getattr(args, "variable_overflow_continuous_workspace_penalty", 250.0)))
            arm_dir_w = max(0.0, float(getattr(args, "variable_overflow_continuous_prefer_arm_direction_weight", 35.0)))
            min_pts = max(3, int(getattr(args, "variable_overflow_min_inside_points", 18)))

            for arm_key in ("arm1", "arm2"):
                ws = _variable_arm_workspace_mask(pts_safe, arm_key)
                # Prefer each arm's nominal workspace, but keep an all-safe fallback.  The final
                # relaxed resolver still rejects unreachable RoArm coordinates.
                pools = []
                if int(np.count_nonzero(ws)) >= min_pts:
                    pools.append(("workspace", pts_safe[ws], 0.0))
                pools.append(("all_safe_with_penalty", pts_safe, workspace_penalty))

                swap_arm = bool(getattr(args, "variable_overflow_swap_arm_selection", True))
                ux = float(unit[0])
                if not swap_arm:
                    if arm_key == "arm1":
                        dir_bonus = arm_dir_w * max(0.0, ux)
                    else:
                        dir_bonus = arm_dir_w * max(0.0, -ux)
                else:
                    if arm_key == "arm1":
                        dir_bonus = arm_dir_w * max(0.0, -ux)
                    else:
                        dir_bonus = arm_dir_w * max(0.0, ux)

                for pool_name, pool, pool_penalty in pools:
                    if len(pool) < 5:
                        continue
                    d_anchor = np.linalg.norm(pool - anchor.reshape(1, 2), axis=1)
                    d_center = np.linalg.norm(pool - center.reshape(1, 2), axis=1)
                    score = d_anchor + center_w * d_center + pool_penalty - dir_bonus
                    order = np.argsort(score)[:min(8, len(pool))]
                    for jj in order:
                        start = pool[int(jj)].astype(np.float32)
                        end = start + unit * float(pull_distance)
                        ex, ey = _clamp_board_xy(float(end[0]), float(end[1]), target_margin)
                        end = np.array([ex, ey], dtype=np.float32)
                        props.append({
                            "arm_key": arm_key,
                            "start": start,
                            "end": end,
                            "score": float(score[int(jj)]),
                            "pool": pool_name,
                            "anchor": anchor.copy(),
                            "center": center.copy(),
                            "points": int(len(pool)),
                            "anchor_dist": float(d_anchor[int(jj)]),
                        })
            props.sort(key=lambda d: float(d.get("score", 1e9)))
            return props
        except Exception as e:
            if bool(getattr(args, "fallback_print_debug", False)):
                print(f"[VAR-CONTINUOUS] contact proposal failed: {repr(e)}")
            return props

    def _build_continuous_vector_pull_plan(raw_board: np.ndarray, planning_board: np.ndarray,
                                           raw_src: str, plan_src: str,
                                           print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Build the Step_a33 general / plan: outside-mask vector -> internal pull contact."""
        mode, overflow_info = _continuous_overflow_vector_info(raw_board)
        sides = overflow_info.get("sides", {}) if isinstance(overflow_info, dict) else {}
        if mode is None:
            if print_result:
                depths = {k: round(float(v.get("overflow", 0.0)), 1) for k, v in sides.items()}
                cont = overflow_info.get("continuous", {}) if isinstance(overflow_info, dict) else {}
                print(f"[VAR-CONTINUOUS] no correction needed/available. side_overflow_mm={depths} continuous={cont}")
            return None

        u = np.asarray(mode["pull_unit"], dtype=np.float32).reshape(2)
        un = float(np.linalg.norm(u))
        if un < 1e-6:
            if print_result:
                print("[VAR-CONTINUOUS] invalid zero correction vector")
            return None
        u = u / un
        gain = max(0.0, float(getattr(args, "variable_overflow_gain", 0.80)))
        min_pull = max(0.0, float(getattr(args, "variable_overflow_min_pull_mm", 30.0)))
        max_pull = max(min_pull, float(getattr(args, "variable_overflow_max_pull_mm", 95.0)))
        raw_dist = gain * float(mode["overflow_norm"])
        dist = float(np.clip(raw_dist, min_pull, max_pull))

        hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
        contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
        if args.boundary_recovery_drag_clear_z is not None:
            clear_z = float(args.boundary_recovery_drag_clear_z)
        elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
            clear_z = float(args.press_extra_clear_z)
        elif args.press_clear_z is not None:
            clear_z = float(args.press_clear_z)
        else:
            clear_z = float(hover_z)

        proposals = _continuous_contact_proposals(planning_board, u, dist)
        chosen = None
        resolved = None
        for prop in proposals:
            arm_key = str(prop["arm_key"])
            start = np.asarray(prop["start"], dtype=np.float32).reshape(2)
            end = np.asarray(prop["end"], dtype=np.float32).reshape(2)
            hover = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), hover_z, "VAR-CONT-HOVER")
            down_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start[0]), float(start[1]), contact_z, "VAR-CONT-DOWN")
            drag_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(end[0]), float(end[1]), contact_z, "VAR-CONT-DRAG")
            down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "VAR-CONT-DOWN") if down_raw is not None else None
            drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "VAR-CONT-DRAG") if drag_raw is not None else None
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is not None and down is not None and drag is not None and clear is not None:
                chosen = prop
                resolved = (hover, down, drag, clear, down_raw, drag_raw)
                break
        if chosen is None or resolved is None:
            if print_result:
                print(f"[VAR-CONTINUOUS] blocked: no reachable contact/drag proposal. proposals={len(proposals)}")
            return None

        hover, down, drag, clear, down_raw, drag_raw = resolved
        arm_key = str(chosen["arm_key"])
        start = np.asarray(chosen["start"], dtype=np.float32).reshape(2)
        end = np.asarray(chosen["end"], dtype=np.float32).reshape(2)
        depths = {k: float(v.get("overflow", 0.0)) for k, v in sides.items()}
        ratios = {k: float(v.get("outside_ratio", 0.0)) for k, v in sides.items()}
        cont = overflow_info.get("continuous", {}) if isinstance(overflow_info, dict) else {}
        angle_deg = float(np.degrees(np.arctan2(float(u[1]), float(u[0]))))
        swap_arm = bool(getattr(args, "variable_overflow_swap_arm_selection", True))
        summary = (f"continuous vector pull arm={arm_key.upper()} angle={angle_deg:+.1f}deg "
                   f"depth={float(mode['overflow_norm']):.1f}mm raw_dist={raw_dist:.1f} dist={dist:.1f}mm "
                   f"outside_ratio={float(mode.get('outside_ratio',0.0)):.3f} "
                   f"start=({start[0]:.1f},{start[1]:.1f}) -> end=({end[0]:.1f},{end[1]:.1f}) "
                   f"anchor=({chosen['anchor'][0]:.1f},{chosen['anchor'][1]:.1f}) pool={chosen.get('pool')} "
                   f"swap_arm={'ON' if swap_arm else 'OFF'} score={chosen.get('score',0.0):.1f}")
        vp = {
            "mode": "drag",
            "recovery_kind": "continuous_vector_overflow_pull",
            "overflow_mode": "continuous",
            "side": str(mode.get("main_side", "continuous")),
            "arm_key": arm_key,
            "side_overflow_mm": depths,
            "side_outside_ratio": ratios,
            "overflow_percentiles": overflow_info.get("percentiles", {}),
            "overflow_limits": overflow_info.get("limits", {}),
            "continuous_info": cont,
            "major": float(mode.get("major", mode["overflow_norm"])),
            "minor": 0.0,
            "minor_share": 0.0,
            "reachable_points": int(chosen.get("points", 0)),
            "start_board_xy": [float(start[0]), float(start[1])],
            "end_board_xy": [float(end[0]), float(end[1])],
            "pull_vector": [float(u[0]), float(u[1])],
            "pull_distance": float(dist),
            "policy": "continuous_vector_pull_from_internal_mask",
            "contact_target_type": "continuous_anchor",
            "contact_target": [float(chosen["anchor"][0]), float(chosen["anchor"][1])],
            "raw_mask_source": raw_src,
            "planning_mask_source": plan_src,
            "swap_arm_selection": bool(swap_arm),
            "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
            "hover": hover,
            "down": down,
            "drag": drag,
            "clear": clear,
            "down_raw": down_raw,
            "drag_raw": drag_raw,
            "summary": summary,
        }
        if print_result:
            print("\n========== CONTINUOUS VECTOR OVERFLOW PLAN (/) ==========")
            print(summary)
            print(f"side_overflow_mm={{{', '.join(f'{k}:{v:.1f}' for k, v in depths.items())}}}")
            print(f"continuous={cont}")
            print("Policy: full-garment outside points -> inward correction vector; contact is an internal board-safe cloth point near the overflowing side.")
            print(f"ARM selection swap: {'ON (ARM1/ARM2 preference reversed)' if swap_arm else 'OFF'}")
            print("========================================================\n")
        return vp

    def _build_pose_neck_pull_in_plan(raw_board: np.ndarray, planning_board: np.ndarray,
                                      overflow_info: Dict[str, Any], raw_src: str, plan_src: str,
                                      print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Build the new Step_a32 / plan.

        If max overflow >= trigger, grab slightly inside the pose neck and drag along
        the path toward the board-internal point 50 mm above the ID1-ID3 bottom side.
        """
        try:
            sides = overflow_info.get("sides", {}) if isinstance(overflow_info, dict) else {}
            depths = {k: float(v.get("overflow", 0.0)) for k, v in sides.items()}
            if not depths:
                return None
            max_side = max(depths.keys(), key=lambda k: depths[k])
            max_ov = float(depths[max_side])
            trigger = max(0.0, float(getattr(args, "variable_overflow_pose_neck_trigger_mm", 30.0)))
            if max_ov < trigger:
                if print_result:
                    print(f"[VAR-POSE-NECK] no pose-neck pull needed: max_overflow={max_ov:.1f}mm < trigger={trigger:.1f}mm depths={depths}")
                return None

            start_b, start_msg, start_detail = _pose_neck_grip_board_xy_from_latest_pose(planning_board)
            if start_b is None:
                if print_result:
                    print(f"[VAR-POSE-NECK] blocked: {start_msg}")
                return None
            target_b = _pose_neck_pull_target_board_xy()
            if target_b is None:
                if print_result:
                    print("[VAR-POSE-NECK] blocked: bottom-center internal target failed")
                return None

            move_vec = target_b - start_b
            move_norm = float(np.linalg.norm(move_vec))
            if move_norm < 1e-6:
                if print_result:
                    print("[VAR-POSE-NECK] already at target; no move")
                return None
            u = move_vec / move_norm
            max_pull = max(1.0, float(getattr(args, "variable_overflow_pose_neck_max_pull_mm", 160.0)))
            min_pull = max(0.0, float(getattr(args, "variable_overflow_min_pull_mm", 30.0)))
            dist = float(np.clip(move_norm, min_pull if move_norm >= min_pull else 0.0, max_pull))
            if dist <= 1e-6:
                return None
            end_b = start_b + u * dist
            target_margin = float(args.boundary_recovery_target_margin)
            end_b = np.array(_clamp_board_xy(float(end_b[0]), float(end_b[1]), target_margin), dtype=np.float32)

            arm_key = _choose_arm_for_pose_neck_pull(start_b)
            hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
            contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
            if args.boundary_recovery_drag_clear_z is not None:
                clear_z = float(args.boundary_recovery_drag_clear_z)
            elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
                clear_z = float(args.press_extra_clear_z)
            elif args.press_clear_z is not None:
                clear_z = float(args.press_clear_z)
            else:
                clear_z = float(hover_z)

            hover = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start_b[0]), float(start_b[1]), hover_z, "POSE-NECK-HOVER")
            down_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(start_b[0]), float(start_b[1]), contact_z, "POSE-NECK-DOWN")
            drag_raw = _resolve_board_target_for_arm_relaxed_variable(arm_key, float(end_b[0]), float(end_b[1]), contact_z, "POSE-NECK-DRAG")
            down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "POSE-NECK-DOWN") if down_raw is not None else None
            drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "POSE-NECK-DRAG") if drag_raw is not None else None
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is None or down is None or drag is None or clear is None:
                if print_result:
                    print(f"[VAR-POSE-NECK] blocked: resolved target unsafe for {arm_key.upper()}")
                return None

            ratios = {k: float(v.get("outside_ratio", 0.0)) for k, v in sides.items()}
            angle_deg = float(np.degrees(np.arctan2(float(u[1]), float(u[0]))))
            summary = (f"pose-neck pull-in arm={arm_key.upper()} max_side={max_side} max_overflow={max_ov:.1f}mm "
                       f"neck_inset_start=({start_b[0]:.1f},{start_b[1]:.1f}) -> "
                       f"bottom_internal_target=({target_b[0]:.1f},{target_b[1]:.1f}) "
                       f"end=({end_b[0]:.1f},{end_b[1]:.1f}) dist={dist:.1f}/{move_norm:.1f}mm "
                       f"angle={angle_deg:+.1f}deg snap={start_detail.get('snap_used')}")
            vp = {
                "mode": "drag",
                "recovery_kind": "pose_neck_pull_in",
                "overflow_mode": "pose_neck",
                "side": str(max_side),
                "arm_key": arm_key,
                "side_overflow_mm": depths,
                "side_outside_ratio": ratios,
                "overflow_percentiles": overflow_info.get("percentiles", {}),
                "overflow_limits": overflow_info.get("limits", {}),
                "major": float(max_ov),
                "minor": 0.0,
                "minor_share": 0.0,
                "reachable_points": int(len(planning_board)) if planning_board is not None else 0,
                "start_board_xy": [float(start_b[0]), float(start_b[1])],
                "end_board_xy": [float(end_b[0]), float(end_b[1])],
                "pull_vector": [float(u[0]), float(u[1])],
                "pull_distance": float(dist),
                "policy": "pose_neck_to_bottom_mid_plus_50mm",
                "contact_target_type": "pose_neck",
                "contact_target": "ID1_ID3_midpoint_inward",
                "pose_neck_detail": start_detail,
                "raw_mask_source": raw_src,
                "planning_mask_source": plan_src,
                "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
                "hover": hover,
                "down": down,
                "drag": drag,
                "clear": clear,
                "down_raw": down_raw,
                "drag_raw": drag_raw,
                "summary": summary,
            }
            if print_result:
                print("\n========== POSE-NECK OVERFLOW PULL-IN PLAN (/) ==========")
                print(summary)
                print(f"side_overflow_mm={{{', '.join(f'{k}:{v:.1f}' for k, v in depths.items())}}}")
                print(f"pose={start_msg}")
                print("Policy: if any side overflow >= trigger, grip slightly inside neck_center and drag toward 50 mm inside from ID1-ID3 bottom midpoint.")
                print("========================================================\n")
            return vp
        except Exception as e:
            if print_result:
                print(f"[VAR-POSE-NECK] failed: {repr(e)}")
            return None

    def build_variable_overflow_recovery_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        if not bool(getattr(args, "variable_overflow_recovery_mode", True)):
            if print_result:
                print("[VAR-OVERFLOW] variable overflow recovery mode is OFF")
            return None
        if bool(getattr(args, "variable_overflow_circumcenter_vacancy_mode", True)):
            vp_circ = _build_circumcenter_vacancy_pull_plan(plan, print_result=print_result)
            if vp_circ is not None:
                return vp_circ
            if not bool(getattr(args, "variable_overflow_circumcenter_fallback_to_weighted", True)):
                return None
            if print_result:
                print("[VAR-CIRC] falling back to plain inside-vacancy weighted side-midpoint pull plan")
        if bool(getattr(args, "variable_overflow_inside_vacancy_mode", True)):
            return _build_inside_vacancy_pull_plan(plan, print_result=print_result)

        raw_board, cand, raw_src = _candidate_board_points_for_variable_overflow(plan, use_raw=True)
        planning_board, _cand2, plan_src = _candidate_board_points_for_variable_overflow(plan, use_raw=False)
        if raw_board is None or planning_board is None:
            if print_result:
                print(f"[VAR-OVERFLOW] not ready: raw={raw_src}, planning={plan_src}")
            return None
        if bool(getattr(args, "variable_overflow_continuous_vector_mode", True)):
            vp_cont = _build_continuous_vector_pull_plan(raw_board, planning_board, raw_src, plan_src, print_result=print_result)
            if vp_cont is not None:
                return vp_cont
            # Keep continuous mode explicit; do not silently fall back to old hard-coded cases.
            return None

        overflow_info = _variable_side_overflows_from_board(raw_board)
        sides = overflow_info.get("sides", {})
        if bool(getattr(args, "variable_overflow_pose_neck_pull_mode", False)):
            vp_neck = _build_pose_neck_pull_in_plan(raw_board, planning_board, overflow_info, raw_src, plan_src, print_result=print_result)
            if vp_neck is not None:
                return vp_neck
            return None

        mode, overflow_info = _choose_variable_overflow_mode(raw_board, planning_board)
        sides = overflow_info.get("sides", {})
        if mode is None:
            if print_result:
                depths = {k: round(float(v.get("overflow", 0.0)), 1) for k, v in sides.items()}
                print(f"[VAR-OVERFLOW] no correction needed. side_overflow_mm={depths}")
            return None
        contact = _choose_variable_overflow_contact_point(planning_board, mode)
        if contact is None:
            if print_result:
                print(f"[VAR-OVERFLOW] no safe contact point for mode={mode}")
            return None
        start_bx, start_by, npts, anchor_dist = contact
        u = np.asarray(mode["pull_unit"], dtype=np.float32).reshape(2)
        un = float(np.linalg.norm(u))
        if un < 1e-6:
            if print_result:
                print("[VAR-OVERFLOW] invalid zero pull vector")
            return None
        u = u / un
        gain = max(0.0, float(getattr(args, "variable_overflow_gain", 0.80)))
        min_pull = max(0.0, float(getattr(args, "variable_overflow_min_pull_mm", 30.0)))
        max_pull = max(min_pull, float(getattr(args, "variable_overflow_max_pull_mm", 95.0)))
        raw_dist = gain * float(mode["overflow_norm"])
        dist = float(np.clip(raw_dist, min_pull, max_pull))
        target_margin = float(args.boundary_recovery_target_margin)
        end_bx, end_by = _clamp_board_xy(start_bx + float(u[0]) * dist, start_by + float(u[1]) * dist, target_margin)

        hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
        contact_z = float(args.boundary_recovery_drag_z) if args.boundary_recovery_drag_z is not None else float(args.press_z)
        if args.boundary_recovery_drag_clear_z is not None:
            clear_z = float(args.boundary_recovery_drag_clear_z)
        elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
            clear_z = float(args.press_extra_clear_z)
        elif args.press_clear_z is not None:
            clear_z = float(args.press_clear_z)
        else:
            clear_z = float(hover_z)

        arm_key = str(mode["arm_key"])
        hover = resolve_board_target_for_arm(arm_key, start_bx, start_by, hover_z, "VAR-OVERFLOW-HOVER")
        down_raw = resolve_board_target_for_arm(arm_key, start_bx, start_by, contact_z, "VAR-OVERFLOW-DOWN")
        drag_raw = resolve_board_target_for_arm(arm_key, end_bx, end_by, contact_z, "VAR-OVERFLOW-DRAG")
        down = _apply_low_z_roarm_offset(down_raw, "boundary_recovery", "VAR-OVERFLOW-DOWN")
        drag = _apply_low_z_roarm_offset(drag_raw, "boundary_recovery", "VAR-OVERFLOW-DRAG")
        clear = None
        if drag is not None:
            clear = dict(drag)
            clear["rz"] = float(clear_z)
        if hover is None or down is None or drag is None or clear is None:
            if print_result:
                print(f"[VAR-OVERFLOW] blocked: resolved target unsafe for {arm_key.upper()}")
            return None

        depths = {k: float(v.get("overflow", 0.0)) for k, v in sides.items()}
        ratios = {k: float(v.get("outside_ratio", 0.0)) for k, v in sides.items()}
        mode_text = str(mode["mode"])
        side_text = str(mode["main_side"])
        angle_deg = float(np.degrees(np.arctan2(float(u[1]), float(u[0]))))
        policy_text = str(mode.get("policy", ""))
        summary = (f"variable overflow {mode_text} side={side_text} arm={arm_key.upper()} policy={policy_text} "
                   f"pull_unit=({float(u[0]):+.3f},{float(u[1]):+.3f}) angle={angle_deg:+.1f}deg "
                   f"overflow_norm={float(mode['overflow_norm']):.1f} raw_dist={raw_dist:.1f} dist={dist:.1f}mm "
                   f"start=({start_bx:.1f},{start_by:.1f}) -> end=({end_bx:.1f},{end_by:.1f}) "
                   f"anchor=({float(np.asarray(mode['anchor'])[0]):.1f},{float(np.asarray(mode['anchor'])[1]):.1f}) anchor_dist={anchor_dist:.1f}mm")
        vp = {
            "mode": "drag",
            "recovery_kind": "variable_overflow",
            "overflow_mode": mode_text,
            "side": side_text,
            "arm_key": arm_key,
            "side_overflow_mm": depths,
            "side_outside_ratio": ratios,
            "overflow_percentiles": overflow_info.get("percentiles", {}),
            "overflow_limits": overflow_info.get("limits", {}),
            "major": float(mode.get("major", 0.0)),
            "minor": float(mode.get("minor", 0.0)),
            "minor_share": float(mode.get("minor_share", 0.0)),
            "reachable_points": int(npts),
            "start_board_xy": [float(start_bx), float(start_by)],
            "end_board_xy": [float(end_bx), float(end_by)],
            "pull_vector": [float(u[0]), float(u[1])],
            "pull_distance": float(dist),
            "policy": str(mode.get("policy", "")),
            "contact_target_type": str(mode.get("contact_target_type", "")),
            "contact_target": mode.get("contact_target", None),
            "raw_mask_source": raw_src,
            "planning_mask_source": plan_src,
            "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
            "hover": hover,
            "down": down,
            "drag": drag,
            "clear": clear,
            "down_raw": down_raw,
            "drag_raw": drag_raw,
            "summary": summary,
        }
        if print_result:
            print("\n========== VARIABLE OVERFLOW RECOVERY PLAN (/) ==========")
            print(summary)
            print(f"side_overflow_mm={{{', '.join(f'{k}:{v:.1f}' for k, v in depths.items())}}}")
            print(f"outside_ratio={{{', '.join(f'{k}:{v:.3f}' for k, v in ratios.items())}}}")
            if mode_text == "diagonal":
                print(f"diagonal condition: major={float(mode.get('major',0.0)):.1f}, minor={float(mode.get('minor',0.0)):.1f}, minor_share={float(mode.get('minor_share',0.0)):.3f}")
            print("Key '/' now executes one planned contact-drag per round, then can rejudge and repeat until the overflow target is met. Key 4 auto-center is untouched.")
            print("=======================================================\n")
        return vp

    def _variable_board_center_axis_for_pose_stop() -> Optional[Tuple[np.ndarray, np.ndarray]]:
        try:
            p0 = _marker_xy_for_variable_overflow(0)
            p1 = _marker_xy_for_variable_overflow(1)
            p2 = _marker_xy_for_variable_overflow(2)
            p3 = _marker_xy_for_variable_overflow(3)
            top_mid = 0.5 * (p0 + p2)
            bottom_mid = 0.5 * (p1 + p3)
            if float(np.linalg.norm(bottom_mid - top_mid)) < 1e-6:
                return None
            return top_mid.astype(np.float32), bottom_mid.astype(np.float32)
        except Exception:
            return None

    def _point_line_distance_mm(pt: np.ndarray, a: np.ndarray, b: np.ndarray) -> float:
        v = b - a
        n = float(np.linalg.norm(v))
        if n < 1e-6:
            return float("inf")
        p = pt - a
        return float(abs(float(v[0]) * float(p[1]) - float(v[1]) * float(p[0])) / n)

    def _variable_pose_axis_center_error_mm() -> Tuple[Optional[float], str, Dict[str, Any]]:
        """Average distance from T-shirt neck/waist axis endpoints to the board center axis.

        The pose model defines the shirt axis as neck_center -> waist_mid.  The board
        center axis is midpoint(ID0,ID2) -> midpoint(ID1,ID3).  This returns the
        mean perpendicular distance of neck_center and waist_mid to that board axis.
        """
        try:
            plan = latest_pose_rotation_plan if isinstance(latest_pose_rotation_plan, dict) else None
            if plan is None:
                return None, "pose axis unavailable: no latest pose plan", {}
            neck = plan.get("neck_board_xy")
            waist = plan.get("waist_board_xy")
            if neck is None or waist is None:
                return None, "pose axis unavailable: missing neck/waist board points", {}
            neck_b = np.asarray(neck, dtype=np.float32).reshape(2)
            waist_b = np.asarray(waist, dtype=np.float32).reshape(2)
            if not np.all(np.isfinite(neck_b)) or not np.all(np.isfinite(waist_b)):
                return None, "pose axis unavailable: non-finite neck/waist", {}
            axis_len = float(np.linalg.norm(waist_b - neck_b))
            min_len = float(getattr(args, "pose_rotate_min_axis_len_mm", 80.0))
            if axis_len < min_len:
                return None, f"pose axis unavailable: len={axis_len:.1f}mm < {min_len:.1f}mm", {}
            line = _variable_board_center_axis_for_pose_stop()
            if line is None:
                return None, "pose axis unavailable: board center axis failed", {}
            a, b = line
            d_neck = _point_line_distance_mm(neck_b, a, b)
            d_waist = _point_line_distance_mm(waist_b, a, b)
            avg = 0.5 * (d_neck + d_waist)
            axis = waist_b - neck_b
            pose_angle = float(np.degrees(np.arctan2(float(axis[1]), float(axis[0]))))
            board_axis = b - a
            board_angle = float(np.degrees(np.arctan2(float(board_axis[1]), float(board_axis[0]))))
            detail = {
                "avg_mm": float(avg),
                "neck_dist_mm": float(d_neck),
                "waist_dist_mm": float(d_waist),
                "axis_len_mm": float(axis_len),
                "pose_axis_deg": float(pose_angle),
                "board_axis_deg": float(board_angle),
                "neck_board_xy": [float(neck_b[0]), float(neck_b[1])],
                "waist_board_xy": [float(waist_b[0]), float(waist_b[1])],
            }
            msg = (f"pose_axis_center_error avg={avg:.1f}mm "
                   f"neck={d_neck:.1f} waist={d_waist:.1f} "
                   f"pose_angle={pose_angle:+.1f} board_axis={board_angle:+.1f}")
            return float(avg), msg, detail
        except Exception as e:
            return None, f"pose axis error failed: {repr(e)}", {}

    def _a133_execute_variable_overflow_plan_exact(vp: Dict[str, Any], label: str = "A133 exact center plan") -> bool:
        """Execute one frozen variable-overflow plan without rebuilding it."""
        nonlocal coarse_x_since_last_press
        if not isinstance(vp, dict):
            print("[A136-CENTER-BLOCKED] frozen plan missing")
            return False
        if not send_enabled:
            print("[DRY-RUN] A136 exact center commands not sent.")
            return False
        arm_key = str(vp.get("arm_key", "")); arm_obj = arms.get(arm_key)
        if arm_obj is None:
            print(f"[A136-CENTER-BLOCKED] {arm_key.upper()} not connected")
            return False
        try:
            drag_gripper = float(args.boundary_recovery_drag_gripper)
            drag_speed = float(args.boundary_recovery_drag_speed)
            print("\n========== A136 EXACT LATE CENTER DRAG ==========")
            print(label); print(vp.get("summary", "frozen center plan"))
            print("No snapshot, inference, arm selection, contact, or endpoint is rebuilt.")
            print("================================================\n")
            _a140_note_action_command(f"{label} torque-on")
            arm_obj.torque_on()
            arm_obj.set_gripper(drag_gripper, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(0.15)
            hover, down, drag, clear = vp["hover"], vp["down"], vp["drag"], vp["clear"]
            arm_obj.move_goal(args.move_command, hover["rx"], hover["ry"], hover["rz"], t=args.t, spd=spd_default); time.sleep(0.25)
            arm_obj.move_goal(args.move_command, down["rx"], down["ry"], down["rz"], t=args.t, spd=drag_speed); time.sleep(max(0.0, float(args.boundary_recovery_drag_down_wait)))
            arm_obj.move_goal(args.move_command, drag["rx"], drag["ry"], drag["rz"], t=args.t, spd=drag_speed); time.sleep(max(0.0, float(args.boundary_recovery_drag_sweep_wait)))
            arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=args.t, spd=spd_default); time.sleep(0.25)
            _a140_note_vertical_clear(str(label))
            if bool(args.boundary_recovery_drag_open_after_clear):
                arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.15); time.sleep(float(args.boundary_recovery_release_wait))
                _a140_note_release(f"{label} open after clear")
            coarse_x_since_last_press = 0
            _reset_coarse_auto_press_cycle("cloth changed: A136 exact late center")
            if args.imaging_standby and not args.no_standby:
                move_arms_to_standby(reason="after A136 exact late center")
            return True
        except Exception as e:
            print(f"[A136-CENTER-ERROR] {repr(e)}")
            raise RuntimeError(f"A136 exact center physical command failed: {repr(e)}") from e

    def variable_overflow_recovery_once(force_execute_plan: bool = False, execution_mode: str = "press_drag"):
        nonlocal coarse_x_since_last_press
        nonlocal snapshot_reference_gray, snapshot_foreground_state, target_stale_frames, target_removed_frames, target_changed_frames, target_stale_armed_at
        nonlocal latest_variable_overflow_plan, latest_variable_overflow_status, variable_overflow_rejudge_capture_allowed, variable_overflow_rejudge_waiting_for_still
        if not bool(getattr(args, "variable_overflow_recovery_mode", True)):
            print("[VAR-OVERFLOW] variable overflow recovery mode is OFF")
            return

        def _measure_current_overflow_for_loop() -> Tuple[Optional[float], Dict[str, float], str]:
            raw_board, _cand, raw_src = _candidate_board_points_for_variable_overflow(latest_coarse_plan, use_raw=True)
            if raw_board is None or len(raw_board) < 20:
                return None, {}, raw_src
            info = _variable_side_overflows_from_board(raw_board)
            sides = info.get("sides", {})
            depths = {k: float(v.get("overflow", 0.0)) for k, v in sides.items()}
            max_ov = max(depths.values()) if depths else 0.0
            return float(max_ov), depths, raw_src

        execution_mode_norm = str(execution_mode or "press_drag").strip().lower()

        def _execute_circumcenter_grip_lift_pull(vp: Dict[str, Any]) -> bool:
            """Execute ordinary CENTER_CIRCUMCENTER without any low-Z horizontal drag.

            Required gripper order:
              OPEN once before approach -> keep OPEN through high-XY approach and vertical descent
              -> CLOSE exactly once at the reached grip XYZ -> carry while closed
              -> OPEN exactly once at the endpoint -> same-XY vertical clear.

            T:104 `t` is deliberately set to the same open/closed angle as T:106.
            On this RoArm setup, using args.t during approach can physically close the
            gripper even after an explicit T:106 OPEN command.
            """
            nonlocal coarse_x_since_last_press
            if not send_enabled:
                print("[DRY-RUN] Circumcenter Grip-Lift-Pull commands not sent.")
                return False
            if str(vp.get("recovery_kind", "")) != "circumcenter_vacancy_pull":
                print(
                    "[CIRC-GRIP-BLOCKED] Grip-Lift-Pull is restricted to ordinary "
                    f"circumcenter_vacancy_pull; got recovery_kind={vp.get('recovery_kind')}"
                )
                return False

            arm_key = str(vp.get("arm_key", ""))
            arm_obj = arms.get(arm_key)
            if arm_obj is None:
                print(f"[CIRC-GRIP-BLOCKED] {arm_key.upper()} is not connected.")
                return False

            grip_z_value = get_arm_grip_z(arm_key)
            if grip_z_value is None:
                print(f"[CIRC-GRIP-BLOCKED] {arm_key.upper()} grip_z is not configured.")
                return False
            grip_z_value = float(grip_z_value)
            lift_z_value = float(get_arm_lift_z(arm_key))

            hover_plan = vp.get("hover") if isinstance(vp.get("hover"), dict) else None
            down_plan = vp.get("down") if isinstance(vp.get("down"), dict) else None
            drag_plan = vp.get("drag") if isinstance(vp.get("drag"), dict) else None
            if hover_plan is None or down_plan is None or drag_plan is None:
                print("[CIRC-GRIP-BLOCKED] Circumcenter plan is missing hover/down/drag coordinates.")
                return False

            start_rx = float(down_plan["rx"]); start_ry = float(down_plan["ry"])
            end_rx = float(drag_plan["rx"]); end_ry = float(drag_plan["ry"])
            if getattr(args, "grip_approach_z", None) is not None:
                approach_z = float(args.grip_approach_z)
                approach_source = "grip_approach_z"
            else:
                approach_z = float(hover_plan["rz"])
                approach_source = "existing Circumcenter safe hover"

            if not (approach_z > grip_z_value and lift_z_value > grip_z_value):
                print(
                    f"[CIRC-GRIP-BLOCKED] unsafe Z order for {arm_key.upper()}: "
                    f"approach={approach_z:.1f}, lift={lift_z_value:.1f}, grip={grip_z_value:.1f}; "
                    "both approach and lift must be higher than grip Z."
                )
                return False

            targets = {
                "approach": (start_rx, start_ry, approach_z),
                "grip": (start_rx, start_ry, grip_z_value),
                "lift": (start_rx, start_ry, lift_z_value),
                "carry": (end_rx, end_ry, lift_z_value),
                "clear": (end_rx, end_ry, approach_z),
            }
            if not bool(getattr(args, "allow_unsafe_roarm", False)):
                unsafe = [
                    (name, xyz) for name, xyz in targets.items()
                    if not is_xyz_safe(float(xyz[0]), float(xyz[1]), float(xyz[2]), args)
                ]
                if unsafe:
                    print(f"[CIRC-GRIP-BLOCKED] resolved Grip-Lift-Pull target outside safety range: {unsafe}")
                    return False

            open_angle = float(args.grip_open)
            close_angle = float(args.grip_close)
            move_speed = float(spd_default)
            carry_speed = float(args.boundary_recovery_drag_speed)
            approach_wait = max(
                0.0,
                float(getattr(args, "grip_down_wait", 0.60)),
                float(getattr(args, "coarse_hover_wait", 0.80)),
                float(getattr(args, "dual_hover_wait", 1.00)),
            )
            descend_wait = max(
                0.0,
                float(getattr(args, "grip_down_wait", 0.60)),
                float(getattr(args, "coarse_parallel_descend_wait", 0.20)),
            )
            close_wait = max(
                0.0,
                float(getattr(args, "coarse_parallel_close_wait", 0.25)),
                float(getattr(args, "boundary_recovery_close_wait", 0.45)),
            )
            close_settle = max(0.0, float(getattr(args, "coarse_parallel_close_settle", 0.18)))
            lift_wait = max(
                0.0,
                float(getattr(args, "boundary_recovery_lift_wait", 0.25)),
                float(getattr(args, "coarse_parallel_lift_wait", 0.12)),
            )
            carry_wait = max(
                0.0,
                float(getattr(args, "boundary_recovery_drag_sweep_wait", 0.35)),
                float(getattr(args, "coarse_stretch_wait", 0.80)),
                float(getattr(args, "dual_stretch_wait", 0.80)),
            )
            release_wait = max(0.0, float(getattr(args, "center_circumcenter_release_settle_s", 0.80)))
            clear_wait = max(0.25, float(getattr(args, "grip_down_wait", 0.60)))
            pre_open_wait = max(
                0.0,
                float(getattr(args, "coarse_parallel_pre_open_wait", 0.05)),
                float(getattr(args, "startup_open_wait", 0.80)),
            )

            print("\n========== CIRCUMCENTER GRIP-LIFT-PULL ==========")
            print(vp.get("summary", "circumcenter-vacancy plan"))
            print(
                f"arm={arm_key.upper()} approach_z={approach_z:.1f}({approach_source}) "
                f"grip_z={grip_z_value:.1f} lift_z={lift_z_value:.1f} "
                f"open={open_angle:.3f} close_once={close_angle:.3f}"
            )
            print(
                "Sequence: OPEN -> high approach at final grip XY -> same-XY vertical down "
                "-> CLOSE once -> same-XY vertical lift -> original Circumcenter XY path at lift Z "
                "-> OPEN at end -> same-XY vertical clear -> standby"
            )
            print("No OPEN at the reached grip point, no repeated CLOSE, no grip_hold, no low-Z horizontal drag.")
            print("=================================================\n")

            _a140_note_action_command("ordinary CENTER_CIRCUMCENTER Grip-Lift-Pull torque-on")
            arm_obj.torque_on()

            # 1) Explicitly open once before any approach. There is intentionally no
            # second OPEN after reaching the final grip XYZ.
            print(f"[CIRC-GRIP-OPEN] {arm_key.upper()} T:106 open angle={open_angle:.3f}")
            arm_obj.set_gripper(open_angle, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(pre_open_wait)

            # 2) Move XY at a safe high Z. T:104 t also stays OPEN so the motion
            # command itself cannot close the gripper during approach.
            ax, ay, az = targets["approach"]
            print(f"[CIRC-MOVE-OPEN-TO-GRIP-XY-HIGH] {arm_key.upper()} move: ({ax:.1f},{ay:.1f},{az:.1f}) t=open")
            arm_obj.move_goal(args.move_command, ax, ay, az, t=open_angle, spd=move_speed)
            time.sleep(approach_wait)

            gx, gy, gz = targets["grip"]
            print(f"[CIRC-VERTICAL-DOWN-OPEN-TO-GRIP-Z] {arm_key.upper()} move: ({gx:.1f},{gy:.1f},{gz:.1f}) t=open")
            arm_obj.move_goal(args.move_command, gx, gy, gz, t=open_angle, spd=move_speed)
            time.sleep(descend_wait)

            # 4) CLOSE exactly once at the completed grip XYZ. Do not re-open here,
            # do not repeat close, and do not send a separate grip_hold angle.
            print(f"[CIRC-CLOSE-AT-GRIP] {arm_key.upper()} T:106 close ONCE angle={close_angle:.3f}")
            arm_obj.set_gripper(close_angle, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(close_wait + close_settle)

            lx, ly, lz = targets["lift"]
            print(f"[CIRC-VERTICAL-LIFT] {arm_key.upper()} move: ({lx:.1f},{ly:.1f},{lz:.1f}) t=close")
            arm_obj.move_goal(args.move_command, lx, ly, lz, t=close_angle, spd=move_speed)
            time.sleep(lift_wait)

            cx, cy, cz = targets["carry"]
            print(f"[CIRC-MOVE-ALONG-PLAN-LIFTED] {arm_key.upper()} move: ({cx:.1f},{cy:.1f},{cz:.1f}) t=close")
            arm_obj.move_goal(args.move_command, cx, cy, cz, t=close_angle, spd=carry_speed)
            time.sleep(carry_wait)

            print(f"[CIRC-OPEN-AT-END] {arm_key.upper()} T:106 open angle={open_angle:.3f}")
            arm_obj.set_gripper(open_angle, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(release_wait)
            print(f"[CIRC-RELEASE-SETTLE] waited {release_wait:.2f}s with XYZ stationary")
            _a140_note_release("ordinary CENTER_CIRCUMCENTER Grip-Lift-Pull open at end")

            # 8) Same endpoint X/Y, vertical clear with T:104 t kept OPEN.
            qx, qy, qz = targets["clear"]
            print(f"[CIRC-VERTICAL-CLEAR] {arm_key.upper()} move: ({qx:.1f},{qy:.1f},{qz:.1f}) t=open")
            arm_obj.move_goal(args.move_command, qx, qy, qz, t=open_angle, spd=move_speed)
            time.sleep(clear_wait)
            _a140_note_vertical_clear("ordinary CENTER_CIRCUMCENTER Grip-Lift-Pull")

            coarse_x_since_last_press = 0
            _reset_coarse_auto_press_cycle("cloth changed: ordinary Circumcenter Grip-Lift-Pull executed")
            if args.imaging_standby and not args.no_standby:
                move_arms_to_standby(reason="after ordinary CENTER_CIRCUMCENTER Grip-Lift-Pull")
            return True

        def _wait_circumcenter_nudge_hover_arrival(arm_key: str, arm_obj, hover: Dict[str, Any]) -> bool:
            """Wait until one nudge arm is physically at high-Z hover XY before contact descent."""
            if not bool(getattr(args, "circumcenter_nudge_xy_arrival_barrier", True)) or not send_enabled:
                return True
            timeout_s = max(0.5, float(getattr(args, "circumcenter_nudge_xy_arrival_timeout_s", 6.0)))
            xy_tol = max(1.0, float(getattr(args, "circumcenter_nudge_xy_tolerance_mm", 22.0)))
            z_tol = max(1.0, float(getattr(args, "circumcenter_nudge_hover_z_tolerance_mm", 25.0)))
            need = max(1, int(getattr(args, "circumcenter_nudge_arrival_consecutive_samples", 2)))
            poll = max(0.0, float(getattr(args, "circumcenter_nudge_arrival_poll_interval_s", 0.12)))
            fb_timeout = max(0.10, float(getattr(args, "circumcenter_nudge_arrival_feedback_timeout_s", 0.80)))
            tx, ty, tz = float(hover["rx"]), float(hover["ry"]), float(hover["rz"])
            started = time.monotonic(); stable = 0; sample = 0
            print(
                f"[CIRC-NUDGE-XY-BARRIER] {arm_key.upper()} target=({tx:.1f},{ty:.1f},{tz:.1f}) "
                f"timeout={timeout_s:.1f}s xy_tol={xy_tol:.1f} z_tol={z_tol:.1f} stable={need}"
            )
            while time.monotonic() - started <= timeout_s:
                sample += 1
                fb = None
                try:
                    fb = arm_obj.feedback(timeout=fb_timeout)
                except Exception as exc:
                    print(f"[CIRC-NUDGE-XY-FEEDBACK-ERROR] {arm_key.upper()} {repr(exc)}")
                xy_err = float('inf'); z_err = float('inf'); ok = False
                if isinstance(fb, dict):
                    try:
                        xy_err = float(math.hypot(float(fb['x']) - tx, float(fb['y']) - ty))
                        z_err = abs(float(fb['z']) - tz)
                        ok = bool(xy_err <= xy_tol and z_err <= z_tol)
                    except Exception:
                        pass
                stable = stable + 1 if ok else 0
                print(
                    f"[CIRC-NUDGE-XY-SAMPLE] {arm_key.upper()} n={sample} "
                    f"xy={xy_err:.1f} z={z_err:.1f} ok={ok} stable={stable}/{need}"
                )
                if stable >= need:
                    print(f"[CIRC-NUDGE-XY-PASS] {arm_key.upper()} elapsed={time.monotonic()-started:.2f}s; contact-Z descent now allowed")
                    return True
                time.sleep(poll)
            print(f"[CIRC-NUDGE-XY-TIMEOUT] {arm_key.upper()} high-Z hover arrival not confirmed; contact-Z descent suppressed")
            return False

        def _execute_variable_plan(vp: Dict[str, Any]) -> bool:
            nonlocal coarse_x_since_last_press
            if execution_mode_norm == "grip_lift_pull":
                return _execute_circumcenter_grip_lift_pull(vp)
            nudge_xy_barrier = bool(execution_mode_norm == "press_drag_xy_barrier")
            if execution_mode_norm not in {"press_drag", "press_drag_xy_barrier"}:
                print(f"[VAR-OVERFLOW-BLOCKED] unknown execution_mode={execution_mode_norm!r}")
                return False
            if not send_enabled:
                print("[DRY-RUN] Variable overflow recovery commands not sent.")
                return False
            arm_key = vp["arm_key"]
            arm_obj = arms.get(arm_key)
            if arm_obj is None:
                print(f"[VAR-OVERFLOW-BLOCKED] {arm_key.upper()} is not connected.")
                return False
            drag_gripper = float(args.boundary_recovery_drag_gripper)
            drag_speed = float(args.boundary_recovery_drag_speed)
            print("\n========== VARIABLE OVERFLOW CONTACT-DRAG (/) ==========")
            print(vp["summary"])
            print(f"drag_gripper={drag_gripper:.3f}, contact_z={vp.get('z_info', {}).get('contact_z')}, clear_z={vp.get('z_info', {}).get('clear_z')}, speed={drag_speed:.2f}")
            print("This uses the displayed/rejudged snapshot plan. Contact point is drawn in cyan on OpenCV.")
            print("Keep emergency power cutoff ready.")
            print("=======================================================\n")

            _a140_note_action_command("variable overflow recovery torque-on")
            arm_obj.torque_on()
            print(f"[VAR-OVERFLOW-PADDED-CLOSE] {arm_key.upper()} contact gripper angle={drag_gripper:.3f}")
            arm_obj.set_gripper(drag_gripper, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(0.15)

            hover = vp["hover"]
            print(f"[VAR-OVERFLOW-HOVER] {arm_key.upper()} move: ({hover['rx']:.1f},{hover['ry']:.1f},{hover['rz']:.1f})")
            arm_obj.move_goal(args.move_command, hover["rx"], hover["ry"], hover["rz"], t=args.t, spd=spd_default)
            if nudge_xy_barrier:
                if not _wait_circumcenter_nudge_hover_arrival(arm_key, arm_obj, hover):
                    if args.imaging_standby and not args.no_standby:
                        move_arms_to_standby(reason="circumcenter nudge hover-arrival failure")
                    return False
            else:
                time.sleep(0.25)

            down = vp["down"]
            print(f"[VAR-OVERFLOW-CONTACT-DOWN] {arm_key.upper()} move: ({down['rx']:.1f},{down['ry']:.1f},{down['rz']:.1f})")
            arm_obj.move_goal(args.move_command, down["rx"], down["ry"], down["rz"], t=args.t, spd=drag_speed)
            time.sleep(max(0.0, float(args.boundary_recovery_drag_down_wait)))

            drag = vp["drag"]
            print(f"[VAR-OVERFLOW-DRAG] {arm_key.upper()} drag low: ({drag['rx']:.1f},{drag['ry']:.1f},{drag['rz']:.1f})")
            arm_obj.move_goal(args.move_command, drag["rx"], drag["ry"], drag["rz"], t=args.t, spd=drag_speed)
            time.sleep(max(0.0, float(args.boundary_recovery_drag_sweep_wait)))

            clear = vp["clear"]
            print(f"[VAR-OVERFLOW-VERTICAL-CLEAR] {arm_key.upper()} clear at same XY: ({clear['rx']:.1f},{clear['ry']:.1f},{clear['rz']:.1f})")
            arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=args.t, spd=spd_default)
            time.sleep(0.25)
            _a140_note_vertical_clear("variable overflow recovery")

            if bool(args.boundary_recovery_drag_open_after_clear):
                print(f"[VAR-OVERFLOW-OPEN-AFTER-CLEAR] {arm_key.upper()} open angle={float(args.grip_open):.3f}")
                arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
                time.sleep(float(args.boundary_recovery_release_wait))
                _a140_note_release("variable overflow recovery open after clear")

            coarse_x_since_last_press = 0
            _reset_coarse_auto_press_cycle("cloth changed: variable overflow recovery executed")
            if args.imaging_standby and not args.no_standby:
                move_arms_to_standby(reason="after variable overflow recovery")
            return True

        def _post_motion_rejudge(round_no: int) -> Optional[Dict[str, Any]]:
            nonlocal variable_overflow_rejudge_capture_allowed, variable_overflow_rejudge_waiting_for_still
            if not snapshot_mode:
                return None
            settle_s = max(0.0, float(getattr(args, "variable_overflow_auto_rejudge_settle_s", 0.8)))
            if settle_s > 0.0:
                print(f"[VAR-OVERFLOW-REJUDGE] standby settle {settle_s:.2f}s before allowing a fresh stillness-gated snapshot")
                time.sleep(settle_s)

            if bool(getattr(args, "variable_overflow_rejudge_wait_stillness", True)):
                old_serial = inference_serial
                timeout = float(getattr(args, "variable_overflow_auto_rejudge_timeout", getattr(args, "variable_overflow_fresh_timeout", 8.0)))
                try:
                    variable_overflow_rejudge_waiting_for_still = True
                    reset_snapshot(f"after variable overflow round {round_no}: waiting for fresh still frame")
                    print(f"[VAR-OVERFLOW-REJUDGE] waiting for stillness-gated snapshot after round {round_no}")
                    start = time.time()
                    while time.time() - start < timeout:
                        time.sleep(0.05)
                        if inference_serial > old_serial and not yolo_busy:
                            if latest_coarse_plan is not None:
                                a2 = latest_coarse_plan["targets"]["arm2"]["board_xy"]
                                a1 = latest_coarse_plan["targets"]["arm1"]["board_xy"]
                                m = latest_coarse_plan.get("metrics", {})
                                mode = m.get("axis_mode", latest_coarse_plan.get("spread_axis", {}).get("axis_mode", "?"))
                                print(f"[VAR-OVERFLOW-REJUDGE] fresh still snapshot ready: mode={mode} ARM2=({a2[0]:.1f},{a2[1]:.1f}), ARM1=({a1[0]:.1f},{a1[1]:.1f})")
                                return latest_coarse_plan
                            print(f"[VAR-OVERFLOW-REJUDGE-BLOCKED] fresh still inference finished but coarse plan is not ready: {latest_coarse_status}")
                            return None
                    print(f"[VAR-OVERFLOW-REJUDGE-TIMEOUT] no fresh still snapshot within {timeout:.1f}s")
                    return None
                finally:
                    variable_overflow_rejudge_waiting_for_still = False

            try:
                variable_overflow_rejudge_capture_allowed = True
                return request_fresh_coarse_plan_and_wait(
                    reason=f"after variable overflow round {round_no}",
                    timeout=float(getattr(args, "variable_overflow_auto_rejudge_timeout", getattr(args, "variable_overflow_fresh_timeout", 8.0))),
                )
            finally:
                variable_overflow_rejudge_capture_allowed = False

        auto_loop = bool(getattr(args, "variable_overflow_auto_loop", True))
        max_rounds = max(1, int(getattr(args, "variable_overflow_auto_max_rounds", 4))) if auto_loop else 1
        done_mm = max(0.0, float(getattr(args, "variable_overflow_auto_done_mm", 10.0)))
        pose_done_mm = max(0.0, float(getattr(args, "variable_overflow_pose_axis_done_mm", 50.0)))
        done_metric = str(getattr(args, "variable_overflow_done_metric", "pose_axis_distance"))

        # policy:
        #   - First / plan uses the already displayed snapshot/mask. No fresh snapshot before motion.
        #   - After each completed motion, arms return to standby, then a normal stillness-gated
        #     snapshot is taken before the next plan is built.
        #   - Auto-loop stopping can use the pose neck/waist axis distance from board center axis.
        print("[VAR-OVERFLOW] first round uses existing displayed snapshot/mask. No pre-motion snapshot/rejudgment.")
        latest_variable_overflow_status = "running"

        executed = 0
        while executed < max_rounds:
            max_ov, depths, src = _measure_current_overflow_for_loop()
            pose_err, pose_msg, _pose_detail = _variable_pose_axis_center_error_mm()

            if max_ov is not None:
                print(f"[VAR-OVERFLOW-LOOP] round={executed+1}/{max_rounds} current_max_overflow={max_ov:.1f}mm depths={{{', '.join(f'{k}:{v:.1f}' for k,v in depths.items())}}}")
            else:
                print(f"[VAR-OVERFLOW-LOOP] could not measure current overflow: {src}")

            if bool(force_execute_plan):
                print("[VAR-OVERFLOW-FORCE] X planner priority-1 centering: bypass old / done checks and force one circumcenter-vacancy plan from current mask")
            elif done_metric == "vacancy_center_balance":
                vac_ok, center_err, gap_balance, vac_msg, _vac_detail = _inside_vacancy_center_balance_stop_metrics(latest_coarse_plan)
                center_done = float(getattr(args, "variable_overflow_vacancy_center_done_mm", 50.0))
                gap_done = float(getattr(args, "variable_overflow_vacancy_gap_balance_done_mm", 80.0))
                print(f"[VAR-VACANCY-BALANCE-STOP] {vac_msg} targets: center_error<={center_done:.1f}mm, gap_balance<={gap_done:.1f}mm")
                if bool(vac_ok):
                    latest_variable_overflow_status = f"done center_error={center_err:.1f}mm, gap_balance={gap_balance:.1f}mm"
                    print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                    return
            elif done_metric == "inside_vacancy_center":
                inside_ratio, pose_center_err, vac_msg, _vac_detail = _inside_vacancy_stop_metrics(latest_coarse_plan)
                ratio_done = float(getattr(args, "variable_overflow_inside_area_done_ratio", 0.85))
                center_done = float(getattr(args, "variable_overflow_pose_center_done_mm", 50.0))
                print(f"[VAR-VACANCY-STOP] {vac_msg} targets: inside_ratio>={ratio_done:.2f}, pose_center_error<={center_done:.1f}mm")
                if inside_ratio is not None and pose_center_err is not None and inside_ratio >= ratio_done and pose_center_err <= center_done:
                    latest_variable_overflow_status = f"done inside_ratio={inside_ratio:.3f}, pose_center_error={pose_center_err:.1f}mm"
                    print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                    return
            elif done_metric == "pose_axis_distance":
                if pose_err is not None:
                    print(f"[VAR-OVERFLOW-POSE-STOP] {pose_msg} target<={pose_done_mm:.1f}mm")
                    if pose_err <= pose_done_mm:
                        latest_variable_overflow_status = f"done pose_axis_center_error={pose_err:.1f}mm <= {pose_done_mm:.1f}mm"
                        print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                        return
                else:
                    print(f"[VAR-OVERFLOW-POSE-STOP] unavailable: {pose_msg}")
                    if bool(getattr(args, "variable_overflow_pose_axis_require_pose", False)):
                        latest_variable_overflow_status = f"stop: pose stop metric unavailable: {pose_msg}"
                        print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                        return
                    if max_ov is not None and max_ov <= done_mm:
                        latest_variable_overflow_status = f"done fallback max_overflow={max_ov:.1f}mm <= {done_mm:.1f}mm"
                        print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                        return
            else:
                if max_ov is not None:
                    print(f"[VAR-OVERFLOW-MAX-STOP] target<={done_mm:.1f}mm")
                    if max_ov <= done_mm:
                        latest_variable_overflow_status = f"done max_overflow={max_ov:.1f}mm <= {done_mm:.1f}mm"
                        print(f"[VAR-OVERFLOW-DONE] {latest_variable_overflow_status}")
                        return

            old_min = getattr(args, "variable_overflow_min_overflow_mm", None)
            try:
                if old_min is not None:
                    args.variable_overflow_min_overflow_mm = min(float(old_min), max(done_mm, 1.0))
                vp = build_variable_overflow_recovery_plan(latest_coarse_plan, print_result=True)
            finally:
                if old_min is not None:
                    args.variable_overflow_min_overflow_mm = old_min

            if vp is None:
                latest_variable_overflow_plan = None
                latest_variable_overflow_status = "no executable plan"
                print("[VAR-OVERFLOW-LOOP] stop: no executable / plan from current mask")
                return

            latest_variable_overflow_plan = vp
            latest_variable_overflow_status = vp.get("summary", "planned")
            preview_wait = max(0.0, float(getattr(args, "variable_overflow_preview_wait", 0.0)))
            if preview_wait > 0.0:
                print(f"[VAR-OVERFLOW-PREVIEW] showing cyan contact point/arrow for {preview_wait:.2f}s before executing")
                time.sleep(preview_wait)

            if not _execute_variable_plan(vp):
                return
            executed += 1

            if not auto_loop:
                break
            # Rejudge after the arm has finished and returned to standby.  This is the automatic
            # post-motion judgment the user wanted, not a pre-motion snapshot at / key press.
            _post_motion_rejudge(executed)

        max_ov, depths, src = _measure_current_overflow_for_loop()
        pose_err, pose_msg, _pose_detail = _variable_pose_axis_center_error_mm()
        if pose_err is not None:
            latest_variable_overflow_status = f"max rounds reached; latest pose_axis_center_error={pose_err:.1f}mm"
            print(f"[VAR-OVERFLOW-LOOP] {latest_variable_overflow_status} | {pose_msg}")
        elif max_ov is not None:
            latest_variable_overflow_status = f"max rounds reached; latest max_overflow={max_ov:.1f}mm"
            print(f"[VAR-OVERFLOW-LOOP] {latest_variable_overflow_status} depths={{{', '.join(f'{k}:{v:.1f}' for k,v in depths.items())}}}")
        else:
            latest_variable_overflow_status = f"max rounds reached; latest overflow unavailable: {src}"
            print(f"[VAR-OVERFLOW-LOOP] {latest_variable_overflow_status}")


    def _marker_fill_marker_points() -> Dict[int, Tuple[float, float]]:
        pts: Dict[int, Tuple[float, float]] = {}
        try:
            raw = cfg.get("aruco", {}).get("marker_board_mm", {})
            for k, v in raw.items():
                mid = int(k)
                if mid in (0, 1, 2, 3) and isinstance(v, (list, tuple)) and len(v) >= 2:
                    pts[mid] = (float(v[0]), float(v[1]))
        except Exception:
            pass
        pts.setdefault(0, (0.0, 0.0))
        pts.setdefault(1, (0.0, -496.0))
        pts.setdefault(2, (492.0, 5.0))
        pts.setdefault(3, (494.0, -490.0))
        return pts

    def _marker_fill_arm_for_marker(marker_id: int) -> str:
        return "arm2" if int(marker_id) in (0, 1) else "arm1"

    def _choose_marker_fill_target(board: np.ndarray) -> Tuple[Optional[int], Dict[str, Any]]:
        """Pick the ArUco marker that is farthest from the visible cloth mask.

        Step_a2 policy for key 4:
          1) measure nearest cloth distance for ID0/ID1/ID2/ID3;
          2) select the marker with the largest nearest distance;
          3) use the marker-side arm and drag a nearby internal cloth point toward that marker.
        """
        markers = _marker_fill_marker_points()
        radius = max(30.0, float(args.marker_fill_radius_mm))
        stats: Dict[int, Dict[str, Any]] = {}
        for mid, mxy in markers.items():
            mp = np.asarray(mxy, dtype=np.float32).reshape(2)
            if board is None or len(board) == 0:
                nearest = 9999.0
                count = 0
                mean_near = 9999.0
            else:
                d = np.linalg.norm(board[:, :2] - mp.reshape(1, 2), axis=1)
                count = int(np.count_nonzero(d <= radius))
                nearest = float(np.min(d)) if len(d) else 9999.0
                k = min(25, len(d))
                mean_near = float(np.mean(np.partition(d, k - 1)[:k])) if k > 0 else nearest
            score = float(nearest) + 0.15 * float(mean_near) - 0.25 * float(count)
            stats[mid] = {
                "marker_xy": [float(mp[0]), float(mp[1])],
                "near_count": int(count),
                "nearest_mm": float(nearest),
                "mean_nearest_mm": float(mean_near),
                "score": float(score),
                "arm_key": _marker_fill_arm_for_marker(mid),
            }

        if not stats:
            return None, {"status": "no marker coordinates", "stats": stats}
        selected = max(stats.keys(), key=lambda mid: (float(stats[mid]["nearest_mm"]), float(stats[mid]["score"])))
        return int(selected), {
            "status": "OK farthest marker selected",
            "stats": stats,
            "selected": int(selected),
            "score": float(stats[int(selected)]["score"]),
        }

    def _marker_fill_candidate_for_arm(board: np.ndarray, marker_id: int, arm_key: str) -> Optional[Tuple[float, float, int]]:
        """Choose a stable internal cloth point for key 4 marker fill.

        Policy:
          1) key 4 selects the marker farthest from the current cloth mask;
          2) the marker-side arm is used;
          3) the contact point is the actual cloth-mask sample closest to that marker,
             but inset toward the cloth center by --marker-fill-inside-offset-mm so it
             is not an unstable edge point.
        """
        markers = _marker_fill_marker_points()
        if marker_id not in markers or board is None or len(board) < 10:
            return None
        marker_xy = np.asarray(markers[marker_id], dtype=np.float32).reshape(2)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(max(10.0, float(getattr(args, "marker_fill_pick_safe_margin", args.boundary_recovery_target_margin))))
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        dead = float(args.workspace_dead_half_width)
        min_pts = max(3, int(args.marker_fill_min_safe_points))
        inset = max(0.0, float(getattr(args, "marker_fill_inside_offset_mm", 45.0)))

        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        target_safe = ((board[:, 0] >= min_bx + target_margin) & (board[:, 0] <= max_bx - target_margin) &
                       (board[:, 1] >= min_by + target_margin) & (board[:, 1] <= max_by - target_margin))
        if arm_key == "arm2":
            arm_side = board[:, 0] <= (split_x - dead)
        else:
            arm_side = board[:, 0] >= (split_x + dead)

        masks_to_try = [
            target_safe & arm_side,
            board_inside & arm_side,
            target_safe,
            board_inside,
        ]
        idxs = np.array([], dtype=int)
        for mask in masks_to_try:
            cand = np.where(mask)[0]
            if len(cand) >= min_pts:
                idxs = cand
                break
        if len(idxs) < min_pts:
            return None

        pts = board[idxs].astype(np.float32)
        all_inside_pts = board[board_inside].astype(np.float32)
        cloth_center = np.median(all_inside_pts[:, :2], axis=0).astype(np.float32) if len(all_inside_pts) >= 10 else np.median(board[:, :2], axis=0).astype(np.float32)

        d_marker = np.linalg.norm(pts[:, :2] - marker_xy.reshape(1, 2), axis=1)
        edge_i = int(np.argmin(d_marker))
        edge_pt = pts[edge_i, :2].astype(np.float32)

        v_in = cloth_center - edge_pt
        n_in = float(np.linalg.norm(v_in))
        if n_in > 1e-6 and inset > 0.0:
            desired = edge_pt + (v_in / n_in) * min(inset, n_in * 0.92)
        else:
            desired = edge_pt

        min_ratio = float(np.clip(getattr(args, "marker_fill_min_internal_ratio", 0.62), 0.0, 0.90))
        if n_in > 1e-6:
            deep_len = min(max(inset, n_in * min_ratio), n_in * 0.88)
            deep_pick = edge_pt + (v_in / n_in) * deep_len
        else:
            deep_pick = edge_pt.copy()

        # fix: key 4 also must keep the displayed/commanded internal point
        # inside the selected marker-side arm workspace.  Otherwise the point can
        # appear on the cloth but land in the center dead zone and become BLOCKED.
        ws_margin = max(0.0, float(getattr(args, "deep_internal_pick_workspace_margin_mm", 12.0)))
        if n_in > 1e-6:
            if arm_key == "arm1":
                arm_min_x = float(split_x + dead + ws_margin)
                if float(deep_pick[0]) < arm_min_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_min_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = max(float(deep_pick[0]), arm_min_x)
            else:
                arm_max_x = float(split_x - dead - ws_margin)
                if float(deep_pick[0]) > arm_max_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_max_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = min(float(deep_pick[0]), arm_max_x)

        deep_pick[0] = float(np.clip(deep_pick[0], min_bx + target_margin, max_bx - target_margin))
        deep_pick[1] = float(np.clip(deep_pick[1], min_by + target_margin, max_by - target_margin))
        if bool(getattr(args, "smart_reposition_snap_to_mask", True)):
            snap_mask = np.zeros(len(board), dtype=bool)
            snap_mask[idxs] = True
            deep_pick, support_dist, snap_n = _snap_deep_pick_to_mask_board_point(
                board, snap_mask, deep_pick, edge_pt, cloth_center, arm_key, f"MARKER-FILL-ID{marker_id}"
            )
        else:
            d_support = np.linalg.norm(pts[:, :2] - deep_pick.reshape(1, 2), axis=1)
            support_dist = float(np.min(d_support)) if len(d_support) else -1.0
            snap_n = int(len(idxs))
        bx, by = float(deep_pick[0]), float(deep_pick[1])
        print(f"[MARKER-FILL-DEEP-INTERNAL-PICK] ID{marker_id} {arm_key.upper()} edge=({edge_pt[0]:.1f},{edge_pt[1]:.1f}) "
              f"center=({cloth_center[0]:.1f},{cloth_center[1]:.1f}) inset={inset:.1f} ratio={min_ratio:.2f} "
              f"pick=({bx:.1f},{by:.1f}) ws_margin={float(getattr(args, 'deep_internal_pick_workspace_margin_mm', 12.0)):.1f} nearest_mask_sample_dist={support_dist:.1f}mm snap_candidates={snap_n}")
        return bx, by, int(len(idxs))

    def _smart_internal_candidate_toward_target(board: np.ndarray, target_xy: Tuple[float, float], arm_key: str, label: str = "CENTER") -> Optional[Tuple[float, float, int]]:
        """Generic deep-internal contact point for key-4 AUTO CENTER.

        It chooses a real cloth side facing the desired target point, then moves the
        displayed/commanded pick point aggressively toward the cloth median center.
        The final point is also kept inside the selected arm's private workspace so
        the camera overlay and the executable RoArm target cannot fall into BLOCKED.
        """
        if board is None or len(board) < 10:
            return None
        target = np.asarray(target_xy, dtype=np.float32).reshape(2)
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        target_margin = float(max(10.0, float(getattr(args, "marker_fill_pick_safe_margin", args.boundary_recovery_target_margin))))
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        dead = float(args.workspace_dead_half_width)
        min_pts = max(3, int(args.marker_fill_min_safe_points))
        inset = max(0.0, float(getattr(args, "marker_fill_inside_offset_mm", 125.0)))

        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        target_safe = ((board[:, 0] >= min_bx + target_margin) & (board[:, 0] <= max_bx - target_margin) &
                       (board[:, 1] >= min_by + target_margin) & (board[:, 1] <= max_by - target_margin))
        if arm_key == "arm2":
            arm_side = board[:, 0] <= (split_x - dead)
        else:
            arm_side = board[:, 0] >= (split_x + dead)

        masks_to_try = [
            target_safe & arm_side,
            board_inside & arm_side,
            target_safe,
            board_inside,
        ]
        idxs = np.array([], dtype=int)
        for mask in masks_to_try:
            cand = np.where(mask)[0]
            if len(cand) >= min_pts:
                idxs = cand
                break
        if len(idxs) < min_pts:
            return None

        pts = board[idxs].astype(np.float32)
        all_inside_pts = board[board_inside].astype(np.float32)
        cloth_center = np.median(all_inside_pts[:, :2], axis=0).astype(np.float32) if len(all_inside_pts) >= 10 else np.median(board[:, :2], axis=0).astype(np.float32)

        d_target = np.linalg.norm(pts[:, :2] - target.reshape(1, 2), axis=1)
        edge_i = int(np.argmin(d_target))
        edge_pt = pts[edge_i, :2].astype(np.float32)

        v_in = cloth_center - edge_pt
        n_in = float(np.linalg.norm(v_in))
        min_ratio = float(np.clip(getattr(args, "marker_fill_min_internal_ratio", 0.62), 0.0, 0.90))
        if n_in > 1e-6:
            deep_len = min(max(inset, n_in * min_ratio), n_in * 0.88)
            deep_pick = edge_pt + (v_in / n_in) * deep_len
        else:
            deep_pick = edge_pt.copy()

        # Keep inside the selected arm workspace; this prevents center dead-zone BLOCKED.
        ws_margin = max(0.0, float(getattr(args, "deep_internal_pick_workspace_margin_mm", 12.0)))
        if n_in > 1e-6:
            if arm_key == "arm1":
                arm_min_x = float(split_x + dead + ws_margin)
                if float(deep_pick[0]) < arm_min_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_min_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = max(float(deep_pick[0]), arm_min_x)
            else:
                arm_max_x = float(split_x - dead - ws_margin)
                if float(deep_pick[0]) > arm_max_x:
                    dx = float(v_in[0])
                    if abs(dx) > 1e-6:
                        frac = float(np.clip((arm_max_x - float(edge_pt[0])) / dx, 0.0, 0.88))
                        deep_pick = edge_pt + v_in * frac
                    deep_pick[0] = min(float(deep_pick[0]), arm_max_x)

        deep_pick[0] = float(np.clip(deep_pick[0], min_bx + target_margin, max_bx - target_margin))
        deep_pick[1] = float(np.clip(deep_pick[1], min_by + target_margin, max_by - target_margin))
        if bool(getattr(args, "smart_reposition_snap_to_mask", True)):
            snap_mask = np.zeros(len(board), dtype=bool)
            snap_mask[idxs] = True
            deep_pick, support_dist, snap_n = _snap_deep_pick_to_mask_board_point(
                board, snap_mask, deep_pick, edge_pt, cloth_center, arm_key, f"AUTO-CENTER-{label}"
            )
        else:
            d_support = np.linalg.norm(pts[:, :2] - deep_pick.reshape(1, 2), axis=1)
            support_dist = float(np.min(d_support)) if len(d_support) else -1.0
            snap_n = int(len(idxs))
        bx, by = float(deep_pick[0]), float(deep_pick[1])
        print(f"[AUTO-CENTER-DEEP-INTERNAL-PICK] {arm_key.upper()} target={label} edge=({edge_pt[0]:.1f},{edge_pt[1]:.1f}) "
              f"center=({cloth_center[0]:.1f},{cloth_center[1]:.1f}) inset={inset:.1f} ratio={min_ratio:.2f} "
              f"pick=({bx:.1f},{by:.1f}) ws_margin={float(getattr(args, 'deep_internal_pick_workspace_margin_mm', 12.0)):.1f} nearest_mask_sample_dist={support_dist:.1f}mm snap_candidates={snap_n}")
        return bx, by, int(len(idxs))

    def build_marker_fill_drag_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True) -> Optional[Dict[str, Any]]:
        """Build key-4 SMART REPOSITION plan.

        Step_a9 policy:
          1) If the garment is clearly biased left/right from the board center axis,
             absorb the old key-9 recovery behavior into key 4 and pull the cloth back
             toward the opposite side/center.
          2) If side bias is not large, choose the ArUco marker farthest from the cloth
             and pull a deep internal cloth point toward that empty marker/corner.
          3) The displayed camera pick point and the commanded pick point are the same
             deep-internal point, and it is kept inside the selected arm workspace.
        """
        nonlocal latest_marker_fill_plan, latest_marker_fill_status
        if not bool(args.marker_fill_drag_mode):
            latest_marker_fill_plan, latest_marker_fill_status = None, "smart reposition mode OFF"
            return None

        board = _boundary_board_points_from_plan(plan)
        if board is None or len(board) < 20:
            latest_marker_fill_plan, latest_marker_fill_status = None, "no current mask board points"
            if print_result:
                print(f"[SMART-REPOSITION] not ready: {latest_marker_fill_status}")
            return None

        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        board_center_x = 0.5 * (float(min_bx) + float(max_bx))
        board_inside = ((board[:, 0] >= min_bx) & (board[:, 0] <= max_bx) &
                        (board[:, 1] >= min_by) & (board[:, 1] <= max_by))
        pts_inside = board[board_inside] if int(np.count_nonzero(board_inside)) >= 10 else board
        board_center_y = 0.5 * (float(min_by) + float(max_by))
        cloth_median_x = float(np.median(pts_inside[:, 0]))
        cloth_median_y = float(np.median(pts_inside[:, 1]))
        cloth_mean_x = float(np.mean(pts_inside[:, 0]))
        cloth_mean_y = float(np.mean(pts_inside[:, 1]))
        delta_x = cloth_median_x - board_center_x
        delta_y = cloth_median_y - board_center_y
        error_x = board_center_x - cloth_median_x
        error_y = board_center_y - cloth_median_y
        center_error_norm = float(np.linalg.norm([error_x, error_y]))
        done_x = max(0.0, float(getattr(args, "auto_center_done_error_x_mm", 30.0)))
        done_y = max(0.0, float(getattr(args, "auto_center_done_error_y_mm", 35.0)))
        side_threshold = max(0.0, float(getattr(args, "smart_reposition_side_bias_threshold_mm", 35.0)))

        def _common_contact_plan(
            *,
            smart_mode: str,
            arm_key: str,
            start_bx: float,
            start_by: float,
            end_bx: float,
            end_by: float,
            npts: int,
            target_label: str,
            marker_id: int = -1,
            marker_xy: Optional[Tuple[float, float]] = None,
            stats: Optional[Dict[str, Any]] = None,
            side_info: Optional[Dict[str, Any]] = None,
            pull_distance: float = 0.0,
        ) -> Optional[Dict[str, Any]]:
            nonlocal latest_marker_fill_plan, latest_marker_fill_status
            hover_z = float(args.boundary_recovery_hover_z) if args.boundary_recovery_hover_z is not None else float(args.z)
            if args.marker_fill_drag_z is not None:
                contact_z = float(args.marker_fill_drag_z)
            elif args.boundary_recovery_drag_z is not None:
                contact_z = float(args.boundary_recovery_drag_z)
            else:
                contact_z = float(args.press_z)

            if args.marker_fill_drag_clear_z is not None:
                clear_z = float(args.marker_fill_drag_clear_z)
            elif args.boundary_recovery_drag_clear_z is not None:
                clear_z = float(args.boundary_recovery_drag_clear_z)
            elif bool(getattr(args, "press_extra_clear_after_sweep", False)) and args.press_extra_clear_z is not None:
                clear_z = float(args.press_extra_clear_z)
            elif args.press_clear_z is not None:
                clear_z = float(args.press_clear_z)
            else:
                clear_z = float(hover_z)

            hover = resolve_board_target_for_arm(arm_key, start_bx, start_by, hover_z, "SMART-REPOSITION-HOVER")
            down_raw = resolve_board_target_for_arm(arm_key, start_bx, start_by, contact_z, "SMART-REPOSITION-DOWN")
            drag_raw = resolve_board_target_for_arm(arm_key, end_bx, end_by, contact_z, "SMART-REPOSITION-DRAG")
            down = _apply_low_z_roarm_offset(down_raw, "marker_fill", "SMART-REPOSITION-DOWN")
            drag = _apply_low_z_roarm_offset(drag_raw, "marker_fill", "SMART-REPOSITION-DRAG")
            clear = None
            if drag is not None:
                clear = dict(drag)
                clear["rz"] = float(clear_z)
            if hover is None or down is None or drag is None or clear is None:
                latest_marker_fill_status = f"resolved smart reposition target blocked: mode={smart_mode}, target={target_label}, arm={arm_key.upper()}"
                if print_result:
                    print(f"[SMART-REPOSITION] not ready: {latest_marker_fill_status}")
                return None

            sx, sy = float(start_bx), float(start_by)
            ex, ey = float(end_bx), float(end_by)
            v = np.asarray([ex - sx, ey - sy], dtype=np.float32)
            norm = float(np.linalg.norm(v))
            ux, uy = (float(v[0] / norm), float(v[1] / norm)) if norm > 1e-6 else (0.0, 0.0)
            if marker_xy is None:
                marker_xy = (float(ex), float(ey))

            if smart_mode == "side_recovery":
                mode_label = "SIDE_RECOVERY"
            elif smart_mode == "center_reposition":
                mode_label = "AUTO_CENTER"
            else:
                mode_label = "MARKER_FILL"
            latest_marker_fill_plan = {
                "mode": "smart_reposition",
                "smart_mode": smart_mode,
                "mode_label": mode_label,
                "target_label": str(target_label),
                "marker_id": int(marker_id),
                "marker_xy": [float(marker_xy[0]), float(marker_xy[1])],
                "arm_key": arm_key,
                "start_board_xy": [sx, sy],
                "end_board_xy": [ex, ey],
                "pull_vector": [float(ux), float(uy)],
                "pull_distance": float(pull_distance),
                "reachable_points": int(npts),
                "stats": stats or {},
                "side_info": side_info or {},
                "cloth_median_x": float(cloth_median_x),
                "cloth_mean_x": float(cloth_mean_x),
                "board_center_x": float(board_center_x),
                "delta_x": float(delta_x),
                "side_threshold_mm": float(side_threshold),
                "hover": hover,
                "down": down,
                "drag": drag,
                "clear": clear,
                "down_raw": down_raw,
                "drag_raw": drag_raw,
                "contact_offset_roarm": [
                    float(getattr(args, f"marker_fill_{arm_key}_contact_offset_x", 0.0)),
                    float(getattr(args, f"marker_fill_{arm_key}_contact_offset_y", 0.0)),
                ],
                "z_info": {"hover_z": float(hover_z), "contact_z": float(contact_z), "clear_z": float(clear_z)},
                "summary": (
                    f"smart reposition mode={mode_label} target={target_label} arm={arm_key.upper()} "
                    f"pick=({sx:.1f},{sy:.1f}) -> ({ex:.1f},{ey:.1f}) dist={float(pull_distance):.1f}mm "
                    f"delta_x={float(delta_x):.1f}mm threshold={float(side_threshold):.1f}mm points={int(npts)} "
                    f"offset={float(getattr(args, f'marker_fill_{arm_key}_contact_offset_x', 0.0)):.1f},"
                    f"{float(getattr(args, f'marker_fill_{arm_key}_contact_offset_y', 0.0)):.1f}"
                ),
                "sequence": "padded-close -> hover -> vertical contact down -> low-z drag -> vertical clear -> open -> standby/reinfer",
            }
            latest_marker_fill_status = "OK"
            return latest_marker_fill_plan

        if abs(error_x) > done_x or abs(error_y) > done_y:
            target_center = np.asarray([board_center_x, board_center_y], dtype=np.float32)
            drag_vec = target_center - np.asarray([cloth_median_x, cloth_median_y], dtype=np.float32)
            drag_norm = float(np.linalg.norm(drag_vec))
            if drag_norm > 1e-6:
                if abs(error_x) >= max(12.0, 0.35 * max(done_x, 1.0)):
                    arm_order = ["arm1", "arm2"] if error_x > 0.0 else ["arm2", "arm1"]
                else:
                    arm_order = ["arm1", "arm2"] if cloth_median_x >= board_center_x else ["arm2", "arm1"]

                cand = None
                arm_key = arm_order[0]
                for ak in arm_order:
                    cand_try = _smart_internal_candidate_toward_target(board, (float(board_center_x), float(board_center_y)), ak, label="BOARD_CENTER")
                    if cand_try is not None:
                        cand = cand_try
                        arm_key = ak
                        break

                if cand is not None:
                    start_bx, start_by, npts = cand
                    gain = max(0.0, float(getattr(args, "auto_center_pull_gain", 0.75)))
                    dmin = max(0.0, float(getattr(args, "auto_center_pull_min_mm", 40.0)))
                    dmax = max(dmin, float(getattr(args, "auto_center_pull_max_mm", 95.0)))
                    dist = float(np.clip(gain * drag_norm, dmin, dmax))
                    ux, uy = float(drag_vec[0] / drag_norm), float(drag_vec[1] / drag_norm)
                    target_margin = float(max(float(args.boundary_recovery_target_margin), float(args.board_margin)))
                    end_bx, end_by = _clamp_board_xy(start_bx + ux * dist, start_by + uy * dist, target_margin)
                    print(f"[AUTO-CENTER] mode=CENTERING error=({error_x:+.1f},{error_y:+.1f})mm norm={drag_norm:.1f} "
                          f"done=({done_x:.1f},{done_y:.1f}) arm={arm_key.upper()} pull={dist:.1f}mm")
                    mp = _common_contact_plan(
                        smart_mode="center_reposition",
                        arm_key=arm_key,
                        start_bx=start_bx,
                        start_by=start_by,
                        end_bx=end_bx,
                        end_by=end_by,
                        npts=npts,
                        target_label="BOARD_CENTER",
                        marker_id=-1,
                        marker_xy=(float(board_center_x), float(board_center_y)),
                        stats={},
                        side_info={
                            "policy": "closed-loop auto-center: move cloth median toward ArUco frame center",
                            "cloth_median_x": float(cloth_median_x),
                            "cloth_median_y": float(cloth_median_y),
                            "cloth_mean_x": float(cloth_mean_x),
                            "cloth_mean_y": float(cloth_mean_y),
                            "board_center_x": float(board_center_x),
                            "board_center_y": float(board_center_y),
                            "error_x": float(error_x),
                            "error_y": float(error_y),
                            "error_norm": float(drag_norm),
                            "done_x": float(done_x),
                            "done_y": float(done_y),
                        },
                        pull_distance=dist,
                    )
                    if mp is not None:
                        if print_result:
                            print("\n========== AUTO CENTER PLAN (4) ==========")
                            print(mp["summary"])
                            print(f"Priority: center error is outside tolerance. error=({error_x:+.1f},{error_y:+.1f})mm, done=({done_x:.1f},{done_y:.1f})mm")
                            print("Key 4 will repeat this fresh-mask correction up to --auto-center-rounds times.")
                            print("==========================================\n")
                        return mp
                    print("[AUTO-CENTER] centering plan was blocked; falling back to side/marker logic.")
                else:
                    print("[AUTO-CENTER] no reachable internal point for centering; falling back to side/marker logic.")

        if abs(delta_x) >= side_threshold:
            side = "left" if delta_x < 0.0 else "right"
            arm_key = "arm1" if side == "left" else "arm2"
            cand = _boundary_candidate_for_opposite_drag_arm(board, side, arm_key)
            if cand is not None:
                start_bx, start_by, npts = cand
                ux, uy = _boundary_pull_vector(side)
                raw_dist = getattr(args, "smart_reposition_side_pull_distance", None)
                dist = float(args.boundary_recovery_pull_distance) if raw_dist is None else float(raw_dist)
                dist = max(0.0, dist)
                target_margin = float(max(float(args.boundary_recovery_target_margin), float(args.board_margin)))
                end_bx, end_by = _clamp_board_xy(start_bx + ux * dist, start_by + uy * dist, target_margin)
                side_info = {
                    "side": side,
                    "cloth_median_x": float(cloth_median_x),
                    "cloth_mean_x": float(cloth_mean_x),
                    "center_axis_x": float(board_center_x),
                    "delta_x": float(delta_x),
                    "threshold_mm": float(side_threshold),
                    "policy": "large side bias: merged old key 9 into key 4",
                }
                target_label = "ID0/1 -> ID2/3" if side == "left" else "ID2/3 -> ID0/1"
                print(f"[SMART-REPOSITION] mode=SIDE_RECOVERY side={side} delta_x={delta_x:.1f} threshold={side_threshold:.1f} arm={arm_key.upper()}")
                mp = _common_contact_plan(
                    smart_mode="side_recovery",
                    arm_key=arm_key,
                    start_bx=start_bx,
                    start_by=start_by,
                    end_bx=end_bx,
                    end_by=end_by,
                    npts=npts,
                    target_label=target_label,
                    marker_id=-1,
                    marker_xy=(end_bx, end_by),
                    stats={},
                    side_info=side_info,
                    pull_distance=dist,
                )
                if mp is not None:
                    if print_result:
                        print("\n========== SMART REPOSITION PLAN (4) ==========")
                        print(mp["summary"])
                        print("Priority: side recovery because left/right center-axis bias is large.")
                        print("Key 9 is disabled; this behavior now lives inside key 4.")
                        print("==============================================\n")
                    return mp
                print("[SMART-REPOSITION] side recovery plan was blocked; falling back to marker-fill mode.")
            else:
                print(f"[SMART-REPOSITION] side bias detected but no reachable internal point for {arm_key.upper()}; falling back to marker-fill mode.")

        marker_id, info = _choose_marker_fill_target(board)
        if marker_id is None:
            latest_marker_fill_plan, latest_marker_fill_status = None, info.get("status", "no selected marker")
            if print_result:
                print(f"[SMART-REPOSITION] {latest_marker_fill_status}")
                print(f"[SMART-REPOSITION] stats={info.get('stats')}")
            return None

        stats = info.get("stats", {}) if isinstance(info, dict) else {}
        selected_stat = stats.get(int(marker_id), {}) if isinstance(stats, dict) else {}
        nearest_mm = float(selected_stat.get("nearest_mm", 9999.0))
        marker_threshold = max(0.0, float(getattr(args, "smart_reposition_marker_empty_threshold_mm", 65.0)))
        if nearest_mm < marker_threshold:
            latest_marker_fill_plan = None
            latest_marker_fill_status = (
                f"balanced: side bias |delta_x|={abs(delta_x):.1f}mm < {side_threshold:.1f}mm and "
                f"farthest marker ID{int(marker_id)} nearest={nearest_mm:.1f}mm < {marker_threshold:.1f}mm"
            )
            if print_result:
                print(f"[SMART-REPOSITION] {latest_marker_fill_status}")
                print(f"[SMART-REPOSITION] marker stats={stats}")
            return None

        markers = _marker_fill_marker_points()
        marker_xy = markers[int(marker_id)]
        arm_key = _marker_fill_arm_for_marker(int(marker_id))
        cand = _marker_fill_candidate_for_arm(board, int(marker_id), arm_key)
        if cand is None:
            latest_marker_fill_plan = None
            latest_marker_fill_status = f"no safe visible cloth point for marker ID{marker_id} with {arm_key.upper()}"
            if print_result:
                print(f"[SMART-REPOSITION] not ready: {latest_marker_fill_status}")
                print(f"[SMART-REPOSITION] marker stats={stats}")
            return None

        start_bx, start_by, npts = cand
        target = np.asarray(marker_xy, dtype=np.float32).reshape(2)
        start = np.asarray([start_bx, start_by], dtype=np.float32)
        vec = target - start
        norm = float(np.linalg.norm(vec))
        if norm < 1e-6:
            latest_marker_fill_plan = None
            latest_marker_fill_status = f"selected point is already at marker ID{marker_id}"
            if print_result:
                print(f"[SMART-REPOSITION] {latest_marker_fill_status}")
            return None
        ux, uy = float(vec[0] / norm), float(vec[1] / norm)
        dist = min(max(0.0, float(args.marker_fill_pull_distance)), max(0.0, norm - float(max(args.boundary_recovery_target_margin, args.board_margin)) * 0.35))
        target_margin = float(max(float(args.boundary_recovery_target_margin), float(args.board_margin)))
        end_bx, end_by = _clamp_board_xy(start_bx + ux * dist, start_by + uy * dist, target_margin)

        print(f"[SMART-REPOSITION] mode=MARKER_FILL farthest=ID{int(marker_id)} nearest={nearest_mm:.1f} threshold={marker_threshold:.1f} arm={arm_key.upper()}")
        mp = _common_contact_plan(
            smart_mode="marker_fill",
            arm_key=arm_key,
            start_bx=start_bx,
            start_by=start_by,
            end_bx=end_bx,
            end_by=end_by,
            npts=npts,
            target_label=f"EMPTY ID{int(marker_id)}",
            marker_id=int(marker_id),
            marker_xy=marker_xy,
            stats=stats,
            side_info={
                "cloth_median_x": float(cloth_median_x),
                "cloth_mean_x": float(cloth_mean_x),
                "center_axis_x": float(board_center_x),
                "delta_x": float(delta_x),
                "threshold_mm": float(side_threshold),
            },
            pull_distance=dist,
        )
        if mp is None:
            return None
        if print_result:
            print("\n========== SMART REPOSITION PLAN (4) ==========")
            print(mp["summary"])
            print("Priority: marker/corner fill because side bias is not dominant.")
            print(f"marker stats={stats}")
            print("Key 9 is disabled; use key 4 for this reposition behavior.")
            print("==============================================\n")
        return mp

    def marker_corner_fill_drag(fresh_before: Optional[bool] = None, reinfer_after: bool = True):
        nonlocal latest_marker_fill_plan, latest_marker_fill_status, coarse_x_since_last_press
        if not bool(args.marker_fill_drag_mode):
            print("[SMART-REPOSITION] smart reposition mode is OFF")
            return None
        plan = None
        use_fresh_before = bool(args.marker_fill_fresh_snapshot) if fresh_before is None else bool(fresh_before)
        if use_fresh_before and snapshot_mode:
            plan = request_fresh_coarse_plan_and_wait(
                reason="before smart reposition",
                timeout=float(args.marker_fill_fresh_timeout),
            )
        else:
            plan = latest_coarse_plan
        mp = build_marker_fill_drag_plan(plan, print_result=True)
        if mp is None:
            return None
        if not send_enabled:
            print("[DRY-RUN] Smart reposition commands not sent.")
            return mp

        preview_wait = max(0.0, float(getattr(args, "marker_fill_preview_wait", 0.0)))
        if preview_wait > 0.0:
            print(f"[SMART-REPOSITION-PREVIEW] showing selected contact point/drag vector for {preview_wait:.2f}s before motion")
            time.sleep(preview_wait)

        arm_key = mp["arm_key"]
        arm_obj = arms.get(arm_key)
        if arm_obj is None:
            print(f"[SMART-REPOSITION-BLOCKED] {arm_key.upper()} is not connected.")
            return None

        drag_gripper = float(args.marker_fill_drag_gripper) if args.marker_fill_drag_gripper is not None else float(args.boundary_recovery_drag_gripper)
        drag_speed = float(args.marker_fill_drag_speed)
        print("\n========== MARKER-CORNER FILL CONTACT DRAG (4) ==========")
        print(mp["summary"])
        print(f"drag_gripper={drag_gripper:.3f}, contact_z={mp.get('z_info', {}).get('contact_z')}, clear_z={mp.get('z_info', {}).get('clear_z')}, speed={drag_speed:.2f}")
        print(f"Mode={mp.get('mode_label', mp.get('smart_mode','?'))}, target={mp.get('target_label','?')}")
        print("This does NOT lift the cloth. It presses lightly and drags a deep internal cloth point toward the selected correction target.")
        print("If it drags too hard, raise --marker-fill-drag-z or reduce --marker-fill-drag-gripper.")
        print("Keep emergency power cutoff ready.")
        print("========================================================\n")

        arm_obj.torque_on()
        print(f"[SMART-REPOSITION-PADDED-CLOSE] {arm_key.upper()} contact gripper angle={drag_gripper:.3f}")
        arm_obj.set_gripper(drag_gripper, spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
        time.sleep(0.15)

        hover = mp["hover"]
        print(f"[SMART-REPOSITION-HOVER] {arm_key.upper()} move: ({hover['rx']:.1f},{hover['ry']:.1f},{hover['rz']:.1f})")
        arm_obj.move_goal(args.move_command, hover["rx"], hover["ry"], hover["rz"], t=args.t, spd=spd_default)
        time.sleep(0.25)

        if bool(getattr(args, "marker_fill_hover_only", False)):
            print("[SMART-REPOSITION-HOVER-ONLY] debug option enabled. Stop after hover; no contact/drag.")
            return mp

        down = mp["down"]
        print(f"[SMART-REPOSITION-CONTACT-DOWN] {arm_key.upper()} move: ({down['rx']:.1f},{down['ry']:.1f},{down['rz']:.1f})")
        arm_obj.move_goal(args.move_command, down["rx"], down["ry"], down["rz"], t=args.t, spd=drag_speed)
        time.sleep(max(0.0, float(args.marker_fill_down_wait)))

        if bool(getattr(args, "marker_fill_contact_test_only", False)):
            print("[SMART-REPOSITION-CONTACT-TEST-ONLY] debug option enabled. Lift clear without drag.")
            clear = dict(down)
            clear["rz"] = float(mp.get("z_info", {}).get("clear_z", args.z))
            print(f"[SMART-REPOSITION-TEST-CLEAR] {arm_key.upper()} clear at same corrected XY: ({clear['rx']:.1f},{clear['ry']:.1f},{clear['rz']:.1f})")
            arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=args.t, spd=spd_default)
            time.sleep(0.25)
            return mp

        drag = mp["drag"]
        print(f"[SMART-REPOSITION-DRAG] {arm_key.upper()} drag toward {mp.get('target_label','target')}: ({drag['rx']:.1f},{drag['ry']:.1f},{drag['rz']:.1f})")
        arm_obj.move_goal(args.move_command, drag["rx"], drag["ry"], drag["rz"], t=args.t, spd=drag_speed)
        time.sleep(max(0.0, float(args.marker_fill_sweep_wait)))

        clear = mp["clear"]
        print(f"[SMART-REPOSITION-VERTICAL-CLEAR] {arm_key.upper()} clear at same XY: ({clear['rx']:.1f},{clear['ry']:.1f},{clear['rz']:.1f})")
        arm_obj.move_goal(args.move_command, clear["rx"], clear["ry"], clear["rz"], t=args.t, spd=spd_default)
        time.sleep(0.25)

        if bool(args.marker_fill_open_after_clear):
            print(f"[SMART-REPOSITION-OPEN-AFTER-CLEAR] {arm_key.upper()} open angle={float(args.grip_open):.3f}")
            arm_obj.set_gripper(float(args.grip_open), spd=args.grip_spd, acc=args.grip_acc, delay=0.15)
            time.sleep(float(args.boundary_recovery_release_wait))

        coarse_x_since_last_press = 0
        _reset_coarse_auto_press_cycle("cloth changed: smart reposition executed")

        if args.imaging_standby and not args.no_standby:
            move_arms_to_standby(reason="after smart reposition")
        if bool(reinfer_after):
            if snapshot_mode:
                request_fresh_coarse_plan_and_wait(
                    reason="after smart reposition",
                    timeout=float(args.marker_fill_fresh_timeout),
                )
            elif args.auto_reinfer_after_motion:
                reset_snapshot("smart reposition finished; waiting for fresh still frame")

        return mp

    def auto_center_reposition():
        """Closed-loop key-4 AUTO CENTER.

        One press of key 4 can run up to --auto-center-rounds cycles.  During the
        loop, MO/SIDE-PICK and SELECT/SPREAD share the same snapshot lifecycle:
        old smart-pick overlays are cleared on every snapshot reset, and non-smart
        overlays are hidden until the final fresh inference after the loop.
        """
        nonlocal latest_marker_fill_plan, latest_marker_fill_status
        nonlocal smart_reposition_running
        if not bool(args.marker_fill_drag_mode):
            print("[AUTO-CENTER] disabled. Run without --no-marker-fill-drag-mode.")
            return
        rounds = max(1, int(getattr(args, "auto_center_rounds", 4)))
        done_x = max(0.0, float(getattr(args, "auto_center_done_error_x_mm", 30.0)))
        done_y = max(0.0, float(getattr(args, "auto_center_done_error_y_mm", 35.0)))
        min_progress = max(0.0, float(getattr(args, "auto_center_min_progress_mm", 12.0)))
        prev_center: Optional[Tuple[float, float]] = None
        old_running = bool(smart_reposition_running)
        smart_reposition_running = True
        try:
            print("\n========== KEY 4 AUTO CENTER REPOSITION ==========")
            print(f"max_rounds={rounds}, done_error=({done_x:.1f},{done_y:.1f})mm, min_progress={min_progress:.1f}mm")
            print("Each round: fresh mask -> plan -> deep-internal contact drag -> standby/fresh mask.")
            print("During the loop, old SELECT/SPREAD/center overlays are hidden; MO/SIDE-PICK follows the current snapshot only.")
            print("Key 9 remains disabled. Keep emergency power cutoff ready.")
            print("==================================================\n")

            for round_idx in range(1, rounds + 1):
                print(f"\n[AUTO-CENTER] round {round_idx}/{rounds} starting")
                # First cycle takes a fresh mask. Later cycles reuse the fresh plan that
                # was captured after the previous drag, so we avoid duplicate re-inference
                # and stale SPREAD/center overlays during robot motion.
                need_fresh_before = (round_idx == 1 or latest_coarse_plan is None)
                mp = marker_corner_fill_drag(fresh_before=need_fresh_before, reinfer_after=True)

                if mp is None:
                    status = str(latest_marker_fill_status)
                    print(f"[AUTO-CENTER] stop at round {round_idx}: {status}")
                    break

                side_info = mp.get("side_info", {}) if isinstance(mp, dict) else {}
                cx = side_info.get("cloth_median_x", None)
                cy = side_info.get("cloth_median_y", None)
                ex = side_info.get("error_x", None)
                ey = side_info.get("error_y", None)
                if cx is not None and cy is not None:
                    cur_center = (float(cx), float(cy))
                    if prev_center is not None:
                        progress = float(np.linalg.norm(np.asarray(cur_center, dtype=np.float32) - np.asarray(prev_center, dtype=np.float32)))
                        print(f"[AUTO-CENTER] observed center shift from previous fresh mask: {progress:.1f}mm")
                        if progress < min_progress and round_idx >= 2:
                            print(f"[AUTO-CENTER] stop: center changed less than {min_progress:.1f}mm after the previous drag; likely slipping or no useful progress.")
                            break
                    prev_center = cur_center
                if ex is not None and ey is not None:
                    print(f"[AUTO-CENTER] round {round_idx} pre-drag error was ({float(ex):+.1f},{float(ey):+.1f})mm")

                if round_idx < rounds:
                    time.sleep(max(0.0, float(getattr(args, "auto_center_settle_s", 0.80))))
        finally:
            smart_reposition_running = old_running
            print("[AUTO-CENTER] loop finished. Final SELECT/SPREAD/center overlay is now allowed again.\n")

    def get_arm_press_z(arm_key: str) -> float:
        if arm_key == "arm1" and args.arm1_press_z is not None:
            return float(args.arm1_press_z)
        if arm_key == "arm2" and args.arm2_press_z is not None:
            return float(args.arm2_press_z)
        return float(args.press_z)

    def _clamp_board_xy(bx: float, by: float, margin: Optional[float] = None) -> Tuple[float, float]:
        min_bx, max_bx, min_by, max_by = board_bounds(cfg)
        m = float(args.press_board_margin if margin is None else margin)
        return (float(np.clip(float(bx), min_bx + m, max_bx - m)),
                float(np.clip(float(by), min_by + m, max_by - m)))


    def _nearest_mask_board_point(plan: Dict[str, Any], arm_key: str, target_bx: float, target_by: float) -> Optional[Tuple[float, float]]:
        try:
            board = _press_board_points_from_plan(plan)
            if board is None or len(board) < 10:
                return None
            split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
            dead = float(args.workspace_dead_half_width)
            if arm_key == "arm2":
                side = board[:, 0] <= (split_x - dead)
            else:
                side = board[:, 0] >= (split_x + dead)
            idxs = np.where(side)[0]
            if len(idxs) < 5:
                idxs = np.arange(len(board))
            if len(idxs) < 1:
                return None
            target = np.array([float(target_bx), float(target_by)], dtype=np.float32)
            d = np.linalg.norm((board[idxs] - target) * np.array([1.0, 1.25], dtype=np.float32), axis=1)
            bi = idxs[int(np.argmin(d))]
            bx, by = _clamp_board_xy(float(board[bi, 0]), float(board[bi, 1]))
            return bx, by
        except Exception as e:
            print(f"[PRESS-PLAN-WARN] nearest mask point failed for {arm_key}: {repr(e)}")
            return None

    def _nearest_mask_board_point_any(plan: Dict[str, Any], target_bx: float, target_by: float) -> Optional[Tuple[float, float]]:
        """A95: nearest cloth-mask board point without ARM1/ARM2 hard split.

        Used only for ACTION3 soft workspace active/passive contact pairing.
        """
        try:
            board = _press_board_points_from_plan(plan)
            if board is None or len(board) < 10:
                return None
            target = np.array([float(target_bx), float(target_by)], dtype=np.float32)
            d = np.linalg.norm((board - target) * np.array([1.0, 1.25], dtype=np.float32), axis=1)
            bi = int(np.argmin(d))
            bx, by = _clamp_board_xy(float(board[bi, 0]), float(board[bi, 1]))
            return bx, by
        except Exception as e:
            print(f"[PRESS-PLAN-WARN] nearest any-mask point failed: {repr(e)}")
            return None




    def _effective_press_clear_z() -> float:
        base_clear_z = float(args.press_clear_z) if args.press_clear_z is not None else float(args.press_lift_z)
        if bool(args.press_extra_clear_after_sweep) and args.press_extra_clear_z is not None:
            return max(base_clear_z, float(args.press_extra_clear_z))
        return base_clear_z


    def build_action3_gradient_wrinkle_preview(plan: Optional[Dict[str, Any]] = None,
                                               print_result: bool = True,
                                               include_structural_probe_candidates: bool = True) -> Optional[Dict[str, Any]]:
        """A72 manual-X ACTION3 preview: choose the hottest long wrinkle and pull farther along the heatmap-gradient normal direction.

        This intentionally bypasses the old targeted-press candidate ranking for ACTION3 only.
        A72 keeps ACTION3 contact selection and pull length: the contact point is farther from the red wrinkle,
        the sweep is 30mm longer, the side farther from the nearest ArUco-board side is preferred, and the arm must pull toward itself.
        It uses the visible heatmap itself:
          1) connected hot components from the wrinkle heatmap binary mask,
          2) score by heat + component area + long-axis length,
          3) pick the maximum gradient point around that component,
          4) choose a reachable cloth contact point along +/- gradient direction,
          5) build one padded-gripper sweep candidate that starts near that hot gradient region.
        """
        nonlocal latest_targeted_press_plan, latest_targeted_press_status, latest_wrinkle_heatmap_plan, latest_wrinkle_heatmap_status

        cand = _targeted_press_source_candidate(plan)
        if cand is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: no source garment candidate"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        contour = cand.get("contour") if isinstance(cand, dict) else None
        image_shape = cand.get("image_shape") if isinstance(cand, dict) else None
        if contour is None or image_shape is None or latest_H is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: missing contour/image_shape/H"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        feat = compute_coarse_mask_features(cand, latest_H)
        if feat is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: coarse mask features unavailable"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        center_board = feat.get("board", {}).get("center") if isinstance(feat.get("board", {}), dict) else None
        if center_board is None:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: no garment center board coordinate"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None

        mask_u8 = _mask_u8_from_contour(contour, image_shape)
        wh = build_wrinkle_heatmap_plan(cand, feat=feat, mask_u8=mask_u8, print_result=False)
        if not isinstance(wh, dict):
            latest_targeted_press_plan, latest_targeted_press_status = None, f"A72 action3: no heatmap plan ({latest_wrinkle_heatmap_status})"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        heat = np.asarray(wh.get("heatmap"), dtype=np.uint8)
        binary = np.asarray(wh.get("binary"), dtype=np.uint8)
        inner = np.asarray(wh.get("inner_mask"), dtype=np.uint8)
        if heat.size == 0 or binary.size == 0 or int(np.count_nonzero(binary)) < 5:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: no hot wrinkle pixels in heatmap binary"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None

        heat_f = heat.astype(np.float32)
        gx = cv2.Sobel(heat_f, cv2.CV_32F, 1, 0, ksize=3)
        gy = cv2.Sobel(heat_f, cv2.CV_32F, 0, 1, ksize=3)
        gmag = cv2.magnitude(gx, gy)
        cnts, _ = cv2.findContours((binary > 0).astype(np.uint8) * 255, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if not cnts:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: no connected heatmap components"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None

        min_area = float(max(5.0, getattr(args, "wrinkle_heatmap_min_blob_area", 45)))
        min_ratio = float(max(1.0, getattr(args, "wrinkle_press_direction_min_major_ratio", 1.25)))
        base_sweep_dist = float(max(25.0, getattr(args, "targeted_press_wrinkle_sweep_distance", 75.0)))
        sweep_extra_mm = float(max(0.0, getattr(args, "auto_x_action3_gradient_sweep_extra_mm", 30.0)))
        sweep_dist = float(max(25.0, base_sweep_dist + sweep_extra_mm))
        min_sweep = float(max(10.0, getattr(args, "targeted_press_wrinkle_min_sweep_mm", getattr(args, "targeted_press_min_sweep_execute_mm", 25.0))))
        local_min = float(max(0.06, min(float(getattr(args, "targeted_press_min_local_mask_ratio", 0.18)), 0.18)))
        search_max_mm = float(max(65.0, getattr(args, "auto_x_action3_gradient_search_max_mm", 145.0)))
        step_mm = float(max(4.0, getattr(args, "auto_x_action3_gradient_search_step_mm", 8.0)))
        # do not scrape directly on the red wrinkle ridge.  Start the contact
        # farther along the normal/gradient path, then pull still farther in that same direction.
        min_contact_offset_mm = float(max(0.0, getattr(args, "auto_x_action3_gradient_min_contact_offset_mm", 35.0)))
        preferred_contact_offset_mm = float(max(min_contact_offset_mm, getattr(args, "auto_x_action3_gradient_preferred_contact_offset_mm", 50.0)))

        def _component_metrics(wc: np.ndarray) -> Optional[Dict[str, Any]]:
            area_px = float(cv2.contourArea(wc))
            if area_px < min_area:
                return None
            cmask = np.zeros_like(heat, dtype=np.uint8)
            cv2.drawContours(cmask, [wc], -1, 255, -1)
            roi = (cmask > 0) & (inner > 0)
            if int(np.count_nonzero(roi)) < 5:
                return None
            vals = heat_f[roi]
            max_h = float(np.max(vals))
            mean_h = float(np.mean(vals))
            sum_h = float(np.sum(vals))
            hot_masked = np.where(roi, heat_f, -1.0)
            hot_y, hot_x = np.unravel_index(int(np.argmax(hot_masked)), hot_masked.shape)
            try:
                hottest_board = np.array(pixel_to_board(latest_H, float(hot_x), float(hot_y)), dtype=np.float32)
            except Exception:
                hottest_board = None
            pts = wc.reshape(-1, 2).astype(np.float32)
            if len(pts) < 5:
                return None
            mean_px = np.mean(pts, axis=0)
            pts0 = pts - mean_px
            try:
                cov = np.cov(pts0.T)
                eigvals, eigvecs = np.linalg.eigh(cov)
                order = np.argsort(eigvals)[::-1]
                eigvals = eigvals[order]
                eigvecs = eigvecs[:, order]
                major_px = eigvecs[:, 0].astype(np.float32)
                if major_px[0] < 0:
                    major_px = -major_px
                minor_val = max(float(eigvals[1]) if len(eigvals) > 1 else 1e-6, 1e-6)
                ratio = float(np.sqrt(max(float(eigvals[0]), 1e-6) / minor_val))
            except Exception:
                x, y, w, h = cv2.boundingRect(wc)
                major_px = np.array([1.0, 0.0], dtype=np.float32) if w >= h else np.array([0.0, 1.0], dtype=np.float32)
                ratio = float(max(w, h) / max(1, min(w, h)))
            proj = (pts - mean_px) @ major_px
            p0_px = mean_px + major_px * float(np.min(proj))
            p1_px = mean_px + major_px * float(np.max(proj))
            b0 = None
            b1 = None
            major_board_unit = None
            try:
                b0 = np.array(pixel_to_board(latest_H, float(p0_px[0]), float(p0_px[1])), dtype=np.float32)
                b1 = np.array(pixel_to_board(latest_H, float(p1_px[0]), float(p1_px[1])), dtype=np.float32)
                major_len_mm = float(np.linalg.norm(b1 - b0))
                major_board_unit = _unit_or_none(b1 - b0)
            except Exception:
                major_len_mm = 0.0
            search = cv2.dilate(cmask, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7)), iterations=1)
            search = cv2.bitwise_and(search, inner)
            if int(np.count_nonzero(search)) < 5:
                search = cmask
            masked_g = np.where(search > 0, gmag, -1.0)
            iy, ix = np.unravel_index(int(np.argmax(masked_g)), masked_g.shape)
            grad_mag = float(gmag[iy, ix])
            grad_px = np.array([float(gx[iy, ix]), float(gy[iy, ix])], dtype=np.float32)
            if float(np.linalg.norm(grad_px)) < 1e-6:
                normal_px = np.array([-major_px[1], major_px[0]], dtype=np.float32)
                grad_px = normal_px
                grad_note = "fallback_pca_normal"
            else:
                grad_note = "heatmap_sobel_max_gradient"
            try:
                problem_board = np.array(pixel_to_board(latest_H, float(ix), float(iy)), dtype=np.float32)
            except Exception:
                return None
            try:
                component_center_board = np.array(pixel_to_board(latest_H, float(mean_px[0]), float(mean_px[1])), dtype=np.float32)
            except Exception:
                component_center_board = np.asarray(problem_board, dtype=np.float32).reshape(2)
            grad_board = _pixel_vec_to_board_unit(float(ix), float(iy), grad_px)
            if grad_board is None:
                normal_px = np.array([-major_px[1], major_px[0]], dtype=np.float32)
                grad_board = _pixel_vec_to_board_unit(float(ix), float(iy), normal_px)
                grad_note = "fallback_pca_normal_board_convert"
            if grad_board is None:
                return None
            if major_board_unit is None:
                major_board_unit = _unit_or_none(np.array([-float(grad_board[1]), float(grad_board[0])], dtype=np.float32))
            if major_board_unit is None:
                major_board_unit = np.array([1.0, 0.0], dtype=np.float32)
            score = float(sum_h / 110.0 + max_h * 1.7 + mean_h * 0.7 + major_len_mm * 0.45 + ratio * 12.0)
            if ratio < min_ratio:
                score *= 0.72
            return {
                "contour": wc,
                "component_mask": cmask,
                "area_px": area_px,
                "max_heat": max_h,
                "mean_heat": mean_h,
                "sum_heat": sum_h,
                "major_ratio": ratio,
                "major_len_mm": major_len_mm,
                "grad_mag": grad_mag,
                "grad_px_xy": [float(ix), float(iy)],
                "grad_board": np.asarray(grad_board, dtype=np.float32).reshape(2),
                "major_board_unit": np.asarray(major_board_unit, dtype=np.float32).reshape(2),
                "major_board_endpoints": None if b0 is None or b1 is None else [[float(b0[0]), float(b0[1])], [float(b1[0]), float(b1[1])]],
                "component_center_board": np.asarray(component_center_board, dtype=np.float32).reshape(2),
                "hottest_px_xy": [float(hot_x), float(hot_y)],
                "hottest_board": None if hottest_board is None else np.asarray(hottest_board, dtype=np.float32).reshape(2),
                "grad_note": grad_note,
                "problem_board": problem_board,
                "score": score,
            }

        def _nearest_board_side_distance_mm(bx: float, by: float) -> Tuple[float, str]:
            """Distance from a board point to the nearest of the four ArUco-board sides."""
            try:
                min_x, max_x, min_y, max_y = board_bounds(cfg)
                dists = [
                    (abs(float(bx) - float(min_x)), "ID0-ID1/left"),
                    (abs(float(max_x) - float(bx)), "ID2-ID3/right"),
                    (abs(float(by) - float(min_y)), "ID1-ID3/bottom"),
                    (abs(float(max_y) - float(by)), "ID0-ID2/top"),
                ]
                return min(dists, key=lambda kv: kv[0])
            except Exception:
                return 0.0, "unknown"

        def _pulling_arm_for_direction(u_board: np.ndarray) -> Optional[str]:
            """Choose the arm on the side the contact point is pulled toward.

            For the current two-side RoArm layout, a rightward pull must be done by ARM1
            and a leftward pull by ARM2.  This prevents using the opposite arm to push
            the cloth away from itself.
            """
            ux = float(np.asarray(u_board, dtype=np.float32).reshape(2)[0])
            if ux > 0.08:
                return "arm1"
            if ux < -0.08:
                return "arm2"
            return None

        def _build_structural_candidate_radial_probe_item(metric: Dict[str, Any], repeat_track: Optional[Dict[str, Any]] = None) -> Tuple[Optional[Dict[str, Any]], str]:
            """A98: build a one-arm diagnostic pull for a structural-shadow candidate.

            The hottest pixel inside the selected heatmap component is the circle
            center.  The nearest garment-boundary point is the first circle contact.
            The actual contact is 15mm inward from that boundary and the selected
            nearer arm drags 25mm outward.  The next X observation reuses the existing
            A94 no-response confirmation logic.
            """
            try:
                repeat_mode = isinstance(repeat_track, dict)
                if repeat_mode:
                    if not bool(getattr(args, "auto_x_repeat_action3_probe_enabled", True)):
                        return None, "repeat-ACTION3 radial probe disabled"
                else:
                    if not bool(getattr(args, "auto_x_structural_candidate_radial_probe", True)):
                        return None, "radial structural-candidate probe disabled"
                    if str(metric.get("structural_status", "none")) != "candidate":
                        return None, f"status={metric.get('structural_status','none')} is not candidate"
                hot_px = metric.get("hottest_px_xy")
                hot_board_raw = metric.get("hottest_board")
                if hot_px is None or hot_board_raw is None:
                    return None, "candidate hottest point unavailable"
                hot_board = np.asarray(hot_board_raw, dtype=np.float32).reshape(2)

                k3 = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))
                eroded = cv2.erode((mask_u8 > 0).astype(np.uint8) * 255, k3, iterations=1)
                boundary = cv2.subtract((mask_u8 > 0).astype(np.uint8) * 255, eroded)
                bys, bxs = np.where(boundary > 0)
                if len(bxs) < 8:
                    return None, "garment boundary pixels unavailable"
                if len(bxs) > 24000:
                    step = int(np.ceil(len(bxs) / 24000.0))
                    bxs = bxs[::step]
                    bys = bys[::step]
                boundary_px = np.column_stack([bxs, bys]).astype(np.float32)
                boundary_board = _mask_pixels_to_board(latest_H, boundary_px)
                if boundary_board is None or len(boundary_board) < 8:
                    return None, "garment boundary board transform failed"
                dist = np.linalg.norm(boundary_board - hot_board.reshape(1, 2), axis=1)
                order = np.argsort(dist)
                first_radius = float(dist[int(order[0])])
                if repeat_mode:
                    inset_mm = float(max(1.0, getattr(args, "auto_x_repeat_action3_probe_inset_mm", 15.0)))
                    pull_mm = float(max(1.0, getattr(args, "auto_x_repeat_action3_probe_pull_mm", 20.0)))
                    min_local = float(max(0.0, getattr(args, "auto_x_repeat_action3_probe_min_local_mask_ratio", 0.18)))
                else:
                    inset_mm = float(max(1.0, getattr(args, "auto_x_structural_candidate_radial_probe_inset_mm", 15.0)))
                    pull_mm = float(max(1.0, getattr(args, "auto_x_structural_candidate_radial_probe_pull_mm", 25.0)))
                    min_local = float(max(0.0, getattr(args, "auto_x_structural_candidate_radial_probe_min_local_mask_ratio", 0.18)))
                arm_refs = {
                    "arm2": np.array([float(getattr(args, "arm2_standby_board_x", 0.0)), float(getattr(args, "arm2_standby_board_y", -248.0))], dtype=np.float32),
                    "arm1": np.array([float(getattr(args, "arm1_standby_board_x", 494.0)), float(getattr(args, "arm1_standby_board_y", -245.0))], dtype=np.float32),
                }

                max_radius = first_radius + 6.0
                for oi in order[: min(320, len(order))]:
                    radius = float(dist[int(oi)])
                    if radius > max_radius:
                        break
                    edge = np.asarray(boundary_board[int(oi)], dtype=np.float32).reshape(2)
                    outward = _unit_or_none(edge - hot_board)
                    if outward is None:
                        continue
                    grasp = edge - outward * inset_mm
                    end_raw = grasp + outward * pull_mm
                    gx, gy = _targeted_clamp_board_xy(float(grasp[0]), float(grasp[1]))
                    ex, ey = _targeted_clamp_board_xy(float(end_raw[0]), float(end_raw[1]))
                    grasp = np.array([gx, gy], dtype=np.float32)
                    end = np.array([ex, ey], dtype=np.float32)
                    actual_pull = float(np.linalg.norm(end - grasp))
                    if actual_pull < max(15.0, pull_mm * 0.85):
                        continue
                    local = float(_targeted_mask_ratio_at_board(mask_u8, float(grasp[0]), float(grasp[1])))
                    if local < min_local:
                        continue
                    # One arm only: assign the arm whose standby/reference point is
                    # closer to the actual 15mm-inward grasp point.
                    arm_key = min(("arm2", "arm1"), key=lambda ak: float(np.linalg.norm(grasp - arm_refs[ak])))
                    sp = board_to_pixel(latest_H, float(grasp[0]), float(grasp[1]))
                    ep = board_to_pixel(latest_H, float(end[0]), float(end[1]))
                    exmeta = {
                        "area_px": float(metric.get("area_px", 0.0)),
                        "heat_max": float(metric.get("max_heat", 0.0)),
                        "heat_mean": float(metric.get("mean_heat", 0.0)),
                        "heat_sum": float(metric.get("sum_heat", 0.0)),
                        "major_ratio": float(metric.get("major_ratio", 1.0)),
                        "major_len_mm": float(metric.get("major_len_mm", 0.0)),
                        "action3_gradient": True,
                        "structural_candidate_radial_probe": True,
                        "structural_probe_single_arm": True,
                        "repeat_action3_outward_probe": bool(repeat_mode),
                        "repeat_action3_track_id": (repeat_track.get("id") if repeat_mode else None),
                        "direction_board": [float(outward[0]), float(outward[1])],
                        "direction_reason": ("A102_repeat_ACTION3_hotpoint_to_boundary_outward" if repeat_mode else "A98_hotpoint_circle_to_first_boundary_then_outward"),
                        "wrinkle_axis_board": [float(metric.get("major_board_unit", np.array([1.0, 0.0], dtype=np.float32))[0]), float(metric.get("major_board_unit", np.array([1.0, 0.0], dtype=np.float32))[1])],
                        "wrinkle_axis_endpoints": metric.get("major_board_endpoints"),
                        "wrinkle_problem_board_xy": [float(hot_board[0]), float(hot_board[1])],
                        "structural_probe_hot_board_xy": [float(hot_board[0]), float(hot_board[1])],
                        "structural_probe_boundary_board_xy": [float(edge[0]), float(edge[1])],
                        "structural_probe_circle_radius_mm": float(radius),
                        "structural_probe_first_radius_mm": float(first_radius),
                        "structural_probe_inset_mm": float(inset_mm),
                        "structural_probe_pull_mm": float(actual_pull),
                        "sweep_len_preview_mm": float(actual_pull),
                        "nearest_pose_name": metric.get("nearest_pose_name"),
                        "nearest_pose_index": metric.get("nearest_pose_index"),
                        "nearest_pose_dist_mm": metric.get("nearest_pose_dist_mm"),
                        "axis_signed_dist_mm": metric.get("axis_signed_dist_mm"),
                        "axis_abs_dist_mm": metric.get("axis_abs_dist_mm"),
                        "axis_proj_mm": metric.get("axis_proj_mm"),
                        "structural_status": ("repeat_action3_probe" if repeat_mode else metric.get("structural_status", "candidate")),
                        "structural_line_id": metric.get("structural_line_id"),
                        "structural_reason": (f"A102 non-consecutive repeat ACTION3 track#{repeat_track.get('id')}" if repeat_mode else metric.get("structural_reason", "")),
                    }
                    item = {
                        "kind": "wrinkle",
                        "score": float(metric.get("score", 0.0)),
                        "arm_key": arm_key,
                        "problem_board_xy": [float(hot_board[0]), float(hot_board[1])],
                        "start_board_xy": [float(grasp[0]), float(grasp[1])],
                        "end_board_xy": [float(end[0]), float(end[1])],
                        "problem_px": [float(hot_px[0]), float(hot_px[1])],
                        "start_px": None if sp is None else [float(sp[0]), float(sp[1])],
                        "end_px": None if ep is None else [float(ep[0]), float(ep[1])],
                        "local_mask_ratio": float(local),
                        "inset_mm": float(inset_mm),
                        "reason": ((f"A102 repeated-ACTION3 one-arm diagnostic: hottest point -> first garment boundary "
                                    f"radius={radius:.1f}mm, grasp={inset_mm:.1f}mm inward, pull={actual_pull:.1f}mm outward, one arm={arm_key.upper()}, track#{repeat_track.get('id')}")
                                   if repeat_mode else
                                   (f"A98 structural-candidate radial probe: hottest point -> first garment boundary "
                                    f"radius={radius:.1f}mm, grasp={inset_mm:.1f}mm inward, pull={actual_pull:.1f}mm outward, one arm={arm_key.upper()}")),
                        "extra": exmeta,
                    }
                    return item, "OK"
                return None, (f"no safe {inset_mm:.0f}mm-inward/{pull_mm:.0f}mm-outward radial probe near first boundary "
                              f"radius={first_radius:.1f}mm min_local={min_local:.2f}")
            except Exception as e:
                return None, f"radial probe error: {repr(e)}"

        def _try_gradient_side(metric: Dict[str, Any], sign: float) -> Optional[Dict[str, Any]]:
            p = np.asarray(metric["problem_board"], dtype=np.float32).reshape(2)
            u = np.asarray(metric["grad_board"], dtype=np.float32).reshape(2) * float(sign)
            un = _unit_or_none(u)
            if un is None:
                return None
            pull_arm = _pulling_arm_for_direction(un)
            best = None
            extra_offset_mm = float(max(0.0, getattr(args, "auto_x_action3_contact_extra_offset_mm", 5.0)))
            edge_inset_mm = float(max(0.0, getattr(args, "auto_x_action3_contact_edge_inset_mm", 10.0)))
            edge_dt = cv2.distanceTransform((mask_u8 > 0).astype(np.uint8), cv2.DIST_L2, 5)
            start_i = int(max(0, math.ceil(min_contact_offset_mm / step_mm)))
            max_i = int(max(start_i, math.ceil(search_max_mm / step_mm)))
            used_offsets = set()
            for i in range(start_i, max_i + 1):
                legacy_d = float(i) * step_mm
                requested_d = legacy_d + extra_offset_mm
                safe = _a146_action3_max_safe_contact_offset(
                    p, un, requested_d, edge_inset_mm, mask_u8, latest_H, edge_dt)
                if not isinstance(safe, dict):
                    continue
                d = float(safe.get("offset_mm", 0.0))
                d_key = int(round(d * 10.0))
                if d_key in used_offsets:
                    continue
                used_offsets.add(d_key)
                sb_raw = np.asarray(safe["point"], dtype=np.float32)
                sx, sy = _targeted_clamp_board_xy(float(sb_raw[0]), float(sb_raw[1]))
                workspace_arm = select_arm_for_board_x(cfg, sx)
                if workspace_arm is None:
                    continue
                # The chosen robot must pull the cloth toward itself.  If the start point
                # can only be reached by the opposite arm, this side would be a pushing motion.
                if pull_arm is not None and workspace_arm != pull_arm:
                    continue
                arm_key = workspace_arm if pull_arm is None else pull_arm
                local_ratio = _targeted_mask_ratio_at_board(mask_u8, sx, sy)
                if local_ratio < local_min:
                    continue
                ex_raw = np.array([sx, sy], dtype=np.float32) + un * sweep_dist
                ex, ey = _targeted_clamp_board_xy(float(ex_raw[0]), float(ex_raw[1]))
                actual_vec = np.array([ex - sx, ey - sy], dtype=np.float32)
                forward_mm = float(np.dot(actual_vec, un))
                sweep_len = float(np.linalg.norm(actual_vec))
                if sweep_len < min_sweep or forward_mm < max(min_sweep * 0.75, 12.0):
                    continue
                nearest_dist, nearest_side = _nearest_board_side_distance_mm(sx, sy)
                q = (-abs(d - (preferred_contact_offset_mm + extra_offset_mm))
                     + 35.0 * float(local_ratio)
                     + 0.08 * sweep_len
                     + 0.18 * float(nearest_dist))
                cand_side = {
                    "arm_key": arm_key,
                    "workspace_arm": workspace_arm,
                    "pull_arm": pull_arm,
                    "start": np.array([sx, sy], dtype=np.float32),
                    "end": np.array([ex, ey], dtype=np.float32),
                    "u": un.astype(np.float32),
                    "search_offset_mm": float(d),
                    "legacy_search_offset_mm": float(legacy_d),
                    "requested_search_offset_mm": float(requested_d),
                    "action3_extra_offset_mm": float(extra_offset_mm),
                    "action3_edge_inset_mm": float(edge_inset_mm),
                    "edge_limited": bool(safe.get("edge_limited", False)),
                    "edge_depth_mm": float(safe.get("edge_depth_mm", 0.0)),
                    "local_ratio": float(local_ratio),
                    "sweep_len": float(sweep_len),
                    "forward_mm": float(forward_mm),
                    "nearest_side_dist_mm": float(nearest_dist),
                    "nearest_side_name": str(nearest_side),
                    "quality": float(q),
                }
                if best is None or cand_side["quality"] > best["quality"]:
                    best = cand_side
            return best

        metrics = []
        for wc in cnts:
            m = _component_metrics(wc)
            if m is not None:
                metrics.append(m)
        if not metrics:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A72 action3: no valid heatmap components after filtering"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        filtered_metrics = []
        structural_skipped = 0
        structural_demoted = 0
        recovery_candidates_reopened = 0
        repeat_cycle_blocked = 0
        # Strong Recovery must use the ordinary pre-Late ACTION3 planner.
        # Candidate lines created/demoted in the stalled Late visit are therefore
        # re-observed as executable wrinkles, while older confirmed ignored lines
        # remain protected. Diagnostic repeat/radial probes are suppressed here.
        recovery_mode = bool(_a150_late_phase() == "STRONG_RECOVERY")
        for m in metrics:
            try:
                nb = _auto_x_nearest_pose_keypoint_to_board(m.get("component_center_board", m.get("problem_board")))
                m["nearest_pose_name"] = nb.get("name")
                m["nearest_pose_index"] = nb.get("index")
                m["nearest_pose_dist_mm"] = nb.get("dist_mm")
                sig = _auto_x_structural_signature_for_component(m)
                if isinstance(sig, dict):
                    m["axis_signed_dist_mm"] = sig.get("signed_axis_dist_mm")
                    m["axis_proj_mm"] = sig.get("axis_proj_mm")
                    m["axis_abs_dist_mm"] = sig.get("abs_axis_dist_mm")
                st = _auto_x_structural_status_for_component(m)
                m["structural_status"] = st.get("status", "none")
                m["structural_line_id"] = st.get("line_id")
                m["structural_reason"] = st.get("reason", "")
                # an AMBIGUOUS repeat-probe result may reset this exact
                # component as the new baseline, but it must not immediately be
                # selected for a normal ACTION3 in the same X/observe generation.
                cycle_block_track = None if recovery_mode else _auto_x_repeat_action3_current_cycle_block_track_for_component(m)
                if isinstance(cycle_block_track, dict):
                    repeat_cycle_blocked += 1
                    m["repeat_action3_ambiguous_cycle_blocked"] = True
                    m["repeat_action3_track_id"] = cycle_block_track.get("id")
                    print(f"[A104-REPEAT-A3-CYCLE-BLOCK] skip normal ACTION3 component len={float(m.get('major_len_mm',0.0) or 0.0):.1f}mm area={float(m.get('area_px',0.0) or 0.0):.0f}px track#{cycle_block_track.get('id')} generation={int(auto_x_structural_line_memory.get('observe_generation',0) or 0)}")
                    continue
                repeat_track = None
                if (not recovery_mode) and st.get("status") not in ("candidate", "ignored"):
                    if (float(m.get("major_len_mm", 0.0) or 0.0) >= float(getattr(args, "auto_x_action3_candidate_len_mm", 80.0))
                        and float(m.get("major_ratio", 1.0) or 1.0) >= float(getattr(args, "auto_x_action3_candidate_aspect_ratio", 2.70))):
                        repeat_track = _auto_x_repeat_action3_probe_track_for_component(m)
                if isinstance(repeat_track, dict):
                    m["repeat_action3_probe_due"] = True
                    m["repeat_action3_track_id"] = repeat_track.get("id")
                    m["_repeat_action3_track"] = repeat_track
                if st.get("status") == "ignored":
                    structural_skipped += 1
                    continue
                if st.get("status") == "candidate":
                    if recovery_mode:
                        recovery_candidates_reopened += 1
                        m["structural_status"] = "recovery_candidate"
                        m["a150_recovery_candidate_as_wrinkle"] = True
                    else:
                        structural_demoted += 1
                        mult = float(np.clip(getattr(args, "auto_x_structural_candidate_score_multiplier", 0.30), 0.05, 1.0))
                        m["score"] = float(m.get("score", 0.0)) * mult
                        m["structural_demoted"] = True
                filtered_metrics.append(m)
            except Exception:
                filtered_metrics.append(m)
        metrics = filtered_metrics
        if print_result and (structural_skipped or structural_demoted or recovery_candidates_reopened or repeat_cycle_blocked):
            print(f"[A78-STRUCTURAL-ACTION3] ignored={structural_skipped}, demoted_candidates={structural_demoted}, recovery_reopened={recovery_candidates_reopened}, ambiguous_cycle_blocked={repeat_cycle_blocked}")
            if recovery_mode:
                print("[A150-RECOVERY-PLANNER] structural candidates are treated as ordinary ACTION3 wrinkles; confirmed ignored lines remain excluded; diagnostic A98/A102 probes are disabled")
        if not metrics:
            latest_targeted_press_plan, latest_targeted_press_status = None, "A78 action3: only confirmed garment-structure lines remained after structural-shadow filtering"
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None
        metrics.sort(key=lambda m: float(m.get("score", 0.0)), reverse=True)

        # A137/B57_V2: structural candidates are deliberately score-demoted so they
        # cannot become a normal full ACTION3. Scan every such candidate for its
        # diagnostic radial plan before ordinary candidates.
        structural_probe_metrics = [m for m in metrics if str(m.get("structural_status", "none")) == "candidate"]
        ordinary_metrics = [m for m in metrics if str(m.get("structural_status", "none")) != "candidate"]
        max_normal_scan = max(1, int(getattr(args, "wrinkle_heatmap_max_candidates", 6)))

        # bug fix: qualify ordinary ACTION3 components BEFORE selecting the
        # representative executable component.  A143 selected the first reachable
        # ordinary component by the broad heat/area score and only later checked
        # len/aspect in choose_action().  A wide high-heat blob could therefore win,
        # fail the 80mm/2.70 gate, and hide a lower-scored true linear wrinkle.
        #
        # Keep structural probes completely unchanged.  For ordinary ACTION3:
        #   1) scan every strong-qualified component in the existing score order;
        #   2) if none is executable, fall back to the former ordinary top-N order.
        # The fallback preserves A3-gray/ACTION5/rejudge diagnostics and all existing
        # reachability/workspace/safety checks.
        a144_candidate_len = float(max(1.0, getattr(args, "auto_x_action3_candidate_len_mm", 80.0)))
        a144_candidate_ratio = float(max(1.0, getattr(args, "auto_x_action3_candidate_aspect_ratio", 2.70)))
        strong_ordinary_metrics = [
            m for m in ordinary_metrics
            if float(m.get("major_len_mm", 0.0) or 0.0) >= a144_candidate_len
            and float(m.get("major_ratio", 1.0) or 1.0) >= a144_candidate_ratio
        ]
        strong_ids = {id(m) for m in strong_ordinary_metrics}
        fallback_ordinary_metrics = [m for m in ordinary_metrics if id(m) not in strong_ids]
        for m in strong_ordinary_metrics:
            m["_a144_action3_selection_pool"] = "strong_qualified"
        for m in fallback_ordinary_metrics:
            m["_a144_action3_selection_pool"] = "ordinary_fallback"
        for m in structural_probe_metrics:
            m["_a144_action3_selection_pool"] = "structural_probe"

        ordinary_ordered_metrics = strong_ordinary_metrics + fallback_ordinary_metrics[:max_normal_scan]
        ordered_metrics = (
            structural_probe_metrics + ordinary_ordered_metrics
            if bool(include_structural_probe_candidates)
            else ordinary_ordered_metrics
        )
        if auto_x_debug_logger.is_active():
            print(
                "[LONG-PULL-DIAG-CANDIDATES] "
                f"structural={len(structural_probe_metrics)} strong={len(strong_ordinary_metrics)} "
                f"fallback={len(fallback_ordinary_metrics)} scanned={len(ordered_metrics)} "
                f"ordinary_scan_cap={max_normal_scan} include_structural={bool(include_structural_probe_candidates)} "
                f"thresholds={a144_candidate_len:.1f}mm/{a144_candidate_ratio:.2f}"
            )
        if print_result:
            if structural_probe_metrics:
                mode_txt = "scanned before" if bool(include_structural_probe_candidates) else "excluded; ordinary-only scan"
                print(f"[B57_V2-STATIC-PROBE-PRIORITY] candidate_lines={len(structural_probe_metrics)} {mode_txt} normal_top={max_normal_scan}")
            print(
                f"[A144-A3-QUALIFIED-FIRST] strong={len(strong_ordinary_metrics)} "
                f"fallback={len(fallback_ordinary_metrics)} thresholds="
                f"{a144_candidate_len:.1f}mm/{a144_candidate_ratio:.2f}; "
                f"strong candidates are path-tested before the legacy ordinary fallback"
            )

        selected_item = None
        selected_metric = None
        blocked_notes: List[str] = []
        for m in ordered_metrics:
            if (str(m.get("structural_status", "none")) == "candidate"
                    and not bool(getattr(args, "auto_x_structural_candidate_radial_probe", True))):
                blocked_notes.append(
                    f"structural candidate line_id={m.get('structural_line_id')}: radial probe disabled; normal full ACTION3 prohibited"
                )
                continue
            if str(m.get("structural_status", "none")) == "candidate" and bool(getattr(args, "auto_x_structural_candidate_radial_probe", True)):
                radial_item, radial_reason = _build_structural_candidate_radial_probe_item(m)
                if radial_item is not None:
                    selected_item = radial_item
                    selected_metric = m
                    if print_result:
                        exr = radial_item.get("extra", {})
                        hb = exr.get("structural_probe_hot_board_xy", [0.0, 0.0])
                        eb = exr.get("structural_probe_boundary_board_xy", [0.0, 0.0])
                        gb = radial_item.get("start_board_xy", [0.0, 0.0])
                        ee = radial_item.get("end_board_xy", [0.0, 0.0])
                        print(f"[A98-STRUCTURAL-RADIAL-PROBE] line_id={m.get('structural_line_id')} hot=({hb[0]:.1f},{hb[1]:.1f}) "
                              f"boundary=({eb[0]:.1f},{eb[1]:.1f}) radius={float(exr.get('structural_probe_circle_radius_mm',0.0)):.1f}mm "
                              f"grasp=({gb[0]:.1f},{gb[1]:.1f}) inset={float(exr.get('structural_probe_inset_mm',15.0)):.1f}mm "
                              f"end=({ee[0]:.1f},{ee[1]:.1f}) pull={float(exr.get('structural_probe_pull_mm',25.0)):.1f}mm arm={radial_item.get('arm_key','?').upper()}")
                    break
                blocked_notes.append(f"structural candidate line_id={m.get('structural_line_id')}: {radial_reason}")
                # A structural candidate must not silently fall back to the normal
                # two-arm pull; that would defeat the diagnostic motion requested here.
                continue
            repeat_track = m.get("_repeat_action3_track") if isinstance(m.get("_repeat_action3_track"), dict) else None
            if isinstance(repeat_track, dict) and bool(m.get("repeat_action3_probe_due", False)):
                radial_item, radial_reason = _build_structural_candidate_radial_probe_item(m, repeat_track=repeat_track)
                if radial_item is not None:
                    selected_item = radial_item
                    selected_metric = m
                    if print_result:
                        exr = radial_item.get("extra", {})
                        gb = radial_item.get("start_board_xy", [0.0, 0.0])
                        ee = radial_item.get("end_board_xy", [0.0, 0.0])
                        print(f"[A102-REPEAT-A3-PROBE] track#{repeat_track.get('id')} len={float(m.get('major_len_mm',0.0)):.1f}mm area={float(m.get('area_px',0.0)):.0f}px "
                              f"axis=({float(m.get('axis_signed_dist_mm',0.0) or 0.0):+.1f},{float(m.get('axis_proj_mm',0.0) or 0.0):.1f}) "
                              f"grasp=({gb[0]:.1f},{gb[1]:.1f}) -> end=({ee[0]:.1f},{ee[1]:.1f}) pull={float(exr.get('structural_probe_pull_mm',20.0)):.1f}mm")
                    break
                blocked_notes.append(f"repeat ACTION3 track#{repeat_track.get('id')}: {radial_reason}")
                # Do not fall through to a second full ACTION3 when its diagnostic
                # one-arm path is unsafe. A fresh X can try again.
                continue
            sides = []
            for sg in (1.0, -1.0):
                side = _try_gradient_side(m, sg)
                if side is not None:
                    sides.append(side)
            if not sides:
                blocked_notes.append(f"len={m['major_len_mm']:.1f}mm ratio={m['major_ratio']:.2f} grad={m['grad_mag']:.1f}: no reachable gradient contact")
                continue
            side = max(sides, key=lambda z: (float(z.get("nearest_side_dist_mm", 0.0)),
                                             float(z.get("local_ratio", 0.0)),
                                             float(z.get("quality", 0.0))))
            sx, sy = float(side["start"][0]), float(side["start"][1])
            ex, ey = float(side["end"][0]), float(side["end"][1])
            sp = board_to_pixel(latest_H, sx, sy)
            ep = board_to_pixel(latest_H, ex, ey)
            gpx = m.get("grad_px_xy", [0.0, 0.0])
            item = {
                "kind": "wrinkle",
                "score": float(m["score"]),
                "arm_key": str(side["arm_key"]),
                "problem_board_xy": [float(m["problem_board"][0]), float(m["problem_board"][1])],
                "start_board_xy": [sx, sy],
                "end_board_xy": [ex, ey],
                "problem_px": [float(gpx[0]), float(gpx[1])],
                "start_px": None if sp is None else [float(sp[0]), float(sp[1])],
                "end_px": None if ep is None else [float(ep[0]), float(ep[1])],
                "local_mask_ratio": float(side["local_ratio"]),
                "inset_mm": float(side["search_offset_mm"]),
                "reason": (f"A72 dominant-long-gradient wrinkle: heat max={m['max_heat']:.1f} mean={m['mean_heat']:.1f} "
                           f"area={m['area_px']:.0f}px len={m['major_len_mm']:.1f}mm ratio={m['major_ratio']:.2f} "
                           f"grad={m['grad_mag']:.1f} start_offset={side['search_offset_mm']:.1f}mm "
                           f"nearest_side={side.get('nearest_side_name','?')}:{side.get('nearest_side_dist_mm',0.0):.1f}mm "
                           f"sweep={side['sweep_len']:.1f}mm dir=gradient_pull_toward_{side.get('arm_key','?').upper()}"),
                "extra": {
                    "area_px": float(m["area_px"]),
                    "heat_max": float(m["max_heat"]),
                    "heat_mean": float(m["mean_heat"]),
                    "heat_sum": float(m["sum_heat"]),
                    "max_score": float(m["max_heat"]),
                    "mean_score": float(m["mean_heat"]),
                    "major_ratio": float(m["major_ratio"]),
                    "major_len_mm": float(m["major_len_mm"]),
                    "gradient_mag": float(m["grad_mag"]),
                    "gradient_note": str(m["grad_note"]),
                    "direction_board": [float(side["u"][0]), float(side["u"][1])],
                    "direction_reason": "A71_max_heatmap_gradient_direction",
                    "action3_gradient": True,
                    "wrinkle_axis_board": [float(m.get("major_board_unit", np.array([0.0, 1.0], dtype=np.float32))[0]), float(m.get("major_board_unit", np.array([0.0, 1.0], dtype=np.float32))[1])],
                    "wrinkle_axis_endpoints": m.get("major_board_endpoints"),
                    "wrinkle_problem_board_xy": [float(m["problem_board"][0]), float(m["problem_board"][1])],
                    "sweep_len_preview_mm": float(side["sweep_len"]),
                    "base_sweep_dist_mm": float(base_sweep_dist),
                    "sweep_extra_mm": float(sweep_extra_mm),
                    "search_offset_mm": float(side["search_offset_mm"]),
                    "legacy_search_offset_mm": float(side.get("legacy_search_offset_mm", side["search_offset_mm"])),
                    "requested_search_offset_mm": float(side.get("requested_search_offset_mm", side["search_offset_mm"])),
                    "action3_extra_offset_mm": float(side.get("action3_extra_offset_mm", 5.0)),
                    "action3_edge_inset_mm": float(side.get("action3_edge_inset_mm", 10.0)),
                    "edge_limited": bool(side.get("edge_limited", False)),
                    "edge_depth_mm": float(side.get("edge_depth_mm", 0.0)),
                    "min_contact_offset_mm": float(min_contact_offset_mm),
                    "preferred_contact_offset_mm": float(preferred_contact_offset_mm),
                    "nearest_side_dist_mm": float(side.get("nearest_side_dist_mm", 0.0)),
                    "nearest_side_name": str(side.get("nearest_side_name", "?")),
                    "pull_arm": str(side.get("pull_arm", side.get("arm_key", "?"))),
                    "workspace_arm": str(side.get("workspace_arm", side.get("arm_key", "?"))),
                    "forward_mm": float(side.get("forward_mm", side.get("sweep_len", 0.0))),
                    "edge_pull_mode": False,
                    "nearest_pose_name": m.get("nearest_pose_name"),  # log only in A94
                    "nearest_pose_index": m.get("nearest_pose_index"),
                    "nearest_pose_dist_mm": m.get("nearest_pose_dist_mm"),
                    "axis_signed_dist_mm": m.get("axis_signed_dist_mm"),
                    "axis_abs_dist_mm": m.get("axis_abs_dist_mm"),
                    "axis_proj_mm": m.get("axis_proj_mm"),
                    "structural_status": m.get("structural_status", "none"),
                    "structural_line_id": m.get("structural_line_id"),
                    "structural_reason": m.get("structural_reason", ""),
                    "action3_selection_pool": str(m.get("_a144_action3_selection_pool", "legacy")),
                    "action3_qualified_before_selection": bool(
                        str(m.get("_a144_action3_selection_pool", "")) == "strong_qualified"
                    ),
                }
            }
            selected_item = item
            selected_metric = m
            break

        if selected_item is None:
            latest_targeted_press_plan = None
            latest_targeted_press_status = "A72 action3: no executable gradient pull candidate | " + " | ".join(blocked_notes[-3:])
            if auto_x_debug_logger.is_active():
                print(
                    "[LONG-PULL-DIAG-PREVIEW] result=NONE stage=gradient_contact "
                    f"tested={len(ordered_metrics)} blocked_count={len(blocked_notes)} "
                    f"blocked_tail={' || '.join(str(x) for x in blocked_notes[-6:]) or 'NONE'}"
                )
            if print_result:
                print(f"[ACTION3-GRADIENT] {latest_targeted_press_status}")
            return None

        _selected_extra = selected_item.get("extra", {}) if isinstance(selected_item.get("extra", {}), dict) else {}
        _is_structural_radial = bool(_selected_extra.get("structural_candidate_radial_probe", False))
        _is_repeat_a3_radial = bool(_selected_extra.get("repeat_action3_outward_probe", False))
        latest_targeted_press_plan = {
            "candidates": [selected_item],
            "status": "OK",
            "source_class": str(cand.get("class_name", "?")) if isinstance(cand, dict) else "?",
            "solidity": float(feat.get("solidity", 1.0) or 1.0),
            "center_board": [float(center_board[0]), float(center_board[1])],
            "summary": (("A102 repeated-ACTION3 one-arm 20mm outward diagnostic probe "
                         if _is_repeat_a3_radial else
                         ("A98 ACTION3 structural-candidate one-arm radial boundary probe "
                          if _is_structural_radial else
                          "A144 action3 gradient preview: strong-qualified-first component selection "))
                        + f"pool={selected_metric.get('_a144_action3_selection_pool','legacy')} "
                        + f"len={selected_metric['major_len_mm']:.1f}mm ratio={selected_metric['major_ratio']:.2f} "
                        + (f"radius={float(_selected_extra.get('structural_probe_circle_radius_mm',0.0)):.1f}mm"
                           if _is_structural_radial else f"grad={selected_metric['grad_mag']:.1f}")),
        }
        latest_targeted_press_status = "OK"
        if auto_x_debug_logger.is_active():
            _lp_ex = selected_item.get("extra", {}) if isinstance(selected_item.get("extra", {}), dict) else {}
            print(
                "[LONG-PULL-DIAG-PREVIEW] result=READY "
                f"pool={selected_metric.get('_a144_action3_selection_pool','legacy')} "
                f"len_mm={float(selected_metric.get('major_len_mm',0.0) or 0.0):.1f} "
                f"ratio={float(selected_metric.get('major_ratio',1.0) or 1.0):.2f} "
                f"grad={float(selected_metric.get('grad_mag',0.0) or 0.0):.1f} "
                f"struct={selected_metric.get('structural_status','none')} "
                f"arm={selected_item.get('arm_key','?')} "
                f"sweep_mm={float(_lp_ex.get('sweep_len_preview_mm',0.0) or 0.0):.1f}"
            )
        if print_result:
            print("\n========== ACTION3 GRADIENT WRINKLE PREVIEW (A72) ==========")
            print(latest_targeted_press_plan["summary"])
            if bool(selected_item.get("extra", {}).get("repeat_action3_outward_probe", False)):
                print("A102 repeat-ACTION3 probe: one arm only; hottest point -> nearest garment boundary -> inward grasp -> 20mm outward pull. Next X compares area, length, and pose-relative position only.")
            elif bool(selected_item.get("extra", {}).get("structural_candidate_radial_probe", False)):
                print("A98 candidate probe: one arm only; hottest point -> nearest garment boundary -> 15mm inward grasp -> 25mm outward pull.")
            else:
                print("ACTION3 uses heatmap-gradient direction. Contact is chosen near the red/hot gradient region, not by edge/vacancy ranking.")
            it = selected_item
            sxy = it.get("start_board_xy", [0, 0])
            exy = it.get("end_board_xy", [0, 0])
            pxy = it.get("problem_board_xy", [0, 0])
            exm = it.get("extra", {})
            print(f"01. {it.get('arm_key','?').upper()} problem=({pxy[0]:.1f},{pxy[1]:.1f}) "
                  f"press=({sxy[0]:.1f},{sxy[1]:.1f}) -> end=({exy[0]:.1f},{exy[1]:.1f}) "
                  f"heat_max={float(exm.get('heat_max',0)):.1f} len={float(exm.get('major_len_mm',0)):.1f}mm "
                  f"ratio={float(exm.get('major_ratio',1)):.2f} grad={float(exm.get('gradient_mag',0)):.1f} "
                  f"offset={float(exm.get('search_offset_mm',0)):.1f}mm sweep={float(exm.get('sweep_len_preview_mm',0)):.1f}mm "
                  f"near_side={exm.get('nearest_side_name','?')}:{float(exm.get('nearest_side_dist_mm',0)):.1f}mm "
                  f"pull_arm={exm.get('pull_arm','?')} local={float(it.get('local_mask_ratio',0)):.2f}")
            print("===========================================================\n")
        return latest_targeted_press_plan

    def _a135_point_to_segment_distance_board(point_xy: Any, start_xy: Any, end_xy: Any) -> float:
        try:
            p0 = np.asarray(point_xy, dtype=np.float32).reshape(2)
            a0 = np.asarray(start_xy, dtype=np.float32).reshape(2)
            b0 = np.asarray(end_xy, dtype=np.float32).reshape(2)
            ab = b0 - a0
            den = float(np.dot(ab, ab))
            if den <= 1e-9:
                return float(np.linalg.norm(p0 - a0))
            t0 = float(np.clip(np.dot(p0 - a0, ab) / den, 0.0, 1.0))
            return float(np.linalg.norm(p0 - (a0 + ab * t0)))
        except Exception:
            return 0.0

    def _a135_validate_late_exact_pass(pass_obj: Dict[str, Any], require_hold: bool) -> Tuple[bool, Dict[str, Any]]:
        """Validate late exact commands before either RoArm moves.

        A145 reuses the already validated normal ACTION3 mechanism for Late Strong/Max:
        the normal builder has already enforced board/XYZ safety, center keepout, local
        cloth support, active-to-hold separation, sweep-to-hold separation, and the
        sequential hold/down/pull/clear sequence.  Re-applying A135 natural-side and
        split-margin checks here contradicted that soft-workspace design and rejected
        otherwise executable ACTION3 pairs.  Other late exact actions retain the
        conservative A135 natural-workspace preflight below.
        """
        diag: Dict[str, Any] = {"status": "BLOCKED", "reason_code": "UNKNOWN", "blocked_notes": []}
        if not isinstance(pass_obj, dict):
            diag["reason_code"] = "INVALID_PASS_OBJECT"
            return False, diag
        cand = pass_obj.get("candidate") if isinstance(pass_obj.get("candidate"), dict) else {}
        ex = cand.get("extra") if isinstance(cand.get("extra"), dict) else {}
        if not bool(ex.get("a133_late_exact", False)):
            return True, {"status": "NOT_LATE_EXACT", "reason_code": "NOT_APPLICABLE", "blocked_notes": []}
        arm_key = str(pass_obj.get("arm_key", cand.get("arm_key", "")))
        try:
            start = np.array([
                float(pass_obj.get("down", {}).get("bx", cand.get("start_board_xy", [None, None])[0])),
                float(pass_obj.get("down", {}).get("by", cand.get("start_board_xy", [None, None])[1])),
            ], dtype=np.float32)
            end = np.array([
                float(pass_obj.get("sweep", {}).get("bx", cand.get("end_board_xy", [None, None])[0])),
                float(pass_obj.get("sweep", {}).get("by", cand.get("end_board_xy", [None, None])[1])),
            ], dtype=np.float32)
        except Exception as e:
            diag.update({"reason_code": "INVALID_ACTIVE_BOARD_PATH", "blocked_notes": [repr(e)]})
            return False, diag
        if arm_key not in ("arm1", "arm2") or not np.all(np.isfinite(start)) or not np.all(np.isfinite(end)):
            diag.update({"reason_code": "INVALID_ACTIVE_ARM_OR_PATH", "active_arm": arm_key,
                         "start_board_xy": start.tolist(), "end_board_xy": end.tolist()})
            return False, diag

        # Late Strong/Max are physically the same two-arm ACTION3 primitive as
        # normal ACTION3.  build_targeted_press_motion_plan() has already produced an
        # executable active path and passive hold using the normal soft-workspace /
        # fallback-hold safety mechanism.  Do not invalidate that certified plan by
        # re-imposing the old left/right natural split or Late-only 35 mm margin.
        late_action_name = str(ex.get("a133_action", ""))
        reuse_normal_action3 = bool(
            require_hold
            and late_action_name in {"LATE_CCA_STRONG_ACTION3", "LATE_CCA_MAX_LINEAR_ACTION3"}
        )
        if reuse_normal_action3:
            hold = pass_obj.get("hold") if isinstance(pass_obj.get("hold"), dict) else None
            if hold is None:
                diag.update({"reason_code": "PASSIVE_HOLD_MISSING"})
                return False, diag
            hold_arm = str(hold.get("arm_key", ""))
            hb = hold.get("hold_board_xy")
            if (hold_arm not in ("arm1", "arm2") or hold_arm == arm_key
                    or not isinstance(hb, (list, tuple, np.ndarray)) or len(hb) < 2):
                diag.update({"reason_code": "INVALID_HOLD_ARM_OR_POINT",
                             "hold_arm": hold_arm, "hold_board_xy": hb})
                return False, diag
            hold_pt = np.asarray(hb, dtype=np.float32).reshape(2)
            if not np.all(np.isfinite(hold_pt)):
                diag.update({"reason_code": "INVALID_HOLD_BOARD_POINT",
                             "hold_board_xy": hold_pt.tolist()})
                return False, diag
            pair_start = float(np.linalg.norm(start - hold_pt))
            pair_end = float(np.linalg.norm(end - hold_pt))
            path_dist = _a135_point_to_segment_distance_board(hold_pt, start, end)
            return True, {
                "status": "OK",
                "reason_code": "A145_NORMAL_ACTION3_MECHANISM_REUSED",
                "action": late_action_name,
                "active_arm": arm_key,
                "hold_arm": hold_arm,
                "start_board_xy": start.tolist(),
                "end_board_xy": end.tolist(),
                "hold_board_xy": hold_pt.tolist(),
                "pair_start_mm": pair_start,
                "pair_end_mm": pair_end,
                "path_to_hold_mm": path_dist,
                "soft_workspace": bool(hold.get("soft_workspace", False)),
                "fallback_mode": bool(hold.get("fallback_mode", False)),
                "blocked_notes": [
                    "normal ACTION3 builder safety accepted",
                    "Late natural-side/split-margin duplicate check bypassed",
                ],
            }

        natural_start = select_arm_for_board_x(cfg, float(start[0]))
        natural_end = select_arm_for_board_x(cfg, float(end[0]))
        if natural_start != arm_key or natural_end != arm_key:
            diag.update({"reason_code": "ACTIVE_PATH_CROSSES_NATURAL_WORKSPACE",
                         "active_arm": arm_key, "natural_start": natural_start, "natural_end": natural_end,
                         "start_board_xy": start.tolist(), "end_board_xy": end.tolist()})
            return False, diag
        split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
        margin = float(max(0.0, getattr(args, "auto_x_late_hold_split_margin_mm", 35.0)))
        if arm_key == "arm2" and max(float(start[0]), float(end[0])) > split_x - margin:
            diag.update({"reason_code": "ARM2_PATH_TOO_CLOSE_TO_SPLIT", "split_x": split_x, "margin": margin,
                         "start_board_xy": start.tolist(), "end_board_xy": end.tolist()})
            return False, diag
        if arm_key == "arm1" and min(float(start[0]), float(end[0])) < split_x + margin:
            diag.update({"reason_code": "ARM1_PATH_TOO_CLOSE_TO_SPLIT", "split_x": split_x, "margin": margin,
                         "start_board_xy": start.tolist(), "end_board_xy": end.tolist()})
            return False, diag
        hold = pass_obj.get("hold") if isinstance(pass_obj.get("hold"), dict) else None
        if not require_hold:
            if hold is not None:
                diag.update({"reason_code": "UNEXPECTED_HOLD_ON_SINGLE_ARM_LATE_ACTION"})
                return False, diag
            return True, {"status": "OK", "reason_code": "SAFE_SINGLE_ARM_NATURAL_WORKSPACE",
                          "active_arm": arm_key, "start_board_xy": start.tolist(), "end_board_xy": end.tolist(),
                          "blocked_notes": []}
        if hold is None:
            diag.update({"reason_code": "PASSIVE_HOLD_MISSING"})
            return False, diag
        if bool(getattr(args, "auto_x_late_hold_require_soft_workspace", True)) and not bool(hold.get("soft_workspace", False)):
            diag.update({"reason_code": "HOLD_NOT_SOFT_WORKSPACE_CERTIFIED"})
            return False, diag
        if bool(hold.get("fallback_mode", False)) and not bool(getattr(args, "auto_x_late_hold_allow_fallback", False)):
            diag.update({"reason_code": "FALLBACK_HOLD_FORBIDDEN"})
            return False, diag
        hold_arm = str(hold.get("arm_key", ""))
        hb = hold.get("hold_board_xy")
        if hold_arm not in ("arm1", "arm2") or hold_arm == arm_key or not isinstance(hb, (list, tuple, np.ndarray)) or len(hb) < 2:
            diag.update({"reason_code": "INVALID_HOLD_ARM_OR_POINT", "hold_arm": hold_arm, "hold_board_xy": hb})
            return False, diag
        hold_pt = np.asarray(hb, dtype=np.float32).reshape(2)
        natural_hold = select_arm_for_board_x(cfg, float(hold_pt[0]))
        if natural_hold != hold_arm:
            diag.update({"reason_code": "HOLD_CROSSES_NATURAL_WORKSPACE", "hold_arm": hold_arm,
                         "natural_hold": natural_hold, "hold_board_xy": hold_pt.tolist()})
            return False, diag
        if hold_arm == "arm2" and float(hold_pt[0]) > split_x - margin:
            diag.update({"reason_code": "ARM2_HOLD_TOO_CLOSE_TO_SPLIT", "hold_board_xy": hold_pt.tolist()})
            return False, diag
        if hold_arm == "arm1" and float(hold_pt[0]) < split_x + margin:
            diag.update({"reason_code": "ARM1_HOLD_TOO_CLOSE_TO_SPLIT", "hold_board_xy": hold_pt.tolist()})
            return False, diag
        pair_start = float(np.linalg.norm(start - hold_pt))
        pair_end = float(np.linalg.norm(end - hold_pt))
        xsep_start = abs(float(start[0] - hold_pt[0]))
        xsep_end = abs(float(end[0] - hold_pt[0]))
        path_dist = _a135_point_to_segment_distance_board(hold_pt, start, end)
        min_pair = float(max(1.0, getattr(args, "auto_x_late_hold_min_pair_distance_mm", 140.0)))
        min_xsep = float(max(1.0, getattr(args, "auto_x_late_hold_min_x_separation_mm", 110.0)))
        min_path = float(max(1.0, getattr(args, "auto_x_late_hold_min_path_distance_mm", 120.0)))
        notes = [f"pair_start={pair_start:.1f}", f"pair_end={pair_end:.1f}",
                 f"xsep_start={xsep_start:.1f}", f"xsep_end={xsep_end:.1f}", f"path_dist={path_dist:.1f}"]
        if min(pair_start, pair_end) < min_pair:
            diag.update({"reason_code": "LATE_PAIR_DISTANCE_TOO_SMALL", "blocked_notes": notes})
            return False, diag
        if min(xsep_start, xsep_end) < min_xsep:
            diag.update({"reason_code": "LATE_X_SEPARATION_TOO_SMALL", "blocked_notes": notes})
            return False, diag
        if path_dist < min_path:
            diag.update({"reason_code": "LATE_SWEEP_TOO_CLOSE_TO_HOLD", "blocked_notes": notes})
            return False, diag
        if float(hold.get("pair_distance_mm", 0.0) or 0.0) <= 0.0:
            diag.update({"reason_code": "PAIR_DISTANCE_CERTIFICATE_MISSING", "blocked_notes": notes})
            return False, diag
        return True, {"status": "OK", "reason_code": "SAFE_SOFT_WORKSPACE_PAIR",
                      "active_arm": arm_key, "hold_arm": hold_arm,
                      "start_board_xy": start.tolist(), "end_board_xy": end.tolist(),
                      "hold_board_xy": hold_pt.tolist(), "pair_start_mm": pair_start,
                      "pair_end_mm": pair_end, "xsep_start_mm": xsep_start,
                      "xsep_end_mm": xsep_end, "path_to_hold_mm": path_dist,
                      "blocked_notes": notes}

    def build_targeted_press_motion_plan(plan: Optional[Dict[str, Any]] = None, print_result: bool = True,
                                             execute_count_override: Optional[int] = None) -> Optional[Dict[str, Any]]:
            """Convert inset targeted press preview candidates into actual robot motion targets.

            X action is intentionally not modified here. This function only powers key 7.
            A134 also exposes a compact diagnostic record through
            ``build_targeted_press_motion_plan.last_diagnostics`` so late planning
            can report the exact stage that rejected a candidate.
            """
            build_targeted_press_motion_plan.last_diagnostics = {
                "status": "INIT", "reason_code": "INIT", "blocked_notes": [],
                "candidate_count": 0, "pass_count": 0,
            }
            preview = latest_targeted_press_plan
            source_plan = plan
            if preview is None or bool(args.targeted_press_action_fresh_snapshot):
                if bool(args.targeted_press_action_fresh_snapshot) and snapshot_mode:
                    source_plan = request_fresh_coarse_plan_and_wait(
                        reason="before targeted press execution",
                        timeout=float(args.targeted_press_action_fresh_timeout),
                    )
                preview = build_targeted_press_preview(source_plan, print_result=True)

            if preview is None:
                build_targeted_press_motion_plan.last_diagnostics = {
                    "status": "BLOCKED", "reason_code": "NO_PREVIEW_PLAN",
                    "blocked_notes": ["no targeted press preview plan"],
                    "candidate_count": 0, "pass_count": 0,
                }
                if print_result:
                    print("[TARGET-PRESS-ACTION] blocked: no targeted press preview plan")
                return None

            exec_count = max(1, int(args.targeted_press_execute_count if execute_count_override is None else execute_count_override))
            cands = list(preview.get("candidates", []))
            if not cands:
                build_targeted_press_motion_plan.last_diagnostics = {
                    "status": "BLOCKED", "reason_code": "NO_CANDIDATES",
                    "blocked_notes": ["no targeted press candidates"],
                    "candidate_count": 0, "pass_count": 0,
                }
                if print_result:
                    print("[TARGET-PRESS-ACTION] blocked: no targeted press candidates")
                return None

            clear_z = _effective_press_clear_z()
            passes = []
            min_sweep = max(0.0, float(getattr(args, "targeted_press_min_sweep_execute_mm", 20.0)))
            skip_blocked = bool(getattr(args, "targeted_press_skip_blocked_candidates", True))
            blocked_notes: List[str] = []
            hold_reject_notes: List[str] = []
            build_targeted_press_motion_plan.last_diagnostics = {
                "status": "PLANNING", "reason_code": "PLANNING",
                "blocked_notes": blocked_notes, "candidate_count": len(cands),
                "pass_count": 0, "min_sweep_mm": float(min_sweep),
            }

            def _other_arm_key(ak: str) -> Optional[str]:
                if ak == "arm1":
                    return "arm2"
                if ak == "arm2":
                    return "arm1"
                return None

            def _action3_arm_reference_board(ak: str) -> np.ndarray:
                if ak == "arm1":
                    return np.array([
                        float(getattr(args, "arm1_standby_board_x", 494.0)),
                        float(getattr(args, "arm1_standby_board_y", -245.0)),
                    ], dtype=np.float32)
                return np.array([
                    float(getattr(args, "arm2_standby_board_x", 0.0)),
                    float(getattr(args, "arm2_standby_board_y", -248.0)),
                ], dtype=np.float32)

            def _board_dist_point_to_segment(p0: np.ndarray, a0: np.ndarray, b0: np.ndarray) -> float:
                try:
                    p1 = np.asarray(p0, dtype=np.float32).reshape(2)
                    a1 = np.asarray(a0, dtype=np.float32).reshape(2)
                    b1 = np.asarray(b0, dtype=np.float32).reshape(2)
                    ab = b1 - a1
                    den = float(np.dot(ab, ab))
                    if den < 1e-6:
                        return float(np.linalg.norm(p1 - a1))
                    t = float(np.clip(float(np.dot(p1 - a1, ab) / den), 0.0, 1.0))
                    q = a1 + ab * t
                    return float(np.linalg.norm(p1 - q))
                except Exception:
                    return 0.0

            def _action3_soft_in_center_keepout(pt: np.ndarray) -> bool:
                try:
                    split_x = float(cfg.get("dual_roarm", {}).get("split_board_x", 247.0))
                    dead_half = float(getattr(args, "auto_x_action3_soft_center_keepout_half_width_mm", 55.0))
                    return bool(abs(float(np.asarray(pt, dtype=np.float32).reshape(2)[0]) - split_x) < dead_half)
                except Exception:
                    return False

            def _snap_action3_soft_point(plan0: Optional[Dict[str, Any]], desired: np.ndarray, mask0: Optional[np.ndarray]) -> Tuple[np.ndarray, float, float]:
                dx, dy = _targeted_clamp_board_xy(float(desired[0]), float(desired[1]))
                pt = np.array([dx, dy], dtype=np.float32)
                local = 1.0
                if mask0 is not None:
                    local = float(_targeted_mask_ratio_at_board(mask0, float(pt[0]), float(pt[1])))
                    min_local = float(max(0.0, getattr(args, "auto_x_action3_hold_fallback_min_local_mask_ratio", 0.03)))
                    if local < min_local and isinstance(plan0, dict):
                        snapped = _nearest_mask_board_point_any(plan0, float(pt[0]), float(pt[1]))
                        if snapped is not None:
                            sn = np.array([float(snapped[0]), float(snapped[1])], dtype=np.float32)
                            local2 = float(_targeted_mask_ratio_at_board(mask0, float(sn[0]), float(sn[1])))
                            if local2 >= local:
                                snap_dist = float(np.linalg.norm(sn - pt))
                                return sn, local2, snap_dist
                return pt, local, 0.0

            def _build_action3_soft_workspace_pair(item: Dict[str, Any], active_arm: str, requested_sweep_len: float) -> Optional[Tuple[Dict[str, Any], Dict[str, Any]]]:
                """A95 ACTION3 soft workspace pair.

                Build two symmetric cloth contact points around the detected linear wrinkle.
                The two points must be at least 60mm apart by default.  Each physical arm
                takes the nearer of the two points, but the original active-vs-passive role
                stays unchanged: active_arm sweeps; the other arm only holds.
                """
                if not bool(getattr(args, "auto_x_action3_soft_workspace_hold", True)):
                    hold_reject_notes.append("SOFT_HOLD_DISABLED")
                    return None
                if str(item.get("kind", "")) != "wrinkle":
                    hold_reject_notes.append("SOFT_HOLD_NOT_WRINKLE")
                    return None
                exmeta = item.get("extra", {}) if isinstance(item.get("extra", {}), dict) else {}
                if not bool(exmeta.get("action3_gradient", False)):
                    hold_reject_notes.append("SOFT_HOLD_NOT_ACTION3_GRADIENT")
                    return None
                hold_arm = _other_arm_key(str(active_arm))
                if hold_arm not in ("arm1", "arm2"):
                    hold_reject_notes.append("SOFT_HOLD_INVALID_OPPOSITE_ARM")
                    return None
                try:
                    problem = np.asarray(exmeta.get("wrinkle_problem_board_xy", item.get("problem_board_xy")), dtype=np.float32).reshape(2)
                    old_start = np.asarray(item.get("start_board_xy"), dtype=np.float32).reshape(2)
                except Exception:
                    hold_reject_notes.append("SOFT_HOLD_INVALID_GEOMETRY")
                    return None
                axis = _unit_or_none(exmeta.get("wrinkle_axis_board", None))
                direction = _unit_or_none(exmeta.get("direction_board", None))
                if axis is None and direction is not None:
                    axis = _unit_or_none(np.array([-float(direction[1]), float(direction[0])], dtype=np.float32))
                if direction is None:
                    if axis is not None:
                        vv = old_start - problem
                        pp = vv - axis * float(np.dot(vv, axis))
                        direction = _unit_or_none(pp)
                    if direction is None:
                        direction = _unit_or_none(old_start - problem)
                if direction is None:
                    hold_reject_notes.append("SOFT_HOLD_DIRECTION_UNAVAILABLE")
                    return None
                if axis is not None:
                    nn = direction - axis * float(np.dot(direction, axis))
                    u = _unit_or_none(nn)
                    if u is not None:
                        direction = u
                min_dist = float(max(60.0, getattr(args, "auto_x_action3_soft_pair_min_dist_mm", 100.0)))
                pref_offset = float(max(min_dist * 0.5, getattr(args, "auto_x_action3_soft_pair_offset_mm", 60.0)))
                try:
                    old_perp = old_start - problem
                    if axis is not None:
                        old_perp = old_perp - axis * float(np.dot(old_perp, axis))
                    old_perp_len = float(np.linalg.norm(old_perp))
                except Exception:
                    old_perp_len = 0.0
                base_offset = float(max(min_dist * 0.5, min(max(pref_offset, old_perp_len), 120.0)))
                extra_offset = float(max(0.0, getattr(args, "auto_x_action3_contact_extra_offset_mm", 5.0)))
                edge_inset = float(max(0.0, getattr(args, "auto_x_action3_contact_edge_inset_mm", 10.0)))
                requested_offset = float(base_offset + extra_offset)

                hold_source_plan = source_plan if isinstance(source_plan, dict) else latest_coarse_plan
                mask_for_local = None
                try:
                    cand0 = _targeted_press_source_candidate(hold_source_plan)
                    if isinstance(cand0, dict) and cand0.get("contour") is not None and cand0.get("image_shape") is not None:
                        mask_for_local = _mask_u8_from_contour(cand0.get("contour"), cand0.get("image_shape"))
                except Exception:
                    mask_for_local = None
                if mask_for_local is None:
                    hold_reject_notes.append("A146_EDGE_LIMIT_MASK_UNAVAILABLE")
                    return None
                edge_dt = cv2.distanceTransform((mask_for_local > 0).astype(np.uint8), cv2.DIST_L2, 5)
                safe_a = _a146_action3_max_safe_contact_offset(
                    problem, direction, requested_offset, edge_inset, mask_for_local, latest_H, edge_dt)
                safe_b = _a146_action3_max_safe_contact_offset(
                    problem, -direction, requested_offset, edge_inset, mask_for_local, latest_H, edge_dt)
                if not isinstance(safe_a, dict) or not isinstance(safe_b, dict):
                    hold_reject_notes.append(
                        f"A146_EDGE_INSET_UNAVAILABLE:requested={requested_offset:.1f}mm edge={edge_inset:.1f}mm")
                    if print_result:
                        print(f"[A146-ACTION3-EDGE-LIMIT] reject: no two-sided contact remaining {edge_inset:.1f}mm inside garment")
                    return None
                p_a = np.asarray(safe_a["point"], dtype=np.float32)
                p_b = np.asarray(safe_b["point"], dtype=np.float32)
                local_a = float(_targeted_mask_ratio_at_board(mask_for_local, float(p_a[0]), float(p_a[1])))
                local_b = float(_targeted_mask_ratio_at_board(mask_for_local, float(p_b[0]), float(p_b[1])))
                snap_a = float(requested_offset - float(safe_a.get("offset_mm", requested_offset)))
                snap_b = float(requested_offset - float(safe_b.get("offset_mm", requested_offset)))
                pair_dist = float(np.linalg.norm(p_a - p_b))
                if pair_dist < min_dist:
                    hold_reject_notes.append(f"SOFT_PAIR_DISTANCE_TOO_SMALL:{pair_dist:.1f}<{min_dist:.1f}")
                    if print_result:
                        print(f"[A95-ACTION3-SOFT-HOLD] reject: symmetric pair distance {pair_dist:.1f}mm < {min_dist:.1f}mm")
                    return None
                active_ref = _action3_arm_reference_board(str(active_arm))
                hold_ref = _action3_arm_reference_board(str(hold_arm))
                assign_ab = float(np.linalg.norm(p_a - active_ref) + np.linalg.norm(p_b - hold_ref))
                assign_ba = float(np.linalg.norm(p_b - active_ref) + np.linalg.norm(p_a - hold_ref))
                if assign_ab <= assign_ba:
                    active_pt, hold_pt = p_a, p_b
                    active_local, hold_local = local_a, local_b
                    active_snap, hold_snap = snap_a, snap_b
                else:
                    active_pt, hold_pt = p_b, p_a
                    active_local, hold_local = local_b, local_a
                    active_snap, hold_snap = snap_b, snap_a
                if _action3_soft_in_center_keepout(active_pt) or _action3_soft_in_center_keepout(hold_pt):
                    hold_reject_notes.append(f"SOFT_CONTACT_CENTER_KEEPOUT:active=({float(active_pt[0]):.1f},{float(active_pt[1]):.1f}),hold=({float(hold_pt[0]):.1f},{float(hold_pt[1]):.1f})")
                    if print_result:
                        print(f"[A97-ACTION3-SOFT-HOLD] reject: contact point inside center keepout zone active=({float(active_pt[0]):.1f},{float(active_pt[1]):.1f}) hold=({float(hold_pt[0]):.1f},{float(hold_pt[1]):.1f})")
                    return None
                min_local = float(max(0.0, getattr(args, "auto_x_action3_hold_fallback_min_local_mask_ratio", 0.03)))
                if min(active_local, hold_local) < min_local:
                    hold_reject_notes.append(f"SOFT_LOCAL_SUPPORT_LOW:active={active_local:.2f},hold={hold_local:.2f},min={min_local:.2f}")
                    if print_result:
                        print(f"[A95-ACTION3-SOFT-HOLD] reject: local support active={active_local:.2f} hold={hold_local:.2f} < {min_local:.2f}")
                    return None
                pull_dir = _unit_or_none(active_pt - problem)
                if pull_dir is None:
                    hold_reject_notes.append("SOFT_PULL_DIRECTION_ZERO")
                    return None
                sweep_len2 = float(max(20.0, requested_sweep_len))
                end_pt = np.array(_targeted_clamp_board_xy(float(active_pt[0] + pull_dir[0] * sweep_len2),
                                                           float(active_pt[1] + pull_dir[1] * sweep_len2)), dtype=np.float32)
                min_sweep_hold = float(max(0.0, getattr(args, "auto_x_action3_soft_min_sweep_to_hold_dist_mm", 90.0)))
                end_hold_dist = float(np.linalg.norm(end_pt - hold_pt))
                path_hold_dist = _board_dist_point_to_segment(hold_pt, active_pt, end_pt)
                if _action3_soft_in_center_keepout(end_pt):
                    hold_reject_notes.append(f"SOFT_SWEEP_END_CENTER_KEEPOUT:end=({float(end_pt[0]):.1f},{float(end_pt[1]):.1f})")
                    if print_result:
                        print(f"[A97-ACTION3-SOFT-HOLD] reject: active sweep end inside center keepout zone end=({float(end_pt[0]):.1f},{float(end_pt[1]):.1f})")
                    return None
                if min(end_hold_dist, path_hold_dist) < min_sweep_hold:
                    hold_reject_notes.append(f"SOFT_SWEEP_TOO_CLOSE_TO_HOLD:end={end_hold_dist:.1f},path={path_hold_dist:.1f},min={min_sweep_hold:.1f}")
                    if print_result:
                        print(f"[A97-ACTION3-SOFT-HOLD] reject: active sweep approaches hold too closely end_dist={end_hold_dist:.1f}mm path_dist={path_hold_dist:.1f}mm < {min_sweep_hold:.1f}mm")
                    return None
                # Build active and passive targets through the soft resolver. This bypasses
                # only the ARM1/ARM2 hard split; board and RoArm safety still apply.
                active_z = get_arm_press_z(str(active_arm))
                hold_z = get_arm_press_z(str(hold_arm))
                active_hover = resolve_board_target_for_arm_soft_action3(str(active_arm), float(active_pt[0]), float(active_pt[1]), clear_z, "A95-ACTION3-ACTIVE-CLEAR")
                active_down = resolve_board_target_for_arm_soft_action3(str(active_arm), float(active_pt[0]), float(active_pt[1]), active_z, "A95-ACTION3-ACTIVE-DOWN")
                active_sweep = resolve_board_target_for_arm_soft_action3(str(active_arm), float(end_pt[0]), float(end_pt[1]), active_z, "A95-ACTION3-ACTIVE-SWEEP")
                active_lift = resolve_board_target_for_arm_soft_action3(str(active_arm), float(end_pt[0]), float(end_pt[1]), clear_z, "A95-ACTION3-ACTIVE-LIFT")
                hold_hover = resolve_board_target_for_arm_soft_action3(str(hold_arm), float(hold_pt[0]), float(hold_pt[1]), clear_z, "A95-ACTION3-HOLD-CLEAR")
                hold_down = resolve_board_target_for_arm_soft_action3(str(hold_arm), float(hold_pt[0]), float(hold_pt[1]), hold_z, "A95-ACTION3-HOLD-DOWN")
                hold_lift = resolve_board_target_for_arm_soft_action3(str(hold_arm), float(hold_pt[0]), float(hold_pt[1]), clear_z, "A95-ACTION3-HOLD-LIFT")
                if any(v is None for v in (active_hover, active_down, active_sweep, active_lift, hold_hover, hold_down, hold_lift)):
                    missing = [name for name, val in (("active_hover",active_hover),("active_down",active_down),("active_sweep",active_sweep),("active_lift",active_lift),("hold_hover",hold_hover),("hold_down",hold_down),("hold_lift",hold_lift)) if val is None]
                    hold_reject_notes.append("SOFT_TARGET_RESOLUTION_FAILED:" + ",".join(missing))
                    if print_result:
                        print("[A95-ACTION3-SOFT-HOLD] reject: one or more soft ACTION3 targets failed board/roarm safety resolution")
                    return None
                actual_sweep = float(np.linalg.norm(np.array([active_sweep["bx"] - active_down["bx"], active_sweep["by"] - active_down["by"]], dtype=np.float32)))
                if actual_sweep < min_sweep:
                    hold_reject_notes.append(f"SOFT_EXECUTABLE_SWEEP_TOO_SHORT:{actual_sweep:.1f}<{min_sweep:.1f}")
                    if print_result:
                        print(f"[A95-ACTION3-SOFT-HOLD] reject: executable active sweep {actual_sweep:.1f}mm < {min_sweep:.1f}mm")
                    return None
                new_item = dict(item)
                new_item["start_board_xy"] = [float(active_pt[0]), float(active_pt[1])]
                new_item["end_board_xy"] = [float(end_pt[0]), float(end_pt[1])]
                new_item["local_mask_ratio"] = float(active_local)
                ex2 = dict(exmeta)
                ex2["a95_soft_workspace_action3"] = True
                ex2["a95_pair_distance_mm"] = float(pair_dist)
                ex2["a95_hold_local_mask_ratio"] = float(hold_local)
                ex2["a95_active_local_mask_ratio"] = float(active_local)
                ex2["a146_base_offset_mm"] = float(base_offset)
                ex2["a146_extra_offset_mm"] = float(extra_offset)
                ex2["a146_requested_offset_mm"] = float(requested_offset)
                ex2["a146_edge_inset_mm"] = float(edge_inset)
                ex2["a146_active_edge_limited"] = bool(active_snap > 0.5)
                ex2["a146_hold_edge_limited"] = bool(hold_snap > 0.5)
                ex2["direction_board"] = [float(pull_dir[0]), float(pull_dir[1])]
                ex2["direction_reason"] = str(ex2.get("direction_reason", "A71_max_heatmap_gradient_direction")) + "/A95_soft_symmetric_pair"
                new_item["extra"] = ex2
                hold_plan = {
                    "enabled": True,
                    "arm_key": hold_arm,
                    "active_arm_key": active_arm,
                    "desired_board_xy": [float(hold_pt[0]), float(hold_pt[1])],
                    "hold_board_xy": [float(hold_pt[0]), float(hold_pt[1])],
                    "problem_board_xy": [float(problem[0]), float(problem[1])],
                    "active_start_board_xy": [float(active_pt[0]), float(active_pt[1])],
                    "wrinkle_axis_board": None if axis is None else [float(axis[0]), float(axis[1])],
                    "local_mask_ratio": float(hold_local),
                    "snap_dist_mm": float(hold_snap),
                    "hover": hold_hover,
                    "down": hold_down,
                    "lift": hold_lift,
                    "hold_z": float(hold_z),
                    "gripper": float(getattr(args, "auto_x_action3_hold_gripper", 3.050)),
                    "quality": float((active_local + hold_local) * 50.0 + pair_dist * 0.05),
                    "fallback_mode": False,
                    "soft_workspace": True,
                    "pair_distance_mm": float(pair_dist),
                    "a146_base_offset_mm": float(base_offset),
                    "a146_extra_offset_mm": float(extra_offset),
                    "a146_requested_offset_mm": float(requested_offset),
                    "a146_edge_inset_mm": float(edge_inset),
                    "a146_edge_limited": bool(hold_snap > 0.5),
                    "a97_sweep_end_to_hold_dist_mm": float(end_hold_dist),
                    "a97_sweep_path_to_hold_dist_mm": float(path_hold_dist),
                }
                new_item["_a95_active_targets"] = {
                    "hover": active_hover,
                    "down": active_down,
                    "sweep": active_sweep,
                    "lift": active_lift,
                    "actual_sweep_len_mm": float(actual_sweep),
                }
                if print_result:
                    print(f"[A146-ACTION3-SOFT-HOLD] active={str(active_arm).upper()}@({float(active_pt[0]):.1f},{float(active_pt[1]):.1f}) "
                          f"hold={str(hold_arm).upper()}@({float(hold_pt[0]):.1f},{float(hold_pt[1]):.1f}) "
                          f"pair_dist={pair_dist:.1f}mm offset=base{base_offset:.1f}+{extra_offset:.1f} "
                          f"requested={requested_offset:.1f}mm edge>={edge_inset:.1f}mm limited=({active_snap:.1f},{hold_snap:.1f}) "
                          f"local=({active_local:.2f},{hold_local:.2f}) sweep={actual_sweep:.1f}mm")
                return new_item, hold_plan

            def _build_action3_opposite_hold(item: Dict[str, Any], active_arm: str) -> Optional[Dict[str, Any]]:
                """A76 ACTION3: passive opposite-arm anchor.

                The existing active-arm wrinkle pull is preserved.  The opposite arm is
                moved to the point symmetric to the active contact across the detected
                wrinkle axis, rests/clamps there, stays down while the active arm sweeps,
                then clears only after the active pull has finished.  Large snapping is
                rejected so the hold point remains genuinely symmetric to the wrinkle line.
                """
                if not bool(getattr(args, "auto_x_action3_opposite_hold", True)):
                    return None
                if str(item.get("kind", "")) != "wrinkle":
                    return None
                exmeta = item.get("extra", {}) if isinstance(item.get("extra", {}), dict) else {}
                if not bool(exmeta.get("action3_gradient", False)):
                    return None
                # the legacy opposite-hold fallback must obey the same
                # +5mm wrinkle clearance and 10mm garment-edge limit as the
                # primary symmetric soft pair.
                extra_offset = float(max(0.0, getattr(args, "auto_x_action3_contact_extra_offset_mm", 5.0)))
                edge_inset = float(max(0.0, getattr(args, "auto_x_action3_contact_edge_inset_mm", 10.0)))
                hold_arm = _other_arm_key(str(active_arm))
                if hold_arm not in ("arm1", "arm2"):
                    return None
                try:
                    active_start = np.asarray(item.get("start_board_xy"), dtype=np.float32).reshape(2)
                    problem = np.asarray(exmeta.get("wrinkle_problem_board_xy", item.get("problem_board_xy")), dtype=np.float32).reshape(2)
                except Exception:
                    return None
                axis = _unit_or_none(exmeta.get("wrinkle_axis_board", None))
                direction = _unit_or_none(exmeta.get("direction_board", None))
                if axis is None and direction is not None:
                    axis = _unit_or_none(np.array([-float(direction[1]), float(direction[0])], dtype=np.float32))
                if axis is None:
                    return None
                if direction is None:
                    direction = _unit_or_none(active_start - problem)
                v = active_start - problem
                along = axis * float(np.dot(v, axis))
                perp = v - along
                desired_list: List[np.ndarray] = []
                reflected = (problem + along - perp).astype(np.float32)
                if float(np.linalg.norm(perp)) >= 5.0:
                    desired_list.append(reflected)
                    for shift_mm in (18.0, -18.0, 32.0, -32.0, 55.0, -55.0):
                        desired_list.append((reflected + axis * float(shift_mm)).astype(np.float32))
                    # never silently fall back to the old single-arm behavior if
                    # a usable passive point exists on the opposite normal side.
                    if direction is not None:
                        desired_list.append((problem - direction * (45.0 + extra_offset)).astype(np.float32))
                        desired_list.append((problem - direction * (65.0 + extra_offset)).astype(np.float32))
                else:
                    if direction is not None:
                        desired_list.append((problem - direction * (45.0 + extra_offset)).astype(np.float32))
                        desired_list.append((problem - direction * (65.0 + extra_offset)).astype(np.float32))

                hold_source_plan = source_plan if isinstance(source_plan, dict) else latest_coarse_plan
                cand0 = _targeted_press_source_candidate(hold_source_plan)
                mask_for_local = None
                try:
                    if isinstance(cand0, dict) and cand0.get("contour") is not None and cand0.get("image_shape") is not None:
                        mask_for_local = _mask_u8_from_contour(cand0.get("contour"), cand0.get("image_shape"))
                except Exception:
                    mask_for_local = None
                edge_dt = None
                if mask_for_local is not None:
                    try:
                        edge_dt = cv2.distanceTransform((mask_for_local > 0).astype(np.uint8), cv2.DIST_L2, 5)
                    except Exception:
                        edge_dt = None

                def _try_hold_candidates(max_snap_mm: float, min_local_req: float, fallback_mode: bool) -> Optional[Dict[str, Any]]:
                    best_hold_local = None
                    for desired in desired_list:
                        desired_use = np.asarray(desired, dtype=np.float32).reshape(2)
                        if mask_for_local is not None and edge_dt is not None:
                            ray = desired_use - problem
                            ray_len = float(np.linalg.norm(ray))
                            safe = _a146_action3_max_safe_contact_offset(
                                problem, ray, ray_len, edge_inset,
                                mask_for_local, latest_H, edge_dt)
                            if not isinstance(safe, dict):
                                continue
                            desired_use = np.asarray(safe["point"], dtype=np.float32)
                        dx, dy = _targeted_clamp_board_xy(float(desired_use[0]), float(desired_use[1]))
                        snapped = _nearest_mask_board_point(hold_source_plan, hold_arm, dx, dy)
                        if snapped is None:
                            hx, hy = dx, dy
                        else:
                            hx, hy = float(snapped[0]), float(snapped[1])
                        local = 1.0
                        actual_edge_depth_mm = None
                        if mask_for_local is not None:
                            local = _targeted_mask_ratio_at_board(mask_for_local, hx, hy)
                            if local < float(min_local_req):
                                continue
                            # Hard-workspace snapping can move the hold point.
                            # Recheck that the actual executable hold still has
                            # the requested 10mm cloth margin.
                            safe_actual = _a146_action3_max_safe_contact_offset(
                                np.asarray([hx, hy], dtype=np.float32),
                                np.asarray([1.0, 0.0], dtype=np.float32),
                                0.0, edge_inset, mask_for_local, latest_H, edge_dt)
                            if not isinstance(safe_actual, dict):
                                continue
                            actual_edge_depth_mm = float(safe_actual.get("edge_depth_mm", 0.0))
                        hold_z = get_arm_press_z(hold_arm)
                        hover = resolve_board_target_for_arm(hold_arm, hx, hy, clear_z, "ACTION3-HOLD-CLEAR")
                        down = resolve_board_target_for_arm(hold_arm, hx, hy, hold_z, "ACTION3-HOLD-DOWN")
                        lift = resolve_board_target_for_arm(hold_arm, hx, hy, clear_z, "ACTION3-HOLD-LIFT")
                        if hover is None or down is None or lift is None:
                            continue
                        dist_to_desired = float(np.linalg.norm(np.array([hx - dx, hy - dy], dtype=np.float32)))
                        if float(max_snap_mm) > 0.0 and dist_to_desired > float(max_snap_mm):
                            continue
                        q = float(local) * 100.0 - dist_to_desired - (35.0 if fallback_mode else 0.0)
                        h = {
                            "enabled": True,
                            "arm_key": hold_arm,
                            "active_arm_key": active_arm,
                            "desired_board_xy": [float(dx), float(dy)],
                            "hold_board_xy": [float(hx), float(hy)],
                            "problem_board_xy": [float(problem[0]), float(problem[1])],
                            "active_start_board_xy": [float(active_start[0]), float(active_start[1])],
                            "wrinkle_axis_board": [float(axis[0]), float(axis[1])],
                            "local_mask_ratio": float(local),
                            "snap_dist_mm": float(dist_to_desired),
                            "hover": hover,
                            "down": down,
                            "lift": lift,
                            "hold_z": float(hold_z),
                            "gripper": float(getattr(args, "auto_x_action3_hold_gripper", 3.050)),
                            "quality": q,
                            "fallback_mode": bool(fallback_mode),
                            "a146_extra_offset_mm": float(extra_offset),
                            "a146_edge_inset_mm": float(edge_inset),
                            "a146_actual_edge_depth_mm": actual_edge_depth_mm,
                        }
                        if best_hold_local is None or h["quality"] > best_hold_local["quality"]:
                            best_hold_local = h
                    return best_hold_local

                strict_snap = float(max(0.0, getattr(args, "auto_x_action3_hold_max_snap_mm", 35.0)))
                strict_local = float(max(0.0, getattr(args, "auto_x_action3_hold_min_local_mask_ratio", 0.12)))
                best_hold = _try_hold_candidates(strict_snap, strict_local, False)
                if best_hold is not None:
                    return best_hold

                fallback_snap = float(max(strict_snap, getattr(args, "auto_x_action3_hold_fallback_max_snap_mm", 75.0)))
                fallback_local = float(max(0.0, getattr(args, "auto_x_action3_hold_fallback_min_local_mask_ratio", 0.06)))
                best_hold = _try_hold_candidates(fallback_snap, fallback_local, True)
                if best_hold is not None and bool(print_result):
                    print(f"[A83-ACTION3-HOLD-FALLBACK] strict passive hold unavailable; using wider symmetric cloth-supported hold snap={float(best_hold.get('snap_dist_mm',0.0)):.1f}mm local={float(best_hold.get('local_mask_ratio',0.0)):.2f}")
                if best_hold is None:
                    hold_reject_notes.append(f"OPPOSITE_HOLD_NOT_FOUND:candidates={len(desired_list)},strict_snap={strict_snap:.1f},fallback_snap={fallback_snap:.1f},strict_local={strict_local:.2f},fallback_local={fallback_local:.2f}")
                return best_hold

            for cand_rank, item in enumerate(cands, 1):
                if len(passes) >= exec_count:
                    break
                idx = len(passes) + 1
                arm_key = str(item.get("arm_key", ""))
                if arm_key not in ("arm2", "arm1"):
                    blocked_notes.append(f"rank={cand_rank} invalid arm={arm_key}")
                    continue
                sxy = item.get("start_board_xy")
                exy = item.get("end_board_xy")
                if not sxy or not exy:
                    blocked_notes.append(f"rank={cand_rank} missing start/end")
                    continue
                sxy_arr = np.asarray(sxy, dtype=np.float32).reshape(2)
                exy_arr = np.asarray(exy, dtype=np.float32).reshape(2)
                sweep_len = float(np.linalg.norm(exy_arr - sxy_arr))
                score = float(item.get("score", 0.0))
                exmeta = item.get("extra", {}) if isinstance(item.get("extra", {}), dict) else {}
                heat = float(exmeta.get("heat_score", exmeta.get("heat_mean", exmeta.get("heat_max", 0.0))) or 0.0)
                is_action3_grad = bool(exmeta.get("action3_gradient", False)) and str(item.get("kind", "")) == "wrinkle"
                is_structural_radial_probe = bool(exmeta.get("structural_candidate_radial_probe", False))
                force_single_arm = bool(exmeta.get("a135_force_single_arm", False))
                hold_plan = None
                pre_targets = None
                if is_action3_grad and (not is_structural_radial_probe) and (not force_single_arm) and bool(getattr(args, "auto_x_action3_soft_workspace_hold", True)):
                    soft_pair = _build_action3_soft_workspace_pair(item, arm_key, requested_sweep_len=float(sweep_len))
                    if isinstance(soft_pair, tuple) and len(soft_pair) == 2:
                        item, hold_plan = soft_pair
                        sxy = item.get("start_board_xy")
                        exy = item.get("end_board_xy")
                        sxy_arr = np.asarray(sxy, dtype=np.float32).reshape(2)
                        exy_arr = np.asarray(exy, dtype=np.float32).reshape(2)
                        sweep_len = float(np.linalg.norm(exy_arr - sxy_arr))
                        exmeta = item.get("extra", {}) if isinstance(item.get("extra", {}), dict) else {}
                        pre_targets = item.get("_a95_active_targets") if isinstance(item.get("_a95_active_targets"), dict) else None
                if sweep_len < min_sweep:
                    msg = (f"[TARGET-PRESS-CAND] rank={cand_rank} kind={item.get('kind','?')} arm={arm_key.upper()} "
                           f"score={score:.1f} heat={heat:.1f} sweep={sweep_len:.1f}mm -> SKIP too short < {min_sweep:.1f}mm")
                    if print_result:
                        print(msg)
                    blocked_notes.append(msg)
                    continue
                pz = get_arm_press_z(arm_key)
                if isinstance(pre_targets, dict):
                    hover = pre_targets.get("hover")
                    down = pre_targets.get("down")
                    sweep = pre_targets.get("sweep")
                    lift = pre_targets.get("lift")
                    mid = None
                else:
                    resolver = resolve_board_target_for_arm_soft_action3 if is_action3_grad else resolve_board_target_for_arm
                    hover = resolver(arm_key, float(sxy[0]), float(sxy[1]), clear_z, f"TARGET-PRESS{idx}-CLEAR-START")
                    down = resolver(arm_key, float(sxy[0]), float(sxy[1]), pz, f"TARGET-PRESS{idx}-DOWN")
                    sweep = resolver(arm_key, float(exy[0]), float(exy[1]), pz, f"TARGET-PRESS{idx}-SWEEP")
                    lift = resolver(arm_key, float(exy[0]), float(exy[1]), clear_z, f"TARGET-PRESS{idx}-CLEAR-LIFT")
                    mid = None
                    use_micro = bool(str(item.get("kind", "")) == "wrinkle" and bool(args.wrinkle_press_micro_sweep) and not is_action3_grad and not is_structural_radial_probe)
                    if use_micro:
                        rr = float(np.clip(float(args.wrinkle_press_micro_mid_ratio), 0.1, 0.9))
                        mx = float(sxy[0]) + (float(exy[0]) - float(sxy[0])) * rr
                        my = float(sxy[1]) + (float(exy[1]) - float(sxy[1])) * rr
                        mid = resolver(arm_key, mx, my, pz, f"TARGET-PRESS{idx}-MICRO-MID")
                blocked = hover is None or down is None or sweep is None or lift is None or (str(item.get("kind", "")) == "wrinkle" and bool(args.wrinkle_press_micro_sweep) and (not is_action3_grad) and mid is None)
                if blocked:
                    msg = (f"[TARGET-PRESS-CAND] rank={cand_rank} kind={item.get('kind','?')} arm={arm_key.upper()} "
                           f"score={score:.1f} heat={heat:.1f} sweep={sweep_len:.1f}mm -> SKIP target blocked before down")
                    if print_result:
                        print(msg)
                    blocked_notes.append(msg)
                    if not skip_blocked:
                        if print_result:
                            print(f"[TARGET-PRESS-ACTION] blocked: target resolution failed at candidate rank {cand_rank} {arm_key.upper()}")
                        return None
                    continue
                actual_sweep_len = float(np.linalg.norm(np.array([sweep["bx"] - down["bx"], sweep["by"] - down["by"]], dtype=np.float32)))
                if actual_sweep_len < min_sweep:
                    msg = (f"[TARGET-PRESS-CAND] rank={cand_rank} kind={item.get('kind','?')} arm={arm_key.upper()} "
                           f"score={score:.1f} heat={heat:.1f} executable_sweep={actual_sweep_len:.1f}mm -> SKIP too short after resolve")
                    if print_result:
                        print(msg)
                    blocked_notes.append(msg)
                    continue
                if hold_plan is None and not is_structural_radial_probe and not force_single_arm:
                    hold_plan = _build_action3_opposite_hold(item, arm_key)
                if is_action3_grad and (not is_structural_radial_probe) and (not force_single_arm) and bool(getattr(args, "auto_x_action3_require_passive_hold", True)) and hold_plan is None:
                    hold_detail = ";".join(hold_reject_notes[-10:]) if hold_reject_notes else "NO_HOLD_DIAGNOSTIC"
                    msg = (f"[TARGET-PRESS-CAND] rank={cand_rank} kind={item.get('kind','?')} arm={arm_key.upper()} "
                           f"score={score:.1f} heat={heat:.1f} sweep={actual_sweep_len:.1f}mm -> SKIP ACTION3 requires passive hold | hold_reasons={hold_detail}")
                    if print_result:
                        print(msg)
                    blocked_notes.append(msg)
                    continue
                if print_result:
                    if is_structural_radial_probe:
                        print(f"[A98-STRUCTURAL-RADIAL-PROBE] executable one-arm path: {arm_key.upper()} "
                              f"grasp=({float(sxy[0]):.1f},{float(sxy[1]):.1f}) -> "
                              f"end=({float(exy[0]):.1f},{float(exy[1]):.1f}) pull={actual_sweep_len:.1f}mm; passive hold intentionally disabled")
                    hold_msg = ""
                    if isinstance(hold_plan, dict):
                        hb = hold_plan.get("hold_board_xy", [0.0, 0.0])
                        hold_msg = f" | opposite_hold={str(hold_plan.get('arm_key','?')).upper()}@({float(hb[0]):.1f},{float(hb[1]):.1f}) local={float(hold_plan.get('local_mask_ratio',0.0)):.2f}"
                    elif bool(getattr(args, "auto_x_action3_opposite_hold", True)) and bool(exmeta.get("action3_gradient", False)):
                        hold_msg = " | opposite_hold=NO_REACHABLE_SYMMETRIC_POINT"
                    print(f"[TARGET-PRESS-CAND] rank={cand_rank} kind={item.get('kind','?')} arm={arm_key.upper()} "
                          f"score={score:.1f} heat={heat:.1f} sweep={actual_sweep_len:.1f}mm -> EXEC pass {idx}{hold_msg}")
                passes.append({
                    "index": idx,
                    "candidate": item,
                    "arm_key": arm_key,
                    "hover": hover,
                    "down": down,
                    "mid": mid,
                    "sweep": sweep,
                    "lift": lift,
                    "hold": hold_plan,
                    "sweep_len_mm": actual_sweep_len,
                    "candidate_rank": cand_rank,
                })

            if not passes:
                reason_code = "NO_EXECUTABLE_PASS"
                joined = " | ".join(str(x) for x in blocked_notes).lower()
                if "requires passive hold" in joined:
                    reason_code = "PASSIVE_HOLD_NOT_FOUND"
                elif "too short after resolve" in joined:
                    reason_code = "SWEEP_TOO_SHORT_AFTER_RESOLVE"
                elif "too short" in joined:
                    reason_code = "SWEEP_TOO_SHORT"
                elif "target blocked before down" in joined:
                    reason_code = "TARGET_RESOLUTION_FAILED"
                elif "invalid arm" in joined:
                    reason_code = "ACTIVE_ARM_INVALID"
                elif "missing start/end" in joined:
                    reason_code = "MISSING_START_END"
                build_targeted_press_motion_plan.last_diagnostics = {
                    "status": "BLOCKED", "reason_code": reason_code,
                    "blocked_notes": list(blocked_notes),
                    "candidate_count": len(cands), "pass_count": 0,
                    "min_sweep_mm": float(min_sweep),
                }
                if print_result:
                    print("[TARGET-PRESS-ACTION] blocked: no executable passes after pre-check. "
                          "This means wrinkle/target candidates existed, but their sweep was too short or crossed board/arm workspace safety.")
                return None

            out = {
                "passes": passes,
                "summary": f"targeted press action passes={len(passes)} clear_z={clear_z:.1f} press_z={float(args.press_z):.1f} speed={float(args.press_speed):.2f} min_sweep={min_sweep:.1f} micro_sweep={bool(args.wrinkle_press_micro_sweep)} dir_mode={args.wrinkle_press_direction_mode}",
            }
            build_targeted_press_motion_plan.last_diagnostics = {
                "status": "OK", "reason_code": "OK",
                "blocked_notes": list(blocked_notes),
                "candidate_count": len(cands), "pass_count": len(passes),
                "min_sweep_mm": float(min_sweep),
            }
            if print_result:
                print("\n========== TARGETED PRESS ACTION PLAN ==========")
                print(out["summary"])
                for p in passes:
                    c = p.get("candidate", {})
                    sxy = c.get("start_board_xy", [0, 0])
                    exy = c.get("end_board_xy", [0, 0])
                    ex = c.get("extra", {})
                    hold = p.get("hold") if isinstance(p.get("hold"), dict) else None
                    hold_txt = ""
                    if hold is not None:
                        hb = hold.get("hold_board_xy", [0.0, 0.0])
                        hold_txt = f" | passive_hold {str(hold.get('arm_key','?')).upper()}=({float(hb[0]):.1f},{float(hb[1]):.1f}) local={float(hold.get('local_mask_ratio',0.0)):.2f}"
                    print(f"PASS {p['index']}: {p['arm_key'].upper()} {c.get('kind','?')} "
                          f"press=({sxy[0]:.1f},{sxy[1]:.1f}) -> end=({exy[0]:.1f},{exy[1]:.1f}) "
                          f"local={float(c.get('local_mask_ratio',0)):.2f} "
                          f"q+={float(ex.get('quality_bonus',0)):.1f} repeat-={float(ex.get('repeat_penalty',0)):.1f}{hold_txt}")
                print("===============================================\n")
            return out

    def _pose_visibility_score_from_plan(plan: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        total = max(1, len(TSHIRT_POSE_KPT_NAMES))
        valid_names: List[str] = []
        if isinstance(plan, dict):
            try:
                valid_names = sorted(set(str(x) for x in plan.get("valid_kpt_names", [])))
            except Exception:
                valid_names = []
        valid_count = len(valid_names)
        ratio = float(valid_count) / float(total)
        return {
            "valid_count": int(valid_count),
            "total": int(total),
            "ratio": float(ratio),
            "valid_names": valid_names,
        }

    def _auto_align_rotate_pose_is_ready(plan: Optional[Dict[str, Any]], label: str = "") -> Tuple[bool, Dict[str, Any]]:
        """Return True when the pose model sees enough T-shirt keypoints.

        Step_a47 policy:
          - 85% keypoint visibility means the cloth is flat enough to leave X wrinkle spreading.
          - This check does NOT require the key-6 rotation target to be currently feasible.
            A pose can be visible while key-6 is temporarily BLOCKED by workspace/position.
            In that case we still proceed to the center-correction decision first.
        """
        score = _pose_visibility_score_from_plan(plan)
        ratio_thr = float(np.clip(getattr(args, "auto_align_rotate_pose_visible_ratio", 0.85), 0.0, 1.0))
        min_kpts = int(getattr(args, "auto_align_rotate_min_valid_kpts", 0))
        if min_kpts <= 0:
            min_kpts = int(math.ceil(float(score["total"]) * ratio_thr))
        min_kpts = max(1, min(int(score["total"]), min_kpts))
        rotation_plan_usable = bool(isinstance(plan, dict) and (bool(plan.get("ready", False)) or bool(plan.get("done", False))))
        visible_ok = bool(score["valid_count"] >= min_kpts and score["ratio"] >= ratio_thr)
        ok = bool(visible_ok)
        status = str(plan.get("status", "no pose plan")) if isinstance(plan, dict) else "no pose plan"
        reason = str(plan.get("ready_reason", "")) if isinstance(plan, dict) else ""
        print("\n========== AUTO WRINKLE -> CENTER -> ROTATE CHECK ==========")
        if label:
            print(f"source={label}")
        print(f"pose visible keypoints: {score['valid_count']}/{score['total']} = {score['ratio']:.2f}  target>={ratio_thr:.2f}, min_kpts={min_kpts}")
        print(f"wrinkle-flat decision: visible_ok={visible_ok}")
        print(f"key-6 plan currently usable: {rotation_plan_usable}  [not required before / decision]")
        print(f"pose status: {status}")
        if reason:
            print(f"pose ready_reason: {reason}")
        print("==========================================================\n")
        detail = dict(score)
        detail.update({
            "ratio_threshold": float(ratio_thr),
            "min_kpts": int(min_kpts),
            "pose_ok": bool(rotation_plan_usable),
            "rotation_plan_usable": bool(rotation_plan_usable),
            "visible_ok": bool(visible_ok),
            "ok": bool(ok),
            "status": status,
            "ready_reason": reason,
        })
        return ok, detail

    def _auto_variable_overflow_needed_by_done_metric(plan: Optional[Dict[str, Any]]) -> Tuple[bool, str, Dict[str, Any]]:
        """Decide whether to auto-run '/' using exactly the current '/' stopping metric.

        True means center/position correction is still needed. False means the same
        done criterion used by '/' is already satisfied, so the cascade can skip '/'
        and go straight to key-6 pose rotation.
        """
        done_metric = str(getattr(args, "variable_overflow_done_metric", "pose_axis_distance"))
        detail: Dict[str, Any] = {"done_metric": done_metric}

        if plan is None:
            return True, "coarse/segmentation plan unavailable; run / because center state cannot be judged", detail

        if done_metric == "vacancy_center_balance":
            vac_ok, center_err, gap_balance, vac_msg, vac_detail = _inside_vacancy_center_balance_stop_metrics(plan)
            center_done = float(getattr(args, "variable_overflow_vacancy_center_done_mm", 50.0))
            gap_done = float(getattr(args, "variable_overflow_vacancy_gap_balance_done_mm", 80.0))
            detail.update({
                "center_error_mm": None if center_err is None else float(center_err),
                "gap_balance_mm": None if gap_balance is None else float(gap_balance),
                "center_done_mm": center_done,
                "gap_done_mm": gap_done,
                "vacancy_detail": vac_detail,
            })
            if bool(vac_ok):
                return False, (f"/ not needed: vacancy_center_balance already done "
                               f"center_error={center_err:.1f}mm <= {center_done:.1f}mm, "
                               f"gap_balance={gap_balance:.1f}mm <= {gap_done:.1f}mm"), detail
            ce = "None" if center_err is None else f"{center_err:.1f}"
            gb = "None" if gap_balance is None else f"{gap_balance:.1f}"
            return True, (f"/ needed: vacancy_center_balance not satisfied "
                          f"center_error={ce}mm target<={center_done:.1f}mm, "
                          f"gap_balance={gb}mm target<={gap_done:.1f}mm | {vac_msg}"), detail

        if done_metric == "inside_vacancy_center":
            inside_ratio, pose_center_err, vac_msg, vac_detail = _inside_vacancy_stop_metrics(plan)
            ratio_done = float(getattr(args, "variable_overflow_inside_area_done_ratio", 0.85))
            center_done = float(getattr(args, "variable_overflow_pose_center_done_mm", 50.0))
            detail.update({
                "inside_ratio": None if inside_ratio is None else float(inside_ratio),
                "pose_center_error_mm": None if pose_center_err is None else float(pose_center_err),
                "inside_ratio_done": ratio_done,
                "pose_center_done_mm": center_done,
                "vacancy_detail": vac_detail,
            })
            if inside_ratio is not None and pose_center_err is not None and inside_ratio >= ratio_done and pose_center_err <= center_done:
                return False, (f"/ not needed: inside_vacancy_center already done "
                               f"inside_ratio={inside_ratio:.3f}>={ratio_done:.2f}, "
                               f"pose_center_error={pose_center_err:.1f}mm<={center_done:.1f}mm"), detail
            ir = "None" if inside_ratio is None else f"{inside_ratio:.3f}"
            pe = "None" if pose_center_err is None else f"{pose_center_err:.1f}"
            return True, (f"/ needed: inside_vacancy_center not satisfied "
                          f"inside_ratio={ir} target>={ratio_done:.2f}, "
                          f"pose_center_error={pe}mm target<={center_done:.1f}mm | {vac_msg}"), detail

        if done_metric == "pose_axis_distance":
            pose_err, pose_msg, pose_detail = _variable_pose_axis_center_error_mm()
            pose_done_mm = max(0.0, float(getattr(args, "variable_overflow_pose_axis_done_mm", 50.0)))
            detail.update({
                "pose_axis_center_error_mm": None if pose_err is None else float(pose_err),
                "pose_axis_done_mm": pose_done_mm,
                "pose_detail": pose_detail,
            })
            if pose_err is not None and pose_err <= pose_done_mm:
                return False, f"/ not needed: pose_axis_center_error={pose_err:.1f}mm <= {pose_done_mm:.1f}mm", detail
            if pose_err is not None:
                return True, f"/ needed: pose_axis_center_error={pose_err:.1f}mm > {pose_done_mm:.1f}mm", detail
            if bool(getattr(args, "variable_overflow_pose_axis_require_pose", False)):
                return False, f"/ not run: pose-axis stop metric unavailable and require_pose=True | {pose_msg}", detail
            return True, f"/ needed: pose-axis stop metric unavailable, fallback to / action | {pose_msg}", detail

        raw_board, _cand, raw_src = _candidate_board_points_for_variable_overflow(plan, use_raw=True)
        done_mm = max(0.0, float(getattr(args, "variable_overflow_auto_done_mm", 10.0)))
        if raw_board is None or len(raw_board) < 20:
            detail.update({"raw_src": raw_src})
            return True, f"/ needed: max_overflow cannot be measured reliably ({raw_src})", detail
        info = _variable_side_overflows_from_board(raw_board)
        sides = info.get("sides", {})
        depths = {k: float(v.get("overflow", 0.0)) for k, v in sides.items()}
        max_ov = max(depths.values()) if depths else 0.0
        detail.update({"max_overflow_mm": float(max_ov), "done_mm": done_mm, "depths": depths})
        if max_ov <= done_mm:
            return False, f"/ not needed: max_overflow={max_ov:.1f}mm <= {done_mm:.1f}mm", detail
        return True, f"/ needed: max_overflow={max_ov:.1f}mm > {done_mm:.1f}mm", detail

    def _auto_wrinkle_area_from_plan(plan: Optional[Dict[str, Any]]) -> Optional[float]:
        try:
            m = _coarse_eval_metrics_from_plan(plan)
            if m is None:
                return None
            area = float(m.get("area_px", 0.0) or 0.0)
            return area if area > 1.0 else None
        except Exception:
            return None

    def _auto_wrinkle_report(plan: Optional[Dict[str, Any]], label: str = "") -> Dict[str, Any]:
        """Measure texture-wrinkle ratio inside the current garment mask.

        ratio = wrinkle-like pixels / inner garment-mask pixels.
        The binary wrinkle pixels come from the existing Step37 heatmap pipeline,
        so this stays consistent with the OpenCV wrinkle overlay.
        """
        out: Dict[str, Any] = {
            "ok": False,
            "ratio": None,
            "wrinkle_px": 0,
            "inner_px": 0,
            "area_px": _auto_wrinkle_area_from_plan(plan),
            "status": "not computed",
        }
        # X planner must not stop just because a two-arm coarse SPREAD
        # plan is blocked.  A fallback/segmentation candidate is still enough for
        # wrinkle-ratio and centroid judgment, especially before priority-1 centering.
        cand = _targeted_press_source_candidate(plan)
        if plan is None:
            if cand is not None:
                try:
                    out["area_px"] = float(cand.get("area", cand.get("area_px", 0.0)) or 0.0)
                except Exception:
                    pass
                out["status"] = "no coarse spread plan; using latest segmentation candidate"
            else:
                out["status"] = "no coarse/segmentation candidate"
                print(f"[AUTO-WRINKLE-METRIC] {label}: {out['status']}")
                return out
        wh = build_wrinkle_heatmap_plan(cand, print_result=False)
        if wh is None:
            out["status"] = f"wrinkle heatmap unavailable: {latest_wrinkle_heatmap_status}"
            print(f"[AUTO-WRINKLE-METRIC] {label}: {out['status']}")
            return out
        try:
            inner = np.asarray(wh.get("inner_mask")) > 0
            binary = np.asarray(wh.get("binary")) > 0
            denom = int(np.count_nonzero(inner))
            numer = int(np.count_nonzero(binary & inner))
            ratio = float(numer) / float(max(1, denom))
            out.update({
                "ok": True,
                "ratio": float(ratio),
                "wrinkle_px": int(numer),
                "inner_px": int(denom),
                "candidate_count": int(len(wh.get("candidates", []))),
                "threshold": float(wh.get("threshold", 0.0)),
                "status": "OK",
            })
            area_txt = "?" if out["area_px"] is None else f"{float(out['area_px']):.0f}px"
            print(f"[AUTO-WRINKLE-METRIC] {label}: wrinkle_ratio={ratio:.3f} "
                  f"({numer}/{denom}) area={area_txt} candidates={out.get('candidate_count',0)} thr={out.get('threshold',0):.1f}")
        except Exception as e:
            out["status"] = f"wrinkle metric error: {repr(e)}"
            print(f"[AUTO-WRINKLE-METRIC] {label}: {out['status']}")
        return out

    def _auto_area_change_ratio(prev_area: Optional[float], cur_area: Optional[float]) -> Optional[float]:
        try:
            if prev_area is None or cur_area is None:
                return None
            p = float(prev_area)
            c = float(cur_area)
            if p <= 1.0:
                return None
            return float(abs(c - p) / p)
        except Exception:
            return None

    def _auto_center_correction_once(label: str, require_plan: bool = True, execution_mode: str = "press_drag") -> bool:
        """Run one / center-correction execution from the already observed snapshot.

        Step_a53 snapshot discipline:
          - observe() already captured the decision snapshot and built latest_coarse_plan.
          - / must execute from that current plan.
          - / must NOT run its own internal post-motion rejudge snapshot inside this action.
          - The outer X planner will capture exactly one new snapshot after the action.

        Step_a55 policy:
          - X planner priority-1 position correction is judged ONLY by garment-mask
            center error against the board center.
          - If center error is large, force one existing circumcenter-vacancy plan
            from the current mask.  Do not stop just because max_overflow==0.
          - The existing circumcenter algorithm itself is preserved.
        """
        if not bool(getattr(args, "auto_align_rotate_run_variable_overflow", True)):
            print(f"[AUTO-WRINKLE-CENTER] skipped by option: {label}")
            return False
        if require_plan and latest_coarse_plan is None:
            print(f"[AUTO-WRINKLE-CENTER] blocked: no coarse/segmentation plan for {label}")
            return False

        one_snapshot = bool(getattr(args, "auto_wrinkle_one_snapshot_per_decision", True))
        saved_rounds = getattr(args, "variable_overflow_auto_max_rounds", 4)
        saved_auto_loop = getattr(args, "variable_overflow_auto_loop", True)
        saved_circ_direct = getattr(args, "variable_overflow_circumcenter_direct_to_center", True)
        try:
            rounds = max(1, int(getattr(args, "auto_wrinkle_single_center_rounds", 1)))
            setattr(args, "variable_overflow_auto_max_rounds", rounds)
            if one_snapshot:
                # Important: variable_overflow_recovery_once() normally does a post-motion
                # rejudge even when max_rounds==1. Disable that inner loop here so the
                # X planner owns the single post-action snapshot.
                setattr(args, "variable_overflow_auto_loop", False)
                rounds = 1
                setattr(args, "variable_overflow_auto_max_rounds", rounds)
                print(f"[AUTO-WRINKLE-CENTER] one-snapshot policy ON: use current observed / plan, no internal / rejudge snapshot")
            force_circ = bool(getattr(args, "auto_wrinkle_force_circumcenter_centering", True))
            if force_circ:
                setattr(args, "variable_overflow_circumcenter_direct_to_center", False)
                print("[AUTO-WRINKLE-CENTER-A90] ACTION1 uses the bounded Circumcenter plan: "
                      "triangle/circumcenter target is preserved, while the motion endpoint is "
                      "start + unit(center->circumcenter) * clipped(gain*center_to_target).")
            print(f"[AUTO-WRINKLE-CENTER] running forced circumcenter center correction bounded to {rounds} round(s): {label}; force_circumcenter={force_circ}")
            variable_overflow_recovery_once(force_execute_plan=force_circ, execution_mode=execution_mode)
            return True
        finally:
            setattr(args, "variable_overflow_auto_max_rounds", saved_rounds)
            setattr(args, "variable_overflow_auto_loop", saved_auto_loop)
            setattr(args, "variable_overflow_circumcenter_direct_to_center", saved_circ_direct)

    def _a140_run_frozen_center_once(label: str, require_plan: bool = True, execution_mode: str = "press_drag") -> bool:
        """A140 orchestration guard: one frozen center action, no inner rejudge."""
        saved_one_snapshot = getattr(args, "auto_wrinkle_one_snapshot_per_decision", True)
        saved_center_rounds = getattr(args, "auto_wrinkle_single_center_rounds", 1)
        try:
            setattr(args, "auto_wrinkle_one_snapshot_per_decision", True)
            setattr(args, "auto_wrinkle_single_center_rounds", 1)
            return bool(_auto_center_correction_once(label, require_plan=require_plan, execution_mode=execution_mode))
        finally:
            setattr(args, "auto_wrinkle_one_snapshot_per_decision", saved_one_snapshot)
            setattr(args, "auto_wrinkle_single_center_rounds", saved_center_rounds)

    def _auto_mask_center_reposition_once(label: str) -> bool:
        """Run one real mask-center correction from the current observed snapshot.

        This is different from the '/' overflow/circumcenter recovery:
          - '/' is only for overflow/vacancy correction and may legitimately stop when max_overflow==0.
          - mask-center correction uses the key-4 SMART REPOSITION drag planner.

        Step_a54 fix:
          When X planner says center_error is too large but overflow_needed is False,
          do NOT call '/'.  Use one current-snapshot marker/smart reposition drag instead.
          No fresh-before or internal after-action snapshot is allowed here; the outer
          X planner performs the next observe() snapshot.
        """
        if latest_coarse_plan is None:
            print(f"[AUTO-X-MASK-CENTER] blocked: no current observed coarse/segmentation plan for {label}")
            return False
        saved_marker_fresh = getattr(args, "marker_fill_fresh_snapshot", True)
        saved_reinfer_after = getattr(args, "auto_reinfer_after_motion", True)
        try:
            setattr(args, "marker_fill_fresh_snapshot", False)
            setattr(args, "auto_reinfer_after_motion", False)
            print(f"[AUTO-X-MASK-CENTER] one-snapshot policy ON: run key-4 style smart reposition from current snapshot only: {label}")
            mp = marker_corner_fill_drag(fresh_before=False, reinfer_after=False)
            return mp is not None
        finally:
            setattr(args, "marker_fill_fresh_snapshot", saved_marker_fresh)
            setattr(args, "auto_reinfer_after_motion", saved_reinfer_after)

    def _auto_refresh_coarse(label: str, timeout: float, required: bool = True,
                             expected_auto_x_epoch: Optional[int] = None) -> Optional[Dict[str, Any]]:
        plan = request_fresh_coarse_plan_and_wait(
            reason=label,
            timeout=timeout,
            expected_auto_x_epoch=expected_auto_x_epoch,
        )
        if plan is None and required:
            print(f"[AUTO-WRINKLE-CASCADE] blocked: fresh coarse/segmentation plan unavailable: {latest_coarse_status}")
        return plan

    def _auto_run_x_spread_only(force_fresh_plan: bool = False) -> bool:
        """Run one X coarse-spread action from the current observed snapshot/plan.

        Step_a53 snapshot discipline:
          - observe() captures exactly one fresh snapshot and stores latest_coarse_plan.
          - This X motion must reuse that plan. It must not take another fresh snapshot
            immediately before moving.
          - This X motion must not run coarse_grip_and_small_lift()'s internal
            post-evaluation snapshot. The outer planner will take exactly one fresh
            observation after the motion ends.

        The older auto press / auto targeted press cascade stays disabled here.
        Targeted press remains intentionally held out of the X planner.
        """
        saved_use_displayed = getattr(args, "coarse_action_use_displayed_plan_first", True)
        saved_fresh_snapshot = getattr(args, "coarse_action_fresh_snapshot", True)
        saved_eval_after = getattr(args, "coarse_eval_after_action", True)
        saved_auto_reinfer = getattr(args, "auto_reinfer_after_motion", True)
        try:
            if force_fresh_plan:
                print("[AUTO-WRINKLE-SPREAD] A140 exact-plan policy: fresh rejudge must happen in observe(), not inside X motion")
            # absolute invariant: execute only the already observed/frozen
            # plan.  The outer controller owns the single post-action snapshot,
            # even if a legacy CLI disables the former optional one-snapshot flag.
            setattr(args, "coarse_action_use_displayed_plan_first", True)
            setattr(args, "coarse_action_fresh_snapshot", False)
            setattr(args, "coarse_eval_after_action", False)
            setattr(args, "auto_reinfer_after_motion", False)
            return bool(coarse_grip_and_small_lift())
        finally:
            setattr(args, "coarse_action_use_displayed_plan_first", saved_use_displayed)
            setattr(args, "coarse_action_fresh_snapshot", saved_fresh_snapshot)
            setattr(args, "coarse_eval_after_action", saved_eval_after)
            setattr(args, "auto_reinfer_after_motion", saved_auto_reinfer)

    def _a109_run_step37_action2_motion(plan: Dict[str, Any], pull_mm: float, action_label: str) -> bool:
        """Execute only ACTION2 with the Step37 X-key dual-arm spread primitive.

        The saved same-snapshot plan is used directly.  Step37's air-release at the
        stretched lift pose is restored; a108's ACTION2 floor-place/slow-open override
        is intentionally not used for this action.
        """
        nonlocal latest_coarse_plan, coarse_action_stretch_distance_override
        if not isinstance(plan, dict):
            print("[A109-ACTION2-STEP37-BLOCKED] no saved Step37 ACTION2 plan")
            return False

        saved_plan = latest_coarse_plan
        saved_override = coarse_action_stretch_distance_override
        saved_air_release = bool(getattr(args, "coarse_release_at_stretch_lift", True))
        saved_vertical_retract = bool(getattr(args, "coarse_release_vertical_retract_before_standby", True))
        saved_place_after = bool(getattr(args, "coarse_stretch_place_after", True))
        saved_slow_flag = bool(getattr(args, "auto_x_action2_floor_slow_release_active", False))
        try:
            latest_coarse_plan = plan
            coarse_action_stretch_distance_override = float(max(1.0, pull_mm))
            setattr(args, "coarse_release_at_stretch_lift", True)
            setattr(args, "coarse_release_vertical_retract_before_standby", True)
            setattr(args, "coarse_stretch_place_after", True)
            setattr(args, "auto_x_action2_floor_slow_release_active", False)
            mode = plan.get("metrics", {}).get("axis_mode", plan.get("spread_axis", {}).get("axis_mode", "?"))
            p2 = plan.get("targets", {}).get("arm2", {}).get("board_xy")
            p1 = plan.get("targets", {}).get("arm1", {}).get("board_xy")
            print(f"[A109-ACTION2-STEP37] execute {action_label}: minor-first/inward-grasp plan mode={mode}, pull={coarse_action_stretch_distance_override:.1f}mm per arm")
            if p2 is not None and p1 is not None:
                print(f"[A109-ACTION2-STEP37] saved same-snapshot contacts: ARM2=({float(p2[0]):.1f},{float(p2[1]):.1f}), ARM1=({float(p1[0]):.1f},{float(p1[1]):.1f})")
            print("[A109-ACTION2-STEP37] motion: parallel grip/lift -> selected Step37 spread axis -> air release -> vertical retract")
            return bool(_auto_run_x_spread_only(force_fresh_plan=False))
        finally:
            latest_coarse_plan = saved_plan
            coarse_action_stretch_distance_override = saved_override
            setattr(args, "coarse_release_at_stretch_lift", saved_air_release)
            setattr(args, "coarse_release_vertical_retract_before_standby", saved_vertical_retract)
            setattr(args, "coarse_stretch_place_after", saved_place_after)
            setattr(args, "auto_x_action2_floor_slow_release_active", saved_slow_flag)

    def _auto_return_to_standby_before_next_snapshot(action: str) -> bool:
        """Ensure the next decision snapshot is taken with both arms out of the ROI.

        Step_a56 policy: after every executed motion chosen by the X planner,
        both arms must be moved to the imaging standby pose before the outer
        planner requests the next fresh snapshot.
        """
        try:
            if (not bool(getattr(args, "imaging_standby", True))
                    or bool(getattr(args, "no_standby", False))):
                print("[A140-INITIAL-STANDBY-INCOMPLETE] AUTO-X imaging requires enabled both-arm standby")
                return False
            print(f"[AUTO-X-STANDBY] action {action} finished; move arms to imaging standby before next snapshot")
            both_ok = bool(move_arms_to_standby(reason=f"after AUTO-X action {action} before next snapshot"))
            if not both_ok:
                print("[A140-INITIAL-STANDBY-INCOMPLETE] both standby command paths are required before AUTO-X imaging")
                return False
            if not bool(arms_in_imaging_standby):
                print("[A140-INITIAL-STANDBY-INCOMPLETE] standby commands were accepted but T:105 camera-clear arrival was not confirmed")
                return False
            wait_s = max(0.0, float(getattr(args, "auto_wrinkle_standby_settle_s", 0.35)))
            if wait_s > 0.0:
                time.sleep(wait_s)
            return True
        except Exception as e:
            print(f"[AUTO-X-STANDBY-WARN] failed to move standby before next snapshot: {repr(e)}")
            return False

    def _auto_area_trend_status(area_history: List[Optional[float]],
                                stable_thr: float,
                                recent_stable_count: int,
                                min_total_gain_ratio: float,
                                trend_positive_ratio: float) -> Dict[str, Any]:
        """Judge the Step_a50 strict mask-area trend.

        Desired behavior:
          - remember the mask area right after the first / correction;
          - after each X cycle, append the current mask area;
          - finish only when the area has generally increased from the baseline
            and the most recent N area changes are small.

        This is intentionally tolerant rather than strictly monotonic because
        segmentation noise and small clothing motion can cause tiny area drops.
        """
        clean = []
        for a in area_history:
            try:
                if a is not None and float(a) > 1.0:
                    clean.append(float(a))
            except Exception:
                pass
        out: Dict[str, Any] = {
            "ok": False,
            "enough_points": False,
            "recent_stable": False,
            "trend_ok": False,
            "total_gain_ratio": None,
            "positive_step_ratio": None,
            "recent_changes": [],
            "areas": clean,
            "reason": "not enough valid area samples",
        }
        n_recent = max(1, int(recent_stable_count))
        if len(clean) < n_recent + 1:
            return out

        rel_changes: List[float] = []
        signed_steps: List[float] = []
        for prev, cur in zip(clean[:-1], clean[1:]):
            if prev <= 1.0:
                continue
            signed = (cur - prev) / prev
            signed_steps.append(float(signed))
            rel_changes.append(float(abs(signed)))
        if len(rel_changes) < n_recent:
            return out

        recent = rel_changes[-n_recent:]
        recent_stable = bool(all(ch <= float(stable_thr) for ch in recent))
        total_gain = float((clean[-1] - clean[0]) / max(1.0, clean[0]))
        nondec = sum(1 for step in signed_steps if step >= -float(stable_thr))
        pos_ratio = float(nondec) / float(max(1, len(signed_steps)))
        min_gain = max(0.0, float(min_total_gain_ratio))
        trend_ratio_thr = float(np.clip(trend_positive_ratio, 0.0, 1.0))
        trend_ok = bool(total_gain >= min_gain and pos_ratio >= trend_ratio_thr)
        out.update({
            "enough_points": True,
            "recent_stable": bool(recent_stable),
            "trend_ok": bool(trend_ok),
            "total_gain_ratio": float(total_gain),
            "positive_step_ratio": float(pos_ratio),
            "recent_changes": recent,
            "ok": bool(recent_stable and trend_ok),
            "reason": (f"recent_stable={recent_stable}, trend_ok={trend_ok}, "
                       f"total_gain={total_gain:.3f}, positive_step_ratio={pos_ratio:.2f}"),
        })
        return out

    def _auto_force_fresh_coarse_rejudge(label: str, timeout: float) -> Optional[Dict[str, Any]]:
        nonlocal latest_coarse_plan
        latest_coarse_plan = None
        print(f"[AUTO-WRINKLE-REJUDGE] {label}: discard old coarse plan and request a fresh stable grasp target")
        return request_fresh_coarse_plan_and_wait(reason=label, timeout=timeout)

    def _auto_mask_center_error_status(plan: Optional[Dict[str, Any]], threshold_mm: float = 35.0) -> Dict[str, Any]:
        """Return garment-mask centroid error from the board center in board-mm.

        This is the X planner's explicit final-position metric requested by the user:
        distance(garment mask center, board center) <= threshold_mm.
        The normal '/' overflow metric is still checked separately as a safety/overflow gate.
        """
        out: Dict[str, Any] = {
            "ok": False,
            "error_mm": None,
            "threshold_mm": float(threshold_mm),
            "center_board_xy": None,
            "board_center_xy": None,
            "source": "unavailable",
        }
        try:
            min_bx, max_bx, min_by, max_by = board_bounds(cfg)
            board_center = np.array([(float(min_bx) + float(max_bx)) * 0.5,
                                     (float(min_by) + float(max_by)) * 0.5], dtype=np.float32)
            center = None
            src = "coarse_feature_center"
            metrics = _coarse_eval_metrics_from_plan(plan)
            if isinstance(metrics, dict) and metrics.get("center_board") is not None:
                center = np.asarray(metrics.get("center_board"), dtype=np.float32).reshape(2)
            if center is None:
                pts, _cand, src2 = _candidate_board_points_for_variable_overflow(plan, use_raw=False)
                src = "mask_centroid_samples:" + str(src2)
                if pts is not None and len(pts) >= 20:
                    center = np.asarray(pts, dtype=np.float32).reshape(-1, 2).mean(axis=0)
            if center is None:
                out["source"] = src
                return out
            err = float(np.linalg.norm(center - board_center))
            out.update({
                "ok": bool(err <= float(threshold_mm)),
                "error_mm": err,
                "center_board_xy": [float(center[0]), float(center[1])],
                "board_center_xy": [float(board_center[0]), float(board_center[1])],
                "source": src,
            })
            return out
        except Exception as e:
            out["source"] = f"center error failed: {repr(e)}"
            return out

    def auto_align_rotate_after_wrinkle_pipeline(trigger: str = "x_coarse_wrinkle_spread",
                                                  expected_cycle_epoch: Optional[int] = None) -> bool:
        nonlocal latest_pose_rotation_plan, latest_coarse_plan, coarse_action_stretch_distance_override
        nonlocal latest_auto_x_decision_text, latest_auto_x_decision_detail, latest_auto_x_decision_until, pending_auto_x_action, auto_x_manual_judge_active
        nonlocal latest_auto_x_post_action_title, latest_auto_x_post_action_detail_1, latest_auto_x_post_action_detail_2
        nonlocal last_auto_x_executed_action, last_auto_x_executed_at
        """Step_a58 user-defined X planner.

        User policy implemented here:
          - Every decision starts from imaging standby and exactly one fresh snapshot.
          - In VLA collection mode, action count is diagnostic only; there is no hard motion-count stop.
          - Priority actions are: CENTER_CIRCUMCENTER, SEGMENTATION_SPREAD, LOCAL_SPREAD.
          - Final gate means READY_FOR_ROTATION only; this planner still does not execute key-6.
        """
        if not bool(getattr(args, "auto_align_rotate_after_wrinkle", True)):
            return False
        if latest_H is None:
            print("[AUTO-X-PLANNER] skipped: Homography not locked")
            return False
        judge_epoch = int(auto_x_controller.current_epoch() if expected_cycle_epoch is None else expected_cycle_epoch)
        if not auto_x_controller.is_current(judge_epoch):
            print(f"[A140-JUDGE-CANCELLED] stale/disarmed judge before observation epoch={judge_epoch}")
            return False

        timeout = max(0.5, float(getattr(args, "auto_align_rotate_fresh_timeout", 15.0)))
        settle = max(0.0, float(getattr(args, "auto_align_rotate_after_press_wait", 0.55)))
        center_action_trigger_mm = max(0.0, float(getattr(args, "auto_wrinkle_center_done_mm", 50.0)))
        center_long_pull_compete_enable = bool(getattr(args, "auto_x_center_long_pull_compete_enable", True))
        center_long_pull_hard_priority_mm = max(
            center_action_trigger_mm,
            float(getattr(args, "auto_x_center_long_pull_hard_priority_mm", 90.0)),
        )
        center_finish_mm = max(0.0, float(getattr(args, "auto_wrinkle_finish_center_done_mm", 35.0)))
        max_actions = max(1, int(getattr(args, "auto_x_max_actions", getattr(args, "auto_wrinkle_planner_max_rounds", 10))))
        repeat_limit = max(1, int(getattr(args, "auto_wrinkle_action_repeat_limit", 2)))
        min_center_improve = max(0.0, float(getattr(args, "auto_wrinkle_min_center_improvement_mm", 8.0)))
        pose_area_ratio_min = float(np.clip(getattr(args, "auto_x_pose_area_ratio_min", 0.75), 0.0, 1.0))
        boundary_ignore_mm = max(0.0, float(getattr(args, "auto_x_wrinkle_boundary_ignore_mm", 15.0)))
        seg_pull_mm = max(0.0, float(getattr(args, "auto_x_segmentation_spread_pull_mm", 50.0)))
        local_pull_mm = max(0.0, float(getattr(args, "auto_x_local_spread_pull_mm", 15.0)))
        local_grip_offset_mm = max(5.0, float(getattr(args, "auto_x_local_spread_grip_offset_mm", 35.0)))
        local_snap_radius_mm = max(10.0, float(getattr(args, "auto_x_local_spread_snap_radius_mm", 80.0)))
        local_min_internal_px = max(0.0, float(getattr(args, "auto_x_local_spread_min_internal_px", 8.0)))
        local_after_seg_count = max(1, int(getattr(args, "auto_x_local_after_segmentation_count", 3)))
        local_continue_if_effective = bool(getattr(args, "auto_x_local_continue_if_effective", True))
        local_long_dominance_ratio = max(1.0, float(getattr(args, "auto_x_local_long_dominance_ratio", 1.35)))
